def _project_special_skill_upgrade_count(level: int) -> int:
    """Level one is the authored baseline; growth starts with level two."""
    return max(0, int(level) - 1)


def project_special_skill_cost_scale_bp(skill_id: int, level: int) -> int:
    """Return the remaining resource-cost ratio in basis points."""
    balance = PROJECT_SPECIAL_SKILL_BALANCE.get(skill_id)
    if balance is None:
        return 10_000
    reduction = balance.get("cost_reduction_bp_per_upgrade", 0)
    return max(
        0,
        10_000 - reduction * _project_special_skill_upgrade_count(level),
    )


def project_special_skill_mp_cost(skill_id: int, level: int, max_mp: int) -> int:
    balance = PROJECT_SPECIAL_SKILL_BALANCE[skill_id]
    base_cost = max(1, round(max(0, max_mp) * balance["max_mp_percent"] / 100.0))
    return max(1, base_cost * project_special_skill_cost_scale_bp(skill_id, level) // 10_000)


def project_special_skill_zq_cost(skill_id: int, level: int) -> int:
    balance = PROJECT_SPECIAL_SKILL_BALANCE[skill_id]
    base_cost = max(0, balance["zq_cost"])
    return max(0, base_cost * project_special_skill_cost_scale_bp(skill_id, level) // 10_000)


def project_special_skill_cooldown_ms(skill_id: int, level: int) -> int:
    balance = PROJECT_SPECIAL_SKILL_BALANCE[skill_id]
    reduction = balance.get("cooldown_reduction_ms_per_upgrade", 0)
    return max(
        1_000,
        balance["cooldown_ms"]
        - reduction * _project_special_skill_upgrade_count(level),
    )


def project_shadow_clone_attribute_ratio_bp(skill_id: int, level: int) -> int:
    balance = PROJECT_SPECIAL_SKILL_BALANCE[skill_id]
    return min(
        10_000,
        balance["attribute_ratio_bp"]
        + balance["attribute_ratio_bp_per_upgrade"]
        * _project_special_skill_upgrade_count(level),
    )
