def _save_path_lock(path: Path) -> threading.RLock:
    """Share one reentrant lock across every live store for the same save file."""
    key = os.path.normcase(str(path.resolve()))
    with _SAVE_PATH_LOCKS_GUARD:
        return _SAVE_PATH_LOCKS.setdefault(key, threading.RLock())


def _load_simplified_translation() -> dict[int, str]:
    """Load the same Traditional-to-Simplified map used by the editor."""
    try:
        lines = LOCALIZATION_MAP_PATH.read_text(encoding="utf-8").replace("\r", "").splitlines()
        if len(lines) >= 2 and len(lines[0]) == len(lines[1]):
            return str.maketrans(dict(zip(lines[0], lines[1])))
    except (OSError, UnicodeError):
        pass
    return {}


SIMPLIFIED_TRANSLATION = _load_simplified_translation()


def _load_nya208_runtime_catalogs() -> dict[str, Any]:
    """Load immutable plaintext catalogs generated from the archived Nya captures."""
    try:
        payload = json.loads(NYA208_RUNTIME_CATALOG_PATH.read_text(encoding="utf-8"))
    except (FileNotFoundError, OSError, json.JSONDecodeError):
        return {"exchange": [], "merchants": []}
    return payload if isinstance(payload, dict) else {"exchange": [], "merchants": []}


