def decode_original_client_payload(payload: bytes) -> bytes:
    """Undo CodecUtil.encodeBuffer for one original-client request body."""
    return bytes(ORIGINAL_CLIENT_DECODE_BOX[value] for value in payload)


def editor_shop_override(entity_type: str, entity_id: int | str) -> dict[str, Any]:
    """Read one atomically-written live override through the shared hot-reload cache."""
    runtime = (
        EDITOR_RUNTIME
        if EDITOR_RUNTIME.path == Path(EDITOR_PROJECT_PATH)
        else RuntimeConfig(Path(EDITOR_PROJECT_PATH))
    )
    return runtime.override(entity_type, entity_id)

