def _skill_requirement_rows(packed: str) -> tuple[tuple[int, int], ...]:
    """Decode compact copies of the original client's SkillReqTable rows."""
    return tuple(
        tuple(int(value) for value in row.split(","))
        for row in packed.split(";")
    )


