class PetSoulFusionSelection(IntEnum):
    """Button indexes sent by PetRongHunTab.requestRongHun."""

    THREE_TAILS = 2
    FOUR_TAILS = 3
    EIGHT_TAILS = 7
    NINE_TAILS = 8

    def target_pet_id(self) -> PetTemplateId:
        """Resolve the Flash tab button index to its original tail-beast template."""
        return {
            PetSoulFusionSelection.THREE_TAILS: PetTemplateId.THREE_TAILS,
            PetSoulFusionSelection.FOUR_TAILS: PetTemplateId.FOUR_TAILS,
            PetSoulFusionSelection.EIGHT_TAILS: PetTemplateId.EIGHT_TAILS,
            PetSoulFusionSelection.NINE_TAILS: PetTemplateId.NINE_TAILS,
        }[self]


