def apply_nya208_transform_card_profile(item: InventoryItem) -> bool:
    """Apply factory traits without erasing player reforges or special washes."""
    before = (
        item.aptitude,
        item.max_endure,
        item.endure,
        item.base_attr_type,
        item.base_attr_value,
        item.born_attr_value,
        item.strength_value,
        tuple(tuple(values) for values in item.plus_attributes),
        tuple(tuple(values) for values in item.special_attributes),
        item.special_level,
        item.special_effect_type,
        item.afterimage_flag,
    )
    captured = NYA208_CAPTURED_TRANSFORM_CARD_ATTRIBUTES.get(item.item_id)
    captured_attributes, special_attributes_default = captured or ((), ())
    plus_attributes = TRANSFORM_CARD_GAME_DATA_CATALOG.get_equipment_template_attributes(
        item.item_id
    )
    if not plus_attributes:
        plus_attributes = [list(values) for values in captured_attributes]
    item.aptitude = 1
    item.max_endure = 100
    item.endure = 100
    item.base_attr_type = int(EquipmentAttribute.ATTACK_SPEED)
    item.base_attr_value = 10
    item.strength_value = 0
    if item.reforge_time <= 0:
        item.plus_attributes = [list(values) for values in plus_attributes]
        item.born_attr_value = 0
    if (
        not item.special_attributes
        and item.special_level == 0
        and item.special_effect_type == 0
        and item.afterimage_flag == 0
    ):
        item.special_attributes = [
            list(values) for values in special_attributes_default
        ]
        item.special_level = len(item.special_attributes)
    after = (
        item.aptitude,
        item.max_endure,
        item.endure,
        item.base_attr_type,
        item.base_attr_value,
        item.born_attr_value,
        item.strength_value,
        tuple(tuple(values) for values in item.plus_attributes),
        tuple(tuple(values) for values in item.special_attributes),
        item.special_level,
        item.special_effect_type,
        item.afterimage_flag,
    )
    return before != after


