SECOND_LEVEL_PASSWORD_ATTEMPTS = 5
SECOND_LEVEL_PASSWORD_ITERATIONS = 310_000


def _hash_second_level_secret(secret: str) -> str:
    """Return a self-contained PBKDF2 credential for a local security secret."""
    salt = secrets.token_bytes(16)
    digest = hashlib.pbkdf2_hmac(
        "sha256",
        secret.encode("utf-8"),
        salt,
        SECOND_LEVEL_PASSWORD_ITERATIONS,
    )
    return "$".join(
        (
            "pbkdf2_sha256",
            str(SECOND_LEVEL_PASSWORD_ITERATIONS),
            base64.urlsafe_b64encode(salt).decode("ascii"),
            base64.urlsafe_b64encode(digest).decode("ascii"),
        )
    )


def _verify_second_level_secret(secret: str, encoded: str) -> bool:
    """Verify one second-level password or security answer in constant time."""
    try:
        algorithm, raw_iterations, raw_salt, raw_digest = encoded.split("$", 3)
        if algorithm != "pbkdf2_sha256":
            return False
        iterations = int(raw_iterations)
        if iterations < 100_000 or iterations > 1_000_000:
            return False
        salt = base64.urlsafe_b64decode(raw_salt.encode("ascii"))
        expected = base64.urlsafe_b64decode(raw_digest.encode("ascii"))
    except (TypeError, ValueError, binascii.Error):
        return False
    actual = hashlib.pbkdf2_hmac(
        "sha256",
        secret.encode("utf-8"),
        salt,
        iterations,
    )
    return hmac.compare_digest(actual, expected)


@dataclass
class SecondLevelPasswordState:
    """Persistent second-level password state without plaintext secrets."""

    password_hash: str = ""
    contact_configured: bool = False
    question1: str = ""
    answer1_hash: str = ""
    question2: str = ""
    answer2_hash: str = ""
    questions_confirmed: bool = False
    update_attempts_remaining: int = SECOND_LEVEL_PASSWORD_ATTEMPTS
    delete_attempts_remaining: int = SECOND_LEVEL_PASSWORD_ATTEMPTS

    @property
    def configured(self) -> bool:
        return bool(
            self.password_hash
            and self.question1
            and self.answer1_hash
            and self.question2
            and self.answer2_hash
            and self.questions_confirmed
        )


@dataclass
class SinglePlayerState:
    """All state that survives closing and reopening the Flash client."""

    version: int = SAVE_VERSION
    character: CharacterState = field(default_factory=CharacterState)
    inventory: dict[int, InventoryItem] = field(default_factory=dict)
    storage: dict[int, InventoryItem] = field(default_factory=dict)
    bag_capacity: int = DEFAULT_BAG_CAPACITY
    storage_capacity: int = DEFAULT_STORAGE_CAPACITY
    pet_capacity: int = DEFAULT_PET_CAPACITY
    skills: dict[int, SkillState] = field(default_factory=dict)
    pets: dict[int, PetState] = field(default_factory=dict)
    progression: OfflineProgressionState = field(default_factory=OfflineProgressionState)
    quest: QuestProgress = field(default_factory=QuestProgress)
    original_quests: dict[int, OriginalQuestProgress] = field(default_factory=dict)
    keymap: dict[int, KeyBindingState] = field(default_factory=default_keymap)
    character_config: dict[str, Any] = field(default_factory=default_character_config)
    second_level_password: SecondLevelPasswordState = field(
        default_factory=SecondLevelPasswordState
    )
    money: int = 0
    bound_money: int = 0
    cash_money: int = 0
    coupon_money: int = 0
    pending_money_sell_reports: list[dict[str, int | bool]] = field(
        default_factory=list
    )
    recharge_total: int = 0
    first_charge_claimed: bool = False
    limited_recharge_total_claims: list[int] = field(default_factory=list)
    limited_recharge_each_claims: list[int] = field(default_factory=list)
    new_server_claimed_ids: list[int] = field(default_factory=list)
    new_server_cashbind_remaining: int = 579
    storage_money: int = 0
    vip_item_id: int = 0
    vip_expires_at: int = 0
    vip_sweep_pending: list[dict[str, Any]] = field(default_factory=list)
    vip_pve_sweep_week_key: str = ""
    active_item_effects: dict[int, int] = field(default_factory=dict)
    auto_consume_effects: dict[int, dict[str, int]] = field(default_factory=dict)
    item_cooldowns: dict[int, int] = field(default_factory=dict)
    skill_cooldowns: dict[int, int] = field(default_factory=dict)
    pvp_mode: int = 1
    yata_resistance_element: int = 2
    active_skill_buffs: dict[int, dict[str, int | float]] = field(default_factory=dict)
    fudai_transaction: FudaiTransaction | None = None
    pending_mai_explosion: PersistedMaiExplosion | None = None
    card_submissions: dict[str, dict[int, int]] = field(default_factory=dict)
    card_claimed_nodes: list[str] = field(default_factory=list)
    transform_card_collection: list[int] = field(default_factory=list)
    transform_card_storage: dict[int, InventoryItem] = field(default_factory=dict)
    charm_claimed_reward_ids: list[int] = field(default_factory=list)
    charm_name_color_reward_id: int = 0
    charm_text_color_reward_id: int = 0
    shown_tutorials: list[str] = field(default_factory=list)
    gm_notifications: list[dict[str, Any]] = field(default_factory=list)
    ring_daily_day_key: str = ""
    ring_daily_count: int = 0
    ring_week_key: str = ""
    ring_weekly_count: int = 0
    ring_active_mode: str = ""
    ring_quest_modes: dict[int, str] = field(default_factory=dict)

    @classmethod
    def default(cls) -> "SinglePlayerState":
        """Create an untouched level-one character at GameData's original start map."""
        return cls()

    @classmethod
    def from_dict(cls, payload: dict[str, Any]) -> "SinglePlayerState":
        """Load a save payload while filling fields added by later versions."""
        save_version = int(payload.get("version") or 1)
        defaults = asdict(CharacterState())
        defaults.update(payload.get("character") or {})
        character = CharacterState(**{key: defaults[key] for key in CharacterState.__dataclass_fields__})
        # Older GM builds allowed values that exceeded native protocol fields.
        # Normalize them during every load so an already affected character can
        # log in again without needing a separate repair utility first.
        character.level = max(1, min(len(EXP_BY_LEVEL) - 1, int(character.level)))
        character.zq = max(0, min(MAX_ZQ, int(character.zq)))
        for field_name in ("ap_atk", "ap_def", "ap_dex", "ap_phy", "remaining_ap"):
            setattr(
                character,
                field_name,
                max(0, min(0xFFFF, int(getattr(character, field_name, 0)))),
            )
        if save_version < op(SaveVersion.PLAYABLE_STARTER):
            # ponytail: version 1 was a fixed level-80 mock; reset it once so leveling is playable.
            character.level = 1
            character.exp = 0
            character.zq = 10_000
        if save_version < op(SaveVersion.CULTIVATION_TABS):
            # The original client hides several cultivation tabs below level 70.
            character.level = max(character.level, MIN_CULTIVATION_LEVEL)
        inventory: dict[int, InventoryItem] = {}
        for raw_slot, raw_item in (payload.get("inventory") or {}).items():
            if not isinstance(raw_item, dict):
                continue
            try:
                slot = int(raw_slot)
                item_data = dict(raw_item)
                item_data["slot"] = slot
                # Older GM grants could persist a larger value and make the
                # next login fail while rebuilding the native inventory packet.
                item_id = max(0, int(item_data.get("item_id", 0)))
                item_data["quantity"] = _safe_item_quantity(
                    item_id, item_data.get("quantity", 1) or 0, default=1
                )
                inventory[slot] = InventoryItem(**item_data)
            except (TypeError, ValueError, OverflowError):
                # One malformed slot must not discard an otherwise recoverable
                # character save or leave the login socket half-initialized.
                continue
        storage: dict[int, InventoryItem] = {}
        for raw_slot, raw_item in (payload.get("storage") or {}).items():
            if not isinstance(raw_item, dict):
                continue
            try:
                slot = int(raw_slot)
                item_data = dict(raw_item)
                item_data["slot"] = slot
                item_id = max(0, int(item_data.get("item_id", 0)))
                item_data["quantity"] = _safe_item_quantity(
                    item_id, item_data.get("quantity", 1) or 0, default=1
                )
                storage[slot] = InventoryItem(**item_data)
            except (TypeError, ValueError, OverflowError):
                continue
        if save_version < op(SaveVersion.PLAYABLE_STARTER):
            cls._migrate_starter_items(inventory)
        skills: dict[int, SkillState] = {}
        for raw_skill_id, raw_skill in (payload.get("skills") or {}).items():
            try:
                skill_id = int(raw_skill_id)
                skill_data = dict(raw_skill) if isinstance(raw_skill, dict) else {}
                definition = GAME_DATA_CATALOG.get_skill_definition(skill_id)
                if definition is None or not (
                    skill_id < 10_000
                    or skill_id in COMMON_PROBABILITY_SKILL_IDS
                    or skill_id // 10_000 == int(character.job)
                ):
                    continue
                skill_data["skill_id"] = skill_id
                skill_data["level"] = max(
                    1,
                    min(
                        len(EXP_BY_LEVEL) - 1,
                        int(skill_data.get("level", 1) or 1),
                    ),
                )
                skill_data["master_level"] = max(
                    0,
                    min(2_147_483_647, int(skill_data.get("master_level", 0) or 0)),
                )
                skills[skill_id] = SkillState(**skill_data)
            except (TypeError, ValueError, OverflowError):
                continue
        if save_version < op(SaveVersion.ORIGINAL_SKILL_MASTERY):
            for skill in skills.values():
                row_index = skill.level - 2
                if not 0 <= row_index < len(NORMAL_SKILL_REQUIREMENTS):
                    continue
                if skill.skill_id // 100 in {31, 32}:
                    required_mastery = FAMILY_SKILL_REQUIREMENTS[row_index][0]
                else:
                    required_mastery = NORMAL_SKILL_REQUIREMENTS[row_index][1]
                skill.master_level = max(skill.master_level, required_mastery)
        if save_version < op(SaveVersion.ORIGINAL_SKILL_MASTERY_CAP):
            for skill in skills.values():
                row_index = skill.level - 1
                if not 0 <= row_index < len(NORMAL_SKILL_REQUIREMENTS):
                    skill.master_level = max(0, skill.master_level)
                    continue
                if skill.skill_id // 100 in {31, 32}:
                    mastery_cap = FAMILY_SKILL_REQUIREMENTS[row_index][0]
                else:
                    mastery_cap = NORMAL_SKILL_REQUIREMENTS[row_index][1]
                skill.master_level = max(0, min(skill.master_level, mastery_cap))
        pets: dict[int, PetState] = {}
        for raw_unique_id, raw_pet in (payload.get("pets") or {}).items():
            unique_id = int(raw_unique_id)
            pet_data = dict(raw_pet) if isinstance(raw_pet, dict) else {}
            pet_data["unique_id"] = unique_id
            legacy_active = bool(pet_data.pop("active", True))
            if "position" not in pet_data:
                pet_data["position"] = int(
                    PetPosition.ATTACHED if legacy_active else PetPosition.BAG
                )
            raw_pet_skills = pet_data.pop("skills", None)
            legacy_skill_id = int(pet_data.pop("skill_id", 0) or 0)
            legacy_skill_level = int(pet_data.pop("skill_level", 1) or 1)
            pet_skills: dict[int, SkillState] = {}
            if isinstance(raw_pet_skills, dict):
                for raw_skill_id, raw_skill in raw_pet_skills.items():
                    skill_id = int(raw_skill_id)
                    skill_data = dict(raw_skill) if isinstance(raw_skill, dict) else {}
                    skill_data["skill_id"] = skill_id
                    pet_skills[skill_id] = SkillState(**skill_data)
            if not pet_skills and legacy_skill_id > 0:
                pet_skills[legacy_skill_id] = SkillState(legacy_skill_id, legacy_skill_level)
            raw_pet_equipment = pet_data.pop("equipment", None)
            pet_equipment: dict[int, InventoryItem] = {}
            if isinstance(raw_pet_equipment, dict):
                for raw_position, raw_item in raw_pet_equipment.items():
                    position = int(raw_position)
                    item_data = dict(raw_item) if isinstance(raw_item, dict) else {}
                    item_data["slot"] = position
                    pet_equipment[position] = InventoryItem(**item_data)
            allowed_fields = PetState.__dataclass_fields__
            pet = PetState(**{key: value for key, value in pet_data.items() if key in allowed_fields})
            pet.skills = pet_skills or {
                GAME_DATA_CATALOG.get_pet_default_skill(pet.item_id): SkillState(
                    GAME_DATA_CATALOG.get_pet_default_skill(pet.item_id)
                )
            }
            pet.skills.pop(0, None)
            pet.equipment = pet_equipment
            # The original PetAptitude enum only accepts 1..4; repair early mock values.
            pet.aptitude = min(4, max(1, pet.aptitude))
            if save_version < op(SaveVersion.PET_TRADE_PROVENANCE):
                # Older saves inherited can_trade=False for every source. Only
                # the fixed starter companion is inherently account-bound.
                pet.can_trade = not (
                    pet.unique_id == 90_001
                    and pet.item_id == int(PetTemplateId.STARTER_DOG)
                )
            if save_version < op(SaveVersion.GEM_AND_COMPLETE_PET_GROWTH):
                # Older saves did not persist caps; seed them from the original aptitude table.
                minimum, _ = GAME_DATA_CATALOG.get_pet_potential_bounds(
                    pet.item_id, pet.aptitude
                )
                pet.potential_total_atk = minimum
                pet.potential_total_def = minimum
                pet.potential_total_dex = minimum
                pet.potential_total_str = minimum
            pets[unique_id] = pet
        if not pets and save_version < op(SaveVersion.PLAYABLE_STARTER):
            starter_pet = PetState()
            pets[starter_pet.unique_id] = starter_pet
        if save_version < op(SaveVersion.PET_SOUL_FUSION):
            # PetRongHunTab blocks the request client-side unless the selected pet is outstanding.
            fusion_pet_ids = {int(value.target_pet_id()) for value in PetSoulFusionSelection}
            for pet in pets.values():
                if pet.item_id not in fusion_pet_ids:
                    pet.aptitude = 4
        raw_progression = payload.get("progression") or {}
        stages = {
            str(key): int(value)
            for key, value in (raw_progression.get("stages") or {}).items()
        }
        stage_progress = {
            str(key): int(value)
            for key, value in (raw_progression.get("stage_progress") or {}).items()
        }
        # A previous runtime wrote reincarnation-eye items to an internal
        # "轮回眼" key while every native panel and combat calculation reads
        # "轮眼". Merge that split state without discarding either side.
        for suffix in ("", ":祝福"):
            legacy_key = f"轮回眼{suffix}"
            canonical_key = f"轮眼{suffix}"
            if legacy_key in stages:
                stages[canonical_key] = max(
                    stages.get(canonical_key, 0), stages.pop(legacy_key)
                )
            if legacy_key in stage_progress:
                stage_progress[canonical_key] = max(
                    stage_progress.get(canonical_key, 0),
                    stage_progress.pop(legacy_key),
                )
        progression = OfflineProgressionState(
            stages=stages,
            stage_progress=stage_progress,
            visited_maps=[int(value) for value in (raw_progression.get("visited_maps") or [])],
            total_monster_kills=max(0, int(raw_progression.get("total_monster_kills") or 0)),
            boss_weekly_kills=max(0, int(raw_progression.get("boss_weekly_kills") or 0)),
            lianzhan_best=max(0, int(raw_progression.get("lianzhan_best") or 0)),
            lianzhan_count=max(0, min(899, int(raw_progression.get("lianzhan_count") or 0))),
            lianzhan_stage=max(0, min(8, int(raw_progression.get("lianzhan_stage") or 0))),
            lianzhan_buff_expires_at=max(0, int(raw_progression.get("lianzhan_buff_expires_at") or 0)),
            pve_progress=max(0, int(raw_progression.get("pve_progress") or 0)),
            pve_points=max(
                0,
                int(
                    raw_progression.get("pve_points")
                    or raw_progression.get("pve_progress")
                    or 0
                ),
            ),
            wu_gong_progress=max(0, int(raw_progression.get("wu_gong_progress") or 0)),
            flower_sent=max(0, int(raw_progression.get("flower_sent") or 0)),
            local_pk_points=max(0, int(raw_progression.get("local_pk_points") or 0)),
            local_pk_day_key=str(raw_progression.get("local_pk_day_key") or ""),
            local_pk_battles=max(
                0, int(raw_progression.get("local_pk_battles") or 0)
            ),
            local_pk_wins=max(
                0, int(raw_progression.get("local_pk_wins") or 0)
            ),
            local_pk_win_streak=max(
                0, int(raw_progression.get("local_pk_win_streak") or 0)
            ),
            local_pk_lose_streak=max(
                0, int(raw_progression.get("local_pk_lose_streak") or 0)
            ),
            local_pk_best_win_streak=max(
                0, int(raw_progression.get("local_pk_best_win_streak") or 0)
            ),
            local_pk_best_win_streak_today=max(
                0,
                int(
                    raw_progression.get("local_pk_best_win_streak_today")
                    or raw_progression.get("local_pk_best_win_streak")
                    or 0
                ),
            ),
            local_pk_claimed_prizes=sorted(
                {
                    int(value)
                    for value in (
                        raw_progression.get("local_pk_claimed_prizes") or []
                    )
                    if 0 <= int(value) <= 9
                }
            ),
            lunhui_pvp_soul_claimed=bool(
                raw_progression.get("lunhui_pvp_soul_claimed")
            ),
            arena_day_key=str(raw_progression.get("arena_day_key") or ""),
            arena_used_count=max(
                0, int(raw_progression.get("arena_used_count") or 0)
            ),
            arena_max_count=max(
                15, int(raw_progression.get("arena_max_count") or 15)
            ),
            arena_cooldown_until=max(
                0, int(raw_progression.get("arena_cooldown_until") or 0)
            ),
            arena_win_streak=max(
                0, int(raw_progression.get("arena_win_streak") or 0)
            ),
            arena_rank=max(
                1, min(1000, int(raw_progression.get("arena_rank") or 1000))
            ),
            arena_rank_reward_day_key=str(
                raw_progression.get("arena_rank_reward_day_key") or ""
            ),
            effect_xielunyan_stage=max(
                0, int(raw_progression.get("effect_xielunyan_stage") or 0)
            ),
            effect_skill_jingjie=int(
                raw_progression.get("effect_skill_jingjie")
                if raw_progression.get("effect_skill_jingjie") is not None
                else -1
            ),
            arena_return_map_id=max(
                0, int(raw_progression.get("arena_return_map_id") or 0)
            ),
            arena_return_x=int(raw_progression.get("arena_return_x") or 0),
            arena_return_y=int(raw_progression.get("arena_return_y") or 0),
            arena_reports=[
                {
                    "challenger": int(value.get("challenger") or 0),
                    "winnerId": int(value.get("winnerId") or 0),
                    "winnerName": str(value.get("winnerName") or "")[:12],
                    "loserId": int(value.get("loserId") or 0),
                    "loserName": str(value.get("loserName") or "")[:12],
                    "timeStamp": max(0, int(value.get("timeStamp") or 0)),
                    "timeIntv": max(0, int(value.get("timeIntv") or 0)),
                    "resultPkLevel": max(
                        1, min(1000, int(value.get("resultPkLevel") or 1000))
                    ),
                }
                for value in (raw_progression.get("arena_reports") or [])
                if isinstance(value, dict)
            ][-5:],
            tower_season_key=str(raw_progression.get("tower_season_key") or ""),
            tower_day_key=str(raw_progression.get("tower_day_key") or ""),
            tower_max_level=max(
                0, min(60, int(raw_progression.get("tower_max_level") or 0))
            ),
            tower_attempts_used=max(
                0, int(raw_progression.get("tower_attempts_used") or 0)
            ),
            tower_purchased_attempts=max(
                0, int(raw_progression.get("tower_purchased_attempts") or 0)
            ),
            tower_records={
                str(max(1, min(60, int(level)))): max(1, int(milliseconds))
                for level, milliseconds in (
                    raw_progression.get("tower_records") or {}
                ).items()
                if str(level).lstrip("-").isdigit()
                and str(milliseconds).lstrip("-").isdigit()
            },
            tower_claimed_milestones=sorted(
                {
                    int(value)
                    for value in (
                        raw_progression.get("tower_claimed_milestones") or []
                    )
                    if int(value) in {5, 10, 20, 30, 40, 50, 60}
                }
            ),
            tower_active_level=max(
                0, min(60, int(raw_progression.get("tower_active_level") or 0))
            ),
            tower_active_started_at=max(
                0, int(raw_progression.get("tower_active_started_at") or 0)
            ),
            tower_active_spawn_at=max(
                0, int(raw_progression.get("tower_active_spawn_at") or 0)
            ),
            tower_return_map_id=max(
                0, int(raw_progression.get("tower_return_map_id") or 0)
            ),
            tower_return_x=int(raw_progression.get("tower_return_x") or 0),
            tower_return_y=int(raw_progression.get("tower_return_y") or 0),
            fb_use_time_short=max(0, int(raw_progression.get("fb_use_time_short") or 0)),
            claimed_achievements=[str(value) for value in (raw_progression.get("claimed_achievements") or [])],
            notified_achievements=[
                str(value)
                for value in (raw_progression.get("notified_achievements") or [])
            ],
            online_week_key=str(raw_progression.get("online_week_key") or ""),
            online_week_seconds=max(
                0, int(raw_progression.get("online_week_seconds") or 0)
            ),
            online_last_week_minutes=max(
                0, int(raw_progression.get("online_last_week_minutes") or 0)
            ),
            online_last_week_reward=max(
                0, int(raw_progression.get("online_last_week_reward") or 0)
            ),
            online_last_week_claimed=bool(
                raw_progression.get("online_last_week_claimed", True)
            ),
            first_login_online_seconds=max(
                0, int(raw_progression.get("first_login_online_seconds") or 0)
            ),
            first_login_claimed_gifts=sorted(
                {
                    int(value)
                    for value in (
                        raw_progression.get("first_login_claimed_gifts") or []
                    )
                    if 0 <= int(value) < 7
                }
            ),
            weekly_login_week_key=str(
                raw_progression.get("weekly_login_week_key") or ""
            ),
            weekly_login_dates=sorted(
                {
                    str(value)
                    for value in (raw_progression.get("weekly_login_dates") or [])
                    if str(value)
                }
            )[-7:],
            weekly_login_claimed_days=sorted(
                {
                    int(value)
                    for value in (
                        raw_progression.get("weekly_login_claimed_days") or []
                    )
                    if int(value) in {2, 4, 7}
                }
            ),
            level_gift_claimed_levels=sorted(
                {
                    int(value)
                    for value in (
                        raw_progression.get("level_gift_claimed_levels") or []
                    )
                    if 5 <= int(value) <= 100 and int(value) % 5 == 0
                }
            ),
            claimed_activation_gift_codes=sorted(
                {
                    str(value)
                    for value in (
                        raw_progression.get("claimed_activation_gift_codes") or []
                    )
                    if str(value) in {"01001", "01002"}
                }
            ),
            may7_gift_claimed=bool(raw_progression.get("may7_gift_claimed")),
            hero_day_key=str(raw_progression.get("hero_day_key") or ""),
            hero_enter_counts={
                int(key): max(0, int(value))
                for key, value in (raw_progression.get("hero_enter_counts") or {}).items()
            },
            everyday_gift_last_claim_date=str(
                raw_progression.get("everyday_gift_last_claim_date") or ""
            ),
            everyday_gift_accumulate_days=max(
                0,
                min(7, int(raw_progression.get("everyday_gift_accumulate_days") or 0)),
            ),
            meditation_experience_remainder=max(
                0,
                min(59, int(raw_progression.get("meditation_experience_remainder") or 0)),
            ),
            meditation_chakra_remainder=max(
                0,
                min(59, int(raw_progression.get("meditation_chakra_remainder") or 0)),
            ),
            exchange_counts={
                str(key): max(0, int(value or 0))
                for key, value in (raw_progression.get("exchange_counts") or {}).items()
            },
            mystery_shop_refresh_at=max(
                0, int(raw_progression.get("mystery_shop_refresh_at") or 0)
            ),
            mystery_shop_item_ids=[
                int(value)
                for value in (raw_progression.get("mystery_shop_item_ids") or [])
                if int(value or 0) > 0
            ][:5],
            mystery_shop_bought_ids=[
                int(value)
                for value in (raw_progression.get("mystery_shop_bought_ids") or [])
                if int(value or 0) > 0
            ][:5],
            trial_active=bool(raw_progression.get("trial_active")),
            trial_kills=max(0, int(raw_progression.get("trial_kills") or 0)),
            trial_best=max(0, int(raw_progression.get("trial_best") or 0)),
            trial_return_map=int(raw_progression.get("trial_return_map") or DEFAULT_MAP_ID),
            biguan_seconds=max(0, int(raw_progression.get("biguan_seconds") or 0)),
            biguan_updated_at=max(
                0,
                int(
                    raw_progression["biguan_updated_at"]
                    if "biguan_updated_at" in raw_progression
                    else time.time()
                ),
            ),
            xiuxing_day_key=str(raw_progression.get("xiuxing_day_key") or ""),
            xiuxing_index=max(
                0, min(10, int(raw_progression.get("xiuxing_index") or 0))
            ),
            xiuxing_cooldown_until=max(
                0, int(raw_progression.get("xiuxing_cooldown_until") or 0)
            ),
            xiuxing_problem_id=max(
                0, int(raw_progression.get("xiuxing_problem_id") or 0)
            ),
            xiuxing_xianfa_index=max(
                0,
                min(10, int(raw_progression.get("xiuxing_xianfa_index") or 0)),
            ),
            xiuxing_yueli_index=max(
                0,
                min(3, int(raw_progression.get("xiuxing_yueli_index") or 0)),
            ),
            active_achievement_title=str(
                raw_progression.get("active_achievement_title") or ""
            ),
            family_joined=bool(raw_progression.get("family_joined")),
            family_contribution=max(
                0, int(raw_progression.get("family_contribution") or 0)
            ),
            family_weekly_contribution=max(
                0, int(raw_progression.get("family_weekly_contribution") or 0)
            ),
            family_fund=max(0, int(raw_progression.get("family_fund") or 0)),
            family_flag_level=max(
                1, int(raw_progression.get("family_flag_level") or 1)
            ),
            family_flag_name=str(
                raw_progression.get("family_flag_name") or "木叶旗帜"
            )[:12],
            family_flag_style=max(
                1000, int(raw_progression.get("family_flag_style") or 1000)
            ),
            family_boss_time_indices=sorted(
                {
                    int(value)
                    for value in (raw_progression.get("family_boss_time_indices") or [])
                    if 0 <= int(value) <= 6
                }
            )[:2],
            family_boss_set_count=max(
                0, int(raw_progression.get("family_boss_set_count") or 0)
            ),
            family_boss_week_key=str(
                raw_progression.get("family_boss_week_key") or ""
            ),
            family_quest_day_key=str(
                raw_progression.get("family_quest_day_key") or ""
            ),
            family_quest_count=max(
                0, min(5, int(raw_progression.get("family_quest_count") or 0))
            ),
            mai_shared_exp=max(0, int(raw_progression.get("mai_shared_exp") or 0)),
            mai_shared_exp_count=max(
                0,
                int(raw_progression.get("mai_shared_exp_count") or 0),
            ),
            activity_day_key=str(
                raw_progression.get("activity_day_key") or ""
            ),
            activity_counts=(
                [
                    max(0, int(value or 0))
                    for value in (raw_progression.get("activity_counts") or [])
                ][:15]
                + [0] * 15
            )[:15],
            activity_score=max(
                0, min(150, int(raw_progression.get("activity_score") or 0))
            ),
            activity_claimed_level=max(
                -1,
                min(7, int(raw_progression.get("activity_claimed_level", -1))),
            ),
            activity_online_seconds=max(
                0, int(raw_progression.get("activity_online_seconds") or 0)
            ),
            activity_online_updated_at=max(
                1,
                int(raw_progression.get("activity_online_updated_at") or time.time()),
            ),
            world_boss_damage=max(
                0, int(raw_progression.get("world_boss_damage") or 0)
            ),
            world_boss_claimed_levels=sorted(
                {
                    int(value)
                    for value in (
                        raw_progression.get("world_boss_claimed_levels") or []
                    )
                    if 0 <= int(value) < len(CAPTURED_WORLD_BOSS_DAMAGE_REWARDS)
                }
            ),
            world_boss_kills=max(
                0, int(raw_progression.get("world_boss_kills") or 0)
            ),
            world_boss_kill_reward_claimed=bool(
                raw_progression.get("world_boss_kill_reward_claimed")
            ),
            world_boss_round_key=str(
                raw_progression.get("world_boss_round_key") or ""
            ),
            artifact_war_wins=max(
                0, int(raw_progression.get("artifact_war_wins") or 0)
            ),
            war_battle_kills_total=max(
                0, int(raw_progression.get("war_battle_kills_total") or 0)
            ),
            war_battle_wins=max(
                0, int(raw_progression.get("war_battle_wins") or 0)
            ),
            war_3v3_week_key=str(raw_progression.get("war_3v3_week_key") or ""),
            war_3v3_points_weekly=max(
                0, int(raw_progression.get("war_3v3_points_weekly") or 0)
            ),
            war_3v3_wins=max(
                0, int(raw_progression.get("war_3v3_wins") or 0)
            ),
            chunin_wins=max(0, int(raw_progression.get("chunin_wins") or 0)),
            chunin_losses=max(0, int(raw_progression.get("chunin_losses") or 0)),
            spirit_items=[
                SpiritState(
                    item_id=max(1, int(value.get("item_id") or 1)),
                    color=max(1, min(8, int(value.get("color") or 1))),
                    slot=int(value.get("slot") or 0),
                    experience=max(0, int(value.get("experience") or 0)),
                    level=max(1, min(20, int(value.get("level") or 1))),
                )
                for value in (raw_progression.get("spirit_items") or [])
                if isinstance(value, dict) and int(value.get("slot") or 0) != 0
            ],
            spirit_panel_items=[
                int(value)
                for value in (raw_progression.get("spirit_panel_items") or [])
                if int(value or 0) > 0
            ][:20],
            spirit_panel_obtained_at=[
                max(0, int(value or 0))
                for value in (
                    raw_progression.get("spirit_panel_obtained_at") or []
                )
            ][:20],
            spirit_pack_limit=max(
                5, min(30, int(raw_progression.get("spirit_pack_limit") or 5))
            ),
            spirit_npc_status=(
                [
                    max(0, min(2, int(value or 0)))
                    for value in (
                        raw_progression.get("spirit_npc_status")
                        or [1, 0, 0, 0, 0]
                    )
                ][:5]
                + [0] * 5
            )[:5],
            spirit_special_count=max(
                0, min(20, int(raw_progression.get("spirit_special_count") or 0))
            ),
        )
        if len(progression.spirit_panel_obtained_at) > len(
            progression.spirit_panel_items
        ):
            progression.spirit_panel_obtained_at = (
                progression.spirit_panel_obtained_at[
                    : len(progression.spirit_panel_items)
                ]
            )
        elif len(progression.spirit_panel_obtained_at) < len(
            progression.spirit_panel_items
        ):
            progression.spirit_panel_obtained_at.extend(
                [int(time.time())]
                * (
                    len(progression.spirit_panel_items)
                    - len(progression.spirit_panel_obtained_at)
                )
            )
        if not any(progression.spirit_npc_status):
            progression.spirit_npc_status[0] = 1
        if save_version < op(SaveVersion.SHARINGAN_AND_LINGQI):
            # Older builds exposed a full bar without ever consuming spirit items.
            # Start the current stage at zero now that progress is authoritative.
            progression.stage_progress["写轮眼"] = 0
            progression.stage_progress["写轮眼:祝福"] = 0
            for item in inventory.values():
                if item.item_id // 1_000_000 == 20 and item.plus_attributes == [
                    [op(EquipmentAttribute.ATTACK), 600]
                ]:
                    item.plus_attributes = []
        if save_version < op(SaveVersion.UNIFIED_GROWTH_ATTRIBUTES):
            cls._rollback_legacy_cultivation_deltas(character, progression)
        quest_data = {"state": int(QuestState.NOT_STARTED), "kills": 0}
        quest_data.update(payload.get("quest") or {})
        original_quests: dict[int, OriginalQuestProgress] = {}
        for raw_quest_id, raw_progress in (payload.get("original_quests") or {}).items():
            quest_id = int(raw_quest_id)
            progress_data = dict(raw_progress) if isinstance(raw_progress, dict) else {}
            progress_data["progress"] = {
                str(key): int(value)
                for key, value in (progress_data.get("progress") or {}).items()
            }
            progress_data["difficulty_level"] = max(
                1, min(5, int(progress_data.get("difficulty_level") or 5))
            )
            progress_data["rich_degree"] = max(
                1, min(5, int(progress_data.get("rich_degree") or 1))
            )
            progress_data["refresh_available_at"] = max(
                0, int(progress_data.get("refresh_available_at") or 0)
            )
            original_quests[quest_id] = OriginalQuestProgress(**progress_data)
        keymap = {
            int(raw_key): KeyBindingState(**raw_binding)
            for raw_key, raw_binding in (payload.get("keymap") or {}).items()
            if isinstance(raw_binding, dict)
        }
        if save_version < op(SaveVersion.DEFAULT_SHORTCUTS) and not keymap:
            keymap = default_keymap()
        character_config = default_character_config()
        raw_character_config = payload.get("character_config")
        if isinstance(raw_character_config, dict):
            character_config.update(
                {
                    str(key): value
                    for key, value in raw_character_config.items()
                    if isinstance(value, (bool, int, float, str))
                }
            )
        for threshold_name, default_value in (
            ("auotReplyHpValue", 70),
            ("auotReplyMpValue", 50),
        ):
            try:
                threshold_value = int(float(character_config.get(threshold_name, default_value)))
            except (TypeError, ValueError):
                threshold_value = default_value
            character_config[threshold_name] = max(1, min(99, threshold_value))
        loaded_money = (
            max(10_000_000, int(payload.get("money") or 0))
            if save_version < op(SaveVersion.EQUIPMENT_FORGE_AND_PET_ADVANCE)
            else int(payload.get("money") or 0)
        )
        if save_version < op(SaveVersion.PET_SOUL_FUSION):
            # Give old local saves enough gold for one original 30-million fusion attempt.
            loaded_money = max(SINGLE_PLAYER_STARTING_MONEY, loaded_money)
        # Older local saves exposed every balance through the copper field. Preserve copper
        # exactly, but seed separate offline-only balances so spending one currency cannot
        # silently change another.
        bound_money = max(0, int(payload.get("bound_money") or 0))
        cash_money = max(0, int(payload.get("cash_money") or 0))
        coupon_money = max(0, int(payload.get("coupon_money") or 0))
        if save_version < op(SaveVersion.MULTI_CURRENCY_AND_LOOT):
            cash_money = max(cash_money, 10_000)
            coupon_money = max(coupon_money, 10_000)
        fudai_transaction = None
        raw_fudai = payload.get("fudai_transaction")
        if isinstance(raw_fudai, dict):
            transaction_mode = str(raw_fudai.get("mode") or "fudai")
            transaction_type = int(raw_fudai.get("type_id") or 1)
            candidates = [
                int(item_id)
                for item_id in (raw_fudai.get("candidates") or [])
                if (
                    (
                        int(item_id) in KUN_CHONG_ITEM_IDS
                        if transaction_type == 6
                        else int(item_id) in CAPTURED_FUDAI_REWARD_POOL
                    )
                    if transaction_mode == "fudai"
                    else GAME_DATA_CATALOG.get_item_definition(int(item_id)) is not None
                )
            ]
            selected_index = int(raw_fudai.get("selected_index", -1))
            if len(candidates) == 16 and -1 <= selected_index < len(candidates):
                candidate_aptitudes = [
                    min(4, max(0, int(value)))
                    for value in (raw_fudai.get("candidate_aptitudes") or [])
                ]
                candidate_strengths = [
                    min(19, max(0, int(value)))
                    for value in (raw_fudai.get("candidate_strengths") or [])
                ]
                if len(candidate_aptitudes) != len(candidates):
                    candidate_aptitudes = [0] * len(candidates)
                if len(candidate_strengths) != len(candidates):
                    candidate_strengths = [0] * len(candidates)
                fudai_transaction = FudaiTransaction(
                    item_id=int(raw_fudai.get("item_id") or 0),
                    type_id=transaction_type,
                    candidates=candidates,
                    selected_index=selected_index,
                    mode=transaction_mode,
                    source_slot=max(0, int(raw_fudai.get("source_slot") or 0)),
                    candidate_aptitudes=candidate_aptitudes,
                    candidate_strengths=candidate_strengths,
                )
        pending_mai_explosion = None
        raw_mai_explosion = payload.get("pending_mai_explosion")
        if isinstance(raw_mai_explosion, dict):
            try:
                candidate = PersistedMaiExplosion(
                    due_at=float(raw_mai_explosion.get("due_at") or 0),
                    list_id=int(raw_mai_explosion.get("list_id") or 0),
                    mai_id=int(raw_mai_explosion.get("mai_id") or 0),
                    point_id=int(raw_mai_explosion.get("point_id") or 0),
                    point_count=max(0, int(raw_mai_explosion.get("point_count") or 0)),
                    succeeded=bool(raw_mai_explosion.get("succeeded")),
                    last_point=bool(raw_mai_explosion.get("last_point")),
                    map_id=int(raw_mai_explosion.get("map_id") or character.map_id),
                    x=int(raw_mai_explosion.get("x") or 0),
                    y=int(raw_mai_explosion.get("y") or 0),
                )
                if (
                    candidate.due_at > 0
                    and 0 <= candidate.list_id <= GAME_DATA_CATALOG.mai_max_list_id()
                ):
                    pending_mai_explosion = candidate
            except (TypeError, ValueError):
                pending_mai_explosion = None
        card_submissions: dict[str, dict[int, int]] = {}
        for raw_node_key, raw_counts in (payload.get("card_submissions") or {}).items():
            if not isinstance(raw_counts, dict):
                continue
            node_key = str(raw_node_key)
            card_submissions[node_key] = {
                int(item_id): max(0, int(count or 0))
                for item_id, count in raw_counts.items()
                if str(item_id).isdigit()
            }
        card_claimed_nodes = sorted(
            {
                str(node_key)
                for node_key in (payload.get("card_claimed_nodes") or [])
                if isinstance(node_key, (str, int))
            }
        )
        transform_card_collection = sorted(
            {
                int(item_id)
                for item_id in (payload.get("transform_card_collection") or [])
                if str(item_id).isdigit() and int(item_id) > 0
            }
        )
        transform_card_storage: dict[int, InventoryItem] = {}
        for raw_item_id, raw_item in (payload.get("transform_card_storage") or {}).items():
            if not isinstance(raw_item, dict):
                continue
            try:
                item_id = int(raw_item_id)
                item_data = dict(raw_item)
                item_data["item_id"] = item_id
                item_data["slot"] = 0
                item_data["quantity"] = _safe_item_quantity(
                    item_id, item_data.get("quantity", 1) or 0, default=1
                )
                transform_card_storage[item_id] = InventoryItem(**item_data)
            except (TypeError, ValueError):
                continue
        charm_claimed_reward_ids = sorted(
            {
                int(value)
                for value in (payload.get("charm_claimed_reward_ids") or [])
                if int(value) in {1, 2, 3}
            }
        )
        valid_charm_color_ids = set(range(101, 121))
        charm_name_color_reward_id = int(
            payload.get("charm_name_color_reward_id") or 0
        )
        charm_text_color_reward_id = int(
            payload.get("charm_text_color_reward_id") or 0
        )
        if charm_name_color_reward_id not in valid_charm_color_ids:
            charm_name_color_reward_id = 0
        if charm_text_color_reward_id not in valid_charm_color_ids:
            charm_text_color_reward_id = 0
        shown_tutorials = sorted(
            {
                str(tutorial)
                for tutorial in (payload.get("shown_tutorials") or [])
                if isinstance(tutorial, (str, int))
            }
        )
        raw_second_level = payload.get("second_level_password")
        second_level_password = SecondLevelPasswordState()
        if isinstance(raw_second_level, dict):
            second_level_password = SecondLevelPasswordState(
                password_hash=str(raw_second_level.get("password_hash") or ""),
                contact_configured=bool(
                    raw_second_level.get("contact_configured")
                ),
                question1=str(raw_second_level.get("question1") or "")[:80],
                answer1_hash=str(raw_second_level.get("answer1_hash") or ""),
                question2=str(raw_second_level.get("question2") or "")[:80],
                answer2_hash=str(raw_second_level.get("answer2_hash") or ""),
                questions_confirmed=bool(
                    raw_second_level.get("questions_confirmed")
                ),
                update_attempts_remaining=max(
                    0,
                    min(
                        SECOND_LEVEL_PASSWORD_ATTEMPTS,
                        int(
                            raw_second_level.get("update_attempts_remaining")
                            if raw_second_level.get("update_attempts_remaining")
                            is not None
                            else SECOND_LEVEL_PASSWORD_ATTEMPTS
                        ),
                    ),
                ),
                delete_attempts_remaining=max(
                    0,
                    min(
                        SECOND_LEVEL_PASSWORD_ATTEMPTS,
                        int(
                            raw_second_level.get("delete_attempts_remaining")
                            if raw_second_level.get("delete_attempts_remaining")
                            is not None
                            else SECOND_LEVEL_PASSWORD_ATTEMPTS
                        ),
                    ),
                ),
            )
        return cls(
            version=SAVE_VERSION,
            character=character,
            inventory=inventory,
            storage=storage,
            bag_capacity=max(
                DEFAULT_BAG_CAPACITY,
                min(MAX_BAG_CAPACITY, int(payload.get("bag_capacity") or DEFAULT_BAG_CAPACITY)),
                max((slot for slot in inventory if slot > 0), default=0),
            ),
            storage_capacity=max(
                DEFAULT_STORAGE_CAPACITY,
                min(
                    MAX_STORAGE_CAPACITY,
                    int(payload.get("storage_capacity") or DEFAULT_STORAGE_CAPACITY),
                ),
                max((slot for slot in storage if slot > 0), default=0),
            ),
            pet_capacity=max(
                DEFAULT_PET_CAPACITY,
                min(MAX_PET_CAPACITY, int(payload.get("pet_capacity") or DEFAULT_PET_CAPACITY)),
                min(MAX_PET_CAPACITY, len(pets)),
            ),
            skills=skills,
            pets=pets,
            progression=progression,
            quest=QuestProgress(**quest_data),
            original_quests=original_quests,
            keymap=keymap,
            character_config=character_config,
            second_level_password=second_level_password,
            money=loaded_money,
            bound_money=bound_money,
            cash_money=cash_money,
            coupon_money=coupon_money,
            pending_money_sell_reports=[
                {
                    "is_jingbi": bool(value.get("is_jingbi", False)),
                    "quantity": max(0, int(value.get("quantity", 0))),
                    "value": max(0, int(value.get("value", 0))),
                    "succ": bool(value.get("succ", True)),
                }
                for value in (payload.get("pending_money_sell_reports") or [])
                if isinstance(value, dict)
            ][-20:],
            # Premium-currency balance is not a recharge record. Older saves
            # without this field therefore start at zero instead of inheriting
            # whatever balance happened to be in the account.
            recharge_total=max(0, int(payload.get("recharge_total") or 0)),
            first_charge_claimed=bool(payload.get("first_charge_claimed")),
            limited_recharge_total_claims=sorted(
                {
                    int(value)
                    for value in (payload.get("limited_recharge_total_claims") or [])
                    if 0 <= int(value) < 9
                }
            ),
            limited_recharge_each_claims=sorted(
                {
                    int(value)
                    for value in (payload.get("limited_recharge_each_claims") or [])
                    if 0 <= int(value) < 4
                }
            ),
            new_server_claimed_ids=sorted(
                {
                    int(value)
                    for value in (payload.get("new_server_claimed_ids") or [])
                    if int(value) in {6_000_057, 6_000_058}
                }
            ),
            new_server_cashbind_remaining=max(
                0, int(payload.get("new_server_cashbind_remaining") or 579)
            ),
            storage_money=max(0, int(payload.get("storage_money") or 0)),
            vip_item_id=max(0, int(payload.get("vip_item_id") or 0)),
            vip_expires_at=max(0, int(payload.get("vip_expires_at") or 0)),
            vip_sweep_pending=cls._sanitize_vip_sweep_pending(
                payload.get("vip_sweep_pending")
            ),
            vip_pve_sweep_week_key=str(
                payload.get("vip_pve_sweep_week_key") or ""
            )[:16],
            active_item_effects={
                int(item_id): max(0, int(expires_at or 0))
                for item_id, expires_at in (payload.get("active_item_effects") or {}).items()
                if str(item_id).isdigit()
            },
            auto_consume_effects={
                int(item_id): {
                    "remaining": max(0, int(effect.get("remaining") or 0)),
                    "total": max(
                        max(0, int(effect.get("remaining") or 0)),
                        int(effect.get("total") or 0),
                    ),
                }
                for item_id, effect in (payload.get("auto_consume_effects") or {}).items()
                if str(item_id).isdigit()
                and isinstance(effect, dict)
                and int(effect.get("remaining") or 0) > 0
            },
            item_cooldowns={
                int(item_id): max(0, int(expires_at or 0))
                for item_id, expires_at in (payload.get("item_cooldowns") or {}).items()
                if str(item_id).lstrip("-").isdigit()
            },
            skill_cooldowns={
                int(skill_id): max(0, int(expires_at or 0))
                for skill_id, expires_at in (payload.get("skill_cooldowns") or {}).items()
                if str(skill_id).isdigit()
            },
            pvp_mode=max(1, min(4, int(payload.get("pvp_mode") or 1))),
            yata_resistance_element=(
                int(payload.get("yata_resistance_element") or 2)
                if int(payload.get("yata_resistance_element") or 2)
                in YATA_RESISTANCE_NAMES
                else 2
            ),
            active_skill_buffs={
                int(buff_type): dict(buff)
                for buff_type, buff in (payload.get("active_skill_buffs") or {}).items()
                if str(buff_type).isdigit() and isinstance(buff, dict)
            },
            fudai_transaction=fudai_transaction,
            pending_mai_explosion=pending_mai_explosion,
            card_submissions=card_submissions,
            card_claimed_nodes=card_claimed_nodes,
            transform_card_collection=transform_card_collection,
            transform_card_storage=transform_card_storage,
            charm_claimed_reward_ids=charm_claimed_reward_ids,
            charm_name_color_reward_id=charm_name_color_reward_id,
            charm_text_color_reward_id=charm_text_color_reward_id,
            shown_tutorials=shown_tutorials,
            gm_notifications=cls._sanitize_gm_notifications(
                payload.get("gm_notifications")
            ),
            ring_daily_day_key=str(payload.get("ring_daily_day_key") or ""),
            ring_daily_count=max(0, min(20, int(payload.get("ring_daily_count") or 0))),
            ring_week_key=str(payload.get("ring_week_key") or ""),
            ring_weekly_count=max(0, min(100, int(payload.get("ring_weekly_count") or 0))),
            ring_active_mode=(
                str(payload.get("ring_active_mode") or "")
                if str(payload.get("ring_active_mode") or "") in {"daily", "weekly"}
                else ""
            ),
            ring_quest_modes={
                int(quest_id): str(mode)
                for quest_id, mode in (payload.get("ring_quest_modes") or {}).items()
                if str(quest_id).isdigit()
                and 8003 <= int(quest_id) <= 8022
                and str(mode) in {"daily", "weekly"}
            },
        )

    @staticmethod
    def _sanitize_vip_sweep_pending(raw_pending: Any) -> list[dict[str, Any]]:
        """Keep only unclaimed, GameData-valid elite-sweep rewards from a save."""
        if not isinstance(raw_pending, list):
            return []
        pending: list[dict[str, Any]] = []
        seen_reward_ids: set[int] = set()
        for raw_reward in raw_pending[-100:]:
            if not isinstance(raw_reward, dict):
                continue
            try:
                reward_id = int(raw_reward.get("rewardId") or 0)
                copy_id = int(raw_reward.get("copyId") or 0)
                gold_reward = max(0, int(raw_reward.get("goldReward") or 0))
            except (TypeError, ValueError):
                continue
            if (
                reward_id <= 0
                or reward_id > 2_147_483_647
                or reward_id in seen_reward_ids
                or copy_id <= 0
                or not bool(raw_reward.get("canClaim", True))
            ):
                continue
            items: list[dict[str, Any]] = []
            for raw_item in raw_reward.get("items") or []:
                if not isinstance(raw_item, dict):
                    continue
                try:
                    item_id = int(raw_item.get("itemId") or 0)
                    count = max(1, min(9_999, int(raw_item.get("count") or 1)))
                    aptitude = max(
                        1,
                        min(5, int(raw_item.get("aptitude") or 2)),
                    )
                except (TypeError, ValueError):
                    continue
                if GAME_DATA_CATALOG.get_item_definition(item_id) is None:
                    continue
                items.append(
                    {
                        "itemId": item_id,
                        "count": count,
                        "aptitude": aptitude,
                        "canTrade": bool(raw_item.get("canTrade", True)),
                    }
                )
                if len(items) >= 15:
                    break
            seen_reward_ids.add(reward_id)
            pending.append(
                {
                    "chapterName": str(
                        raw_reward.get("chapterName") or "精英副本"
                    )[:80],
                    "items": items,
                    "goldReward": gold_reward,
                    "rewardId": reward_id,
                    "copyId": copy_id,
                    "canClaim": True,
                }
            )
        return pending

    @staticmethod
    def _sanitize_gm_notifications(raw_notifications: Any) -> list[dict[str, Any]]:
        """Keep a bounded, display-only history of GM grants and adjustments."""
        if not isinstance(raw_notifications, list):
            return []
        notifications: list[dict[str, Any]] = []
        seen_ids: set[str] = set()
        for raw_notification in raw_notifications[-100:]:
            if not isinstance(raw_notification, dict):
                continue
            notification_id = str(raw_notification.get("id") or "").strip()[:80]
            if not notification_id or notification_id in seen_ids:
                continue
            seen_ids.add(notification_id)
            notifications.append(
                {
                    "id": notification_id,
                    "kind": str(raw_notification.get("kind") or "notice")[:24],
                    "title": str(raw_notification.get("title") or "GM通知")[:80],
                    "body": str(raw_notification.get("body") or "")[:500],
                    "createdAt": max(
                        0, int(raw_notification.get("createdAt") or 0)
                    ),
                    "readAt": max(0, int(raw_notification.get("readAt") or 0)),
                }
            )
        return notifications

    @staticmethod
    def _migrate_starter_items(inventory: dict[int, InventoryItem]) -> None:
        """Replace the incompatible mock weapon and add the books needed by the skill window."""
        for item in inventory.values():
            if item.item_id == 1_010_042:
                item.item_id = int(ItemId.STARTER_GLOVES)
        next_unique_id = max((item.unique_id for item in inventory.values()), default=0) + 1
        for item_id in (
            ItemId.RAIKIRI_BOOK,
            ItemId.LIGHTNING_BALL_BOOK,
            ItemId.CHIDORI_STREAM_BOOK,
        ):
            if any(item.item_id == int(item_id) for item in inventory.values()):
                continue
            slot = next(slot for slot in range(1, 97) if slot not in inventory)
            inventory[slot] = InventoryItem(
                item_id=int(item_id),
                slot=slot,
                unique_id=next_unique_id,
            )
            next_unique_id += 1

    @staticmethod
    def _rollback_legacy_cultivation_deltas(
        character: CharacterState,
        progression: OfflineProgressionState,
    ) -> None:
        """Remove old stage-up mutations before bonuses become derived from saved stages."""
        systems = (
            ("结印", "JieYin", 12),
            ("柔拳", "RouQuan", 8),
            (
                "写轮眼",
                "XieLunYan",
                GAME_DATA_CATALOG.cultivation_max_stage("XieLunYan"),
            ),
            ("轮眼", "LunHuiYan", 8),
        )
        for state_key, config_name, maximum_stage in systems:
            stage = min(max(1, progression.stages.get(state_key, 1)), maximum_stage)
            if stage <= 1:
                continue
            first = FakeFlashSession._cultivation_attributes_from_catalog(config_name, 1)
            current = FakeFlashSession._cultivation_attributes_from_catalog(config_name, stage)
            for attribute_name, current_value in current.items():
                delta = max(0, current_value - first.get(attribute_name, 0))
                if attribute_name == CultivationAttribute.MAX_HP.value:
                    character.max_hp = max(1, character.max_hp - delta)
                    character.hp = min(character.hp, character.max_hp)
                elif attribute_name == CultivationAttribute.MAX_MP.value:
                    character.max_mp = max(1, character.max_mp - delta)
                    character.mp = min(character.mp, character.max_mp)
                elif attribute_name == CultivationAttribute.ATTACK.value:
                    character.ap_atk = max(1, character.ap_atk - delta)
                elif attribute_name == CultivationAttribute.DEFENCE.value:
                    character.ap_def = max(1, character.ap_def - delta)

    def normalize_item_quantities(self) -> bool:
        """Clamp every persisted item before JSON or native packet serialization."""
        changed = False
        containers = (
            self.inventory,
            self.storage,
            self.transform_card_storage,
        )
        for container in containers:
            for item in container.values():
                if not isinstance(item, InventoryItem):
                    continue
                safe_quantity = _safe_item_quantity(item.item_id, item.quantity)
                if item.quantity != safe_quantity:
                    item.quantity = safe_quantity
                    changed = True
        return changed

    def to_dict(self) -> dict[str, Any]:
        """Convert the game state to a stable JSON-compatible structure."""
        return {
            "version": self.version,
            "character": asdict(self.character),
            "inventory": {str(slot): asdict(item) for slot, item in sorted(self.inventory.items())},
            "storage": {str(slot): asdict(item) for slot, item in sorted(self.storage.items())},
            "bag_capacity": self.bag_capacity,
            "storage_capacity": self.storage_capacity,
            "pet_capacity": self.pet_capacity,
            "skills": {str(skill_id): asdict(skill) for skill_id, skill in sorted(self.skills.items())},
            "pets": {str(unique_id): asdict(pet) for unique_id, pet in sorted(self.pets.items())},
            "progression": asdict(self.progression),
            "quest": asdict(self.quest),
            "original_quests": {
                str(quest_id): asdict(progress)
                for quest_id, progress in sorted(self.original_quests.items())
            },
            "keymap": {str(key): asdict(binding) for key, binding in sorted(self.keymap.items())},
            "character_config": self.character_config,
            "second_level_password": asdict(self.second_level_password),
            "money": self.money,
            "bound_money": self.bound_money,
            "cash_money": self.cash_money,
            "coupon_money": self.coupon_money,
            "recharge_total": self.recharge_total,
            "first_charge_claimed": self.first_charge_claimed,
            "limited_recharge_total_claims": self.limited_recharge_total_claims,
            "limited_recharge_each_claims": self.limited_recharge_each_claims,
            "new_server_claimed_ids": self.new_server_claimed_ids,
            "new_server_cashbind_remaining": self.new_server_cashbind_remaining,
            "storage_money": self.storage_money,
            "vip_item_id": self.vip_item_id,
            "vip_expires_at": self.vip_expires_at,
            "vip_sweep_pending": self._sanitize_vip_sweep_pending(
                self.vip_sweep_pending
            ),
            "vip_pve_sweep_week_key": self.vip_pve_sweep_week_key,
            "active_item_effects": {
                str(item_id): expires_at
                for item_id, expires_at in sorted(self.active_item_effects.items())
            },
            "auto_consume_effects": {
                str(item_id): {
                    "remaining": max(0, int(effect.get("remaining") or 0)),
                    "total": max(
                        max(0, int(effect.get("remaining") or 0)),
                        int(effect.get("total") or 0),
                    ),
                }
                for item_id, effect in sorted(self.auto_consume_effects.items())
                if int(effect.get("remaining") or 0) > 0
            },
            "item_cooldowns": {
                str(item_id): expires_at
                for item_id, expires_at in sorted(self.item_cooldowns.items())
            },
            "skill_cooldowns": {
                str(skill_id): expires_at
                for skill_id, expires_at in sorted(self.skill_cooldowns.items())
            },
            "pvp_mode": max(1, min(4, int(self.pvp_mode or 1))),
            "yata_resistance_element": self.yata_resistance_element,
            "active_skill_buffs": {
                str(buff_type): dict(buff)
                for buff_type, buff in sorted(self.active_skill_buffs.items())
            },
            "fudai_transaction": (
                asdict(self.fudai_transaction) if self.fudai_transaction is not None else None
            ),
            "pending_mai_explosion": (
                asdict(self.pending_mai_explosion)
                if self.pending_mai_explosion is not None
                else None
            ),
            "card_submissions": {
                node_key: {
                    str(item_id): count
                    for item_id, count in sorted(counts.items())
                }
                for node_key, counts in sorted(self.card_submissions.items())
            },
            "card_claimed_nodes": sorted(self.card_claimed_nodes),
            "transform_card_collection": sorted(self.transform_card_collection),
            "transform_card_storage": {
                str(item_id): asdict(item)
                for item_id, item in sorted(self.transform_card_storage.items())
            },
            "charm_claimed_reward_ids": sorted(self.charm_claimed_reward_ids),
            "charm_name_color_reward_id": self.charm_name_color_reward_id,
            "charm_text_color_reward_id": self.charm_text_color_reward_id,
            "shown_tutorials": sorted(self.shown_tutorials),
            "gm_notifications": self._sanitize_gm_notifications(
                self.gm_notifications
            ),
            "ring_daily_day_key": self.ring_daily_day_key,
            "ring_daily_count": self.ring_daily_count,
            "ring_week_key": self.ring_week_key,
            "ring_weekly_count": self.ring_weekly_count,
            "ring_active_mode": self.ring_active_mode,
            "ring_quest_modes": {
                str(quest_id): mode
                for quest_id, mode in sorted(self.ring_quest_modes.items())
                if mode in {"daily", "weekly"}
            },
        }


