@dataclass(frozen=True)
class SkillDefinition:
    """Learn, consume, damage, and targeting data read from the original Skill section."""

    skill_id: int
    required_level: int
    book_item_id: int
    mp_costs: dict[int, int]
    cooldown_seconds: dict[int, float]
    cooldown_base: float
    cooldown_per_level: float
    zq_cost_per_level: int
    damage_base: float
    damage_per_level: float
    multi_target: bool
    required_skill_id: int = 0
    required_mai: int = 0
    required_xielunyan: int = 0
    required_family_contribution: int = 0
    target_type: int = 1
    effect_type: str = "attack"
    effect_value_base: float = 0
    effect_value_per_level: float = 0
    effect_duration_base_ms: int = 0
    effect_duration_per_level_ms: int = 0
    trigger_base: float = 100
    trigger_per_level: float = 0
    effect_value2_base: float = 0
    effect_value2_per_level: float = 0
    range_type: int = 0
    range_base: float = 0
    range_per_level: float = 0
    range_max: float = 0
    max_range: float = 0
    fire_local: bool = False
    client_hit_trigger: bool = False
    opposite_skill_id: int = 0
    defence_probability_base: float = 0
    defence_probability_per_level: float = 0
    debuff_transfer_probability: float = 0
    trigger_skill_id: int = 0

    def mp_cost(self, level: int) -> int:
        """Return the exact configured cost, clamping above the available table."""
        if not self.mp_costs:
            return 0
        bounded_level = min(max(1, level), max(self.mp_costs))
        return self.mp_costs.get(bounded_level, 0)

    def damage_percent(self, level: int) -> int:
        """Convert the original additive attack effect into a total damage percentage."""
        forbidden_balance = FORBIDDEN_SKILL_BALANCE.get(self.skill_id)
        if forbidden_balance is not None and forbidden_balance["damage_percent"] > 0:
            return forbidden_balance["damage_percent"]
        # 神罗天征（4009）的 effect.valueBase/valueLevel 是击退效果参数，
        # 不是伤害加成。客户端技能说明单独规定其伤害为 110% + 每级 1%。
        if self.skill_id == 4_009 and self.effect_type == "knock_back":
            return max(25, 110 + max(1, level))
        return max(25, round(100 + self.damage_base + self.damage_per_level * level))

    def cooldown_ms(self, level: int) -> int:
        """Return the original per-level cooldown or its base/level fallback in milliseconds."""
        forbidden_balance = FORBIDDEN_SKILL_BALANCE.get(self.skill_id)
        if forbidden_balance is not None:
            return forbidden_balance["cooldown_ms"]
        project_balance = PROJECT_SPECIAL_SKILL_BALANCE.get(self.skill_id)
        if project_balance is not None:
            return project_special_skill_cooldown_ms(self.skill_id, level)
        if self.skill_id == SHINRA_TENSEI_SKILL_ID:
            return SHINRA_TENSEI_FIXED_COOLDOWN_MS
        seconds = self.cooldown_seconds.get(level)
        if seconds is None:
            seconds = self.cooldown_base + self.cooldown_per_level * level
        return max(0, round(seconds * 1_000))

    def zq_cost(self, level: int) -> int:
        """Return the configured cast-time chakra-essence cost for this level."""
        forbidden_balance = FORBIDDEN_SKILL_BALANCE.get(self.skill_id)
        if forbidden_balance is not None:
            return forbidden_balance["zq_cost"]
        project_balance = PROJECT_SPECIAL_SKILL_BALANCE.get(self.skill_id)
        if project_balance is not None:
            return project_special_skill_zq_cost(self.skill_id, level)
        return max(0, self.zq_cost_per_level * level)

    def effect_value(self, level: int) -> float:
        """Return the authored Buff magnitude for one learned level."""
        return self.effect_value_base + self.effect_value_per_level * level

    def effect_value2(self, level: int) -> float:
        """Return the authored secondary magnitude used by compound effects."""
        return self.effect_value2_base + self.effect_value2_per_level * level

    def effect_range(self, level: int) -> float:
        """Return the authored cast radius/range, including the original cap."""
        value = self.range_base + self.range_per_level * max(1, level)
        if self.range_max > 0:
            value = min(value, self.range_max)
        if self.max_range > 0 and value <= 0:
            value = self.max_range
        if value > 0:
            return value
        return {1: 150.0, 2: 400.0, 3: 300.0, 4: 1_200.0}.get(
            self.range_type,
            650.0,
        )

    def effect_duration_ms(self, level: int) -> int:
        """Return the authored Buff duration for one learned level."""
        return max(
            0,
            round(self.effect_duration_base_ms + self.effect_duration_per_level_ms * level),
        )

    def trigger_percent(self, level: int) -> float:
        """Return the authored trigger chance clamped to a normal percentage."""
        return max(0.0, min(100.0, self.trigger_base + self.trigger_per_level * level))

    def upgrade_requirements(self, next_level: int) -> tuple[int, int]:
        """Return the original coin cost and accumulated mastery requirement."""
        row_index = next_level - 2
        if not 0 <= row_index < len(NORMAL_SKILL_REQUIREMENTS):
            return 0, 0
        if self.skill_id // 100 in {31, 32}:
            mastery, coins = FAMILY_SKILL_REQUIREMENTS[row_index]
            return coins, mastery
        return NORMAL_SKILL_REQUIREMENTS[row_index]


