    value_base: float
    value_per_level: float
    duration_base_ms: int
    duration_per_level_ms: int
    trigger_base: float
    trigger_per_level: float

    def value(self, level: int) -> float:
        return self.value_base + self.value_per_level * level

    def duration_ms(self, level: int) -> int:
        return max(0, round(self.duration_base_ms + self.duration_per_level_ms * level))

    def trigger_percent(self, level: int) -> float:
        return max(0.0, min(100.0, self.trigger_base + self.trigger_per_level * level))

