@dataclass(frozen=True)
class FootholdState:
    """One walkable map segment used by authoritative monster movement."""

    foothold_id: int
    x1: int
    y1: int
    x2: int
    y2: int
    previous_id: int = 0
    next_id: int = 0

    @property
    def left(self) -> int:
        return min(self.x1, self.x2)

    @property
    def right(self) -> int:
        return max(self.x1, self.x2)

    def y_at(self, x: int) -> int:
        if self.x1 == self.x2:
            return min(self.y1, self.y2)
        ratio = (max(self.left, min(self.right, x)) - self.x1) / (self.x2 - self.x1)
        return round(self.y1 + (self.y2 - self.y1) * ratio)


