@dataclass(frozen=True)
class MapDefinition:
    """Minimal map runtime data extracted from GameData.dat."""

    map_id: int
    name: str
    return_map_id: int
    required_level: int
    portals: dict[str, PortalState]
    footholds: dict[int, FootholdState]
    ladder_ropes: tuple[LadderRopeState, ...]
    npcs: tuple[NpcState, ...]
    monsters: tuple[MonsterState, ...]
    items: tuple[MapItemState, ...]

    def foothold_below(self, x: int, y: int) -> FootholdState | None:
        """Resolve the same nearest walkable floor used for authored spawns."""
        candidates = [
            (floor.y_at(x) - y, floor)
            for floor in self.footholds.values()
            if floor.x1 != floor.x2
            and floor.left <= x <= floor.right
            and floor.y_at(x) >= y - 20
        ]
        if candidates:
            return min(candidates, key=lambda value: value[0])[1]
        overlapping = [
            floor
            for floor in self.footholds.values()
            if floor.x1 != floor.x2 and floor.left <= x <= floor.right
        ]
        return min(overlapping, key=lambda floor: abs(floor.y_at(x) - y), default=None)

    def ground_position(
        self,
        x: int,
        y: int,
        foothold_id: int = 0,
    ) -> tuple[int, int, int]:
        """Project a runtime spawn onto a real walkable foothold in this map."""
        walkable = [floor for floor in self.footholds.values() if floor.x1 != floor.x2]
        floor = self.footholds.get(foothold_id)
        if floor is not None and (floor.x1 == floor.x2 or not floor.left <= x <= floor.right):
            floor = None
        floor = floor or self.foothold_below(x, y)
        if floor is None and walkable:
            floor = min(
                walkable,
                key=lambda candidate: (
                    max(candidate.left - x, 0, x - candidate.right) ** 2
                    + (candidate.y_at(max(candidate.left, min(candidate.right, x))) - y) ** 2
                ),
            )
        if floor is None:
            return x, y, foothold_id
        grounded_x = max(floor.left, min(floor.right, x))
        return grounded_x, floor.y_at(grounded_x), floor.foothold_id

    @staticmethod
    def _ground_transition_x(
        source: FootholdState,
        destination: FootholdState,
    ) -> int:
        endpoints = (
            (source.x1, source.y1, destination.x1, destination.y1),
            (source.x1, source.y1, destination.x2, destination.y2),
            (source.x2, source.y2, destination.x1, destination.y1),
            (source.x2, source.y2, destination.x2, destination.y2),
        )
        closest = min(
            endpoints,
            key=lambda value: (value[0] - value[2]) ** 2 + (value[1] - value[3]) ** 2,
        )
        return closest[0]

    def _monster_path_edges(
        self,
    ) -> dict[int, list[tuple[int, str, int]]]:
        """Build Nya-compatible ground and ladder/rope path connections."""
        edges: dict[int, list[tuple[int, str, int]]] = {
            foothold_id: [] for foothold_id in self.footholds
        }

        def add_edge(source_id: int, destination_id: int, kind: str, x: int) -> None:
            if source_id == destination_id or destination_id not in edges:
                return
            edge = (destination_id, kind, x)
            if edge not in edges[source_id]:
                edges[source_id].append(edge)

        for floor in self.footholds.values():
            if floor.x1 == floor.x2:
                continue
            for neighbor_id in (floor.previous_id, floor.next_id):
                neighbor = self.footholds.get(neighbor_id)
                if neighbor is None or neighbor.x1 == neighbor.x2:
                    continue
                transition_x = self._ground_transition_x(floor, neighbor)
                add_edge(floor.foothold_id, neighbor_id, "ground", transition_x)
                add_edge(
                    neighbor_id,
                    floor.foothold_id,
                    "ground",
                    self._ground_transition_x(neighbor, floor),
                )

        for connector in self.ladder_ropes:
            intersecting: list[tuple[int, int]] = []
            below: list[tuple[int, int]] = []
            for floor in self.footholds.values():
                if floor.x1 == floor.x2 or not floor.left <= connector.x <= floor.right:
                    continue
                floor_y = floor.y_at(connector.x)
                if connector.top - 20 <= floor_y <= connector.bottom:
                    intersecting.append((floor.foothold_id, floor_y))
                elif floor_y > connector.bottom:
                    below.append((floor.foothold_id, floor_y))
            if below:
                intersecting.append(min(below, key=lambda value: value[1]))
            connected = sorted(set(intersecting), key=lambda value: value[1])
            for source_id, _ in connected:
                for destination_id, _ in connected:
                    add_edge(source_id, destination_id, "ladder", connector.x)

        # Several original maps encode stairs as a vertical foothold rather
        # than a LadderRope node.  The old path builder skipped those segments,
        # leaving a boss on one platform with no route to a player on the next
        # platform.  Treat the nearest horizontal floors at the two ends of a
        # vertical segment as the same authored transition.  This preserves
        # server-side floor grounding while allowing the existing teleport
        # fragment to perform the vertical step on the client.
        for connector in self.footholds.values():
            if connector.x1 != connector.x2:
                continue
            connector_top = min(connector.y1, connector.y2)
            connector_bottom = max(connector.y1, connector.y2)
            endpoint_floors: list[tuple[int, int, int]] = []
            for floor in self.footholds.values():
                if floor.x1 == floor.x2 or not floor.left <= connector.x1 <= floor.right:
                    continue
                floor_y = floor.y_at(connector.x1)
                distance_to_top = abs(floor_y - connector_top)
                distance_to_bottom = abs(floor_y - connector_bottom)
                endpoint_floors.append(
                    (floor.foothold_id, floor_y, min(distance_to_top, distance_to_bottom))
                )
            if not endpoint_floors:
                continue
            top_candidates = [
                value for value in endpoint_floors if value[1] <= connector_top + 8
            ]
            bottom_candidates = [
                value for value in endpoint_floors if value[1] >= connector_bottom
            ]
            if not top_candidates or not bottom_candidates:
                continue
            top_floor = max(
                top_candidates,
                key=lambda value: (value[1], -value[2]),
            )
            bottom_floor = min(
                bottom_candidates,
                key=lambda value: (value[1], value[2]),
            )
            if (
                top_floor[0] == bottom_floor[0]
                or abs(top_floor[1] - connector_top) > 64
                or abs(bottom_floor[1] - connector_bottom) > 64
            ):
                continue
            add_edge(top_floor[0], bottom_floor[0], "ladder", connector.x1)
            add_edge(bottom_floor[0], top_floor[0], "ladder", connector.x1)
        return edges

    def monster_path_next_edge(
        self,
        source_foothold_id: int,
        destination_foothold_id: int,
    ) -> tuple[int, str, int] | None:
        """Return the first original path-finder transition toward a target floor."""
        if source_foothold_id == destination_foothold_id:
            return None
        edges = self._monster_path_edges()
        if source_foothold_id not in edges or destination_foothold_id not in edges:
            return None
        queue = [source_foothold_id]
        previous: dict[int, tuple[int, str, int] | None] = {
            source_foothold_id: None
        }
        for current_id in queue:
            for destination_id, kind, transition_x in edges[current_id]:
                if destination_id in previous:
                    continue
                previous[destination_id] = (current_id, kind, transition_x)
                if destination_id == destination_foothold_id:
                    queue.clear()
                    break
                queue.append(destination_id)
        if destination_foothold_id not in previous:
            return None
        cursor = destination_foothold_id
        while True:
            step = previous[cursor]
            if step is None:
                return None
            parent_id, kind, transition_x = step
            if parent_id == source_foothold_id:
                return cursor, kind, transition_x
            cursor = parent_id

    def spawn_portal(self) -> PortalState | None:
        """Return the map's explicit spawn portal, or its first portal as a fallback."""
        for portal in self.portals.values():
            if portal.name == "sp" or portal.portal_type in (-1, 0):
                return portal
        return next(iter(self.portals.values()), None)

    def portal_named(self, name: str) -> PortalState | None:
        """Find the destination portal named by the source map's `tn` field."""
        return next((portal for portal in self.portals.values() if portal.name == name), None)

    def arrival_portal(
        self,
        source_map_id: int,
        source_portal: PortalState,
    ) -> PortalState | None:
        """Resolve only an authored destination or the one known malformed copy exit."""
        named_matches = [
            portal
            for portal in self.portals.values()
            if source_portal.target_portal_name
            and portal.name == source_portal.target_portal_name
        ]
        if len(named_matches) == 1:
            return named_matches[0]

        strict_reverse_matches = [
            portal
            for portal in self.portals.values()
            if portal.target_map_id == source_map_id
            and portal.target_portal_name == source_portal.name
        ]
        if len(strict_reverse_matches) == 1:
            return strict_reverse_matches[0]

        reverse_matches = [
            portal for portal in self.portals.values() if portal.target_map_id == source_map_id
        ]
        if len(reverse_matches) == 1:
            return reverse_matches[0]

        # First Training Ground is the only local map whose authored exit has neither `tn`
        # nor a reverse edge. Its original return destination is Konoha's west gate.
        if (
            source_map_id == 401_000_000
            and self.map_id == 100_000_000
            and not source_portal.target_portal_name
        ):
            return self.portal_named("west01")
        return None


