    def muye_battle_shop(self) -> dict[int, int]:
        """Return the authoritative item-to-fame prices from GameData.MuyeBattle.shop."""
        raw_shop = self.raw_muye_battle.get("shop")
        decoded_shop = self._decode_section(raw_shop) if raw_shop is not None else {}
        if not isinstance(decoded_shop, dict):
            return {}
        prices: dict[int, int] = {}
        for raw_entry in decoded_shop.values():
            if not isinstance(raw_entry, dict):
                continue
            item_id = self._as_int(raw_entry.get("itemId"))
            fame_point = self._as_int(raw_entry.get("famePoint"))
            if (
                item_id > 0
                and fame_point > 0
                and self.get_item_definition(item_id) is not None
            ):
                prices[item_id] = fame_point
        return prices

    def local_pk_common(self) -> dict[str, Any]:
        """Return the decoded LocalPk.common server rules."""
        raw_common = self.raw_local_pk.get("common")
