    def spirit_pack_extension_cost(self, current_limit: int, target_limit: int) -> int:
        """Mirror the client's cumulative GameData.Spirit.common.extend lookup."""
        extend = self.spirit_common().get("extend")
        decoded = self._decode_section(extend) if extend is not None else {}
        if not isinstance(decoded, dict):
            return 0
        return sum(
            max(0, self._as_int(decoded.get(str(limit - 4))))
            for limit in range(max(5, current_limit), min(30, target_limit))
        )

    def pet_weather_rate(self, weather_type: int, pet_item_id: int) -> int:
        """Return the authored weather percentage for a dog, toad, or snake pet."""
        definition = self.weather_definitions.get(str(max(0, min(9, weather_type))))
        if not isinstance(definition, dict):
            return 0
        rate_field = {1: "dog_rate", 2: "toad_rate", 3: "snake_rate"}.get(
            max(0, pet_item_id) // 100
        )
        return self._as_int(definition.get(rate_field)) if rate_field else 0

    def spirit_equip_limit(self, level: int) -> int:
        """Return the number of unlocked negative equipment slots at a level."""
        carry = self.spirit_common().get("carry")
        decoded = self._decode_section(carry) if carry is not None else {}
        if not isinstance(decoded, dict):
            return 1
        unlocked = 0
        for raw_level, raw_count in decoded.items():
            required = self._as_int(str(raw_level)[5:])
            if required <= level:
                unlocked = max(unlocked, self._as_int(raw_count))
        return max(1, min(8, unlocked))

    def spirit_level_threshold(self, item_id: int, level: int) -> int:
        """Return the cumulative fusion experience required for one authored level."""
        definition = self.spirit_items().get(item_id)
        spec = definition.get("spec") if isinstance(definition, dict) else None
        color = str(spec.get("color") or "") if isinstance(spec, dict) else ""
        level_up = self.spirit_common().get("levelUp")
        decoded = self._decode_section(level_up) if level_up is not None else {}
        row = decoded.get(f"level{max(1, min(20, level))}") if isinstance(decoded, dict) else None
        return max(0, self._as_int(row.get(color))) if isinstance(row, dict) else 0

    def spirit_attribute_values(self, item_id: int, level: int) -> dict[str, int]:
        """Return one equipped spirit's authored attribute at the requested level."""
        definition = self.spirit_items().get(item_id)
        spec = definition.get("spec") if isinstance(definition, dict) else None
        if not isinstance(spec, dict):
            return {}
        attribute_name = str(spec.get("attrType") or "")
        if item_id in {801, 802}:
            # Gold yin/yang Six Paths wills use a stable +3% per level:
            # level 1 is 3%, level 20 is 60%.
            value = 3 * max(1, min(20, level))
            return {attribute_name: value} if attribute_name and value > 0 else {}
        values = spec.get("attrValues")
        value = 0
        if isinstance(values, dict):
            # Some authored spirit tables dip at high levels (for example the
            # gold yin/yang Six Paths wills).  Attribute bonuses must never
            # shrink as the will levels up, so take the cumulative maximum.
            for level_candidate in range(1, max(1, min(20, level)) + 1):
                value = max(
                    value,
                    self._as_int(values.get(f"level{level_candidate}")),
                )
        return {attribute_name: value} if attribute_name and value > 0 else {}

