class MultiplayerHub:
    """Thread-safe registry for online sessions, visibility, chat, and top-login."""

    TICKET_SECONDS = 180.0

    def __init__(self, accounts: AccountService = ACCOUNT_SERVICE):
        self.accounts = accounts
        self.lock = threading.RLock()
        self.stall_path = accounts.path.with_name(f"{accounts.path.stem}-stalls.json")
        self.auction_path = accounts.path.with_name(
            f"{accounts.path.stem}-auctions.json"
        )
        self.money_sell_path = accounts.path.with_name(
            f"{accounts.path.stem}-money-sell.json"
        )
        self.bounty_path = accounts.path.with_name(
            f"{accounts.path.stem}-bounties.json"
        )
        self.artifact_war_path = accounts.path.with_name(
            f"{accounts.path.stem}-artifact-war.json"
        )
        self.war_relic_path = accounts.path.with_name(
            f"{accounts.path.stem}-war-relics.json"
        )
        self.chunin_path = accounts.path.with_name(
            f"{accounts.path.stem}-chunin.json"
        )
        self.boss_state_path = accounts.path.with_name(
            f"{accounts.path.stem}-boss-state.json"
        )
        self.redemption_codes_path = accounts.path.with_name(
            f"{accounts.path.stem}-redemption-codes.json"
        )
        self.redemption_codes: dict[str, dict[str, Any]] = self._load_redemption_codes()
        self.news_path = accounts.path.with_name(f"{accounts.path.stem}-news.json")
        self.news: dict[str, Any] = self._load_news()
        self.activity_overrides_path = accounts.path.with_name(
            f"{accounts.path.stem}-activity-overrides.json"
        )
        self.activity_overrides: dict[str, Any] = self._load_activity_overrides()
        self.pending_channels: dict[int, ChannelTicket] = {}
        self.sessions_by_character: dict[int, FakeFlashSession] = {}
        self.sessions_by_account: dict[int, FakeFlashSession] = {}
        # Login, character-selection, and channel sockets can overlap briefly.
        # They must share one state object or an older socket can save a stale
        # full JSON document over activity and achievement progress.
        self.character_stores: dict[Path, SinglePlayerStore] = {}
        self.parties: dict[int, PartyState] = {}
        self.party_by_character: dict[int, int] = {}
        self.next_party_id = 1
        self.trade_invites: dict[int, int] = {}
        self.trades_by_character: dict[int, TradeState] = {}
        self.double_heal_invites: dict[int, int] = {}
        self.bond_invites: dict[int, tuple[int, int]] = {}
        self.family_invites: dict[int, int] = {}
        self.next_drop_by_world: dict[tuple[int, int, int], int] = {}
        self.monster_controllers: dict[tuple[Any, ...], FakeFlashSession] = {}
        self.world_states: dict[tuple[Any, ...], WorldMapState] = {}
        self.stalls: dict[int, StallState] = self._load_stalls()
        self.next_stall_listing_id = 1 + max(
            (
                listing.uid
                for stall in self.stalls.values()
                for listing in stall.listings.values()
            ),
            default=0,
        )
        self.auction_lots: dict[int, AuctionLot] = self._load_auctions()
        self.next_auction_lot_id = 1 + max(self.auction_lots, default=0)
        self.money_sell_listings: dict[int, MoneySellListing] = (
            self._load_money_sell_listings()
        )
        self.next_money_sell_sn = 1 + max(self.money_sell_listings, default=0)
        self.bounties: dict[int, BountyEntry] = self._load_bounties()
        self.next_bounty_id = 1 + max(self.bounties, default=0)
        self.artifact_war = self._load_artifact_war()
        self.war_relics = self._load_war_relics()
        self.chunin = self._load_chunin()
        self.boss_respawns = self._load_boss_respawns()
        self.war_battle_settled_season = ""
        self.next_copy_instance_id = 1
        self.next_transient_player_id = 1_700_000_000
        self.muye_battle_started_at = 0.0
        self.muye_battle_duration = 30 * 60
        self.local_pk_queue: list[int] = []
        self.war_3v3_registrations: dict[int, War3V3Registration] = {}
        self.war_3v3_queue: list[int] = []
        self.war_3v3_matches: dict[int, War3V3Match] = {}
        # Nya's newer 2343 panel has its own party/matching state.  Keep it
        # separate from the legacy 1840 confirmation flow so one client can
        # never receive a packet from the wrong protocol family.
        self.ninja_3v3_queue: dict[int, float] = {}
        self.next_war_3v3_match_id = 1
        self.published_event_notices: set[str] = set()

    def character_store(self, path: Path) -> SinglePlayerStore:
        """Return the process-authoritative store shared by every socket for a character."""
        resolved = path.resolve()
        with self.lock:
            store = self.character_stores.get(resolved)
            if store is None:
                store = SinglePlayerStore(resolved)
                self.character_stores[resolved] = store
            return store

    def issue_channel_ticket(
        self,
        account_id: int,
        character_id: int,
        line_id: int,
        native_flash_direct: bool = False,
        advertise_host: str = "",
    ) -> None:
        with self.lock:
            self.pending_channels[int(character_id)] = ChannelTicket(
                account_id=int(account_id),
                character_id=int(character_id),
                line_id=max(1, min(PUBLIC_LINE_COUNT, int(line_id))),
                expires_at=time.monotonic() + self.TICKET_SECONDS,
                native_flash_direct=bool(native_flash_direct),
                advertise_host=str(advertise_host).strip(),
            )

    def consume_channel_ticket(self, character_id: int) -> ChannelTicket | None:
        with self.lock:
            now = time.monotonic()
            expired = [
                key
                for key, ticket in self.pending_channels.items()
                if ticket.expires_at < now
            ]
            for key in expired:
                self.pending_channels.pop(key, None)
            ticket = self.pending_channels.pop(int(character_id), None)
            return ticket if ticket and ticket.expires_at >= now else None

    def enter_world(self, session: FakeFlashSession) -> None:
        """Register a player, kick an older account session, and sync map visibility."""
        old_session: FakeFlashSession | None = None
        canceled_trade: tuple[TradeState, list[FakeFlashSession]] | None = None
        with self.lock:
            if session.account_id:
                old_session = self.sessions_by_account.get(session.account_id)
            if old_session is not None and old_session is not session:
                canceled_trade = self.cancel_trade(old_session.character.character_id)
            self.sessions_by_character[session.character.character_id] = session
            if session.account_id:
                self.sessions_by_account[session.account_id] = session
            self._bind_world_state_locked(session)
            peers = self._visible_peers_locked(session)
        if old_session is not None and old_session is not session:
            old_session.kick("账号已在另一处登录，当前连接已被顶下线。")
        if canceled_trade is not None:
            for participant in canceled_trade[1]:
                participant.send_text(
                    f"{op(ServerOpcode.PLAYER_INTERACTION)}:9:0"
                )
        for peer in peers:
            if not getattr(session, "server_simulated", False):
                session._send_foreign_player(peer)
            if not getattr(peer, "server_simulated", False):
                peer._send_foreign_player(session)
        simulated_module = sys.modules.get("simulated_player_ai")
        if simulated_module is not None:
            simulated_module.notify_real_session_visibility(session)

    def leave_world(self, session: FakeFlashSession) -> bool:
        """Remove this connection and report whether it still owns persistence."""
        canceled_trade: tuple[TradeState, list[FakeFlashSession]] | None = None
        local_pk_opponent: FakeFlashSession | None = None
        canceled_war_registration_members: list[FakeFlashSession] = []
        forfeited_war_match: War3V3Match | None = None
        war_match_finisher: FakeFlashSession | None = None
        forfeiting_war_team = session.war_3v3_team
        with self.lock:
            if self.sessions_by_character.get(session.character.character_id) is not session:
                # A newer login already owns this character. The replaced session
                # must not overwrite the new session's save from stale memory.
                return not session.entered_game
            self.local_pk_queue = [
                character_id
                for character_id in self.local_pk_queue
                if character_id != session.character.character_id
            ]
            queued_ninja_party_ids = [
                party_id
                for party_id, _queued_at in self.ninja_3v3_queue.items()
                if (
                    (party := self.parties.get(party_id)) is not None
                    and session.character.character_id in party.member_ids
                )
            ]
            for party_id in queued_ninja_party_ids:
                self.ninja_3v3_queue.pop(party_id, None)
            if session.local_pk_opponent_id:
                local_pk_opponent = self.sessions_by_character.get(
                    session.local_pk_opponent_id
                )
            registration_party_ids = [
                party_id
                for party_id, registration in self.war_3v3_registrations.items()
                if session.character.character_id in registration.member_ids
            ]
            for party_id in registration_party_ids:
                registration = self.war_3v3_registrations.pop(party_id)
                self.war_3v3_queue = [
                    queued_party_id
                    for queued_party_id in self.war_3v3_queue
                    if queued_party_id != party_id
                ]
                canceled_war_registration_members.extend(
                    member
                    for member_id in registration.member_ids
                    if (
                        (member := self.sessions_by_character.get(member_id))
                        is not None
                        and member is not session
                    )
                )
            if session.war_3v3_match_id:
                forfeited_war_match = self.war_3v3_matches.pop(
                    session.war_3v3_match_id,
                    None,
                )
                if forfeited_war_match is not None:
                    war_match_finisher = next(
                        (
                            participant
                            for participant_id in forfeited_war_match.participant_ids
                            if (
                                (
                                    participant := self.sessions_by_character.get(
                                        participant_id
                                    )
                                )
                                is not None
                                and participant is not session
                            )
                        ),
                        None,
                    )
            canceled_trade = self.cancel_trade(session.character.character_id)
            peers = self._visible_peers_locked(session)
            self.sessions_by_character.pop(session.character.character_id, None)
            if session.account_id and self.sessions_by_account.get(session.account_id) is session:
                self.sessions_by_account.pop(session.account_id, None)
            self.trade_invites.pop(session.character.character_id, None)
            self.trade_invites = {
                target_id: source_id
                for target_id, source_id in self.trade_invites.items()
                if source_id != session.character.character_id
            }
            self.double_heal_invites.pop(session.character.character_id, None)
            self.double_heal_invites = {
                target_id: source_id
                for target_id, source_id in self.double_heal_invites.items()
                if source_id != session.character.character_id
            }
            self.bond_invites.pop(session.character.character_id, None)
            self.family_invites.pop(session.character.character_id, None)
        if (
            local_pk_opponent is not None
            and local_pk_opponent.local_pk_opponent_id
            == session.character.character_id
        ):
            local_pk_opponent._finish_local_pk_battle(
                session,
                notify_loser=False,
            )
        if canceled_trade is not None:
            for participant in canceled_trade[1]:
                if participant is not session:
                    participant.send_text(
                        f"{op(ServerOpcode.PLAYER_INTERACTION)}:9:0"
                    )
        for participant in canceled_war_registration_members:
            participant.send_text(
                f"{op(ServerOpcode.WAR_3V3_SOMEONE_LEAVE_MATCHING)}"
            )
        if forfeited_war_match is not None and war_match_finisher is not None:
            forced_result = 2 if forfeiting_war_team == 0 else 1
            war_match_finisher._finish_war_3v3_match(
                forfeited_war_match,
                forced_result=forced_result,
            )
        session._restore_war_3v3_disconnect_location()
        for peer in peers:
            peer.send_text(
                f"{op(ServerOpcode.REMOVE_PLAYER_FROM_MAP)}:"
                f"{session.character.character_id}"
            )
        return True

    def before_map_change(self, session: FakeFlashSession) -> None:
        replacement = self.release_monster_control(session)
        if replacement is not None:
            replacement._send_alive_monster_controls()
        with self.lock:
            peers = self._visible_peers_locked(session)
        for peer in peers:
            peer.send_text(
                f"{op(ServerOpcode.REMOVE_PLAYER_FROM_MAP)}:"
                f"{session.character.character_id}"
            )
            session.send_text(
                f"{op(ServerOpcode.REMOVE_PLAYER_FROM_MAP)}:"
                f"{peer.character.character_id}"
            )

    def after_map_change(self, session: FakeFlashSession) -> None:
        with self.lock:
            self._bind_world_state_locked(session)
            peers = self._visible_peers_locked(session)
        for peer in peers:
            if not getattr(session, "server_simulated", False):
                session._send_foreign_player(peer)
            if not getattr(peer, "server_simulated", False):
                peer._send_foreign_player(session)
        simulated_module = sys.modules.get("simulated_player_ai")
        if simulated_module is not None:
            simulated_module.notify_real_session_visibility(session)

    def visible_peers(self, session: FakeFlashSession) -> list[FakeFlashSession]:
        with self.lock:
            return list(self._visible_peers_locked(session))

    def muye_battle_sessions(self) -> list[FakeFlashSession]:
        """Return every connected participant in the shared Wood Leaf battlefield."""
        with self.lock:
            return [
                session
                for session in self.sessions_by_character.values()
                if session.entered_game and session.muye_battle_team in (1, 2)
            ]

    def _visible_peers_locked(self, session: FakeFlashSession) -> list[FakeFlashSession]:
        return [
            peer
            for peer in self.sessions_by_character.values()
            if peer is not session
            and peer.entered_game
            and (
                peer.line_id == session.line_id
                or (
                    session.war_3v3_match_id > 0
                    and peer.war_3v3_match_id == session.war_3v3_match_id
                )
                or (
                    session.war_battle_active
                    and peer.war_battle_active
                    and peer.war_battle_channel == session.war_battle_channel
                )
                or (
                    session.chunin_active
                    and peer.chunin_active
                    and peer.copy_instance_id == session.copy_instance_id
                )
            )
            and peer.character.map_id == session.character.map_id
            and peer.copy_instance_id == session.copy_instance_id
        ]

    def session_for_character(self, character_id: int) -> FakeFlashSession | None:
        with self.lock:
            return self.sessions_by_character.get(int(character_id))

    def visible_shadow_clone(
        self,
        viewer: FakeFlashSession,
        actor_id: int,
    ) -> tuple[FakeFlashSession, ShadowCloneState] | None:
        """Resolve one transient clone only when its owner is visible to viewer."""
        with self.lock:
            visible_owners = {viewer, *self._visible_peers_locked(viewer)}
            for owner in visible_owners:
                clone = owner.shadow_clones.get(int(actor_id))
                if clone is not None:
                    return owner, clone
        return None

    def session_for_name(self, name: str) -> FakeFlashSession | None:
        normalized = name.strip().casefold()
        with self.lock:
            return next(
                (
                    session
                    for session in self.sessions_by_character.values()
                    if session.character.name.casefold() == normalized
                ),
                None,
            )

    def broadcast_visible(self, source: FakeFlashSession, payload: str) -> None:
        for peer in self.visible_peers(source):
            if (
                getattr(source, "server_simulated", False)
                and getattr(peer, "server_simulated", False)
            ):
                continue
            peer.send_text(payload)

    def broadcast_line(self, source: FakeFlashSession, payload: str) -> None:
        with self.lock:
            peers = [
                peer
                for peer in self.sessions_by_character.values()
                if peer is not source and peer.entered_game and peer.line_id == source.line_id
            ]
        for peer in peers:
            peer.send_text(payload)

    def broadcast_world(self, source: FakeFlashSession, payload: str) -> None:
        with self.lock:
            peers = [
                peer
                for peer in self.sessions_by_character.values()
                if peer is not source and peer.entered_game
            ]
        for peer in peers:
            peer.send_text(payload)

    @staticmethod
    def _monster_world_key(session: FakeFlashSession) -> tuple[Any, ...]:
        map_id = int(session.character.map_id)
        copy_id = int(session.copy_instance_id)
        if session.war_3v3_match_id > 0:
            return ("war3v3", int(session.war_3v3_match_id), map_id, copy_id)
        if session.war_battle_active:
            return ("war", int(session.war_battle_channel), map_id, copy_id)
        if session.chunin_active:
            return ("chunin", copy_id, map_id)
        return ("line", int(session.line_id), map_id, copy_id)

    def _bind_world_state_locked(self, session: FakeFlashSession) -> WorldMapState:
        key = self._monster_world_key(session)
        state = self.world_states.get(key)
        if state is None:
            state = WorldMapState(session.monsters, session.drops, session.chests)
            self._restore_boss_respawns_locked(session, state)
            self.world_states[key] = state
        session.monsters = state.monsters
        session.drops = state.drops
        session.chests = state.chests
        session.world_state = state
        return state

    def bind_world_state(self, session: FakeFlashSession) -> WorldMapState:
        """Attach a session to its persistent line/map/instance entity state."""
        with self.lock:
            return self._bind_world_state_locked(session)

    def monster_controller(
        self,
        session: FakeFlashSession,
    ) -> FakeFlashSession | None:
        """Return the one elected original-client AI driver for a map instance."""
        key = self._monster_world_key(session)
        with self.lock:
            candidates = [
                value
                for value in self.sessions_by_character.values()
                if (
                    value.entered_game
                    and not getattr(value, "server_simulated", False)
                    and not getattr(value, "_nya208_waiting_for_world_ready", False)
                    and self._monster_world_key(value) == key
                )
            ]
            if (
                session.entered_game
                and not getattr(session, "server_simulated", False)
                and not getattr(session, "_nya208_waiting_for_world_ready", False)
                and session not in candidates
            ):
                candidates.append(session)
            controller = self.monster_controllers.get(key)
            if controller not in candidates:
                controller = min(
                    candidates,
                    key=lambda value: int(value.character.character_id),
                    default=None,
                )
                if controller is None:
                    self.monster_controllers.pop(key, None)
                else:
                    self.monster_controllers[key] = controller
            return controller

    def claim_monster_control(self, session: FakeFlashSession) -> bool:
        return self.monster_controller(session) is session

    def monster_world_sessions(
        self,
        session: FakeFlashSession,
    ) -> list[FakeFlashSession]:
        """Return every live player in one authoritative monster-world instance."""
        key = self._monster_world_key(session)
        with self.lock:
            return [
                value
                for value in self.sessions_by_character.values()
                if value.entered_game and self._monster_world_key(value) == key
            ]

    def release_monster_control(
        self,
        session: FakeFlashSession,
    ) -> FakeFlashSession | None:
        """Release one world controller and return the elected online replacement."""
        key = self._monster_world_key(session)
        with self.lock:
            if self.monster_controllers.get(key) is not session:
                return None
            candidates = [
                value
                for value in self.sessions_by_character.values()
                if value is not session
                and value.entered_game
                and not getattr(value, "server_simulated", False)
                and self._monster_world_key(value) == key
            ]
            replacement = min(
                candidates,
                key=lambda value: int(value.character.character_id),
                default=None,
            )
            if replacement is None:
                self.monster_controllers.pop(key, None)
            else:
                self.monster_controllers[key] = replacement
            return replacement

    def allocate_drop_id(self, session: FakeFlashSession) -> int:
        key = (
            session.line_id,
            session.character.map_id,
            session.copy_instance_id,
        )
        with self.lock:
            value = self.next_drop_by_world.get(key, 3001)
            self.next_drop_by_world[key] = value + 1
            return value

    def party_for(self, character_id: int) -> PartyState | None:
        with self.lock:
            party_id = self.party_by_character.get(int(character_id))
            return self.parties.get(party_id) if party_id is not None else None

    def create_party(self, session: FakeFlashSession) -> PartyState:
        character_id = session.character.character_id
        with self.lock:
            existing = self.party_for(character_id)
            if existing is not None:
                return existing
            party = PartyState(
                party_id=self.next_party_id,
                leader_id=character_id,
                name=f"{session.character.name}的小队",
                member_ids=[character_id],
            )
            self.next_party_id += 1
            self.parties[party.party_id] = party
            self.party_by_character[character_id] = party.party_id
            return party

    def invite_to_party(
        self,
        source: FakeFlashSession,
        target: FakeFlashSession,
    ) -> PartyState | None:
        with self.lock:
            party = self.create_party(source)
            if len(party.member_ids) >= 6 or target.character.character_id in self.party_by_character:
                return None
            party.invitations.add(target.character.character_id)
            return party

    def accept_party_invitation(
        self,
        session: FakeFlashSession,
        party_id: int,
    ) -> PartyState | None:
        with self.lock:
            party = self.parties.get(int(party_id))
            character_id = session.character.character_id
            if (
                party is None
                or character_id not in party.invitations
                or len(party.member_ids) >= 6
                or character_id in self.party_by_character
            ):
                return None
            party.invitations.discard(character_id)
            party.member_ids.append(character_id)
            self.party_by_character[character_id] = party.party_id
            return party

    def party_sessions(self, party: PartyState) -> list[FakeFlashSession]:
        with self.lock:
            return [
                self.sessions_by_character[character_id]
                for character_id in party.member_ids
                if character_id in self.sessions_by_character
            ]

    def remove_from_party(
        self,
        character_id: int,
        disband: bool = False,
    ) -> tuple[PartyState | None, list[FakeFlashSession]]:
        with self.lock:
            party = self.party_for(character_id)
            if party is None:
                return None, []
            sessions = self.party_sessions(party)
            if disband or len(party.member_ids) <= 2:
                for member_id in party.member_ids:
                    self.party_by_character.pop(member_id, None)
                self.parties.pop(party.party_id, None)
                return party, sessions
            party.member_ids = [value for value in party.member_ids if value != character_id]
            self.party_by_character.pop(character_id, None)
            if party.leader_id == character_id:
                party.leader_id = party.member_ids[0]
            return party, sessions

    def invite_trade(self, source: FakeFlashSession, target: FakeFlashSession) -> bool:
        with self.lock:
            source_id = source.character.character_id
            target_id = target.character.character_id
            if source_id in self.trades_by_character or target_id in self.trades_by_character:
                return False
            self.trade_invites[target_id] = source_id
            return True

    def accept_trade(
        self,
        target: FakeFlashSession,
        inviter_id: int,
    ) -> tuple[TradeState, FakeFlashSession] | None:
        with self.lock:
            target_id = target.character.character_id
            if self.trade_invites.get(target_id) != int(inviter_id):
                return None
            inviter = self.sessions_by_character.get(int(inviter_id))
            if inviter is None:
                return None
            self.trade_invites.pop(target_id, None)
            trade = TradeState(
                first_id=inviter.character.character_id,
                second_id=target_id,
                offered_slots={inviter.character.character_id: {}, target_id: {}},
                offered_money={inviter.character.character_id: 0, target_id: 0},
                offered_cash_money={
                    inviter.character.character_id: 0,
                    target_id: 0,
                },
            )
            self.trades_by_character[trade.first_id] = trade
            self.trades_by_character[trade.second_id] = trade
            return trade, inviter

    def cancel_trade(self, character_id: int) -> tuple[TradeState, list[FakeFlashSession]] | None:
        with self.lock:
            trade = self.trades_by_character.get(int(character_id))
            if trade is None:
                return None
            sessions = [
                session
                for participant_id in (trade.first_id, trade.second_id)
                if (session := self.sessions_by_character.get(participant_id)) is not None
            ]
            self.trades_by_character.pop(trade.first_id, None)
            self.trades_by_character.pop(trade.second_id, None)
            return trade, sessions

    def stall_for(self, owner_id: int) -> StallState | None:
        with self.lock:
            return self.stalls.get(int(owner_id))

    @staticmethod
    def _stall_pet_from_dict(payload: dict[str, Any]) -> PetState:
        raw = dict(payload)
        raw_skills = raw.pop("skills", {})
        raw_equipment = raw.pop("equipment", {})
        allowed = set(PetState.__dataclass_fields__)
        pet = PetState(**{key: value for key, value in raw.items() if key in allowed})
        pet.skills = {
            int(key): SkillState(**value)
            for key, value in raw_skills.items()
            if isinstance(value, dict)
        }
        pet.equipment = {
            int(key): InventoryItem(**value)
            for key, value in raw_equipment.items()
            if isinstance(value, dict)
        }
        return pet

    def _load_stalls(self) -> dict[int, StallState]:
        try:
            payload = json.loads(self.stall_path.read_text(encoding="utf-8"))
        except (OSError, ValueError, json.JSONDecodeError):
            return {}
        stalls: dict[int, StallState] = {}
        for raw_owner_id, raw_stall in payload.items() if isinstance(payload, dict) else ():
            if not isinstance(raw_stall, dict):
                continue
            listings: dict[int, StallListing] = {}
            for raw_uid, raw_listing in (raw_stall.get("listings") or {}).items():
                if not isinstance(raw_listing, dict):
                    continue
                values = dict(raw_listing)
                raw_item = values.pop("item", None)
                raw_pet = values.pop("pet", None)
                try:
                    listing = StallListing(
                        **{
                            key: value
                            for key, value in values.items()
                            if key in StallListing.__dataclass_fields__
                        }
                    )
                    if isinstance(raw_item, dict):
                        listing.item = InventoryItem(**raw_item)
                    if isinstance(raw_pet, dict):
                        listing.pet = self._stall_pet_from_dict(raw_pet)
                except (TypeError, ValueError):
                    continue
                listings[int(raw_uid)] = listing
            owner_id = int(raw_owner_id)
            stalls[owner_id] = StallState(
                owner_id=owner_id,
                owner_name=str(raw_stall.get("owner_name") or "无名忍者"),
                name=str(raw_stall.get("name") or "玩家摊位"),
                listings=listings,
                logs=[str(value) for value in raw_stall.get("logs") or []][-30:],
            )
        return stalls

    def persist_stalls(self) -> None:
        """Atomically persist escrow so a server restart cannot lose listed assets."""
        with self.lock:
            payload = {
                str(owner_id): asdict(stall)
                for owner_id, stall in self.stalls.items()
            }
            self.stall_path.parent.mkdir(parents=True, exist_ok=True)
            temporary = self.stall_path.with_name(
                f".{self.stall_path.name}.{os.getpid()}.{secrets.token_hex(4)}.tmp"
            )
            try:
                temporary.write_text(
                    json.dumps(payload, ensure_ascii=False, indent=2),
                    encoding="utf-8",
                )
                temporary.replace(self.stall_path)
            finally:
                temporary.unlink(missing_ok=True)

    @staticmethod
    def _load_inventory_item(payload: Any) -> InventoryItem | None:
        if not isinstance(payload, dict):
            return None
        try:
            return InventoryItem(
                **{
                    key: value
                    for key, value in payload.items()
                    if key in InventoryItem.__dataclass_fields__
                }
            )
        except (TypeError, ValueError):
            return None

    def _load_auctions(self) -> dict[int, AuctionLot]:
        try:
            payload = json.loads(self.auction_path.read_text(encoding="utf-8"))
        except (OSError, ValueError, json.JSONDecodeError):
            return {}
        lots: dict[int, AuctionLot] = {}
        rows = payload.get("lots", {}) if isinstance(payload, dict) else {}
        for raw_id, raw_lot in rows.items() if isinstance(rows, dict) else ():
            if not isinstance(raw_lot, dict):
                continue
            item = self._load_inventory_item(raw_lot.get("item"))
            if item is None:
                continue
            values = dict(raw_lot)
            values.pop("item", None)
            try:
                lot = AuctionLot(
                    item=item,
                    **{
                        key: value
                        for key, value in values.items()
                        if key in AuctionLot.__dataclass_fields__
                    },
                )
            except (TypeError, ValueError):
                continue
            lots[int(raw_id)] = lot
        return lots

    def persist_auctions(self) -> None:
        with self.lock:
            self._persist_shared_payload(
                self.auction_path,
                {"version": 1, "lots": {str(key): asdict(value) for key, value in self.auction_lots.items()}},
            )

    def _load_money_sell_listings(self) -> dict[int, MoneySellListing]:
        try:
            payload = json.loads(self.money_sell_path.read_text(encoding="utf-8"))
        except (OSError, ValueError, json.JSONDecodeError):
            return {}
        rows = payload.get("listings", {}) if isinstance(payload, dict) else {}
        result: dict[int, MoneySellListing] = {}
        for raw_sn, raw_listing in rows.items() if isinstance(rows, dict) else ():
            if not isinstance(raw_listing, dict):
                continue
            try:
                listing = MoneySellListing(
                    **{
                        key: value
                        for key, value in raw_listing.items()
                        if key in MoneySellListing.__dataclass_fields__
                    }
                )
            except (TypeError, ValueError):
                continue
            if listing.sn > 0 and listing.quantity > 0 and listing.value > 0:
                result[int(raw_sn)] = listing
        return result

    def persist_money_sell_listings(self) -> None:
        with self.lock:
            self._persist_shared_payload(
                self.money_sell_path,
                {
                    "version": 1,
                    "listings": {
                        str(key): asdict(value)
                        for key, value in self.money_sell_listings.items()
                    },
                },
            )

    def _load_bounties(self) -> dict[int, BountyEntry]:
        try:
            payload = json.loads(self.bounty_path.read_text(encoding="utf-8"))
        except (OSError, ValueError, json.JSONDecodeError):
            return {}
        bounties: dict[int, BountyEntry] = {}
        rows = payload.get("bounties", {}) if isinstance(payload, dict) else {}
        for raw_id, raw_entry in rows.items() if isinstance(rows, dict) else ():
            if not isinstance(raw_entry, dict):
                continue
            values = dict(raw_entry)
            raw_items = values.pop("reward_items", [])
            items = [
                item
                for raw_item in raw_items if isinstance(raw_items, list)
                if (item := self._load_inventory_item(raw_item)) is not None
            ]
            try:
                entry = BountyEntry(
                    reward_items=items,
                    **{
                        key: value
                        for key, value in values.items()
                        if key in BountyEntry.__dataclass_fields__
                    },
                )
            except (TypeError, ValueError):
                continue
            bounties[int(raw_id)] = entry
        return bounties

    def persist_bounties(self) -> None:
        with self.lock:
            self._persist_shared_payload(
                self.bounty_path,
                {"version": 1, "bounties": {str(key): asdict(value) for key, value in self.bounties.items()}},
            )

    def _load_artifact_war(self) -> ArtifactWarState:
        try:
            payload = json.loads(self.artifact_war_path.read_text(encoding="utf-8"))
        except (OSError, ValueError, json.JSONDecodeError):
            return ArtifactWarState()
        raw = payload.get("state", payload) if isinstance(payload, dict) else {}
        try:
            return ArtifactWarState(
                **{
                    key: value
                    for key, value in raw.items()
                    if key in ArtifactWarState.__dataclass_fields__
                }
            )
        except (TypeError, ValueError):
            return ArtifactWarState()

    def persist_artifact_war(self) -> None:
        with self.lock:
            self._persist_shared_payload(
                self.artifact_war_path,
                {"version": 1, "state": asdict(self.artifact_war)},
            )

    def _load_war_relics(self) -> dict[int, WarRelicState]:
        try:
            payload = json.loads(self.war_relic_path.read_text(encoding="utf-8"))
        except (OSError, ValueError, json.JSONDecodeError):
            payload = {}
        rows = payload.get("relics", {}) if isinstance(payload, dict) else {}
        relics: dict[int, WarRelicState] = {}
        for item_id in (17_200_001, 17_200_002, 17_200_003, 17_200_004):
            raw = rows.get(str(item_id), {}) if isinstance(rows, dict) else {}
            try:
                relics[item_id] = WarRelicState(
                    item_id=item_id,
                    **{
                        key: value
                        for key, value in raw.items()
                        if key in WarRelicState.__dataclass_fields__ and key != "item_id"
                    },
                )
            except (TypeError, ValueError):
                relics[item_id] = WarRelicState(item_id=item_id)
        return relics

    def persist_war_relics(self) -> None:
        with self.lock:
            self._persist_shared_payload(
                self.war_relic_path,
                {"version": 1, "relics": {str(key): asdict(value) for key, value in self.war_relics.items()}},
            )

    def _load_chunin(self) -> ChuninTournamentState:
        try:
            payload = json.loads(self.chunin_path.read_text(encoding="utf-8"))
        except (OSError, ValueError, json.JSONDecodeError):
            return ChuninTournamentState()
        raw = payload.get("state", payload) if isinstance(payload, dict) else {}
        entries: dict[int, ChuninEntry] = {}
        for raw_id, raw_entry in (raw.get("entries") or {}).items() if isinstance(raw, dict) else ():
            if not isinstance(raw_entry, dict):
                continue
            try:
                entry = ChuninEntry(
                    **{
                        key: value
                        for key, value in raw_entry.items()
                        if key in ChuninEntry.__dataclass_fields__
                    }
                )
            except (TypeError, ValueError):
                continue
            entries[int(raw_id)] = entry
        return ChuninTournamentState(
            season_key=str(raw.get("season_key") or "") if isinstance(raw, dict) else "",
            entries=entries,
            finished_round=max(0, int(raw.get("finished_round") or 0)) if isinstance(raw, dict) else 0,
            champion_id=max(0, int(raw.get("champion_id") or 0)) if isinstance(raw, dict) else 0,
            champion_name=str(raw.get("champion_name") or "") if isinstance(raw, dict) else "",
        )

    def persist_chunin(self) -> None:
        with self.lock:
            self._persist_shared_payload(
                self.chunin_path,
                {"version": 1, "state": asdict(self.chunin)},
            )

    def _load_boss_respawns(self) -> dict[str, dict[str, int | float]]:
        """Load absolute wild-Boss respawn deadlines that survive process restarts."""
        try:
            payload = json.loads(self.boss_state_path.read_text(encoding="utf-8"))
        except (OSError, ValueError, json.JSONDecodeError):
            return {}
        rows = payload.get("bosses", {}) if isinstance(payload, dict) else {}
        result: dict[str, dict[str, int | float]] = {}
        for raw_key, raw_state in rows.items() if isinstance(rows, dict) else ():
            if not isinstance(raw_state, dict):
                continue
            try:
                template_id = int(raw_state.get("template_id") or 0)
                respawn_at_epoch = float(raw_state.get("respawn_at_epoch") or 0)
            except (TypeError, ValueError):
                continue
            if (
                template_id <= 0
                or respawn_at_epoch <= 0
                or not math.isfinite(respawn_at_epoch)
            ):
                continue
            result[str(raw_key)] = {
                "template_id": template_id,
                "respawn_at_epoch": respawn_at_epoch,
            }
        return result

    @staticmethod
    def _boss_respawn_key(
        session: FakeFlashSession,
        monster: MonsterState,
    ) -> str:
        return ":".join(
            str(value)
            for value in (
                int(session.line_id),
                int(session.character.map_id),
                int(monster.template_id),
                int(monster.spawn_x),
                int(monster.spawn_y),
            )
        )

    @staticmethod
    def _is_persistent_wild_boss(
        session: FakeFlashSession,
        monster: MonsterState,
    ) -> bool:
        if (
            int(session.copy_instance_id) != 0
            or session.active_copy_id is not None
            or session.active_hero_copy_id is not None
        ):
            return False
        return GAME_DATA_CATALOG.get_monster_definition(monster.template_id).boss

    def _persist_boss_respawns_locked(self) -> None:
        self._persist_shared_payload(
            self.boss_state_path,
            {"version": 1, "bosses": self.boss_respawns},
        )

    def persist_boss_respawn(
        self,
        session: FakeFlashSession,
        monster: MonsterState,
        delay_seconds: float,
        *,
        respawn_at_epoch: float | None = None,
    ) -> None:
        """Persist wild-Boss cooldowns using restart-safe wall-clock time."""
        if not self._is_persistent_wild_boss(session, monster):
            return
        deadline = respawn_at_epoch
        if deadline is None and delay_seconds > 0 and math.isfinite(delay_seconds):
            deadline = time.time() + float(delay_seconds)
        if deadline is None or deadline <= time.time() or not math.isfinite(deadline):
            return
        key = self._boss_respawn_key(session, monster)
        with self.lock:
            self.boss_respawns[key] = {
                "template_id": int(monster.template_id),
                "respawn_at_epoch": float(deadline),
            }
            self._persist_boss_respawns_locked()

    def clear_boss_respawn(
        self,
        session: FakeFlashSession,
        monster: MonsterState,
    ) -> None:
        if not self._is_persistent_wild_boss(session, monster):
            return
        key = self._boss_respawn_key(session, monster)
        with self.lock:
            if self.boss_respawns.pop(key, None) is not None:
                self._persist_boss_respawns_locked()

    def _restore_boss_respawns_locked(
        self,
        session: FakeFlashSession,
        state: WorldMapState,
    ) -> None:
        """Reapply unexpired wild-Boss deaths to a newly created map state."""
        if int(session.copy_instance_id) != 0:
            return
        now_epoch = time.time()
        now_monotonic = time.monotonic()
        changed = False
        for monster in state.monsters.values():
            if not self._is_persistent_wild_boss(session, monster):
                continue
            changed = self._restore_boss_respawn_locked(
                session,
                monster,
                now_epoch=now_epoch,
                now_monotonic=now_monotonic,
            ) or changed
        if changed:
            self._persist_boss_respawns_locked()

    def _restore_boss_respawn_locked(
        self,
        session: FakeFlashSession,
        monster: MonsterState,
        *,
        now_epoch: float,
        now_monotonic: float,
    ) -> bool:
        key = self._boss_respawn_key(session, monster)
        persisted = self.boss_respawns.get(key)
        if persisted is None:
            return False
        if int(persisted.get("template_id") or 0) != int(monster.template_id):
            self.boss_respawns.pop(key, None)
            return True
        deadline = float(persisted.get("respawn_at_epoch") or 0)
        if deadline <= now_epoch:
            self.boss_respawns.pop(key, None)
            return True
        monster.hp = 0
        monster.respawn_at = now_monotonic + (deadline - now_epoch)
        monster.target_character_id = 0
        return False

    def restore_boss_respawn(
        self,
        session: FakeFlashSession,
        monster: MonsterState,
    ) -> None:
        """Reapply one persisted death after a scheduled round rebuilds its actor."""
        if not self._is_persistent_wild_boss(session, monster):
            return
        with self.lock:
            changed = self._restore_boss_respawn_locked(
                session,
                monster,
                now_epoch=time.time(),
                now_monotonic=time.monotonic(),
            )
            if changed:
                self._persist_boss_respawns_locked()

    @staticmethod
    def _persist_shared_payload(path: Path, payload: dict[str, Any]) -> None:
        path.parent.mkdir(parents=True, exist_ok=True)
        temporary = path.with_name(
            f".{path.name}.{os.getpid()}.{threading.get_ident()}."
            f"{secrets.token_hex(4)}.tmp"
        )
        try:
            temporary.write_text(
                json.dumps(payload, ensure_ascii=False, indent=2),
                encoding="utf-8",
            )
            temporary.replace(path)
        finally:
            temporary.unlink(missing_ok=True)

    def next_auction_id(self) -> int:
        with self.lock:
            value = self.next_auction_lot_id
            self.next_auction_lot_id += 1
            return value

    def next_bounty_uid(self) -> int:
        with self.lock:
            value = self.next_bounty_id
            self.next_bounty_id += 1
            return value

    def open_stall(self, session: FakeFlashSession) -> StallState:
        owner_id = session.character.character_id
        changed = False
        with self.lock:
            stall = self.stalls.get(owner_id)
            if stall is None:
                stall = StallState(
                    owner_id=owner_id,
                    owner_name=session.character.name,
                    name=f"{session.character.name}的摊位",
                )
                self.stalls[owner_id] = stall
                changed = True
            else:
                if stall.owner_name != session.character.name:
                    stall.owner_name = session.character.name
                    changed = True
        if changed:
            self.persist_stalls()
        return stall

    def next_stall_uid(self) -> int:
        with self.lock:
            value = self.next_stall_listing_id
            self.next_stall_listing_id += 1
            return value

    def allocate_copy_instance(self) -> int:
        """Return an instance key that isolates one party copy from other parties."""
        with self.lock:
            value = self.next_copy_instance_id
            self.next_copy_instance_id += 1
            return value

    def allocate_transient_player_id(self) -> int:
        """Return a positive actor id that is never registered as an account."""
        with self.lock:
            value = self.next_transient_player_id
            self.next_transient_player_id += 1
            if self.next_transient_player_id >= 2_000_000_000:
                self.next_transient_player_id = 1_700_000_000
            return value


    def _load_redemption_codes(self) -> dict[str, dict[str, Any]]:
        try:
            payload = json.loads(self.redemption_codes_path.read_text(encoding="utf-8"))
        except (OSError, ValueError, json.JSONDecodeError):
            return {}
        codes = payload.get("codes") if isinstance(payload, dict) else None
        return codes if isinstance(codes, dict) else {}

    def persist_redemption_codes(self) -> None:
        with self.lock:
            self._persist_shared_payload(
                self.redemption_codes_path,
                {"version": 1, "codes": self.redemption_codes},
            )

    def _load_news(self) -> dict[str, Any]:
        try:
            payload = json.loads(self.news_path.read_text(encoding="utf-8"))
        except (OSError, ValueError, json.JSONDecodeError):
            payload = {}
        if isinstance(payload, dict) and payload.get("version") == 1:
            return {
                "title": str(payload.get("title") or ""),
                "subtitle": str(payload.get("subtitle") or ""),
                "entries": [str(value) for value in (payload.get("entries") or [])],
            }
        return _default_news()

    def persist_news(self) -> None:
        with self.lock:
            self._persist_shared_payload(
                self.news_path,
                {"version": 1, **self.news},
            )

    def _load_activity_overrides(self) -> dict[str, Any]:
        try:
            payload = json.loads(
                self.activity_overrides_path.read_text(encoding="utf-8")
            )
        except (OSError, ValueError, json.JSONDecodeError):
            return {}
        if isinstance(payload, dict) and payload.get("version") == 1:
            overrides = payload.get("overrides")
            return overrides if isinstance(overrides, dict) else {}
        return {}

    def persist_activity_overrides(self) -> None:
        with self.lock:
            self._persist_shared_payload(
                self.activity_overrides_path,
                {"version": 1, "overrides": self.activity_overrides},
            )


