    def __init__(
        self,
        conn: socket.socket,
        address: tuple[str, int],
        lan_ip: str,
        store: SinglePlayerStore | None = None,
        hub: MultiplayerHub | None = None,
    ):
        """Create one connection with dispatch, stream, map-object, and drop state."""
        self.conn = conn
        self.address = address
        self.lan_ip = lan_ip
        self.store = store or DEFAULT_STORE
        self.hub = hub
        self.accounts = hub.accounts if hub is not None else ACCOUNT_SERVICE
        self.account_id = 0
        self.account_name = ""
        local_port = self.conn.getsockname()[1]
        self.native_flash_direct = (
            NATIVE_LOGIN_PORT != SERVER_PORT
            and local_port in {NATIVE_LOGIN_PORT, CHANNEL_PORT}
        )
        self.line_id = 1
        self.selected_character_id = self.store.state.character.character_id
        self.kicked = False
        self._normalize_transform_card_attributes()
        self._normalize_transform_card_collection()
        self._normalize_item_binding()
        self._normalize_ling_qi_attributes()
        self._normalize_equipment_inlays()
        self._normalize_badge_attributes()
        self._normalize_special_equipment_strength()
        self._normalize_kun_chong_attributes()
        self._normalize_equipment_forge_eligibility()
        if self.character.zq < 0 or self.character.zq > MAX_ZQ:
            with self.store.lock:
                self.character.zq = max(0, min(MAX_ZQ, self.character.zq))
                self.store.save()
        self.entered_game = False
        self.sent_bootstrap = False
        self.pending_equipment_pickups: set[int] = set()
        self.wire_mode: str | None = None
        self.server_sequence = 1
        self.current_map = GAME_DATA_CATALOG.get_map(self.character.map_id)
        if self.current_map is None:
            self._place_character_at_default_spawn()
        else:
            self._repair_mismatched_default_position()
        self._recover_arena_location()
        self.x = self.character.x
        self.y = self.character.y
        self.direction = 0
        self.player_movement_flag = PLAYER_MOVEMENT_FLAG_GROUNDED
        self.player_movement_action = PLAYER_MOVEMENT_ACTION_STAND
        self.receive_buffer = bytearray()
        self.send_lock = threading.Lock()
        self._transport_closed = False
        self.combat_lock = threading.RLock()
        self.npcs: dict[int, NpcState] = {}
        self.monsters: dict[int, MonsterState] = {}
        self.active_npc_object_id: int | None = None
        self.active_quest_dialog_id: int | None = None
        self.active_quest_dialog_action: str | None = None
        self.active_quest_dialog_lines: tuple[str, ...] = ()
        self.active_quest_dialog_index = 0
        self.active_cash_category_id = int(CashShopCategory.COMMON)
        self.drops: dict[int, DropState] = {}
        self.pending_drop_publications: deque[int] = deque()
        self.drop_publication_burst_until = 0.0
        self.next_drop_object_id = 3001
        self.random = random.Random(self.character.character_id)
        random_name_count = len(self.RANDOM_NAME_SURNAMES) * len(
            self.RANDOM_NAME_GIVEN_NAMES
        )
        self._generated_name_cursor = (
            time.time_ns() ^ id(self) ^ self.address[1]
        ) % random_name_count
        self._last_generated_character_name = ""
        self.healing_active = False
        self.healing_partner_id = 0
        self.second_level_password_unlocked = False
        self.hang_active = False
        self.pending_copy_id: int | None = None
        self.pending_copy_enter_at = 0.0
        self.active_copy_id: int | None = None
        self.copy_instance_id = 0
        self.active_copy_return_map_id: int | None = None
        self.active_copy_return_position: tuple[int, int] | None = None
        self.active_copy_started_at = 0.0
        self.active_copy_kills = 0
        self.active_copy_target_kills = 0
        self.active_copy_finished = False
        self.active_copy_waves: tuple[tuple[int, ...], ...] = ()
        self.active_copy_wave_index = -1
        self.active_copy_failed = False
        self.active_copy_miss_count = 0
        self.active_copy_protect_hp = 0
        self.active_copy_deadline = 0.0
        # Keep a completed instance alive while its drops are being collected.
        self.active_copy_exit_at = 0.0
        self.active_copy_affinity = -1
        self.active_copy_last_objective_tick = 0.0
        self.active_copy_last_affinity_notice = 0.0
        self.active_copy_next_wave_at = 0.0
        self.xiulian_selected_mob_id = 5_400_099
        self.xiulian_stay_still = True
        self.xiulian_has_summoned = False
        self.xiulian_running = False
        self.xiulian_started_at = 0.0
        self.xiulian_duration = 60
        self.xiulian_total_damage = 0
        self.xiulian_max_hit = 0
        self.xiulian_character_damage = 0
        self.xiulian_an_qi_damage = 0
        self.xiulian_reflect_damage = 0
        self.xiulian_last_push_at = 0.0
        self.chests: dict[int, ChestState] = {}
        self.active_hero_copy_id: int | None = None
        self.active_hero_boss_id = 0
        self.active_hero_return_map_id: int | None = None
        self.active_hero_return_position: tuple[int, int] | None = None
