    @staticmethod
    def _activity_day_key(now: time.struct_time | None = None) -> str:
        """Return the local-calendar key used by the original daily task cycle."""
        return time.strftime("%Y-%m-%d", now or time.localtime())

    def _refresh_daily_activity(self) -> None:
        """Reset daily counters atomically without counting disconnected time."""
        progression = self.store.state.progression
        day_key = self._activity_day_key()
        now = int(time.time())
        changed = False
        with self.store.lock:
            if progression.activity_day_key != day_key:
                progression.activity_day_key = day_key
                progression.activity_counts = [0] * 15
                progression.activity_score = 0
                progression.activity_claimed_level = -1
                progression.activity_online_seconds = 0
                changed = True
            if progression.activity_online_updated_at != now:
                progression.activity_online_updated_at = now
                changed = True
            if changed:
                self.store.save()

    def _advance_activity(self, slot: int, amount: int = 1) -> None:
        """Advance one authored daily task and emit the native incremental update."""
        self._refresh_daily_activity()
        tasks = GAME_DATA_CATALOG.huoyuedu_tasks()
        if not 0 <= slot < len(tasks) or amount <= 0:
            return
        progression = self.store.state.progression
        required = int(tasks[slot]["requiredCount"])
        old_count = progression.activity_counts[slot]
        new_count = min(required, old_count + amount)
        added = new_count - old_count
        if added <= 0:
            return
        # The original panel totals 150 points across 15 independently completed tasks.
        added_score = 10 if old_count < required <= new_count else 0
        with self.store.lock:
            progression.activity_counts[slot] = new_count
            progression.activity_score = min(
                150, progression.activity_score + added_score
            )
            self.store.save()
        if self.entered_game:
            self.send_text(
                f"{op(ServerOpcode.HUO_YUE)}:2:{slot + 1}:"
                f"{new_count}:{added_score}"
            )

    def _tick_activity_online(self, now: float) -> None:
        """Accumulate connected playtime and complete the authored three-hour task."""
        self._refresh_daily_activity()
        elapsed = max(0, int(now - self.last_activity_online_tick))
        if elapsed <= 0:
            return
        self.last_activity_online_tick = now
        progression = self.store.state.progression
        with self.store.lock:
            progression.activity_online_seconds = min(
                3 * 60 * 60,
                progression.activity_online_seconds + elapsed,
            )
            progression.activity_online_updated_at = int(time.time())
            self.store.save()
        if progression.activity_online_seconds >= 3 * 60 * 60:
            self._advance_activity(0)

    def _claim_next_activity_reward(self) -> None:
        """Grant the next eligible GameData tier exactly once."""
        self._refresh_daily_activity()
        progression = self.store.state.progression
        rewards = GAME_DATA_CATALOG.huoyuedu_rewards()
        next_level = progression.activity_claimed_level + 1
        if not 0 <= next_level < len(rewards):
            self.send_text(
                f"{op(ServerOpcode.HUO_YUE)}:1:"
                f"{progression.activity_claimed_level}"
            )
            return
        reward = rewards[next_level]
        if progression.activity_score < reward["requiredScore"]:
            self.send_text(
                f"{op(ServerOpcode.HUO_YUE)}:1:"
                f"{progression.activity_claimed_level}"
            )
            return
        items = [
            (reward["itemId1"], reward["count1"]),
            (reward["itemId2"], reward["count2"]),
        ]
        items = [(item_id, count) for item_id, count in items if item_id > 0 and count > 0]
        if not self._has_inventory_capacity(items):
            self._send_system_chat("背包空间不足，活跃度奖励暂未领取。")
            return
        gained_items: list[tuple[InventoryItem, bool]] = []
        experience = reward["experienceRate"] * self.character.level ** 3 // 100
        with self.store.lock:
            for item_id, count in items:
                gained_items.append(self._add_inventory_item(item_id, count))
            self.store.state.coupon_money += reward["coupon"]
            progression.activity_claimed_level = next_level
            self.store.save()
        for item, created in gained_items:
            if created:
                self._send_inventory_add(item, from_drop=0)
            else:
                self._send_inventory_update(item, from_drop=0)
        if experience > 0:
            self._grant_experience(experience)
        self._send_stats({StatType.CASH_BIND: self.store.state.coupon_money})
        self.send_text(f"{op(ServerOpcode.HUO_YUE)}:1:{next_level}")

    def handle_huo_yue(self, read_str: str) -> None:
        """Serve and settle the complete GameData-authored daily activity loop."""
        fields = self._request_fields(read_str, ClientOpcode.HUO_YUE)
        action = self._safe_int(fields[0], -1) if fields else -1
        self._refresh_daily_activity()
        progression = self.store.state.progression
        if action == 0:
            self._send_activity_panel()
            return
        if action == 1:
            self._claim_next_activity_reward()

    def _send_activity_panel(self) -> None:
        """Push the complete daily activity snapshot expected by HuoyueduProcessor."""
        self._refresh_daily_activity()
        progression = self.store.state.progression
        counts = ":".join(
            str(max(0, value)) for value in progression.activity_counts
        )
        self.send_text(
            f"{op(ServerOpcode.HUO_YUE)}:0:15:{counts}:"
            f"{progression.activity_claimed_level}:"
            f"{progression.activity_score}"
        )

    @staticmethod
    def _card_node_key(level: int, node_id: int) -> str:
        """Return the stable save key used by one card-album node."""
        return f"{level}:{node_id}"

    def _card_node_counts(self, definition: CardNodeDefinition) -> dict[int, int]:
        """Return submitted counts clamped to the current GameData requirements."""
        saved = self.store.state.card_submissions.get(
            self._card_node_key(definition.level, definition.node_id), {}
        )
        return {
            requirement.item_id: min(
                requirement.count,
                max(0, int(saved.get(requirement.item_id, 0))),
            )
            for requirement in definition.items
        }

    def _card_node_finished(self, definition: CardNodeDefinition) -> bool:
        """Return whether every authored card quantity has been submitted."""
        counts = self._card_node_counts(definition)
        return all(
            counts[requirement.item_id] >= requirement.count
            for requirement in definition.items
        )

    def _send_card_level_info(self, level: int) -> None:
        """Send action 0 in the field order decoded by CardProcessor."""
        rows: list[str] = []
        for node_id in range(100):
            definition = GAME_DATA_CATALOG.get_card_node(level, node_id)
            if definition is None:
                continue
            rows.append(f"{node_id}&{1 if self._card_node_finished(definition) else 0}")
        self.send_text(
            f"{op(ServerOpcode.CARD_ACTION)}:0:{level}:{'@'.join(rows) or '-'}"
        )

    def _send_card_node_info(self, definition: CardNodeDefinition) -> None:
        """Send action 1 with persistent submitted counts for one node."""
        node_key = self._card_node_key(definition.level, definition.node_id)
        counts = self._card_node_counts(definition)
        rows: list[str] = []
        for requirement in definition.items:
            rows.append(f"{requirement.item_id}&{counts[requirement.item_id]}")
        self.send_text(
            f"{op(ServerOpcode.CARD_ACTION)}:1:{definition.level}:{definition.node_id}:"
            f"{1 if self._card_node_finished(definition) else 0}:"
            f"{1 if node_key in self.store.state.card_claimed_nodes else 0}:"
            f"{'@'.join(rows) or '-'}"
        )

    def handle_card_action(self, read_str: str) -> None:
        """Run the original card-album query, partial submit, and AP claim loop."""
        fields = self._request_fields(read_str, ClientOpcode.CARD_ACTION)
        action = self._safe_int(fields[0], -1) if fields else -1
        level = self._safe_int(fields[1], -1) if len(fields) > 1 else -1
        if action == 0:
            if level in GAME_DATA_CATALOG.card_levels:
                self._send_card_level_info(level)
            return
        node_id = self._safe_int(fields[2], -1) if len(fields) > 2 else -1
        definition = GAME_DATA_CATALOG.get_card_node(level, node_id)
        if definition is None:
            return
        if action == 1:
            self._send_card_node_info(definition)
            return
        if action == 2:
            changes: list[tuple[InventoryItem, bool]] = []
            node_key = self._card_node_key(level, node_id)
            with self.store.lock:
                submitted = self.store.state.card_submissions.setdefault(node_key, {})
                for requirement in definition.items:
                    current = min(
                        requirement.count,
                        max(0, int(submitted.get(requirement.item_id, 0))),
                    )
                    needed = requirement.count - current
                    consumed = min(
                        needed,
                        self._inventory_item_quantity(requirement.item_id),
                    )
                    if consumed <= 0:
                        continue
                    changes.extend(
                        self._consume_inventory_quantity(requirement.item_id, consumed)
                    )
                    submitted[requirement.item_id] = current + consumed
                if changes:
                    self.store.save()
            for item, removed in changes:
                if removed:
                    self._send_inventory_clear(item.slot, InventoryType.BAG)
                else:
                    self._send_inventory_update(item, from_drop=0)
            self._send_card_node_info(definition)
            return
        if action == 3:
            node_key = self._card_node_key(level, node_id)
            if (
                self._card_node_finished(definition)
                and node_key not in self.store.state.card_claimed_nodes
            ):
                with self.store.lock:
                    self.store.state.card_claimed_nodes.append(node_key)
                    self.character.remaining_ap += definition.gain_ap
                    self.store.save()
                self._send_stats({StatType.AVAILABLE_AP: self.character.remaining_ap})
            self._send_card_node_info(definition)

    def _send_legacy_hokage_collection_info(self) -> None:
        """Send both authored catalogs and the cards currently stored in the album."""
        role_catalog = GAME_DATA_CATALOG.permanent_transform_card_ids
        pet_catalog = GAME_DATA_CATALOG.permanent_pet_transform_card_ids
        stored_ids = set(self.store.state.transform_card_storage)
        role_collected = sorted(
            item_id for item_id in stored_ids if item_id in set(role_catalog)
        )
        pet_collected = sorted(
            item_id for item_id in stored_ids if item_id in set(pet_catalog)
        )
        body = bytearray(struct.pack("<B", 0))
        for values in (role_catalog, pet_catalog, role_collected, pet_collected):
            body.extend(struct.pack("<i", len(values)))
            for value in values:
                body.extend(struct.pack("<i", int(value)))
        body.extend(struct.pack("<3i", len(role_collected), len(pet_collected), len(stored_ids)))
        self.send_original_packet(ServerOpcode.HOKAGE_COLLECTION, bytes(body))

    def _handle_legacy_hokage_collection(self, read_str: str) -> None:
        """Store and restore complete transform-card instances through the native album."""
        fields = self._request_fields(read_str, ClientOpcode.HOKAGE_COLLECTION)
        action = self._safe_int(fields[0], -1) if fields else -1
        if action == 0:
            self._send_hokage_collection_info()
            return
        if action not in (1, 2, 6) or len(fields) < 3:
            return
        item_id = self._safe_int(fields[1], 0)
        category = self._safe_int(fields[2], -1)
        catalog = (
            set(GAME_DATA_CATALOG.permanent_pet_transform_card_ids)
            if category == 1
            else set(GAME_DATA_CATALOG.permanent_transform_card_ids)
        )
        if item_id not in catalog:
            return
        if action == 1:
            if item_id in self.store.state.transform_card_storage:
                self._send_hokage_collection_info()
                return
            source = next(
                (
                    item
                    for item in self.store.state.inventory.values()
                    if item.slot > 0 and item.item_id == item_id and item.quantity > 0
                ),
                None,
            )
            if source is None:
                self._send_system_chat("背包中没有这张变身卡。")
                return
            stored = replace(source, slot=0, quantity=1)
            source.quantity -= 1
            removed = source.quantity == 0
            with self.store.lock:
                if removed:
                    del self.store.state.inventory[source.slot]
                self.store.state.transform_card_storage[item_id] = stored
                if item_id not in self.store.state.transform_card_collection:
                    self.store.state.transform_card_collection.append(item_id)
                    self.store.state.transform_card_collection.sort()
                self.store.save()
            if removed:
                self._send_inventory_clear(source.slot, InventoryType.BAG)
            else:
                self._send_inventory_update(source, from_drop=0)
            self._send_hokage_collection_info()
            return
        if action == 6:
            self._switch_collection_transform_card(item_id, category)
            return
        stored = self.store.state.transform_card_storage.get(item_id)
        if stored is None:
            self._send_hokage_collection_info()
            return
        slot = next(
            (
                value
                for value in range(1, self.store.state.bag_capacity + 1)
                if value not in self.store.state.inventory
            ),
            0,
        )
        if slot == 0:
            self._send_system_chat("背包空间不足，无法取出变身卡。")
            return
        restored = replace(stored, slot=slot)
        with self.store.lock:
            self.store.state.inventory[slot] = restored
            del self.store.state.transform_card_storage[item_id]
            self.store.save()
        self._send_inventory_add(restored, from_drop=0)
        self._send_hokage_collection_info()

    def _hokage_collection_charm(self) -> tuple[int, int, int]:
        """Calculate authoritative role, pet, and total charm from lifetime collection."""
        collected = set(self.store.state.transform_card_collection)
        role_charm = sum(
            GAME_DATA_CATALOG.get_collection_charm(item_id)
            for item_id in GAME_DATA_CATALOG.permanent_transform_card_ids
            if item_id in collected
        )
        pet_charm = sum(
            GAME_DATA_CATALOG.get_collection_charm(item_id)
            for item_id in GAME_DATA_CATALOG.permanent_pet_transform_card_ids
            if item_id in collected
        )
        return role_charm, pet_charm, role_charm + pet_charm

    def _send_hokage_collection_info(self) -> None:
        """Send current album occupancy while preserving lifetime charm progress."""
        stored_ids = set(self.store.state.transform_card_storage)
        role_catalog = GAME_DATA_CATALOG.permanent_transform_card_ids
        pet_catalog = GAME_DATA_CATALOG.permanent_pet_transform_card_ids
        role_collected = tuple(
            item_id for item_id in role_catalog if item_id in stored_ids
        )
        pet_collected = tuple(
            item_id for item_id in pet_catalog if item_id in stored_ids
        )
        role_charm, pet_charm, total_charm = self._hokage_collection_charm()
        body = bytearray(struct.pack("<B", 0))
        for values in (
            role_catalog,
            pet_catalog,
            role_collected,
            pet_collected,
        ):
            body.extend(struct.pack("<i", len(values)))
            for value in values:
                body.extend(struct.pack("<i", int(value)))
        body.extend(struct.pack("<3i", role_charm, pet_charm, total_charm))
        self.send_original_packet(ServerOpcode.HOKAGE_COLLECTION, bytes(body))

    def _send_hokage_charm_info(self) -> None:
        """Send captured charm rewards, neutral Simplified Chinese colors, and selections."""
        role_charm, pet_charm, total_charm = self._hokage_collection_charm()
        claimed = set(self.store.state.charm_claimed_reward_ids)
        body = bytearray(struct.pack("<B3ii", 1, role_charm, pet_charm, total_charm, len(NYA208_CHARM_REWARDS)))
        for reward_id, need_charm, items in NYA208_CHARM_REWARDS:
            body.extend(
                struct.pack(
                    "<iiBBi",
                    reward_id,
                    need_charm,
                    int(reward_id in claimed),
                    int(total_charm >= need_charm and reward_id not in claimed),
                    len(items),
                )
            )
            for item_id, count, bind in items:
                body.extend(struct.pack("<iiB", item_id, count, bind))
        body.extend(struct.pack("<i", len(NYA208_CHARM_COLORS)))
        for reward_id, need_charm, name, prefix_color, name_color, text_color in NYA208_CHARM_COLORS:
            body.extend(struct.pack("<iiB", reward_id, need_charm, int(total_charm >= need_charm)))
            body.extend(self._original_utf(name))
            body.extend(self._original_utf("【明星】 "))
            body.extend(struct.pack("<III", prefix_color, name_color, text_color))
        body.extend(
            struct.pack(
                "<ii",
                self.store.state.charm_name_color_reward_id,
                self.store.state.charm_text_color_reward_id,
            )
        )
        self.send_original_packet(ServerOpcode.HOKAGE_COLLECTION, bytes(body))

    def _store_hokage_collection_item(self, item_id: int, category: int) -> None:
        catalog = set(
            GAME_DATA_CATALOG.permanent_pet_transform_card_ids
            if category == 1
            else GAME_DATA_CATALOG.permanent_transform_card_ids
        )
        if item_id not in catalog or item_id in self.store.state.transform_card_storage:
            self._send_hokage_collection_info()
            return
        source = next(
            (
                item
                for item in self.store.state.inventory.values()
                if item.slot > 0 and item.item_id == item_id and item.quantity > 0
            ),
            None,
        )
        if source is None:
            self._send_system_chat("背包中没有这张永久变身卡。")
            return
        stored = replace(source, slot=0, quantity=1)
        source.quantity -= 1
        removed = source.quantity == 0
        with self.store.lock:
            if removed:
                del self.store.state.inventory[source.slot]
            self.store.state.transform_card_storage[item_id] = stored
            if item_id not in self.store.state.transform_card_collection:
                self.store.state.transform_card_collection.append(item_id)
                self.store.state.transform_card_collection.sort()
            self.store.save()
        if removed:
            self._send_inventory_clear(source.slot, InventoryType.BAG)
        else:
            self._send_inventory_update(source, from_drop=0)
        self._send_hokage_collection_info()

    def _retrieve_hokage_collection_item(self, item_id: int, category: int) -> None:
        catalog = set(
            GAME_DATA_CATALOG.permanent_pet_transform_card_ids
            if category == 1
            else GAME_DATA_CATALOG.permanent_transform_card_ids
        )
        stored = self.store.state.transform_card_storage.get(item_id)
        if item_id not in catalog or stored is None:
            self._send_hokage_collection_info()
            return
        slot = next(
            (value for value in range(1, self.store.state.bag_capacity + 1) if value not in self.store.state.inventory),
            0,
        )
        if slot == 0:
            self._send_system_chat("背包空间不足，无法取出变身卡。")
            return
        restored = replace(stored, slot=slot)
        with self.store.lock:
            self.store.state.inventory[slot] = restored
            del self.store.state.transform_card_storage[item_id]
            self.store.save()
        self._send_inventory_add(restored, from_drop=0)
        self._send_hokage_collection_info()

    def _switch_collection_transform_card(self, item_id: int, category: int) -> None:
        """Equip one stored transform card directly from the collection album."""
        catalog = set(
            GAME_DATA_CATALOG.permanent_pet_transform_card_ids
            if category == 1
            else GAME_DATA_CATALOG.permanent_transform_card_ids
        )
        if item_id not in catalog:
            return
        equipped_slot = op(EquipmentPosition.TRANSFORM)
        current = self.store.state.inventory.get(equipped_slot)
        if current is not None and current.item_id == item_id:
            # Already equipped: refresh without creating a duplicate card.
            self._send_hokage_collection_info()
            self._send_equipment_slot_update(current)
            self._send_all_stats()
            self._send_character_look()
            return
        stored = self.store.state.transform_card_storage.get(item_id)
        if stored is None:
            if item_id in self.store.state.transform_card_collection:
                self._send_system_chat("图鉴中暂无该变身卡实体，请先放入或取出。")
            else:
                self._send_system_chat("图鉴中没有这张变身卡。")
            return
        with self.store.lock:
            new_card = replace(stored, slot=equipped_slot)
            if current is not None:
                self.store.state.transform_card_storage[current.item_id] = replace(
                    current,
                    slot=0,
                    quantity=1,
                )
                del self.store.state.inventory[equipped_slot]
            self.store.state.inventory[equipped_slot] = new_card
            del self.store.state.transform_card_storage[item_id]
            self.store.save()
        self._send_inventory_clear(equipped_slot, InventoryType.EQUIPPED)
        self._send_inventory_add(new_card, from_drop=0)
        self._send_equipment_slot_update(new_card)
        self._send_all_stats()
        self._send_character_look()
        self._send_hokage_collection_info()
        self._send_system_chat(
            f"已切换变身：{self._item_display_name(item_id, '变身卡')}。"
        )

    def _claim_hokage_charm_reward(self, reward_id: int) -> None:
        reward = next((row for row in NYA208_CHARM_REWARDS if row[0] == reward_id), None)
        if reward is None:
            return
        _, need_charm, items = reward
        if reward_id in self.store.state.charm_claimed_reward_ids:
            self._send_hokage_charm_info()
            return
        if self._hokage_collection_charm()[2] < need_charm:
            self._send_system_chat("藏品魅力不足，暂时无法领取。")
            self._send_hokage_charm_info()
            return
        rewards = [(item_id, count) for item_id, count, _ in items]
        if not self._has_inventory_capacity(rewards):
            self._send_system_chat("背包空间不足，无法领取魅力奖励。")
            return
        granted: list[tuple[InventoryItem, bool]] = []
        with self.store.lock:
            if reward_id in self.store.state.charm_claimed_reward_ids:
                return
            for item_id, count, bind in items:
                granted.append(self._add_inventory_item(item_id, count, can_trade=not bool(bind)))
            self.store.state.charm_claimed_reward_ids.append(reward_id)
            self.store.state.charm_claimed_reward_ids.sort()
            self.store.save()
        for item, created in granted:
            if created:
                self._send_inventory_add(item, from_drop=0)
            else:
                self._send_inventory_update(item, from_drop=0)
        self._send_hokage_charm_info()

    def _set_hokage_charm_colors(self, name_reward_id: int, text_reward_id: int) -> None:
        total_charm = self._hokage_collection_charm()[2]
        colors = {row[0]: row for row in NYA208_CHARM_COLORS}
        valid_name = name_reward_id == 0 or (
            name_reward_id in colors and total_charm >= colors[name_reward_id][1]
        )
        valid_text = text_reward_id == 0 or (
            text_reward_id in colors and total_charm >= colors[text_reward_id][1]
        )
        if not valid_name or not valid_text:
            self._send_system_chat("该聊天颜色尚未解锁。")
            self._send_hokage_charm_info()
            return
        with self.store.lock:
            self.store.state.charm_name_color_reward_id = name_reward_id
            self.store.state.charm_text_color_reward_id = text_reward_id
            self.store.save()
        self._send_hokage_charm_info()

    def _hokage_charm_chat_prefix(self) -> str:
        """Build trusted chat metadata from persisted unlocked color IDs."""
        name_id = self.store.state.charm_name_color_reward_id
        text_id = self.store.state.charm_text_color_reward_id
        colors = {row[0]: row for row in NYA208_CHARM_COLORS}
        name_row = colors.get(name_id)
        text_row = colors.get(text_id)
        total_charm = self._hokage_collection_charm()[2]
        if (
            name_row is None
            or text_row is None
            or total_charm < name_row[1]
            or total_charm < text_row[1]
        ):
            return ""
        return (
            f"[[CHARM~{name_row[3]:06X}|{name_row[4]:06X}|"
            f"{text_row[5]:06X}|【明星】 ]]"
        )

    def handle_hokage_collection(self, read_str: str) -> None:
        """Serve permanent catalogs, storage, charm rewards, and trusted chat colors."""
        fields = self._request_fields(read_str, ClientOpcode.HOKAGE_COLLECTION)
        action = self._safe_int(fields[0], -1) if fields else -1
        if action == 0:
            self._send_hokage_collection_info()
        elif action == 1 and len(fields) >= 3:
            self._store_hokage_collection_item(
                self._safe_int(fields[1], 0), self._safe_int(fields[2], -1)
            )
        elif action == 2 and len(fields) >= 3:
            self._retrieve_hokage_collection_item(
                self._safe_int(fields[1], 0), self._safe_int(fields[2], -1)
            )
        elif action == 3 and len(fields) >= 2:
            self._claim_hokage_charm_reward(self._safe_int(fields[1], 0))
        elif action == 4:
            self._send_hokage_charm_info()
        elif action == 5 and len(fields) >= 3:
            self._set_hokage_charm_colors(
                self._safe_int(fields[1], 0), self._safe_int(fields[2], 0)
            )
        elif action == 6 and len(fields) >= 3:
            self._switch_collection_transform_card(
                self._safe_int(fields[1], 0), self._safe_int(fields[2], -1)
            )

    def handle_banghui(self, read_str: str) -> None:
        """Serve the original family browser and persistent local membership loop."""
        fields = self._request_fields(read_str, ClientOpcode.BANGHUI)
        action = self._safe_int(fields[0], -1) if fields else -1
        if self.hub is not None and self.account_id:
            if self._handle_multiplayer_family(action, fields):
                return
        if action == 2:
            family_id = self._safe_int(fields[1], 0) if len(fields) > 1 else 0
            if family_id != 1:
                return
            with self.store.lock:
                self.store.state.progression.family_joined = True
                self.store.save()
            # The client must know its family id before action 7 requests member data.
            self._send_family_info()
            self.send_text(
                f"{op(ServerOpcode.BANGHUI)}:7:{self.character.character_id}"
            )
            return
        if action == 105:
            progression = self.store.state.progression
            row = "&".join(
                (
                    str(self.character.character_id),
                    self.character.name,
                    str(self.character.level),
                    "1",
                    "0",
                    "0",
                    "0",
                    "0",
                    "0",
                    str(progression.family_contribution),
                    "1",
                    "0",
                )
            )
            self.send_text(f"{op(ServerOpcode.BANGHUI)}:6:{row}")
            return
        if action == 102:
            progression = self.store.state.progression
            members = "&".join(
                (
                    self.character.name,
                    str(self.character.level),
                    "1",
                    str(progression.family_contribution),
                    str(progression.family_contribution),
                )
            )
            display_style = self._family_display_flag_style(
                {
                    "flagLevel": progression.family_flag_level,
                    "flagStyle": progression.family_flag_style,
                }
            )
            self.send_text(
                f"{op(ServerOpcode.BANGHUI)}:1:1:木叶家族:欢迎回家:1:"
                f"{self.character.name}:{self.character.level}:0:1721552400:"
                f"{progression.family_flag_level}:{progression.family_flag_name}:"
                f"{display_style}:{members}"
            )
            return
        if action == 103:
            progression = self.store.state.progression
            display_style = self._family_display_flag_style(
                {
                    "flagLevel": progression.family_flag_level,
                    "flagStyle": progression.family_flag_style,
                }
            )
            self.send_text(
                f"{op(ServerOpcode.BANGHUI)}:4:{progression.family_flag_name}:"
                f"{progression.family_flag_level}:{display_style}"
            )
            return
        if action == 104:
            self._send_family_contribution()
            return
        if action == 12:
            self._handle_family_contribution(fields[1] if len(fields) > 1 else "")
            return
        if action == 205:
            rows = "@".join(
                f"{item_id}&{count}&{price}"
                for item_id, count, price in self._family_shop_rows()
            )
            self.send_text(f"{op(ServerOpcode.BANGHUI)}:23:{rows}")
            return
        if action == 10:
            progression = self.store.state.progression
            if not progression.family_joined:
                return
            next_level = max(1, int(progression.family_flag_level)) + 1
            if next_level > 10:
                self._send_character_notice("家族旗帜已经达到最高等级。")
                return
            required_items = (16_000_023, 16_000_024, 16_000_025, 16_000_026)
            missing = [
                item_id
                for item_id in required_items
                if self._inventory_item_quantity(item_id) < 1
            ]
            if self.store.state.money < 666 or missing:
                self._send_character_notice("家族升级需要666金币和春夏秋冬书各一本。")
                return
            changes: list[tuple[InventoryItem, bool]] = []
            with self.store.lock:
                for item_id in required_items:
                    changes.extend(self._consume_inventory_quantity(item_id, 1))
                self.store.state.money -= 666
                progression.family_flag_level = next_level
                self.store.save()
            for item, removed in changes:
                if removed:
                    self._send_inventory_clear(item.slot, InventoryType.BAG)
                else:
                    self._send_inventory_update(item, from_drop=0)
            self._send_stats({StatType.MONEY: self.store.state.money})
            self._send_family_info()
            self._send_family_flag_identity(visible=True)
            self._send_all_stats()
            self._send_character_notice(f"家族旗帜已升级到 {next_level} 级。")
            return
        if action == 206:
            item_id = self._safe_int(fields[1], 0) if len(fields) > 1 else 0
            self._buy_family_shop_item(item_id)
            return
        if action == 201:
            self._send_family_boss_schedule()
            return
        if action == 202:
            self._set_family_boss_schedule(fields[1:3])
            return
        if action != 101:
            return
        page_size = max(1, self._safe_int(fields[1], 100)) if len(fields) > 1 else 100
        page_id = max(1, self._safe_int(fields[2], 1)) if len(fields) > 2 else 1
        row = "-"
        if page_id == 1:
            row = "&".join(
                (
                    "1",
                    "1",
                    "木叶家族",
                    self.character.name,
                    str(self.character.character_id),
                    "1",
                    "1",
                    "50",
                    str(self.character.level),
                    "0",
                    "1000",
                    "木叶",
                )
            )
        self.send_text(
            f"{op(ServerOpcode.BANGHUI)}:3:1:{page_size}:{page_id}:{row}"
        )

    def handle_change_name(self, read_str: str) -> None:
        """Handle Nya's role rename card and name-history requests on opcode 2330."""
        fields = self._request_fields(read_str, ClientOpcode.CHANGE_NAMES)
        action = self._safe_int(fields[0], -1) if fields else -1
        if action == 10:
            owner = self.accounts.character_owner(self.character.character_id)
            character = owner[1] if owner is not None else {}
            history = [
                str(value)
                for value in character.get("nameHistory", [])
                if str(value).strip()
            ]
            self._send_change_name_result(10, self.character.name, history)
            return
        if action == 12 and len(fields) >= 2:
            requested_name = fields[1].strip().casefold()
            character = next(
                (
                    value
                    for _, value in self.accounts.characters()
                    if str(value.get("name", "")).casefold() == requested_name
                ),
                None,
            )
            history = [
                str(value)
                for value in (character or {}).get("nameHistory", [])
                if str(value).strip()
            ]
            self._send_change_name_result(
                12,
                str((character or {}).get("name", fields[1])),
                history,
            )
            return
        if action != 1 or len(fields) < 2:
            return
        new_name = fields[1].strip()
        rename_card_id = 16_000_180
        if self._inventory_item_quantity(rename_card_id) < 1:
            self._send_character_notice("改名卡不足")
            self._send_change_name_result(1, "改名卡不足")
            return
        try:
            renamed = self.accounts.rename_character(
                self.account_id,
                self.character.character_id,
                new_name,
            )
        except ValueError as exc:
            message = str(exc)
            self._send_character_notice(message)
            self._send_change_name_result(1, message)
            return
        with self.store.lock:
            consumed, removed = self._consume_bag_item(rename_card_id)
            if consumed is None:
                return
            self.character.name = str(renamed["name"])
            self.store.save()
        if removed:
            self._send_inventory_clear(consumed.slot, InventoryType.BAG)
        else:
            self._send_inventory_update(consumed, from_drop=0)
        self._send_change_name_result(0, self.character.name)

    def _send_change_name_result(
        self,
        result: int,
        message: str,
        history: list[str] | None = None,
    ) -> None:
        values = "@".join(history or []) or "-"
        self.send_text(
            f"{op(ServerOpcode.CHANGE_NAMES)}:{result}:{message}:{values}"
        )

    def _current_family(self) -> dict[str, Any] | None:
        """Return only the family persisted on the authenticated account."""
        if not self.account_id:
            return None
        account = self.accounts.account_by_id(self.account_id)
        if account is None:
            return None
        return self.accounts.family_by_id(int(account.get("familyId", 0)))

    def _current_family_name(self) -> str:
        family = self._current_family()
        return str(family.get("name", "-")) if family is not None else "-"

    def _flag_owner_family(self) -> dict[str, Any] | None:
        """Use only the authenticated character's real family for local flags."""
        return self._current_family()

    def _handle_multiplayer_family(self, action: int, fields: list[str]) -> bool:
        account = self.accounts.account_by_id(self.account_id)
        if account is None:
            return True
        family = self.accounts.family_by_id(int(account.get("familyId", 0)))
        if action == 1 and len(fields) >= 6:
            try:
                family = self.accounts.create_family(
                    self.account_id,
                    fields[2],
                    self._safe_int(fields[1], 1000),
                    fields[3],
                    fields[4],
                    self._safe_int(fields[5], 0),
                )
            except ValueError:
                self.send_text(f"{op(ServerOpcode.BANGHUI)}:2:0:0")
                return True
            self.store.state.progression.family_joined = True
            self.store.save()
            self.send_text(
                f"{op(ServerOpcode.BANGHUI)}:2:1:{family['id']}"
            )
            self._refresh_family_identity(family)
            return True
        if action == 2 and len(fields) >= 2:
            status, family = self.accounts.request_family_join(
                self.account_id,
                self._safe_int(fields[1], 0),
            )
            if status == "joined" and family is not None:
                self.store.state.progression.family_joined = True
                self.store.save()
                self._send_family_info()
                self._send_family_flag_identity(visible=True)
                self.send_text(
                    f"{op(ServerOpcode.BANGHUI)}:7:{self.character.character_id}"
                )
            elif status == "pending" and family is not None:
                leader = self.accounts.account_by_id(
                    int(family["leaderAccountId"])
                )
                leader_character = (
                    leader.get("characters", [{}])[0] if leader is not None else {}
                )
                leader_session = self.hub.session_for_character(
                    int(leader_character.get("id", 0))
                )
                if leader_session is not None:
                    leader_session.send_text(
                        f"{op(ServerOpcode.BANGHUI)}:8:{self.character.name}:"
                        f"{self.character.character_id}:{self._current_character_face()}:"
                        f"{self.character.level}"
                    )
            return True
        if action == 6:
            self.accounts.leave_family(self.account_id)
            self.store.state.progression.family_joined = False
            self.store.save()
            self._send_family_flag_clear(visible=True)
            self.send_text(
                f"{op(ServerOpcode.BANGHUI)}:14:{self.character.character_id}:"
                f"{self.character.name}"
            )
            return True
        if action == 3 and len(fields) >= 2:
            invited_family_id = self.hub.family_invites.pop(
                self.character.character_id,
                None,
            )
            if invited_family_id is None:
                invited_family_id = self.accounts.take_family_invite(self.account_id)
            else:
                self.accounts.set_family_invite(self.account_id, 0)
            if invited_family_id is not None:
                invited_family = self.accounts.family_by_id(invited_family_id)
                if invited_family is not None:
                    leader = self.accounts.account_by_id(
                        int(invited_family["leaderAccountId"])
                    )
                    leader_character = (
                        leader.get("characters", [{}])[0] if leader else {}
                    )
                    leader_session = self.hub.session_for_character(
                        int(leader_character.get("id", 0))
                    )
                    if leader_session is not None:
                        leader_session.send_text(
                            f"{op(ServerOpcode.BANGHUI)}:9:{self.character.name}"
                        )
            return True
        if action == 15 and len(fields) >= 2:
            family_id = self._safe_int(fields[1], 0)
            stored_family_id = int(account.get("familyInviteId", 0))
            if (
                self.hub.family_invites.get(self.character.character_id) != family_id
                and stored_family_id != family_id
            ):
                return True
            self.hub.family_invites.pop(self.character.character_id, None)
            self.accounts.set_family_invite(self.account_id, 0)
            joined = self.accounts.join_family(self.account_id, family_id)
            if joined is not None:
                self.store.state.progression.family_joined = True
                self.store.save()
                self._send_family_info()
                self._send_family_flag_identity(visible=True)
                for member in self._family_online_sessions(joined):
                    member.send_text(
                        f"{op(ServerOpcode.BANGHUI)}:7:{self.character.character_id}"
                    )
            return True
        if action == 21 and len(fields) >= 2:
            requested_name = fields[1].strip().casefold()
            available = not any(
                str(value.get("name", "")).casefold() == requested_name
                for value in self.accounts.families()
            )
            self.send_text(
                f"{op(ServerOpcode.BANGHUI)}:19:{1 if available else 0}"
            )
            return True
        if action == 101:
            page_size = max(1, self._safe_int(fields[1], 100)) if len(fields) > 1 else 100
            page_id = max(1, self._safe_int(fields[2], 1)) if len(fields) > 2 else 1
            rows: list[str] = []
            for value in self.accounts.families()[(page_id - 1) * page_size : page_id * page_size]:
                leader = self.accounts.account_by_id(int(value["leaderAccountId"]))
                leader_character = (
                    leader.get("characters", [{}])[0] if leader is not None else {}
                )
                rows.append(
                    "&".join(
                        str(item)
                        for item in (
                            value["id"],
                            (
                                self.hub.session_for_character(
                                    int(leader_character.get("id", 0))
                                ).line_id
                                if self.hub.session_for_character(
                                    int(leader_character.get("id", 0))
                                )
                                else -1
                            ),
                            value["name"],
                            leader_character.get("name", "-"),
                            leader_character.get("id", 0),
                            value.get("flagLevel", 1),
                            len(value.get("members", [])),
                            50,
                            sum(
                                int(
                                    self.accounts.account_by_id(int(member_id))
                                    .get("characters", [{}])[0]
                                    .get("level", 1)
                                )
                                for member_id in value.get("members", [])
                                if self.accounts.account_by_id(int(member_id)) is not None
                            ),
                            0,
                            self._family_display_flag_style(value),
                            value.get("flagName", "-"),
                        )
                    )
                )
            self.send_text(
                f"{op(ServerOpcode.BANGHUI)}:3:{len(self.accounts.families())}:"
                f"{page_size}:{page_id}:{'@'.join(rows) or '-'}"
            )
            return True
        if family is None:
            return action in {102, 103, 104, 105}
        is_leader = int(family["leaderAccountId"]) == self.account_id
        if action == 20 and is_leader and len(fields) >= 2:
            enabled = self._safe_int(fields[1], 0) != 0
            family = self.accounts.update_family(
                int(family["id"]),
                autoAccept=enabled,
            ) or family
            if enabled:
                for applicant_id in list(family.get("applications", [])):
                    applicant = self.accounts.account_by_id(int(applicant_id))
                    if applicant is None:
                        continue
                    self.accounts.decide_family_application(
                        int(family["id"]),
                        int(applicant_id),
                        True,
                    )
                    applicant_session = self.hub.sessions_by_account.get(
                        int(applicant_id)
                    )
                    if applicant_session is not None:
                        applicant_session.store.state.progression.family_joined = True
                        applicant_session.store.save()
                        applicant_session._send_family_info()
                        applicant_session._send_family_flag_identity(visible=True)
            return True
        if action in {13, 14} and is_leader and len(fields) >= 2:
            target_owner = self.accounts.character_owner(
                self._safe_int(fields[1], 0)
            )
            if target_owner is None:
                return True
            accepted = action == 14
            self.accounts.decide_family_application(
                int(family["id"]),
                int(target_owner[0]["id"]),
                accepted,
            )
            target_session = self.hub.session_for_character(
                int(target_owner[1]["id"])
            )
            if target_session is not None:
                if accepted:
                    target_session.store.state.progression.family_joined = True
                    target_session.store.save()
                    target_session._send_family_info()
                    target_session._send_family_flag_identity(visible=True)
                    for member in self._family_online_sessions(family):
                        member.send_text(
                            f"{op(ServerOpcode.BANGHUI)}:7:"
                            f"{target_session.character.character_id}"
                        )
                else:
                    target_session.send_text(
                        f"{op(ServerOpcode.BANGHUI)}:9:{self.character.name}"
                    )
            return True
        if action == 19 and is_leader and len(fields) >= 2:
            target = self.hub.session_for_character(
                self._safe_int(fields[1], 0)
            )
            if target is not None:
                self.hub.family_invites[target.character.character_id] = int(
                    family["id"]
                )
                self.accounts.set_family_invite(target.account_id, int(family["id"]))
                target._send_family_invitation(int(family["id"]))
                target.pending_social_replay_at = time.monotonic() + 0.5
            else:
                target_owner = self.accounts.character_owner(self._safe_int(fields[1], 0))
                if target_owner is not None:
                    self.accounts.set_family_invite(
                        int(target_owner[0]["id"]),
                        int(family["id"]),
                    )
            return True
        if action == 4 and is_leader and len(fields) >= 2:
            target_owner = self.accounts.character_owner(
                self._safe_int(fields[1], 0)
            )
            if (
                target_owner is not None
                and int(target_owner[0]["id"]) != self.account_id
            ):
                self.accounts.leave_family(int(target_owner[0]["id"]))
                target_session = self.hub.session_for_character(
                    int(target_owner[1]["id"])
                )
                for member in self._family_online_sessions(family):
                    member.send_text(
                        f"{op(ServerOpcode.BANGHUI)}:12:{target_owner[1]['id']}:"
                        f"{target_owner[1]['name']}"
                    )
                if target_session is not None:
                    target_session.store.state.progression.family_joined = False
                    target_session.store.save()
                    target_session._send_family_flag_clear(visible=True)
            return True
        if action == 5 and is_leader:
            family_id = int(family["id"])
            members = self.accounts.disband_family(family_id)
            for member_account_id in members:
                member = self.hub.sessions_by_account.get(member_account_id)
                if member is not None:
                    member.store.state.progression.family_joined = False
                    member.store.save()
                    member._send_family_flag_clear(visible=True)
                    member.send_text(
                        f"{op(ServerOpcode.BANGHUI)}:13:{family_id}"
                    )
            return True
        if action == 18 and is_leader and len(fields) >= 2:
            target_owner = self.accounts.character_owner(
                self._safe_int(fields[1], 0)
            )
            if target_owner is not None:
                self.accounts.set_family_leader(
                    int(family["id"]),
                    int(target_owner[0]["id"]),
                )
                for member in self._family_online_sessions(family):
                    member._send_family_info()
            return True
        if action == 17 and is_leader and len(fields) >= 3:
            target_owner = self.accounts.character_owner(
                self._safe_int(fields[1], 0)
            )
            if target_owner is not None:
                ranks = dict(family.get("ranks", {}))
                ranks[str(int(target_owner[0]["id"]))] = max(
                    2,
                    min(4, self._safe_int(fields[2], 4)),
                )
                self.accounts.update_family(int(family["id"]), ranks=ranks)
            return True
        if action == 16 and is_leader and len(fields) >= 3:
            target_owner = self.accounts.character_owner(
                self._safe_int(fields[1], 0)
            )
            if target_owner is not None:
                nicknames = dict(family.get("memberNick", {}))
                nicknames[str(int(target_owner[0]["id"]))] = fields[2][:12].replace(
                    ":",
                    "：",
                )
                self.accounts.update_family(
                    int(family["id"]),
                    memberNick=nicknames,
                )
            return True
        if action == 8 and is_leader and len(fields) >= 2:
            family = self.accounts.update_family(
                int(family["id"]),
                flagName=fields[1][:12].replace(":", "："),
            ) or family
            self._refresh_family_identity(family)
            return True
        if action == 9 and is_leader and len(fields) >= 3:
            family = self.accounts.update_family(
                int(family["id"]),
                flagStyle=max(1000, self._safe_int(fields[2], 1000)),
            ) or family
            self._refresh_family_identity(family)
            return True
        if action == 10 and is_leader:
            current_level = max(1, int(family.get("flagLevel", 1)))
            next_level = current_level + 1
            if next_level > 10:
                self._send_character_notice("家族旗帜已经达到最高等级。")
                return True
            money_cost = 666
            item_costs: dict[str, int] = {
                str(item_id): 1
                for item_id in (16_000_023, 16_000_024, 16_000_025, 16_000_026)
            }
            materials = {
                str(key): max(0, self._safe_int(value, 0))
                for key, value in dict(family.get("materials", {})).items()
            }
            missing_items = [
                (item_id, count - materials.get(item_id, 0))
                for item_id, count in item_costs.items()
                if materials.get(item_id, 0) < count
            ]
            if int(family.get("fund", 0)) < money_cost:
                self._send_character_notice(
                    f"家族资金不足，升级需要 {money_cost} 金币。"
                )
                return True
            if missing_items:
                details = "、".join(
                    f"{self._item_display_name(self._safe_int(item_id, 0), '家族材料')}缺少{count}个"
                    for item_id, count in missing_items
                )
                self._send_character_notice(f"家族升级材料不足：{details}。")
                return True
            for item_id, count in item_costs.items():
                materials[item_id] -= count
            family = self.accounts.update_family(
                int(family["id"]),
                flagLevel=next_level,
                fund=int(family.get("fund", 0)) - money_cost,
                materials=materials,
            ) or family
            self._refresh_family_identity(family)
            self._send_character_notice(f"家族旗帜已升级到 {next_level} 级。")
            return True
        if action == 102:
            members = self._family_member_summaries(family)
            leader_account = self.accounts.account_by_id(int(family["leaderAccountId"]))
            leader_character = leader_account.get("characters", [{}])[0] if leader_account else {}
            self.send_text(
                f"{op(ServerOpcode.BANGHUI)}:1:{family['id']}:{family['name']}:"
                f"{family.get('notice', '-')}:{len(family.get('members', []))}:"
                f"{leader_character.get('name', '-')}:{sum(int(row[1]) for row in members)}:"
                f"0:{family.get('createdAt', 0)}:{family.get('flagLevel', 1)}:"
                f"{family.get('flagName', '-')}:{self._family_display_flag_style(family)}:"
                f"{'@'.join('&'.join(str(value) for value in row) for row in members) or '-'}"
            )
            return True
        if action == 103:
            self.send_text(
                f"{op(ServerOpcode.BANGHUI)}:4:{family.get('flagName', '-')}:"
                f"{family.get('flagLevel', 1)}:{self._family_display_flag_style(family)}"
            )
            return True
        if action == 105:
            rows = []
            for member_id in family.get("members", []):
                member = self.accounts.account_by_id(int(member_id))
                summary = member.get("characters", [{}])[0] if member else {}
                state = self._persisted_character_state(summary)
                character = state.character if state is not None else None
                progression = state.progression if state is not None else None
                character_id = (
                    character.character_id
                    if character is not None
                    else self._safe_int(summary.get("id"), 0)
                )
                online = self.hub.session_for_character(character_id)
                contribution = progression.family_contribution if progression else 0
                weekly_contribution = (
                    progression.family_weekly_contribution if progression else 0
                )
                skill_value = (
                    progression.wu_gong_progress
                    or sum(max(0, skill.level) for skill in state.skills.values())
                    if progression is not None and state is not None
                    else 0
                )
                mai_value = (
                    max(0, progression.stages.get("八门", 0)) if progression else 0
                )
                achievement_value = (
                    len(progression.claimed_achievements) if progression else 0
                )
                shengwang_value = max(0, character.shengwang) if character else 0
                boss_value = progression.boss_weekly_kills if progression else 0
                rows.append(
                    "&".join(
                        str(value)
                        for value in (
                            character_id,
                            character.name if character is not None else summary.get("name", "-"),
                            character.level if character is not None else summary.get("level", 1),
                            int(
                                family.get("ranks", {}).get(
                                    str(int(member_id)),
                                    1
                                    if int(member_id)
                                    == int(family["leaderAccountId"])
                                    else 4,
                                )
                            ),
                            character.job if character is not None else summary.get("job", 300),
                            (
                                online._current_character_face()
                                if online is not None
                                else summary.get("face", 300)
                            ),
                            character.gender if character is not None else summary.get("gender", 0),
                            0,
                            contribution,
                            weekly_contribution,
                            online.line_id if online else -1,
                            family.get("memberNick", {}).get(str(int(member_id)), ""),
                            skill_value,
                            mai_value,
                            achievement_value,
                            shengwang_value,
                            boss_value,
                        )
                    )
                )
            self.send_text(f"{op(ServerOpcode.BANGHUI)}:6:{'@'.join(rows) or '-'}")
            return True
        if action == 7 and int(family["leaderAccountId"]) == self.account_id:
            self.accounts.update_family(
                int(family["id"]),
                notice=":".join(fields[1:])[:80].replace(":", "："),
            )
            for member in self._family_online_sessions(family):
                member._send_family_info()
            return True
        return False

    def _family_member_summaries(self, family: dict[str, Any]) -> list[tuple[Any, ...]]:
        rows: list[tuple[Any, ...]] = []
        for member_id in family.get("members", []):
            account = self.accounts.account_by_id(int(member_id))
            character = account.get("characters", [{}])[0] if account else {}
            state = self._persisted_character_state(character)
            progression = state.progression if state is not None else None
            live_character = state.character if state is not None else None
            contribution = (
                progression.family_contribution if progression is not None else 0
            )
            rows.append(
                (
                    live_character.name if live_character is not None else character.get("name", "-"),
                    live_character.level if live_character is not None else int(character.get("level", 1)),
                    int(
                        family.get("ranks", {}).get(
                            str(int(member_id)),
                            1
                            if int(member_id) == int(family["leaderAccountId"])
                            else 4,
                        )
                    ),
                    contribution,
                    contribution,
                    contribution,
                )
            )
        return rows

    def _persisted_character_state(
        self,
        character: dict[str, Any],
    ) -> SinglePlayerState | None:
        """Load authoritative offline character data used by social list views."""
        character_id = self._safe_int(character.get("id"), 0)
        if character_id <= 0:
            return None
        online = (
            self.hub.session_for_character(character_id)
            if self.hub is not None
            else None
        )
        if online is not None:
            return online.store.state
        save_path = self.accounts.character_path(character)
        if not save_path.is_file():
            return None
        try:
            return SinglePlayerStore(save_path).state
        except (OSError, UnicodeError, ValueError, TypeError):
            return None

    def _family_online_sessions(
        self,
        family: dict[str, Any],
    ) -> list[FakeFlashSession]:
        if self.hub is None:
            return []
        return [
            session
            for account_id in family.get("members", [])
            if (
                session := self.hub.sessions_by_account.get(int(account_id))
            )
            is not None
        ]

    def _refresh_family_identity(self, family: dict[str, Any]) -> None:
        """Push changed flag identity to every online member and visible map flag."""
        sessions = self._family_online_sessions(family)
        if not sessions:
            sessions = [self]
        payload = (
            f"{op(ServerOpcode.BANGHUI)}:4:{family.get('flagName', '-')}:"
            f"{family.get('flagLevel', 1)}:{self._family_display_flag_style(family)}"
        )
        for session in sessions:
            session._send_family_info()
            session.send_text(payload)
            session._send_family_flag_identity(visible=True)
            session._send_local_flag_spawn(visible=True)
            session._send_all_stats()

    @staticmethod
    def _family_shop_rows() -> tuple[tuple[int, int, int], ...]:
        """Return a small deterministic catalog priced in family contribution."""
        return ((int(ItemId.HEALTH_POTION), 5, 20), (3_000_002, 3, 30))

    @staticmethod
    def _family_contribution_item_ids() -> tuple[int, ...]:
        """Return the five authored family books shown by the stock pane."""
        return (16_000_022, 16_000_023, 16_000_024, 16_000_025, 16_000_026)

    def _send_family_contribution(self) -> None:
        """Populate contribution ranking with all persisted family members."""
        progression = self.store.state.progression
        family = None
        if self.hub is not None and self.account_id:
            account = self.accounts.account_by_id(self.account_id)
            family = (
                self.accounts.family_by_id(int(account.get("familyId", 0)))
                if account is not None
                else None
            )
        members = []
        member_rows: list[tuple[int, dict[str, Any] | None, SinglePlayerState, FakeFlashSession | None]] = []
        if family is not None:
            for member_id in family.get("members", []):
                account = self.accounts.account_by_id(int(member_id))
                summary = account.get("characters", [{}])[0] if account else {}
                online = (
                    self.hub.sessions_by_account.get(int(member_id))
                    if self.hub is not None
                    else None
                )
                state = online.store.state if online is not None else self._persisted_character_state(summary)
                if state is not None:
                    member_rows.append((int(member_id), summary, state, online))
        if not member_rows:
            member_rows.append((self.account_id, None, self.store.state, self))
        for member_id, summary, member_state, member_session in member_rows:
            member_progression = member_state.progression
            member_character = member_state.character
            rank = (
                int(
                    family.get("ranks", {}).get(
                        str(member_id),
                        4,
                    )
                )
                if family is not None
                else 1
            )
            members.append(
                "&".join(
                    (
                        str(member_character.character_id),
                        member_character.name if member_character is not None else str((summary or {}).get("name", "-")),
                        str(member_character.level if member_character is not None else int((summary or {}).get("level", 1))),
                        str(rank),
                        "0",
                        str(member_progression.family_fund),
                        "0",
                        str(member_progression.family_fund),
                        str(member_session.line_id if member_session is not None else -1),
                        str(member_progression.family_contribution),
                        str(member_progression.family_weekly_contribution),
                    )
                )
            )
        family_fund = (
            int(family.get("fund", 0))
            if family is not None
            else progression.family_fund
        )
        materials = dict(family.get("materials", {})) if family is not None else {}
        item_stock = ",".join(
            f"{item_id}&{max(0, self._safe_int(materials.get(str(item_id)), 0))}"
            for item_id in self._family_contribution_item_ids()
        )
        self.send_text(
            f"{op(ServerOpcode.BANGHUI)}:5:{family_fund}:"
            f"{item_stock}:{'@'.join(members) or '-'}"
        )

    def _handle_family_contribution(self, payload: str) -> None:
        """Consume donated gold/items atomically and credit persistent contribution."""
        family: dict[str, Any] | None = None
        entries: list[tuple[int, int]] = []
        try:
            decoded = json.loads(payload)
        except (TypeError, ValueError):
            decoded = None
        if isinstance(decoded, dict):
            rows = [decoded] if "itemid" in decoded else list(decoded.values())
        elif isinstance(decoded, list):
            rows = decoded
        else:
            rows = []
        for row in rows:
            if not isinstance(row, dict):
                continue
            item_id = self._safe_int(row.get("itemid"), -1)
            count = max(0, self._safe_int(row.get("count"), 0))
            if item_id >= 0 and count > 0:
                entries.append((item_id, count))
        if not entries:
            for raw_entry in payload.split("@"):
                values = raw_entry.split("&")
                if len(values) < 2:
                    continue
                item_id = self._safe_int(values[0], -1)
                count = max(0, self._safe_int(values[1], 0))
                if item_id >= 0 and count > 0:
                    entries.append((item_id, count))
        if not entries:
            self.send_text(f"{op(ServerOpcode.BANGHUI)}:17:0:0")
            return
        money = sum(count for item_id, count in entries if item_id == 0)
        item_entries = [(item_id, count) for item_id, count in entries if item_id > 0]
        if money > self.store.state.money or any(
            self._inventory_item_quantity(item_id) < count for item_id, count in item_entries
        ):
            self.send_text(
                f"{op(ServerOpcode.BANGHUI)}:17:{1 if money else 0}:0"
            )
            return
        changes: list[tuple[InventoryItem, bool]] = []
        with self.store.lock:
            self.store.state.money -= money
            for item_id, count in item_entries:
                changes.extend(self._consume_inventory_quantity(item_id, count))
            gained = money // 1_000 + sum(count * 5 for _, count in item_entries)
            progression = self.store.state.progression
            progression.family_fund += money
            progression.family_contribution += gained
            progression.family_weekly_contribution += gained
            self.store.save()
        if self.hub is not None and self.account_id:
            account = self.accounts.account_by_id(self.account_id)
            family = (
                self.accounts.family_by_id(int(account.get("familyId", 0)))
                if account is not None
                else None
            )
            if family is not None:
                materials = {
                    str(key): max(0, self._safe_int(value, 0))
                    for key, value in dict(family.get("materials", {})).items()
                }
                for item_id, count in item_entries:
                    key = str(item_id)
                    materials[key] = materials.get(key, 0) + count
                family = self.accounts.update_family(
                    int(family["id"]),
                    fund=int(family.get("fund", 0)) + money,
                    materials=materials,
                ) or family
        for item, removed in changes:
            if removed:
                self._send_inventory_clear(item.slot, InventoryType.BAG)
            else:
                self._send_inventory_update(item, from_drop=0)
        if money:
            self._send_stats({StatType.MONEY: self.store.state.money})
        self.send_text(f"{op(ServerOpcode.BANGHUI)}:17:{1 if money else 0}:1")
        self.send_text(
            f"{op(ServerOpcode.BANGHUI)}:20:"
            f"{self.store.state.progression.family_contribution}"
        )
        refresh_sessions = (
            self._family_online_sessions(family) if family is not None else [self]
        )
        if not refresh_sessions:
            refresh_sessions = [self]
        for session in refresh_sessions:
            session._send_family_contribution()
        self._advance_activity(14)

    def _buy_family_shop_item(self, item_id: int) -> None:
        """Exchange family contribution for one configured stack."""
        row = next((value for value in self._family_shop_rows() if value[0] == item_id), None)
        if row is None:
            return
        _, count, price = row
        progression = self.store.state.progression
        if progression.family_contribution < price or not self._has_inventory_capacity([(item_id, count)]):
            return
        with self.store.lock:
            progression.family_contribution -= price
            item, created = self._add_inventory_item(item_id, count)
            self.store.save()
        if created:
            self._send_inventory_add(item, from_drop=0)
        else:
            self._send_inventory_update(item, from_drop=0)
        self.send_text(
            f"{op(ServerOpcode.BANGHUI)}:20:{progression.family_contribution}"
        )

    @staticmethod
    def _family_boss_week_key(now: time.struct_time | None = None) -> str:
        """Return a stable local-calendar key for the family's weekly schedule."""
        return time.strftime("%Y-%W", now or time.localtime())

    def _refresh_family_boss_week(self, now: time.struct_time | None = None) -> None:
        """Reset the original once-per-week schedule lock when a new week starts."""
        progression = self.store.state.progression
        current_key = self._family_boss_week_key(now)
        if progression.family_boss_week_key == current_key:
            return
        with self.store.lock:
            progression.family_boss_week_key = current_key
            progression.family_boss_set_count = 0
            progression.family_boss_time_indices = []
            self.store.save()

    def _send_family_boss_schedule(self, now: time.struct_time | None = None) -> None:
        """Populate the original family activity-time window through opcode 2314."""
        current = now or time.localtime()
        self._refresh_family_boss_week(current)
        progression = self.store.state.progression
        day = current.tm_wday + 1
        seconds = current.tm_hour * 3600 + current.tm_min * 60 + current.tm_sec
        selected = "@".join(str(value) for value in progression.family_boss_time_indices) or "-"
        self.send_text(
            f"{op(ServerOpcode.BANGHUI_BOSS)}:0:{day}:{seconds}:"
            f"{progression.family_boss_set_count}:{selected}"
        )

    def _set_family_boss_schedule(self, raw_indices: list[str]) -> None:
        """Persist up to two authored weekly activity slots and refresh the window."""
        self._refresh_family_boss_week()
        progression = self.store.state.progression
        if progression.family_boss_set_count > 0:
            self._send_family_boss_schedule()
            return
        selected = sorted(
            {
                value
                for raw_value in raw_indices
                if 0 <= (value := self._safe_int(raw_value, -1)) <= 6
            }
        )[:2]
        with self.store.lock:
            progression.family_boss_time_indices = selected
            progression.family_boss_set_count = 1
            self.store.save()
        self._send_family_boss_schedule()

    def _send_family_info(self) -> None:
        """Initialize the client-side family manager with the local family identity."""
        if self.hub is not None and self.account_id:
            account = self.accounts.account_by_id(self.account_id)
            family = (
                self.accounts.family_by_id(int(account.get("familyId", 0)))
                if account is not None
                else None
            )
            if family is not None:
                leader_account = self.accounts.account_by_id(
                    int(family["leaderAccountId"])
                )
                leader_character = (
                    leader_account.get("characters", [{}])[0]
                    if leader_account is not None
                    else {}
                )
                self.send_text(
                    f"{op(ServerOpcode.BANGHUI)}:15:{family['id']}:{family['name']}:"
                    f"{family.get('notice', '-')}:{family.get('createdAt', 0)}:"
                    f"{leader_character.get('id', 0)}:"
                    f"{leader_character.get('name', '-')}"
                )
            return
        self.send_text(
            f"{op(ServerOpcode.BANGHUI)}:15:1:木叶家族:欢迎回家:1721552400:"
            f"{self.character.character_id}:{self.character.name}"
        )

    def _add_zq(self, amount: int) -> int:
        """Apply one essence delta while preserving the client's fixed 500000 cap."""
        self.character.zq = max(0, min(MAX_ZQ, self.character.zq + int(amount)))
        return self.character.zq

    def _send_stats(self, updates: dict[StatType, int]) -> None:
        """Send one or more incremental character stat changes."""
        synchronized = dict(updates)
        changed = False
        maximum_hp = synchronized.get(StatType.MAX_HP)
        maximum_mp = synchronized.get(StatType.MAX_MP)
        with self.store.lock:
            if StatType.ZQ in synchronized:
                clamped_zq = max(0, min(MAX_ZQ, self.character.zq))
                if clamped_zq != self.character.zq:
                    self.character.zq = clamped_zq
                    changed = True
                synchronized[StatType.ZQ] = self.character.zq
            current_max_hp = self._current_max_hp()
            current_max_mp = self._current_max_mp()
            if maximum_hp is not None and self.character.hp > current_max_hp:
                self.character.hp = max(0, current_max_hp)
                synchronized[StatType.HP] = self.character.hp
                changed = True
            if maximum_mp is not None and self.character.mp > current_max_mp:
                self.character.mp = max(0, current_max_mp)
                synchronized[StatType.MP] = self.character.mp
                changed = True
            if changed:
                self.store.save()
        if StatType.MP in synchronized and self._is_mp_sealed():
            synchronized[StatType.MP] = 0
        encoded = "@".join(
            f"{op(stat_type)}&{value}" for stat_type, value in synchronized.items()
        )
        self.send_text(f"{op(ServerOpcode.UPDATE_STATS)}:{encoded}")
        if any(
            stat_type in synchronized
            for stat_type in (StatType.HP, StatType.MAX_HP, StatType.MP, StatType.MAX_MP)
        ):
            self._broadcast_party_member_stats()
        if StatType.LEVEL in synchronized and self.hub is not None:
            party = self.hub.party_for(self.character.character_id)
            if party is not None:
                self._broadcast_party_status(party)

    def _send_authoritative_resources(
        self,
        *,
        include_hp: bool = True,
        include_mp: bool = True,
    ) -> None:
        """Synchronize current and maximum resources through 32-bit stat rows."""
        updates: dict[StatType, int] = {}
        if include_hp:
            updates[StatType.MAX_HP] = self._current_max_hp()
            updates[StatType.HP] = self.character.hp
        if include_mp:
            updates[StatType.MAX_MP] = self._current_max_mp()
            updates[StatType.MP] = self.character.mp
        if updates:
            self._send_stats(updates)

    def _send_crime_update(self) -> None:
        """Refresh local crime combat stats and nearby name-color state."""
        self._send_stats(
            {
                StatType.CRIME: self.character.crime,
                StatType.ATTACK: self._current_attack(),
                StatType.DEFENCE: self._current_defence(),
            }
        )
        if self.hub is None:
            return
        payload = (
            f"{op(ServerOpcode.UPDATE_FOREIGN_STATS)}:"
            f"{self.character.character_id}:"
            f"{op(StatType.CRIME)}&{self.character.crime}"
        )
        self.hub.broadcast_visible(self, payload)

    def _change_crime(self, delta: int) -> int:
        """Persist a bounded crime delta and return the amount actually applied."""
        with self.store.lock:
            previous = max(0, self.character.crime)
            self.character.crime = max(0, previous + delta)
            applied = self.character.crime - previous
            if applied:
                self.store.save()
        if applied:
            self._send_crime_update()
        return applied

    def _tick_crime_decay(self, now: float) -> None:
        """Remove the GameData-authored crime amount for each full online interval."""
        rules = GAME_DATA_CATALOG.pvp_open_config().get("crime")
        if not isinstance(rules, dict):
            self.last_crime_decay_at = now
            return
        interval = max(1, self._safe_int(rules.get("crimeDesTimeIntv"), 60))
        intervals = int((now - self.last_crime_decay_at) // interval)
        if intervals <= 0:
            return
        self.last_crime_decay_at += intervals * interval
        decrease = max(0, self._safe_int(rules.get("crimeDesTimePoint"), 0))
        if decrease and self.character.crime > 0:
            self._change_crime(-(decrease * intervals))

    def _reduce_crime_for_monster(self, monster_level: int) -> None:
        """Apply the authored one-point redemption for a level-eligible monster kill."""
        rules = GAME_DATA_CATALOG.pvp_open_config().get("crime")
        if not isinstance(rules, dict) or self.character.crime <= 0:
            return
        level_interval = max(
            0, self._safe_int(rules.get("crimeDesMobLevelIntv"), 0)
        )
        if monster_level < self.character.level - level_interval:
            return
        decrease = max(0, self._safe_int(rules.get("crimeDesMobPoint"), 0))
        if decrease:
            self._change_crime(-decrease)

    def handle_distribute_ap(self, read_str: str) -> None:
        """Apply the four attribute increments sent by the character panel."""
        fields = self._request_fields(read_str, ClientOpcode.DISTRIBUTE_AP)
        if len(fields) < 4:
            return
        increments = tuple(self._safe_int(value, -1) for value in fields[:4])
        spent = sum(increments)
        if any(value < 0 for value in increments) or spent > self.character.remaining_ap:
            self._send_system_chat("属性点不足，本次分配已取消。")
            return
        if spent == 0:
            return
        current = self._base_attributes()
        requested = tuple(value + increment for value, increment in zip(current, increments))
        self._apply_attribute_values(requested, spent)

    def handle_distribute_auto_ap(self, read_str: str) -> None:
        """Distribute every remaining point evenly when an automatic request is received."""
        remaining = self.character.remaining_ap
        if remaining <= 0:
            return
        values = list(self._base_attributes())
        for index in range(remaining):
            values[index % len(values)] += 1
        self._apply_attribute_values(tuple(values), remaining)

    def handle_rewash_ap(self, read_str: str) -> None:
        """Refund the exact four attribute amounts selected in the native wash panel."""
        fields = self._request_fields(read_str, ClientOpcode.REWASH_AP)
        if len(fields) < 4:
            return
        requested = tuple(self._safe_int(value, -1) for value in fields[:4])
        if any(value < 0 for value in requested):
            return
        baseline = self._level_attribute_baseline()
        current = self._base_attributes()
        available = tuple(max(0, value - base) for value, base in zip(current, baseline))
        if any(value > maximum for value, maximum in zip(requested, available)):
            self._send_native_server_message("洗点数值无效，请重新打开洗点窗口。", 16)
            return
        refunded = sum(requested)
        if refunded == 0:
            self._send_native_server_message("当前没有选中需要重洗的潜能点。", 16)
            return
        material_id = 16_000_011
        super_material_id = 15_016_001
        material_count = refunded if self.character.level > 30 else 0
        use_super_material = bool(
            material_count
            and requested == available
            and self._inventory_item_quantity(super_material_id) > 0
        )
        if (
            material_count
            and not use_super_material
            and self._inventory_item_quantity(material_id) < material_count
        ):
            self._send_native_server_message("洗点卷数量不足，洗点失败。", 16)
            return
        inventory_changes: list[tuple[InventoryItem, bool]] = []
        with self.store.lock:
            if use_super_material:
                inventory_changes = self._consume_inventory_quantity(
                    super_material_id, 1
                )
            elif material_count:
                inventory_changes = self._consume_inventory_quantity(
                    material_id, material_count
                )
            self.character.ap_atk, self.character.ap_def, self.character.ap_dex, self.character.ap_phy = (
                value - refund for value, refund in zip(current, requested)
            )
            self.character.remaining_ap += refunded
            self.store.save()
        for item, removed in inventory_changes:
            if removed:
                self._send_inventory_clear(item.slot, InventoryType.BAG)
            else:
                self._send_inventory_update(item, from_drop=0)
        self._send_attribute_stats()
        self._send_native_server_message(f"洗点成功，返还 {refunded} 点潜能。", 5)

    def handle_mixin(self, read_str: str) -> None:
        """Run the native three-attempt escort flow used by Oil Girl Shino."""
        payload = self._strip_timestamp(read_str)
        values = payload.split(":", 2)
        if values and values[0] == str(op(ClientOpcode.MIXIN)):
            values = values[1:]
        if not values:
            return
        action = self._safe_int(values[0], -1)
        data: dict[str, Any] = {}
        if len(values) > 1:
            try:
                decoded = json.loads(values[1])
                if isinstance(decoded, dict):
                    data = decoded
            except json.JSONDecodeError:
                pass
        if action == 1:
            progress = self.store.state.original_quests.get(8100)
            if progress is not None and QuestState(progress.state) in (
                QuestState.ACTIVE,
                QuestState.READY_TO_COMPLETE,
            ):
                self._send_native_server_message("护送进行中不能刷新任务品质。", 16)
                self._send_mixin_state()
                return
            current = self._mixin_pending_color()
            if current >= 5:
                self._send_native_server_message("护送任务已经是最高品质。", 16)
                self._send_mixin_state()
                return
            with self.store.lock:
                progression = self.store.state.progression.stage_progress
                new_quality = current + 1
                progression["护送:品质"] = new_quality
                progression["护送:刷新次数"] = self._mixin_refresh_count() + 1
                self.store.save()
            self._send_mixin_state()
            if new_quality >= 4:
                quality_name = {4: "紫色", 5: "橙色"}.get(
                    new_quality,
                    f"{new_quality}级",
                )
                self._broadcast_rare_event(
                    f"{self.character.name}将护送任务刷新到了{quality_name}品质！",
                    highlights=(self.character.name, quality_name),
                    colored_values=((quality_name, "#ff5498"),),
                    action_link=("我要护送", f"npc{self._escort_start_npc_id()}"),
                )
            return
        if action == 2:
            self._start_mixin_escort()
            return
        if action == 3:
            self._mark_mixin_escort_ready()
            return
        if action == 4:
            self._send_mixin_state()
            return
        if action == 5:
            self._cancel_mixin_escort(notify=True)
            return
        if action == 6:
            self._claim_mixin_escort_reward()

    def _cancel_mixin_escort(self, *, notify: bool) -> bool:
        """Clear quest, copy, and actor remnants from normal and legacy escort saves."""
        progress = self.store.state.original_quests.get(8100)
        state = self._safe_int(progress.state, -1) if progress is not None else -1
        quest_active = state not in {
            int(QuestState.NOT_STARTED),
            int(QuestState.COMPLETED),
        }
        copy_active = self.pending_copy_id == 9 or self.active_copy_id == 9
        actor_active = 6_900 in self.monsters
        if not (quest_active or copy_active or actor_active):
            if notify:
                self._send_native_server_message("当前没有进行中的护送任务。", 16)
            return False
        with self.store.lock:
            if progress is not None and quest_active:
                progress.state = int(QuestState.NOT_STARTED)
                progress.progress = {}
            progression = self.store.state.progression.stage_progress
            progression["护送:品质"] = 1
            progression["护送:刷新次数"] = 0
            if self.pending_copy_id == 9:
                self.pending_copy_id = None
                self.pending_copy_enter_at = 0.0
            self.store.save()
        if actor_active:
            self.monsters.pop(6_900, None)
            self._send_visible(
                f"{op(ServerOpcode.KILL_MONSTER)}:6900:"
                f"{op(MonsterRemovalAnimation.IMMEDIATE)}"
            )
        if self.active_copy_id == 9:
            self._leave_active_copy()
        self._send_original_quest_lists()
        self._send_npc_quest_status()
        self._send_stats({StatType.WALK_SPEED: self._current_walk_speed()})
        if notify:
            self._send_native_server_message(
                "已取消护送任务，移动速度已恢复。",
                16,
            )
        return True

    @staticmethod
    def _escort_start_npc_id() -> int:
        definition = GAME_DATA_CATALOG.get_quest_definition(8100)
        return definition.start_npc_id if definition is not None else 23

    def _mixin_reward_values(self) -> tuple[int, int]:
        """Return the base card reward scaled by the pending escort level."""
        color = self._mixin_pending_color()
        return self.character.level * 1200 * color, self.character.level * 20 * color

    def _mixin_pending_color(self) -> int:
        """Read the selected escort quality from persisted character state."""
        return max(
            1,
            min(
                5,
                self._safe_int(
                    self.store.state.progression.stage_progress.get("护送:品质"),
                    1,
                ),
            ),
        )

    def _mixin_refresh_count(self) -> int:
        """Read the persisted escort quality-refresh count."""
        return max(
            0,
            self._safe_int(
                self.store.state.progression.stage_progress.get("护送:刷新次数"),
                0,
            ),
        )

    def _mixin_dynamic_data(self, progress: OriginalQuestProgress) -> dict[str, Any]:
        color = max(1, min(5, self._safe_int(progress.progress.get("color"), 3)))
        exp = max(0, self._safe_int(progress.progress.get("exp"), 0))
        zq = max(0, self._safe_int(progress.progress.get("zq"), 0))
        definition = GAME_DATA_CATALOG.get_quest_definition(8100)
        return {
            "check": {"info": {"level": color}},
            "act": {"info": {"level": color}, "exp": exp, "zq": zq},
            "actEx": {},
            "npc": definition.end_npc_id if definition is not None else 75,
        }

    def _send_mixin_state(self) -> None:
        progress = self.store.state.original_quests.get(8100)
        definition = GAME_DATA_CATALOG.get_quest_definition(8100)
        color = self._mixin_pending_color()
        if progress is not None:
            color = max(1, min(5, self._safe_int(progress.progress.get("color"), color)))
        exp, zq = self._mixin_reward_values()
        if progress is not None and QuestState(progress.state) in (
            QuestState.ACTIVE,
            QuestState.READY_TO_COMPLETE,
        ):
            exp = max(0, self._safe_int(progress.progress.get("exp"), exp))
            zq = max(0, self._safe_int(progress.progress.get("zq"), zq))
        data = {
            "npcid": definition.end_npc_id if definition is not None else 75,
            "color": color,
            "add_hp": 0,
            "time_limit": 1200,
            "refresh_count": self._mixin_refresh_count(),
            "total_free_count": 3,
            "total_quest_count": 3,
            "exp": exp,
            "zq": zq,
        }
        self.send_original_packet(
            ServerOpcode.MIXIN,
            b"\x01" + build_original_object_buffer(data),
        )

    def _start_mixin_escort(self) -> None:
        if self.character.level < 30:
            self._send_native_server_message("30级后才可接取护送任务。", 16)
            return
        current = self.store.state.original_quests.get(8100)
        if current is not None and QuestState(current.state) in (
            QuestState.ACTIVE,
            QuestState.READY_TO_COMPLETE,
        ):
            self._send_native_server_message("护送任务已经在进行中。", 16)
            return
        finish_count = current.finish_count if current is not None else 0
        if finish_count >= 3:
            self._send_native_server_message("今日护送次数已经用完。", 16)
            return
        color = self._mixin_pending_color()
        exp, zq = self._mixin_reward_values()
        with self.store.lock:
            progress = OriginalQuestProgress(
                state=int(QuestState.ACTIVE),
                progress={"color": color, "exp": exp, "zq": zq},
                finish_count=finish_count,
            )
            self.store.state.original_quests[8100] = progress
            self.store.save()
        self._send_original_quest_lists()
        self._send_original_quest_started_notification(8100)
        self._send_npc_quest_status()
        self._send_stats({StatType.WALK_SPEED: self._current_walk_speed()})

    def _mark_mixin_escort_ready(self) -> None:
        """Finish navigation and open the native reward-card flow at the target NPC."""
        progress = self.store.state.original_quests.get(8100)
        if progress is None or QuestState(progress.state) != QuestState.ACTIVE:
            if progress is None or QuestState(progress.state) != QuestState.READY_TO_COMPLETE:
                self._send_native_server_message("当前没有进行中的护送任务。", 16)
            return
        definition = GAME_DATA_CATALOG.get_quest_definition(8100)
        if definition is None:
            return
        with self.store.lock:
            progress.state = int(QuestState.READY_TO_COMPLETE)
            self.store.save()
        self._return_mixin_to_shino()
        # PrizeCardSprite snapshots these values as soon as status 2 arrives.
        # Publish the level-scaled reward first so its five cards never render as zero.
        if self.wire_mode == "original":
            self._send_mixin_state()
        self._send_original_quest_full_progress(definition, progress, flash_status=2)
        self._send_original_quest_lists()
        self._send_original_quest_completion_notification(8100)
        self._send_npc_quest_status()

    def _return_mixin_to_shino(self) -> None:
        """Return a completed escort beside Oil Girl Shino in Konoha."""
        definition = GAME_DATA_CATALOG.get_quest_definition(8100)
        target_map_id = 100_000_000
        target_map = GAME_DATA_CATALOG.get_map(target_map_id)
        start_npc_id = definition.start_npc_id if definition is not None else 23
        shino = next(
            (
                npc
                for npc in target_map.npcs
                if npc.template_id == start_npc_id
            ),
            None,
        ) if target_map is not None else None
        target_position = (shino.x - 80, shino.y) if shino is not None else None
        target_foothold = shino.foothold if shino is not None else None
        if self.active_copy_id == 9:
            self._leave_active_copy(
                return_map_id=target_map_id,
                return_position=target_position,
                return_foothold=target_foothold,
            )
            return
        if target_foothold is not None:
            self.character.foothold = target_foothold
        self._warp_to_map(target_map_id, exact_position=target_position)

    def _claim_mixin_escort_reward(self) -> None:
        """Settle the selected reward card once and restore normal movement speed."""
        progress = self.store.state.original_quests.get(8100)
        if progress is None or QuestState(progress.state) != QuestState.READY_TO_COMPLETE:
            self._send_native_server_message("请先把护送目标送到终点。", 16)
            return
        multiplier = 2 if self.random.randrange(5) == 0 else 1
        exp = max(0, self._safe_int(progress.progress.get("exp"), 0))
        zq = max(0, self._safe_int(progress.progress.get("zq"), 0))
        with self.store.lock:
            progress.state = int(QuestState.COMPLETED)
            progress.finish_count += 1
            self._add_zq(zq * multiplier)
            self.store.state.progression.stage_progress["护送:品质"] = 1
            self.store.state.progression.stage_progress["护送:刷新次数"] = 0
            self.store.save()
        if self.wire_mode == "original":
            self.send_original_packet(
                ServerOpcode.MIXIN,
                b"\x04" + struct.pack("<i", multiplier),
            )
        else:
            self.send_text(f"{op(ServerOpcode.MIXIN)}:4:{multiplier}")
        self._grant_experience(exp * multiplier)
        self._send_stats(
            {
                StatType.ZQ: self.character.zq,
                StatType.WALK_SPEED: self._current_walk_speed(),
            }
        )
        self._send_original_quest_lists()
        self._send_npc_quest_status()
        self._advance_activity(5)
        self._send_native_server_message(
            f"护送完成，获得经验 {exp * multiplier}、查克拉精华 {zq * multiplier}。",
            5,
        )

    def _apply_attribute_values(self, values: tuple[int, int, int, int], spent: int) -> None:
        """Persist one validated attribute allocation and refresh all affected UI fields."""
        with self.store.lock:
            self.character.ap_atk, self.character.ap_def, self.character.ap_dex, self.character.ap_phy = values
            self.character.remaining_ap -= spent
            self.store.save()
        self._send_attribute_stats()

    def _send_attribute_stats(self) -> None:
        """Refresh the four base attributes and remaining point count in one packet."""
        self._send_stats(
            {
                StatType.AP_ATK: self.character.ap_atk,
                StatType.AP_DEF: self.character.ap_def,
                StatType.AP_DEX: self.character.ap_dex,
                StatType.AP_PHY: self.character.ap_phy,
                StatType.AVAILABLE_AP: self.character.remaining_ap,
                **self._client_base_combat_stats(),
            }
        )

    def _base_attributes(self) -> tuple[int, int, int, int]:
        """Return persisted attack, defence, agility, and constitution values."""
        return (
            self.character.ap_atk,
            self.character.ap_def,
            self.character.ap_dex,
            self.character.ap_phy,
        )

    def _level_attribute_baseline(self) -> tuple[int, int, int, int]:
        """Return zero-based starter allocations plus one automatic point per level."""
        level_growth = max(0, self.character.level - 1)
        return (level_growth, level_growth, level_growth, level_growth)

    def handle_move(self, read_str: str) -> None:
        """Track client-authoritative movement without echoing a packet that cancels jumping."""
        if self._is_edo_controlled():
            return
        fields = self._request_fields(read_str, ClientOpcode.MOVE_PLAYER)
        if len(fields) >= 2:
            if self._has_active_skill_buff(CombatBuffType.STUN):
                return
            if (
                self._has_active_skill_buff(CombatBuffType.LOSE_JUMP)
                and len(fields) > 2
                and self._safe_int(fields[2], 0) == 2
            ):
                return
            next_x = self._safe_int(fields[0], self.x)
            next_y = self._safe_int(fields[1], self.y)
            now = time.monotonic()
            if (
                self.entered_game
                and self.last_map_change_at
                and now - self.last_map_change_at
                < self.PORTAL_TRANSITION_GUARD_SECONDS
                and (
                    abs(next_x - self.x) > self.POST_WARP_MOVE_MAX_DELTA_X
                    or abs(next_y - self.y) > self.POST_WARP_MOVE_MAX_DELTA_Y
                )
            ):
                return
            if (
                self.player_knockback_guard_until > now
                and self.player_knockback_origin is not None
            ):
                origin_x, origin_y = self.player_knockback_origin
                distance_from_landing = (next_x - self.x) ** 2 + (next_y - self.y) ** 2
                distance_from_origin = (
                    (next_x - origin_x) ** 2 + (next_y - origin_y) ** 2
                )
                # Movement samples already queued before a server-authorized
                # knockback commonly arrive after the landing packet. Ignore
                # only samples that clearly belong to that old origin; nearby
                # post-landing input remains immediately client-authoritative.
                if (
                    distance_from_origin + 80**2 < distance_from_landing
                    and distance_from_landing > 120**2
                ):
                    return
            previous_position = (self.x, self.y)
            self.x = next_x
            self.y = next_y
            if self.x != previous_position[0]:
                self.direction = 0 if self.x > previous_position[0] else 1
            self.character.x = self.x
            self.character.y = self.y
            self._record_position_sample(now)
            if self.player_knockback_guard_until and now >= self.player_knockback_guard_until:
                self.player_knockback_guard_until = 0.0
                self.player_knockback_origin = None
            if self.current_map is not None:
                current_floor = self.current_map.foothold_below(self.x, self.y)
                if current_floor is not None:
                    self.character.foothold = current_floor.foothold_id
            movement_action = self._safe_int(
                fields[2],
                PLAYER_MOVEMENT_ACTION_STAND,
            ) if len(fields) > 2 else PLAYER_MOVEMENT_ACTION_STAND
            movement_flag = self._safe_int(
                fields[5],
                PLAYER_MOVEMENT_FLAG_GROUNDED,
            ) if len(fields) > 5 else PLAYER_MOVEMENT_FLAG_GROUNDED
            self.player_movement_action = (
                movement_action
                if PLAYER_MOVEMENT_ACTION_MIN
                <= movement_action
                <= PLAYER_MOVEMENT_ACTION_MAX
                else PLAYER_MOVEMENT_ACTION_STAND
            )
            self.player_movement_flag = (
                movement_flag if 0 <= movement_flag <= 7 else PLAYER_MOVEMENT_FLAG_GROUNDED
            )
            moved = (self.x, self.y) != previous_position
            if self.healing_active and moved and not self.healing_partner_id:
                self._stop_healing(send_state=True)
            if self.hub is not None and self.entered_game:
                movement_type = self._safe_int(fields[8], 0) if len(fields) > 8 else 0
                payload = ":".join(
                    str(value)
                    for value in (
                        op(ServerOpcode.MOVE_PLAYER),
                        0,
                        self.character.character_id,
                        movement_type,
                        movement_type,
                        self.x,
                        self.y,
                        self._safe_int(fields[3], 0) if len(fields) > 3 else 0,
                        self._safe_int(fields[4], 0) if len(fields) > 4 else 0,
                        self._safe_int(fields[5], 0) if len(fields) > 5 else 0,
                        self._safe_int(fields[2], 0) if len(fields) > 2 else 0,
                        self._safe_int(fields[6], 0) if len(fields) > 6 else 0,
                        self._safe_int(fields[7], 0) if len(fields) > 7 else 0,
                    )
                )
                original_movements = getattr(
                    self,
                    "_last_original_movement_list_payload",
                    None,
                )
                for peer in self.hub.visible_peers(self):
                    if original_movements is not None and peer.wire_mode == "original":
                        peer.send_original_packet(
                            ServerOpcode.MOVE_PLAYER,
                            struct.pack(
                                "<Bi",
                                0,
                                self.character.character_id,
                            )
                            + original_movements,
                        )
                    else:
                        peer.send_text(payload)
                if original_movements is not None:
                    del self._last_original_movement_list_payload
        # Field 3 is the movement state, not direction; the local Flash physics owns it.

    def handle_stop_aggro(self, _: str) -> None:
        """Accept the client's binary stop-aggro notice and end the local combat window."""
        self.last_combat_at = 0.0

    def handle_heal_over_time(self, read_str: str) -> None:
        """Start or stop original single-player meditation and its HP/MP recovery ticks."""
        fields = self._request_fields(read_str, ClientOpcode.HEAL_OVER_TIME)
        if not fields:
            return
        try:
            action = HealAction(self._safe_int(fields[0], -1))
        except ValueError:
            return
        if action == HealAction.START:
            if self._is_dead() or self._is_in_combat():
                self._send_heal_state(HealState.STOPPED)
                return
            was_active = self.healing_active
            self.healing_active = True
            if not was_active:
                self.last_meditation_reward_at = time.monotonic()
            self._send_heal_state(HealState.SINGLE)
            if not was_active:
                self._send_dynamic_info(
                    "你获得了【单人打坐】状态。你进入了打坐状态，"
                    "每隔一段时间可以获得经验和查克拉精华。"
                )
            self._runtime_tick()
        elif action == HealAction.STOP:
            self._stop_healing(send_state=True)
        elif action == HealAction.QUERY_XINFA:
            self._send_default_xinfa()
        elif action == HealAction.CHANGE_XINFA:
            requested_id = self._safe_int(fields[1], 0) if len(fields) > 1 else 0
            if (
                requested_id in self.store.state.skills
                and GAME_DATA_CATALOG.is_xinfa_skill(requested_id)
            ):
                self.store.state.character_config["defaultXinfaId"] = requested_id
                self.store.save()
            else:
                selected_id = self._default_xinfa_id()
                if self.store.state.character_config.get("defaultXinfaId") != selected_id:
                    self.store.state.character_config["defaultXinfaId"] = selected_id
                    self.store.save()
        elif action == HealAction.DOUBLE_INVITE:
            target_id = self._safe_int(fields[1], 0) if len(fields) > 1 else 0
            target = (
                self.hub.session_for_character(target_id)
                if self.hub is not None
                else None
            )
            if (
                target is None
                or target not in self.hub.visible_peers(self)
                or self._is_dead()
                or target._is_dead()
            ):
                self.send_text(f"{op(ServerOpcode.HEAL_STATE)}:4:{target_id}")
                self._send_dynamic_info("对方不在当前地图或暂时无法双修。")
                return
            self.hub.double_heal_invites[target_id] = self.character.character_id
            target.send_text(
                f"{op(ServerOpcode.HEAL_STATE)}:2:{self.character.character_id}"
            )
            self._send_dynamic_info(f"已向{target.character.name}发送双修邀请。")
        elif action == HealAction.DOUBLE_ACCEPT:
            inviter_id = self._safe_int(fields[1], 0) if len(fields) > 1 else 0
            inviter = (
                self.hub.session_for_character(inviter_id)
                if self.hub is not None
                else None
            )
            if (
                inviter is None
                or self.hub.double_heal_invites.get(self.character.character_id)
                != inviter_id
            ):
                self.send_text(f"{op(ServerOpcode.HEAL_STATE)}:4:{inviter_id}")
                return
            self.hub.double_heal_invites.pop(self.character.character_id, None)
            now = time.monotonic()
            for participant, partner in ((self, inviter), (inviter, self)):
                participant.healing_active = True
                participant.healing_partner_id = partner.character.character_id
                participant.last_meditation_reward_at = now
                participant.double_meditation_started_at = now
            for participant, partner in ((self, inviter), (inviter, self)):
                participant.send_text(
                    f"{op(ServerOpcode.HEAL_STATE)}:1:{op(HealState.DOUBLE)}:"
                    f"{participant.character.character_id}:"
                    f"{partner.character.character_id}"
                )
                participant.send_text(
                    f"{op(ServerOpcode.HEAL_STATE)}:1:{op(HealState.DOUBLE)}:"
                    f"{partner.character.character_id}:"
                    f"{participant.character.character_id}"
                )
                participant._send_dynamic_info(
                    f"你与{partner.character.name}开始双修。"
                )
        elif action == HealAction.DOUBLE_DENY:
            target_id = self._safe_int(fields[1], 0) if len(fields) > 1 else 0
            if self.hub is not None:
                source_id = self.hub.double_heal_invites.pop(
                    self.character.character_id,
                    None,
                )
                inviter = self.hub.session_for_character(source_id or target_id)
                if inviter is not None:
                    inviter.send_text(
                        f"{op(ServerOpcode.HEAL_STATE)}:4:"
                        f"{self.character.character_id}"
                    )
            self.send_text(f"{op(ServerOpcode.HEAL_STATE)}:4:{target_id}")

    def _default_xinfa_id(self) -> int:
        """Resolve the selected learned xinfa, repairing stale saved selections."""
        configured = self._safe_int(
            self.store.state.character_config.get("defaultXinfaId"), 0
        )
        if (
            configured in self.store.state.skills
            and GAME_DATA_CATALOG.is_xinfa_skill(configured)
        ):
            return configured
        return next(
            (
                skill_id
                for skill_id in sorted(self.store.state.skills)
                if GAME_DATA_CATALOG.is_xinfa_skill(skill_id)
            ),
            0,
        )

    def _send_default_xinfa(self) -> None:
        """Open or refresh the original xinfa window with a valid learned skill."""
        selected_id = self._default_xinfa_id()
        if self.store.state.character_config.get("defaultXinfaId") != selected_id:
            self.store.state.character_config["defaultXinfaId"] = selected_id
            self.store.save()
        self.send_text(f"{op(ServerOpcode.HEAL_STATE)}:3:{selected_id}")

    def handle_char_search(self, read_str: str) -> None:
        """Return searchable account characters or visible players in original row order."""
        fields = self._request_fields(read_str, ClientOpcode.CHAR_SEARCH)
        if len(fields) < 2:
            return
        search_id = self._safe_int(fields[0], -1)
        mode = self._safe_int(fields[1], -1)
        if search_id < 0 or mode not in (1, 2):
            return
        blocked_accounts: set[int] = set()
        if self.account_id:
            account = self.accounts.account_by_id(self.account_id)
            if account is not None:
                blocked_accounts.update(
                    int(value) for value in account.get("blocked", [])
                )
            for other_account_id, _ in self.accounts.characters():
                other = self.accounts.account_by_id(other_account_id)
                if (
                    other is not None
                    and self.account_id
                    in {int(value) for value in other.get("blocked", [])}
                ):
                    blocked_accounts.add(int(other_account_id))
        candidates: list[tuple[int, dict[str, Any], FakeFlashSession | None]] = []
        if mode == 2 and self.hub is not None:
            candidates = [
                (
                    peer.account_id,
                    {
                        "id": peer.character.character_id,
                        "name": peer.character.name,
                        "level": peer.character.level,
                        "job": peer.character.job,
                    },
                    peer,
                )
                for peer in self.hub.visible_peers(self)
            ]
        else:
            query = fields[2].strip().casefold() if len(fields) > 2 else ""
            for account_id, character in self.accounts.characters():
                state = self._persisted_character_state(character)
                if state is not None:
                    character = {
                        **character,
                        "id": state.character.character_id,
                        "name": state.character.name,
                        "level": state.character.level,
                        "job": state.character.job,
                    }
                if query and query not in str(character.get("name", "")).casefold():
                    continue
                online = (
                    self.hub.session_for_character(int(character["id"]))
                    if self.hub is not None
                    else None
                )
                candidates.append((account_id, character, online))
        rows: list[str] = []
        seen_character_ids: set[int] = set()
        for account_id, character, online in candidates:
            character_id = int(character.get("id", 0))
            if (
                character_id <= 0
                or character_id in seen_character_ids
                or character_id == self.character.character_id
                or int(account_id) in blocked_accounts
            ):
                continue
            seen_character_ids.add(character_id)
            account = self.accounts.account_by_id(account_id)
            family_id = int(account.get("familyId", 0)) if account is not None else 0
            family = self.accounts.family_by_id(family_id) if family_id else None
            rows.append(
                "&".join(
                    str(value)
                    for value in (
                        online.line_id if online is not None else -1,
                        character_id,
                        int(
                            online.character.level
                            if online is not None
                            else character.get("level", 1)
                        ),
                        int(
                            online.character.job
                            if online is not None
                            else character.get("job", 300)
                        ),
                        str(character.get("name", "忍者")),
                        family_id,
                        family.get("name", "-") if family is not None else "-",
                        "-",
                    )
                )
            )
        self.send_text(
            f"{op(ServerOpcode.CHAR_SEARCH)}:{search_id}:"
            f"{'@'.join(rows) or '-'}"
        )
        if search_id == 4 and not rows:
            self._send_dynamic_info(
                "\u5f53\u524d\u5730\u56fe\u6ca1\u6709\u53ef\u53cc\u4fee\u7684\u5176\u4ed6\u73a9\u5bb6\u3002"
            )

    def _send_heal_state(self, state: HealState) -> None:
        """Update the original HealHandler using action/state/partner/character fields."""
        self.send_text(
            f"{op(ServerOpcode.HEAL_STATE)}:1:{op(state)}:"
            f"{self.character.character_id}:0"
        )

    def _stop_healing(self, send_state: bool) -> None:
        """Clear meditation and optionally tell Flash to return to its standing state."""
        was_active = self.healing_active
        partner_id = self.healing_partner_id
        self.healing_active = False
        self.healing_partner_id = 0
        self.last_meditation_reward_at = 0.0
        self.double_meditation_started_at = 0.0
        if send_state and was_active:
            self._send_heal_state(HealState.STOPPED)
            if partner_id:
                self.send_text(
                    f"{op(ServerOpcode.HEAL_STATE)}:1:{op(HealState.STOPPED)}:"
                    f"{partner_id}:0"
                )
            self._send_dynamic_info("【单人打坐】状态已消失。")
        if partner_id and self.hub is not None:
            partner = self.hub.session_for_character(partner_id)
            if (
                partner is not None
                and partner.healing_partner_id == self.character.character_id
            ):
                partner.healing_partner_id = 0
                partner.healing_active = False
                partner.last_meditation_reward_at = 0.0
                partner.double_meditation_started_at = 0.0
                partner._send_heal_state(HealState.STOPPED)
                partner.send_text(
                    f"{op(ServerOpcode.HEAL_STATE)}:1:{op(HealState.STOPPED)}:"
                    f"{self.character.character_id}:0"
                )
                partner._send_dynamic_info("双修已结束。")

    def _boss_teleport_lock_exempt(self) -> bool:
        """Match the original client's copy and battlefield exemptions."""
        return bool(
            self.active_copy_id is not None
            or self.scheduled_warfield_section
            or self.war_battle_active
            or self.war_3v3_match_id > 0
            or self.muye_battle_team in (1, 2)
            or self.local_pk_opponent_id > 0
            or self.arena_opponent is not None
        )

    def _mark_boss_combat(self, monster: MonsterState) -> None:
        """Start the original 30-second public-Boss map-change lock."""
        if self._boss_teleport_lock_exempt():
            return
        definition = GAME_DATA_CATALOG.get_monster_definition(monster.template_id)
        if definition.boss:
            self.last_boss_fight_at = time.monotonic()
            self.last_boss_fight_object_id = monster.object_id
            self.last_boss_fight_template_id = monster.template_id
            self.last_boss_fight_map_id = self.character.map_id

    def _reset_boss_teleport_lock(self) -> None:
        """Clear the complete source record for the public-Boss map lock."""
        self.last_boss_fight_at = 0.0
        self.last_boss_fight_object_id = 0
        self.last_boss_fight_template_id = 0
        self.last_boss_fight_map_id = 0

    def _clear_boss_teleport_locks_after_kill(
        self,
        monster: MonsterState,
    ) -> None:
        """Release every local fighter locked by the Boss that just died."""
        definition = GAME_DATA_CATALOG.get_monster_definition(monster.template_id)
        if not definition.boss:
            return
        sessions = [self]
        if self.hub is not None:
            with self.hub.lock:
                sessions = list(self.hub.sessions_by_character.values())
                if self not in sessions:
                    sessions.append(self)
        for session in sessions:
            if (
                not session.entered_game
                or session.line_id != self.line_id
                or session.character.map_id != self.character.map_id
            ):
                continue
            if session.last_boss_fight_map_id not in (0, self.character.map_id):
                continue
            locked_boss_still_alive = any(
                candidate.hp > 0
                and GAME_DATA_CATALOG.get_monster_definition(
                    candidate.template_id
                ).boss
                and session.last_boss_fight_object_id
                in (0, candidate.object_id)
                and session.last_boss_fight_template_id
                in (0, candidate.template_id)
                for candidate in session.monsters.values()
            )
            if locked_boss_still_alive:
                continue
            session._reset_boss_teleport_lock()

    def _boss_teleport_lock_remaining(self, now: float | None = None) -> int:
        """Return the original integer countdown, or zero when map change is legal."""
        if not self.last_boss_fight_at or self._boss_teleport_lock_exempt():
            return 0
        current_time = time.monotonic() if now is None else now
        elapsed = current_time - self.last_boss_fight_at
        if elapsed >= self.BOSS_TELEPORT_LOCK_SECONDS:
            self._reset_boss_teleport_lock()
            return 0
        return max(1, int(self.BOSS_TELEPORT_LOCK_SECONDS - elapsed))

    def _reject_boss_locked_map_change(self) -> bool:
        """Reject every server map-change entry point while fighting a public Boss."""
        remaining = self._boss_teleport_lock_remaining()
        if remaining <= 0:
            return False
        self._send_character_notice(
            f"正在与Boss战斗中，还有{remaining}秒才能切换地图"
        )
        return True

    def _mark_combat(self) -> None:
        """Reset out-of-combat recovery and cancel meditation after an attack or hit."""
        self.last_combat_at = time.monotonic()
        self._stop_healing(send_state=True)

    def _schedule_combat_save(self, now: float | None = None) -> None:
        """Coalesce hot-path HP/MP/position writes without risking logout data loss."""
        current = time.monotonic() if now is None else now
        due_at = current + self.COMBAT_SAVE_DELAY_SECONDS
        if not self.pending_combat_save_at:
            self.pending_combat_save_at = due_at
        else:
            self.pending_combat_save_at = min(self.pending_combat_save_at, due_at)

    def _accept_combat_packet(
        self,
        phase: str,
        read_str: str,
        now: float | None = None,
    ) -> bool:
        """Drop an exact short-window replay while allowing real rapid skill changes."""
        current = time.monotonic() if now is None else now
        if self.recent_combat_packets:
            self.recent_combat_packets = {
                key: expires_at
                for key, expires_at in self.recent_combat_packets.items()
                if expires_at > current
            }
        normalized = self._strip_timestamp(read_str)
        digest = hashlib.blake2s(
            normalized.encode("utf-8", errors="replace"),
            digest_size=12,
        ).digest()
        key = (phase, digest)
        if self.recent_combat_packets.get(key, 0.0) > current:
            return False
        self.recent_combat_packets[key] = (
            current + self.COMBAT_PACKET_DEDUPE_SECONDS
        )
        return True

    def _record_position_sample(self, now: float | None = None) -> None:
        """Keep a bounded movement history for server-side PVP rewind checks."""
        current = time.monotonic() if now is None else now
        sample = (
            current,
            self.x,
            self.y,
            self.character.map_id,
            self.line_id,
            self.copy_instance_id,
        )
        if (
            not self.position_history
            or self.position_history[-1][1:] != sample[1:]
            or current - self.position_history[-1][0] >= 0.05
        ):
            self.position_history.append(sample)
        cutoff = current - self.PVP_POSITION_HISTORY_SECONDS
        self.position_history = [
            value for value in self.position_history if value[0] >= cutoff
        ][-32:]

    def _validated_cast_origin(
        self,
        claimed_x: int,
        claimed_y: int,
        now: float | None = None,
    ) -> tuple[int, int]:
        """Accept a client cast origin only when it matches recent movement history."""
        current = time.monotonic() if now is None else now
        self._record_position_sample(current)
        maximum_error = self.PLAYER_ATTACK_SYNC_TOLERANCE + 120
        maximum_error_squared = maximum_error**2
        for sampled_at, sample_x, sample_y, map_id, line_id, copy_id in reversed(
            self.position_history
        ):
            if current - sampled_at > self.PVP_REWIND_WINDOW_SECONDS:
                break
            if (
                map_id == self.character.map_id
                and line_id == self.line_id
                and copy_id == self.copy_instance_id
                and (sample_x - claimed_x) ** 2 + (sample_y - claimed_y) ** 2
                <= maximum_error_squared
            ):
                return claimed_x, claimed_y
        return self.x, self.y

    def _pvp_target_position_at_cast(
        self,
        target: FakeFlashSession,
        caster_x: int,
        caster_y: int,
        maximum_distance: int,
        now: float | None = None,
    ) -> tuple[int, int] | None:
        """Find a recent target position that was in range when the cast began."""
        current = time.monotonic() if now is None else now
        target._record_position_sample(current)
        maximum_distance_squared = maximum_distance**2
        for sampled_at, target_x, target_y, map_id, line_id, copy_id in reversed(
            target.position_history
        ):
            if current - sampled_at > self.PVP_REWIND_WINDOW_SECONDS:
                break
            if (
                map_id == self.character.map_id
                and line_id == self.line_id
                and copy_id == self.copy_instance_id
                and (target_x - caster_x) ** 2 + (target_y - caster_y) ** 2
                <= maximum_distance_squared
            ):
                return target_x, target_y
        return None

    def _settle_due_pvp_hits(self, now: float | None = None) -> None:
        """Settle authorized PVP hits even when the victim's report is delayed or lost."""
        current = time.monotonic() if now is None else now
        due: list[tuple[int, PendingPvpHit]] = []
        with self.combat_lock:
            for attacker_id, pending_hits in self.pending_pvp_hits.items():
                for pending in pending_hits:
                    if pending.server_settle_at <= current < pending.expires_at:
                        due.append((attacker_id, pending))
        for attacker_id, pending in due[:16]:
            with self.combat_lock:
                live_hits = self.pending_pvp_hits.get(attacker_id, ())
                if pending not in live_hits:
                    continue
            direction = 1 if pending.target_x >= pending.attacker_x else -1
            self.handle_player_damage(
                f"{op(ClientOpcode.PLAYER_DAMAGE)}:{attacker_id}:0:0:"
                f"{pending.skill_id}:{pending.skill_level}:true:{direction}"
            )

    def _is_in_combat(self, now: float | None = None) -> bool:
        """Return whether the configured post-combat recovery delay is still active."""
        current_time = time.monotonic() if now is None else now
        return bool(
            self.last_combat_at
            and current_time - self.last_combat_at < self.OUT_OF_COMBAT_SECONDS
        )

    def _runtime_tick(self, *, allow_original: bool = False) -> None:
        """Restore HP/MP after combat while preserving the explicit meditation protocol."""
        now = time.monotonic()
        self._tick_welcome_announcement(now)
        if self.entered_game and now >= self._auto_sell_next_check_at:
            self._auto_sell_next_check_at = now + AUTO_SELL_CHECK_INTERVAL_SECONDS
            self._run_auto_sell()
        self._tick_pending_edo_prompt(now)
        self._tick_edo_tensei_control(now)
        self._tick_shadow_clones(now)
        self._tick_flying_raijin_mark(now)
        self._tick_auto_consume_effects(now)
        if self.pending_monster_hits:
            self.pending_monster_hits = {
                object_id: [
                    claim for claim in claims if claim.expires_at > now
                ]
                for object_id, claims in self.pending_monster_hits.items()
                if any(claim.expires_at > now for claim in claims)
            }
        with self.combat_lock:
            if self.pending_pvp_hits:
                self.pending_pvp_hits = {
                    attacker_id: [
                        pending for pending in hits if pending.expires_at > now
                    ]
                    for attacker_id, hits in self.pending_pvp_hits.items()
                    if any(pending.expires_at > now for pending in hits)
                }
        self._settle_due_pvp_hits(now)
        if self.preconsumed_skill_casts:
            self.preconsumed_skill_casts = {
                skill_id: [
                    expires_at for expires_at in casts if expires_at > now
                ]
                for skill_id, casts in self.preconsumed_skill_casts.items()
                if any(expires_at > now for expires_at in casts)
            }
        if self.announced_skill_replay_acks:
            self.announced_skill_replay_acks = {
                skill_id: expires_at
                for skill_id, expires_at in self.announced_skill_replay_acks.items()
                if expires_at > now
            }
        if self.pending_combat_save_at and now >= self.pending_combat_save_at:
            self.pending_combat_save_at = 0.0
            self.store.save()
        if self.entered_game:
            self._flush_pending_drop_publications()
            self._expire_map_drops(now)
        if (
            self.pending_walk_speed_refresh_at
            and now >= self.pending_walk_speed_refresh_at
        ):
            self.pending_walk_speed_refresh_at = 0.0
            self._send_stats({StatType.WALK_SPEED: self._current_walk_speed()})
        if (
            self.pending_weather_refresh_at
            and now >= self.pending_weather_refresh_at
        ):
            self._refresh_weather(force=True)
            self.pending_weather_refresh_attempts = max(
                0, self.pending_weather_refresh_attempts - 1
            )
            if self.pending_weather_refresh_attempts:
                self.pending_weather_refresh_at = now + 0.75
            else:
                self.pending_weather_refresh_at = 0.0
        if (
            self.pending_persistent_status_replay_at
            and now >= self.pending_persistent_status_replay_at
        ):
            self.pending_persistent_status_replay_at = 0.0
            self._send_persistent_status_replay()
        if self.entered_game:
            self._send_system_activity_buffs()
            self._expire_spirit_panel_items(notify=True)
        # These timers are native-client bootstrap work, not part of the
        # Ruffle-oriented periodic simulation below.  They must run before the
        # original-wire early return or active loop/escort quests can remain in
        # QuestDataManager while never reaching the late-created tracker window.
        if (
            self.pending_quest_list_replay_at
            and now >= self.pending_quest_list_replay_at
        ):
            self._send_original_quest_lists()
            self.pending_quest_list_replay_attempts = max(
                0, self.pending_quest_list_replay_attempts - 1
            )
            if self.pending_quest_list_replay_attempts:
                self.pending_quest_list_replay_at = (
                    now + self.QUEST_LIST_BOOTSTRAP_REPLAY_INTERVAL
                )
            else:
                self.pending_quest_list_replay_at = 0.0
        if (
            self.pending_quest_notifications_at
            and now >= self.pending_quest_notifications_at
        ):
            quest_ids = self.pending_quest_notifications
            self.pending_quest_notifications = []
            self.pending_quest_notifications_at = 0.0
            for quest_id in quest_ids:
                self._send_original_quest_started_notification(quest_id)
        if (
            self.pending_tower_hud_replay_at
            and now >= self.pending_tower_hud_replay_at
        ):
            self._send_tower_hud_state()
            self.pending_tower_hud_replay_attempts = max(
                0, self.pending_tower_hud_replay_attempts - 1
            )
            if self.pending_tower_hud_replay_attempts:
                self.pending_tower_hud_replay_at = (
                    now + self.TOWER_HUD_REPLAY_INTERVAL
                )
            else:
                self.pending_tower_hud_replay_at = 0.0
        if self.entered_game:
            self._tick_tower_challenge()
        # Arena snapshots are server-owned actors and must continue to tick for
        # native Flash sessions before the original-wire early return below.
        self._tick_arena()
        if self.wire_mode == "original" and not allow_original:
            # Native Flash does not need the Ruffle-oriented periodic replay loop,
            # but server-authored multi-phase skills must still advance while the
            # socket is idle. Keep this narrow so monster AI and timed rewards are
            # not processed twice by native and shared-world sessions.
            if self.entered_game and (
                self.hub is None or self.hub.claim_monster_control(self)
            ):
                self._refresh_monster_if_due()
                self._tick_server_monsters(now)
            return
        self._flush_pending_tutorials()
        if self.pending_social_replay_at and now >= self.pending_social_replay_at:
            self.pending_social_replay_at = 0.0
            self._send_pending_social_cues()
        if self.pending_peer_snapshot_at and now >= self.pending_peer_snapshot_at:
            self.pending_peer_snapshot_at = 0.0
            if self.hub is not None and self.entered_game:
                for peer in self.hub.visible_peers(self):
                    self._send_foreign_player(peer)
        if self.entered_game:
            self._resolve_pending_mai_explosion()
        if (
            self.pending_copy_id is not None
            and self.pending_copy_enter_at
            and now >= self.pending_copy_enter_at
        ):
            self._enter_pending_copy()
        self._flush_pending_monster_kills()
        self._refresh_monster_if_due()
        self._tick_server_monsters()
        self._tick_hero_copy(now)
        self._tick_copy_objectives(now)
        self._tick_xiulian(now)
        self._refresh_vip_entitlement()
        self._refresh_active_item_effects()
        self._tick_player_skill_statuses(int(time.time() * 1_000))
        self._refresh_active_skill_buffs()
        self._refresh_lianzhan(now)
        if self.entered_game:
            self._sync_scheduled_events()
            self._refresh_scheduled_map_bgm_config()
        self._refresh_weather()
        self._tick_revive()
        self._tick_muye_battle()
        self._tick_local_pk()
        self._tick_war_3v3()
        self._tick_war_battle()
        self._tick_chunin()
        self._expire_artifact_ownership()
        self._tick_scheduled_warfield()
        if self.entered_game:
            self._tick_crime_decay(now)
            self._tick_online_duration_reward(now)
            self._tick_activity_online(now)
            if now - self.last_editor_timer_at >= 1.0:
                self.last_editor_timer_at = now
                self._trigger_editor_events("定时器", {"online_seconds": round(now - self.session_started_at)})
            if now - self.last_achievement_refresh_at >= 1.0:
                self.last_achievement_refresh_at = now
                self._refresh_achievement_completion_notices(notify=True)
        if not self.entered_game or self._is_dead():
            return
        if self._is_in_combat(now):
            return
        self._tick_meditation_rewards(now)
        if now - self.last_recovery_at < self.RECOVERY_INTERVAL_SECONDS:
            return
        self.last_recovery_at = now
        maximum_hp = self._current_max_hp()
        maximum_mp = self._current_max_mp()
        hp_gain = max(1, maximum_hp * self.RECOVERY_PERCENT // 100)
        mp_gain = max(1, maximum_mp * self.RECOVERY_PERCENT // 100)
        next_hp = min(maximum_hp, self.character.hp + hp_gain)
        next_mp = min(maximum_mp, self.character.mp + mp_gain)
        updates: dict[StatType, int] = {}
        with self.store.lock:
            if next_hp != self.character.hp:
                self.character.hp = next_hp
                updates[StatType.HP] = next_hp
            if next_mp != self.character.mp:
                self.character.mp = next_mp
                updates[StatType.MP] = next_mp
            if updates:
                self.store.save()
        if updates:
            self._send_stats(updates)

    def _welcome_announcement_repeat_seconds(self) -> float:
        """Return the hot-reloadable interval for the recurring anti-piracy notice."""
        configured = EDITOR_RUNTIME.number(
            "game_texts",
            "welcome",
            "repeatIntervalSeconds",
            WELCOME_ANNOUNCEMENT_REPEAT_SECONDS,
        )
        return max(30.0, min(configured, 24 * 60 * 60))

    def _tick_welcome_announcement(self, now: float) -> None:
        """Replay the anti-piracy marquee while the character remains in game."""
        if (
            not self.entered_game
            or not self.next_welcome_announcement_at
            or now < self.next_welcome_announcement_at
        ):
            return
        welcome = EDITOR_RUNTIME.text("welcome", WELCOME_ANNOUNCEMENT_DEFAULT)
        if not welcome:
            self.next_welcome_announcement_at = 0.0
            return
        self._send_scrolled_announcement(welcome)
        self.next_welcome_announcement_at = (
            now + self._welcome_announcement_repeat_seconds()
        )

    def _tick_xiulian(self, now: float) -> None:
        if self.active_copy_id != self.XIULIAN_COPY_ID or not self.xiulian_running:
            return
        elapsed = now - self.xiulian_started_at
        if elapsed >= self.xiulian_duration:
            self.xiulian_running = False
            stats = self._xiulian_stats(now)
            self._send_xiulian_action(2, stats)
            self._send_xiulian_action(
                3,
                {
                    **stats,
                    "summary": f"总伤害 {self.xiulian_total_damage:,} / DPS {stats['dps']:,.1f}",
                },
            )
            return
        if now - self.xiulian_last_push_at >= 1.0:
            self.xiulian_last_push_at = now
            self._send_xiulian_action(1, self._xiulian_stats(now))

    def _tick_copy_objectives(self, now: float) -> None:
        """Advance server-owned defence failures and hidden treasure completion."""
        members = self._active_copy_members()
        if members and min(
            member.character.character_id for member in members
        ) != self.character.character_id:
            return
        if (
            self.active_copy_finished
            and self.active_copy_exit_at
            and now >= self.active_copy_exit_at
        ):
            for member in members:
                member._leave_active_copy()
            return
        if (
            self.active_copy_id == 9
            and not self.active_copy_finished
            and now - self.active_copy_last_objective_tick >= 0.5
        ):
            self.active_copy_last_objective_tick = now
            escort = self.monsters.get(6_900)
            if escort is None or escort.hp <= 0:
                self._fail_active_copy("护送目标倒下，副本失败。")
                return
            current_x, current_y = self._settle_monster_motion(escort, now)
            delta_x = escort.target_x - current_x
            delta_y = escort.target_y - current_y
            if abs(delta_x) <= 80 and abs(delta_y) <= 80:
                escort.x, escort.y = escort.target_x, escort.target_y
                self._broadcast_server_monster_stop(escort, now)
                for member in members:
                    member._complete_active_copy()
                return
            distance = max(1.0, math.hypot(delta_x, delta_y))
            step = min(90.0, distance)
            destination_x = round(current_x + delta_x * step / distance)
            destination_y = round(current_y + delta_y * step / distance)
            self._broadcast_server_monster_move(
                escort,
                destination_x,
                destination_y,
                500,
                now,
            )
            return
        objective_interval = 0.2 if self.active_copy_id == 4 else 0.5
        if (
            self.active_copy_id not in {3, 4}
            or self.active_copy_finished
            or now - self.active_copy_last_objective_tick < objective_interval
        ):
            return
        self.active_copy_last_objective_tick = now
        if self.active_copy_next_wave_at:
            if now >= self.active_copy_next_wave_at:
                self.active_copy_next_wave_at = 0.0
                self._spawn_next_copy_wave(members)
            return
        escaped: MonsterState | None = None
        for monster in self.monsters.values():
            if (
                monster.hp <= 0
                or monster.target_x == 0
                or monster.attack_animation_until > now
                or monster.knockback_until > now
                or self._monster_status_blocks_action(monster)
            ):
                continue
            current_x, current_y = self._settle_monster_motion(monster, now)
            delta_x = monster.target_x - current_x
            delta_y = monster.target_y - current_y
            if abs(delta_x) <= 70 and abs(delta_y) <= 90:
                self._broadcast_server_monster_stop(monster, now)
                escaped = monster
                break
            distance = max(1.0, math.hypot(delta_x, delta_y))
            step = min(float(self._monster_move_step(monster)), distance)
            self._broadcast_server_monster_move(
                monster,
                round(current_x + delta_x * step / distance),
                round(current_y + delta_y * step / distance),
                500,
                now,
            )
        if escaped is None:
            return
        escaped.hp = 0
        escaped.respawn_at = float("inf")
        self._send_visible(
            f"{op(ServerOpcode.KILL_MONSTER)}:{escaped.object_id}:"
            f"{op(MonsterRemovalAnimation.IMMEDIATE)}"
        )
        if self.active_copy_id == 3:
            self.active_copy_miss_count += 1
            if self.active_copy_miss_count >= 100:
                self._fail_active_copy("已有100名敌人进入木叶村，守卫失败。")
                return
        else:
            remaining_hp = max(0, self.active_copy_protect_hp - 1)
            for member in members:
                member.active_copy_protect_hp = remaining_hp
                member._send_system_chat(
                    f"鸣人还剩余{remaining_hp}/500点血量。"
                )
            if self.active_copy_protect_hp <= 0:
                self._fail_active_copy("鸣人保护值耗尽，秽土转生副本失败。")
                return
        self._record_copy_kill()

    def _monster_world_sessions(self) -> list[FakeFlashSession]:
        """Return the live recipients that share this map instance's monsters."""
        if self.hub is None:
            return [self] if self.entered_game else []
        return self.hub.monster_world_sessions(self)

    def _monster_broadcast_sessions(self, monster: MonsterState) -> list[FakeFlashSession]:
        """Return live sessions close enough to receive one monster movement."""
        participants: list[FakeFlashSession] = []
        for participant in self._monster_world_sessions():
            if getattr(participant, "server_simulated", False):
                continue
            if self.arena_monster is monster and participant is self:
                participants.append(participant)
                continue
            if (
                abs(participant.x - monster.x) > self.MONSTER_MOVE_BROADCAST_RANGE
                or abs(participant.y - monster.y) > self.MONSTER_MOVE_BROADCAST_RANGE
            ):
                continue
            participants.append(participant)
        return participants

    @staticmethod
    def _short_coordinate(value: int) -> int:
        return max(-0x8000, min(0x7FFF, int(value)))

    def _monster_safe_walk_bounds(
        self,
        floor: FootholdState,
    ) -> tuple[int, int]:
        """Keep velocity-driven clients far enough from an unsupported edge."""
        width = max(0, floor.right - floor.left)
        margin = min(self.MONSTER_EDGE_MARGIN, width // 4)
        left = floor.left + margin
        right = floor.right - margin
        if left > right:
            left = right = (floor.left + floor.right) // 2
        return left, right

    def _clamp_monster_walk_x(self, floor: FootholdState, x: int) -> int:
        left, right = self._monster_safe_walk_bounds(floor)
        return max(left, min(right, int(x)))

    def _broadcast_server_monster_move(
        self,
        monster: MonsterState,
        destination_x: int,
        destination_y: int,
        duration_ms: int,
        now: float | None = None,
    ) -> None:
        """Publish one Nya-style absolute movement sample and advance server state."""
        current = time.monotonic() if now is None else now
        # A new command may be issued while the previous server-side tween is
        # still settling. Anchor the next fragment at the rendered position,
        # otherwise the old destination is sent as the new start and the Flash
        # client visibly snaps backwards.
        self._settle_monster_motion(monster, current, force=True)
        start_x = self._short_coordinate(monster.x)
        start_y = self._short_coordinate(monster.y)
        destination_x = self._short_coordinate(destination_x)
        destination_y = self._short_coordinate(destination_y)
        duration_ms = max(100, min(0xFFFF, int(duration_ms)))
        direction = 1 if destination_x >= start_x else -1
        velocity_x = self._short_coordinate(
            direction * self._monster_walk_velocity(monster)
        )
        # Nya's absolute ground fragments always use flag=2 and velocity_y=0.
        # The client follows the authored foothold for slope height; encoding the
        # slope delta as vertical velocity makes gravity fight the foothold solver
        # and repeatedly launches otherwise grounded monsters into the air.
        velocity_y = 0
        # Monster.status uses (MobAction << 1) | direction, not the generic
        # player walk constants. 3 is stand-left for a monster, which made the
        # client translate the model while holding its idle animation.
        movement_status = 6 if direction > 0 else 7
        motion_signature = (velocity_x, velocity_y, 3, monster.foothold)
        # TCP already preserves every velocity transition. Re-sending an
        # absolute sample during the same walk makes the client visibly snap to
        # the server's quantized position. Only publish when velocity, action,
        # direction, or foothold changes; a newly joined observer has no
        # signature and therefore still receives the current movement at once.
        participants = [
            participant
            for participant in self._monster_broadcast_sessions(monster)
            if participant.monster_motion_signatures.get(monster.object_id)
            != motion_signature
        ]
        if participants:
            monster.move_sequence = (monster.move_sequence + 1) & 0xFFFF
            payload = bytearray(
                struct.pack(
                    "<BiHBBhhB",
                    0,
                    monster.object_id,
                    monster.move_sequence,
                    0,
                    0,
                    0,
                    0,
                    1,
                )
            )
            payload.extend(
                struct.pack(
                    "<BhhhhHBHH",
                    0,
                    start_x,
                    start_y,
                    velocity_x,
                    velocity_y,
                    2,
                    movement_status,
                    0,
                    max(0, min(0xFFFF, monster.foothold)),
                )
            )
            text_payload = ":".join(
                str(value)
                for value in (
                    op(ServerOpcode.MOVE_MONSTER),
                    0,
                    monster.object_id,
                    0,
                    0,
                    start_x,
                    start_y,
                    velocity_x,
                    velocity_y,
                    2,
                    movement_status,
                    0,
                    monster.foothold,
                    monster.move_sequence,
                    0,
                    0,
                    0,
                    0,
                )
            )
            for participant in participants:
                if participant.wire_mode == "original":
                    participant.send_original_packet(
                        ServerOpcode.MOVE_MONSTER,
                        bytes(payload),
                    )
                else:
                    participant.send_text(text_payload)
                participant.monster_motion_signatures[monster.object_id] = (
                    motion_signature
                )
            monster.last_movement_broadcast_at = current
        monster.client_velocity_x = velocity_x
        monster.client_velocity_y = velocity_y
        monster.client_movement_action = 3
        monster.client_foothold = monster.foothold
        monster.motion_origin_x = start_x
        monster.motion_origin_y = start_y
        monster.motion_destination_x = destination_x
        monster.motion_destination_y = destination_y
        monster.motion_started_at = current
        monster.motion_ends_at = current + duration_ms / 1_000
        monster.facing_right = direction > 0
        monster.x = destination_x
        monster.y = destination_y

    def _broadcast_server_monster_teleport(
        self,
        monster: MonsterState,
        destination_x: int,
        destination_y: int,
        destination_foothold: int,
        now: float | None = None,
    ) -> None:
        """Use Nya's instant path transition for jump/climb path-finder joints."""
        current = time.monotonic() if now is None else now
        start_x, start_y = self._settle_monster_motion(monster, current, force=True)
        start_x = self._short_coordinate(start_x)
        start_y = self._short_coordinate(start_y)
        destination_x = self._short_coordinate(destination_x)
        destination_y = self._short_coordinate(destination_y)
        monster.move_sequence = (monster.move_sequence + 1) & 0xFFFF
        payload = bytearray(
            struct.pack(
                "<BiHBBhhB",
                0,
                monster.object_id,
                monster.move_sequence,
                0,
                0,
                start_x,
                start_y,
                    2,
                )
            )
        # MovementType.TELEPORT (14) has no duration or foothold fields. The
        # following ground fragment will publish the new authoritative foothold.
        payload.extend(
            struct.pack(
                "<BhhhhB",
                14,
                destination_x,
                destination_y,
                0,
                0,
                2,
            )
        )
        # TeleportMovement does not update grounded/foothold state in the
        # client command controller. Follow it with a normal ground fragment so
        # ladder/path transitions cannot leave a monster airborne.
        payload.extend(
            struct.pack(
                "<BhhhhHBHH",
                0,
                destination_x,
                destination_y,
                0,
                0,
                2,
                6 if monster.facing_right else 7,
                0,
                max(0, min(0xFFFF, destination_foothold)),
            )
        )
        text_payload = ":".join(
            str(value)
            for value in (
                op(ServerOpcode.MOVE_MONSTER),
                0,
                monster.object_id,
                14,
                14,
                destination_x,
                destination_y,
                0,
                0,
                2,
                6 if monster.facing_right else 7,
                0,
                destination_foothold,
                monster.move_sequence,
                0,
                0,
                destination_x,
                destination_y,
            )
        )
        text_ground_payload = ":".join(
            str(value)
            for value in (
                op(ServerOpcode.MOVE_MONSTER),
                0,
                monster.object_id,
                0,
                0,
                destination_x,
                destination_y,
                0,
                0,
                2,
                6 if monster.facing_right else 7,
                0,
                destination_foothold,
                monster.move_sequence,
                0,
                0,
                destination_x,
                destination_y,
            )
        )
        for participant in self._monster_broadcast_sessions(monster):
            if participant.wire_mode == "original":
                participant.send_original_packet(ServerOpcode.MOVE_MONSTER, bytes(payload))
            else:
                participant.send_text(text_payload)
                participant.send_text(text_ground_payload)
            participant.monster_motion_signatures[monster.object_id] = (
                0,
                0,
                1,
                destination_foothold,
            )
        monster.x = destination_x
        monster.y = destination_y
        monster.foothold = destination_foothold
        monster.motion_origin_x = destination_x
        monster.motion_origin_y = destination_y
        monster.motion_destination_x = destination_x
        monster.motion_destination_y = destination_y
        monster.motion_started_at = 0.0
        monster.motion_ends_at = 0.0
        monster.client_velocity_x = 0
        monster.client_velocity_y = 0
        monster.client_movement_action = 1
        monster.client_foothold = monster.foothold
        monster.last_movement_broadcast_at = current
        monster.movement_distance_remainder = 0.0

    def _monster_render_position(
        self,
        monster: MonsterState,
        now: float | None = None,
    ) -> tuple[int, int]:
        """Predict the continuously moving client, including delayed server ticks."""
        current = time.monotonic() if now is None else now
        if monster.motion_ends_at <= monster.motion_started_at:
            return monster.x, monster.y
        if current >= monster.motion_ends_at:
            destination_x = monster.motion_destination_x
            destination_y = monster.motion_destination_y
            if monster.client_movement_action == 3 and monster.client_velocity_x:
                # A delayed socket/runtime tick does not stop the Flash client: it
                # keeps integrating the last velocity. Catch the authoritative
                # prediction up before issuing the next action, otherwise every
                # stop/attack packet visibly pulls the monster backwards.
                elapsed = min(
                    self.MONSTER_MOVE_CATCHUP_MAX_SECONDS,
                    max(0.0, current - monster.motion_ends_at),
                )
                if elapsed >= 0.001:
                    direction = 1 if monster.client_velocity_x > 0 else -1
                    destination_x += round(
                        direction
                        * self._monster_client_walk_velocity(monster)
                        * elapsed
                    )
                    floor = (
                        self.current_map.footholds.get(monster.foothold)
                        if self.current_map is not None
                        else None
                    )
                    if floor is not None:
                        safe_left, safe_right = self._monster_safe_walk_bounds(floor)
                        # Patrol and same-platform chase destinations are authored
                        # inside the safe bounds. A Boss path transition may
                        # deliberately target the physical joint outside them;
                        # allow that explicit command to reach the adjacent edge.
                        if not safe_left <= monster.motion_destination_x <= safe_right:
                            destination_x = max(
                                floor.left,
                                min(floor.right, destination_x),
                            )
                        else:
                            destination_x = max(
                                safe_left,
                                min(safe_right, destination_x),
                            )
                        destination_y = floor.y_at(destination_x)
            return destination_x, destination_y
        if current <= monster.motion_started_at:
            return monster.motion_origin_x, monster.motion_origin_y
        ratio = (current - monster.motion_started_at) / (
            monster.motion_ends_at - monster.motion_started_at
        )
        return (
            round(
                monster.motion_origin_x
                + (monster.motion_destination_x - monster.motion_origin_x) * ratio
            ),
            round(
                monster.motion_origin_y
                + (monster.motion_destination_y - monster.motion_origin_y) * ratio
            ),
        )

    def _settle_monster_motion(
        self,
        monster: MonsterState,
        now: float | None = None,
        *,
        force: bool = False,
    ) -> tuple[int, int]:
        """Commit a finished tween, or stop an active tween at its rendered point."""
        current = time.monotonic() if now is None else now
        position = self._monster_render_position(monster, current)
        if force or (monster.motion_ends_at and current >= monster.motion_ends_at):
            monster.x, monster.y = position
            monster.motion_started_at = 0.0
            monster.motion_ends_at = 0.0
        return position

    def _begin_monster_knockback(
        self,
        monster: MonsterState,
        *,
        source_x: int,
        skill_level: int,
        normal_knockback: bool = False,
        distance_pixels: int | None = None,
        now: float | None = None,
    ) -> bool:
        """Pause server AI while the client renders an authored knockback."""
        definition = GAME_DATA_CATALOG.get_monster_definition(monster.template_id)
        if (
            monster.hp <= 0
            or monster.immobile
            or definition.boss
            or self._is_wealth_mouse_family(monster.template_id)
        ):
            return False
        current = time.monotonic() if now is None else now
        monster_x, monster_y = self._settle_monster_motion(monster, current, force=True)
        self._broadcast_server_monster_stop(monster, current)
        distance = abs(monster_x - source_x)
        if normal_knockback:
            velocity_x, velocity_y = 160, 450
        elif distance < 50:
            velocity_x, velocity_y = 200, 1_200
        elif distance < 100:
            velocity_x, velocity_y = 600, 1_000
        else:
            velocity_x, velocity_y = 1_000, 800
        growth_scale = (
            1.0
            if normal_knockback
            else min(160.0, 80.0 + max(1, skill_level) * 0.62) / 120.0
        )
        velocity_x = round(velocity_x * growth_scale)
        velocity_y = round(velocity_y * growth_scale)
        flight_seconds = (
            0.45
            if distance_pixels is not None
            else (
                0.75
                if normal_knockback
                else max(0.65, min(1.60, 2.0 * velocity_y / 2_000.0))
            )
        )
        direction = 1 if distance == 0 else (1 if monster_x > source_x else -1)
        travel_distance = (
            max(0, distance_pixels)
            if distance_pixels is not None
            else round(velocity_x * flight_seconds)
        )
        destination_x = monster_x + direction * travel_distance
        floor = (
            self.current_map.footholds.get(monster.foothold)
            if self.current_map is not None
            else None
        )
        if floor is not None:
            destination_x = self._clamp_monster_walk_x(floor, destination_x)
            destination_y = round(floor.y_at(destination_x))
        else:
            destination_y = monster_y
        monster.knockback_until = current + flight_seconds
        monster.knockback_target_x = self._short_coordinate(destination_x)
        monster.knockback_target_y = self._short_coordinate(destination_y)
        monster.knockback_report_x = monster_x
        monster.knockback_report_y = monster_y
        monster.knockback_reported = False
        monster.next_move_at = monster.knockback_until + 0.25
        return True

    def _finish_monster_knockback(
        self,
        monster: MonsterState,
        now: float | None = None,
    ) -> None:
        """Commit the client-reported landing, with an authored physics fallback."""
        current = time.monotonic() if now is None else now
        destination_x = (
            monster.knockback_report_x
            if monster.knockback_reported
            else monster.knockback_target_x
        )
        floor = (
            self.current_map.footholds.get(monster.foothold)
            if self.current_map is not None
            else None
        )
        if floor is not None:
            destination_x = self._clamp_monster_walk_x(floor, destination_x)
            destination_y = round(floor.y_at(destination_x))
        else:
            destination_y = (
                monster.knockback_report_y
                if monster.knockback_reported
                else monster.knockback_target_y
            )
        monster.x = self._short_coordinate(destination_x)
        monster.y = self._short_coordinate(destination_y)
        monster.motion_origin_x = monster.x
        monster.motion_origin_y = monster.y
        monster.motion_destination_x = monster.x
        monster.motion_destination_y = monster.y
        monster.motion_started_at = 0.0
        monster.motion_ends_at = 0.0
        monster.knockback_until = 0.0
        monster.knockback_reported = False
        self._broadcast_server_monster_stop(monster, current)

    def _broadcast_server_monster_stop(
        self,
        monster: MonsterState,
        now: float | None = None,
    ) -> None:
        """Stop interpolation and repair observers that missed the idle stance."""
        idle_signature = (0, 0, 1, monster.foothold)
        recipients = [
            participant
            for participant in self._monster_broadcast_sessions(monster)
            if participant.monster_motion_signatures.get(monster.object_id)
            != idle_signature
        ]
        already_idle = (
            monster.client_velocity_x == 0
            and monster.client_velocity_y == 0
            and monster.client_movement_action == 1
            and monster.client_foothold == monster.foothold
        )
        # MonsterState is shared by everyone in an instance, while the last
        # rendered movement packet is not. A player entering/reloading after a
        # monster has stopped has no local signature yet; skipping on the
        # shared state alone leaves that client looping its last run animation.
        if already_idle and not recipients:
            return
        self._broadcast_server_monster_action(
            monster,
            1,
            now,
            participants=recipients,
        )

    def _broadcast_server_monster_action(
        self,
        monster: MonsterState,
        action: int,
        now: float | None = None,
        *,
        participants: Iterable[FakeFlashSession] | None = None,
    ) -> None:
        """Publish a stationary native monster stance at the authoritative position."""
        current = time.monotonic() if now is None else now
        self._settle_monster_motion(monster, current, force=True)
        position_x = self._short_coordinate(monster.x)
        position_y = self._short_coordinate(monster.y)
        movement_status = (max(0, min(0x7F, action)) << 1) | (
            0 if monster.facing_right else 1
        )
        monster.move_sequence = (monster.move_sequence + 1) & 0xFFFF
        payload = bytearray(
            struct.pack(
                "<BiHBBhhB",
                0,
                monster.object_id,
                monster.move_sequence,
                0,
                0,
                position_x,
                position_y,
                1,
            )
        )
        payload.extend(
            struct.pack(
                "<BhhhhHBHH",
                0,
                position_x,
                position_y,
                0,
                0,
                2,
                movement_status,
                0,
                max(0, min(0xFFFF, monster.foothold)),
            )
        )
        text_payload = ":".join(
            str(value)
            for value in (
                op(ServerOpcode.MOVE_MONSTER),
                0,
                monster.object_id,
                0,
                0,
                position_x,
                position_y,
                0,
                0,
                2,
                movement_status,
                0,
                monster.foothold,
                monster.move_sequence,
                0,
                0,
                position_x,
                position_y,
            )
        )
        recipients = (
            self._monster_broadcast_sessions(monster)
            if participants is None
            else list(participants)
        )
        for participant in recipients:
            if participant.wire_mode == "original":
                participant.send_original_packet(ServerOpcode.MOVE_MONSTER, bytes(payload))
            else:
                participant.send_text(text_payload)
            participant.monster_motion_signatures[monster.object_id] = (
                0,
                0,
                action,
                monster.foothold,
            )
        monster.client_velocity_x = 0
        monster.client_velocity_y = 0
        monster.client_movement_action = action
        monster.client_foothold = monster.foothold
        monster.last_movement_broadcast_at = current
        monster.movement_distance_remainder = 0.0

    def _monster_walk_velocity(self, monster: MonsterState) -> int:
        """Return Nya's captured velocity derived directly from authored Mob speed."""
        definition = GAME_DATA_CATALOG.get_monster_definition(monster.template_id)
        slow = self._monster_status_value(monster, "slow")
        fixed_slow = self._monster_status_value(monster, "fix_slow")
        speed_factor = 0.7 if fixed_slow > 0 else max(0.0, (100.0 - slow) / 100.0)
        authored_velocity = (
            self.MONSTER_BASE_WALK_SPEED
            * self.MONSTER_WALK_SPEED_FACTOR
            * definition.speed
            * speed_factor
            / 100
        )
        return max(1, round(authored_velocity))

    def _monster_move_step(self, monster: MonsterState) -> int:
        """Advance by the same quantized distance the 36 FPS client renders."""
        return max(
            0,
            round(
                self._monster_client_walk_velocity(monster)
                * self.MONSTER_MOVE_INTERVAL_SECONDS
            ),
        )

    def _consume_monster_move_step(self, monster: MonsterState) -> int:
        """Preserve fractional client-rendered distance between server AI ticks."""
        client_velocity = self._monster_client_walk_velocity(monster)
        if client_velocity <= 0:
            monster.movement_distance_remainder = 0.0
            return 0
        exact_distance = (
            client_velocity * self.MONSTER_MOVE_INTERVAL_SECONDS
            + monster.movement_distance_remainder
        )
        distance = max(0, int(exact_distance))
        remainder = max(0.0, exact_distance - distance)
        monster.movement_distance_remainder = 0.0 if remainder < 1e-9 else remainder
        return distance

    def _monster_client_walk_velocity(self, monster: MonsterState) -> int:
        """Predict Flash's integer-per-frame displacement for server reconciliation."""
        velocity = abs(self._monster_walk_velocity(monster))
        frame_rate = max(1, int(self.NYA_MAIN_FRAME_RATE))
        short_frame_ms, long_frame_count = divmod(1_000, frame_rate)
        short_frame_count = frame_rate - long_frame_count
        long_frame_ms = short_frame_ms + 1
        # AbstractPhysicObject.applyVelocity floors/ceils x after every frame.
        # Reproduce that loss here instead of correcting the client at each stop.
        return (
            short_frame_count * (velocity * short_frame_ms // 1_000)
            + long_frame_count * (velocity * long_frame_ms // 1_000)
        )

    @staticmethod
    def _monster_status_value(monster: MonsterState, *effect_types: str) -> float:
        """Return the strongest live percentage for one server-owned monster status."""
        requested = set(effect_types)
        now = time.monotonic()
        return max(
            (
                float(payload.get("value") or 0)
                for effect_type, payload in monster.skill_statuses.items()
                if effect_type in requested
                and float(payload.get("expires_at") or 0) > now
            ),
            default=0.0,
        )

    def _send_monster_status(
        self,
        monster: MonsterState,
        effect_type: str,
        payload: dict[str, int | float],
    ) -> None:
        """Show one authoritative monster Debuff through the original icon protocol."""
        buff_type = COMBAT_DEBUFF_TYPE_BY_EFFECT.get(effect_type)
        if buff_type is None:
            return
        duration_ms = max(
            1,
            round((float(payload.get("expires_at") or 0) - time.monotonic()) * 1_000),
        )
        value = float(payload.get("value") or 0) / 100.0
        self._send_visible(
            f"{op(ServerOpcode.APPLY_MONSTER_STATUS)}:{monster.object_id}:"
            f"{op(buff_type)}&{format(value, '.6g')}&"
            f"{self._safe_int(payload.get('skill_id'), 0)}&"
            f"{max(1, self._safe_int(payload.get('skill_level'), 1))}&"
            f"{duration_ms}:0"
        )

    def _cancel_monster_statuses(
        self,
        monster: MonsterState,
        effect_types: Iterable[str],
    ) -> None:
        """Remove status icons and their server-side modifiers from one monster."""
        buff_types = [
            op(COMBAT_DEBUFF_TYPE_BY_EFFECT[effect_type])
            for effect_type in effect_types
            if effect_type in COMBAT_DEBUFF_TYPE_BY_EFFECT
        ]
        if buff_types:
            self._send_visible(
                f"{op(ServerOpcode.CANCEL_MONSTER_STATUS)}:{monster.object_id}:"
                f"{'@'.join(str(value) for value in buff_types)}"
            )

    @staticmethod
    def _defence_skill_probability(skill_id: int, skill_level: int) -> float:
        """Return the original resistance percentage for one learned defence skill."""
        definition = GAME_DATA_CATALOG.get_skill_definition(skill_id)
        if definition is None or skill_level <= 0:
            return 0.0
        if skill_id == 2_010 and skill_level > 60:
            return min(100.0, 90.0 + (skill_level - 60) * 0.25)
        return min(
            100.0,
            definition.defence_probability_base
            + definition.defence_probability_per_level * skill_level,
        )

    def _player_skill_resistance(self, attack: SkillDefinition) -> float:
        """Resolve the target player's matching resistance from oppositeSkill."""
        if attack.opposite_skill_id <= 0:
            return 0.0
        state = self.store.state.skills.get(attack.opposite_skill_id)
        if state is None:
            return 0.0
        return self._defence_skill_probability(
            attack.opposite_skill_id,
            self._effective_skill_level(state),
        )

    def _monster_skill_resistance(
        self,
        monster: MonsterState,
        attack: SkillDefinition,
    ) -> float:
        """Resolve authored monster resistance skills exactly as Nya's client does."""
        if attack.opposite_skill_id <= 0:
            return 0.0
        monster_definition = GAME_DATA_CATALOG.get_monster_definition(
            monster.template_id
        )
        return max(
            (
                self._defence_skill_probability(
                    authored.skill_id,
                    authored.skill_level,
                )
                for authored in monster_definition.attacks
                if authored.skill_id == attack.opposite_skill_id
            ),
            default=0.0,
        )

    def _skill_status_triggered(
        self,
        attack: SkillDefinition,
        skill_level: int,
        *,
        player_target: FakeFlashSession | None = None,
        monster_target: MonsterState | None = None,
    ) -> bool:
        """Run Nya's inclusive 0..100 roll after subtracting target resistance."""
        resistance = 0.0
        if player_target is not None:
            resistance = player_target._player_skill_resistance(attack)
        elif monster_target is not None:
            resistance = self._monster_skill_resistance(monster_target, attack)
        effective_probability = attack.trigger_percent(skill_level) - resistance
        return effective_probability >= self.random.randint(0, 100)

    def _triggered_knockback_passive(
        self,
        attack: SkillDefinition | None,
    ) -> tuple[SkillDefinition, int] | None:
        """Resolve the learned 怪力 passive attached to a job's first attack."""
        if attack is None or attack.trigger_skill_id != 1_002_001:
            return None
        passive = GAME_DATA_CATALOG.get_skill_definition(attack.trigger_skill_id)
        state = self.store.state.skills.get(attack.trigger_skill_id)
        if passive is None or state is None or passive.effect_type != "knock_back":
            return None
        return passive, self._effective_skill_level(state)

    def _apply_monster_skill_status(
        self,
        monster: MonsterState,
        definition: SkillDefinition,
        skill_level: int,
    ) -> bool:
        """Persist a GameData Debuff on the shared monster object."""
        effect_type = definition.effect_type
        if effect_type not in COMBAT_DEBUFF_TYPE_BY_EFFECT:
            return False
        monster_definition = GAME_DATA_CATALOG.get_monster_definition(monster.template_id)
        if effect_type == "tian_zhao" and monster_definition.boss:
            return False
        if not self._skill_status_triggered(
            definition,
            skill_level,
            monster_target=monster,
        ):
            return False
        duration_ms = max(1_000, definition.effect_duration_ms(skill_level))
        now = time.monotonic()
        payload: dict[str, int | float] = {
            "skill_id": definition.skill_id,
            "skill_level": skill_level,
            "value": definition.effect_value(skill_level),
            "value2": definition.effect_value2(skill_level),
            "caster_id": self.character.character_id,
            "expires_at": now + duration_ms / 1_000.0,
            "next_tick_at": now + 1.0,
        }
        monster.skill_statuses[effect_type] = payload
        self._send_monster_status(monster, effect_type, payload)
        return True

    @staticmethod
    def _monster_status_blocks_action(monster: MonsterState) -> bool:
        """Return whether the monster is sealed or stunned by a live status."""
        now = time.monotonic()
        return any(
            effect_type in {"stun", "yue_du", "tian_zhao"}
            and float(payload.get("expires_at") or 0) > now
            for effect_type, payload in monster.skill_statuses.items()
        )

    def _tick_monster_skill_statuses(self, now: float) -> None:
        """Expire Debuffs and settle poison/burn damage once for the shared map."""
        for monster in self.monsters.values():
            expired = [
                effect_type
                for effect_type, payload in monster.skill_statuses.items()
                if float(payload.get("expires_at") or 0) <= now
            ]
            if expired:
                for effect_type in expired:
                    monster.skill_statuses.pop(effect_type, None)
                self._cancel_monster_statuses(monster, expired)
            if monster.hp <= 0:
                continue
            for effect_type in ("poison", "tian_zhao", "atk_buff"):
                payload = monster.skill_statuses.get(effect_type)
                if payload is None or float(payload.get("next_tick_at") or 0) > now:
                    continue
                payload["next_tick_at"] = now + 1.0
                value = max(0.0, float(payload.get("value") or 0))
                damage = self._monster_damage_amount(
                    monster,
                    max(1, round(monster.max_hp * value / 100.0)),
                )
                caster = (
                    self.hub.session_for_character(
                        self._safe_int(payload.get("caster_id"), 0)
                    )
                    if self.hub is not None
                    else self
                )
                owner = caster if caster is not None else self
                damage = owner._apply_copy_damage_rules(monster, damage)
                monster.hp -= damage
                owner._record_world_boss_damage(monster, damage)
                owner._record_xiulian_damage(monster, damage)
                self._send_visible(
                    f"{op(ServerOpcode.DAMAGE_MONSTER)}:{monster.object_id}:{damage}"
                )
                self._send_visible(
                    f"{op(ServerOpcode.SHOW_MONSTER_HP)}:{monster.object_id}:"
                    f"{round(monster.hp * 100 / monster.max_hp)}"
                )
                if monster.hp == 0:
                    owner._handle_monster_killed(monster)
                    break

    def _advance_monster_patrol_phase(
        self,
        monster: MonsterState,
        now: float,
    ) -> None:
        """Give each idle monster an independent formal-style move/rest phase."""
        if monster.patrol_phase_until <= 0:
            phase = ((monster.object_id * 1_103_515_245 + 12_345) & 0xFFFF) / 0xFFFF
            monster.patrol_moving = int(phase * 100) < self.MONSTER_PATROL_WALK_CHANCE
            bounds = (
                self.MONSTER_PATROL_MOVE_SECONDS
                if monster.patrol_moving
                else self.MONSTER_PATROL_REST_SECONDS
            )
            duration = bounds[0] + phase * (bounds[1] - bounds[0])
        else:
            monster.patrol_moving = (
                self.random.randrange(100) < self.MONSTER_PATROL_WALK_CHANCE
            )
            bounds = (
                self.MONSTER_PATROL_MOVE_SECONDS
                if monster.patrol_moving
                else self.MONSTER_PATROL_REST_SECONDS
            )
            duration = self.random.uniform(*bounds)
            if monster.patrol_moving and self.random.randrange(2):
                monster.facing_right = not monster.facing_right
        monster.patrol_phase_until = now + duration

    def _broadcast_server_monster_attack(
        self,
        monster: MonsterState,
        target: FakeFlashSession,
        now: float | None = None,
    ) -> None:
        """Animate and settle one monster attack without trusting TAKE_DAMAGE."""
        current = time.monotonic() if now is None else now
        if self._monster_status_value(monster, "lose_mp") > 0:
            self._broadcast_server_monster_stop(monster, current)
            monster.attack_animation_until = current + 0.25
            return
        monster.facing_right = target.x >= monster.x
        direction = 0 if monster.facing_right else 1
        attack = self._choose_monster_attack(monster)
        self._activate_copy_monster_buff(monster, attack.skill_id, current)
        self._broadcast_server_monster_action(monster, attack.action, current)
        body = bytearray(b"\x01")
        body.extend(
            struct.pack(
                "<iBb5i",
                monster.object_id,
                attack.action,
                direction,
                attack.skill_id,
                attack.skill_level,
                monster.x,
                monster.y,
                1,
            )
        )
        body.extend(struct.pack("<ii", target.character.character_id, 0))
        body.extend(build_original_object_buffer(None))
        for participant in self._monster_broadcast_sessions(monster):
            if participant.wire_mode == "original":
                participant.send_original_packet(ServerOpcode.MOVE_MONSTER, bytes(body))
        monster.attack_animation_until = current + attack.attack_after_ms / 1_000
        target._apply_server_monster_damage(
            monster,
            attack_action=attack.action,
            attack_skill_id=attack.skill_id,
            attack_skill_level=attack.skill_level,
        )

    def _broadcast_server_monster_attack_clone(
        self,
        monster: MonsterState,
        owner: FakeFlashSession,
        clone: ShadowCloneState,
        now: float | None = None,
    ) -> None:
        """Animate and settle a monster hit against a server-owned clone."""
        current = time.monotonic() if now is None else now
        if clone.hp <= 0 or clone.actor_id not in owner.shadow_clones:
            return
        if self._monster_status_value(monster, "lose_mp") > 0:
            self._broadcast_server_monster_stop(monster, current)
            monster.attack_animation_until = current + 0.25
            return
        monster.facing_right = clone.x >= monster.x
        direction = 0 if monster.facing_right else 1
        attack = self._choose_monster_attack(monster)
        self._activate_copy_monster_buff(monster, attack.skill_id, current)
        self._broadcast_server_monster_action(monster, attack.action, current)
        body = bytearray(b"\x01")
        body.extend(
            struct.pack(
                "<iBb5i",
                monster.object_id,
                attack.action,
                direction,
                attack.skill_id,
                attack.skill_level,
                monster.x,
                monster.y,
                1,
            )
        )
        body.extend(struct.pack("<ii", clone.actor_id, 0))
        body.extend(build_original_object_buffer(None))
        for participant in self._monster_broadcast_sessions(monster):
            if participant.wire_mode == "original":
                participant.send_original_packet(ServerOpcode.MOVE_MONSTER, bytes(body))
        monster.attack_animation_until = current + attack.attack_after_ms / 1_000
        self._apply_server_monster_damage_to_clone(
            monster,
            owner,
            clone,
            attack_action=attack.action,
            attack_skill_id=attack.skill_id,
        )

    def _apply_server_monster_damage_to_clone(
        self,
        monster: MonsterState,
        owner: FakeFlashSession,
        clone: ShadowCloneState,
        *,
        attack_action: int,
        attack_skill_id: int,
    ) -> int:
        """Use the normal monster formula against a clone's tenth-stat snapshot."""
        if clone.hp <= 0 or clone.actor_id not in owner.shadow_clones:
            return 0
        definition = GAME_DATA_CATALOG.get_monster_definition(monster.template_id)
        monster_attack = self._monster_stat(
            monster,
            definition.attack,
            EliteAttribute.ATTACK,
        )
        monster_attack = round(
            monster_attack
            * (1.0 + self._monster_status_value(monster, "copy_add_atk") / 100.0)
        )
        attack_reduction = max(
            self._monster_status_value(monster, "lose_eq_atk"),
            self._monster_status_value(monster, "reduce_atk"),
        )
        monster_attack = round(
            monster_attack * max(0.0, 100.0 - attack_reduction) / 100.0
        )
        ignored_defence = self._monster_status_value(monster, "copy_ignore_def")
        effective_defence = round(
            clone.defence * max(0.0, 100.0 - ignored_defence) / 100.0
        )
        reduced_damage = round(
            monster_attack
            * self.MONSTER_DAMAGE_REDUCTION_BASE
            / (self.MONSTER_DAMAGE_REDUCTION_BASE + max(0, effective_defence))
        )
        avoided = self._roll_combat_rate(clone.evasion)
        critical = False
        if avoided:
            damage = 0
        elif definition.fixed_damage > 0:
            damage = min(definition.fixed_damage, clone.hp)
        else:
            monster_critical = self._monster_stat(
                monster,
                definition.critical,
                EliteAttribute.CRITICAL,
            )
            monster_critical = round(
                monster_critical
                * max(
                    0.0,
                    100.0 - self._monster_status_value(monster, "reduce_bsk"),
                )
                / 100.0
            )
            critical = self._roll_combat_rate(monster_critical)
            if critical:
                reduced_damage *= self.CRITICAL_DAMAGE_MULTIPLIER
            damage = min(
                max(self.MONSTER_MIN_DAMAGE, reduced_damage),
                clone.hp,
            )
        clone.hp -= damage
        owner._mark_combat()
        self._send_visible(
            f"{op(ServerOpcode.DAMAGE_PLAYER)}:{clone.actor_id}:"
            f"{attack_skill_id}:false:{damage}:{attack_action}:"
            f"{monster.object_id}:{int(critical)}:0"
        )
        self._send_visible(
            f"{op(ServerOpcode.PLAYER_HP)}:{clone.actor_id}:"
            f"{clone.max_hp}:{clone.hp}"
        )
        if clone.hp <= 0:
            owner._remove_shadow_clone(clone.actor_id)
        return damage

    @staticmethod
    def _activate_copy_monster_buff(
        monster: MonsterState,
        skill_id: int,
        now: float,
    ) -> None:
        """Activate the four authored Team Seven Boss effects from skills 8201-8204."""
        effects = {
            8_201: ("copy_add_atk", 100.0, 30.0),
            8_202: ("copy_ignore_def", 100.0, 30.0),
            8_203: ("copy_damage_reflect", 100.0, 60.0),
            8_204: ("copy_damage_reduce", 100.0, 120.0),
        }
        effect = effects.get(skill_id)
        if effect is None:
            return
        effect_type, value, duration = effect
        monster.skill_statuses[effect_type] = {
            "skill_id": skill_id,
            "skill_level": 100,
            "value": value,
            "expires_at": now + duration,
        }

    def _choose_monster_attack(self, monster: MonsterState) -> MonsterAttackDefinition:
        """Choose one authored attack using its GameData skillRate weight."""
        attacks = GAME_DATA_CATALOG.get_monster_definition(monster.template_id).attacks
        total = sum(max(1, attack.probability) for attack in attacks)
        roll = self.random.randrange(total)
        for attack in attacks:
            roll -= max(1, attack.probability)
            if roll < 0:
                return attack
        return attacks[-1]

    def _apply_server_monster_damage(
        self,
        monster: MonsterState,
        *,
        attack_action: int,
        attack_skill_id: int = 0,
        attack_skill_level: int = 1,
    ) -> None:
        """Apply the same formal damage formula from a server-scheduled attack."""
        if self._is_dead() or monster.hp <= 0:
            return
        definition = GAME_DATA_CATALOG.get_monster_definition(monster.template_id)
        self._mark_boss_combat(monster)
        monster_attack = self._monster_stat(
            monster, definition.attack, EliteAttribute.ATTACK
        )
        monster_attack = round(
            monster_attack
            * (
                1.0
                + self._monster_status_value(monster, "copy_add_atk") / 100.0
            )
        )
        attack_reduction = max(
            self._monster_status_value(monster, "lose_eq_atk"),
            self._monster_status_value(monster, "reduce_atk"),
        )
        monster_attack = round(
            monster_attack * max(0.0, 100.0 - attack_reduction) / 100.0
        )
        ignored_defence = self._monster_status_value(monster, "copy_ignore_def")
        effective_defence = round(
            self._current_defence() * max(0.0, 100.0 - ignored_defence) / 100.0
        )
        reduced_damage = round(
            monster_attack
            * self.MONSTER_DAMAGE_REDUCTION_BASE
            / (self.MONSTER_DAMAGE_REDUCTION_BASE + max(0, effective_defence))
        )
        damage_reduce = min(100, max(0, self._current_damage_reduce()))
        reduced_damage = round(reduced_damage * (100 - damage_reduce) / 100)
        invincible = self._is_damage_invincible()
        avoided = invincible or self._roll_combat_rate(self._current_evasion())
        critical = False
        if avoided:
            damage = 0
        elif definition.fixed_damage > 0:
            damage = min(definition.fixed_damage, self.character.hp)
        else:
            monster_critical = self._monster_stat(
                monster, definition.critical, EliteAttribute.CRITICAL
            )
            monster_critical = round(
                monster_critical
                * max(
                    0.0,
                    100.0 - self._monster_status_value(monster, "reduce_bsk"),
                )
                / 100.0
            )
            critical = self._roll_combat_rate(monster_critical)
            if critical:
                reduced_damage *= self.CRITICAL_DAMAGE_MULTIPLIER
                critical_reduction = min(
                    100,
                    max(0, self._passive_skill_effect_value("damage_reduce_for_bsk")),
                )
                reduced_damage = round(
                    reduced_damage * (100 - critical_reduction) / 100
                )
            damage = min(max(self.MONSTER_MIN_DAMAGE, reduced_damage), self.character.hp)
        reflect_payload = monster.skill_statuses.get("pet_damage_reflect")
        if (
            damage > 0
            and reflect_payload is not None
            and float(reflect_payload.get("expires_at") or 0) > time.monotonic()
            and self._safe_int(reflect_payload.get("caster_id"), 0)
            == self.character.character_id
        ):
            reflected = self._monster_damage_amount(
                monster,
                max(
                    1,
                    round(
                        damage
                        * max(0.0, float(reflect_payload.get("value") or 0))
                        / 100.0
                    ),
                ),
            )
            reflected = self._apply_copy_damage_rules(monster, reflected)
            damage = 0
            monster.hp -= reflected
            self._record_world_boss_damage(monster, reflected)
            self._record_xiulian_damage(monster, reflected, "reflect")
            self._send_visible(
                f"{op(ServerOpcode.DAMAGE_MONSTER)}:{monster.object_id}:{reflected}"
            )
            self._send_visible(
                f"{op(ServerOpcode.SHOW_MONSTER_HP)}:{monster.object_id}:"
                f"{round(monster.hp * 100 / monster.max_hp)}"
            )
            if monster.hp == 0:
                self._handle_monster_killed(monster)
        if damage > 0:
            damage = self._cap_damage_with_death_protection(damage)
        reflect_rate = min(100, max(0, self._current_damage_reflect()))
        if damage > 0 and reflect_rate > 0 and monster.hp > 0:
            reflected = self._monster_damage_amount(
                monster,
                max(1, round(damage * reflect_rate / 100.0)),
            )
            reflected = self._apply_copy_damage_rules(monster, reflected)
            monster.hp -= reflected
            self._record_world_boss_damage(monster, reflected)
            self._record_xiulian_damage(monster, reflected, "reflect")
            self._send_visible(
                f"{op(ServerOpcode.DAMAGE_MONSTER)}:{monster.object_id}:{reflected}"
            )
            self._send_visible(
                f"{op(ServerOpcode.SHOW_MONSTER_HP)}:{monster.object_id}:"
                f"{round(monster.hp * 100 / monster.max_hp)}"
            )
            if monster.hp == 0:
                self._handle_monster_killed(monster)
        self._mark_combat()
        if damage > 0:
            with self.store.lock:
                self.character.hp -= damage
            self._schedule_combat_save()
        attack_skill = GAME_DATA_CATALOG.get_skill_definition(attack_skill_id)
        status_triggered = False
        if damage > 0 and monster.hp > 0 and attack_skill is not None:
            if attack_skill.effect_type in COMBAT_DEBUFF_TYPE_BY_EFFECT:
                status_triggered = self._apply_player_skill_status(
                    attack_skill,
                    attack_skill_level,
                    source_character_id=0,
                    source_monster_id=monster.object_id,
                )
            elif attack_skill.effect_type == "suck_hp" and self._skill_status_triggered(
                attack_skill,
                attack_skill_level,
                player_target=self,
            ):
                recovered = max(
                    1,
                    round(
                        damage
                        * max(0.0, attack_skill.effect_value(attack_skill_level))
                        / 100.0
                    ),
                )
                monster.hp = min(monster.max_hp, monster.hp + recovered)
                status_triggered = True
                self._send_visible(
                    f"{op(ServerOpcode.SHOW_MONSTER_HP)}:{monster.object_id}:"
                    f"{round(monster.hp * 100 / monster.max_hp)}"
                )
        self.send_text(
            f"{op(ServerOpcode.DAMAGE_PLAYER)}:{self.character.character_id}:"
            f"{attack_skill_id}:{str(status_triggered).lower()}:{damage}:"
            f"{attack_action}:{monster.object_id}:{int(critical)}:0"
        )
        self._send_stats({StatType.HP: self.character.hp})
        if self._is_dead():
            if not self._try_izanagi_revive():
                self._send_player_dead_box()

    def _tick_world_skill_effects(self, now: float) -> None:
        """Advance shared multi-phase skills even if their caster socket changes."""
        state = self.world_state
        if state is None or not state.pending_skill_effects:
            return
        for pending in tuple(state.pending_skill_effects):
            if pending.due_at > now:
                continue
            caster = (
                self.hub.session_for_character(pending.caster_id)
                if self.hub is not None
                else self
            )
            sender = caster if caster is not None else self
            living_ids = tuple(
                object_id
                for object_id in pending.target_ids
                if object_id in self.monsters and self.monsters[object_id].hp > 0
            )
            if pending.phase == 0:
                # Do not send the native pull packet.  It enters the client's
                # BeatBackEffect control loop and is unsafe for large monster
                # groups.  Damage remains server-authoritative below.
                pending.phase = 1
                pending.due_at = now + 0.65
                continue
            if 1 <= pending.phase <= 3:
                skill_definition = GAME_DATA_CATALOG.get_skill_definition(
                    pending.skill_id
                )
                total_percent = (
                    skill_definition.damage_percent(pending.skill_level)
                    if skill_definition is not None
                    else 360
                )
                phase_percent = max(1, round(total_percent / 3.0))
                for object_id in living_ids:
                    monster = self.monsters.get(object_id)
                    if monster is None or monster.hp <= 0:
                        continue
                    calculated, critical = sender._calculate_player_damage(
                        monster,
                        phase_percent,
                        force_hit=True,
                    )
                    damage = self._monster_damage_amount(monster, calculated)
                    damage = sender._apply_copy_damage_rules(monster, damage)
                    monster.hp -= damage
                    sender._record_world_boss_damage(monster, damage)
                    sender._record_xiulian_damage(monster, damage)
                    self._send_visible(
                        f"{op(ServerOpcode.DAMAGE_MONSTER)}:{monster.object_id}:{damage}"
                    )
                    self._send_visible(
                        f"{op(ServerOpcode.SHOW_MONSTER_HP)}:{monster.object_id}:"
                        f"{round(monster.hp * 100 / monster.max_hp)}"
                    )
                    if monster.hp == 0:
                        sender._handle_monster_killed(monster, critical=critical)
                pending.phase += 1
                pending.due_at = now + 0.55
                continue
            # Knock-up is also a BeatBackEffect packet in the Flash client.
            # Leave the final positional effect out of this compatibility
            # path until a non-freezing visual implementation is available.
            state.pending_skill_effects.remove(pending)

    def _return_boss_to_spawn(
        self,
        monster: MonsterState,
        monster_x: int,
        monster_y: int,
        now: float,
    ) -> None:
        """Return a disengaged boss to its authored spawn without resuming patrol."""
        if (
            monster.foothold == monster.spawn_foothold
            and abs(monster_x - monster.spawn_x) <= 1
            and abs(monster_y - monster.spawn_y) <= 1
        ):
            monster.x = monster.spawn_x
            monster.y = monster.spawn_y
            monster.engaged_character_ids.clear()
            monster.patrol_moving = False
            self._broadcast_server_monster_stop(monster, now)
            return
        if now < monster.next_move_at:
            return

        move_step = self._consume_monster_move_step(monster)
        floor = (
            self.current_map.footholds.get(monster.foothold)
            if self.current_map is not None
            else None
        )
        spawn_floor = (
            self.current_map.footholds.get(monster.spawn_foothold)
            if self.current_map is not None
            else None
        )
        if monster.immobile or floor is None or spawn_floor is None:
            self._broadcast_server_monster_teleport(
                monster,
                monster.spawn_x,
                monster.spawn_y,
                monster.spawn_foothold,
                now,
            )
            monster.patrol_moving = False
            return

        destination_x = monster_x
        destination_y = monster_y
        if floor.foothold_id != spawn_floor.foothold_id:
            path_edge = self.current_map.monster_path_next_edge(
                floor.foothold_id,
                spawn_floor.foothold_id,
            )
            if path_edge is None:
                self._broadcast_server_monster_teleport(
                    monster,
                    monster.spawn_x,
                    monster.spawn_y,
                    monster.spawn_foothold,
                    now,
                )
                monster.patrol_moving = False
                return
            next_foothold_id, transition_kind, transition_x = path_edge
            next_floor = self.current_map.footholds[next_foothold_id]
            transition_delta = transition_x - monster_x
            if abs(transition_delta) > move_step + self.MONSTER_PATH_JOINT_TOLERANCE:
                destination_x = monster_x + max(
                    -move_step,
                    min(move_step, transition_delta),
                )
                destination_x = max(floor.left, min(floor.right, destination_x))
                destination_y = floor.y_at(destination_x)
            elif transition_kind == "ladder":
                self._broadcast_server_monster_teleport(
                    monster,
                    transition_x,
                    next_floor.y_at(transition_x),
                    next_foothold_id,
                    now,
                )
                monster.next_move_at = now + self.MONSTER_MOVE_INTERVAL_SECONDS
                monster.patrol_moving = False
                return
            else:
                monster.foothold = next_foothold_id
                floor = next_floor
                destination_x = max(floor.left, min(floor.right, transition_x))
                destination_y = floor.y_at(destination_x)
        else:
            delta_x = monster.spawn_x - monster_x
            destination_x = (
                monster.spawn_x
                if abs(delta_x) <= move_step
                else monster_x + max(-move_step, min(move_step, delta_x))
            )
            destination_x = max(floor.left, min(floor.right, destination_x))
            destination_y = (
                monster.spawn_y
                if destination_x == monster.spawn_x
                else floor.y_at(destination_x)
            )

        monster.next_move_at = now + self.MONSTER_MOVE_INTERVAL_SECONDS
        monster.patrol_moving = False
        if (destination_x, destination_y) != (monster_x, monster_y):
            self._broadcast_server_monster_move(
                monster,
                destination_x,
                destination_y,
                round(self.MONSTER_MOVE_INTERVAL_SECONDS * 1_000),
                now,
            )
        else:
            self._broadcast_server_monster_teleport(
                monster,
                monster.spawn_x,
                monster.spawn_y,
                monster.spawn_foothold,
                now,
            )

    def _tick_monster_shadow_clone_target(
        self,
        monster: MonsterState,
        definition: MonsterDefinition,
        owner: FakeFlashSession,
        clone: ShadowCloneState,
        floor: FootholdState | None,
        monster_x: int,
        monster_y: int,
        now: float,
    ) -> bool:
        """Chase or attack an aggroed clone; return whether the target remains valid."""
        if (
            clone.hp <= 0
            or clone.actor_id not in owner.shadow_clones
            or owner._is_dead()
        ):
            return False
        chase_distance = (
            self.BOSS_CHASE_DISTANCE
            if definition.boss
            else self.MONSTER_CHASE_DISTANCE
        )
        if (
            (clone.x - monster_x) ** 2 + (clone.y - monster_y) ** 2
            > chase_distance**2
        ):
            return False
        target_floor = None
        if self.current_map is not None:
            target_floor = self.current_map.foothold_below(clone.x, clone.y)
            if target_floor is None:
                target_floor = self.current_map.footholds.get(clone.foothold)
            if target_floor is not None:
                clone.foothold = target_floor.foothold_id
        if (
            floor is not None
            and target_floor is not None
            and floor.foothold_id != target_floor.foothold_id
        ):
            if not definition.boss:
                return False
            if now >= monster.next_move_at:
                destination_x = self._clamp_monster_walk_x(
                    target_floor,
                    clone.x
                    + (
                        -self.MONSTER_ATTACK_DISTANCE
                        if clone.x >= monster_x
                        else self.MONSTER_ATTACK_DISTANCE
                    ),
                )
                self._broadcast_server_monster_teleport(
                    monster,
                    destination_x,
                    target_floor.y_at(destination_x),
                    target_floor.foothold_id,
                    now,
                )
                monster.next_move_at = now + self.MONSTER_MOVE_INTERVAL_SECONDS
            return True
        if now < monster.attack_animation_until:
            return True
        if monster.attack_animation_until > 0:
            monster.attack_animation_until = 0.0
            self._broadcast_server_monster_stop(monster, now)
        delta_x = clone.x - monster_x
        delta_y = clone.y - monster_y
        if (
            abs(delta_x) <= self.MONSTER_ATTACK_DISTANCE
            and abs(delta_y) <= self.MONSTER_ATTACK_DISTANCE
        ):
            if now >= monster.next_attack_at:
                attack_slow = self._monster_status_value(
                    monster,
                    "reduce_atk_speed",
                )
                monster.next_attack_at = now + (
                    self.MONSTER_ATTACK_INTERVAL_SECONDS
                    * (1.0 + attack_slow / 100.0)
                    * self.random.uniform(0.85, 1.15)
                )
                self._broadcast_server_monster_attack_clone(
                    monster,
                    owner,
                    clone,
                    now,
                )
            else:
                self._broadcast_server_monster_stop(monster, now)
            return True
        if monster.immobile:
            self._broadcast_server_monster_stop(monster, now)
            return True
        if now < monster.next_move_at or floor is None:
            return True
        move_step = self._consume_monster_move_step(monster)
        stop_offset = (
            -self.MONSTER_ATTACK_DISTANCE
            if clone.x >= monster_x
            else self.MONSTER_ATTACK_DISTANCE
        )
        desired_x = clone.x + stop_offset
        destination_x = monster_x + max(
            -move_step,
            min(move_step, desired_x - monster_x),
        )
        destination_x = self._clamp_monster_walk_x(floor, destination_x)
        destination_y = floor.y_at(destination_x)
        monster.next_move_at = now + self.MONSTER_MOVE_INTERVAL_SECONDS
        if (destination_x, destination_y) != (monster_x, monster_y):
            self._broadcast_server_monster_move(
                monster,
                destination_x,
                destination_y,
                round(self.MONSTER_MOVE_INTERVAL_SECONDS * 1_000),
                now,
            )
        else:
            self._broadcast_server_monster_stop(monster, now)
        return True

    def _tick_server_monsters(self, now: float | None = None) -> None:
        """Patrol, chase, and attack once per shared map from server-owned state."""
        if not self.entered_game:
            return
        if self.hub is not None and not self.hub.claim_monster_control(self):
            return
        current = time.monotonic() if now is None else now
        self._tick_world_skill_effects(current)
        self._tick_monster_skill_statuses(current)
        players = [
            value
            for value in self._monster_world_sessions()
            if not value._is_dead()
        ]
        if not players:
            return
        players_by_id = {
            value.character.character_id: value for value in players
        }
        clone_targets = {
            clone.actor_id: (owner, clone)
            for owner in players
            for clone in owner.shadow_clones.values()
            if clone.hp > 0
        }

        def foothold_for(monster: MonsterState) -> FootholdState | None:
            if self.current_map is None:
                return None
            # The original WorldBoss tuple keeps its authored foothold index
            # separate from the visual spawn coordinates. Resolve the physical
            # platform for AI pathing without rewriting the client-facing tuple.
            if (
                self._is_primary_world_boss_instance(monster)
                and monster.foothold == self.WORLD_BOSS_FOOTHOLD
            ):
                authored_floor = self.current_map.foothold_below(monster.x, monster.y)
                if authored_floor is not None:
                    return authored_floor
            return self.current_map.footholds.get(monster.foothold)

        def player_is_on_floor(player: FakeFlashSession, floor: FootholdState | None) -> bool:
            if floor is None:
                return True
            return (
                floor.left - 24 <= player.x <= floor.right + 24
                and abs(player.y - floor.y_at(player.x)) <= 100
            )

        def foothold_for_player(player: FakeFlashSession) -> FootholdState | None:
            if self.current_map is None:
                return None
            floor = self.current_map.foothold_below(player.x, player.y)
            if floor is not None:
                player.character.foothold = floor.foothold_id
                return floor
            return self.current_map.footholds.get(player.character.foothold)

        for monster in self.monsters.values():
            if self.arena_monster is monster:
                # Arena PlayerMonster movement and skill selection are driven by
                # _tick_arena so the generic GameData Boss AI cannot double-act.
                continue
            if monster.hp <= 0 or monster.respawn_at:
                continue
            definition = GAME_DATA_CATALOG.get_monster_definition(monster.template_id)
            current_target = players_by_id.get(monster.target_character_id)
            if (
                current_target is not None
                and current_target._has_active_skill_buff(CombatBuffType.DARKSIGHT)
                and not (
                    definition.boss
                    and definition.level >= current_target.character.level
                )
            ):
                # Losing sight is immediate even while the monster is stunned,
                # being knocked back, or following a scripted copy path.
                monster.target_character_id = 0
                monster.engaged_character_ids.discard(
                    current_target.character.character_id
                )
            if monster.knockback_until > 0:
                if current < monster.knockback_until:
                    continue
                self._finish_monster_knockback(monster, current)
                continue
            if self._monster_status_blocks_action(monster):
                self._settle_monster_motion(monster, current, force=True)
                self._broadcast_server_monster_stop(monster, current)
                continue
            if self.active_copy_id in {3, 4} and (
                monster.target_x != 0 or monster.target_y != 0
            ):
                monster.target_character_id = 0
                continue
            monster_x, monster_y = self._settle_monster_motion(monster, current)
            if definition.pet_link > 0:
                monster.target_character_id = 0
                monster.patrol_moving = False
                monster.patrol_phase_until = float("inf")
                self._broadcast_server_monster_stop(monster, current)
                continue
            can_attack = not self._is_wealth_mouse_family(monster.template_id)
            chase_distance = (
                self.BOSS_CHASE_DISTANCE
                if definition.boss
                else self.MONSTER_CHASE_DISTANCE
            )
            if not can_attack:
                # Wealth mice keep their authored patrol but never retain aggro or
                # retaliate after player, pet, or delayed-skill damage.
                monster.target_character_id = 0
            floor = foothold_for(monster)
            in_copy_instance = (
                self.active_copy_id is not None or self.active_hero_copy_id is not None
            )
            repair_missing_floor = in_copy_instance or definition.boss
            if floor is None and self.current_map is not None and repair_missing_floor:
                grounded_x, grounded_y, grounded_foothold = self.current_map.ground_position(
                    monster_x,
                    monster_y,
                    monster.foothold,
                )
                floor = self.current_map.footholds.get(grounded_foothold)
                if floor is not None:
                    self._broadcast_server_monster_teleport(
                        monster,
                        grounded_x,
                        grounded_y,
                        grounded_foothold,
                        current,
                    )
                    monster_x, monster_y = grounded_x, grounded_y
                    # A missing runtime foothold may be repaired for AI
                    # pathing, but never overwrite an authored Boss spawn.
                    # Respawn and disengage must still return to GameData's
                    # original x/y/fh tuple.
            if floor is None and repair_missing_floor and self.current_map is not None:
                monster.target_character_id = 0
                self._broadcast_server_monster_stop(monster, current)
                continue
            clone_target = clone_targets.get(monster.target_character_id)
            if clone_target is not None and can_attack:
                clone_owner, clone = clone_target
                if self._tick_monster_shadow_clone_target(
                    monster,
                    definition,
                    clone_owner,
                    clone,
                    floor,
                    monster_x,
                    monster_y,
                    current,
                ):
                    continue
                monster.target_character_id = 0
                monster.engaged_character_ids.discard(clone.actor_id)
            combat_y = monster_y
            if (
                self._is_primary_world_boss_instance(monster)
                and floor is not None
                and monster.foothold == self.WORLD_BOSS_FOOTHOLD
            ):
                # Its authored y is the client render origin; combat range uses
                # the platform height under the sprite's feet.
                combat_y = floor.y_at(monster_x)
            detectable_players = [
                player
                for player in players
                if not player._has_active_skill_buff(CombatBuffType.DARKSIGHT)
                or (
                    definition.boss
                    and definition.level >= player.character.level
                )
            ]
            detectable_players_by_id = {
                player.character.character_id: player
                for player in detectable_players
            }
            target = (
                detectable_players_by_id.get(monster.target_character_id)
                if can_attack
                else None
            )
            if target is None and monster.target_character_id:
                monster.target_character_id = 0
            if definition.boss:
                monster.engaged_character_ids.intersection_update(
                    detectable_players_by_id
                )
            if target is not None:
                distance_sq = (target.x - monster_x) ** 2 + (target.y - combat_y) ** 2
                target_floor = foothold_for_player(target)
                cross_floor_path = (
                    definition.boss
                    and floor is not None
                    and target_floor is not None
                    and floor.foothold_id != target_floor.foothold_id
                    and self.current_map is not None
                    and (
                        self.current_map.monster_path_next_edge(
                            floor.foothold_id,
                            target_floor.foothold_id,
                        )
                        is not None
                        or target.character.character_id
                        in monster.engaged_character_ids
                    )
                )
                if distance_sq > chase_distance**2 or (
                    not player_is_on_floor(target, floor) and not cross_floor_path
                ):
                    target = None
                    monster.target_character_id = 0
            if (
                target is None
                and definition.boss
                and can_attack
                and monster.engaged_character_ids
            ):
                engaged_players = [
                    player
                    for character_id in monster.engaged_character_ids
                    if (
                        player := detectable_players_by_id.get(character_id)
                    ) is not None
                    and (player.x - monster_x) ** 2 + (player.y - combat_y) ** 2
                    <= chase_distance**2
                ]
                target = min(
                    engaged_players,
                    key=lambda player: (
                        (player.x - monster_x) ** 2
                        + (player.y - combat_y) ** 2
                    ),
                    default=None,
                )
                if target is not None:
                    monster.target_character_id = target.character.character_id
            boss_returning = (
                definition.boss
                and can_attack
                and target is None
                and (
                    monster.foothold != monster.spawn_foothold
                    or abs(monster_x - monster.spawn_x) > 1
                    or abs(monster_y - monster.spawn_y) > 1
                )
            )
            # Bosses stay dormant until a real combat action assigns a target.
            # Their authored firstAttack flag is still sent to the client for
            # normal monster semantics, but it must not turn nearby players
            # into an implicit boss encounter. Ordinary aggressive monsters
            # retain the original proximity acquisition behavior.
            if (
                target is None
                and can_attack
                and not definition.boss
                and monster.first_attack
                and not boss_returning
            ):
                floor_players = [
                    value
                    for value in detectable_players
                    if player_is_on_floor(value, floor)
                    or (
                        definition.boss
                        and floor is not None
                        and self.current_map is not None
                        and (
                            candidate_floor := foothold_for_player(value)
                        )
                        is not None
                        and self.current_map.monster_path_next_edge(
                            floor.foothold_id,
                            candidate_floor.foothold_id,
                        )
                        is not None
                    )
                ]
                target = min(
                    floor_players,
                    key=lambda value: (value.x - monster_x) ** 2 + (value.y - monster_y) ** 2,
                    default=None,
                )
                if target is not None:
                    distance_sq = (target.x - monster_x) ** 2 + (target.y - monster_y) ** 2
                    if distance_sq <= chase_distance**2:
                        monster.target_character_id = target.character.character_id
                    else:
                        target = None
            if current < monster.attack_animation_until:
                continue
            if monster.attack_animation_until > 0:
                monster.attack_animation_until = 0.0
                self._broadcast_server_monster_stop(monster, current)
            if target is not None:
                delta_x = target.x - monster_x
                delta_y = target.y - combat_y
                if (
                    abs(delta_x) <= self.MONSTER_ATTACK_DISTANCE
                    and abs(delta_y) <= self.MONSTER_ATTACK_DISTANCE
                ):
                    if current >= monster.next_attack_at:
                        attack_slow = self._monster_status_value(
                            monster,
                            "reduce_atk_speed",
                        )
                        monster.next_attack_at = current + (
                            self.MONSTER_ATTACK_INTERVAL_SECONDS
                            * (1.0 + attack_slow / 100.0)
                            * self.random.uniform(0.85, 1.15)
                        )
                        self._broadcast_server_monster_attack(monster, target, current)
                    else:
                        self._broadcast_server_monster_stop(monster, current)
                    continue
                if monster.immobile:
                    self._broadcast_server_monster_stop(monster, current)
                    continue
                if current < monster.next_move_at:
                    continue
                move_step = self._consume_monster_move_step(monster)
                target_floor = foothold_for_player(target)
                if (
                    definition.boss
                    and floor is not None
                    and target_floor is not None
                    and floor.foothold_id != target_floor.foothold_id
                    and self.current_map is not None
                ):
                    path_edge = self.current_map.monster_path_next_edge(
                        floor.foothold_id,
                        target_floor.foothold_id,
                    )
                    if path_edge is None:
                        destination_x = self._clamp_monster_walk_x(
                            target_floor,
                            target.x
                            + (
                                -self.MONSTER_ATTACK_DISTANCE
                                if target.x >= monster_x
                                else self.MONSTER_ATTACK_DISTANCE
                            ),
                        )
                        self._broadcast_server_monster_teleport(
                            monster,
                            destination_x,
                            target_floor.y_at(destination_x),
                            target_floor.foothold_id,
                            current,
                        )
                        monster.next_move_at = (
                            current + self.MONSTER_MOVE_INTERVAL_SECONDS
                        )
                        continue
                    next_foothold_id, transition_kind, transition_x = path_edge
                    next_floor = self.current_map.footholds[next_foothold_id]
                    transition_delta = transition_x - monster_x
                    if (
                        abs(transition_delta)
                        > move_step + self.MONSTER_PATH_JOINT_TOLERANCE
                    ):
                        destination_x = monster_x + max(
                            -move_step,
                            min(move_step, transition_delta),
                        )
                        destination_x = max(
                            floor.left,
                            min(floor.right, destination_x),
                        )
                    elif transition_kind == "ladder":
                        self._broadcast_server_monster_teleport(
                            monster,
                            transition_x,
                            next_floor.y_at(transition_x),
                            next_foothold_id,
                            current,
                        )
                        monster.next_move_at = (
                            current + self.MONSTER_MOVE_INTERVAL_SECONDS
                        )
                        continue
                    else:
                        monster.foothold = next_foothold_id
                        floor = next_floor
                        destination_x = max(
                            floor.left,
                            min(floor.right, transition_x),
                        )
                else:
                    if abs(delta_y) > 160:
                        self._broadcast_server_monster_stop(monster, current)
                        continue
                    destination_x = monster_x + max(
                        -move_step,
                        min(move_step, delta_x),
                    )
                    if floor is not None:
                        destination_x = self._clamp_monster_walk_x(
                            floor,
                            destination_x,
                        )
            else:
                if definition.boss and can_attack:
                    self._return_boss_to_spawn(
                        monster,
                        monster_x,
                        monster_y,
                        current,
                    )
                    continue
                if current >= monster.patrol_phase_until:
                    self._advance_monster_patrol_phase(monster, current)
                if not monster.patrol_moving:
                    self._broadcast_server_monster_stop(monster, current)
                    continue
                if current < monster.next_move_at:
                    continue
                move_step = self._consume_monster_move_step(monster)
                left = min(monster.patrol_left, monster.patrol_right)
                right = max(monster.patrol_left, monster.patrol_right)
                if left == right:
                    left = monster.spawn_x - move_step
                    right = monster.spawn_x + move_step
                if floor is not None:
                    safe_left, safe_right = self._monster_safe_walk_bounds(floor)
                    left = max(left, safe_left)
                    right = min(right, safe_right)
                    if left > right:
                        left = right = self._clamp_monster_walk_x(
                            floor,
                            monster.spawn_x,
                        )
                if monster.facing_right and monster_x >= right:
                    monster.facing_right = False
                elif not monster.facing_right and monster_x <= left:
                    monster.facing_right = True
                destination_x = min(
                    right,
                    monster_x + move_step,
                ) if monster.facing_right else max(
                    left,
                    monster_x - move_step,
                )
            monster.next_move_at = current + self.MONSTER_MOVE_INTERVAL_SECONDS
            if destination_x != monster_x:
                destination_y = floor.y_at(destination_x) if floor is not None else monster.y
                self._broadcast_server_monster_move(
                    monster,
                    destination_x,
                    destination_y,
                    round(self.MONSTER_MOVE_INTERVAL_SECONDS * 1_000),
                    current,
                )
            else:
                self._broadcast_server_monster_stop(monster, current)

    def _tick_muye_battle(self) -> None:
        """Finish the shared 30-minute battle once and return every participant."""
        if (
            self.hub is None
            or self.muye_battle_team not in (1, 2)
            or self.hub.muye_battle_started_at <= 0
            or time.monotonic() - self.hub.muye_battle_started_at
            < self.hub.muye_battle_duration
        ):
            return
        with self.hub.lock:
            if self.hub.muye_battle_started_at <= 0:
                return
            self.hub.muye_battle_started_at = 0.0
            participants = self.hub.muye_battle_sessions()
        for participant in participants:
            participant._leave_muye_battle(show_result=True)

    def _refresh_weather(self, force: bool = False) -> None:
        """Publish the same global weather effect on every map."""
        if not self.entered_game:
            return
        period = int(time.time()) // self.WEATHER_INTERVAL_SECONDS
        forced_weather = GM_STATE.weather_override()
        if forced_weather is None:
            global_type, notice = GAME_DATA_CATALOG.weather_for_period(period)
        else:
            global_type, notice = forced_weather, ""
        weather_type = max(0, min(9, self._safe_int(global_type, 0)))
        period_changed = period != self.weather_period
        weather_changed = weather_type != self.weather_type
        changed = period_changed or weather_changed
        if not changed and not force:
            return
        self.weather_period = period
        self.weather_type = weather_type
        self.send_text(f"{op(ServerOpcode.CHANGE_WEATHER)}:{weather_type}")
        if weather_changed:
            self._send_all_stats()
        if period_changed and notice:
            self._send_dynamic_info(notice)

    def _schedule_weather_refresh(
        self,
        *,
        delay_seconds: float = 0.75,
        attempts: int = 8,
    ) -> None:
        """Replay weather after asynchronous map and UI creation has settled."""
        if not self.entered_game:
            return
        self.pending_weather_refresh_attempts = max(
            self.pending_weather_refresh_attempts,
            max(1, int(attempts)),
        )
        self.pending_weather_refresh_at = time.monotonic() + max(
            0.05,
            float(delay_seconds),
        )

    def _refresh_active_skill_buffs(self) -> None:
        """Expire combat Buffs, remove their icons, and restore authoritative stats."""
        now = int(time.time() * 1_000)
        expired = [
            buff_type
            for buff_type, payload in self.store.state.active_skill_buffs.items()
            if self._safe_int(payload.get("expires_at"), 0) <= now
        ]
        if not expired:
            return
        with self.store.lock:
            for buff_type in expired:
                self.store.state.active_skill_buffs.pop(buff_type, None)
            self.store.save()
        self.send_text(
            f"{op(ServerOpcode.CANCEL_BUFF)}:{'@'.join(str(value) for value in expired)}"
        )
        foreign_expired = [
            buff_type
            for buff_type in expired
            if buff_type == op(CombatBuffType.DARKSIGHT)
            or buff_type in {op(value) for value in COMBAT_DEBUFF_TYPE_BY_EFFECT.values()}
        ]
        if foreign_expired:
            self._send_visible(
                f"{op(ServerOpcode.CANCEL_FOREIGN_BUFF)}:"
                f"{self.character.character_id}:"
                f"{'@'.join(str(value) for value in foreign_expired)}",
                include_self=False,
            )
        if self.entered_game:
            self._send_all_stats()

    def _send_active_skill_buffs(self) -> None:
        """Replay persisted combat Buff icons and remaining durations after login."""
        self._refresh_active_skill_buffs()
        now = int(time.time() * 1_000)
        edo_payload = self.store.state.active_skill_buffs.get(
            op(CombatBuffType.SEDUCE)
        )
        if (
            isinstance(edo_payload, dict)
            and edo_payload.get("effect_type") == "edo_control"
            and self._safe_int(edo_payload.get("expires_at"), 0) > now
            and not self.edo_controlled_until
        ):
            self.edo_controlled_until = time.monotonic() + (
                self._safe_int(edo_payload.get("expires_at"), now) - now
            ) / 1_000.0
            self.edo_controller_id = self._safe_int(
                edo_payload.get("source_character_id"),
                0,
            )
            self.edo_next_action_at = time.monotonic()
            self.character.hp = min(self.character.hp, self._current_max_hp())
            self.character.mp = min(self.character.mp, self._current_max_mp())
        rows = [
            "&".join(
                (
                    str(buff_type),
                    format(float(payload.get("value_percent") or 0) / 100.0, ".6g"),
                    str(self._safe_int(payload.get("skill_id"), 0)),
                    str(max(1, self._safe_int(payload.get("skill_level"), 1))),
                    str(max(1, self._safe_int(payload.get("expires_at"), 0) - now)),
                )
            )
            for buff_type, payload in self.store.state.active_skill_buffs.items()
            if self._safe_int(payload.get("expires_at"), 0) > now
        ]
        if rows:
            self.send_text(f"{op(ServerOpcode.GIVE_BUFF)}:{'@'.join(rows)}")
        if self._is_mp_sealed():
            self._send_stats({StatType.MP: self.character.mp})
        if self._is_edo_controlled():
            self._send_edo_state_message(True)

    def _send_active_skill_cooldowns(self) -> None:
        """Replay unexpired server-authoritative skill cooldowns after login."""
        now = int(time.time() * 1_000)
        expired = [
            skill_id
            for skill_id, expires_at in self.store.state.skill_cooldowns.items()
            if int(expires_at or 0) <= now
        ]
        if expired:
            with self.store.lock:
                for skill_id in expired:
                    self.store.state.skill_cooldowns.pop(skill_id, None)
                self.store.persist_skill_cooldowns()
                self.store.save()
        for skill_id, expires_at in sorted(self.store.state.skill_cooldowns.items()):
            remaining_ms = max(0, int(expires_at or 0) - now)
            if remaining_ms:
                self.send_text(
                    f"{op(ServerOpcode.COOLDOWN)}:{skill_id}:{remaining_ms}"
                )

    def _tick_player_skill_statuses(self, now_ms: int) -> None:
        """Settle periodic damage and pet recovery Buffs exactly once per second."""
        damage_due: list[dict[str, int | float | str]] = []
        recovery_due: list[dict[str, int | float | str]] = []
        with self.store.lock:
            for payload in self.store.state.active_skill_buffs.values():
                effect_type = str(payload.get("effect_type") or "")
                if effect_type not in (
                    PLAYER_PERIODIC_DAMAGE_EFFECTS
                    | PLAYER_PERIODIC_RECOVERY_EFFECTS
                ):
                    continue
                if self._safe_int(payload.get("expires_at"), 0) <= now_ms:
                    continue
                next_tick_at = self._safe_int(payload.get("next_tick_at"), 0)
                if next_tick_at <= 0:
                    payload["next_tick_at"] = now_ms + 1_000
                    continue
                if next_tick_at > now_ms:
                    continue
                payload["next_tick_at"] = now_ms + 1_000
                if effect_type in PLAYER_PERIODIC_DAMAGE_EFFECTS:
                    damage_due.append(payload)
                else:
                    recovery_due.append(payload)
            if damage_due or recovery_due:
                self.store.save()
        if self._is_dead():
            return
        total_damage = 0
        for payload in damage_due:
            value = max(0.0, float(payload.get("value_percent") or 0))
            total_damage += max(1, round(self._current_max_hp() * value / 100.0))
        damage = self._cap_damage_with_death_protection(
            min(total_damage, self.character.hp)
        )
        if damage > 0:
            with self.store.lock:
                self.character.hp -= damage
            self._schedule_combat_save()
            self._mark_combat()
            self.send_text(
                f"{op(ServerOpcode.DAMAGE_PLAYER)}:{self.character.character_id}:0:false:"
                f"{damage}:0:0:0:0"
            )
            self._send_stats({StatType.HP: self.character.hp})
            self._send_visible(
                f"{op(ServerOpcode.PLAYER_HP)}:{self.character.character_id}:"
                f"{self._current_max_hp()}:{self.character.hp}"
            )
            if self._is_dead():
                if self._try_izanagi_revive():
                    return
                self._release_global_battle_items("death")
                self._send_player_dead_box()
                return

        hp_rate = sum(
            max(0.0, float(payload.get("value_percent") or 0))
            for payload in recovery_due
            if payload.get("effect_type") == "pet_cure_hp_buff"
        )
        mp_rate = sum(
            max(0.0, float(payload.get("value_percent") or 0))
            for payload in recovery_due
            if payload.get("effect_type") == "pet_cure_mp_buff"
        )
        updates: dict[StatType, int] = {}
        with self.store.lock:
            if hp_rate > 0 and self.character.hp < self._current_max_hp():
                self.character.hp = min(
                    self._current_max_hp(),
                    self.character.hp
                    + max(1, round(self._current_max_hp() * hp_rate / 100.0)),
                )
                updates[StatType.HP] = self.character.hp
            if (
                mp_rate > 0
                and not self._is_mp_sealed()
                and self.character.mp < self._current_max_mp()
            ):
                self.character.mp = min(
                    self._current_max_mp(),
                    self.character.mp
                    + max(1, round(self._current_max_mp() * mp_rate / 100.0)),
                )
                updates[StatType.MP] = self.character.mp
            if updates:
                self.store.save()
        if updates:
            self._send_stats(updates)
        if StatType.HP in updates:
            self._send_visible(
                f"{op(ServerOpcode.PLAYER_HP)}:{self.character.character_id}:"
                f"{self._current_max_hp()}:{self.character.hp}"
            )

    @staticmethod
    def _double_gain_activity_periods(
        now_epoch: float | None = None,
    ) -> tuple[tuple[bool, int, int], tuple[bool, int, int]]:
        """Return active state, remaining seconds, and total seconds for gain events."""
        current = datetime.fromtimestamp(time.time() if now_epoch is None else now_epoch)
        seconds = (
            current.hour * 3600
            + current.minute * 60
            + current.second
            + current.microsecond / 1_000_000
        )
        config = EDITOR_RUNTIME.entity(
            "balance_rules",
            "monster_drops",
            BALANCE_DEFAULTS["monster_drops"],
        )

        def clock_seconds(value: Any, fallback: int) -> int:
            match = re.fullmatch(r"\s*(\d{1,2}):(\d{2})\s*", str(value or ""))
            if match is None:
                return fallback
            hour, minute = int(match.group(1)), int(match.group(2))
            if hour == 24 and minute == 0:
                return 86_400
            if not (0 <= hour < 24 and 0 <= minute < 60):
                return fallback
            return hour * 3600 + minute * 60

        raw_days = config.get("weekendDays", "5,6,7")
        day_values = (
            re.split(r"[,，\s]+", raw_days.strip())
            if isinstance(raw_days, str)
            else raw_days
            if isinstance(raw_days, (list, tuple, set))
            else (5, 6, 7)
        )
        weekend_days = {
            int(value)
            for value in day_values
            if str(value).isdigit() and 1 <= int(value) <= 7
        }
        weekend_start = clock_seconds(config.get("weekendStartTime"), 10 * 3600)
        weekend_end = clock_seconds(config.get("weekendEndTime"), 20 * 3600)
        raw_holidays = config.get("holidayDates", "")
        holiday_values = (
            re.split(r"[,，\s]+", raw_holidays.strip())
            if isinstance(raw_holidays, str)
            else raw_holidays
            if isinstance(raw_holidays, (list, tuple, set))
            else ()
        )
        holiday_dates = {str(value) for value in holiday_values if value}

        base_intervals: list[tuple[int, int]] = [
            (12 * 3600, 13 * 3600),
            (19 * 3600, 20 * 3600),
        ]
        if (
            current.isoweekday() in weekend_days
            and weekend_start < weekend_end
        ):
            base_intervals.append((weekend_start, weekend_end))
        if current.date().isoformat() in holiday_dates:
            base_intervals.append((0, 86_400))

        def resolve(
            intervals: Iterable[tuple[int, int]],
        ) -> tuple[bool, int, int]:
            merged: list[list[int]] = []
            for start, end in sorted(intervals):
                start = max(0, min(86_400, int(start)))
                end = max(0, min(86_400, int(end)))
                if end <= start:
                    continue
                if merged and start <= merged[-1][1]:
                    merged[-1][1] = max(merged[-1][1], end)
                else:
                    merged.append([start, end])
            for start, end in merged:
                if start <= seconds < end:
                    return (
                        True,
                        max(1, math.ceil(end - seconds)),
                        max(1, end - start),
                    )
            return False, 0, 0

        monster_period = resolve(base_intervals)
        meditation_period = resolve((*base_intervals, (0, 8 * 3600)))
        return monster_period, meditation_period

    def _system_activity_buff_periods(
        self,
        now_epoch: float | None = None,
    ) -> dict[int, tuple[float, int, int]]:
        """Map original System Buff icons to active server-side activity effects."""
        monster_period, meditation_period = self._double_gain_activity_periods(
            now_epoch
        )
        periods: dict[int, tuple[float, int, int]] = {}
        if monster_period[0]:
            periods[0] = (2.0, monster_period[1], monster_period[2])
        if meditation_period[0]:
            periods[1] = (2.0, meditation_period[1], meditation_period[2])
        return periods

    def _send_system_activity_buffs(
        self,
        *,
        force: bool = False,
        now_epoch: float | None = None,
    ) -> None:
        """Synchronize original double-experience/essence activity Buff icons."""
        active = self._system_activity_buff_periods(now_epoch)
        active_types = set(active)
        for buff_type in sorted(self.visible_system_activity_buffs - active_types):
            self.send_text(
                f"{op(ServerOpcode.SYSTEM_BUF_ACTION)}:1:{buff_type}"
            )
        for buff_type, (value, remaining, duration) in sorted(active.items()):
            if force or buff_type not in self.visible_system_activity_buffs:
                self.send_text(
                    f"{op(ServerOpcode.SYSTEM_BUF_ACTION)}:0:{buff_type}:"
                    f"{format(value, '.6g')}:{remaining}:{duration}"
                )
        self.visible_system_activity_buffs = active_types

    def _send_persistent_status_replay(self) -> None:
        """Replay persistent icons after the Flash HUD has finished constructing."""
        self._send_active_item_effects()
        self._send_auto_consume_effects()
        self._send_active_skill_buffs()
        self._send_system_activity_buffs(force=True)
        self._send_lianzhan_count()
        self._send_lianzhan_stage()
        self._send_crime_update()
        self._send_arena_rank_reward_status()

    def _tick_meditation_rewards(self, now: float) -> None:
        """Grant the original periodic sitting rewards and trigger native gain floaters."""
        if not self.healing_active or not self.last_meditation_reward_at:
            return
        config = EDITOR_RUNTIME.entity("balance_rules", "meditation", BALANCE_DEFAULTS["meditation"])
        interval = float(config.get("dualIntervalSeconds" if self.healing_partner_id else "singleIntervalSeconds", 25 if self.healing_partner_id else 30))
        if now - self.last_meditation_reward_at < interval:
            return
        self.last_meditation_reward_at = now
        progression = self.store.state.progression
        experience_multiplier = max(0.0, float(config.get("dualExperienceMultiplier" if self.healing_partner_id else "singleExperienceMultiplier", 1.2 if self.healing_partner_id else 1.0)))
        essence_multiplier = max(0.0, float(config.get("dualEssenceMultiplier" if self.healing_partner_id else "singleEssenceMultiplier", 1.2 if self.healing_partner_id else 1.0)))
        spouse = self._bond_partner_session()
        if (
            self.character.level >= 40
            and spouse is not None
            and self.healing_partner_id == spouse.character.character_id
            and spouse.character.map_id == self.character.map_id
            and spouse.line_id == self.line_id
            and spouse.copy_instance_id == self.copy_instance_id
        ):
            # Nya 2.1.1 skill 3304 grants a further 13% while cultivating together.
            experience_multiplier += 0.13
            essence_multiplier += 0.13
        _, meditation_event = self._active_double_gain()
        event_bonus = 1.0 if meditation_event else 0.0
        if self._has_active_vip():
            experience_multiplier *= 2.0
            essence_multiplier *= 2.0
        experience_item_bonus = self._active_gain_item_rate("exp") / 100.0
        essence_item_bonus = self._active_gain_item_rate("zq") / 100.0
        experience_multiplier += event_bonus + experience_item_bonus
        essence_multiplier += event_bonus + essence_item_bonus
        experience, progression.meditation_experience_remainder = divmod(
            progression.meditation_experience_remainder
            + round(max(2_000, self.character.level * 100 + 2_000) * experience_multiplier),
            self.MEDITATION_REWARD_DIVISOR,
        )
        chakra, progression.meditation_chakra_remainder = divmod(
            progression.meditation_chakra_remainder
            + round(max(400, self.character.level * 8 + 200) * essence_multiplier),
            self.MEDITATION_REWARD_DIVISOR,
        )
        self._grant_experience(experience, apply_item_effect=False)
        xinfa_update: SkillState | None = None
        with self.store.lock:
            self._add_zq(chakra)
            xinfa_id = self._default_xinfa_id()
            xinfa_skill = self.store.state.skills.get(xinfa_id)
            xinfa_definition = GAME_DATA_CATALOG.get_skill_definition(xinfa_id)
            if (
                xinfa_skill is not None
                and xinfa_definition is not None
                and GAME_DATA_CATALOG.is_xinfa_skill(xinfa_id)
                and self._increase_skill_mastery(xinfa_skill, xinfa_definition)
            ):
                xinfa_update = xinfa_skill
            current_zq = self.character.zq
            self.store.save()
        self._send_stats({StatType.ZQ: current_zq})
        if xinfa_update is not None:
            self._send_skill_update(xinfa_update)
        # The stat packets above already trigger the client's native gain
        # floaters. Skill updates also trigger the client's original xinfa +1 tip.

    def _try_auto_use_potion(self, now: float) -> None:
        """Legacy test helper; live auto-use is triggered exclusively by the Flash client."""
        if now - self.last_auto_potion_at < 1.0:
            return
        config = self.store.state.character_config
        maximum_hp = self._current_max_hp()
        maximum_mp = self._current_max_mp()
        hp_threshold = max(1, min(99, self._config_int(config, "auotReplyHpValue", 70)))
        mp_threshold = max(1, min(99, self._config_int(config, "auotReplyMpValue", 50)))
        need_hp = (
            self._config_bool(config, "autoReplyHp", True)
            and self.character.hp < maximum_hp
            and self.character.hp * 100 <= maximum_hp * hp_threshold
        )
        mp_sealed = self._is_mp_sealed()
        need_mp = (
            not mp_sealed
            and self._config_bool(config, "autoReplyMp", True)
            and self.character.mp < maximum_mp
            and self.character.mp * 100 <= maximum_mp * mp_threshold
        )
        if not need_hp and not need_mp:
            return
        self.last_auto_potion_at = now
        for slot, item in sorted(self.store.state.inventory.items()):
            if slot <= 0 or item.quantity <= 0:
                continue
            definition = GAME_DATA_CATALOG.get_item_definition(item.item_id)
            if definition is None or self.character.level < definition.required_level:
                continue
            if mp_sealed and definition.mp_restore > 0:
                continue
            if not (
                (need_hp and definition.hp_restore > 0)
                or (need_mp and definition.mp_restore > 0)
            ):
                continue
            with self.store.lock:
                current = self.store.state.inventory.get(slot)
                if current is None or current.item_id != item.item_id or current.quantity <= 0:
                    return
                hp_before = self.character.hp
                mp_before = self.character.mp
                current.quantity -= 1
                self.character.hp = min(maximum_hp, self.character.hp + definition.hp_restore)
                self.character.mp = min(maximum_mp, self.character.mp + definition.mp_restore)
                removed = current.quantity == 0
                if removed:
                    del self.store.state.inventory[slot]
                self.store.save()
            if removed:
                self._send_inventory_clear(slot, InventoryType.BAG)
            else:
                self._send_inventory_update(current, from_drop=0)
            updates: dict[StatType, int] = {}
            if definition.hp_restore:
                updates[StatType.HP] = self.character.hp
            if definition.mp_restore:
                updates[StatType.MP] = self.character.mp
            if updates:
                self._send_stats(updates)
                self._share_bond_potion(
                    definition.hp_restore,
                    definition.mp_restore,
                )
            print(
                f"[auto-potion] item={item.item_id} slot={slot} "
                f"hp={self.character.hp}/{maximum_hp} mp={self.character.mp}/{maximum_mp}",
                flush=True,
            )
            restored: list[str] = []
            if self.character.hp > hp_before:
                restored.append(f"生命 {self.character.hp - hp_before}")
            if self.character.mp > mp_before:
                restored.append(f"查克拉 {self.character.mp - mp_before}")
            if restored:
                self._send_character_notice(
                    f"自动使用{definition.name}，恢复{'、'.join(restored)}。"
                )
            return

    def _share_bond_potion(self, hp_value: int, mp_value: int) -> None:
        """Share a ring-stage percentage of medicine with an online same-map spouse."""
        spouse = self._bond_partner_session()
        account = self.accounts.account_by_id(self.account_id) if self.account_id else None
        half_ring = int(account.get("bondHalfRingItem", 0)) if account else 0
        stage = (half_ring // 10_000) % 10
        share_rate = max(0, min(100, stage * 10))
        if (
            spouse is None
            or share_rate <= 0
            or spouse.character.map_id != self.character.map_id
            or spouse.line_id != self.line_id
            or spouse.copy_instance_id != self.copy_instance_id
        ):
            return
        hp_gain = max(0, round(int(hp_value) * share_rate / 100))
        mp_gain = max(0, round(int(mp_value) * share_rate / 100))
        with spouse.store.lock:
            previous_hp = spouse.character.hp
            previous_mp = spouse.character.mp
            spouse.character.hp = min(
                spouse._current_max_hp(),
                spouse.character.hp + hp_gain,
            )
            spouse.character.mp = min(
                spouse._current_max_mp(),
                spouse.character.mp + mp_gain,
            )
            if spouse.character.hp != previous_hp or spouse.character.mp != previous_mp:
                spouse.store.save()
        updates: dict[StatType, int] = {}
        if spouse.character.hp != previous_hp:
            updates[StatType.HP] = spouse.character.hp
        if spouse.character.mp != previous_mp:
            updates[StatType.MP] = spouse.character.mp
        if updates:
            spouse._send_stats(updates)
            spouse._send_character_notice(
                f"羁绊共享药品，恢复生命{spouse.character.hp - previous_hp}、"
                f"查克拉{spouse.character.mp - previous_mp}。"
            )

    @staticmethod
    def _config_bool(config: dict[str, Any], name: str, default: bool) -> bool:
        value = config.get(name, default)
        if isinstance(value, bool):
            return value
        return str(value).strip().lower() in {"1", "true", "yes", "on"}

    @staticmethod
    def _config_int(config: dict[str, Any], name: str, default: int) -> int:
        try:
            return int(float(config.get(name, default)))
        except (TypeError, ValueError):
            return default

    def handle_pet_action(self, read_str: str) -> None:
        """Handle original pet summon, growth, skill, equipment, and movement actions."""
        fields = self._request_fields(read_str, ClientOpcode.PET_ACTION)
        if not fields:
            return
        try:
            action = PetRequestAction(self._safe_int(fields[0], -1))
        except ValueError:
            return
        if action == PetRequestAction.CREATE:
            self._send_pet_list()
            return
        if action == PetRequestAction.CATCH:
            if len(fields) > 1:
                self._catch_pet(self._safe_int(fields[1], 0))
            return
        if action == PetRequestAction.EXTEND_LIMIT:
            self._extend_pet_capacity()
            return
        unique_id = self._safe_int(fields[1], 0) if len(fields) > 1 else 0
        pet = self.store.state.pets.get(unique_id)
        if pet is None:
            return
        if action == PetRequestAction.CALL_OUT:
            self._activate_pet(pet, PetPosition.ATTACHED)
        elif action == PetRequestAction.CALL_BACK:
            pet.position = op(PetPosition.BAG)
            self.store.save()
            self._send_pet_unshow(pet)
        elif action == PetRequestAction.ATTACK_OUT:
            self._activate_pet(pet, PetPosition.ATTACKING)
        elif action == PetRequestAction.ATTACK_BACK:
            pet.position = op(PetPosition.BAG)
            self.store.save()
            self._send_pet_unshow(pet)
        elif action == PetRequestAction.RENAME and len(fields) > 2:
            pet.name = fields[2].replace(":", "")[:12] or pet.name
            self.store.save()
            self.send_text(
                f"{op(ServerOpcode.PET_ACTION)}:{op(PetResponseAction.UPDATE_NAME)}:"
                f"{self.character.character_id}:{pet.unique_id}:{pet.name}"
            )
        elif action == PetRequestAction.FEED and len(fields) > 2:
            self._feed_pet(pet, self._safe_int(fields[2], 0))
        elif action == PetRequestAction.REWASH_APTITUDE:
            self._rewash_pet_aptitude(pet)
        elif action == PetRequestAction.CHANGE_SAVVY:
            self._increase_pet_savvy(pet)
        elif action == PetRequestAction.LEARN_SKILL and len(fields) > 2:
            self._learn_pet_skill(pet, self._safe_int(fields[2], 0))
        elif action == PetRequestAction.PUT_EQUIPMENT and len(fields) > 2:
            self._put_on_pet_equipment(pet, self._safe_int(fields[2], 0))
        elif action == PetRequestAction.TAKE_OFF_EQUIPMENT and len(fields) > 2:
            self._take_off_pet_equipment(pet, self._safe_int(fields[2], 0))
        elif action == PetRequestAction.EVOLUTION_UP:
            help_item_count = max(0, self._safe_int(fields[2], 0)) if len(fields) > 2 else 0
            self._advance_pet(pet, help_item_count)
        elif action == PetRequestAction.STRENGTH_POTENTIAL and len(fields) > 3:
            self._strengthen_pet_potential(
                pet,
                max(0, self._safe_int(fields[2], 0)),
                self._safe_int(fields[3], 0),
            )
        elif action == PetRequestAction.SOUL_FUSION and len(fields) > 2:
            self._fuse_pet_soul(pet, self._safe_int(fields[2], -1))
        elif action == PetRequestAction.MOVE:
            # The request already contains MovementList.decode2 fields 2..14; add owner at 15.
            movement = ":".join(fields[1:15])
            self.send_text(
                f"{op(ServerOpcode.PET_ACTION)}:{op(PetResponseAction.MOVE)}:{movement}:"
                f"{self.character.character_id}"
            )
        elif action == PetRequestAction.RELEASE:
            self._release_pet(pet)
        if action != PetRequestAction.MOVE:
            self._send_all_stats()

    def _release_pet(self, pet: PetState) -> bool:
        """Release one ordinary bag pet without silently deleting active gear."""
        if (
            pet.unique_id == 90_001
            and pet.item_id == int(PetTemplateId.STARTER_DOG)
        ):
            self._send_native_server_message("初始忍犬是绑定伙伴，不能放生。", 16)
            return False
        if pet.position != op(PetPosition.BAG):
            self._send_native_server_message("请先收回宠物，再进行放生。", 16)
            return False
        if pet.equipment:
            self._send_native_server_message("请先卸下宠物装备，再进行放生。", 16)
            return False
        with self.store.lock:
            current = self.store.state.pets.get(pet.unique_id)
            if current is not pet:
                return False
            del self.store.state.pets[pet.unique_id]
            self.store.save()
        self.send_text(
            f"{op(ServerOpcode.PET_ACTION)}:{op(PetResponseAction.DELETE)}:"
            f"{pet.unique_id}"
        )
        self._send_native_server_message(f"已放生宠物{pet.name}。", 16)
        return True

    def _catch_pet(self, monster_object_id: int) -> None:
        """Convert one nearby GameData-catchable monster into a persisted pet."""
        monster = self.monsters.get(monster_object_id)
        if monster is None or monster.hp <= 0 or monster.respawn_at:
            return
        definition = GAME_DATA_CATALOG.get_monster_definition(monster.template_id)
        if definition.pet_link <= 0:
            self._send_native_server_message("这个怪物不能捕捉。", 16)
            return
        if len(self.store.state.pets) >= self.store.state.pet_capacity:
            self._send_native_server_message("宠物栏位不足，无法捕捉。", 16)
            return
        if (self.x - monster.x) ** 2 + (self.y - monster.y) ** 2 > 280**2:
            self._send_native_server_message("距离太远，无法捕捉宠物。", 16)
            return
        unique_id = max(self.store.state.pets, default=90_000) + 1
        pet = PetState(
            unique_id=unique_id,
            item_id=definition.pet_link,
            name=f"宠物{definition.pet_link}",
            level=max(1, min(self.character.level, definition.level)),
            position=op(PetPosition.BAG),
            aptitude=definition.pet_aptitude,
            can_trade=True,
        )
        default_skill_id = GAME_DATA_CATALOG.get_pet_default_skill(pet.item_id)
        pet.skills = (
            {default_skill_id: SkillState(default_skill_id)}
            if default_skill_id > 0
            else {}
        )
        minimum, _ = GAME_DATA_CATALOG.get_pet_potential_bounds(
            pet.item_id, pet.aptitude
        )
        pet.potential_total_atk = minimum
        pet.potential_total_def = minimum
        pet.potential_total_dex = minimum
        pet.potential_total_str = minimum
        with self.store.lock:
            self.store.state.pets[pet.unique_id] = pet
            monster.hp = 0
            monster.respawn_at = time.monotonic() + self._monster_respawn_delay(
                monster, definition
            )
            self.store.save()
        self._send_visible(
            f"{op(ServerOpcode.KILL_MONSTER)}:{monster.object_id}:"
            f"{op(MonsterRemovalAnimation.IMMEDIATE)}"
        )
        self.send_text(
            f"{op(ServerOpcode.PET_ACTION)}:{op(PetResponseAction.CREATE)}:"
            f"{self._encode_pet_update(pet)}"
        )
        for quest_id, progress in tuple(self.store.state.original_quests.items()):
            if QuestState(progress.state) != QuestState.ACTIVE:
                continue
            quest = GAME_DATA_CATALOG.get_quest_definition(quest_id)
            if quest is None:
                continue
            if any(
                objective.kind == QuestObjectiveKind.PET
                and objective.target_id == pet.item_id
                for objective in quest.objectives
            ):
                self._advance_original_quest(
                    quest,
                    QuestObjectiveKind.PET,
                    pet.item_id,
                    1,
                    self.character.map_id,
                )
        self._send_native_server_message("捕捉宠物成功。", 16)

    def handle_buff_he_cheng(self, read_str: str) -> None:
        """Consume two selected ingredients and return the authored cooking result."""
        # The native client writes an int action followed by an AMF object with
        # item0/item1 slots.  Keep the older colon form for diagnostic tools,
        # but parse the real JSON object as one unit instead of splitting it on
        # the colons inside the object.
        payload = self._strip_timestamp(read_str)
        prefix = f"{op(ClientOpcode.BUFF_HECHENG)}:"
        if payload.startswith(prefix):
            payload = payload[len(prefix) :]
        raw_action, separator, raw_data = payload.partition(":")
        if not separator or self._safe_int(raw_action, -1) != 1:
            return
        first_slot = 0
        second_slot = 0
        if raw_data.lstrip().startswith("{"):
            try:
                request_data = json.loads(raw_data)
            except (ValueError, json.JSONDecodeError):
                request_data = {}
            if isinstance(request_data, dict):
                first_slot = self._safe_int(request_data.get("item0"), 0)
                second_slot = self._safe_int(request_data.get("item1"), 0)
        else:
            raw_first, slot_separator, raw_second = raw_data.partition(":")
            if slot_separator:
                first_slot = self._safe_int(raw_first, 0)
                second_slot = self._safe_int(raw_second, 0)
        first_item = self.store.state.inventory.get(first_slot)
        second_item = self.store.state.inventory.get(second_slot)
        if (
            first_slot <= 0
            or second_slot <= 0
            or first_slot == second_slot
            or first_item is None
            or second_item is None
            or first_item.quantity <= 0
            or second_item.quantity <= 0
            or first_item.item_id == second_item.item_id
            or first_item.item_id // 10_000 != 1601
            or second_item.item_id // 10_000 != 1601
        ):
            self.send_text(f"{op(ServerOpcode.BUFF_HECHENG)}:2:0")
            return
        money_cost = GAME_DATA_CATALOG.cooking_cost()
        result_item_id = GAME_DATA_CATALOG.cooking_result(
            first_item.item_id,
            second_item.item_id,
        )
        result_stack_exists = any(
            item.slot > 0 and item.item_id == result_item_id
            for item in self.store.state.inventory.values()
        )
        source_slot_will_free = first_item.quantity == 1 or second_item.quantity == 1
        if (
            self.store.state.money < money_cost
            or (
                result_item_id > 0
                and not result_stack_exists
                and not source_slot_will_free
                and not self._has_inventory_capacity([(result_item_id, 1)])
            )
        ):
            self.send_text(f"{op(ServerOpcode.BUFF_HECHENG)}:2:0")
            return
        with self.store.lock:
            first_changed, first_removed = self._consume_bag_slot(
                first_slot,
                first_item.item_id,
            )
            second_changed, second_removed = self._consume_bag_slot(
                second_slot,
                second_item.item_id,
            )
            if first_changed is None or second_changed is None:
                return
            self.store.state.money -= money_cost
            result_item = None
            if result_item_id > 0:
                result_item, _ = self._add_inventory_item(result_item_id, 1)
            self.store.save()
        for changed, removed in (
            (first_changed, first_removed),
            (second_changed, second_removed),
        ):
            if removed:
                self._send_inventory_clear(changed.slot, InventoryType.BAG)
            else:
                self._send_inventory_update(changed, from_drop=0)
        self._send_stats({StatType.MONEY: self.store.state.money})
        if result_item is not None:
            self._send_inventory_add(result_item, from_drop=0)
        self.send_text(f"{op(ServerOpcode.BUFF_HECHENG)}:2:{result_item_id}")

    def handle_can_juan_action(self, read_str: str) -> None:
        """Compose one skill book from its authored fragments and optional lucky charms."""
        fields = self._request_fields(read_str, ClientOpcode.CAN_JUAN_ACTION)
        if len(fields) < 3 or self._safe_int(fields[0], -1) != 0:
            return
        selected_unique_id = self._safe_int(fields[1], 0)
        requested_helper_count = max(0, self._safe_int(fields[2], 0))
        selected_item = next(
            (
                item
                for item in self.store.state.inventory.values()
                if item.slot > 0 and item.unique_id == selected_unique_id
            ),
            None,
        )
        recipe = (
            GAME_DATA_CATALOG.skill_fragment_recipe(selected_item.item_id)
            if selected_item is not None
            else None
        )
        if selected_item is None or recipe is None:
            self.send_text(f"{op(ServerOpcode.CAN_JUAN_ACTION)}:0:0")
            return
        book_id, fragment_count = recipe
        zq_cost, base_probability, helper_item_id = (
            GAME_DATA_CATALOG.skill_fragment_composition_config()
        )
        helper_count = min(9, requested_helper_count)
        fragment_available = self._inventory_item_quantity(selected_item.item_id)
        helper_available = (
            self._inventory_item_quantity(helper_item_id)
            if helper_item_id > 0
            else 0
        )
        if (
            fragment_available < fragment_count
            or self.character.zq < zq_cost
            or helper_count > helper_available
        ):
            self.send_text(f"{op(ServerOpcode.CAN_JUAN_ACTION)}:0:0")
            return

        result_stack_exists = any(
            item.slot > 0 and item.item_id == book_id
            for item in self.store.state.inventory.values()
        )
        source_slot_will_free = fragment_available == fragment_count
        helper_slot_will_free = (
            helper_count > 0 and helper_available == helper_count
        )
        if (
            not result_stack_exists
            and not source_slot_will_free
            and not helper_slot_will_free
            and not self._has_inventory_capacity([(book_id, 1)])
        ):
            self.send_text(f"{op(ServerOpcode.CAN_JUAN_ACTION)}:0:0")
            return

        probability = min(100, base_probability + helper_count * 3)
        succeeded = self.random.randrange(100) < probability
        with self.store.lock:
            inventory_changes = self._consume_inventory_quantity(
                selected_item.item_id,
                fragment_count,
            )
            if helper_count > 0:
                inventory_changes.extend(
                    self._consume_inventory_quantity(helper_item_id, helper_count)
                )
            self.character.zq -= zq_cost
            result_item = None
            result_created = False
            if succeeded:
                result_item, result_created = self._add_inventory_item(book_id, 1)
            self.store.save()

        for item, removed in inventory_changes:
            if removed:
                self._send_inventory_clear(item.slot, InventoryType.BAG)
            else:
                self._send_inventory_update(item, from_drop=0)
        self._send_stats({StatType.ZQ: self.character.zq})
        if result_item is not None:
            if result_created:
                self._send_inventory_add(result_item, from_drop=0)
            else:
                self._send_inventory_update(result_item, from_drop=0)
        self.send_text(
            f"{op(ServerOpcode.CAN_JUAN_ACTION)}:0:{1 if succeeded else 0}"
        )

    def _consume_pet_growth_cost(
        self,
        config: dict[str, Any],
        requested_help_count: int = 0,
    ) -> tuple[list[tuple[InventoryItem, bool]], int] | None:
        """Consume one original pet-growth row and return changed stacks plus helper count."""
        material_id = self._safe_int(config.get("needItemId"), 0)
        material_count = max(0, self._safe_int(config.get("needItemCnt"), 0))
        money_cost = max(0, self._safe_int(config.get("needMoney"), 0))
        help_item_id = self._safe_int(config.get("helpItemId"), 0)
        help_count = min(max(0, requested_help_count), self._inventory_item_quantity(help_item_id))
        if self._inventory_item_quantity(material_id) < material_count:
            material_name = self._item_display_name(material_id, "宠物培养材料")
            self._send_system_chat(f"请先在木叶商店购买{material_name}。")
            return None
        if self.store.state.money < money_cost:
            self._send_system_chat("金币不足。")
            return None
        changes = self._consume_inventory_quantity(material_id, material_count)
        if help_count > 0:
            changes.extend(self._consume_inventory_quantity(help_item_id, help_count))
        self.store.state.money -= money_cost
        return changes, help_count

    def _finish_pet_growth(
        self,
        pet: PetState,
        changes: list[tuple[InventoryItem, bool]],
    ) -> None:
        """Persist a pet growth attempt and refresh its materials, gold, and full data."""
        self.store.save()
        for item, removed in changes:
            if removed:
                self._send_inventory_clear(item.slot, InventoryType.BAG)
            else:
                self._send_inventory_update(item, from_drop=0)
        self._send_stats({StatType.MONEY: self.store.state.money})
        self.send_text(
            f"{op(ServerOpcode.PET_ACTION)}:{op(PetResponseAction.UPDATE)}:"
            f"{self._encode_pet_update(pet)}"
        )

    def _rewash_pet_aptitude(self, pet: PetState) -> None:
        """Raise pet aptitude only when the original template explicitly enables rewashing."""
        pet_config = GAME_DATA_CATALOG.get_pet_config(pet.item_id)
        info = pet_config.get("info") if isinstance(pet_config.get("info"), dict) else {}
        aptitude_root = info.get("aptitude") if isinstance(info.get("aptitude"), dict) else {}
        if self._safe_int(aptitude_root.get("enable"), 0) == 0 or pet.aptitude >= 4:
            self._send_system_chat("这只宠物的资质重置未开放。")
            return
        config = GAME_DATA_CATALOG.get_pet_growth_config(pet.item_id, "aptitude", pet.aptitude)
        previous_aptitude = pet.aptitude
        with self.store.lock:
            paid = self._consume_pet_growth_cost(config)
            if paid is None:
                return
            changes, _ = paid
            succeeded = self._roll_forge(self._safe_int(config.get("probability"), 0))
            if succeeded:
                pet.aptitude += 1
                self._reroll_pet_potential_totals(pet)
            self._finish_pet_growth(pet, changes)
        if succeeded:
            self._send_character_notice(
                f"通灵兽品级提升成功，从 {previous_aptitude} 提升至 {pet.aptitude}。"
            )
        else:
            self._send_character_notice("通灵兽品级提升失败，本次属性未改变。")

    def _increase_pet_savvy(self, pet: PetState) -> None:
        """Increase pet savvy using its original aptitude-specific material and gold row."""
        if pet.savvy >= 100:
            self._send_character_notice("该通灵兽悟性已经达到上限。")
            return
        config = GAME_DATA_CATALOG.get_pet_growth_config(pet.item_id, "savvy", pet.aptitude)
        if not config:
            self._send_character_notice("该通灵兽当前无法提升悟性。")
            return
        previous_savvy = pet.savvy
        with self.store.lock:
            paid = self._consume_pet_growth_cost(config)
            if paid is None:
                return
            changes, _ = paid
            succeeded = self._roll_forge(self._safe_int(config.get("probability"), 0))
            if succeeded:
                pet.savvy = min(100, pet.savvy + 1)
            self._finish_pet_growth(pet, changes)
        if succeeded:
            self._send_character_notice(
                f"通灵兽悟性提升成功，从 {previous_savvy} 提升至 {pet.savvy}。"
            )
        else:
            self._send_character_notice("通灵兽悟性提升失败，本次属性未改变。")

    def _strengthen_pet_potential(
        self,
        pet: PetState,
        requested_help_count: int,
        potential_type: int,
    ) -> None:
        """Raise one of attack, defence, dexterity, or strength potential toward its cap."""
        potential_fields = {
            1: ("potential_real_atk", "potential_total_atk", "攻击潜力"),
            2: ("potential_real_def", "potential_total_def", "防御潜力"),
            3: ("potential_real_dex", "potential_total_dex", "灵巧潜力"),
            4: ("potential_real_str", "potential_total_str", "健体潜力"),
        }
        selected = potential_fields.get(potential_type)
        if selected is None:
            self._send_character_notice("请选择需要提升的通灵兽属性。")
            return
        real_field, total_field, attribute_name = selected
        if getattr(pet, real_field) >= getattr(pet, total_field):
            self._send_system_chat("该项宠物潜能已达上限。")
            return
        config = GAME_DATA_CATALOG.get_pet_growth_config(pet.item_id, "potential", pet.aptitude)
        previous_value = getattr(pet, real_field)
        with self.store.lock:
            paid = self._consume_pet_growth_cost(config, requested_help_count)
            if paid is None:
                return
            changes, help_count = paid
            probability = self._safe_int(config.get("probability"), 0) + help_count * 3
            succeeded = self._roll_forge(probability)
            if succeeded:
                setattr(
                    pet,
                    real_field,
                    min(getattr(pet, total_field), getattr(pet, real_field) + 1),
                )
            self._finish_pet_growth(pet, changes)
        if succeeded:
            self._send_character_notice(
                f"通灵兽{attribute_name}提升成功，从 {previous_value} "
                f"提升至 {getattr(pet, real_field)}。"
            )
        else:
            self._send_character_notice(
                f"通灵兽{attribute_name}提升失败，本次属性未改变。"
            )

    def _reroll_pet_potential_totals(self, pet: PetState) -> None:
        """Raise aptitude potentials without erasing permanent charm gains."""
        minimum, maximum = GAME_DATA_CATALOG.get_pet_potential_bounds(
            pet.item_id, pet.aptitude
        )
        for attr in ("atk", "def", "dex", "str"):
            real_field = f"potential_real_{attr}"
            total_field = f"potential_total_{attr}"
            rolled = self.random.randint(minimum, maximum)
            # Potential charms permanently raise both values. Aptitude rerolls
            # may improve their cap, but must never lower it or leave current
            # potential above the cap (the client renders that as a negative).
            new_total = max(
                0,
                rolled,
                getattr(pet, total_field),
                getattr(pet, real_field),
            )
            setattr(pet, total_field, new_total)
            setattr(pet, real_field, max(0, min(getattr(pet, real_field), new_total)))

    def _learn_pet_skill(self, pet: PetState, item_id: int, slot: int = 0) -> None:
        """Consume one original 07 pet skill book and learn or upgrade its configured skill."""
        definition = GAME_DATA_CATALOG.get_item_definition(item_id)
        if definition is None or item_id // 1_000_000 != 7 or definition.skill_id <= 0:
            self._send_system_chat("这不是可学习的宠物技能书。")
            return
        with self.store.lock:
            if slot > 0:
                item = self.store.state.inventory.get(slot)
                if item is None or item.item_id != item_id:
                    return
                consumed, removed = self._consume_bag_slot(slot, item_id)
                changes = [(consumed, removed)] if consumed is not None else []
            else:
                changes = self._consume_inventory_quantity(item_id, 1)
            if not changes:
                self._send_system_chat("背包里没有这本宠物技能书。")
                return
            skill = pet.skills.get(definition.skill_id)
            if skill is None:
                skill = SkillState(definition.skill_id)
                pet.skills[skill.skill_id] = skill
            else:
                skill.level = min(10, skill.level + 1)
            self.store.save()
        for changed_item, removed in changes:
            if removed:
                self._send_inventory_clear(changed_item.slot, InventoryType.BAG)
            else:
                self._send_inventory_update(changed_item, from_drop=0)
        # Native action 12 appends a numeric id into an Array<SkillInfo> and
        # corrupts the open panel. Action 17 replaces it with decoded SkillInfo
        # rows and action 2 refreshes the rest of the selected pet immediately.
        self._send_pet_skill_list(pet)
        self.send_text(
            f"{op(ServerOpcode.PET_ACTION)}:{op(PetResponseAction.UPDATE)}:"
            f"{self._encode_pet_update(pet)}"
        )

    def _auto_learn_pet_skills(self, pet: PetState) -> list[int]:
        """Unlock one configured pet skill every 10 levels as the pet grows."""
        pet_config = GAME_DATA_CATALOG.get_pet_config(pet.item_id)
        skills_config = (
            pet_config.get("skills")
            if isinstance(pet_config.get("skills"), dict)
            else {}
        )
        learned: list[int] = []
        slots = sorted(
            (int(key) for key in skills_config if str(key).isdigit()),
        )
        for slot in slots:
            row = skills_config.get(str(slot))
            if not isinstance(row, dict):
                continue
            skill_id = self._safe_int(row.get("skillid"), 0)
            if skill_id <= 0 or skill_id in pet.skills:
                continue
            unlock_level = (slot + 1) * 10
            if pet.level >= unlock_level:
                pet.skills[skill_id] = SkillState(skill_id)
                learned.append(skill_id)
        return learned

    def _use_pet_skill_symbol(
        self,
        slot: int,
        definition: ItemDefinition,
        selection: dict[str, Any],
    ) -> None:
        """Use one 神奇技能符 to learn or replace a pet skill."""
        pet_uid = self._safe_int(selection.get("petUid"), 0)
        old_skill_id = self._safe_int(selection.get("oldskill"), 0)
        new_skill_id = self._safe_int(selection.get("newskill"), 0)
        pet = self.store.state.pets.get(pet_uid)
        if pet is None:
            self._send_system_chat("请选择要操作的宠物。")
            return
        new_definition = GAME_DATA_CATALOG.get_pet_skill_definition(new_skill_id)
        if new_skill_id <= 0 or new_definition is None:
            self._send_system_chat("请选择要学习的通灵兽技能。")
            return
        already_owned = new_skill_id in pet.skills
        if already_owned and old_skill_id == new_skill_id:
            self._send_system_chat("新旧技能相同，无需替换。")
            return
        if already_owned and old_skill_id not in pet.skills:
            self._send_system_chat("宠物已拥有该技能，请选择要替换的旧技能。")
            return
        pet_config = GAME_DATA_CATALOG.get_pet_config(pet.item_id)
        skills_config = (
            pet_config.get("skills")
            if isinstance(pet_config.get("skills"), dict)
            else {}
        )
        max_slots = sum(1 for key in skills_config if str(key).isdigit()) or 7
        if (
            not already_owned
            and len(pet.skills) >= max_slots
            and old_skill_id not in pet.skills
        ):
            self._send_system_chat("宠物技能栏已满，请先选择一个要替换的旧技能。")
            return
        with self.store.lock:
            consumed, _ = self._consume_parameter_item(slot, definition)
            if consumed is None:
                return
            if old_skill_id in pet.skills and old_skill_id != new_skill_id:
                del pet.skills[old_skill_id]
            if new_skill_id not in pet.skills:
                pet.skills[new_skill_id] = SkillState(new_skill_id)
            self.store.save()
        self._send_pet_skill_list(pet)
        self.send_text(
            f"{op(ServerOpcode.PET_ACTION)}:{op(PetResponseAction.UPDATE)}:"
            f"{self._encode_pet_update(pet)}"
        )
        self._send_character_notice(
            "新技能已存在，已替换旧技能。"
            if already_owned
            else "宠物技能已学习成功。"
        )

    def _send_pet_skill_list(self, pet: PetState) -> None:
        """Refresh every pet skill after a reset with PetProcessor action 17."""
        encoded = "@".join(
            f"{skill.skill_id}&{skill.level}&{skill.master_level}"
            for skill in sorted(pet.skills.values(), key=lambda value: value.skill_id)
        ) or "-"
        self.send_text(
            f"{op(ServerOpcode.PET_ACTION)}:{op(PetResponseAction.UPDATE_SKILL_LIST)}:"
            f"{self.character.character_id}:{pet.unique_id}:{encoded}"
        )

    def _put_on_pet_equipment(self, pet: PetState, bag_slot: int) -> None:
        """Move one validated PetA-PetE CocoEquip from the bag into the selected pet."""
        item = self.store.state.inventory.get(bag_slot)
        definition = GAME_DATA_CATALOG.get_pet_equipment_definition(item.item_id) if item else None
        if item is None or bag_slot <= 0 or definition is None:
            self._send_system_chat("请放入通灵兽装备。")
            return
        if pet.level < definition.required_level:
            self._send_system_chat(f"宠物需要达到 {definition.required_level} 级才能穿戴。")
            return
        position = op(definition.position)
        if (
            position == op(PetEquipmentPosition.TRANSFORM)
            and definition.additional_attributes
        ):
            item.plus_attributes = [
                [int(attribute_type), int(value)]
                for attribute_type, value in definition.additional_attributes
            ]
        newly_bound = self._binds_when_equipped(
            item,
            character_equipment=False,
        )
        with self.store.lock:
            previous = pet.equipment.get(position)
            if newly_bound:
                self._bind_item_instance(item)
            del self.store.state.inventory[bag_slot]
            if previous is not None:
                previous.slot = bag_slot
                self.store.state.inventory[bag_slot] = previous
            item.slot = position
            pet.equipment[position] = item
            self.store.save()
        self._send_inventory_clear(bag_slot, InventoryType.BAG)
        if previous is not None:
            self._send_inventory_add(previous, from_drop=0)
        self.send_text(
            f"{op(ServerOpcode.PET_ACTION)}:{op(PetResponseAction.UPDATE_EQUIPMENT)}:"
            f"{self.character.character_id}:{pet.unique_id}:{self._encode_item_payload(item)}"
        )
        self.send_text(
            f"{op(ServerOpcode.PET_ACTION)}:{op(PetResponseAction.UPDATE)}:"
            f"{self._encode_pet_update(pet)}"
        )
        if position == op(PetEquipmentPosition.TRANSFORM):
            self._send_pet_face_update(pet)
            self._refresh_pet_transform_skin(pet)
        if newly_bound:
            self._send_character_notice("装备成功，物品已绑定。")

    def _take_off_pet_equipment(self, pet: PetState, position: int) -> None:
        """Return one pet equipment instance to the first free character bag slot."""
        item = pet.equipment.get(position)
        if item is None:
            return
        bag_slot = next(
            (slot for slot in range(1, self.store.state.bag_capacity + 1) if slot not in self.store.state.inventory),
            0,
        )
        if bag_slot == 0:
            self._send_system_chat("背包已满，无法卸下宠物装备。")
            return
        with self.store.lock:
            del pet.equipment[position]
            item.slot = bag_slot
            self.store.state.inventory[bag_slot] = item
            self.store.save()
        self._send_inventory_add(item, from_drop=0)
        self.send_text(
            f"{op(ServerOpcode.PET_ACTION)}:{op(PetResponseAction.REMOVE_EQUIPMENT)}:"
            f"{self.character.character_id}:{pet.unique_id}:{position}"
        )
        self.send_text(
            f"{op(ServerOpcode.PET_ACTION)}:{op(PetResponseAction.UPDATE)}:"
            f"{self._encode_pet_update(pet)}"
        )
        if position == op(PetEquipmentPosition.TRANSFORM):
            self._send_pet_face_update(pet)
            self._refresh_pet_transform_skin(pet)

    def _refresh_pet_transform_skin(self, pet: PetState) -> None:
        """Recreate a visible pet actor so its equipped transform skin changes now."""
        if pet.position == op(PetPosition.BAG):
            return
        self._send_pet_unshow(pet, PetPosition.BAG)
        self._send_pet_spawn(pet)

    def _send_pet_face_update(self, pet: PetState) -> None:
        """Refresh a live pet actor after equipping or removing its PetE card."""
        self.send_text(
            f"{op(ServerOpcode.PET_ACTION)}:{op(PetResponseAction.UPDATE_STATS)}:"
            f"{self.character.character_id}:{pet.unique_id}:"
            f"5&{self._pet_skin(pet)}"
        )

    def _advance_pet(self, pet: PetState, requested_help_count: int) -> None:
        """Consume original Pet.evolution costs and emit actions 15/19 on success or failure."""
        previous_pet_id = pet.item_id
        config = GAME_DATA_CATALOG.get_pet_evolution_config(pet.item_id)
        next_pet_id = self._safe_int(config.get("nextPetId"), 0)
        if not config or self._safe_int(config.get("enable"), 0) == 0 or next_pet_id <= 0:
            self._send_system_chat("这只宠物已无法继续进阶。")
            return
        material_id = self._safe_int(config.get("needItemId"), 0)
        material_count = max(0, self._safe_int(config.get("needItemCnt"), 0))
        money_cost = max(0, self._safe_int(config.get("needMoney"), 0))
        help_item_id = self._safe_int(config.get("helpItemId"), 0)
        available_help = self._inventory_item_quantity(help_item_id) if help_item_id > 0 else 0
        help_count = min(requested_help_count, available_help)
        if self._inventory_item_quantity(material_id) < material_count:
            material_name = self._item_display_name(material_id, "宠物进阶材料")
            self._send_system_chat(f"请先在木叶商店购买{material_name}。")
            return
        if self.store.state.money < money_cost:
            self._send_system_chat("金币不足。")
            return
        with self.store.lock:
            inventory_changes = self._consume_inventory_quantity(material_id, material_count)
            if help_count > 0:
                inventory_changes.extend(self._consume_inventory_quantity(help_item_id, help_count))
            self.store.state.money -= money_cost
            probability = self._pet_evolution_success_chance(pet, config)
            succeeded = self.random.randrange(100) < probability
            if succeeded:
                pet.item_id = next_pet_id
                self._apply_pet_template_growth(
                    pet,
                    previous_pet_id,
                    next_pet_id,
                )
                next_name = GAME_DATA_CATALOG.get_pet_name(next_pet_id)
                if next_name:
                    pet.name = next_name.translate(SIMPLIFIED_TRANSLATION)
                pet.blessing = 0
                default_skill = GAME_DATA_CATALOG.get_pet_default_skill(next_pet_id)
                if not pet.skills and default_skill > 0:
                    pet.skills[default_skill] = SkillState(default_skill)
            else:
                pet_config = GAME_DATA_CATALOG.get_pet_config(pet.item_id)
                info = pet_config.get("info") if isinstance(pet_config.get("info"), dict) else {}
                maximum_blessing = max(1, self._safe_int(info.get("maxZhuFu"), 1000))
                blessing_config = (
                    config.get("zhufu")
                    if isinstance(config.get("zhufu"), dict)
                    else {}
                )
                # upZhuFu is the authored progress-bar target, not one failure's gain.
                # Twenty failed attempts reaches the guaranteed threshold for every tier.
                guaranteed_at = max(
                    1,
                    self._safe_int(blessing_config.get("reqZhuFu2"), 0),
                )
                blessing_gain = max(1, (guaranteed_at + 19) // 20)
                pet.blessing = min(maximum_blessing, pet.blessing + blessing_gain)
            self.store.save()
        for item, removed in inventory_changes:
            if removed:
                self._send_inventory_clear(item.slot, InventoryType.BAG)
            else:
                self._send_inventory_update(item, from_drop=0)
        self._send_stats({StatType.MONEY: self.store.state.money})
        if succeeded:
            self.send_text(
                f"{op(ServerOpcode.PET_ACTION)}:{op(PetResponseAction.EVOLUTION_UP)}:"
                f"{self._encode_pet_update(pet)}"
            )
        else:
            self.send_text(
                f"{op(ServerOpcode.PET_ACTION)}:{op(PetResponseAction.UPDATE)}:"
                f"{self._encode_pet_update(pet)}"
            )
        self.send_text(
            f"{op(ServerOpcode.PET_ACTION)}:{op(PetResponseAction.EVOLUTION_RESULT)}:"
            f"{self.character.character_id}:{pet.unique_id}:{1 if succeeded else 0}"
        )

    @staticmethod
    def _apply_pet_template_growth(
        pet: PetState,
        previous_pet_id: int,
        next_pet_id: int,
        *,
        fill_target_maximum: bool = False,
    ) -> None:
        """Apply the authored template increase without erasing permanent cultivation."""
        previous_minimum, _ = GAME_DATA_CATALOG.get_pet_potential_bounds(
            previous_pet_id,
            pet.aptitude,
        )
        next_minimum, next_maximum = GAME_DATA_CATALOG.get_pet_potential_bounds(
            next_pet_id,
            pet.aptitude,
        )
        template_gain = max(0, next_minimum - previous_minimum)
        required_value = next_maximum if fill_target_maximum else next_minimum
        for attribute in ("atk", "def", "dex", "str"):
            real_field = f"potential_real_{attribute}"
            total_field = f"potential_total_{attribute}"
            previous_real = max(0, int(getattr(pet, real_field)))
            previous_total = max(previous_real, int(getattr(pet, total_field)))
            updated_real = max(required_value, previous_real + template_gain)
            updated_total = max(
                required_value,
                updated_real,
                previous_total + template_gain,
            )
            setattr(pet, real_field, updated_real)
            setattr(pet, total_field, updated_total)

    def _pet_evolution_success_chance(
        self,
        pet: PetState,
        config: dict[str, Any],
    ) -> int:
        """Apply the client-described blessing thresholds to the authored base chance."""
        base = min(
            100,
            max(
                0,
                self._safe_int(
                    config.get("realprob"),
                    self._safe_int(config.get("probability"), 0),
                ),
            ),
        )
        blessing_config = (
            config.get("zhufu") if isinstance(config.get("zhufu"), dict) else {}
        )
        guaranteed_at = max(0, self._safe_int(blessing_config.get("reqZhuFu2"), 0))
        starts_at = max(0, self._safe_int(blessing_config.get("reqZhuFu1"), 0))
        if guaranteed_at <= 0 or pet.blessing < starts_at:
            return base
        if pet.blessing >= guaranteed_at:
            return 100
        span = max(1, guaranteed_at - starts_at)
        bonus = (100 - base) * (pet.blessing - starts_at) / span
        return min(100, max(base, round(base + bonus)))

    def _fuse_pet_soul(self, pet: PetState, raw_selection: int) -> None:
        """Transform an outstanding pet through PetRongHunTab action 22 and persist it."""
        try:
            selection = PetSoulFusionSelection(raw_selection)
        except ValueError:
            self._send_system_chat("该尾兽融魂选项尚未开放。")
            return
        target_pet_id = int(selection.target_pet_id())
        if pet.item_id in {int(value) for value in PetTemplateId if value != PetTemplateId.STARTER_DOG}:
            self._send_system_chat("这只宠物已经完成融魂。")
            return
        if pet.aptitude < 4:
            self._send_system_chat("只有卓越资质的宠物可以融魂。")
            return
        if self._pet_total_dream_score(pet) < 70:
            self._send_system_chat("融魂需要总梦幻度达到 70。")
            return
        target_config = GAME_DATA_CATALOG.get_pet_config(target_pet_id)
        if not target_config:
            self._send_system_chat("本地缺少该尾兽配置。")
            return
        cost_config = GAME_DATA_CATALOG.get_pet_evolution_config(target_pet_id)
        previous_pet_id = pet.item_id
        preserved_dream = max(0, min(100, pet.dream))
        with self.store.lock:
            paid = self._consume_pet_growth_cost(cost_config)
            if paid is None:
                return
            inventory_changes, _ = paid
            target_name = GAME_DATA_CATALOG.get_pet_name(target_pet_id)
            pet.item_id = target_pet_id
            pet.name = (
                target_name.translate(SIMPLIFIED_TRANSLATION)
                if target_name
                else pet.name
            )
            pet.blessing = 0
            self._apply_pet_template_growth(
                pet,
                previous_pet_id,
                target_pet_id,
                fill_target_maximum=True,
            )
            pet.dream = preserved_dream
            pet.skills = {
                skill_id: SkillState(skill_id)
                for skill_id in GAME_DATA_CATALOG.get_pet_default_skills(target_pet_id)
            }
            self.store.save()
        for item, removed in inventory_changes:
            if removed:
                self._send_inventory_clear(item.slot, InventoryType.BAG)
            else:
                self._send_inventory_update(item, from_drop=0)
        self._send_stats({StatType.MONEY: self.store.state.money})
        # Action 15 invokes PetHandler.onPetEvulutionUp, refreshing both the tab and map skin.
        self.send_text(
            f"{op(ServerOpcode.PET_ACTION)}:{op(PetResponseAction.EVOLUTION_UP)}:"
            f"{self._encode_pet_update(pet)}"
        )
        # PetHandler's evolution callback rebuilds the displayed CocoPet. Send
        # one ordinary full refresh afterwards so dream and cultivated values
        # cannot fall back to the target template defaults in the open panel.
        self.send_text(
            f"{op(ServerOpcode.PET_ACTION)}:{op(PetResponseAction.UPDATE)}:"
            f"{self._encode_pet_update(pet)}"
        )
        self._send_system_chat(f"{pet.name}融魂成功。")

    def _feed_pet(self, pet: PetState, item_id: int) -> None:
        """Consume one requested food item and refresh the pet's persisted fullness."""
        with self.store.lock:
            consumed, removed = self._consume_bag_item(item_id)
            if consumed is None:
                self._send_system_chat("背包里没有这种宠物食物。")
                return
            pet.fullness = min(100, pet.fullness + 10)
            self.store.save()
        if removed:
            self._send_inventory_clear(consumed.slot, InventoryType.BAG)
        else:
            self._send_inventory_update(consumed, from_drop=0)
        self.send_text(
            f"{op(ServerOpcode.PET_ACTION)}:{op(PetResponseAction.UPDATE)}:{self._encode_pet_update(pet)}"
        )
        if pet.position == op(PetPosition.ATTACHED):
            self._send_all_stats()

    def handle_pet_attack(self, read_str: str) -> None:
        """Validate one direct or triggered pet skill from the original client."""
        fields = self._request_fields(read_str, ClientOpcode.PET_ATTACK)
        skill_id = self._safe_int(fields[9], 0) if len(fields) > 9 else 0
        # Client.requestPetAttack increments SkillHandler's shared
        # fired_not_replay_count before every request. This counter also gates
        # normal player skills and locks all combat after four unacknowledged
        # pet casts. Release exactly one slot for every request, including a
        # miss, a target that died meanwhile, or a rejected/stale pet skill.
        self.send_text(f"{op(ServerOpcode.SKILL_BACK)}:{skill_id}")
        if len(fields) < 15:
            return
        if self._safe_int(fields[0], 0) != self.character.character_id:
            return
        pet = self.store.state.pets.get(self._safe_int(fields[1], 0))
        if pet is None or pet.position != op(PetPosition.ATTACKING):
            return
        skill_id = self._safe_int(fields[9], 101)
        skill = pet.skills.get(skill_id)
        if skill is None:
            if skill_id != 101:
                return
            skill = SkillState(101)
        definition = GAME_DATA_CATALOG.get_pet_skill_definition(skill.skill_id)
        if definition is None:
            return
        if definition.for_player and definition.effect_type in {"cure_hp", "cure_mp"}:
            self._apply_active_pet_cure(pet, skill, definition)
            return
        if definition.for_player:
            self._apply_triggered_pet_owner_buff(read_str, skill, definition, fields)
            return
        target_ids = fields[14].split("@") if fields[14] != "-" else []
        unique_target_ids = dict.fromkeys(
            target_id
            for raw in target_ids
            if (target_id := self._safe_int(raw, -1)) in self.monsters
            and self.monsters[target_id].hp > 0
        )
        targets = [self.monsters[target_id] for target_id in unique_target_ids]
        if not targets:
            return
        if definition.effect_type in PET_MONSTER_DEBUFF_EFFECTS:
            for target in targets:
                self._apply_pet_monster_status(target, skill, definition)
            return
        if definition.effect_type == "knock_back":
            self._send_visible(self._strip_timestamp(read_str), include_self=False)
            return
        target_limit = len(targets) if definition.target_type == 2 else 1
        for target in targets[:target_limit]:
            self._apply_pet_damage(pet, target, skill, definition)

    def _apply_pet_monster_status(
        self,
        monster: MonsterState,
        skill: SkillState,
        definition: PetSkillDefinition,
    ) -> None:
        """Persist one GameData pet Debuff on the shared monster state."""
        level = max(1, skill.level)
        if self.random.random() * 100 >= definition.trigger_percent(level):
            return
        effect_type = PET_MONSTER_DEBUFF_EFFECTS.get(definition.effect_type)
        if effect_type is None:
            return
        duration_ms = max(1_000, definition.duration_ms(level))
        now = time.monotonic()
        payload: dict[str, int | float] = {
            "skill_id": skill.skill_id,
            "skill_level": level,
            "value": definition.value(level),
            "value2": 0,
            "caster_id": self.character.character_id,
            "expires_at": now + duration_ms / 1_000.0,
            "next_tick_at": now + 1.0,
        }
        monster.skill_statuses[effect_type] = payload
        self._send_monster_status(monster, effect_type, payload)

    def _apply_triggered_pet_owner_buff(
        self,
        read_str: str,
        skill: SkillState,
        definition: PetSkillDefinition,
        fields: list[str],
    ) -> None:
        """Apply one client-triggered owner Buff after the authored probability roll."""
        buff_type = PET_OWNER_BUFF_TYPE_BY_EFFECT.get(definition.effect_type)
        if buff_type is None:
            return
        player_targets = {
            self._safe_int(value, 0)
            for value in (fields[13].split("@") if fields[13] != "-" else ())
        }
        if self.character.character_id not in player_targets:
            return
        level = max(1, skill.level)
        if self.random.random() * 100 >= definition.trigger_percent(level):
            return
        duration_ms = definition.duration_ms(level)
        if duration_ms <= 0:
            return
        self._apply_timed_skill_buff(
            buff_type=buff_type,
            skill_id=skill.skill_id,
            skill_level=level,
            value_percent=definition.value(level),
            duration_ms=duration_ms,
            effect_type=definition.effect_type,
        )
        # The casting client already queued PetBuffEffect locally. Peers still
        # need the original PetAttackInfo to render the pet and affected effect.
        self._send_visible(self._strip_timestamp(read_str), include_self=False)

    def _apply_active_pet_cure(
        self,
        pet: PetState,
        skill: SkillState,
        definition: PetSkillDefinition,
    ) -> None:
        """Apply original pet skills 104/105 to their owner and play their effect."""
        maximum = self._current_max_hp() if definition.effect_type == "cure_hp" else self._current_max_mp()
        current = self.character.hp if definition.effect_type == "cure_hp" else self.character.mp
        gain = max(1, round(definition.value(max(1, skill.level))))
        updated = min(maximum, current + gain)
        with self.store.lock:
            if definition.effect_type == "cure_hp":
                self.character.hp = updated
                stat = StatType.HP
            else:
                self.character.mp = updated
                stat = StatType.MP
            self.store.save()
        self._send_visible(
            f"{op(ServerOpcode.PET_ATTACK)}:{self.character.character_id}:{pet.unique_id}:"
            f"0:0:0:0:0:0:10:{skill.skill_id}:{max(1, skill.level)}:"
            f"{self.x}:{self.y}:{self.character.character_id}:-:0"
        )
        self._send_stats({stat: updated})

    def _apply_pet_damage(
        self,
        pet: PetState,
        monster: MonsterState,
        skill: SkillState | None = None,
        definition: PetSkillDefinition | None = None,
    ) -> None:
        """Animate one pet attack, damage the target, and grant pet experience on a kill."""
        monster.target_character_id = self.character.character_id
        skill = skill or self._primary_pet_skill(pet)
        equipment_attack = sum(
            self._equipment_attribute_total(item, op(EquipmentAttribute.ATTACK))
            for item in pet.equipment.values()
        )
        base_damage = 25 + pet.level * 5 + equipment_attack
        definition = definition or GAME_DATA_CATALOG.get_pet_skill_definition(
            skill.skill_id
        )
        damage_percent = (
            max(25, round(100 + definition.value(max(1, skill.level))))
            if definition is not None and definition.effect_type == "attack"
            else 100
        )
        damage = self._monster_damage_amount(
            monster,
            max(1, round(base_damage * damage_percent / 100)),
        )
        damage = self._apply_copy_damage_rules(monster, damage)
        self.send_text(
            f"{op(ServerOpcode.PET_ATTACK)}:{self.character.character_id}:{pet.unique_id}:"
            f"{damage}:0:0:0:0:0:10:{skill.skill_id}:{skill.level}:"
            f"{monster.x}:{monster.y}:-:{monster.object_id}:0"
        )
        self._record_world_boss_damage(monster, damage)
        self._record_xiulian_damage(monster, damage)
        monster.hp -= damage
        self.send_text(f"{op(ServerOpcode.DAMAGE_MONSTER)}:{monster.object_id}:{damage}")
        self.send_text(
            f"{op(ServerOpcode.SHOW_MONSTER_HP)}:{monster.object_id}:"
            f"{round(monster.hp * 100 / monster.max_hp)}"
        )
        if monster.hp == 0:
            self._handle_monster_killed(monster)

    @staticmethod
    def _primary_pet_skill(pet: PetState) -> SkillState:
        """Return the first learned pet skill or the original basic attack fallback."""
        return min(pet.skills.values(), key=lambda value: value.skill_id) if pet.skills else SkillState(101)

    def _grant_pet_experience(self, pet: PetState, amount: int) -> None:
        """Persist pet experience and emit the original level-up/update packets."""
        leveled = False
        pet.experience += max(0, amount)
        while pet.experience >= pet.level * 100 and pet.level < 120:
            pet.experience -= pet.level * 100
            pet.level += 1
            leveled = True
        new_skills = self._auto_learn_pet_skills(pet) if leveled else []
        self.store.save()
        if leveled:
            self.send_text(
                f"{op(ServerOpcode.PET_ACTION)}:{op(PetResponseAction.LEVEL_UP)}:"
                f"{self.character.character_id}:{pet.unique_id}"
            )
            if new_skills:
                self._send_pet_skill_list(pet)
        self.send_text(
            f"{op(ServerOpcode.PET_ACTION)}:{op(PetResponseAction.UPDATE)}:{self._encode_pet_update(pet)}"
        )

    def handle_monster_move(self, read_str: str) -> None:
        """Accept only landing samples for a server-authorized knockback window."""
        fields = self._request_fields(read_str, ClientOpcode.MOVE_LIFE)
        if len(fields) < 6:
            return
        monster = self.monsters.get(self._safe_int(fields[1], -1))
        current = time.monotonic()
        if monster is None or monster.knockback_until <= current:
            return
        reported_x = self._safe_int(fields[4], monster.x)
        reported_y = self._safe_int(fields[5], monster.y)
        if (
            abs(reported_x - monster.knockback_report_x) > 1_200
            or abs(reported_y - monster.knockback_report_y) > 1_200
        ):
            return
        monster.knockback_report_x = self._short_coordinate(reported_x)
        monster.knockback_report_y = self._short_coordinate(reported_y)
        monster.knockback_reported = True
        monster.x = monster.knockback_report_x
        monster.y = monster.knockback_report_y

    def handle_chat(self, read_str: str) -> None:
        """Echo nearby chat or execute the local all-map teleport command."""
        fields = self._request_fields(read_str, ClientOpcode.CHAT)
        message = fields[-1] if fields else ""
        if not message:
            return
        if self._handle_map_chat_command(message):
            return
        payload = (
            f"{op(ServerOpcode.CHATTEXT)}:{self.character.character_id}:"
            f"{self.character.name}:{message}:0:{int(time.time())}"
        )
        self.send_text(payload)
        if self.hub is not None:
            self.hub.broadcast_visible(self, payload)

    def handle_chat_message(self, read_str: str) -> None:
        """Echo the current client's colon-delimited ChatMessage packet."""
        payload = self._strip_timestamp(read_str)
        prefix = f"{op(ClientOpcode.CHAT_MESSAGE)}:"
        if not payload.startswith(prefix):
            return
        fields = payload[len(prefix) :].split(":")
        if len(fields) < 8:
            return
        char_type, positions, message_type, target_char_type, target_id = fields[:5]
        # Text is the only field that may contain colons. The final two request fields
        # are always the encoded item tag and whisper target name.
        message = ":".join(fields[5:-2]).strip()
        tag = fields[-2] or "-"
        target_name = fields[-1]
        if not message:
            return
        if self._handle_map_chat_command(message):
            return
        safe_message = message.replace(":", "：")
        response_message_type = self._safe_int(message_type, 3)
        if response_message_type == 8 and not self._consume_speaker_for_chat():
            return
        if response_message_type in {7, 8}:
            safe_message = self._hokage_charm_chat_prefix() + safe_message
        response_positions = self._safe_int(positions, 0)
        if response_positions == 0:
            response_positions = {
                3: 8,        # general + overhead speech
                4: 16,       # whisper
                5: 32,       # party
                6: 64,       # guild
                7: 128,      # world; the client renders overhead speech separately
                8: 257,      # speaker channel + top white scrolling notice
            }.get(response_message_type, 8)
        elif response_message_type == 8:
            response_positions |= 257
        response_payload = (
            f"{op(ServerOpcode.CHAT_MESSAGE)}:{response_message_type}:"
            f"{response_positions}:{safe_message}:{self.character.name}:"
            f"{self.character.character_id}:{self.character.level}:{tag}:{target_name}:"
            f"{self._safe_int(target_id, 0)}:{self._safe_int(char_type, 0)}:"
            f"{self._safe_int(target_char_type, 0)}"
        )
        self.send_text(response_payload)
        if self.hub is not None:
            target_character_id = self._safe_int(target_id, 0)
            if response_message_type == 4:
                target = self.hub.session_for_character(target_character_id)
                if target is None and target_name:
                    target = self.hub.session_for_name(target_name)
                if target is not None and target is not self:
                    target.send_text(response_payload)
            elif response_message_type in {7, 8}:
                self.hub.broadcast_world(self, response_payload)
            elif response_message_type in {5, 6}:
                self.hub.broadcast_line(self, response_payload)
            else:
                self.hub.broadcast_visible(self, response_payload)
        target_character_id = self._safe_int(target_id, 0)
        if self.hub is None and response_message_type == 4 and (
            target_character_id == self.LOCAL_COMPANION_ID
            or target_name == self.LOCAL_COMPANION_NAME
        ):
            self.send_text(
                f"{op(ServerOpcode.CHAT_MESSAGE)}:4:16:收到：{safe_message}:"
                f"{self.LOCAL_COMPANION_NAME}:{self.LOCAL_COMPANION_ID}:"
                f"{self.character.level}:-:{self.character.name}:"
                f"{self.character.character_id}:0:0"
            )
        elif self.hub is None and response_message_type == 5:
            self.send_text(
                f"{op(ServerOpcode.CHAT_MESSAGE)}:5:32:队伍收到：{safe_message}:"
                f"{self.LOCAL_COMPANION_NAME}:{self.LOCAL_COMPANION_ID}:"
                f"{self.character.level}:-::0:0:0"
            )

    def _consume_speaker_for_chat(self) -> bool:
        """Consume the GameData-authored horn before publishing a speaker message."""
        raw_config = GAME_DATA_CATALOG.raw_etc.get("laba")
        config = (
            GAME_DATA_CATALOG._decode_section(raw_config)
            if raw_config is not None
            else {}
        )
        item_id = self._safe_int(
            config.get("itemid") if isinstance(config, dict) else 0,
            0,
        )
        if item_id <= 0:
            return False
        with self.store.lock:
            consumed, removed = self._consume_bag_item(item_id)
            if consumed is not None:
                self.store.save()
        if consumed is None:
            self._send_character_notice("你背包中的喇叭不足！")
            return False
        if removed:
            self._send_inventory_clear(consumed.slot, InventoryType.BAG)
        else:
            self._send_inventory_update(consumed, from_drop=0)
        return True

    def handle_mob_skill(self, read_str: str) -> None:
        """Confirm a client-owned monster skill so its original effect can finish."""
        fields = self._request_fields(read_str, ClientOpcode.MOB_SKILL)
        if len(fields) < 10:
            return
        monster = self.monsters.get(self._safe_int(fields[0], -1))
        if monster is None or monster.hp <= 0 or self._safe_int(fields[4], 0) <= 0:
            return
        self.send_text(f"{op(ServerOpcode.MOB_SKILL)}:{':'.join(fields[:10])}")

    def handle_map_flag_action(self, read_str: str) -> None:
        """Return the captured fixed flag list and never synthesize player-relative flags."""
        fields = self._request_fields(read_str, ClientOpcode.MAP_FLAG_ACTION)
        if fields and self._safe_int(fields[0], -1) == 0:
            family = self._flag_owner_family()
            flag_list = "@".join(
                self._encode_local_flag_info(map_id, family)
                for map_id in self.MAP_FLAG_LOCATIONS
                if family is not None and GAME_DATA_CATALOG.get_map(map_id) is not None
            )
            self.send_text(f"{op(ServerOpcode.MAP_FLAG_ACTION)}:0:{flag_list or '-'}")

    def _encode_local_flag_info(
        self,
        map_id: int,
        family: dict[str, Any],
    ) -> str:
        """Encode one persistent local flag at an original-server fixed coordinate."""
        x, y, channel = self.MAP_FLAG_LOCATIONS[map_id]
        family_name = str(family.get("name", "-"))
        flag_level = max(1, int(family.get("flagLevel", 1)))
        flag_style = self._family_display_flag_style(family)
        flag_name = str(family.get("flagName", "-"))
        return "&".join(
            str(value)
            for value in (
                map_id,
                x,
                y,
                channel,
                1,
                family_name,
                10_000,
                10_000,
                flag_level,
                flag_style,
                0,
                flag_name,
            )
        )

    def _local_flag_spawn_payload(self) -> str | None:
        """Build the fixed map flag packet for this player's family, when present."""
        if self.character.map_id not in self.MAP_FLAG_LOCATIONS:
            return None
        family = self._flag_owner_family()
        if family is None:
            return None
        return (
            f"{op(ServerOpcode.MAP_FLAG_ACTION)}:1:{self.character.map_id}:"
            f"{self._encode_local_flag_info(self.character.map_id, family)}"
        )

    def _send_local_flag_spawn(self, *, visible: bool = False) -> None:
        """Spawn the fixed map flag locally and optionally replay it to peers."""
        payload = self._local_flag_spawn_payload()
        if payload is None:
            return
        if visible:
            self._send_visible(payload)
        else:
            self.send_text(payload)

    def _handle_map_chat_command(self, message: str) -> bool:
        """Support `@map next`, `@map prev`, IDs, and unique original map names."""
        normalized = message.strip()
        for prefix in ("@兑换", "@cdk", "@CDK"):
            if normalized.startswith(prefix):
                code = normalized[len(prefix):].strip()
                if not code:
                    self._send_system_chat("用法：@兑换 <兑换码>")
                    return True
                return self._redeem_code(code)
        if normalized.lower().startswith("@portal"):
            portal_id = normalized[len("@portal") :].strip()
            if not portal_id or self._safe_int(portal_id, -1) < 0:
                self._send_system_chat("请靠近传送门后直接点击或使用方向键进入。")
                return True
            self._handle_change_map(f"{op(ClientOpcode.CHANGE_MAP)}:2:{portal_id}")
            return True
        prefixes = ("@map", "@地图")
        prefix = next((item for item in prefixes if normalized.lower().startswith(item.lower())), None)
        if prefix is None:
            return False
        query = normalized[len(prefix) :].strip()
        if query.lower() in ("next", "下一张", "下一个"):
            target_map_id = GAME_DATA_CATALOG.adjacent_map(self.character.map_id, 1)
        elif query.lower() in ("prev", "previous", "上一张", "上一个"):
            target_map_id = GAME_DATA_CATALOG.adjacent_map(self.character.map_id, -1)
        else:
            target_map_id = GAME_DATA_CATALOG.find_map(query) if query else None
        if target_map_id is None:
            self._send_system_chat("用法：@map next、@map prev、@map 唯一地图名。")
            return True
        self._warp_to_map(target_map_id)
        return True

    def _redeem_code(self, raw_code: str) -> bool:
        code = raw_code.strip().upper()
        if self.hub is None or not code:
            return False
        with self.hub.lock:
            record = self.hub.redemption_codes.get(code)
            if record is None:
                self._send_system_chat("兑换码不存在或已被删除。")
                return True
            now = int(time.time())
            if record.get("expiresAt") and now > int(record.get("expiresAt", 0)):
                self._send_system_chat("该兑换码已过期。")
                return True
            used_by = [int(value) for value in (record.get("usedBy") or [])]
            if len(used_by) >= max(1, int(record.get("maxUses", 1))):
                self._send_system_chat("该兑换码已被使用完。")
                return True
            if self.character.character_id in used_by:
                self._send_system_chat("你已经使用过该兑换码。")
                return True
            rewards = record.get("rewards") or []
            if not isinstance(rewards, list) or not rewards:
                self._send_system_chat("该兑换码没有配置奖励。")
                return True
            granted: list[str] = []
            try:
                for reward in rewards:
                    item_id = int(reward.get("itemId") or 0)
                    quantity = max(1, int(reward.get("quantity") or 1))
                    definition = GAME_DATA_CATALOG.get_item_definition(item_id)
                    if definition is None:
                        continue
                    item, created = self._add_inventory_item(item_id, quantity)
                    if created:
                        self._send_inventory_add(item, from_drop=0)
                    else:
                        self._send_inventory_update(item, from_drop=0)
                    granted.append(f"【{definition.name}】×{quantity}")
            except InventoryCapacityError:
                self._send_system_chat("背包空间不足，兑换未完成。")
                return True
            if not granted:
                self._send_system_chat("兑换码奖励发放失败（奖励物品无效）。")
                return True
            record["usedBy"] = [*used_by, self.character.character_id]
            self.store.save()
            self.hub.persist_redemption_codes()
        self._send_dynamic_info(f"兑换成功：{'、'.join(granted)}。")
        return True

    def _send_system_chat(self, message: str) -> None:
        """Compatibility entry point for ordinary local gameplay feedback."""
        self._send_character_notice(message)

    def _send_copy_notice(self, message: str) -> None:
        """Show the original centered red copy instruction layer."""
        safe_message = message.translate(SIMPLIFIED_TRANSLATION).replace(":", "：")
        self.send_text(
            f"{op(ServerOpcode.CHAT_MESSAGE)}:1:{self.COPY_NOTICE_POSITION}:"
            f"{safe_message}:系统:0:0:-::0:0:0"
        )

    def _send_authored_copy_map_notice(
        self,
        previous_map_id: int,
        map_id: int,
    ) -> None:
        """Publish GameData's finish-map instruction on a dedicated result map."""
        if self.active_copy_id is None or previous_map_id == map_id:
            return
        config = GAME_DATA_CATALOG.copy_config(self.active_copy_id)
        if not isinstance(config, dict):
            return
        maps = tuple(row for row in config.get("maps", ()) if isinstance(row, dict))
        # A single-map copy marks its combat room as `finish`; that does not make
        # it a settlement map. Only a later authored map receives this notice.
        if len(maps) < 2:
            return
        current = next(
            (
                row
                for row in maps
                if self._safe_int(row.get("mapId"), 0) == map_id
            ),
            None,
        )
        if current is None or not bool(current.get("finish")):
            return
        strings = config.get("raw", {}).get("string", {})
        message = strings.get("finishMapMessage") if isinstance(strings, dict) else ""
        if message:
            self._send_copy_notice(str(message))

    @staticmethod
    def _item_display_name(item_id: int, fallback: str = "所需物品") -> str:
        """Resolve a player-facing item name without exposing its internal template id."""
        definition = GAME_DATA_CATALOG.get_item_definition(int(item_id))
        if definition is None:
            return fallback
        name = str(definition.name or "").strip()
        if not name or name.isdigit():
            return fallback
        if re.fullmatch(
            r"(?i)(?:物品|道具|装备|材料)\s*(?:ID|编号)?\s*[:：#-]?\s*\d+",
            name,
        ):
            return fallback
        return name

    def _send_comprehensive_chat(self, message: str) -> None:
        """Show one whitelisted local announcement in the comprehensive channel."""
        safe_message = message.replace(":", "：")
        self.send_text(
            f"{op(ServerOpcode.CHAT_MESSAGE)}:1:4:{safe_message}:系统:"
            f"0:0:-::0:0:0"
        )

    def _broadcast_system_chat(self, message: str) -> None:
        """Publish one whitelisted comprehensive announcement to every online player."""
        safe_message = message.replace(":", "：")
        payload = (
            f"{op(ServerOpcode.CHAT_MESSAGE)}:1:4:{safe_message}:系统:"
            f"0:0:-::0:0:0"
        )
        self.send_text(payload)
        if self.hub is not None:
            self.hub.broadcast_world(self, payload)

    def _send_scrolled_announcement(self, message: str) -> None:
        """Show the client's native white top marquee without a chat record."""
        safe_message = message.replace(":", "：")
        # ScrolledAnnouncePane renders this field through TextField.htmlText.
        # Keep the wire text ASCII-only so legacy Flash/Ruffle font and string
        # paths cannot replace CJK characters with question marks.
        safe_message = "".join(
            f"&#{ord(character)};" if ord(character) > 0x7F else character
            for character in safe_message
        )
        self.send_text(
            f"{op(ServerOpcode.CHAT_MESSAGE)}:1:1:{safe_message}:SYSTEM:"
            f"0:0:-::0:0:0"
        )

    def _gm_event_display_name(self, event_key: str) -> str:
        """Resolve a persisted GM event key into a player-facing activity name."""
        key = str(event_key).strip()
        if key == "world-boss":
            return "世界 Boss 宇智波斑"
        if key == "muye-gift":
            return "木叶馈赠"
        if key.startswith("monster-event:"):
            group_id = self._safe_int(key.rsplit(":", 1)[-1], 0)
            names: list[str] = []
            for event in GAME_DATA_CATALOG.scheduled_monster_events():
                if self._safe_int(event.get("groupId"), 0) != group_id:
                    continue
                for template_id in event.get("mobs", ()):
                    definition = GAME_DATA_CATALOG.get_monster_definition(
                        self._safe_int(template_id, 0)
                    )
                    if definition.name not in names:
                        names.append(definition.name)
            if names:
                return " / ".join(names)
        if key.startswith("boss-wang:"):
            index = self._safe_int(key.rsplit(":", 1)[-1], -1)
            row = next(
                (
                    row
                    for row in GAME_DATA_CATALOG.wang_boss_entries()
                    if self._safe_int(row.get("index"), -1) == index
                ),
                None,
            )
            if row is not None:
                definition = GAME_DATA_CATALOG.get_monster_definition(
                    self._safe_int(row.get("mobId"), 0)
                )
                return f"Boss {definition.name}"
        return key or "未知事件"

    def _send_active_gm_event_statuses(self) -> None:
        """Tell a newly entered player which GM-forced events are still active."""
        now = int(time.time())
        events = GM_STATE.snapshot().get("events", {})
        if not isinstance(events, dict):
            return
        for event_key, state in events.items():
            if not isinstance(state, dict):
                continue
            remaining = max(0, self._safe_int(state.get("expiresAt"), 0) - now)
            if remaining <= 0:
                continue
            display_minutes = max(1, (remaining + 59) // 60)
            message = (
                f"【GM事件】{self._gm_event_display_name(str(event_key))}"
                f"正在进行，剩余约{display_minutes}分钟。"
            )
            self._send_scrolled_announcement(message)
            self._send_comprehensive_chat(message)

    def _send_current_map_rank(self) -> None:
        """Mirror the original per-channel current-scene ranking notice."""
        if (
            self.active_copy_id is not None
            or self.active_hero_copy_id is not None
            or self.active_pve_level > 0
            or self.copy_instance_id > 0
            or GAME_DATA_CATALOG.is_copy_map(self.character.map_id)
        ):
            return
        if self.hub is None:
            return
        peers = [
            peer
            for peer in self.hub.visible_peers(self)
            if not getattr(peer, "server_simulated", False)
        ]
        if not peers:
            return
        participants = [self, *peers]
        ranked = sorted(
            participants,
            key=lambda session: (
                -session._combat_power_score(),
                session.character.character_id,
            ),
        )
        rank = next(
            (
                index
                for index, session in enumerate(ranked, start=1)
                if session is self
            ),
            1,
        )
        self._send_comprehensive_chat(
            f"您在本线当前场景中的所有角色里排名第{rank}位!"
        )

    def _combat_power_score(self) -> int:
        """Return one stable server-side score for current-map ordering."""
        return (
            self._current_attack() * 5
            + self._current_defence() * 3
            + self._current_critical() * 2
            + self._current_evasion() * 2
            + self._current_max_hp()
            + self._current_max_mp()
            + self.character.level * 100
        )

    def _send_dynamic_info(self, message: str) -> None:
        """Show one native transient status line without adding a chat record."""
        safe_message = message.replace(":", "：")
        self.send_text(
            f"{op(ServerOpcode.CHAT_MESSAGE)}:1:1024:{safe_message}:系统:"
            f"0:0:-::0:0:0"
        )

    def _broadcast_dynamic_info(self, message: str) -> None:
        """Publish the client's built-in green dynamic notice to every player."""
        safe_message = message.replace(":", "：")
        payload = (
            f"{op(ServerOpcode.CHAT_MESSAGE)}:1:1024:{safe_message}:系统:"
            f"0:0:-::0:0:0"
        )
        self.send_text(payload)
        if self.hub is not None:
            self.hub.broadcast_world(self, payload)

    @staticmethod
    def _rare_event_markup(
        message: str,
        highlights: Iterable[str] = (),
        colored_values: Iterable[tuple[str, str]] = (),
        action_link: tuple[str, str] | None = None,
    ) -> str:
        """Render the native top notice with the original semantic colour rules."""
        candidates = {
            str(value).translate(SIMPLIFIED_TRANSLATION).replace(":", "：")
            for value in highlights
            if str(value).strip()
        }
        # Higher-priority authored colours (notably Will quality colours) win
        # over the generic player/value and rare-name rules.
        ranges: list[tuple[int, int, str, int]] = []
        for raw_value, raw_color in colored_values:
            candidate = str(raw_value).translate(SIMPLIFIED_TRANSLATION).replace(":", "：")
            color = str(raw_color or "#ff5498")
            start = 0
            while candidate:
                start = message.find(candidate, start)
                if start < 0:
                    break
                ranges.append((start, start + len(candidate), color, 100))
                start += len(candidate)
        for candidate in candidates:
            start = 0
            while True:
                start = message.find(candidate, start)
                if start < 0:
                    break
                color = "#ff5498" if start > 0 and message[start - 1] == "【" else "#00ff00"
                ranges.append((start, start + len(candidate), color, 70))
                start += len(candidate)
        for match in re.finditer(r"(?<=【)[^】]+(?=】)", message):
            ranges.append((*match.span(), "#ff5498", 60))
        for match in re.finditer(
            r"第?\d+(?:区|服|线|阶|级|层|次|朵|连杀|分钟|秒|个|件|组)|"
            r"\d+(?:%|％)|×\d+|\*\d+",
            message,
        ):
            ranges.append((*match.span(), "#00ff00", 50))

        selected: list[tuple[int, int, str, int]] = []
        for start, end, color, priority in sorted(
            ranges,
            key=lambda value: (-value[3], -(value[1] - value[0]), value[0]),
        ):
            if any(
                start < current_end and end > current_start
                for current_start, current_end, _, _ in selected
            ):
                continue
            selected.append((start, end, color, priority))
        selected.sort(key=lambda value: value[0])

        parts: list[str] = []
        cursor = 0
        for start, end, color, _ in selected:
            parts.append(html.escape(message[cursor:start]))
            parts.append(
                f'<font color="{html.escape(color, quote=True)}">'
                f'{html.escape(message[start:end])}</font>'
            )
            cursor = end
        parts.append(html.escape(message[cursor:]))
        markup = f'<font color="#ffff00">{"".join(parts)}</font>'
        if action_link is not None:
            label, target = action_link
            # The text bridge is colon-delimited.  The numeric entity survives
            # that bridge and Flash decodes it back to event:npcXX in htmlText.
            safe_target = html.escape(str(target), quote=True)
            markup += (
                '<br/><font color="#00ff00">'
                f'<a href="event&#58;{safe_target}"><u>{html.escape(str(label))}</u></a>'
                '</font>'
            )
        return markup

    def _broadcast_rare_event(
        self,
        message: str,
        *,
        highlights: Iterable[str] = (),
        colored_values: Iterable[tuple[str, str]] = (),
        action_link: tuple[str, str] | None = None,
    ) -> None:
        """Stack one native colored rare-event line at the top of every client."""
        highlights = tuple(highlights)
        simplified = message.translate(SIMPLIFIED_TRANSLATION)
        if simplified.startswith("[系统]"):
            simplified = simplified[len("[系统]") :]
        safe_message = simplified.replace(":", "：")
        comprehensive_text = safe_message
        top_message = self._rare_event_markup(
            safe_message,
            highlights,
            colored_values,
            action_link,
        )
        comprehensive_message = self._rare_event_markup(
            comprehensive_text,
            highlights,
            colored_values,
        )
        payload = (
            # [JH] is the original switch from the white marquee to the static
            # NoticeMidWindow, which stacks up to three independently fading lines.
            f"{op(ServerOpcode.CHAT_MESSAGE)}:1:1:[JH]{top_message}:系统:"
            f"0:0:-::0:0:0"
        )
        # [JH] is a PUB_NOTICE-only switch.  The comprehensive chat renderer
        # does not consume it, so construct that payload independently.
        comprehensive_payload = (
            f"{op(ServerOpcode.CHAT_MESSAGE)}:1:4:{comprehensive_message}:系统:"
            f"0:0:-::0:0:0"
        )
        self.send_text(comprehensive_payload)
        self.send_text(payload)
        if self.hub is not None:
            self.hub.broadcast_world(self, comprehensive_payload)
            self.hub.broadcast_world(self, payload)

    @staticmethod
    def _should_announce_reward_probability(probability_ppm: int) -> bool:
        """Return whether one independently rolled reward is rare enough to announce."""
        return 0 < int(probability_ppm) <= RARE_REWARD_ANNOUNCEMENT_MAX_PPM

    def _rare_reward_announcement(
        self,
        source_name: str,
        reward_name: str,
        quantity: int,
        *,
        source_kind: str,
    ) -> tuple[str, tuple[str, ...], tuple[tuple[str, str], ...]]:
        """Build one screenshot-matched rare-reward line without consuming drop RNG."""
        player_label = f"[{self.line_id}区]{self.character.name}"
        quantity_text = f"{max(1, int(quantity))}个"
        if source_kind == "gift":
            templates = (
                "{player}打开‘{source}’意外获得了{quantity}{reward}，"
                "运气真是太好了！简直是人品大爆发啊！",
                "{player}在开启‘{source}’的时候竟然获得了{quantity}{reward}，"
                "真是太走运了！",
                "{player}开启‘{source}’，居然得到了{quantity}{reward}，"
                "这运气真让人羡慕！",
            )
        else:
            templates = (
                "恭喜{player}击败‘{source}’后意外获得了{quantity}{reward}，"
                "运气真是太好了！",
                "{player}战胜‘{source}’时竟然获得了{quantity}{reward}，"
                "简直是人品大爆发啊！",
                "{player}击败‘{source}’，居然得到了{quantity}{reward}，"
                "真是鸿运当头！",
            )
        variant_key = (
            f"{self.character.character_id}:{source_kind}:{source_name}:"
            f"{reward_name}:{quantity_text}"
        ).encode("utf-8", errors="replace")
        template = templates[zlib.crc32(variant_key) % len(templates)]
        message = template.format(
            player=player_label,
            source=source_name,
            quantity=quantity_text,
            reward=reward_name,
        )
        return (
            message,
            (player_label, quantity_text),
            ((source_name, "#ff5498"), (reward_name, "#ff5498")),
        )

    def _broadcast_rare_reward(
        self,
        source_name: str,
        reward_name: str,
        quantity: int,
        *,
        source_kind: str,
    ) -> None:
        message, highlights, colored_values = self._rare_reward_announcement(
            source_name,
            reward_name,
            quantity,
            source_kind=source_kind,
        )
        self._broadcast_rare_event(
            message,
            highlights=highlights,
            colored_values=colored_values,
        )

    def _send_character_notice(self, message: str) -> None:
        """Show one native yellow floating notice without adding a chat record."""
        safe_message = message.replace(":", "：")
        self.send_text(
            f"{op(ServerOpcode.CHAT_MESSAGE)}:1:512:{safe_message}:系统:"
            f"0:0:-::0:0:0"
        )

    def _settle_announced_monster_attack(
        self,
        read_str: str,
        skill_id: int,
    ) -> bool:
        """Settle validated PVE casts at announce time, before the visual impact."""
        if not self.PVE_ANNOUNCE_SETTLE_ENABLED:
            return False
        before = sum(
            1
            for claims in self.pending_monster_hits.values()
            for claim in claims
            if claim.skill_id == int(skill_id)
        )
        if before <= 0:
            return False
        if self.hub is not None:
            with self.hub.lock:
                self._apply_attack(read_str)
        else:
            self._apply_attack(read_str)
        after = sum(
            1
            for claims in self.pending_monster_hits.values()
            for claim in claims
            if claim.skill_id == int(skill_id)
        )
        if after >= before:
            return False
        self._register_server_settled_pve_impact(skill_id)
        return True

    def _register_server_settled_pve_impact(self, skill_id: int) -> None:
        now = time.monotonic()
        live = [
            expires_at
            for expires_at in self.server_settled_pve_impacts.get(int(skill_id), ())
            if expires_at > now
        ]
        live.append(now + self.PVE_LATE_IMPACT_SUPPRESS_SECONDS)
        self.server_settled_pve_impacts[int(skill_id)] = live[-16:]

    def _consume_server_settled_pve_impact(self, skill_id: int) -> bool:
        now = time.monotonic()
        live = [
            expires_at
            for expires_at in self.server_settled_pve_impacts.get(int(skill_id), ())
            if expires_at > now
        ]
        if not live:
            self.server_settled_pve_impacts.pop(int(skill_id), None)
            return False
        live.pop(0)
        if live:
            self.server_settled_pve_impacts[int(skill_id)] = live
        else:
            self.server_settled_pve_impacts.pop(int(skill_id), None)
        return True

    def handle_attack(self, read_str: str) -> None:
        """Process one impact phase and release any unacknowledged replay guard."""
        if self._is_edo_controlled():
            return
        is_pet_attack = self._is_pet_mob_attack(read_str)
        skill_id = self._attack_skill_id(read_str)
        if (
            not is_pet_attack
            and not read_str.startswith(f"{op(ClientOpcode.PLAYER_ATTACK)}:")
            and self._consume_server_settled_pve_impact(skill_id)
        ):
            return
        if (
            not is_pet_attack
            and self.announced_skill_replay_acks.get(skill_id, 0.0)
            <= time.monotonic()
        ):
            # Some Nya skills arrive only as one of the four AttackInfo packet
            # families. A preceding PLAYER_ATTACK already received its own ack;
            # an impact-only cast still needs one or the client locks all skills
            # after fired_not_replay_count exceeds three.
            self.send_text(f"{op(ServerOpcode.SKILL_BACK)}:{skill_id}")
        if (
            not is_pet_attack
            and skill_id > 0
            and self._is_mp_sealed()
        ):
            self.send_text(f"{op(ServerOpcode.SKILL_BACK)}:{skill_id}")
            return
        if not is_pet_attack and self._has_active_skill_buff(CombatBuffType.STUN):
            self.send_text(f"{op(ServerOpcode.SKILL_BACK)}:{skill_id}")
            return
        phase = "pet-impact" if is_pet_attack else "impact"
        if (
            skill_id != FLYING_RAIJIN_MARK_SKILL_ID
            and not self._accept_combat_packet(phase, read_str)
        ):
            return
        if self.hub is not None:
            with self.hub.lock:
                if is_pet_attack:
                    self._apply_pet_mob_attack(read_str)
                else:
                    self._apply_attack(read_str)
        else:
            if is_pet_attack:
                self._apply_pet_mob_attack(read_str)
            else:
                self._apply_attack(read_str)

    def _reset_client_skill_replay_guard(self) -> None:
        """Clear stale native cast counters left behind by an in-place reconnect."""
        # SkillHandler blocks new casts once fired_not_replay_count exceeds 3.
        # A channel reconnect can preserve that ActionScript singleton, so a
        # fresh server session must drain every possible blocked count.
        for _ in range(4):
            self.send_text(f"{op(ServerOpcode.SKILL_BACK)}:0")

    def _acknowledge_announced_skill(self, skill_id: int) -> None:
        """Release one PLAYER_ATTACK guard and mark its later impact as acknowledged."""
        self.send_text(f"{op(ServerOpcode.SKILL_BACK)}:{skill_id}")
        self.announced_skill_replay_acks[skill_id] = (
            time.monotonic() + self.COMBAT_CAST_WINDOW_SECONDS
        )

    def _is_pet_mob_attack(self, read_str: str) -> bool:
        """Return whether AttackInfo identifies a pet rather than the player."""
        if not read_str.startswith(f"{op(ClientOpcode.MOB_ATTACK)}:"):
            return False
        fields = self._request_fields(read_str, ClientOpcode.MOB_ATTACK)
        return bool(fields) and self._safe_int(fields[0], 1) == 0

    def _apply_pet_mob_attack(self, read_str: str) -> None:
        """Validate and settle the pet-origin AttackInfo emitted after its hit effect."""
        fields = self._request_fields(read_str, ClientOpcode.MOB_ATTACK)
        if len(fields) < 13:
            return
        character_id = self._safe_int(fields[1], 0)
        pet_uid = self._safe_int(fields[2], 0)
        skill_id = self._safe_int(fields[9], 0)
        pet = self.store.state.pets.get(pet_uid)
        skill = pet.skills.get(skill_id) if pet is not None else None
        definition = GAME_DATA_CATALOG.get_pet_skill_definition(skill_id)
        if (
            character_id != self.character.character_id
            or pet is None
            or pet.position != op(PetPosition.ATTACKING)
            or skill is None
            or definition is None
            or definition.for_player
        ):
            print(
                f"[combat] rejected pet skill account={self.account_name or '-'} "
                f"character={self.character.character_id} pet={pet_uid} "
                f"skill={skill_id} learned={skill is not None} "
                f"defined={definition is not None}",
                flush=True,
            )
            return

        target_ids = fields[12].split("@") if fields[12] != "-" else []
        targets = [
            self.monsters[target_id]
            for target_id in dict.fromkeys(
                self._safe_int(raw_target_id, -1) for raw_target_id in target_ids
            )
            if target_id in self.monsters and self.monsters[target_id].hp > 0
        ]
        if not targets:
            return
        self._mark_combat()
        if definition.effect_type in PET_MONSTER_DEBUFF_EFFECTS:
            for target in targets:
                self._apply_pet_monster_status(target, skill, definition)
            return

        target_limit = len(targets) if definition.target_type == 2 else 1
        equipment_attack = sum(
            self._equipment_attribute_total(item, op(EquipmentAttribute.ATTACK))
            for item in pet.equipment.values()
        )
        base_damage = 25 + pet.level * 5 + equipment_attack
        damage_percent = (
            max(25, round(100 + definition.value(max(1, skill.level))))
            if definition.effect_type == "attack"
            else 100
        )
        hit_results: list[PlayerHitResult] = []
        for monster in targets[:target_limit]:
            monster.target_character_id = self.character.character_id
            damage = self._monster_damage_amount(
                monster,
                max(1, round(base_damage * damage_percent / 100)),
            )
            damage = self._apply_copy_damage_rules(monster, damage)
            self._record_world_boss_damage(monster, damage)
            self._record_xiulian_damage(monster, damage)
            monster.hp -= damage
            hit_results.append(PlayerHitResult(monster, damage, False))

        self._send_mob_attack_result(read_str, hit_results)
        for result in hit_results:
            monster = result.monster
            self._send_visible(
                f"{op(ServerOpcode.SHOW_MONSTER_HP)}:{monster.object_id}:"
                f"{round(monster.hp * 100 / monster.max_hp)}"
            )
            if monster.hp == 0:
                self._handle_monster_killed(monster)

    def handle_couple_attack(self, read_str: str) -> None:
        """Validate native couple skills and put protective Buffs on the spouse."""
        fields = self._request_fields(read_str, ClientOpcode.COUPLE_ATTACK)
        if len(fields) < 11 or self.hub is None:
            return
        caster_id = self._safe_int(fields[0], 0)
        target_id = self._safe_int(fields[1], 0)
        skill_id = self._safe_int(fields[5], 0)
        if caster_id != self.character.character_id:
            return
        skill_state = self.store.state.skills.get(skill_id)
        definition = GAME_DATA_CATALOG.get_skill_definition(skill_id)
        target = self.hub.session_for_character(target_id)
        account = self.accounts.account_by_id(self.account_id) if self.account_id else None
        spouse_account_id = self._safe_int(
            account.get("spouseAccountId"), 0
        ) if isinstance(account, dict) else 0
        if (
            skill_state is None
            or definition is None
            or definition.effect_type != "couple_protect"
            or target is None
            or target.account_id != spouse_account_id
            or target.character.map_id != self.character.map_id
            or target.line_id != self.line_id
            or target.copy_instance_id != self.copy_instance_id
        ):
            self._send_character_notice("羁绊不在当前地图，无法使用不离不弃。")
            return
        if not self._consume_skill_cast(skill_state, definition):
            return
        skill_level = self._effective_skill_level(skill_state)
        duration_ms = definition.effect_duration_ms(skill_level)
        target._apply_timed_skill_buff(
            buff_type=CombatBuffType.COUPLE_PROTECT,
            skill_id=skill_id,
            skill_level=skill_level,
            value_percent=definition.effect_value(skill_level),
            duration_ms=duration_ms,
        )
        self._send_visible(self._strip_timestamp(read_str), include_self=False)

    def _remember_monster_attack_claims(self, fields: list[str]) -> None:
        """Snapshot one server-validated monster target group for delayed impact."""
        if len(fields) <= 13:
            return
        now = time.monotonic()
        skill_id = self._safe_int(fields[8], 0) if len(fields) > 8 else 0
        claimed_x = self._safe_int(fields[10], self.x) if len(fields) > 10 else self.x
        claimed_y = self._safe_int(fields[11], self.y) if len(fields) > 11 else self.y
        caster_x, caster_y = self._validated_cast_origin(
            claimed_x,
            claimed_y,
            now,
        )
        definition = GAME_DATA_CATALOG.get_skill_definition(skill_id)
        skill_state = self.store.state.skills.get(skill_id)
        multi_target = bool(definition is not None and definition.multi_target)
        maximum_distance = (
            definition.effect_range(self._effective_skill_level(skill_state))
            if definition is not None and skill_state is not None
            else self.PLAYER_ATTACK_DISTANCE
        )
        # AOE targets are collected by the server from one exact cast-time
        # snapshot. Single-target attacks retain the bounded rewind margin.
        if not multi_target:
            maximum_distance += self.PLAYER_ATTACK_SYNC_TOLERANCE
        expires_at = now + self.COMBAT_CAST_WINDOW_SECONDS
        cast_id = self.next_monster_cast_id
        self.next_monster_cast_id += 1
        selected_ids = {
            self._safe_int(raw_object_id, -1)
            for raw_object_id in fields[13].split("@")
            if raw_object_id and raw_object_id != "-"
        }
        candidates = (
            self.monsters.values()
            if multi_target
            else (
                self.monsters[object_id]
                for object_id in selected_ids
                if object_id in self.monsters
            )
        )
        for monster in candidates:
            if monster is None or monster.hp <= 0 or monster.respawn_at:
                continue
            target_x, target_y = self._monster_render_position(monster, now)
            if (
                (target_x - caster_x) ** 2 + (target_y - caster_y) ** 2
                > maximum_distance**2
            ):
                continue
            object_id = monster.object_id
            claims = [
                claim
                for claim in self.pending_monster_hits.get(object_id, ())
                if claim.expires_at > now
            ]
            claims.append(
                PendingMonsterHitClaim(
                    skill_id=skill_id,
                    created_at=now,
                    expires_at=expires_at,
                    caster_x=caster_x,
                    caster_y=caster_y,
                    target_x=target_x,
                    target_y=target_y,
                    cast_id=cast_id,
                )
            )
            self.pending_monster_hits[object_id] = claims[-4:]

    def _konoha_combat_event_active(self) -> bool:
        """Allow village combat only while an authored event or flag match is live."""
        if self.war_3v3_match_id > 0:
            return True
        if self.world_state is None:
            return False
        return any(
            bool(object_ids)
            and (
                event_key == "primary-world-boss"
                or event_key.startswith("boss-wang:")
                or event_key.startswith("monster-event:")
            )
            for event_key, object_ids in self.world_state.scheduled_object_ids.items()
        )

    def _skill_location_denial_reason(self, skill_id: int) -> str:
        """Return the village-only denial without consuming resources or cooldown."""
        if (
            self.character.map_id != op(MapId.KONOHA_VILLAGE)
            or skill_id not in KONOHA_LOCATION_RESTRICTED_SKILL_IDS
        ):
            return ""
        if skill_id in KONOHA_ALWAYS_FORBIDDEN_SKILL_IDS:
            return "外道魔像和地爆天星在木叶村无法释放。"
        if self._konoha_combat_event_active():
            return ""
        return (
            "木叶村非战斗区域，当前仅Boss事件、入侵事件或夺旗战期间"
            "可释放该忍术。"
        )

    def _reject_skill_for_current_location(
        self,
        skill_id: int,
        *,
        acknowledge: bool = True,
    ) -> bool:
        """Cancel one disallowed cast and restore the native client's local state."""
        reason = self._skill_location_denial_reason(skill_id)
        if not reason:
            return False
        if (
            not acknowledge
            and self.announced_skill_replay_acks.get(skill_id, 0.0)
            > time.monotonic()
        ):
            # The rejected PLAYER_ATTACK can still be followed by its client-owned
            # impact packet. Suppress that late phase without repeating the notice.
            return True
        if acknowledge:
            self._acknowledge_announced_skill(skill_id)
        remaining = max(
            0,
            self.store.state.skill_cooldowns.get(skill_id, 0)
            - int(time.time() * 1_000),
        )
        self.send_text(f"{op(ServerOpcode.COOLDOWN)}:{skill_id}:{remaining}")
        self._send_stats(
            {
                StatType.MP: self.character.mp,
                StatType.ZQ: self.character.zq,
            }
        )
        self._send_character_notice(reason)
        return True

    def handle_player_attack_announce(self, read_str: str) -> None:
        """Relay a validated PVP animation and authorize each selected target's damage reply."""
        if self._is_edo_controlled():
            return
        fields = self._request_fields(read_str, ClientOpcode.PLAYER_ATTACK)
        if len(fields) >= 13:
            claimed_attacker = self._safe_int(
                fields[0],
                self.character.character_id,
            )
            if claimed_attacker != self.character.character_id:
                return
            # PlayerAttackInfo stores skillId before skillLevel. Reading index 9
            # treats the level as an ID and prevents native self-buffs from casting.
            skill_id = self._safe_int(fields[8], 0)
            skill_definition = GAME_DATA_CATALOG.get_skill_definition(skill_id)
            if self._reject_skill_for_current_location(skill_id):
                return
            if skill_id > 0 and self._is_mp_sealed():
                self._acknowledge_announced_skill(skill_id)
                return
            if self._has_active_skill_buff(CombatBuffType.STUN):
                self._acknowledge_announced_skill(skill_id)
                return
            if (
                skill_id != FLYING_RAIJIN_MARK_SKILL_ID
                and not self._accept_combat_packet("announce", read_str)
            ):
                self._acknowledge_announced_skill(skill_id)
                return
            now = time.monotonic()
            skill_state = self.store.state.skills.get(skill_id)
            skill_level = (
                self._effective_skill_level(skill_state)
                if skill_state is not None and skill_definition is not None
                else max(1, self._safe_int(fields[9], 1))
            )
            claimed_x = self._safe_int(fields[10], self.x)
            claimed_y = self._safe_int(fields[11], self.y)
            cast_x, cast_y = self._validated_cast_origin(
                claimed_x,
                claimed_y,
                now,
            )
            maximum_distance = (
                skill_definition.effect_range(skill_level)
                if isinstance(skill_definition, SkillDefinition)
                else self.PLAYER_ATTACK_DISTANCE
            ) + self.PLAYER_ATTACK_SYNC_TOLERANCE
            selected_ids = {
                self._safe_int(value, 0)
                for value in fields[12].split("@")
                if value and value != "-"
            }
            hostile_player_ids: list[int] = []
            if self.hub is not None:
                for character_id in selected_ids:
                    candidate = self.hub.session_for_character(character_id)
                    if candidate is not None and self._can_attack_player(candidate):
                        hostile_player_ids.append(character_id)
            selected_monster_ids: list[int] = []
            if len(fields) > 13:
                selected_monster_ids = [
                    self._safe_int(value, 0)
                    for value in fields[13].split("@")
                    if value and value != "-"
                ]
            # Shadow-clone AI follows the caster's current combat target. A
            # player target is remembered only while it is genuinely hostile;
            # attacking a monster replaces any stale player lock.
            if hostile_player_ids:
                self.last_combat_target_character_id = hostile_player_ids[0]
                self.last_combat_target_monster_id = 0
            elif selected_monster_ids:
                self.last_combat_target_character_id = 0
                self.last_combat_target_monster_id = selected_monster_ids[0]
            self._remember_monster_attack_claims(fields)
            if skill_id == 4_009:
                selected_players = {
                    self._safe_int(value, 0)
                    for value in fields[12].split("@")
                    if value and value != "-"
                }
                selected_monsters = {
                    self._safe_int(value, -1)
                    for value in fields[13].split("@")
                    if value and value != "-"
                } if len(fields) > 13 else set()
                has_monster_target = False
                for object_id in selected_monsters:
                    monster = self.monsters.get(object_id)
                    if monster is None or monster.hp <= 0:
                        continue
                    monster_x, monster_y = self._monster_render_position(monster)
                    if (
                        (monster_x - cast_x) ** 2 + (monster_y - cast_y) ** 2
                        <= maximum_distance**2
                    ):
                        has_monster_target = True
                        break
                has_player_target = False
                if self.hub is not None:
                    has_player_target = any(
                        target is not None
                        and self._can_attack_player(target)
                        and self._pvp_target_position_at_cast(
                            target,
                            cast_x,
                            cast_y,
                            maximum_distance,
                            now,
                        )
                        is not None
                        for target_id in selected_players
                        if (target := self.hub.session_for_character(target_id)) is not None
                    )
                if not has_monster_target and not has_player_target:
                    # Release the native replay guard without replaying the cast.
                    # Shenluo Tianzheng is an attack, not a free-standing map effect.
                    self._acknowledge_announced_skill(skill_id)
                    return
            if (
                skill_definition is not None
                and (
                    (
                        skill_definition.target_type in {2, 3}
                        and skill_definition.effect_type in COMBAT_BUFF_TYPE_BY_EFFECT
                    )
                    or skill_definition.effect_type in NON_DAMAGE_SKILL_EFFECTS
                    or (
                        skill_id in DIRECT_CAST_SKILL_IDS
                        and not (
                            skill_id in PVP_DIRECT_DAMAGE_SKILL_IDS
                            and selected_ids
                        )
                    )
                )
            ):
                self._acknowledge_announced_skill(skill_id)
                self.handle_attack(read_str)
                # The client now owns the authored 4010/4011 frame resources;
                # relay the cast to visible peers, but never send the unsafe
                # pull/knock-up semantic packets that used to freeze BeatBackEffect.
                self._send_visible(
                    self._strip_timestamp(read_str),
                    include_self=False,
                )
                return
            # The native client increments fired_not_replay_count when it sends
            # PLAYER_ATTACK.  Waiting for MOB_ATTACK to acknowledge the cast can
            # deadlock skills that miss, have no target, or never emit an impact
            # packet.  Release the guard as soon as the validated cast arrives.
            self._acknowledge_announced_skill(skill_id)
            settled_monster_attack = (
                self._settle_announced_monster_attack(read_str, skill_id)
                if selected_monster_ids
                else False
            )
            accepted_player_attack = settled_monster_attack
            if self.hub is not None:
                expires_at = now + self.COMBAT_CAST_WINDOW_SECONDS
                authorized_targets: list[
                    tuple[FakeFlashSession, int, int]
                ] = []
                authorized_clones: list[
                    tuple[FakeFlashSession, ShadowCloneState]
                ] = []
                denial_reason = ""
                for target_id in selected_ids:
                    target = self.hub.session_for_character(target_id)
                    if target is None:
                        resolved_clone = self.hub.visible_shadow_clone(
                            self,
                            target_id,
                        )
                        if resolved_clone is None:
                            continue
                        owner, clone = resolved_clone
                        if not self._can_attack_player(owner):
                            denial_reason = (
                                denial_reason
                                or self._ordinary_pvp_denial_reason(owner)
                            )
                            continue
                        if (
                            (clone.x - cast_x) ** 2
                            + (clone.y - cast_y) ** 2
                            > maximum_distance**2
                        ):
                            continue
                        authorized_clones.append((owner, clone))
                        continue
                    if not self._can_attack_player(target):
                        denial_reason = denial_reason or self._ordinary_pvp_denial_reason(
                            target
                        )
                        continue
                    target_position = self._pvp_target_position_at_cast(
                        target,
                        cast_x,
                        cast_y,
                        maximum_distance,
                        now,
                    )
                    if target_position is None:
                        continue
                    target_x, target_y = target_position
                    authorized_targets.append((target, target_x, target_y))
                if (
                    (authorized_targets or authorized_clones)
                    and skill_id > 0
                    and (
                        skill_state is None
                        or skill_definition is None
                        or not self._consume_skill_cast(
                            skill_state,
                            skill_definition,
                        )
                    )
                ):
                    authorized_targets = []
                    authorized_clones = []
                if (
                    (authorized_targets or authorized_clones)
                    and skill_id > 0
                    and (
                        (
                            len(fields) > 13
                            and fields[13] not in {"", "-"}
                        )
                        or skill_id in PVP_DIRECT_DAMAGE_SKILL_IDS
                    )
                ):
                    casts = [
                        value
                        for value in self.preconsumed_skill_casts.get(skill_id, ())
                        if value > now
                    ]
                    casts.append(expires_at)
                    self.preconsumed_skill_casts[skill_id] = casts[-4:]
                for target, target_x, target_y in authorized_targets:
                    with target.combat_lock:
                        pending = [
                            value
                            for value in target.pending_pvp_hits.get(
                                self.character.character_id,
                                (),
                            )
                            if value.expires_at > now
                        ]
                        pending.append(
                            PendingPvpHit(
                                skill_id=skill_id,
                                skill_level=skill_level,
                                created_at=now,
                                expires_at=expires_at,
                                server_settle_at=now + (
                                    self.PVP_CLIENT_HIT_SETTLE_SECONDS
                                    if (
                                        isinstance(skill_definition, SkillDefinition)
                                        and skill_definition.client_hit_trigger
                                    )
                                    else self.PVP_SERVER_SETTLE_SECONDS
                                ),
                                attacker_x=cast_x,
                                attacker_y=cast_y,
                                target_x=target_x,
                                target_y=target_y,
                                map_id=self.character.map_id,
                                line_id=self.line_id,
                                copy_instance_id=self.copy_instance_id,
                            )
                        )
                        target.pending_pvp_hits[
                            self.character.character_id
                        ] = pending[-8:]
                for owner, clone in authorized_clones:
                    self._apply_player_damage_to_shadow_clone(
                        owner,
                        clone,
                        skill_definition,
                        skill_level,
                    )
                authorized = bool(authorized_targets or authorized_clones)
                accepted_player_attack = accepted_player_attack or authorized
                if authorized and skill_id in PVP_DIRECT_DAMAGE_SKILL_IDS:
                    self.handle_attack(read_str)
                if denial_reason:
                    self._send_character_notice(denial_reason)
                if accepted_player_attack and (
                    skill_id <= 0
                    or (
                        skill_definition is not None
                        and skill_id in self.store.state.skills
                    )
                ):
                    # Reveal before relaying the attack animation so observers can
                    # actually render the character's first offensive action.
                    self._cancel_dark_sight_for_attack()
                # The original client renders its own cast before sending
                # PLAYER_ATTACK. Official captures never echo opcode 1328 back
                # to that same character, including fireLocal=0 skills. Only
                # peers should receive the animation packet; self-replay makes
                # one key press execute the visible cast twice.
                if (authorized or not selected_ids) and skill_id != 4_010:
                    self._send_visible(
                        self._strip_timestamp(read_str),
                        include_self=False,
                    )
                elif any(
                    self._safe_int(value, -1) in self.monsters
                    for value in (fields[13].split("@") if len(fields) > 13 else ())
                ):
                    self._send_visible(
                        self._strip_timestamp(read_str),
                        include_self=False,
                    )
            if accepted_player_attack and (
                skill_id <= 0
                or (
                    skill_definition is not None
                    and skill_id in self.store.state.skills
                )
            ):
                self._cancel_dark_sight_for_attack()
        self._apply_an_qi_damage(read_str)

    def _apply_shinra_player_knockback(
        self,
        attacker: FakeFlashSession,
        skill_level: int,
        source_x: int | None = None,
        *,
        normal_knockback: bool = False,
        distance_pixels: int | None = None,
    ) -> int:
        """Commit a player landing so later movement sync cannot pull it back."""
        attack_x = attacker.x if source_x is None else source_x
        distance = abs(self.x - attack_x)
        if normal_knockback:
            velocity_x, velocity_y = 160, 450
        elif distance < 50:
            velocity_x, velocity_y = 200, 1_200
        elif distance < 100:
            velocity_x, velocity_y = 600, 1_000
        else:
            velocity_x, velocity_y = 1_000, 800
        growth_scale = (
            1.0
            if normal_knockback
            else min(160.0, 80.0 + max(1, skill_level) * 0.62) / 120.0
        )
        velocity_x = round(velocity_x * growth_scale)
        velocity_y = round(velocity_y * growth_scale)
        flight_seconds = (
            0.45
            if distance_pixels is not None
            else (
                0.75
                if normal_knockback
                else max(0.65, min(1.60, 2.0 * velocity_y / 2_000.0))
            )
        )
        direction = 1 if self.x >= attack_x else -1
        origin = (self.x, self.y)
        travel_distance = (
            max(0, distance_pixels)
            if distance_pixels is not None
            else round(velocity_x * flight_seconds)
        )
        destination_x = self.x + direction * travel_distance
        floor = (
            self.current_map.footholds.get(self.character.foothold)
            if self.current_map is not None
            else None
        )
        if floor is not None:
            destination_x = max(floor.left, min(floor.right, destination_x))
            destination_y = round(floor.y_at(destination_x))
        else:
            destination_y = self.y
        with self.store.lock:
            self.x = self._short_coordinate(destination_x)
            self.y = self._short_coordinate(destination_y)
            self.character.x = self.x
            self.character.y = self.y
            # Knockback changes the authoritative world position, so persist it
            # immediately; ordinary combat resource changes remain coalesced.
            self.store.save()
        now = time.monotonic()
        self.player_knockback_origin = origin
        self.player_knockback_guard_until = (
            now + self.PLAYER_KNOCKBACK_INPUT_GUARD_SECONDS
        )
        self._record_position_sample(now)
        return direction

    def handle_player_damage(self, read_str: str) -> None:
        """Apply one client-confirmed PVP impact using server-owned combat stats."""
        fields = self._request_fields(read_str, ClientOpcode.PLAYER_DAMAGE)
        if len(fields) < 7:
            return
        attacker_id = self._safe_int(fields[0], -1)
        skill_id = self._safe_int(fields[3], -1)
        skill_level = max(0, self._safe_int(fields[4], 0))
        if attacker_id <= 0 or skill_id < 0:
            return
        skill_trigger = False
        direction = max(-1, min(1, self._safe_int(fields[6], 0)))
        if self.hub is None:
            self.send_text(
                f"{op(ServerOpcode.PLAYER_DAMAGE_PLAYER)}:{self.character.character_id}:"
                f"{attacker_id}:0:0:{skill_id}:{skill_level}:"
                f"{'true' if skill_trigger else 'false'}:{direction}"
            )
            return
        attacker = self.hub.session_for_character(attacker_id)
        now = time.monotonic()
        with self.combat_lock:
            pending_hits = [
                pending
                for pending in self.pending_pvp_hits.get(attacker_id, ())
                if pending.expires_at > now
            ]
            pending_hit = next(
                (
                    pending
                    for pending in pending_hits
                    if pending.skill_id == skill_id
                ),
                None,
            )
            if pending_hit is not None:
                pending_hits.remove(pending_hit)
            if pending_hits:
                self.pending_pvp_hits[attacker_id] = pending_hits
            else:
                self.pending_pvp_hits.pop(attacker_id, None)
        if (
            attacker is None
            or pending_hit is None
            or pending_hit.map_id != self.character.map_id
            or pending_hit.line_id != self.line_id
            or pending_hit.copy_instance_id != self.copy_instance_id
            or pending_hit.map_id != attacker.character.map_id
            or pending_hit.line_id != attacker.line_id
            or pending_hit.copy_instance_id != attacker.copy_instance_id
            or not attacker._can_attack_player(self)
            or self._is_dead()
        ):
            return
        skill_state = attacker.store.state.skills.get(skill_id)
        skill_definition = GAME_DATA_CATALOG.get_skill_definition(skill_id)
        authoritative_skill_level = (
            attacker._effective_skill_level(skill_state)
            if skill_state is not None and skill_definition is not None
            else max(1, pending_hit.skill_level)
        )
        critical = attacker._roll_combat_rate(attacker._current_critical())
        ignored_defence = min(
            100,
            max(0, attacker._current_ignore_defence()),
        )
        effective_defence = round(
            self._current_defence() * (100 - ignored_defence) / 100.0
        )
        raw_damage = round(
            attacker._current_attack()
            * attacker.MONSTER_DAMAGE_REDUCTION_BASE
            / (
                attacker.MONSTER_DAMAGE_REDUCTION_BASE
                + max(0, effective_defence)
            )
        )
        if skill_definition is not None:
            raw_damage = round(
                raw_damage
                * skill_definition.damage_percent(authoritative_skill_level)
                / 100
            )
        if critical:
            raw_damage *= attacker.CRITICAL_DAMAGE_MULTIPLIER
            critical_reduction = min(
                100,
                max(0, self._passive_skill_effect_value("damage_reduce_for_bsk")),
            )
            raw_damage = round(raw_damage * (100 - critical_reduction) / 100)
        damage_reduction = min(100, max(0, self._current_damage_reduce()))
        raw_damage = round(raw_damage * (100 - damage_reduction) / 100.0)
        yata_reduction = self._yata_mirror_resistance_percent(skill_definition)
        raw_damage = round(raw_damage * (100 - yata_reduction) / 100.0)
        damage = (
            0
            if self._is_damage_invincible()
            else self._cap_damage_with_death_protection(
                min(max(1, raw_damage), self.character.hp)
            )
        )
        with self.store.lock:
            self.character.hp -= damage
        self._schedule_combat_save(now)
        if (
            damage > 0
            and skill_definition is not None
            and skill_definition.skill_id == 4_008
        ):
            self._apply_timed_skill_buff(
                buff_type=CombatBuffType.SEAL,
                skill_id=4_008,
                skill_level=authoritative_skill_level,
                value_percent=0,
                duration_ms=SHIKI_FUJIN_MARK_DURATION_MS,
                effect_type="shiki_fujin_mark",
                source_character_id=attacker.character.character_id,
            )
            attacker._apply_shiki_fujin_recoil(damage)
        reflected_damage = self._apply_pvp_damage_reflect(attacker, damage)
        triggered_knockback = attacker._triggered_knockback_passive(skill_definition)
        if damage > 0 and triggered_knockback is not None:
            passive_definition, passive_level = triggered_knockback
            skill_trigger = attacker._skill_status_triggered(
                passive_definition,
                passive_level,
                player_target=self,
            )
        if (
            skill_definition is not None
            and skill_definition.effect_type in COMBAT_DEBUFF_TYPE_BY_EFFECT
        ):
            skill_trigger = self._apply_player_skill_status(
                skill_definition,
                authoritative_skill_level,
                source_character_id=attacker.character.character_id,
            )
        elif (
            damage > 0
            and skill_definition is not None
            and (
                skill_definition.effect_type == "knock_back"
                or skill_definition.skill_id == THUNDER_FIREBALL_SKILL_ID
            )
        ):
            skill_trigger = (
                True
                if skill_definition.skill_id == THUNDER_FIREBALL_SKILL_ID
                else self._skill_status_triggered(
                    skill_definition,
                    authoritative_skill_level,
                    player_target=self,
                )
            )
        if (
            damage > 0
            and skill_definition is not None
            and skill_definition.effect_type == "suck_hp"
            and self._skill_status_triggered(
                skill_definition,
                authoritative_skill_level,
                player_target=self,
            )
        ):
            skill_trigger = True
            recovered = round(
                damage
                * max(0.0, skill_definition.effect_value(authoritative_skill_level))
                / 100.0
            )
            if recovered > 0:
                with attacker.store.lock:
                    attacker.character.hp = min(
                        attacker._current_max_hp(),
                        attacker.character.hp + recovered,
                    )
                attacker._schedule_combat_save(now)
                attacker._send_stats({StatType.HP: attacker.character.hp})
        attacker._mark_combat()
        self._mark_combat()
        self.last_pvp_damage_at = time.monotonic()
        if (
            damage > 0
            and (
                (
                    skill_definition is not None
                    and (
                        skill_definition.effect_type == "knock_back"
                        or skill_definition.skill_id == THUNDER_FIREBALL_SKILL_ID
                    )
                )
                or triggered_knockback is not None
            )
            and skill_trigger
            and not self._is_dead()
        ):
            direction = self._apply_shinra_player_knockback(
                attacker,
                (
                    triggered_knockback[1]
                    if triggered_knockback is not None
                    else authoritative_skill_level
                ),
                pending_hit.attacker_x,
                normal_knockback=triggered_knockback is not None,
                distance_pixels=(
                    200 + 10 * max(1, authoritative_skill_level)
                    if skill_definition is not None
                    and skill_definition.skill_id == THUNDER_FIREBALL_SKILL_ID
                    else None
                ),
            )
        payload = (
            f"{op(ServerOpcode.PLAYER_DAMAGE_PLAYER)}:{attacker_id}:{damage}:"
            f"{int(critical)}:{skill_id}:{skill_level}:"
            f"{'true' if skill_trigger else 'false'}:{direction}:"
            f"{self.character.character_id}"
        )
        self._send_visible(payload)
        self._send_visible(
            f"{op(ServerOpcode.PLAYER_HP)}:{self.character.character_id}:"
            f"{self._current_max_hp()}:{self.character.hp}"
        )
        self._send_stats({StatType.HP: self.character.hp})
        if self._is_dead() and self._try_izanagi_revive():
            return
        if reflected_damage > 0 and attacker._is_dead():
            if not attacker._try_izanagi_revive():
                attacker._release_global_battle_items("death")
                attacker._send_player_dead_box()
        if self._is_dead():
            self._release_global_battle_items("death")
            self._send_visible(
                f"{op(ServerOpcode.OPEN_PVP_ACTION)}:4:"
                f"{self.character.character_id}"
            )
            attacker._record_bounty_player_kill(self)
        if (
            self._is_dead()
            and attacker.war_battle_active
            and self.war_battle_active
            and attacker.war_battle_channel == self.war_battle_channel
            and attacker.war_battle_team in (0, 1)
            and self.war_battle_team in (0, 1)
            and attacker.war_battle_team != self.war_battle_team
        ):
            attacker._record_war_battle_kill(self)
            return
        if (
            self._is_dead()
            and attacker.war_3v3_match_id > 0
            and attacker.war_3v3_match_id == self.war_3v3_match_id
            and attacker.war_3v3_team in (0, 1)
            and self.war_3v3_team in (0, 1)
            and attacker.war_3v3_team != self.war_3v3_team
        ):
            attacker._record_war_3v3_kill(self)
            return
        if (
            self._is_dead()
            and attacker.chunin_active
            and self.chunin_active
            and attacker.copy_instance_id == self.copy_instance_id
        ):
            self._record_chunin_defeat(attacker)
            return
        if (
            self._is_dead()
            and attacker.scheduled_warfield_section == "warfield"
            and self.scheduled_warfield_section == "warfield"
            and attacker.character.map_id == 501_000_000
            and self.character.map_id == 501_000_000
        ):
            with self.store.lock:
                self.character.hp = self._current_max_hp()
                self.character.mp = self._current_max_mp()
                self.store.save()
            self._clear_revive_state()
            self._warp_to_map(501_000_000)
            self._send_stats({StatType.HP: self.character.hp, StatType.MP: self.character.mp})
            return
        if (
            self._is_dead()
            and attacker.muye_battle_team in (1, 2)
            and self.muye_battle_team in (1, 2)
            and attacker.muye_battle_team != self.muye_battle_team
        ):
            with attacker.store.lock:
                attacker.character.fame += 1
                attacker.store.save()
            attacker._record_muye_battle_kill(self)
            self._send_player_dead_box()
            return
        if (
            self._is_dead()
            and attacker.local_pk_opponent_id == self.character.character_id
            and self.local_pk_opponent_id == attacker.character.character_id
        ):
            attacker._finish_local_pk_battle(self)
            return
        if self._is_dead():
            if (
                attacker._same_party_as(self)
                or attacker.character.level < attacker.PVP_MIN_LEVEL
                or self.character.level < attacker.PVP_MIN_LEVEL
            ):
                self._send_player_dead_box(attacker)
                return
            with attacker.store.lock:
                attacker.store.state.progression.local_pk_points += 1
                attacker.character.fame += 1
                attacker.store.save()
            attacker._grant_first_pvp_lunhuiyan_soul(self)
            attacker._add_player_kill_crime(self)
            attacker._send_stats({StatType.FAME: attacker.character.fame})
            attacker._send_system_chat(
                f"击败 {self.character.name}，本服决斗积分 +1。"
            )
            self._send_player_dead_box(attacker)

    def handle_open_pvp_action(self, read_str: str) -> None:
        """Change and broadcast the original peace/party/family/all PVP mode."""
        fields = self._request_fields(read_str, ClientOpcode.OPEN_PVP_ACTION)
        if len(fields) < 2 or self._safe_int(fields[0], -1) != 0:
            return
        mode = max(1, min(4, self._safe_int(fields[1], 1)))
        if mode == 2 and (
            self.hub is None
            or self.hub.party_for(self.character.character_id) is None
        ):
            message = EDITOR_RUNTIME.text("no_party_pk", "当前没有队伍，无法切换为队伍模式")
            if message:
                self._send_character_notice(message)
            self.send_text(
                f"{op(ServerOpcode.OPEN_PVP_ACTION)}:2:"
                f"{self.character.character_id}:{self.pvp_mode}"
            )
            return
        if mode == 3 and self._current_family() is None:
            message = EDITOR_RUNTIME.text("no_family_pk", "当前没有家族，无法切换为家族模式")
            if message:
                self._send_character_notice(message)
            self.send_text(
                f"{op(ServerOpcode.OPEN_PVP_ACTION)}:2:"
                f"{self.character.character_id}:{self.pvp_mode}"
            )
            return
        with self.store.lock:
            self.pvp_mode = mode
            self.store.state.pvp_mode = mode
            self.store.save()
        self._send_visible(
            f"{op(ServerOpcode.OPEN_PVP_ACTION)}:2:"
            f"{self.character.character_id}:{mode}"
        )
        mode_name = {
            1: "普通模式",
            2: "组队模式",
            3: "家族模式",
            4: "全体模式",
        }[mode]
        self._send_character_notice(f"已切换为{mode_name}。")

    def _same_party_as(self, target: FakeFlashSession) -> bool:
        if self.hub is None:
            return False
        own_party = self.hub.party_for(self.character.character_id)
        target_party = self.hub.party_for(target.character.character_id)
        return own_party is not None and own_party is target_party

    def _apply_pvp_damage_reflect(
        self,
        attacker: FakeFlashSession,
        received_damage: int,
    ) -> int:
        """Reflect the target's authored percentage without recursively reflecting it."""
        reflect_rate = min(100, max(0, self._current_damage_reflect()))
        if received_damage <= 0 or reflect_rate <= 0 or attacker._is_dead():
            return 0
        if attacker._is_damage_invincible():
            return 0
        reflected = attacker._cap_damage_with_death_protection(
            min(
                attacker.character.hp,
                max(1, round(received_damage * reflect_rate / 100.0)),
            )
        )
        if reflected <= 0:
            return 0
        with attacker.store.lock:
            attacker.character.hp -= reflected
        attacker._schedule_combat_save()
        attacker._send_stats({StatType.HP: attacker.character.hp})
        attacker._send_visible(
            f"{op(ServerOpcode.PLAYER_HP)}:{attacker.character.character_id}:"
            f"{attacker._current_max_hp()}:{attacker.character.hp}"
        )
        return reflected

    def _ordinary_pvp_denial_reason(self, target: FakeFlashSession) -> str:
        if self._same_party_as(target):
            return "同队成员之间不能互相攻击。"
        if self.character.level < self.PVP_MIN_LEVEL:
            return f"达到 {self.PVP_MIN_LEVEL} 级后才能攻击其他玩家。"
        if target.character.level < self.PVP_MIN_LEVEL:
            return f"对方未达到 {self.PVP_MIN_LEVEL} 级，处于新手保护中。"
        return ""

    def _can_attack_player(self, target: FakeFlashSession) -> bool:
        if (
            self.hub is not None
            and self.entered_game
            and target.entered_game
            and self.chunin_active
            and target.chunin_active
            and self.character.map_id in {504_000_000, 505_000_000}
            and target.character.map_id == self.character.map_id
            and self.copy_instance_id == target.copy_instance_id
            and (
                self.character.map_id == 505_000_000
                or self.chunin_opponent_id == target.character.character_id
            )
            and time.monotonic() >= self.chunin_protect_until
            and time.monotonic() >= target.chunin_protect_until
            and target in self.hub.visible_peers(self)
        ):
            return True
        if (
            self.hub is not None
            and self.entered_game
            and target.entered_game
            and self.war_battle_active
            and target.war_battle_active
            and self.war_battle_channel == target.war_battle_channel
            and self.war_battle_team in (0, 1)
            and target.war_battle_team in (0, 1)
            and self.war_battle_team != target.war_battle_team
            and self.character.map_id == 100_020_000
            and target.character.map_id == 100_020_000
            and time.monotonic() >= self.war_battle_protect_until
            and time.monotonic() >= target.war_battle_protect_until
            and target in self.hub.visible_peers(self)
        ):
            return True
        if (
            self.hub is not None
            and self.entered_game
            and target.entered_game
            and self.war_3v3_match_id > 0
            and self.war_3v3_match_id == target.war_3v3_match_id
            and self.war_3v3_team in (0, 1)
            and target.war_3v3_team in (0, 1)
            and self.war_3v3_team != target.war_3v3_team
            and self.character.map_id == 100_030_000
            and target.character.map_id == 100_030_000
            and self.war_3v3_match_id in self.hub.war_3v3_matches
            and time.monotonic() >= self.war_3v3_protect_until
            and time.monotonic() >= target.war_3v3_protect_until
            and target in self.hub.visible_peers(self)
        ):
            return True
        if (
            self.hub is not None
            and self.entered_game
            and target.entered_game
            and self.character.map_id == 401_000_002
            and target.character.map_id == 401_000_002
            and self.local_pk_opponent_id == target.character.character_id
            and target.local_pk_opponent_id == self.character.character_id
            and time.monotonic() >= self.local_pk_protect_until
            and time.monotonic() >= target.local_pk_protect_until
            and target in self.hub.visible_peers(self)
        ):
            return True
        if (
            self.hub is not None
            and self.entered_game
            and target.entered_game
            and self.muye_battle_team in (1, 2)
            and target.muye_battle_team in (1, 2)
            and self.muye_battle_team != target.muye_battle_team
            and target in self.hub.visible_peers(self)
        ):
            return True
        if (
            self.hub is None
            or target is self
            or not self.entered_game
            or not target.entered_game
            or self.pvp_mode == 1
            or target.pvp_mode == 1
            or target not in self.hub.visible_peers(self)
        ):
            return False
        if (
            self.character.level < self.PVP_MIN_LEVEL
            or target.character.level < self.PVP_MIN_LEVEL
            or self._same_party_as(target)
        ):
            return False
        if self.pvp_mode == 3:
            own_account = self.accounts.account_by_id(self.account_id)
            target_account = self.accounts.account_by_id(target.account_id)
            if (
                own_account is not None
                and target_account is not None
                and int(own_account.get("familyId", 0)) != 0
                and int(own_account.get("familyId", 0))
                == int(target_account.get("familyId", 0))
            ):
                return False
        return True

    def _record_muye_battle_kill(self, victim: FakeFlashSession) -> None:
        """Credit one opposing-team kill and push every native battle scoreboard packet."""
        self.muye_battle_kills += 1
        self.muye_battle_points += 1
        self.muye_battle_combo += 1
        self.muye_battle_best_combo = max(
            self.muye_battle_best_combo,
            self.muye_battle_combo,
        )
        victim.muye_battle_combo = 0
        self._send_stats({StatType.FAME: self.character.fame})
        participants = self._muye_battle_participants()
        update_payload = (
            f"{op(ServerOpcode.MUYE_BATTLE)}:6:{self.character.character_id}:"
            f"{self.muye_battle_points}:{self._muye_battle_title(self.muye_battle_combo)}"
        )
        for participant in participants:
            participant.send_text(update_payload)
        self.send_text(
            f"{op(ServerOpcode.MUYE_BATTLE)}:4:{self.muye_battle_kills}:"
            f"{self.muye_battle_points}:{self.muye_battle_combo}"
        )
        victim.send_text(
            f"{op(ServerOpcode.MUYE_BATTLE)}:4:{victim.muye_battle_kills}:"
            f"{victim.muye_battle_points}:0"
        )
        if self.muye_battle_combo >= 3:
            self._broadcast_rare_event(
                f"{self.character.name}在木叶战场完成{self.muye_battle_combo}连杀！",
                highlights=(
                    self.character.name,
                    f"{self.muye_battle_combo}连杀",
                ),
            )
        self._broadcast_muye_battle_top_ranker(participants)

    def _consume_skill_cast(
        self,
        skill_state: SkillState,
        definition: SkillDefinition,
        *,
        cost_multiplier: int = 1,
        allow_active_cooldown: bool = False,
    ) -> bool:
        """Validate and consume one cast's cooldown, MP, essence, and client cooldown state."""
        if self._is_mp_sealed():
            self._send_system_chat("五行封印期间无法释放忍术。")
            return False
        now_ms = int(time.time() * 1_000)
        skill_level = self._effective_skill_level(skill_state)
        cooldown_remaining_ms = (
            self.store.state.skill_cooldowns.get(definition.skill_id, 0) - now_ms
        )
        cooldown_remaining = cooldown_remaining_ms / 1_000
        if (
            not allow_active_cooldown
            and cooldown_remaining > self.COOLDOWN_GRACE_SECONDS
        ):
            self.send_text(
                f"{op(ServerOpcode.COOLDOWN)}:{definition.skill_id}:"
                f"{round(cooldown_remaining * 1_000)}"
            )
            return False
        cost_multiplier = max(1, int(cost_multiplier))
        forbidden_balance = FORBIDDEN_SKILL_BALANCE.get(definition.skill_id)
        project_balance = PROJECT_SPECIAL_SKILL_BALANCE.get(definition.skill_id)
        balance = forbidden_balance or project_balance
        if project_balance is not None:
            mp_cost = project_special_skill_mp_cost(
                definition.skill_id,
                skill_level,
                self._current_max_mp(),
            )
        elif balance is None:
            mp_cost = definition.mp_cost(skill_level)
        else:
            mp_cost = max(
                1,
                round(
                    self._current_max_mp()
                    * balance["max_mp_percent"]
                    / 100.0
                ),
            )
        mp_cost *= cost_multiplier
        zq_cost = definition.zq_cost(skill_level) * cost_multiplier
        if self.character.mp < mp_cost or self.character.zq < zq_cost:
            self._send_system_chat("查克拉或查克拉精华不足，无法释放这个技能。")
            return False
        cooldown_ms = definition.cooldown_ms(skill_level)
        if definition.skill_id == 4_012:
            cooldown_ms *= cost_multiplier
        mastery_changed = False
        with self.store.lock:
            self.character.mp -= mp_cost
            self.character.zq -= zq_cost
            mastery_changed = self._increase_skill_mastery(
                skill_state,
                definition,
            )
            if cooldown_ms:
                self.store.state.skill_cooldowns[definition.skill_id] = (
                    now_ms + cooldown_ms
                )
                # A browser refresh creates a new store/session immediately;
                # journal only the deadline before acknowledging the cast.
                self.store.persist_skill_cooldowns()
        self._schedule_combat_save()
        resource_updates = {StatType.MP: self.character.mp}
        if zq_cost:
            resource_updates[StatType.ZQ] = self.character.zq
        self._send_stats(resource_updates)
        if mastery_changed:
            self._send_skill_update(skill_state)
        if cooldown_ms:
            self.send_text(
                f"{op(ServerOpcode.COOLDOWN)}:{definition.skill_id}:{cooldown_ms}"
            )
        return True

    def _consume_or_reuse_skill_cast(
        self,
        skill_state: SkillState,
        definition: SkillDefinition,
    ) -> bool:
        """Reuse a PVP-announced cast when its monster impact arrives afterward."""
        now = time.monotonic()
        casts = [
            expires_at
            for expires_at in self.preconsumed_skill_casts.get(
                definition.skill_id,
                (),
            )
            if expires_at > now
        ]
        if casts:
            casts.pop(0)
            if casts:
                self.preconsumed_skill_casts[definition.skill_id] = casts
            else:
                self.preconsumed_skill_casts.pop(definition.skill_id, None)
            return True
        return self._consume_skill_cast(skill_state, definition)

    @staticmethod
    def _increase_skill_mastery(
        skill_state: SkillState,
        definition: SkillDefinition,
        amount: int = 1,
    ) -> bool:
        """Increase mastery without exceeding the next upgrade's authored total."""
        _, mastery_cap = definition.upgrade_requirements(skill_state.level + 1)
        normalized = max(0, min(skill_state.master_level, mastery_cap))
        if mastery_cap <= 0:
            normalized = max(0, skill_state.master_level)
        new_value = min(mastery_cap, normalized + max(0, amount))
        if mastery_cap <= 0:
            new_value = normalized
        changed = new_value != skill_state.master_level
        skill_state.master_level = new_value
        return changed

    def _cast_self_skill_buff(
        self,
        read_str: str,
        skill_state: SkillState,
        definition: SkillDefinition,
    ) -> bool:
        """Apply one original self or friendly-area Buff to validated recipients."""
        buff_type = COMBAT_BUFF_TYPE_BY_EFFECT.get(definition.effect_type)
        if buff_type is None or not self._consume_skill_cast(skill_state, definition):
            return False
        skill_level = self._effective_skill_level(skill_state)
        if self.random.random() * 100 >= definition.trigger_percent(skill_level):
            return True
        duration_ms = definition.effect_duration_ms(skill_level)
        if definition.effect_type == "light_sight" and duration_ms <= 0:
            duration_ms = max(1_000, definition.cooldown_ms(skill_level))
        if duration_ms <= 0:
            return True
        targets = self._support_skill_targets(read_str, definition)
        for target in targets:
            target._apply_timed_skill_buff(
                buff_type=buff_type,
                skill_id=definition.skill_id,
                skill_level=skill_level,
                value_percent=definition.effect_value(skill_level),
                duration_ms=duration_ms,
            )
        return True

    def _apply_timed_skill_buff(
        self,
        *,
        buff_type: CombatBuffType,
        skill_id: int,
        skill_level: int,
        value_percent: float,
        duration_ms: int,
        effect_type: str = "",
        source_character_id: int = 0,
        source_monster_id: int = 0,
        metadata: dict[str, int | float | str] | None = None,
    ) -> None:
        """Persist and display one player or pet Buff on this session."""
        duration_ms = max(1, int(duration_ms))
        now_ms = int(time.time() * 1_000)
        with self.store.lock:
            payload: dict[str, int | float | str] = {
                "skill_id": skill_id,
                "skill_level": skill_level,
                "value_percent": value_percent,
                "expires_at": now_ms + duration_ms,
                "effect_type": effect_type,
                "source_character_id": source_character_id,
                "source_monster_id": source_monster_id,
                "next_tick_at": now_ms + 1_000,
            }
            if metadata:
                payload.update(metadata)
            self.store.state.active_skill_buffs[op(buff_type)] = payload
            self.store.save()
        encoded_value = format(value_percent / 100.0, ".6g")
        self.send_text(
            f"{op(ServerOpcode.GIVE_BUFF)}:{op(buff_type)}&{encoded_value}&"
            f"{skill_id}&{skill_level}&{duration_ms}"
        )
        if (
            op(buff_type) == op(CombatBuffType.DARKSIGHT)
            or op(buff_type)
            in {op(value) for value in COMBAT_DEBUFF_TYPE_BY_EFFECT.values()}
        ):
            self._send_visible(
                f"{op(ServerOpcode.GIVE_FOREIGN_BUFF)}:"
                f"{self.character.character_id}:{op(buff_type)}&{encoded_value}&"
                f"{skill_id}&{skill_level}&{duration_ms}:0",
                include_self=False,
            )
        self._send_all_stats()

    def _apply_player_skill_status(
        self,
        definition: SkillDefinition,
        skill_level: int,
        *,
        source_character_id: int,
        source_monster_id: int = 0,
    ) -> bool:
        """Apply one authoritative Debuff to this player after resistance."""
        buff_type = COMBAT_DEBUFF_TYPE_BY_EFFECT.get(definition.effect_type)
        if buff_type is None or not self._skill_status_triggered(
            definition,
            skill_level,
            player_target=self,
        ):
            return False
        transfer_target = self._debuff_transfer_target(source_character_id)
        if transfer_target is not None:
            transfer_target._apply_timed_skill_buff(
                buff_type=buff_type,
                skill_id=definition.skill_id,
                skill_level=skill_level,
                value_percent=definition.effect_value(skill_level),
                duration_ms=max(1_000, definition.effect_duration_ms(skill_level)),
                effect_type=definition.effect_type,
                source_character_id=self.character.character_id,
            )
            return True
        self._apply_timed_skill_buff(
            buff_type=buff_type,
            skill_id=definition.skill_id,
            skill_level=skill_level,
            value_percent=definition.effect_value(skill_level),
            duration_ms=max(1_000, definition.effect_duration_ms(skill_level)),
            effect_type=definition.effect_type,
            source_character_id=source_character_id,
            source_monster_id=source_monster_id,
        )
        return True

    def _debuff_transfer_target(
        self,
        source_character_id: int,
    ) -> FakeFlashSession | None:
        """Return the online PvP source when 乾坤大挪移 transfers this Debuff."""
        passive_state = self.store.state.skills.get(3_335)
        passive = GAME_DATA_CATALOG.get_skill_definition(3_335)
        if passive_state is None or passive is None or self.hub is None:
            return None
        source = self.hub.session_for_character(source_character_id)
        if (
            source is None
            or source is self
            or not source.entered_game
            or source._is_dead()
            or source.line_id != self.line_id
            or source.character.map_id != self.character.map_id
            or source.copy_instance_id != self.copy_instance_id
        ):
            return None
        probability = max(0.0, min(100.0, passive.debuff_transfer_probability))
        if probability <= 0 or probability < self.random.randint(0, 100):
            return None
        return source

    def _send_foreign_dark_sight_to(self, observer: FakeFlashSession) -> None:
        """Replay active invisibility and Debuff icons when an observer enters view."""
        visible_types = {op(CombatBuffType.DARKSIGHT)} | {
            op(value) for value in COMBAT_DEBUFF_TYPE_BY_EFFECT.values()
        }
        now_ms = int(time.time() * 1_000)
        rows: list[str] = []
        for buff_type, payload in self.store.state.active_skill_buffs.items():
            if buff_type not in visible_types:
                continue
            remaining_ms = self._safe_int(payload.get("expires_at"), 0) - now_ms
            if remaining_ms <= 0:
                continue
            rows.append(
                f"{buff_type}&"
                f"{format(float(payload.get('value_percent') or 0) / 100.0, '.6g')}&"
                f"{self._safe_int(payload.get('skill_id'), 0)}&"
                f"{max(1, self._safe_int(payload.get('skill_level'), 1))}&"
                f"{remaining_ms}"
            )
        if rows:
            observer.send_text(
                f"{op(ServerOpcode.GIVE_FOREIGN_BUFF)}:"
                f"{self.character.character_id}:{'@'.join(rows)}:0"
            )

    def _cancel_dark_sight_for_attack(self) -> bool:
        """Break invisibility after an offensive action has passed validation."""
        return self._consume_active_skill_buff(CombatBuffType.DARKSIGHT)

    def _izanagi_payload(self) -> dict[str, Any] | None:
        """Return the live Izanagi recovery window stored under one visible icon."""
        payload = self.store.state.active_skill_buffs.get(op(CombatBuffType.RECOVERY))
        now_ms = int(time.time() * 1_000)
        if (
            not isinstance(payload, dict)
            or payload.get("effect_type") != "izanagi"
            or self._safe_int(payload.get("expires_at"), 0) <= now_ms
        ):
            return None
        return payload

    def _is_damage_invincible(self) -> bool:
        """Honor ordinary invincibility and Izanagi's first five seconds."""
        if self._has_active_skill_buff(CombatBuffType.INVINCIBLE):
            return True
        payload = self._izanagi_payload()
        return bool(
            payload is not None
            and self._safe_int(payload.get("invincible_until"), 0)
            > int(time.time() * 1_000)
        )

    def _try_izanagi_revive(self) -> bool:
        """Instantly restore the cast-time half resources after a lethal hit."""
        if not self._is_dead():
            return False
        payload = self._izanagi_payload()
        now_ms = int(time.time() * 1_000)
        if payload is None or now_ms < self._safe_int(
            payload.get("invincible_until"),
            0,
        ):
            return False
        restore_hp = max(1, self._safe_int(payload.get("restore_hp"), 1))
        restore_mp = max(1, self._safe_int(payload.get("restore_mp"), 1))
        with self.store.lock:
            self.character.hp = min(self._current_max_hp(), restore_hp)
            self.character.mp = min(self._current_max_mp(), restore_mp)
            self.store.save()
        self._clear_revive_state()
        self._consume_active_skill_buff(CombatBuffType.RECOVERY)
        self._send_stats({StatType.HP: self.character.hp, StatType.MP: self.character.mp})
        self._send_visible(
            f"{op(ServerOpcode.PLAYER_HP)}:{self.character.character_id}:"
            f"{self._current_max_hp()}:{self.character.hp}"
        )
        return True

    def _consume_active_skill_buff(self, buff_type: CombatBuffType) -> bool:
        """Consume one active Buff immediately and synchronize its native removal."""
        encoded_type = op(buff_type)
        with self.store.lock:
            if self.store.state.active_skill_buffs.pop(encoded_type, None) is None:
                return False
            self.store.save()
        self.send_text(f"{op(ServerOpcode.CANCEL_BUFF)}:{encoded_type}")
        if encoded_type == op(CombatBuffType.DARKSIGHT) or encoded_type in {
            op(value) for value in COMBAT_DEBUFF_TYPE_BY_EFFECT.values()
        }:
            self._send_visible(
                f"{op(ServerOpcode.CANCEL_FOREIGN_BUFF)}:"
                f"{self.character.character_id}:{encoded_type}",
                include_self=False,
            )
        self._send_all_stats()
        return True

    def _cap_damage_with_death_protection(self, damage: int) -> int:
        """Consume 生死相许 once when incoming damage would otherwise be lethal."""
        bounded = min(max(0, int(damage)), self.character.hp)
        if bounded < self.character.hp or self.character.hp <= 0:
            return bounded
        if not self._consume_active_skill_buff(CombatBuffType.COUPLE_PROTECT):
            return bounded
        return max(0, self.character.hp - 1)

    def _selected_player_ids(self, read_str: str) -> tuple[int, ...]:
        """Return the explicit PlayerAttackInfo player list without trusting stats."""
        if not read_str.startswith(f"{op(ClientOpcode.PLAYER_ATTACK)}:"):
            return ()
        fields = self._request_fields(read_str, ClientOpcode.PLAYER_ATTACK)
        if len(fields) <= 12 or fields[12] in {"", "-"}:
            return ()
        return tuple(
            character_id
            for character_id in (self._safe_int(value, 0) for value in fields[12].split("@"))
            if character_id > 0
        )

    def _support_skill_targets(
        self,
        read_str: str,
        definition: SkillDefinition,
    ) -> tuple[FakeFlashSession, ...]:
        """Resolve the friendly players selected by original target-type 2 skills."""
        if definition.target_type == 3 or self.hub is None:
            return (self,)
        requested = set(self._selected_player_ids(read_str))
        requested.add(self.character.character_id)
        maximum_distance = (
            definition.effect_range(
                self._effective_skill_level(
                    self.store.state.skills.get(definition.skill_id)
                )
            )
            + self.PLAYER_ATTACK_SYNC_TOLERANCE
        )
        targets: list[FakeFlashSession] = []
        for character_id in requested:
            target = (
                self
                if character_id == self.character.character_id
                else self.hub.session_for_character(character_id)
            )
            if (
                target is None
                or not target.entered_game
                or target.character.map_id != self.character.map_id
                or target.line_id != self.line_id
                or target.copy_instance_id != self.copy_instance_id
                or (target.x - self.x) ** 2 + (target.y - self.y) ** 2
                > maximum_distance**2
                or (
                    target is not self
                    and not self._same_party_as(target)
                    and self._can_attack_player(target)
                )
            ):
                continue
            targets.append(target)
        return tuple(dict.fromkeys(targets)) or (self,)

    def _cast_light_sight(
        self,
        read_str: str,
        definition: SkillDefinition,
        skill_level: int,
    ) -> int:
        """Implement 闪光 exactly as the native deDarkSight level comparison."""
        if self.hub is None:
            return 0
        maximum_distance = (
            definition.effect_range(skill_level) + self.PLAYER_ATTACK_SYNC_TOLERANCE
        )
        revealed = 0
        for character_id in dict.fromkeys(self._selected_player_ids(read_str)):
            target = self.hub.session_for_character(character_id)
            if (
                target is None
                or target is self
                or target.character.map_id != self.character.map_id
                or target.line_id != self.line_id
                or target.copy_instance_id != self.copy_instance_id
                or self._same_party_as(target)
                or not self._can_attack_player(target)
                or (target.x - self.x) ** 2 + (target.y - self.y) ** 2
                > maximum_distance**2
            ):
                continue
            payload = target.store.state.active_skill_buffs.get(
                op(CombatBuffType.DARKSIGHT)
            )
            if (
                payload is None
                or target._safe_int(payload.get("expires_at"), 0)
                <= int(time.time() * 1_000)
                or target._safe_int(payload.get("skill_level"), 1) > skill_level
            ):
                continue
            if target._cancel_dark_sight_for_attack():
                revealed += 1
        return revealed

    def _cast_non_damage_skill(
        self,
        read_str: str,
        definition: SkillDefinition,
        skill_level: int,
    ) -> None:
        """Settle healing and movement skills that never produce a monster hit packet."""
        if definition.effect_type == "light_sight":
            self._cast_light_sight(read_str, definition, skill_level)
            return
        if definition.effect_type == "move_to_couple":
            self._move_to_bond_partner(attack=False)
            return
        if definition.effect_type == "move_to_couple_attack":
            self._move_to_bond_partner(attack=True)
            return
        if definition.effect_type == "move":
            return
        if definition.effect_type != "cure_hp":
            return
        target_sessions = list(self._support_skill_targets(read_str, definition))
        rate = max(0.0, definition.effect_value(skill_level))
        for target in dict.fromkeys(target_sessions):
            maximum_hp = target._current_max_hp()
            gain = max(1, round(maximum_hp * rate / 100.0))
            with target.store.lock:
                previous = target.character.hp
                target.character.hp = min(maximum_hp, target.character.hp + gain)
                target.store.save()
            if target.character.hp == previous:
                continue
            target._send_stats({StatType.HP: target.character.hp})
            target._send_visible(
                f"{op(ServerOpcode.PLAYER_HP)}:{target.character.character_id}:"
                f"{maximum_hp}:{target.character.hp}"
            )

    def _move_to_bond_partner(self, *, attack: bool) -> bool:
        """Execute 如影随形 and the teleport phase of 比翼双飞."""
        spouse = self._bond_partner_session()
        if spouse is None or not spouse.entered_game:
            self._send_character_notice("羁绊当前不在线，无法传送。")
            return False
        if spouse.copy_instance_id or self.copy_instance_id:
            self._send_character_notice("副本中无法使用羁绊传送。")
            return False
        self.line_id = spouse.line_id
        self._warp_to_map(
            spouse.character.map_id,
            exact_position=(spouse.x - 30, spouse.y),
        )
        if not attack:
            return True
        candidates = sorted(
            (
                monster
                for monster in self.monsters.values()
                if monster.hp > 0
                and monster.target_character_id == spouse.character.character_id
            ),
            key=lambda monster: (monster.x - spouse.x) ** 2 + (monster.y - spouse.y) ** 2,
        )
        if not candidates:
            return True
        monster = candidates[0]
        damage = self._monster_damage_amount(monster, max(1, self.character.mp * 2))
        monster.hp -= damage
        self._send_visible(
            f"{op(ServerOpcode.DAMAGE_MONSTER)}:{monster.object_id}:{damage}"
        )
        self._send_visible(
            f"{op(ServerOpcode.SHOW_MONSTER_HP)}:{monster.object_id}:"
            f"{round(monster.hp * 100 / monster.max_hp)}"
        )
        if monster.hp == 0:
            self._handle_monster_killed(monster, critical=False)
        return True

    def _legacy_revive_skill_targets(self, *, all_targets: bool) -> int:
        """Apply the resurrection semantics of Edo Tensei and Rinne Tensei."""
        candidates = [
            target
            for target in self._monster_world_sessions()
            if target is not self and target._is_dead()
        ]
        if self.hub is not None:
            party = self.hub.party_for(self.character.character_id)
            if party is not None:
                candidates = [
                    target
                    for target in candidates
                    if target.character.character_id in party.member_ids
                ]
        candidates.sort(
            key=lambda target: (target.x - self.x) ** 2 + (target.y - self.y) ** 2
        )
        if not all_targets:
            candidates = candidates[:1]
        for target in candidates:
            target._complete_revive(ReviveMode.IN_PLACE)
        if not candidates:
            self._send_character_notice("当前范围内没有可复活的目标。")
        return len(candidates)

    def _revive_skill_candidates(
        self,
        read_str: str,
        *,
        all_targets: bool,
    ) -> list[FakeFlashSession]:
        """Resolve dead, not-yet-reviving players for a resurrection skill."""
        candidates = [
            target
            for target in self._monster_world_sessions()
            if target is not self
            and target._is_dead()
            and not target.pending_in_place_revive_at
        ]
        party = (
            self.hub.party_for(self.character.character_id)
            if self.hub is not None
            else None
        )
        if party is not None:
            candidates = [
                target
                for target in candidates
                if target.character.character_id in party.member_ids
            ]
        requested = set(self._selected_player_ids(read_str))
        if not requested:
            return []
        explicitly_selected = [
            target
            for target in candidates
            if target.character.character_id in requested
        ]
        if not explicitly_selected:
            return []
        if not all_targets:
            candidates = explicitly_selected
        candidates.sort(
            key=lambda target: (target.x - self.x) ** 2 + (target.y - self.y) ** 2
        )
        if not all_targets:
            candidates = candidates[:1]
        return candidates

    def _schedule_skill_revive(
        self,
        *,
        controller: FakeFlashSession,
        controlled: bool,
    ) -> bool:
        """Start the native five-second in-place countdown for a skill revive."""
        if not self._is_dead() or self.pending_in_place_revive_at:
            return False
        now = time.monotonic()
        if not self.death_started_at:
            self.death_started_at = now
            self.death_map_id = self.character.map_id
            self.death_position = (self.x, self.y)
        self.auto_return_revive_at = 0.0
        self.pending_in_place_revive_at = now + self.IN_PLACE_REVIVE_SECONDS
        self.pending_skill_revive_kind = "edo_control" if controlled else "skill"
        self.pending_skill_revive_controller_id = controller.character.character_id
        self.send_text(
            f"{op(ServerOpcode.PLAYER_DEAD_BOX)}:2:{self.IN_PLACE_REVIVE_SECONDS}"
        )
        return True

    def _send_edo_control_prompt(self, target: FakeFlashSession) -> None:
        """Ask the caster whether this Edo resurrection should take control."""
        nonce = self.next_edo_prompt_nonce
        self.next_edo_prompt_nonce += 1
        self.pending_edo_prompt = {
            "nonce": nonce,
            "target_id": target.character.character_id,
            "deadline": time.monotonic() + EDO_TENSEI_PROMPT_SECONDS,
        }
        message = f"__EDO_CONTROL__|{nonce}|{target.character.name}"
        if self.wire_mode == "original":
            self.send_original_packet(
                ServerOpcode.SERVERMESSAGE,
                struct.pack("<B", 0) + self._original_utf(message),
            )
        else:
            self.send_text(f"{op(ServerOpcode.SERVERMESSAGE)}:0:{message}")

    def handle_edo_tensei_control(self, read_str: str) -> None:
        """Accept one nonce-bound Edo control choice from the native client."""
        fields = self._request_fields(read_str, ClientOpcode.EDO_TENSEI_CONTROL)
        pending = self.pending_edo_prompt
        if len(fields) < 2 or pending is None:
            return
        nonce = self._safe_int(fields[0], -1)
        if nonce != self._safe_int(pending.get("nonce"), -2):
            return
        self.pending_edo_prompt = None
        if self.hub is None:
            return
        target = self.hub.session_for_character(
            self._safe_int(pending.get("target_id"), 0)
        )
        if target is None or not target._is_dead():
            return
        controlled = str(fields[1]).lower() in {"1", "true", "yes"}
        target._schedule_skill_revive(controller=self, controlled=controlled)

    def _tick_pending_edo_prompt(self, now: float) -> None:
        """Default an unanswered Edo prompt to an ordinary resurrection."""
        pending = self.pending_edo_prompt
        if pending is None or now < float(pending.get("deadline") or 0):
            return
        self.pending_edo_prompt = None
        if self.hub is None:
            return
        target = self.hub.session_for_character(
            self._safe_int(pending.get("target_id"), 0)
        )
        if target is not None and target._is_dead():
            target._schedule_skill_revive(controller=self, controlled=False)

    def _start_edo_tensei_control(self, controller_id: int) -> None:
        """Revive at one tenth stats and hand the character to server AI for 30 seconds."""
        preferred_character_id = self.last_combat_target_character_id
        preferred_monster_id = self.last_combat_target_monster_id
        self._clear_revive_state()
        self.edo_controller_id = controller_id
        self.edo_preferred_character_id = preferred_character_id
        self.edo_preferred_monster_id = preferred_monster_id
        self.edo_controlled_until = time.monotonic() + EDO_TENSEI_CONTROL_SECONDS
        self.edo_next_action_at = time.monotonic()
        self.edo_skill_cursor = 0
        with self.store.lock:
            self.character.hp = max(1, self._current_max_hp())
            self.character.mp = max(1, self._current_max_mp())
            self.store.save()
        self._apply_timed_skill_buff(
            buff_type=CombatBuffType.SEDUCE,
            skill_id=4_007,
            skill_level=1,
            value_percent=0,
            duration_ms=round(EDO_TENSEI_CONTROL_SECONDS * 1_000),
            effect_type="edo_control",
            source_character_id=controller_id,
        )
        self._send_all_stats()
        self._send_visible(
            f"{op(ServerOpcode.PLAYER_HP)}:{self.character.character_id}:"
            f"{self._current_max_hp()}:{self.character.hp}"
        )
        self._send_edo_state_message(True)

    def _send_edo_state_message(self, active: bool) -> None:
        """Toggle the local death filter and input lock used by Edo control."""
        message = f"__EDO_STATE__|{1 if active else 0}"
        if self.wire_mode == "original":
            self.send_original_packet(
                ServerOpcode.SERVERMESSAGE,
                struct.pack("<B", 0) + self._original_utf(message),
            )
        else:
            self.send_text(f"{op(ServerOpcode.SERVERMESSAGE)}:0:{message}")

    def _is_edo_controlled(self, now: float | None = None) -> bool:
        current = time.monotonic() if now is None else now
        return self.edo_controlled_until > current

    def _finish_edo_tensei_control(self) -> None:
        """End Edo control, kill the vessel, and return normal death control."""
        if not self.edo_controlled_until:
            return
        self.edo_controlled_until = 0.0
        self.edo_controller_id = 0
        self.edo_preferred_character_id = 0
        self.edo_preferred_monster_id = 0
        self.edo_next_action_at = 0.0
        self.edo_skill_cursor = 0
        with self.store.lock:
            self.character.hp = 0
            self.store.save()
        self._consume_active_skill_buff(CombatBuffType.SEDUCE)
        self._send_edo_state_message(False)
        self._send_stats({StatType.HP: 0})
        self._send_visible(
            f"{op(ServerOpcode.PLAYER_HP)}:{self.character.character_id}:"
            f"{self._current_max_hp()}:0"
        )
        self.death_penalty_applied = True
        self._send_player_dead_box()

    @staticmethod
    def _is_ai_combat_ninjutsu(skill_id: int) -> bool:
        """Allow career, world, and non-couple other ninjutsu only."""
        return skill_id in {
            1_001_001,
            1_001_002,
            1_001_003,
            2_001_001,
            2_001_002,
            2_001_003,
            3_001_001,
            3_001_002,
            3_001_003,
            4_001_001,
            4_001_002,
            4_001_003,
            1_002_001,
            1_002_002,
            1_002_003,
            2_000,
            2_001,
            2_002,
            2_003,
            2_004,
            3_110,
            3_120,
            3_130,
            3_140,
        }

    def _next_ai_combat_ninjutsu(
        self,
        cursor: int,
    ) -> tuple[SkillDefinition | None, int]:
        candidates: list[tuple[SkillDefinition, int]] = []
        for skill_id, state in sorted(self.store.state.skills.items()):
            if state.level <= 0 or not self._is_ai_combat_ninjutsu(skill_id):
                continue
            definition = GAME_DATA_CATALOG.get_skill_definition(skill_id)
            if definition is None:
                continue
            candidates.append((definition, self._effective_skill_level(state)))
        if not candidates:
            return None, 1
        return candidates[max(0, cursor) % len(candidates)]

    def _tick_edo_tensei_control(self, now: float) -> None:
        """Move and attack with a small server-authoritative combat AI."""
        if not self.edo_controlled_until:
            return
        if now >= self.edo_controlled_until:
            self._finish_edo_tensei_control()
            return
        if now < self.edo_next_action_at or self._is_dead():
            return
        self.edo_next_action_at = now + 0.45
        player_target = None
        if self.hub is not None and self.edo_preferred_character_id:
            candidate = self.hub.session_for_character(self.edo_preferred_character_id)
            if candidate is not None and self._can_attack_player(candidate):
                player_target = candidate
        monster_target = self.monsters.get(self.edo_preferred_monster_id)
        if monster_target is not None and monster_target.hp <= 0:
            monster_target = None
        if player_target is None and monster_target is None:
            monsters = [monster for monster in self.monsters.values() if monster.hp > 0]
            if monsters:
                monster_target = min(
                    monsters,
                    key=lambda monster: (monster.x - self.x) ** 2 + (monster.y - self.y) ** 2,
                )
            elif self.hub is not None:
                enemies = [
                    peer
                    for peer in self.hub.visible_peers(self)
                    if self._can_attack_player(peer)
                ]
                if enemies:
                    player_target = min(
                        enemies,
                        key=lambda peer: (peer.x - self.x) ** 2 + (peer.y - self.y) ** 2,
                    )
        target_x = player_target.x if player_target is not None else (
            monster_target.x if monster_target is not None else self.x
        )
        target_y = player_target.y if player_target is not None else (
            monster_target.y if monster_target is not None else self.y
        )
        distance_sq = (target_x - self.x) ** 2 + (target_y - self.y) ** 2
        if distance_sq > 210**2:
            distance = max(1.0, math.sqrt(distance_sq))
            step = min(90.0, distance - 190.0)
            self.x = self._short_coordinate(self.x + (target_x - self.x) * step / distance)
            self.y = self._short_coordinate(self.y + (target_y - self.y) * step / distance)
            self.character.x = self.x
            self.character.y = self.y
            self._send_visible(
                f"{op(ServerOpcode.MOVE_PLAYER)}:0:{self.character.character_id}:0:0:"
                f"{self.x}:{self.y}:0:0:0:0:0:0"
            )
            return
        direction = 1 if target_x >= self.x else -1
        skill_definition, skill_level = self._next_ai_combat_ninjutsu(
            self.edo_skill_cursor
        )
        self.edo_skill_cursor += 1
        skill_id = skill_definition.skill_id if skill_definition is not None else 0
        damage_percent = (
            skill_definition.damage_percent(skill_level)
            if skill_definition is not None
            else 100
        )
        if monster_target is not None:
            damage, critical = self._calculate_player_damage(
                monster_target,
                damage_percent,
                force_hit=False,
            )
            damage = self._apply_copy_damage_rules(
                monster_target,
                self._monster_damage_amount(monster_target, damage),
            )
            monster_target.hp -= damage
            if skill_definition is not None:
                self._apply_monster_skill_status(
                    monster_target,
                    skill_definition,
                    skill_level,
                )
            self._broadcast_player_attack_info(
                character_id=self.character.character_id,
                skill_id=skill_id,
                skill_level=skill_level,
                x=self.x,
                y=self.y,
                monsters=(monster_target.object_id,),
                stance=0,
                direction=direction,
            )
            self._send_visible(
                f"{op(ServerOpcode.DAMAGE_MONSTER)}:{monster_target.object_id}:{damage}"
            )
            if monster_target.hp == 0:
                self._handle_monster_killed(monster_target, critical=critical)
            return
        if player_target is not None:
            pending = PendingPvpHit(
                skill_id=skill_id,
                skill_level=skill_level,
                created_at=now,
                expires_at=now + self.COMBAT_CAST_WINDOW_SECONDS,
                server_settle_at=now,
                attacker_x=self.x,
                attacker_y=self.y,
                target_x=player_target.x,
                target_y=player_target.y,
                map_id=self.character.map_id,
                line_id=self.line_id,
                copy_instance_id=self.copy_instance_id,
            )
            player_target.pending_pvp_hits.setdefault(
                self.character.character_id,
                [],
            ).append(pending)
            self._broadcast_player_attack_info(
                character_id=self.character.character_id,
                skill_id=skill_id,
                skill_level=skill_level,
                x=self.x,
                y=self.y,
                players=(player_target.character.character_id,),
                stance=0,
                direction=direction,
            )
            player_target.handle_player_damage(
                f"{op(ClientOpcode.PLAYER_DAMAGE)}:{self.character.character_id}:0:0:"
                f"{skill_id}:{skill_level}:true:{direction}"
            )

    @staticmethod
    def _project_skill_prerequisite(skill_id: int) -> int:
        return {
            MULTI_SHADOW_CLONE_SKILL_ID: SHADOW_CLONE_SKILL_ID,
            FLYING_RAIJIN_MARK_SKILL_ID: FLYING_RAIJIN_INSTANT_SKILL_ID,
        }.get(skill_id, 0)

    def _has_project_skill_prerequisite(self, skill_id: int) -> bool:
        prerequisite = self._project_skill_prerequisite(skill_id)
        if prerequisite <= 0 or prerequisite in self.store.state.skills:
            return True
        self._send_character_notice("请先学习前置特别忍术。")
        return False

    def _clear_shadow_clones(self) -> None:
        """Remove every transient clone without touching account or save state."""
        if not self.shadow_clones:
            return
        clones = tuple(self.shadow_clones.values())
        self.shadow_clones.clear()
        self._send_shadow_clone_buff_state(clones[0].skill_id, active=False)
        for clone in clones:
            self._broadcast_shadow_clone_despawn(clone)
            self._send_visible(
                f"{op(ServerOpcode.REMOVE_PLAYER_FROM_MAP)}:{clone.actor_id}"
            )

    def _broadcast_shadow_clone_despawn(self, clone: ShadowCloneState) -> None:
        """Publish spatial audio while clients can still resolve the clone actor."""
        self._broadcast_player_attack_info(
            character_id=clone.actor_id,
            skill_id=clone.skill_id,
            skill_level=1,
            x=clone.x,
            y=clone.y,
            stance=0,
            direction=0 if clone.facing_right else 1,
            speed=0,
            attack=0,
            defence=0,
            critical=0,
            evasion=0,
            tag={"semantic": "shadow_clone_despawn"},
        )

    def _remove_shadow_clone(self, actor_id: int) -> bool:
        """Remove one clone exactly once and publish its disappearance."""
        clone = self.shadow_clones.pop(int(actor_id), None)
        if clone is None:
            return False
        if not self.shadow_clones:
            self._send_shadow_clone_buff_state(clone.skill_id, active=False)
        self._broadcast_shadow_clone_despawn(clone)
        self._send_visible(
            f"{op(ServerOpcode.REMOVE_PLAYER_FROM_MAP)}:{clone.actor_id}"
        )
        return True

    def _apply_player_damage_to_shadow_clone(
        self,
        owner: FakeFlashSession,
        clone: ShadowCloneState,
        definition: SkillDefinition | None,
        skill_level: int,
    ) -> int:
        """Settle an authorized hostile player hit against a transient clone."""
        if clone.hp <= 0 or clone.actor_id not in owner.shadow_clones:
            return 0
        ignored_defence = min(100, max(0, self._current_ignore_defence()))
        effective_defence = round(
            clone.defence * (100 - ignored_defence) / 100.0
        )
        raw_damage = round(
            self._current_attack()
            * self.MONSTER_DAMAGE_REDUCTION_BASE
            / (self.MONSTER_DAMAGE_REDUCTION_BASE + max(0, effective_defence))
        )
        if definition is not None:
            raw_damage = round(
                raw_damage * definition.damage_percent(skill_level) / 100.0
            )
        critical = self._roll_combat_rate(self._current_critical())
        if critical:
            raw_damage *= self.CRITICAL_DAMAGE_MULTIPLIER
        damage = min(clone.hp, max(1, raw_damage))
        clone.hp -= damage
        self._mark_combat()
        owner._mark_combat()
        direction = 1 if clone.x >= self.x else -1
        self._send_visible(
            f"{op(ServerOpcode.PLAYER_DAMAGE_PLAYER)}:"
            f"{self.character.character_id}:{damage}:{int(critical)}:"
            f"{definition.skill_id if definition is not None else 0}:"
            f"{skill_level}:false:{direction}:{clone.actor_id}"
        )
        self._send_visible(
            f"{op(ServerOpcode.PLAYER_HP)}:{clone.actor_id}:"
            f"{clone.max_hp}:{clone.hp}"
        )
        if clone.hp <= 0:
            owner._remove_shadow_clone(clone.actor_id)
        return damage

    def _spawn_shadow_clones(self, skill_id: int) -> bool:
        balance = PROJECT_SPECIAL_SKILL_BALANCE[skill_id]
        clone_count = max(1, balance["clone_count"])
        duration_seconds = balance["duration_ms"] / 1_000.0
        skill_state = self.store.state.skills.get(skill_id)
        skill_level = (
            self._effective_skill_level(skill_state)
            if skill_state is not None
            else 1
        )
        attribute_ratio_bp = project_shadow_clone_attribute_ratio_bp(
            skill_id,
            skill_level,
        )

        def clone_stat(value: int, *, minimum: int = 1) -> int:
            return max(minimum, round(value * attribute_ratio_bp / 10_000.0))

        self._clear_shadow_clones()
        now = time.monotonic()
        # Keep every clone clear of the owner so its player model and effects remain
        # distinguishable. Keep edge-clamped offsets on the owner's actual floor;
        # generic ground projection can otherwise snap an overflow point onto a
        # lower stacked platform and make a clone appear to fall through the map.
        offsets = (80,) if clone_count == 1 else (-120, 80, 160)
        owner_floor = self._shadow_clone_floor(
            self.x,
            self.y,
            self.character.foothold,
        )
        occupied_x: set[int] = set()
        for offset in offsets[:clone_count]:
            actor_id = (
                self.hub.allocate_transient_player_id()
                if self.hub is not None
                else 1_700_000_000 + len(self.shadow_clones)
            )
            x, y, foothold = self.x + offset, self.y, self.character.foothold
            if owner_floor is not None:
                margin = min(24, max(0, (owner_floor.right - owner_floor.left) // 6))
                left = owner_floor.left + margin
                right = owner_floor.right - margin
                x = max(left, min(right, x))
                if x in occupied_x:
                    alternatives = sorted(
                        range(left, right + 1, 32),
                        key=lambda candidate: (
                            candidate in occupied_x,
                            abs(candidate - (self.x + offset)),
                        ),
                    )
                    x = next(
                        (candidate for candidate in alternatives if candidate not in occupied_x),
                        x,
                    )
                y = owner_floor.y_at(x)
                foothold = owner_floor.foothold_id
            elif self.current_map is not None:
                x, y, foothold = self.current_map.ground_position(x, y, foothold)
            occupied_x.add(x)
            clone = ShadowCloneState(
                actor_id=actor_id,
                skill_id=skill_id,
                x=x,
                y=y,
                foothold=foothold,
                max_hp=clone_stat(self._current_max_hp()),
                hp=clone_stat(self._current_max_hp()),
                attack=clone_stat(self._current_attack()),
                defence=clone_stat(self._current_defence()),
                critical=clone_stat(self._current_critical()),
                evasion=clone_stat(self._current_evasion()),
                dexterity=clone_stat(self.character.ap_dex, minimum=0),
                attack_speed=clone_stat(self._current_attack_speed()),
                walk_speed=clone_stat(self._current_walk_speed()),
                expires_at=now + duration_seconds,
                next_action_at=now + 0.35,
                next_move_at=now + 0.05,
                facing_right=self.direction == 0,
            )
            self.shadow_clones[actor_id] = clone
            self._send_visible(self._shadow_clone_spawn_payload(clone))
            self._send_visible(self._shenqi_status_payload(clone.actor_id))
            clone_family_flag = self._family_flag_identity_payload(clone.actor_id)
            if clone_family_flag is not None:
                self._send_visible(clone_family_flag)
            self._send_visible(self._pvp_mode_payload(clone.actor_id))
            self._broadcast_player_attack_info(
                character_id=clone.actor_id,
                skill_id=skill_id,
                skill_level=skill_level,
                x=clone.x,
                y=clone.y,
                stance=0,
                direction=0 if clone.facing_right else 1,
                speed=0,
                attack=0,
                defence=0,
                critical=0,
                evasion=0,
                tag={"semantic": "shadow_clone_summon"},
            )
        self._send_shadow_clone_buff_state(
            skill_id,
            active=True,
            duration_ms=balance["duration_ms"],
        )
        return True

    def _shadow_clone_target(
        self,
        clone: ShadowCloneState,
    ) -> tuple[MonsterState | None, FakeFlashSession | None]:
        monster_target = self.monsters.get(self.last_combat_target_monster_id)
        if monster_target is not None and monster_target.hp <= 0:
            monster_target = None
            self.last_combat_target_monster_id = 0
        player_target = None
        if self.hub is not None and self.last_combat_target_character_id:
            candidate = self.hub.session_for_character(
                self.last_combat_target_character_id
            )
            if candidate is not None and self._can_attack_player(candidate):
                player_target = candidate
            else:
                self.last_combat_target_character_id = 0
        if monster_target is None and player_target is None:
            living = [monster for monster in self.monsters.values() if monster.hp > 0]
            if living:
                monster_target = min(
                    living,
                    key=lambda monster: (monster.x - clone.x) ** 2
                    + (monster.y - clone.y) ** 2,
                )
            elif self.hub is not None:
                enemies = [
                    peer
                    for peer in self.hub.visible_peers(self)
                    if self._can_attack_player(peer)
                ]
                if enemies:
                    player_target = min(
                        enemies,
                        key=lambda peer: (peer.x - clone.x) ** 2
                        + (peer.y - clone.y) ** 2,
                    )
        return monster_target, player_target

    def _shadow_clone_floor(
        self,
        x: int,
        y: int,
        foothold_id: int = 0,
    ) -> FootholdState | None:
        """Resolve a clone/target floor without projecting across stacked platforms."""
        if self.current_map is None:
            return None
        floor = self.current_map.footholds.get(int(foothold_id))
        if (
            floor is not None
            and floor.x1 != floor.x2
            and floor.left - 24 <= x <= floor.right + 24
            and abs(floor.y_at(max(floor.left, min(floor.right, x))) - y) <= 120
        ):
            return floor
        return self.current_map.foothold_below(x, y)

    def _shadow_clone_target_floor(
        self,
        monster: MonsterState | None,
        player: FakeFlashSession | None,
    ) -> FootholdState | None:
        if monster is not None:
            return self._shadow_clone_floor(
                monster.x,
                monster.y,
                monster.foothold,
            )
        if player is not None:
            return self._shadow_clone_floor(
                player.x,
                player.y,
                player.character.foothold,
            )
        return None

    def _stop_shadow_clone(self, clone: ShadowCloneState) -> None:
        if not clone.moving:
            return
        clone.moving = False
        self._send_visible(
            f"{op(ServerOpcode.MOVE_PLAYER)}:0:{clone.actor_id}:0:0:"
            f"{clone.x}:{clone.y}:0:0:{PLAYER_MOVEMENT_FLAG_GROUNDED}:"
            f"{PLAYER_MOVEMENT_ACTION_STAND}:0:{clone.foothold}"
        )

    def _shadow_clone_can_attack(
        self,
        clone: ShadowCloneState,
        target_x: int,
        target_y: int,
        target_foothold: int = 0,
    ) -> bool:
        if abs(target_x - clone.x) > 210:
            return False
        if self.current_map is None:
            return abs(target_y - clone.y) <= 120
        clone_floor = self._shadow_clone_floor(clone.x, clone.y, clone.foothold)
        target_floor = self._shadow_clone_floor(target_x, target_y, target_foothold)
        return (
            clone_floor is not None
            and target_floor is not None
            and clone_floor.foothold_id == target_floor.foothold_id
        )

    def _move_shadow_clone(
        self,
        clone: ShadowCloneState,
        target_x: int,
        target_y: int,
        target_foothold: int = 0,
        now: float | None = None,
    ) -> bool:
        current = time.monotonic() if now is None else now
        # Nya samples native player movement every 100 ms. The fragment starts
        # at the old position and velocity carries the remote actor to the new
        # authoritative position; sending the endpoint as the fragment origin
        # makes the client overshoot and snap back on every update.
        interval_seconds = 0.10
        # Clone combat attributes remain one tenth of the owner's, but its
        # visible movement must track the owner. Re-read the value here so
        # equipment, skill buffs, weather and other live modifiers are not
        # frozen at the moment the clone was summoned.
        owner_walk_speed = max(1, self._current_walk_speed())
        clone.walk_speed = max(1, round(owner_walk_speed / 10.0))
        visual_speed = float(owner_walk_speed)
        max_step = visual_speed * interval_seconds
        floor = self._shadow_clone_floor(clone.x, clone.y, clone.foothold)
        target_floor = self._shadow_clone_floor(target_x, target_y, target_foothold)
        if self.current_map is not None and floor is not None:
            grounded_x = max(floor.left, min(floor.right, clone.x))
            clone.x = grounded_x
            clone.y = floor.y_at(grounded_x)
            clone.foothold = floor.foothold_id

        destination_x = target_x
        stop_distance = 190.0
        arrival_distance = 210.0
        if (
            self.current_map is not None
            and floor is not None
            and target_floor is not None
            and floor.foothold_id != target_floor.foothold_id
        ):
            path_edge = self.current_map.monster_path_next_edge(
                floor.foothold_id,
                target_floor.foothold_id,
            )
            if path_edge is None:
                self._stop_shadow_clone(clone)
                return False
            next_foothold_id, transition_kind, transition_x = path_edge
            next_floor = self.current_map.footholds[next_foothold_id]
            destination_x = max(floor.left, min(floor.right, transition_x))
            stop_distance = 0.0
            arrival_distance = float(self.MONSTER_PATH_JOINT_TOLERANCE)
            if abs(destination_x - clone.x) <= self.MONSTER_PATH_JOINT_TOLERANCE:
                clone.facing_right = target_x >= clone.x
                if transition_kind == "ladder":
                    previous_x, previous_y = clone.x, clone.y
                    next_x = max(next_floor.left, min(next_floor.right, transition_x))
                    next_y = next_floor.y_at(next_x)
                    duration_ms = max(
                        250,
                        min(
                            2_000,
                            round(abs(next_y - previous_y) / visual_speed * 1_000),
                        ),
                    )
                    velocity_y = self._short_coordinate(
                        (next_y - previous_y) * 1_000 / duration_ms
                    )
                    clone.x, clone.y, clone.foothold = (
                        next_x,
                        next_y,
                        next_foothold_id,
                    )
                    clone.moving = True
                    clone.attack_animation_until = 0.0
                    clone.next_move_at = current + duration_ms / 1_000.0
                    self._send_visible(
                        f"{op(ServerOpcode.MOVE_PLAYER)}:0:{clone.actor_id}:0:0:"
                        f"{previous_x}:{previous_y}:0:{velocity_y}:"
                        f"{PLAYER_MOVEMENT_FLAG_CLIMBING}:"
                        f"{PLAYER_MOVEMENT_ACTION_LADDER}:{duration_ms}:"
                        f"{clone.foothold}"
                    )
                    # Queue the grounded endpoint immediately after the ladder
                    # fragment. The client applies movement fragments in order;
                    # without this queued reset, a delayed/missing server tick
                    # can leave the remote clone's climbing flag set forever.
                    self._send_visible(
                        f"{op(ServerOpcode.MOVE_PLAYER)}:0:{clone.actor_id}:0:0:"
                        f"{next_x}:{next_y}:0:0:{PLAYER_MOVEMENT_FLAG_GROUNDED}:"
                        f"{PLAYER_MOVEMENT_ACTION_STAND}:0:{clone.foothold}"
                    )
                    return True
                clone.foothold = next_foothold_id
                floor = next_floor
                clone.x = max(floor.left, min(floor.right, transition_x))
                clone.y = floor.y_at(clone.x)
                clone.next_move_at = current + interval_seconds
                self._stop_shadow_clone(clone)
                return True
        elif floor is not None and target_floor is not None:
            if floor.foothold_id != target_floor.foothold_id:
                self._stop_shadow_clone(clone)
                return False
            destination_x = max(floor.left, min(floor.right, target_x))
        elif abs(target_y - clone.y) > 120:
            self._stop_shadow_clone(clone)
            return False

        horizontal_distance = abs(destination_x - clone.x)
        if horizontal_distance <= max(arrival_distance, stop_distance):
            self._stop_shadow_clone(clone)
            return False
        step = min(max_step, max(0.0, horizontal_distance - stop_distance))
        if step <= 0:
            self._stop_shadow_clone(clone)
            return False
        previous_x, previous_y = clone.x, clone.y
        direction = 1 if destination_x >= clone.x else -1
        next_x = self._short_coordinate(clone.x + direction * step)
        next_y = previous_y if floor is None else floor.y_at(next_x)
        clone.facing_right = direction > 0
        clone.x, clone.y = next_x, next_y
        clone.moving = True
        clone.attack_animation_until = 0.0
        velocity_x = self._short_coordinate(
            (next_x - previous_x) / interval_seconds
        )
        self._send_visible(
            f"{op(ServerOpcode.MOVE_PLAYER)}:0:{clone.actor_id}:0:0:"
            f"{previous_x}:{previous_y}:{velocity_x}:0:"
            f"{PLAYER_MOVEMENT_FLAG_GROUNDED}:{PLAYER_MOVEMENT_ACTION_WALK}:"
            f"{round(interval_seconds * 1000)}:{clone.foothold}"
        )
        clone.next_move_at = current + interval_seconds
        return True

    def _shadow_clone_monster_damage(
        self,
        clone: ShadowCloneState,
        monster: MonsterState,
        skill_definition: SkillDefinition | None = None,
        skill_level: int = 1,
    ) -> tuple[int, bool]:
        definition = GAME_DATA_CATALOG.get_monster_definition(monster.template_id)
        evasion = self._monster_stat(
            monster,
            definition.evasion,
            EliteAttribute.EVASION,
        )
        if self.random.randrange(100) >= self._player_hit_chance(
            definition,
            evasion,
            clone.dexterity,
        ):
            return 0, False
        defence = self._monster_stat(
            monster,
            definition.defence,
            EliteAttribute.DEFENCE,
        )
        mitigation = max(0, defence - clone.dexterity // 2)
        damage = max(1, clone.attack - mitigation)
        if skill_definition is not None:
            damage = max(
                1,
                round(
                    damage
                    * skill_definition.damage_percent(skill_level)
                    / 100.0
                ),
            )
        critical = self.random.randrange(self.COMBAT_RATE_SCALE) < min(
            self.COMBAT_RATE_CAP,
            max(0, clone.critical),
        )
        if critical:
            damage *= self.CRITICAL_DAMAGE_MULTIPLIER
        return self._monster_damage_amount(monster, damage), critical

    def _apply_shadow_clone_player_damage(
        self,
        clone: ShadowCloneState,
        target: FakeFlashSession,
        skill_definition: SkillDefinition | None = None,
        skill_level: int = 1,
    ) -> None:
        if target._is_dead() or not self._can_attack_player(target):
            return
        raw_damage = round(
            clone.attack
            * self.MONSTER_DAMAGE_REDUCTION_BASE
            / (
                self.MONSTER_DAMAGE_REDUCTION_BASE
                + max(0, target._current_defence())
            )
        )
        if skill_definition is not None:
            raw_damage = round(
                raw_damage
                * skill_definition.damage_percent(skill_level)
                / 100.0
            )
        critical = self.random.randrange(self.COMBAT_RATE_SCALE) < min(
            self.COMBAT_RATE_CAP,
            max(0, clone.critical),
        )
        if critical:
            raw_damage *= self.CRITICAL_DAMAGE_MULTIPLIER
        raw_damage = round(
            raw_damage * (100 - min(100, max(0, target._current_damage_reduce()))) / 100
        )
        yata_reduction = target._yata_mirror_resistance_percent(skill_definition)
        raw_damage = round(raw_damage * (100 - yata_reduction) / 100.0)
        damage = (
            0
            if target._is_damage_invincible()
            else target._cap_damage_with_death_protection(
                min(max(1, raw_damage), target.character.hp)
            )
        )
        with target.store.lock:
            target.character.hp -= damage
        target._schedule_combat_save()
        target._mark_combat()
        self._mark_combat()
        target._send_visible(
            f"{op(ServerOpcode.PLAYER_DAMAGE_PLAYER)}:{clone.actor_id}:{damage}:"
            f"{int(critical)}:0:1:false:{1 if target.x >= clone.x else -1}:"
            f"{target.character.character_id}"
        )
        target._send_visible(
            f"{op(ServerOpcode.PLAYER_HP)}:{target.character.character_id}:"
            f"{target._current_max_hp()}:{target.character.hp}"
        )
        target._send_stats({StatType.HP: target.character.hp})
        if skill_definition is not None:
            target._apply_player_skill_status(
                skill_definition,
                skill_level,
                source_character_id=self.character.character_id,
            )
        if target._is_dead() and not target._try_izanagi_revive():
            target._release_global_battle_items("death")
            target._send_player_dead_box(self)

    def _tick_shadow_clones(self, now: float) -> None:
        if not self.shadow_clones:
            return
        if self._is_dead():
            self._clear_shadow_clones()
            return
        expired = [
            actor_id
            for actor_id, clone in self.shadow_clones.items()
            if now >= clone.expires_at or clone.hp <= 0
        ]
        for actor_id in expired:
            self._remove_shadow_clone(actor_id)
        for clone in tuple(self.shadow_clones.values()):
            monster_target, player_target = self._shadow_clone_target(clone)
            target_x = (
                player_target.x
                if player_target is not None
                else monster_target.x
                if monster_target is not None
                else clone.x
            )
            target_y = (
                player_target.y
                if player_target is not None
                else monster_target.y
                if monster_target is not None
                else clone.y
            )
            target_floor = self._shadow_clone_target_floor(
                monster_target,
                player_target,
            )
            target_foothold = target_floor.foothold_id if target_floor is not None else 0
            if clone.moving and now < clone.next_move_at:
                continue
            if now >= clone.next_move_at and self._move_shadow_clone(
                clone,
                target_x,
                target_y,
                target_foothold,
                now,
            ):
                continue
            if monster_target is None and player_target is None:
                continue
            if not self._shadow_clone_can_attack(
                clone,
                target_x,
                target_y,
                target_foothold,
            ):
                continue
            if now < clone.next_action_at:
                if (
                    clone.attack_animation_until
                    and now >= clone.attack_animation_until
                ):
                    clone.attack_animation_until = 0.0
                    self._send_visible(
                        f"{op(ServerOpcode.MOVE_PLAYER)}:0:{clone.actor_id}:0:0:"
                        f"{clone.x}:{clone.y}:0:0:"
                        f"{PLAYER_MOVEMENT_FLAG_GROUNDED}:"
                        f"{PLAYER_MOVEMENT_ACTION_STAND}:0:{clone.foothold}"
                    )
                continue
            clone.next_action_at = now + max(
                0.55,
                1.15 - min(500, clone.attack_speed) / 1_000.0,
            )
            direction = 0 if target_x >= clone.x else 1
            clone.facing_right = direction == 0
            clone.moving = False
            clone.attack_animation_until = now + 0.35
            self._send_visible(
                f"{op(ServerOpcode.MOVE_PLAYER)}:0:{clone.actor_id}:0:0:"
                f"{clone.x}:{clone.y}:0:0:{PLAYER_MOVEMENT_FLAG_GROUNDED}:"
                f"{PLAYER_MOVEMENT_ACTION_ATTACK}:350:{clone.foothold}"
            )
            skill_definition, skill_level = self._next_ai_combat_ninjutsu(
                clone.skill_cursor
            )
            clone.skill_cursor += 1
            skill_id = skill_definition.skill_id if skill_definition is not None else 0
            if monster_target is not None:
                damage, critical = self._shadow_clone_monster_damage(
                    clone,
                    monster_target,
                    skill_definition,
                    skill_level,
                )
                monster_target.target_character_id = clone.actor_id
                monster_target.engaged_character_ids.add(clone.actor_id)
                monster_target.hp -= damage
                if skill_definition is not None:
                    self._apply_monster_skill_status(
                        monster_target,
                        skill_definition,
                        skill_level,
                    )
                self._record_world_boss_damage(monster_target, damage)
                self._record_xiulian_damage(monster_target, damage)
                self._broadcast_player_attack_info(
                    character_id=clone.actor_id,
                    skill_id=skill_id,
                    skill_level=skill_level,
                    x=clone.x,
                    y=clone.y,
                    monsters=(monster_target.object_id,),
                    stance=0,
                    direction=direction,
                    attack=clone.attack,
                    defence=clone.defence,
                    critical=clone.critical,
                    evasion=clone.evasion,
                )
                self._send_visible(
                    f"{op(ServerOpcode.DAMAGE_MONSTER)}:"
                    f"{monster_target.object_id}:{damage}"
                )
                self._send_visible(
                    f"{op(ServerOpcode.SHOW_MONSTER_HP)}:{monster_target.object_id}:"
                    f"{round(monster_target.hp * 100 / monster_target.max_hp)}"
                )
                if monster_target.hp == 0:
                    self._handle_monster_killed(monster_target, critical=critical)
            elif player_target is not None:
                self._broadcast_player_attack_info(
                    character_id=clone.actor_id,
                    skill_id=skill_id,
                    skill_level=skill_level,
                    x=clone.x,
                    y=clone.y,
                    players=(player_target.character.character_id,),
                    stance=0,
                    direction=direction,
                    attack=clone.attack,
                    defence=clone.defence,
                    critical=clone.critical,
                    evasion=clone.evasion,
                )
                self._apply_shadow_clone_player_damage(
                    clone,
                    player_target,
                    skill_definition,
                    skill_level,
                )

    def _tick_flying_raijin_mark(self, now: float) -> None:
        if (
            self.flying_raijin_instant_chain_until
            and now >= self.flying_raijin_instant_chain_until
        ):
            self.flying_raijin_instant_chain_until = 0.0
            self._send_flying_raijin_buff_state(
                FLYING_RAIJIN_INSTANT_SKILL_ID,
                active=False,
            )
            skill_state = self.store.state.skills.get(FLYING_RAIJIN_INSTANT_SKILL_ID)
            skill_level = (
                self._effective_skill_level(skill_state)
                if skill_state is not None
                else 1
            )
            cooldown_ms = project_special_skill_cooldown_ms(
                FLYING_RAIJIN_INSTANT_SKILL_ID,
                skill_level,
            )
            with self.store.lock:
                self.store.state.skill_cooldowns[
                    FLYING_RAIJIN_INSTANT_SKILL_ID
                ] = int(time.time() * 1_000) + cooldown_ms
                self.store.persist_skill_cooldowns()
            self.send_text(
                f"{op(ServerOpcode.COOLDOWN)}:{FLYING_RAIJIN_INSTANT_SKILL_ID}:{cooldown_ms}"
            )
            self._send_character_notice("飞雷神之术·瞬的连用窗口已结束，进入冷却。")
        mark = self.flying_raijin_mark
        if mark is not None and now >= mark.expires_at:
            self.flying_raijin_mark = None
            self._send_flying_raijin_buff_state(
                FLYING_RAIJIN_MARK_SKILL_ID,
                active=False,
            )
            self._send_character_notice("飞雷神标记已消失。")

    def _send_flying_raijin_buff_state(
        self,
        skill_id: int,
        *,
        active: bool,
        duration_ms: int = 0,
    ) -> None:
        """Update the caster-only visual timer without applying combat stats."""
        self._send_player_attack_info(
            character_id=self.character.character_id,
            skill_id=skill_id,
            skill_level=1,
            x=self.x,
            y=self.y,
            stance=0,
            direction=self.direction,
            speed=0,
            attack=0,
            defence=0,
            critical=0,
            evasion=0,
            tag={
                "semantic": "flying_raijin_state",
                "active": bool(active),
                "duration_ms": max(0, int(duration_ms)),
            },
        )

    def _send_shadow_clone_buff_state(
        self,
        skill_id: int,
        *,
        active: bool,
        duration_ms: int = 0,
    ) -> None:
        """Show the authoritative clone lifetime in the caster's Buff panel."""
        self._send_player_attack_info(
            character_id=self.character.character_id,
            skill_id=skill_id,
            skill_level=1,
            x=self.x,
            y=self.y,
            stance=0,
            direction=self.direction,
            speed=0,
            attack=0,
            defence=0,
            critical=0,
            evasion=0,
            tag={
                "semantic": "shadow_clone_state",
                "active": bool(active),
                "duration_ms": max(0, int(duration_ms)),
            },
        )

    def _broadcast_flying_raijin_phase(
        self,
        skill_id: int,
        phase: str,
        x: int,
        y: int,
    ) -> None:
        """Render one explicit departure, placement, or arrival at its true point."""
        self._broadcast_player_attack_info(
            character_id=self.character.character_id,
            skill_id=skill_id,
            skill_level=1,
            x=x,
            y=y,
            stance=0,
            direction=self.direction,
            speed=0,
            attack=0,
            defence=0,
            critical=0,
            evasion=0,
            tag={"semantic": "flying_raijin_phase", "phase": phase},
        )

    def _selected_flying_raijin_target(
        self,
        read_str: str,
    ) -> tuple[int, int, int, bool] | None:
        if not read_str.startswith(f"{op(ClientOpcode.PLAYER_ATTACK)}:"):
            return None
        fields = self._request_fields(read_str, ClientOpcode.PLAYER_ATTACK)
        player_ids = (
            [self._safe_int(value, 0) for value in fields[12].split("@")]
            if len(fields) > 12 and fields[12] not in {"", "-"}
            else []
        )
        monster_ids = (
            [self._safe_int(value, 0) for value in fields[13].split("@")]
            if len(fields) > 13 and fields[13] not in {"", "-"}
            else []
        )
        if self.hub is not None:
            for character_id in player_ids:
                target = self.hub.session_for_character(character_id)
                if (
                    target is not None
                    and target is not self
                    and target in self.hub.visible_peers(self)
                    and (self._same_party_as(target) or self._can_attack_player(target))
                ):
                    return (
                        target.x,
                        target.y,
                        target.character.foothold,
                        target.direction == 0,
                    )
        for object_id in monster_ids:
            monster = self.monsters.get(object_id)
            if monster is not None and monster.hp > 0:
                x, y = self._monster_render_position(monster)
                return x, y, monster.foothold, monster.facing_right
        return None

    def _commit_flying_raijin_position(
        self,
        x: int,
        y: int,
        foothold: int,
        *,
        project_to_ground: bool = True,
    ) -> None:
        old_position = (self.x, self.y)
        if project_to_ground and self.current_map is not None:
            x, y, foothold = self.current_map.ground_position(x, y, foothold)
        with self.store.lock:
            self.x = self._short_coordinate(x)
            self.y = self._short_coordinate(y)
            self.character.x = self.x
            self.character.y = self.y
            self.character.foothold = foothold
            self.store.save()
        now = time.monotonic()
        self.player_knockback_origin = old_position
        self.player_knockback_guard_until = (
            now + self.PLAYER_KNOCKBACK_INPUT_GUARD_SECONDS
        )
        self._record_position_sample(now)
        # MOVE_PLAYER command 0 controls foreign Character instances. The local
        # player has a KeyController and ignores that path; command 1 is the
        # original server-forced position packet used by onMovePlayerByServer.
        self.send_text(
            f"{op(ServerOpcode.MOVE_PLAYER)}:1:{self.character.character_id}:0:0:"
            f"{self.x}:{self.y}"
        )
        if self.hub is not None:
            self.hub.broadcast_visible(
                self,
                f"{op(ServerOpcode.MOVE_PLAYER)}:0:{self.character.character_id}:0:0:"
                f"{self.x}:{self.y}:0:0:0:0:0:0",
            )

    def _cast_project_special_skill(
        self,
        read_str: str,
        skill_state: SkillState,
        definition: SkillDefinition,
    ) -> bool:
        skill_id = definition.skill_id
        if not self._has_project_skill_prerequisite(skill_id):
            return False
        if skill_id in SHADOW_CLONE_SKILL_IDS:
            if not self._consume_or_reuse_skill_cast(skill_state, definition):
                return False
            self._mark_combat()
            return self._spawn_shadow_clones(skill_id)
        if skill_id == FLYING_RAIJIN_INSTANT_SKILL_ID:
            target = self._selected_flying_raijin_target(read_str)
            if target is None:
                self._send_character_notice(
                    "请选择同图怪物、敌对玩家或队友作为飞雷神目标。"
                )
                self.send_text(f"{op(ServerOpcode.COOLDOWN)}:{skill_id}:0")
                return False
            now = time.monotonic()
            chain_open = (
                self.flying_raijin_instant_chain_until > now
            )
            if not self._consume_skill_cast(
                skill_state,
                definition,
                allow_active_cooldown=chain_open,
            ):
                return False
            origin_x, origin_y = self.x, self.y
            target_x, target_y, target_foothold, target_facing_right = target
            behind_x = target_x - 60 if target_facing_right else target_x + 60
            self._broadcast_flying_raijin_phase(
                skill_id,
                "departure",
                origin_x,
                origin_y,
            )
            self._commit_flying_raijin_position(
                behind_x,
                target_y,
                target_foothold,
            )
            self._broadcast_flying_raijin_phase(
                skill_id,
                "arrival",
                self.x,
                self.y,
            )
            if not chain_open:
                # Keep the authoritative deadline persisted during the five-second
                # second-cast window. The client is unlocked explicitly below;
                # a refresh therefore cannot erase the cast.
                self.flying_raijin_instant_chain_until = (
                    now + FLYING_RAIJIN_INSTANT_CHAIN_WINDOW_SECONDS
                )
                self._send_flying_raijin_buff_state(
                    skill_id,
                    active=True,
                    duration_ms=round(
                        FLYING_RAIJIN_INSTANT_CHAIN_WINDOW_SECONDS * 1_000
                    ),
                )
                self.send_text(
                    f"{op(ServerOpcode.COOLDOWN)}:{FLYING_RAIJIN_INSTANT_SKILL_ID}:0"
                )
            else:
                self.flying_raijin_instant_chain_until = 0.0
                self._send_flying_raijin_buff_state(skill_id, active=False)
            return True
        if skill_id == FLYING_RAIJIN_MARK_SKILL_ID:
            now = time.monotonic()
            mark = self.flying_raijin_mark
            if mark is None or now >= mark.expires_at:
                cooldown_remaining = (
                    self.store.state.skill_cooldowns.get(skill_id, 0)
                    - int(time.time() * 1_000)
                )
                if cooldown_remaining > round(self.COOLDOWN_GRACE_SECONDS * 1_000):
                    self.send_text(
                        f"{op(ServerOpcode.COOLDOWN)}:{skill_id}:"
                        f"{cooldown_remaining}"
                    )
                    return False
                duration = PROJECT_SPECIAL_SKILL_BALANCE[skill_id]["duration_ms"] / 1_000
                self.flying_raijin_mark = FlyingRaijinMarkState(
                    map_id=self.character.map_id,
                    line_id=self.line_id,
                    copy_instance_id=self.copy_instance_id,
                    x=self.x,
                    y=self.y,
                    foothold=self.character.foothold,
                    expires_at=now + duration,
                )
                self._broadcast_flying_raijin_phase(
                    skill_id,
                    "mark_place",
                    self.x,
                    self.y,
                )
                self._send_flying_raijin_buff_state(
                    skill_id,
                    active=True,
                    duration_ms=round(duration * 1_000),
                )
                self.send_text(f"{op(ServerOpcode.COOLDOWN)}:{skill_id}:0")
                self._send_character_notice("已留下飞雷神标记，60秒内再次释放可返回。")
                return True
            if (
                mark.map_id != self.character.map_id
                or mark.line_id != self.line_id
                or mark.copy_instance_id != self.copy_instance_id
            ):
                self.flying_raijin_mark = None
                self._send_flying_raijin_buff_state(skill_id, active=False)
                self._send_character_notice("飞雷神标记已失效。")
                return False
            if not self._consume_skill_cast(skill_state, definition):
                return False
            origin_x, origin_y = self.x, self.y
            self.flying_raijin_mark = None
            self._broadcast_flying_raijin_phase(
                skill_id,
                "departure",
                origin_x,
                origin_y,
            )
            self._send_flying_raijin_buff_state(skill_id, active=False)
            self._commit_flying_raijin_position(
                mark.x,
                mark.y,
                mark.foothold,
                project_to_ground=False,
            )
            self._broadcast_flying_raijin_phase(
                skill_id,
                "arrival",
                self.x,
                self.y,
            )
            return True
        return False

    def _apply_direct_skill_damage(
        self,
        targets: Iterable[MonsterState],
        definition: SkillDefinition,
        skill_level: int,
    ) -> None:
        """Settle placeholder禁术 entries that have no client-generated impact phase."""
        for monster in targets:
            if monster.hp <= 0:
                continue
            monster.target_character_id = self.character.character_id
            calculated, critical = self._calculate_player_damage(
                monster,
                definition.damage_percent(skill_level),
                force_hit=True,
            )
            damage = self._monster_damage_amount(monster, calculated)
            damage = self._apply_copy_damage_rules(monster, damage)
            self._record_world_boss_damage(monster, damage)
            self._record_xiulian_damage(monster, damage)
            monster.hp -= damage
            if self.arena_monster is monster and self.arena_opponent is not None:
                self.arena_opponent.hp = monster.hp
            if definition.skill_id == 4_008:
                self._apply_shiki_fujin_recoil(damage)
            self._send_visible(
                f"{op(ServerOpcode.DAMAGE_MONSTER)}:{monster.object_id}:{damage}"
            )
            self._send_visible(
                f"{op(ServerOpcode.SHOW_MONSTER_HP)}:{monster.object_id}:"
                f"{round(monster.hp * 100 / monster.max_hp)}"
            )
            if monster.hp == 0:
                self._handle_monster_killed(monster, critical=critical)

    def _apply_shiki_fujin_recoil(self, dealt_damage: int) -> int:
        """Mirror Shiki Fujin's real damage to its caster without killing them."""
        recoil = min(max(0, int(dealt_damage)), max(0, self.character.hp - 1))
        if recoil <= 0:
            return 0
        with self.store.lock:
            self.character.hp -= recoil
        self._schedule_combat_save()
        self.send_text(
            f"{op(ServerOpcode.DAMAGE_PLAYER)}:{self.character.character_id}:"
            f"4008:false:{recoil}:0:0:0:0"
        )
        self._send_stats({StatType.HP: self.character.hp})
        self._send_visible(
            f"{op(ServerOpcode.PLAYER_HP)}:{self.character.character_id}:"
            f"{self._current_max_hp()}:{self.character.hp}"
        )
        return recoil

    def _cast_chibaku_tensei(
        self,
        read_str: str,
        definition: SkillDefinition,
        skill_level: int,
    ) -> bool:
        """Start the server-authoritative Chibaku damage/control timeline."""
        fields = self._request_fields(read_str, ClientOpcode.PLAYER_ATTACK)
        center_x = self._safe_int(fields[10], self.x) if len(fields) > 10 else self.x
        center_y = self._safe_int(fields[11], self.y) if len(fields) > 11 else self.y
        radius = definition.effect_range(skill_level)
        target_ids = tuple(
            monster.object_id
            for monster in self.monsters.values()
            if monster.hp > 0
            and (self._monster_render_position(monster)[0] - center_x) ** 2
            + (self._monster_render_position(monster)[1] - center_y) ** 2
            <= radius**2
        )
        # Do not emit any native 4010 visual packet here.  Flash/Ruffle routes
        # the cast and movement packets through BeatBackEffect, which can
        # freeze the entire client.  The shared timeline below still applies
        # the authoritative three damage phases.
        state = self.world_state or WorldMapState(self.monsters, self.drops)
        self.world_state = state
        state.pending_skill_effects.append(
            PendingWorldSkillEffect(
                skill_id=definition.skill_id,
                caster_id=self.character.character_id,
                skill_level=skill_level,
                center_x=center_x,
                center_y=center_y,
                target_ids=target_ids,
                phase=0,
                due_at=time.monotonic() + 0.35,
            )
        )
        return bool(target_ids)

    def _cast_advanced_skill(
        self,
        read_str: str,
        definition: SkillDefinition,
        skill_level: int,
        revive_targets: list[FakeFlashSession] | None = None,
    ) -> bool:
        """Execute禁术 rows whose original GameData has no normal hit workflow."""
        if definition.skill_id == 4_006:
            now_ms = int(time.time() * 1_000)
            self._apply_timed_skill_buff(
                buff_type=CombatBuffType.RECOVERY,
                skill_id=definition.skill_id,
                skill_level=skill_level,
                value_percent=0,
                duration_ms=IZANAGI_DURATION_MS,
                effect_type="izanagi",
                metadata={
                    "invincible_until": now_ms + IZANAGI_INVINCIBLE_MS,
                    "restore_hp": max(1, self.character.hp // 2),
                    "restore_mp": max(1, self.character.mp // 2),
                },
            )
            return False
        if definition.skill_id == 4_007:
            if revive_targets:
                self._send_edo_control_prompt(revive_targets[0])
            return False
        if definition.skill_id == 4_010:
            return self._cast_chibaku_tensei(read_str, definition, skill_level)
        if definition.skill_id == 4_012:
            for target in revive_targets or ():
                target._schedule_skill_revive(controller=self, controlled=False)
            return False
        targets = self._resolve_attack_targets(read_str, definition)
        if definition.multi_target and not targets:
            radius = definition.effect_range(skill_level)
            targets = [
                monster
                for monster in self.monsters.values()
                if monster.hp > 0
                and (self._monster_render_position(monster)[0] - self.x) ** 2
                + (self._monster_render_position(monster)[1] - self.y) ** 2
                <= radius**2
            ]
        self._apply_direct_skill_damage(
            targets if definition.multi_target else targets[:1],
            definition,
            skill_level,
        )
        return bool(targets)

    def _apply_attack(self, read_str: str) -> None:
        """Validate cooldown/resources, then apply hit, defence, and critical calculations."""
        if self._is_dead():
            return
        skill_state, skill_definition = self._resolve_attack_skill(read_str)
        if skill_definition is False:
            return
        if (
            isinstance(skill_definition, SkillDefinition)
            and self._reject_skill_for_current_location(
                skill_definition.skill_id,
                acknowledge=False,
            )
        ):
            return
        if (
            isinstance(skill_definition, SkillDefinition)
            and skill_state is not None
            and skill_definition.skill_id in PROJECT_SPECIAL_SKILL_BALANCE
        ):
            self._cast_project_special_skill(
                read_str,
                skill_state,
                skill_definition,
            )
            return
        if (
            isinstance(skill_definition, SkillDefinition)
            and skill_state is not None
            and skill_definition.target_type in {2, 3}
            and skill_definition.effect_type in COMBAT_BUFF_TYPE_BY_EFFECT
        ):
            if self._cast_self_skill_buff(read_str, skill_state, skill_definition):
                self._mark_combat()
            return
        if (
            isinstance(skill_definition, SkillDefinition)
            and skill_state is not None
            and (
                skill_definition.effect_type in NON_DAMAGE_SKILL_EFFECTS
                or skill_definition.skill_id in DIRECT_CAST_SKILL_IDS
            )
        ):
            revive_targets: list[FakeFlashSession] | None = None
            cost_multiplier = 1
            if skill_definition.skill_id in {4_007, 4_012}:
                if skill_definition.skill_id == 4_007 and self.pending_edo_prompt is not None:
                    self._send_character_notice("已有一个秽土转生选择正在等待确认。")
                    return
                revive_targets = self._revive_skill_candidates(
                    read_str,
                    all_targets=skill_definition.skill_id == 4_012,
                )
                if not revive_targets:
                    self._send_character_notice("当前场景没有尚未复活的合法目标。")
                    self.send_text(
                        f"{op(ServerOpcode.COOLDOWN)}:"
                        f"{skill_definition.skill_id}:0"
                    )
                    self._send_stats(
                        {
                            StatType.MP: self.character.mp,
                            StatType.ZQ: self.character.zq,
                        }
                    )
                    return
                if skill_definition.skill_id == 4_012:
                    cost_multiplier = len(revive_targets)
            consumed = (
                self._consume_skill_cast(
                    skill_state,
                    skill_definition,
                    cost_multiplier=cost_multiplier,
                )
                if skill_definition.skill_id in {4_007, 4_012}
                else self._consume_or_reuse_skill_cast(
                    skill_state,
                    skill_definition,
                )
            )
            if not consumed:
                return
            self._mark_combat()
            skill_level = self._effective_skill_level(skill_state)
            if skill_definition.skill_id in DIRECT_CAST_SKILL_IDS:
                if self._cast_advanced_skill(
                    read_str,
                    skill_definition,
                    skill_level,
                    revive_targets,
                ):
                    self._cancel_dark_sight_for_attack()
            else:
                self._cast_non_damage_skill(read_str, skill_definition, skill_level)
            return
        targets = self._resolve_attack_targets(
            read_str,
            skill_definition if isinstance(skill_definition, SkillDefinition) else None,
        )
        if not targets:
            return
        self.last_combat_target_monster_id = targets[0].object_id
        self._mark_combat()
        if isinstance(skill_definition, SkillDefinition):
            if skill_state is None or not self._consume_or_reuse_skill_cast(
                skill_state,
                skill_definition,
            ):
                return
            skill_level = self._effective_skill_level(skill_state)
            damage_percent = skill_definition.damage_percent(skill_level)
            target_limit = len(targets) if skill_definition.multi_target else 1
        else:
            damage_percent = 100
            target_limit = 1

        self._cancel_dark_sight_for_attack()
        resolved_targets = targets[:target_limit]
        hit_results: list[PlayerHitResult] = []
        triggered_knockback = self._triggered_knockback_passive(
            skill_definition if isinstance(skill_definition, SkillDefinition) else None
        )
        triggered_knockback_any = False
        for monster in resolved_targets:
            monster.target_character_id = self.character.character_id
            calculated_damage, critical = self._calculate_player_damage(
                monster,
                damage_percent,
                force_hit=(
                    isinstance(skill_definition, SkillDefinition)
                    and skill_definition.skill_id == 4_009
                ),
            )
            damage = self._monster_damage_amount(monster, calculated_damage)
            damage = self._apply_copy_damage_rules(monster, damage)
            self._record_world_boss_damage(monster, damage)
            self._record_xiulian_damage(monster, damage)
            monster.hp -= damage
            if self.arena_monster is monster and self.arena_opponent is not None:
                self.arena_opponent.hp = monster.hp
            hit_results.append(PlayerHitResult(monster, damage, critical))
            if damage > 0 and triggered_knockback is not None and monster.hp > 0:
                passive_definition, passive_level = triggered_knockback
                if self._skill_status_triggered(
                    passive_definition,
                    passive_level,
                    monster_target=monster,
                ):
                    triggered_knockback_any = self._begin_monster_knockback(
                        monster,
                        source_x=self.x,
                        skill_level=passive_level,
                        normal_knockback=True,
                    ) or triggered_knockback_any
            if (
                isinstance(skill_definition, SkillDefinition)
                and skill_definition.effect_type in COMBAT_DEBUFF_TYPE_BY_EFFECT
            ):
                self._apply_monster_skill_status(
                    monster,
                    skill_definition,
                    skill_level,
                )

        if read_str.startswith(f"{op(ClientOpcode.MOB_ATTACK)}:"):
            self._send_mob_attack_result(
                read_str,
                hit_results,
                skill_trigger=(
                    triggered_knockback_any
                    if triggered_knockback is not None
                    else None
                ),
            )
        else:
            for result in hit_results:
                self._send_visible(
                    f"{op(ServerOpcode.DAMAGE_MONSTER)}:"
                    f"{result.monster.object_id}:{result.damage}"
                )
        if (
            isinstance(skill_definition, SkillDefinition)
            and skill_definition.skill_id in {4_009, THUNDER_FIREBALL_SKILL_ID}
            and hit_results
        ):
            thunder_fireball = (
                skill_definition.skill_id == THUNDER_FIREBALL_SKILL_ID
            )
            knockback_distance = (
                200 + 10 * max(1, skill_level)
                if thunder_fireball
                else None
            )
            knockback_targets = tuple(
                result.monster.object_id
                for result in hit_results
                if self._begin_monster_knockback(
                    result.monster,
                    source_x=self.x,
                    skill_level=skill_level,
                    distance_pixels=knockback_distance,
                )
            )
        else:
            knockback_targets = ()
        if knockback_targets:
            self._broadcast_player_attack_info(
                character_id=self.character.character_id,
                skill_id=skill_definition.skill_id,
                skill_level=skill_level,
                x=self.x,
                y=self.y,
                monsters=knockback_targets,
                stance=127,
                direction=(
                    0
                    if all(
                        self.monsters[target_id].x >= self.x
                        for target_id in knockback_targets
                    )
                    else 1
                ),
                tag={
                    "semantic": (
                        "knock_back" if thunder_fireball else "knock_up"
                    ),
                    "visual_all": 1,
                    "exact_center": 0 if thunder_fireball else 1,
                    "distance": knockback_distance or 0,
                    "duration_ms": 450 if thunder_fireball else 0,
                },
            )

        for result in hit_results:
            monster = result.monster
            hp_percent = round(monster.hp * 100 / monster.max_hp)
            self._send_visible(
                f"{op(ServerOpcode.SHOW_MONSTER_HP)}:{monster.object_id}:{hp_percent}"
            )
            if monster.hp == 0:
                self._handle_monster_killed(monster, critical=result.critical)
        if (
            isinstance(skill_definition, SkillDefinition)
            and skill_definition.effect_type == "suck_hp"
        ):
            recovered = round(
                sum(
                    result.damage
                    for result in hit_results
                    if self._skill_status_triggered(
                        skill_definition,
                        skill_level,
                        monster_target=result.monster,
                    )
                )
                * max(0.0, skill_definition.effect_value(skill_level))
                / 100.0
            )
            if recovered > 0:
                with self.store.lock:
                    self.character.hp = min(
                        self._current_max_hp(),
                        self.character.hp + recovered,
                    )
                    self.store.save()
                self._send_stats({StatType.HP: self.character.hp})
        self._apply_an_qi_damage(read_str)

    def _send_mob_attack_result(
        self,
        read_str: str,
        hit_results: list[PlayerHitResult],
        *,
        skill_trigger: bool | None = None,
    ) -> None:
        """Return opcode 184 so Flash renders each skill's original hit particle."""
        if not hit_results:
            return
        fields = self._request_fields(read_str, ClientOpcode.MOB_ATTACK)
        is_player = self._safe_int(fields[0], 1) if len(fields) > 0 else 1
        character_id = self._safe_int(fields[1], self.character.character_id) if len(fields) > 1 else self.character.character_id
        pet_uid = fields[2] if len(fields) > 2 else "0"
        character_level = self._safe_int(fields[3], self.character.level) if len(fields) > 3 else self.character.level
        if skill_trigger is None:
            skill_trigger = fields[7].lower() == "true" if len(fields) > 7 else True
        skill_level = max(1, self._safe_int(fields[8], 1)) if len(fields) > 8 else 1
        skill_id = self._attack_skill_id(read_str)
        if skill_id == 4_009:
            # GameData defines a 100% trigger for Shenluo Tianzheng. Keeping this
            # authoritative makes the client load its 0004009 effect and hit SWFs
            # even when an old native client sends a stale false trigger bit.
            skill_trigger = True
        stance = self._safe_int(fields[10], 0) if len(fields) > 10 else 0
        direction = self._safe_int(fields[11], 0) if len(fields) > 11 else 0
        encoded_hits = "@".join(
            f"{result.monster.object_id}&{str(result.monster.hp > 0).lower()}&"
            f"{result.damage}*{int(result.critical)}"
            for result in hit_results
        )
        self._send_visible(
            f"{op(ServerOpcode.MOB_ATTACK)}:{is_player}:{character_id}:{pet_uid}:"
            f"{character_level}:1:{len(hit_results)}:{str(skill_trigger).lower()}:"
            f"{skill_level}:{skill_id}:{stance}:{direction}:{encoded_hits}"
        )

    def _apply_an_qi_damage(self, read_str: str) -> None:
        """Apply client-triggered shuriken targets and emit AnQiDamageInfo action 2."""
        if not read_str.startswith(f"{op(ClientOpcode.PLAYER_ATTACK)}:"):
            return
        fields = self._request_fields(read_str, ClientOpcode.PLAYER_ATTACK)
        # PlayerAttackInfo.encode writes players, mobs, players_anqi, mobs_anqi,
        # then tag.  A non-null tag is metadata, never a shuriken target list.
        # Treating field 16 as targets suppressed the AN_QI action-2 response,
        # so the stock client never created its projectile/hit effect or sound.
        anqi_targets_index = 15
        if len(fields) <= anqi_targets_index or fields[anqi_targets_index] == "-":
            return
        if not self.store.state.progression.stage_progress.get("手里剑:开启", 1):
            return
        stage = self._cultivation_stage("手里剑", 7)
        level = self._an_qi_level()
        stage_config = GAME_DATA_CATALOG.get_cultivation_stage("AnQi", stage)
        levels = stage_config.get("levels") if isinstance(stage_config.get("levels"), dict) else {}
        level_data = levels.get(str(level), {}) if isinstance(levels, dict) else {}
        attack = stage_config.get("attack") if isinstance(stage_config.get("attack"), dict) else {}
        damage_rate = max(1, self._safe_int(level_data.get("atk_rate"), 1))
        target_limit = max(1, self._safe_int(attack.get("target"), 1))
        hits: list[tuple[MonsterState, int]] = []
        successful_hits = 0
        seen: set[int] = set()
        for raw_target_id in fields[anqi_targets_index].split("@"):
            object_id = self._safe_int(raw_target_id, -1)
            monster = self.monsters.get(object_id)
            if monster is None or monster.hp <= 0 or object_id in seen:
                continue
            seen.add(object_id)
            definition = GAME_DATA_CATALOG.get_monster_definition(monster.template_id)
            monster_evasion = self._monster_stat(
                monster,
                definition.evasion,
                EliteAttribute.EVASION,
            )
            monster_evasion = round(
                monster_evasion
                * max(0.0, 100.0 - self._monster_status_value(monster, "reduce_avd"))
                / 100.0
            )
            hit_chance = self._player_hit_chance(
                definition,
                monster_evasion,
                max(0, self.character.ap_dex),
            )
            if self.random.randrange(100) >= hit_chance:
                hits.append((monster, 0))
                if len(hits) >= target_limit:
                    break
                continue
            damage = self._monster_damage_amount(
                monster,
                max(1, round(self._current_attack() * damage_rate / 100)),
            )
            damage = self._apply_copy_damage_rules(monster, damage)
            self._record_world_boss_damage(monster, damage)
            self._record_xiulian_damage(monster, damage, "an_qi")
            monster.hp -= damage
            hits.append((monster, damage))
            successful_hits += 1
            if len(hits) >= target_limit:
                break
        if not hits:
            return
        encoded_hits = "@".join(f"{monster.object_id}&{damage}" for monster, damage in hits)
        self._send_visible(
            f"{op(ServerOpcode.AN_QI)}:{op(CultivationResponseAction.RESULT)}:"
            f"{self.character.character_id}:{stage}:{level}:{fields[5]}:{fields[6]}:{fields[7]}:"
            f"-:{encoded_hits}"
        )
        for monster, damage in hits:
            hp_percent = round(monster.hp * 100 / monster.max_hp)
            self._send_visible(
                f"{op(ServerOpcode.SHOW_MONSTER_HP)}:{monster.object_id}:{hp_percent}"
            )
            if damage > 0 and monster.hp == 0:
                self._handle_monster_killed(monster)
        mastery, mastery_max = self._an_qi_mastery(stage, level)
        if successful_hits > 0 and mastery < mastery_max:
            mastery = min(mastery_max, mastery + successful_hits)
            with self.store.lock:
                if mastery >= mastery_max and level < 4:
                    self.store.state.progression.stages["手里剑:等级"] = level + 1
                    self.store.state.progression.stage_progress["手里剑"] = 0
                else:
                    self.store.state.progression.stage_progress["手里剑"] = mastery
                self.store.save()
            self._send_an_qi_state()

    @classmethod
    def _monster_damage_amount(cls, monster: MonsterState, requested_damage: int) -> int:
        """Make wealth and essence mice take exactly one fifth of max HP per hit."""
        if requested_damage <= 0 or monster.hp <= 0:
            return 0
        damage = (
            max(1, monster.max_hp // cls.SPECIAL_MOUSE_HITS_TO_KILL)
            if cls._is_five_hit_mouse_template(monster.template_id)
            else max(1, requested_damage)
        )
        return min(monster.hp, damage)

    @classmethod
    def _is_five_hit_mouse_template(cls, template_id: int) -> bool:
        """Match every wealth mouse and the Fate's Choice essence mouse."""
        return cls._is_wealth_mouse_family(template_id) or template_id == 4_300_000

    @staticmethod
    def _is_wealth_mouse_template(template_id: int) -> bool:
        """Match every real wealth-mouse row without including its linked variants."""
        return 4_100_000 <= template_id <= 4_100_012 and template_id % 2 == 0

    @staticmethod
    def _is_wealth_mouse_family(template_id: int) -> bool:
        """Match every GameData row that shares the original wealth-mouse body."""
        return 4_100_000 <= template_id <= 4_100_019

    def _calculate_player_damage(
        self,
        monster: MonsterState,
        damage_percent: int,
        *,
        force_hit: bool = False,
    ) -> tuple[int, bool]:
        """Calculate one hit and preserve its critical flag for Flash presentation."""
        if self.arena_monster is monster and self.arena_opponent is not None:
            mitigation = max(0, self.arena_opponent.defence - self.character.ap_dex // 2)
            damage = max(
                1,
                round(
                    max(1, self._current_attack() - mitigation)
                    * damage_percent
                    / 100
                ),
            )
            critical = self._roll_combat_rate(self._current_critical())
            if critical:
                damage *= self.CRITICAL_DAMAGE_MULTIPLIER
            return damage, critical
        definition = GAME_DATA_CATALOG.get_monster_definition(monster.template_id)
        dexterity = max(0, self.character.ap_dex)
        monster_evasion = self._monster_stat(
            monster, definition.evasion, EliteAttribute.EVASION
        )
        monster_evasion = round(
            monster_evasion
            * max(0.0, 100.0 - self._monster_status_value(monster, "reduce_avd"))
            / 100.0
        )
        hit_chance = self._player_hit_chance(definition, monster_evasion, dexterity)
        if not force_hit and self.random.randrange(100) >= hit_chance:
            return 0, False
        # _current_attack already applies equipment, item, and skill percentages
        # independently to the same flat subtotal. Do not multiply that result again.
        attack = self._current_attack()
        ignored_defence = min(
            100,
            max(
                0,
                self._current_ignore_defence(),
                self._monster_status_value(monster, "pet_ignore_def"),
            ),
        )
        monster_defence = self._monster_stat(
            monster, definition.defence, EliteAttribute.DEFENCE
        )
        defence_reduction = max(
            self._monster_status_value(monster, "lose_eq_def"),
            self._monster_status_value(monster, "reduce_def"),
        )
        monster_defence = round(
            monster_defence * max(0.0, 100.0 - defence_reduction) / 100.0
        )
        effective_defence = round(monster_defence * (100 - ignored_defence) / 100)
        mitigation = max(0, effective_defence - dexterity // 2)
        damage = max(1, round(max(1, attack - mitigation) * damage_percent / 100))
        critical = self._roll_combat_rate(self._current_critical())
        damage = EDITOR_RUNTIME.formula("combat", damage, critical=critical)
        extra_attack_rate = min(
            100,
            max(0, self._passive_skill_effect_value("attack_twice_on_attack")),
        )
        if extra_attack_rate and self.random.random() * 100 < extra_attack_rate:
            damage *= 2
        return damage, critical

    def _player_hit_chance(
        self,
        definition: MonsterDefinition,
        monster_evasion: int,
        dexterity: int | None = None,
    ) -> int:
        """Scale authored evasion against level and dexterity without a 35% floor trap."""
        effective_dexterity = max(
            0,
            self.character.ap_dex if dexterity is None else dexterity,
        )
        precision = max(
            100,
            self.character.level * 100 + effective_dexterity * 10,
        )
        evasion = max(0, monster_evasion)
        evasion_penalty = round(evasion * 35 / max(1, evasion + precision))
        level_penalty = max(0, definition.level - self.character.level) * 2
        dexterity_bonus = min(
            10,
            effective_dexterity // max(1, self.character.level * 20),
        )
        return max(
            55,
            min(98, 95 - evasion_penalty - level_penalty + dexterity_bonus),
        )

    def _roll_combat_rate(self, value: int) -> bool:
        """Roll original per-mille combat stats, capped at the game's 50 percent limit."""
        chance = min(self.COMBAT_RATE_CAP, max(0, value))
        return self.random.randrange(self.COMBAT_RATE_SCALE) < chance

    def _attack_skill_id(self, read_str: str) -> int:
        """Read the skill ID from either the animation or impact phase."""
        if read_str.startswith(f"{op(ClientOpcode.PLAYER_ATTACK)}:"):
            fields = self._request_fields(read_str, ClientOpcode.PLAYER_ATTACK)
            return self._safe_int(fields[8], 0) if len(fields) > 8 else 0
        attack_opcodes = (
            ClientOpcode.MOB_ATTACK,
            ClientOpcode.CLOSE_RANGE_ATTACK,
            ClientOpcode.RANGED_ATTACK,
            ClientOpcode.MAGIC_ATTACK,
        )
        attack_opcode = next(
            (
                opcode
                for opcode in attack_opcodes
                if read_str.startswith(f"{op(opcode)}:")
            ),
            None,
        )
        if attack_opcode is not None:
            fields = self._request_fields(read_str, attack_opcode)
            if len(fields) > 9:
                return self._safe_int(fields[9], 0)
            return self._safe_int(fields[6], 0) if len(fields) > 6 else 0
        return 0

    def _resolve_attack_skill(
        self,
        read_str: str,
    ) -> tuple[SkillState | None, SkillDefinition | bool | None]:
        """Return the server-owned skill state, using False to reject forged casts."""
        skill_id = self._attack_skill_id(read_str)
        if skill_id <= 0:
            return None, None
        skill_state = self.store.state.skills.get(skill_id)
        skill_definition = GAME_DATA_CATALOG.get_skill_definition(skill_id)
        if skill_state is None or skill_definition is None:
            opcode = read_str.split(":", 1)[0]
            print(
                f"[combat] rejected skill account={self.account_name or '-'} "
                f"character={self.character.character_id} opcode={opcode} "
                f"skill={skill_id} learned={skill_state is not None} "
                f"defined={skill_definition is not None}",
                flush=True,
            )
            # Native Flash emits both an animation packet and an impact packet for
            # some skills. Keep the diagnostic for both phases, but do not stack
            # the same yellow rejection text twice on the player's screen.
            now = time.monotonic()
            last_skill_id, last_notice_at = getattr(
                self,
                "_last_missing_skill_notice",
                (0, 0.0),
            )
            if skill_id != last_skill_id or now - last_notice_at >= 1.0:
                self._send_system_chat("这个技能还没有学习。")
                self._last_missing_skill_notice = (skill_id, now)
            return None, False
        return skill_state, skill_definition

    def _attack_monster_target_ids(self, read_str: str) -> list[int]:
        """Read only the protocol fields that actually contain monster IDs."""
        if read_str.startswith(f"{op(ClientOpcode.PLAYER_ATTACK)}:"):
            fields = self._request_fields(read_str, ClientOpcode.PLAYER_ATTACK)
            raw_targets = fields[13] if len(fields) > 13 else "-"
        else:
            attack_opcodes = (
                ClientOpcode.MOB_ATTACK,
                ClientOpcode.CLOSE_RANGE_ATTACK,
                ClientOpcode.RANGED_ATTACK,
                ClientOpcode.MAGIC_ATTACK,
            )
            attack_opcode = next(
                (
                    opcode
                    for opcode in attack_opcodes
                    if read_str.startswith(f"{op(opcode)}:")
                ),
                None,
            )
            if attack_opcode is None:
                return []
            fields = self._request_fields(read_str, attack_opcode)
            # Full AttackInfo packets keep targets at index 12. Retain the
            # one-field shorthand used by local diagnostics and regression tests.
            raw_targets = fields[12] if len(fields) > 12 else (
                fields[0] if len(fields) == 1 else "-"
            )

        target_ids: list[int] = []
        seen: set[int] = set()
        for raw_target in str(raw_targets).split("@"):
            # Ruffle text packets may retain per-target hit metadata after '&'.
            object_id = self._safe_int(
                re.split(r"[&*]", raw_target, maxsplit=1)[0],
                -1,
            )
            if object_id >= 0 and object_id not in seen:
                seen.add(object_id)
                target_ids.append(object_id)
        return target_ids

    def _resolve_attack_targets(
        self,
        read_str: str,
        definition: SkillDefinition | None = None,
    ) -> list[MonsterState]:
        """Resolve every unique living monster ID from the attack payload in stable order."""
        targets: list[MonsterState] = []
        now = time.monotonic()
        skill_id = definition.skill_id if definition is not None else self._attack_skill_id(
            read_str
        )
        object_ids = self._attack_monster_target_ids(read_str)
        selected_cast_id: int | None = None
        if definition is not None and definition.multi_target:
            cast_claims = [
                claim
                for object_id in object_ids
                for claim in self.pending_monster_hits.get(object_id, ())
                if claim.expires_at > now and claim.skill_id == skill_id
            ]
            if not cast_claims:
                cast_claims = [
                    claim
                    for claims in self.pending_monster_hits.values()
                    for claim in claims
                    if claim.expires_at > now and claim.skill_id == skill_id
                ]
            if cast_claims:
                selected_claim = min(
                    cast_claims,
                    key=lambda claim: (claim.created_at, claim.cast_id),
                )
                selected_cast_id = selected_claim.cast_id
                object_ids.extend(
                    object_id
                    for object_id, claims in self.pending_monster_hits.items()
                    if object_id not in object_ids
                    and any(
                        claim.skill_id == skill_id
                        and claim.expires_at > now
                        and claim.cast_id == selected_cast_id
                        for claim in claims
                    )
                )

        for object_id in object_ids:
            monster = self.monsters.get(object_id)
            if monster is None or monster.hp <= 0:
                continue
            monster_x, monster_y = self._monster_render_position(monster)
            maximum_distance = (
                definition.effect_range(
                    self._effective_skill_level(
                        self.store.state.skills.get(definition.skill_id)
                    )
                )
                if definition is not None
                and self.store.state.skills.get(definition.skill_id) is not None
                else self.PLAYER_ATTACK_DISTANCE
            )
            if definition is None or not definition.multi_target:
                maximum_distance += self.PLAYER_ATTACK_SYNC_TOLERANCE
            claims = [
                claim
                for claim in self.pending_monster_hits.get(object_id, ())
                if claim.expires_at > now
            ]
            matching_claim = next(
                (
                    claim
                    for claim in claims
                    if claim.skill_id == skill_id
                    and (
                        selected_cast_id is None
                        or claim.cast_id == selected_cast_id
                    )
                ),
                None,
            )
            cast_claimed = matching_claim is not None
            if selected_cast_id is not None and not cast_claimed:
                # Once an AOE cast snapshot exists, impact-time movement cannot
                # add a monster that was outside the authored radius at cast time.
                continue
            training_target = (
                self.active_copy_id == self.XIULIAN_COPY_ID
                and self.character.map_id == self.XIULIAN_MAP_ID
                and object_id == self.XIULIAN_MONSTER_OBJECT_ID
            )
            if (
                not training_target
                and not cast_claimed
                and (monster_x - self.x) ** 2 + (monster_y - self.y) ** 2
                > maximum_distance**2
            ):
                continue
            targets.append(monster)
            if matching_claim is not None:
                claims.remove(matching_claim)
                if claims:
                    self.pending_monster_hits[object_id] = claims
                else:
                    self.pending_monster_hits.pop(object_id, None)
        return targets

    def handle_take_damage(self, read_str: str) -> None:
        """Ignore client hit claims; server-scheduled monster attacks settle damage."""

    def _is_dead(self) -> bool:
        """Use persisted HP as the single authority for the local death state."""
        return self.character.hp <= 0

    def _is_pvp_death_penalty_exempt(
        self, killer: FakeFlashSession | None = None
    ) -> bool:
        """Keep battle instances and authored no-penalty maps out of world PK penalties."""
        if (
            self.war_battle_active
            or self.war_3v3_match_id > 0
            or self.muye_battle_team in (1, 2)
            or self.local_pk_opponent_id > 0
            or self.arena_opponent is not None
        ):
            return True
        if killer is None:
            return False
        raw_maps = GAME_DATA_CATALOG.pvp_open_config().get("unprotectedMaps")
        unprotected_maps = {
            self._safe_int(value, -1)
            for value in raw_maps.values()
        } if isinstance(raw_maps, dict) else set()
        return self.character.map_id in unprotected_maps

    def _add_player_kill_crime(self, victim: FakeFlashSession) -> None:
        """Apply the authored crime gain for a normal open-world player kill."""
        if victim._is_pvp_death_penalty_exempt(self):
            return
        rules = GAME_DATA_CATALOG.pvp_open_config().get("crime")
        if not isinstance(rules, dict):
            return
        gain = max(0, self._safe_int(rules.get("crimeAddByPlayer"), 0))
        if gain:
            self._change_crime(gain)

    def _apply_death_durability_loss(self) -> list[InventoryItem]:
        """Roll normal durability loss independently for each authored equipment slot."""
        durability = GAME_DATA_CATALOG.get_equipment_system_config("naijiu")
        probability = max(0, min(100, self._safe_int(durability.get("deathLoseProb"), 0)))
        repairs = durability.get("repair")
        if probability <= 0 or not isinstance(repairs, dict):
            return []
        changed: list[InventoryItem] = []
        with self.store.lock:
            for item in self.store.state.inventory.values():
                if item.slot >= 0 or item.max_endure < 0 or item.endure <= 0:
                    continue
                definition = GAME_DATA_CATALOG.get_equipment_definition(item.item_id)
                row = (
                    repairs.get(f"stage{definition.stage}")
                    if definition is not None
                    else None
                )
                loss = (
                    max(0, self._safe_int(row.get("normalLose"), 0))
                    if isinstance(row, dict)
                    else 0
                )
                if loss <= 0 or self.random.randrange(100) >= probability:
                    continue
                item.endure = max(0, item.endure - loss)
                changed.append(item)
            if changed:
                self.store.save()
        return changed

    @staticmethod
    def _crime_drop_range(tier: dict[str, Any]) -> tuple[int, int]:
        """Parse GameData's inclusive `2-3` style item-drop range."""
        values = str(tier.get("dropCnt", "0-0")).split("-", 1)
        try:
            minimum = max(0, int(values[0]))
            maximum = max(minimum, int(values[-1]))
        except (TypeError, ValueError):
            return 0, 0
        return minimum, maximum

    def _drop_crime_inventory_items(self, tier: dict[str, Any]) -> list[DropState]:
        """Drop one unit from distinct eligible, unbound, non-quest bag entries."""
        minimum, maximum = self._crime_drop_range(tier)
        if maximum <= 0:
            return []
        inventory = self.store.state.inventory
        eligible = [
            item
            for item in inventory.values()
            if item.slot > 0
            and item.quantity > 0
            and item.can_trade
            and (
                (definition := GAME_DATA_CATALOG.get_item_definition(item.item_id))
                is not None
                and definition.section != "RenWuWuPin"
            )
        ]
        count = min(len(eligible), self.random.randint(minimum, maximum))
        if count <= 0:
            return []
        selected = self.random.sample(eligible, count)
        changed_stacks: list[InventoryItem] = []
        removed_slots: list[int] = []
        drops: list[DropState] = []
        drop_batch_positions: list[tuple[int, int]] = []
        with self.store.lock:
            for index, item in enumerate(selected):
                is_equipment = GAME_DATA_CATALOG.is_equipment_item(item.item_id)
                snapshot = replace(item, slot=0, quantity=1) if is_equipment else None
                item.quantity -= 1
                if item.quantity <= 0:
                    inventory.pop(item.slot, None)
                    removed_slots.append(item.slot)
                else:
                    changed_stacks.append(item)
                object_id = (
                    self.hub.allocate_drop_id(self)
                    if self.hub is not None
                    else self.next_drop_object_id
                )
                if self.hub is None:
                    self.next_drop_object_id += 1
                drop_x, drop_y, drop_foothold = self._next_drop_position(
                    self.x,
                    self.y,
                    self.character.foothold,
                    batch_positions=drop_batch_positions,
                )
                drop = DropState(
                    object_id=object_id,
                    item_id=item.item_id,
                    x=drop_x,
                    y=drop_y,
                    quantity=1,
                    aptitude=item.aptitude,
                    inventory_item=snapshot,
                    foothold=drop_foothold,
                )
                self.drops[object_id] = drop
                drops.append(drop)
            self.store.save()
        for slot in removed_slots:
            self._send_inventory_clear(slot, InventoryType.BAG)
        for item in changed_stacks:
            self._send_inventory_update(item, from_drop=0)
        for drop in drops:
            self._send_drop(drop)
        self._refresh_all_original_quests()
        return drops

    def _fragment_crime_equipment(
        self, tier: dict[str, Any]
    ) -> InventoryItem | None:
        """Mark one recoverable ordinary equipped item as broken at the authored rate."""
        probability = max(
            0, min(100, self._safe_int(tier.get("fragmentProb"), 0))
        )
        if probability <= 0 or self.random.randrange(100) >= probability:
            return None
        candidates = [
            item
            for item in self.store.state.inventory.values()
            if -12 <= item.slot <= -1
            and item.max_endure >= 0
            and item.crash_time <= 0
            and str(item.item_id).zfill(8)[2:4] != "21"
        ]
        if not candidates:
            return None
        item = self.random.choice(candidates)
        with self.store.lock:
            item.crash_time += 1
            self.store.save()
        return item

    def _settle_death_penalties(
        self, killer: FakeFlashSession | None = None
    ) -> None:
        """Settle one death edge exactly once from current GameData rules."""
        if self.death_penalty_applied:
            return
        self.death_penalty_applied = True
        if self._is_pvp_death_penalty_exempt(killer):
            return
        changed_equipment = self._apply_death_durability_loss()
        tier = (
            GAME_DATA_CATALOG.crime_tier_config(self.character.crime)
            if killer is not None
            else None
        )
        dropped: list[DropState] = []
        fragmented: InventoryItem | None = None
        if tier is not None:
            dropped = self._drop_crime_inventory_items(tier)
            fragmented = self._fragment_crime_equipment(tier)
        refresh_items = {item.slot: item for item in changed_equipment}
        if fragmented is not None:
            refresh_items[fragmented.slot] = fragmented
        for item in refresh_items.values():
            self._refresh_inventory_item(item)
        if refresh_items:
            self._clamp_resources_after_equipment_change()
            self._send_all_stats()
        if changed_equipment:
            self._send_character_notice(
                f"死亡惩罚：{len(changed_equipment)} 件装备损失耐久"
            )
        if dropped:
            self._send_character_notice(
                f"罪恶惩罚：掉落 {len(dropped)} 件非绑定物品"
            )
        if fragmented is not None:
            definition = GAME_DATA_CATALOG.get_item_definition(fragmented.item_id)
            name = definition.name if definition is not None else "未知物品"
            self._send_character_notice(f"罪恶惩罚：{name} 已粉碎")

    def _send_player_dead_box(
        self, killer: FakeFlashSession | None = None
    ) -> None:
        """Open Flash's original return-map/original-position revive window."""
        now = time.monotonic()
        if not self.death_started_at:
            self._settle_death_penalties(killer)
            self.death_started_at = now
            self.auto_return_revive_at = now + self.REVIVE_WINDOW_SECONDS
            self.death_map_id = self.character.map_id
            self.death_position = (self.x, self.y)
        remaining_seconds = max(1, int(self.auto_return_revive_at - now + 0.999))
        item_requirement = (
            0
            if self.character.level < self.FREE_IN_PLACE_REVIVE_BELOW_LEVEL
            else 1
        )
        # UPDATE_STATS drives the local DIE action. PLAYER_HP preserves the
        # original server's world-state packet immediately before this dialog.
        self.send_text(
            f"{op(ServerOpcode.PLAYER_HP)}:{self.character.character_id}:"
            f"{self._current_max_hp()}:0"
        )
        self.send_text(
            f"{op(ServerOpcode.PLAYER_DEAD_BOX)}:1:{remaining_seconds}:"
            f"{item_requirement}"
        )

    def handle_make_alive(self, read_str: str) -> None:
        """Start the original in-place countdown or revive at the return map."""
        if not self._is_dead():
            return
        fields = self._request_fields(read_str, ClientOpcode.MAKE_ALIVE)
        if not fields:
            return
        try:
            revive_mode = ReviveMode(self._safe_int(fields[0], -1))
        except ValueError:
            return
        if revive_mode == ReviveMode.RETURN_TO_MAP:
            self._complete_revive(revive_mode)
            return
        if self.pending_in_place_revive_at:
            return
        requested_item_id = self._safe_int(fields[1], 0) if len(fields) > 1 else 0
        if requested_item_id not in (0, self.REVIVE_ITEM_ID):
            return
        if self.character.level >= self.FREE_IN_PLACE_REVIVE_BELOW_LEVEL:
            revive_item = next(
                (
                    item
                    for item in self.store.state.inventory.values()
                    if item.slot > 0
                    and item.item_id == self.REVIVE_ITEM_ID
                    and item.quantity > 0
                ),
                None,
            )
            if revive_item is None:
                return
            with self.store.lock:
                revive_item.quantity -= 1
                removed = revive_item.quantity == 0
                if removed:
                    del self.store.state.inventory[revive_item.slot]
                self.store.save()
            if removed:
                self._send_inventory_clear(revive_item.slot, InventoryType.BAG)
            else:
                self._send_inventory_update(revive_item, from_drop=0)
        now = time.monotonic()
        if not self.death_started_at:
            self.death_started_at = now
            self.death_map_id = self.character.map_id
            self.death_position = (self.x, self.y)
        self.pending_in_place_revive_at = now + self.IN_PLACE_REVIVE_SECONDS
        self.auto_return_revive_at = 0.0
        self.send_text(
            f"{op(ServerOpcode.PLAYER_DEAD_BOX)}:2:{self.IN_PLACE_REVIVE_SECONDS}"
        )

    def _tick_revive(self, now: float | None = None) -> None:
        """Complete server-authoritative five/10-second revive deadlines."""
        if not self._is_dead():
            self._clear_revive_state()
            return
        current_time = time.monotonic() if now is None else now
        if self.pending_in_place_revive_at:
            if current_time >= self.pending_in_place_revive_at:
                if self.pending_skill_revive_kind == "edo_control":
                    self._start_edo_tensei_control(
                        self.pending_skill_revive_controller_id
                    )
                else:
                    self._complete_revive(ReviveMode.IN_PLACE)
            return
        if self.auto_return_revive_at and current_time >= self.auto_return_revive_at:
            self._complete_revive(ReviveMode.RETURN_TO_MAP)

    def _complete_revive(self, revive_mode: ReviveMode) -> None:
        """Restore resources once and apply the selected authoritative destination."""
        return_map_id = (
            self.current_map.return_map_id
            if self.current_map is not None
            else DEFAULT_MAP_ID
        )
        with self.store.lock:
            self.character.hp = max(1, self._current_max_hp() * self.REVIVE_PERCENT // 100)
            self.character.mp = max(1, self._current_max_mp() * self.REVIVE_PERCENT // 100)
            if revive_mode == ReviveMode.IN_PLACE:
                if self.death_position is not None:
                    self.x, self.y = self.death_position
                self.character.x = self.x
                self.character.y = self.y
            self.store.save()
        self._clear_revive_state()
        self.last_combat_at = time.monotonic()
        self.last_recovery_at = self.last_combat_at
        self._send_stats({StatType.HP: self.character.hp, StatType.MP: self.character.mp})
        if (
            revive_mode == ReviveMode.RETURN_TO_MAP
            and self.muye_battle_team in (1, 2)
            and self.character.map_id == 507_000_000
        ):
            self._warp_to_map(
                507_000_000,
                "3" if self.muye_battle_team == 1 else "0",
            )
            return
        if revive_mode == ReviveMode.RETURN_TO_MAP:
            self._warp_to_map(return_map_id)

    def _clear_revive_state(self) -> None:
        """Drop session-only death deadlines after a completed or externally restored revive."""
        self.death_started_at = 0.0
        self.death_penalty_applied = False
        self.auto_return_revive_at = 0.0
        self.pending_in_place_revive_at = 0.0
        self.pending_skill_revive_kind = ""
        self.pending_skill_revive_controller_id = 0
        self.death_map_id = 0
        self.death_position = None

    def _flush_pending_monster_kills(self, now: float | None = None) -> None:
        """Finish delayed critical deaths after the client has played the knockback."""
        current = time.monotonic() if now is None else now
        due_ids = [
            object_id
            for object_id, due_at in self.pending_monster_kills.items()
            if due_at <= current
        ]
        for object_id in due_ids:
            self.pending_monster_kills.pop(object_id, None)
            monster = self.monsters.get(object_id)
            if monster is None or monster.hp > 0:
                continue
            self._send_visible(
                f"{op(ServerOpcode.KILL_MONSTER)}:{object_id}:"
                f"{op(MonsterRemovalAnimation.PLAY_DEATH)}"
            )

    def _handle_battlefield_monster_reward(
        self,
        monster: MonsterState,
        definition: MonsterDefinition,
    ) -> None:
        """Apply activity score/rewards and create globally unique relic drops."""
        if self.hub is None:
            return
        if self.character.map_id == 501_000_000:
            phase, _, season_key = self._artifact_war_phase()
            with self.hub.lock:
                self._prepare_artifact_war_season_locked(season_key, phase)
                state = self.hub.artifact_war
                if (
                    phase == "key"
                    and monster.template_id == 2_200_006
                    and not state.holder_id
                    and not state.ground_drop_id
                ):
                    drop = self._spawn_battle_item_drop(
                        16_000_030,
                        x=monster.x,
                        y=monster.y,
                        foothold=monster.foothold,
                    )
                    state.ground_drop_id = drop.object_id
                    self.hub.persist_artifact_war()
                elif (
                    phase == "artifact"
                    and monster.template_id == 2_200_012
                    and state.holder_id == self.character.character_id
                    and state.held_item_id == 16_000_030
                ):
                    self._remove_one_battle_item(16_000_030)
                    drop = self._spawn_battle_item_drop(
                        17_200_001,
                        x=monster.x,
                        y=monster.y,
                        foothold=monster.foothold,
                    )
                    state.holder_id = 0
                    state.holder_name = ""
                    state.held_item_id = 0
                    state.ground_drop_id = drop.object_id
                    self.hub.persist_artifact_war()

        if not self.war_battle_active:
            return
        score_gain = 25 if definition.boss else 2
        exp_gain = max(100, definition.level * (200 if definition.boss else 20))
        gold_gain = max(10, definition.level * (100 if definition.boss else 5))
        essence_gain = max(1, definition.level // (2 if definition.boss else 10))
        self._add_war_battle_gain(score_gain, exp_gain, gold_gain, essence_gain)
        relic_by_boss = {
            2_200_040: 17_200_001,
            2_200_041: 17_200_002,
            2_200_042: 17_200_003,
            2_200_043: 17_200_004,
        }
        item_id = relic_by_boss.get(monster.template_id)
        if item_id is None:
            return
        with self.hub.lock:
            relic = self.hub.war_relics[item_id]
            if relic.holder_id or relic.ground_drop_id:
                return
            drop = self._spawn_battle_item_drop(
                item_id,
                x=monster.x,
                y=monster.y,
                foothold=monster.foothold,
            )
            relic.ground_drop_id = drop.object_id
            relic.channel_id = self.war_battle_channel
            self.hub.persist_war_relics()

    def _roll_monster_money_value(self, monster_level: int, boss: bool) -> int:
        """Roll the snapshot-authored level band independently from item rewards."""
        level = max(1, int(monster_level))
        if boss:
            base = level * 15_000
            minimum = max(100_000, round(base * 0.8))
            maximum = max(minimum, max(100_000, round(base * 1.2)))
            return self.random.randint(
                minimum,
                maximum,
            )
        minimum = max(10, level * 4)
        return self.random.randint(minimum, minimum * 2)

    def _handle_monster_killed(
        self,
        monster: MonsterState,
        critical: bool = False,
    ) -> None:
        """Remove one monster, grant experience, generate money/items, and advance quests."""
        if self.arena_monster is monster and self.arena_opponent is not None:
            self.arena_opponent.hp = 0
            self._send_visible(
                f"{op(ServerOpcode.KILL_MONSTER)}:{monster.object_id}:"
                f"{op(MonsterRemovalAnimation.PLAY_DEATH)}"
            )
            self._finish_arena_battle(won=True)
            return
        if (
            self.active_copy_id == self.XIULIAN_COPY_ID
            and monster.object_id == self.XIULIAN_MONSTER_OBJECT_ID
        ):
            monster.hp = monster.max_hp
            monster.respawn_at = 0.0
            self._send_visible(
                f"{op(ServerOpcode.SHOW_MONSTER_HP)}:{monster.object_id}:100"
            )
            return
        if monster.respawn_at or monster.object_id in self.pending_monster_kills:
            return
        scheduled_monster_event = self._scheduled_monster_event_for_instance(
            monster
        )
        if (
            scheduled_monster_event is not None
            and self._transform_scheduled_monster_phase(
                monster,
                scheduled_monster_event[0],
                scheduled_monster_event[1],
            )
        ):
            return
        if monster.skill_statuses:
            self._cancel_monster_statuses(monster, tuple(monster.skill_statuses))
            monster.skill_statuses.clear()
        definition = GAME_DATA_CATALOG.get_monster_definition(monster.template_id)
        tower_enemy = self.character.map_id == self.TOWER_MAP_ID
        if not tower_enemy:
            self._record_world_boss_kill(monster)
        self._handle_battlefield_monster_reward(monster, definition)
        if definition.boss and not tower_enemy:
            self._clear_boss_teleport_locks_after_kill(monster)
        self._reduce_crime_for_monster(definition.level)
        respawn_delay = self._monster_respawn_delay(monster, definition)
        monster.respawn_at = time.monotonic() + respawn_delay
        if self.hub is not None and not tower_enemy:
            self.hub.persist_boss_respawn(
                self,
                monster,
                respawn_delay,
                respawn_at_epoch=(
                    self._scheduled_boss_next_spawn_epoch(monster.template_id)
                    if not math.isfinite(respawn_delay)
                    else None
                ),
            )
        if any(
            monster.template_id == template_id
            for _, template_id in self.WAVE_MEMORIAL_BOSS_SPECS
        ):
            self._refresh_wave_memorial_music_config()
        monster.target_character_id = 0
        monster.engaged_character_ids.clear()
        if critical and not definition.boss:
            # AbstractSkillEffect.as applies the original x/y knockback when a fatal
            # hit carries bsk=true. Delay the kill packet so die() does not zero it.
            self.pending_monster_kills[monster.object_id] = (
                time.monotonic() + self.CRITICAL_KILL_DELAY_SECONDS
            )
        else:
            self._send_visible(
                f"{op(ServerOpcode.KILL_MONSTER)}:{monster.object_id}:"
                f"{op(MonsterRemovalAnimation.PLAY_DEATH)}"
            )
        self._advance_lianzhan_kill()
        character_experience = self._monster_experience_reward(monster.experience)
        self._grant_experience(character_experience, apply_item_effect=False)
        pet_experience = max(1, int(character_experience * 1.5))
        for pet in self.store.state.pets.values():
            if pet.position in {
                op(PetPosition.ATTACHED),
                op(PetPosition.ATTACKING),
            }:
                self._grant_pet_experience(pet, pet_experience)
        self._trigger_editor_events(
            "击杀怪物",
            {
                "monster_id": monster.template_id,
                "monster_level": definition.level,
                "is_boss": definition.boss and not tower_enemy,
            },
        )
        if (
            definition.boss
            and not tower_enemy
            and self.active_copy_id is None
            and self.active_hero_copy_id is None
        ):
            self._absorb_lunhuiyan_soul(monster.object_id, 15)
        self._grant_party_kill_credit(monster)
        self._record_hero_copy_kill(monster)
        self._record_copy_kill()
        self._check_tower_clear()
        monster_event = (
            scheduled_monster_event[0]
            if scheduled_monster_event is not None
            else next(
                (
                    event
                    for event in GAME_DATA_CATALOG.scheduled_monster_events()
                    if monster.template_id in event.get("mobs", ())
                ),
                None,
            )
        )
        wang_boss = next(
            (
                row
                for row in GAME_DATA_CATALOG.wang_boss_entries()
                if self._safe_int(row.get("mobId"), 0) == monster.template_id
            ),
            None,
        )
        primary_world_boss = self._is_primary_world_boss_instance(monster)
        announce_boss_kill = definition.boss and not tower_enemy and (
            primary_world_boss
            or monster_event is not None
            or wang_boss is not None
        )
        if definition.boss and not tower_enemy:
            self._advance_activity(1)
        if announce_boss_kill:
            if primary_world_boss:
                self._broadcast_rare_event(
                    f"{self.character.name}击杀了世界Boss【{definition.name}】！",
                    highlights=(self.character.name, definition.name),
                )
            elif monster_event is not None:
                message = str(monster_event.get("killNotice") or "")
                message = (
                    message.replace("#name#", self.character.name)
                    .replace("#mob#", definition.name)
                    .replace("#line#", str(self.line_id))
                )
                self._broadcast_rare_event(
                    message or f"{self.character.name}击败了事件Boss【{definition.name}】！",
                    highlights=(
                        self.character.name,
                        definition.name,
                        f"第{self.line_id}线",
                        f"{self.line_id}线",
                    ),
                )
            elif wang_boss is not None:
                self._broadcast_rare_event(
                    f"{self.character.name}击败了世界Boss【{definition.name}】！",
                    highlights=(self.character.name, definition.name),
                )
        if monster.template_id in {2_200_001, 2_200_055}:
            self._advance_activity(8)
        override_drop_rows = self._monster_drop_override_rows(monster.template_id)
        money_value = self._roll_monster_money_value(
            definition.level,
            definition.boss,
        )
        if self._is_wealth_mouse_template(monster.template_id):
            # Fate's wealth mouse is a special reward target. Keep the five
            # separate money drops, but use the authored Fate multiplier so its
            # total payout is visibly higher than an ordinary field mouse.
            if self.active_copy_id == 2 and self.character.map_id == 403_000_000:
                money_value = max(1, definition.level * 20)
            money_drop_count = 5
        elif definition.boss:
            money_drop_count = 1
        else:
            money_drop_count = 1
        if override_drop_rows is not None:
            money_drop_count = 0
        # Only drops produced by this defeated unit reserve positions against
        # each other. Another unit may use the same row coordinates.
        drop_batch_positions: list[tuple[int, int]] = []
        if override_drop_rows is not None:
            self._spawn_monster_drop_overrides(
                monster,
                override_drop_rows,
                drop_batch_positions,
            )
        for index in range(money_drop_count):
            drop_x, drop_y, drop_foothold = self._next_drop_position(
                monster.x,
                monster.y,
                monster.foothold,
                batch_positions=drop_batch_positions,
            )
            money_drop = DropState(
                object_id=(
                    self.hub.allocate_drop_id(self)
                    if self.hub is not None
                    else self.next_drop_object_id
                ),
                item_id=money_value,
                x=drop_x,
                y=drop_y,
                is_money=True,
                foothold=drop_foothold,
                owner_release_at=time.monotonic()
                + self.DERIVED_DROP_OWNER_PROTECTION_SECONDS,
                lifetime_seconds=self.DERIVED_DROP_LIFETIME_SECONDS,
            )
            if self.hub is None:
                self.next_drop_object_id += 1
            self.drops[money_drop.object_id] = money_drop
            self._send_drop(money_drop)

        item_drop_ids: set[int] = set()
        item_drop_target = (
            0
            if override_drop_rows is not None
            else 15 + self.random.randrange(6)
            if definition.boss
            else 1
        )
        for item_id, aptitude, quantity, can_trade in (
            ()
            if override_drop_rows is not None
            else self._roll_restoration_monster_drops(
                monster.template_id,
                monster=monster,
            )
        ):
            item_drop_ids.add(item_id)
            drop_x, drop_y, drop_foothold = self._next_drop_position(
                monster.x,
                monster.y,
                monster.foothold,
                batch_positions=drop_batch_positions,
            )
            item_drop = DropState(
                object_id=(
                    self.hub.allocate_drop_id(self)
                    if self.hub is not None
                    else self.next_drop_object_id
                ),
                item_id=item_id,
                x=drop_x,
                y=drop_y,
                quantity=quantity,
                aptitude=aptitude,
                can_trade=can_trade,
                foothold=drop_foothold,
                owner_release_at=time.monotonic()
                + self.DATABASE_DROP_OWNER_PROTECTION_SECONDS,
                lifetime_seconds=self.DATABASE_DROP_LIFETIME_SECONDS,
            )
            if self.hub is None:
                self.next_drop_object_id += 1
            self.drops[item_drop.object_id] = item_drop
            self._send_drop(item_drop)
            probability_ppm = self._restoration_monster_drop_probability_ppm(
                monster.template_id,
                item_id,
                monster=monster,
            )
            if (
                announce_boss_kill
                and self._should_announce_reward_probability(probability_ppm)
            ):
                reward_definition = GAME_DATA_CATALOG.get_item_definition(item_id)
                reward_name = (
                    reward_definition.name
                    if reward_definition is not None
                    else "稀有物品"
                )
                self._broadcast_rare_reward(
                    definition.name,
                    reward_name,
                    quantity,
                    source_kind="boss",
                )
        elite_reward_source = self._is_elite_reward_source(monster, definition)
        attempts = 0
        while len(item_drop_ids) < item_drop_target and attempts < max(8, item_drop_target * 8):
            attempts += 1
            item_roll = self._roll_monster_item_drop(
                monster.template_id,
                definition.level,
                definition.boss,
                elite=elite_reward_source,
            )
            if item_roll is None:
                continue
            item_id, aptitude, quantity = item_roll
            if item_id in item_drop_ids:
                continue
            item_drop_ids.add(item_id)
            drop_x, drop_y, drop_foothold = self._next_drop_position(
                monster.x,
                monster.y,
                monster.foothold,
                batch_positions=drop_batch_positions,
            )
            item_drop = DropState(
                object_id=(
                    self.hub.allocate_drop_id(self)
                    if self.hub is not None
                    else self.next_drop_object_id
                ),
                item_id=item_id,
                x=drop_x,
                y=drop_y,
                quantity=quantity,
                aptitude=aptitude,
                foothold=drop_foothold,
                owner_release_at=time.monotonic()
                + self.DERIVED_DROP_OWNER_PROTECTION_SECONDS,
                lifetime_seconds=self.DERIVED_DROP_LIFETIME_SECONDS,
            )
            if self.hub is None:
                self.next_drop_object_id += 1
            self.drops[item_drop.object_id] = item_drop
            self._send_drop(item_drop)
            reward_definition = GAME_DATA_CATALOG.get_item_definition(item_id)
            probability_ppm = self._semantic_monster_drop_probability_ppm(
                definition.level,
                definition.boss,
                item_id,
            )
            if (
                announce_boss_kill
                and self._should_announce_reward_probability(probability_ppm)
            ):
                reward_name = (
                    reward_definition.name
                    if reward_definition is not None
                    else "稀有物品"
                )
                self._broadcast_rare_reward(
                    definition.name,
                    reward_name,
                    quantity,
                    source_kind="boss",
                )

        # Original quests can count kills, capture pets, or request an item from this monster.
        for quest_id, progress in tuple(self.store.state.original_quests.items()):
            if QuestState(progress.state) != QuestState.ACTIVE:
                continue
            quest_definition = GAME_DATA_CATALOG.get_quest_definition(quest_id)
            if quest_definition is None:
                continue
            for objective in quest_definition.objectives:
                if objective.map_id and objective.map_id != self.character.map_id:
                    continue
                if (
                    objective.kind == QuestObjectiveKind.MONSTER
                    and objective.target_id == monster.template_id
                ):
                    self._advance_original_quest(
                        quest_definition,
                        QuestObjectiveKind.MONSTER,
                        monster.template_id,
                        1,
                        self.character.map_id,
                    )
                elif (
                    objective.kind == QuestObjectiveKind.PET
                    and objective.source_monster_id == monster.template_id
                ):
                    self._advance_original_quest(
                        quest_definition,
                        QuestObjectiveKind.PET,
                        objective.target_id,
                        1,
                        self.character.map_id,
                    )
                elif (
                    objective.kind == QuestObjectiveKind.ITEM
                    and objective.source_monster_id == monster.template_id
                ):
                    current_count = sum(
                        item.quantity
                        for item in self.store.state.inventory.values()
                        if item.item_id == objective.target_id
                    )
                    pending_count = sum(
                        drop.quantity
                        for drop in self.drops.values()
                        if not drop.is_money and drop.item_id == objective.target_id
                    )
                    if current_count + pending_count < objective.count:
                        drop_x, drop_y, drop_foothold = self._next_drop_position(
                            monster.x,
                            monster.y,
                            monster.foothold,
                            batch_positions=drop_batch_positions,
                        )
                        quest_drop = DropState(
                            object_id=(
                                self.hub.allocate_drop_id(self)
                                if self.hub is not None
                                else self.next_drop_object_id
                            ),
                            item_id=objective.target_id,
                            x=drop_x,
                            y=drop_y,
                            foothold=drop_foothold,
                            owner_release_at=time.monotonic()
                            + self.DATABASE_DROP_OWNER_PROTECTION_SECONDS,
                            lifetime_seconds=self.DATABASE_DROP_LIFETIME_SECONDS,
                        )
                        if self.hub is None:
                            self.next_drop_object_id += 1
                        self.drops[quest_drop.object_id] = quest_drop
                        self._send_drop(quest_drop)

        trial_just_completed = False
        with self.store.lock:
            quest = self.store.state.quest
            if QuestState(quest.state) == QuestState.ACTIVE:
                quest.kills = min(self.QUEST_TARGET_KILLS, quest.kills + 1)
                if quest.kills >= self.QUEST_TARGET_KILLS:
                    quest.state = int(QuestState.READY_TO_COMPLETE)
            progression = self.store.state.progression
            progression.total_monster_kills += 1
            if progression.trial_active:
                progression.trial_kills += 1
                progression.trial_best = max(progression.trial_best, progression.trial_kills)
                if progression.trial_kills >= 4:
                    progression.trial_active = False
                    trial_just_completed = True
                    self.store.state.money += 500
            self.store.save()
        self._send_npc_quest_status()
        if progression.trial_kills == 3 and progression.trial_active:
            self._send_system_chat("三波试炼完成，下一只怪物视为试炼首领。")
        elif trial_just_completed:
            self._grant_experience(500)
            self._send_stats({StatType.MONEY: self.store.state.money})
            self._send_system_chat("单人试炼通关：获得经验 500、金币 500，可回引导员处领取成就。")

        self._complete_active_pve_if_ready()

    def _grant_party_kill_credit(self, monster: MonsterState) -> None:
        """Share quest credit and assist experience with visible party members."""
        if self.hub is None:
            return
        party = self.hub.party_for(self.character.character_id)
        if party is None:
            return
        visible_ids = {
            peer.character.character_id
            for peer in self.hub.visible_peers(self)
        }
        for member in self.hub.party_sessions(party):
            if (
                member is self
                or member.character.character_id not in visible_ids
                or member._is_dead()
            ):
                continue
            member._grant_experience(
                member._monster_experience_reward(max(1, monster.experience // 2)),
                apply_item_effect=False,
            )
            member._advance_original_quests(
                QuestObjectiveKind.MONSTER,
                monster.template_id,
                1,
                member.character.map_id,
            )
            with member.store.lock:
                quest = member.store.state.quest
                if QuestState(quest.state) == QuestState.ACTIVE:
                    quest.kills = min(member.QUEST_TARGET_KILLS, quest.kills + 1)
                    if quest.kills >= member.QUEST_TARGET_KILLS:
                        quest.state = int(QuestState.READY_TO_COMPLETE)
                member.store.state.progression.total_monster_kills += 1
                member.store.save()
            member._send_npc_quest_status()

    def _roll_monster_item_drop(
        self,
        monster_template_id: int,
        monster_level: int,
        boss: bool,
        *,
        elite: bool = False,
    ) -> tuple[int, int, int] | None:
        """Roll a semantic item drop; money-only and ordinary no-drop outcomes are valid."""
        if 4_100_000 <= monster_template_id <= 4_100_012 and monster_template_id % 2 == 0:
            return None
        drop_config = EDITOR_RUNTIME.entity(
            "balance_rules",
            "monster_drops",
            BALANCE_DEFAULTS["monster_drops"],
        )
        drop_multiplier = self._monster_drop_rate_multiplier(drop_config)
        if not boss:
            rare_roll = self.random.randrange(1_000_000)
            rare_kind = ""
            cumulative_rate = 0
            for candidate_kind in ("spirit", "rouquan", "card", "skill", "fragment", "food"):
                minimum, maximum = NORMAL_RARE_DROP_RATE_LIMITS_PPM[candidate_kind]
                configured_value = drop_config.get(
                    NORMAL_RARE_DROP_RATE_FIELDS[candidate_kind]
                )
                if configured_value is None:
                    continue
                configured_rate = self._safe_int(
                    configured_value,
                    self._safe_int(
                        BALANCE_DEFAULTS["monster_drops"].get(
                            NORMAL_RARE_DROP_RATE_FIELDS[candidate_kind]
                        ),
                        minimum,
                    ),
                )
                base_rate = max(minimum, min(maximum, configured_rate))
                cumulative_rate += min(1_000_000, round(base_rate * drop_multiplier))
                if rare_roll < cumulative_rate:
                    rare_kind = candidate_kind
                    break
            if rare_kind:
                monster_name = GAME_DATA_CATALOG.get_monster_definition(
                    monster_template_id
                ).name
                rare_candidates = GAME_DATA_CATALOG.normal_rare_drop_candidates(
                    rare_kind,
                    monster_name,
                    monster_level,
                )
                if elite:
                    rare_candidates = tuple(
                        item_id
                        for item_id in rare_candidates
                        if GAME_DATA_CATALOG.is_elite_drop_eligible(item_id)
                    )
                if rare_candidates:
                    offset = self.random.randrange(len(rare_candidates))
                    return rare_candidates[offset], 2, 1
        pools = GAME_DATA_CATALOG.drop_candidates_by_kind(monster_level, boss)
        if not boss:
            base_normal_rate = max(
                0,
                min(
                    1_000_000,
                    self._safe_int(
                        drop_config.get("normalItemRatePerMillion"),
                        BALANCE_DEFAULTS["monster_drops"]["normalItemRatePerMillion"],
                    ),
                ),
            )
            normal_rate = min(1_000_000, round(base_normal_rate * drop_multiplier))
            if self.random.randrange(1_000_000) >= normal_rate:
                return None
        roll = self.random.randrange(100)
        if boss:
            kind = "consumable" if roll < 35 else "equipment" if roll < 90 else "skill"
        else:
            kind = "consumable" if roll < 56 else "equipment"
        candidates = pools.get(kind, ())
        if elite:
            candidates = tuple(
                item_id
                for item_id in candidates
                if GAME_DATA_CATALOG.is_elite_drop_eligible(item_id)
            )
        if not candidates:
            return None
        offset = self.random.randrange(len(candidates))
        item_id = candidates[(monster_template_id + offset) % len(candidates)]
        aptitude = 2
        if GAME_DATA_CATALOG.is_equipment_item(item_id):
            quality_roll = self.random.randrange(100)
            if boss:
                aptitude = (
                    1
                    if quality_roll < 15
                    else 2
                    if quality_roll < 45
                    else 3
                    if quality_roll < 75
                    else 4
                    if quality_roll < 95
                    else 5
                )
            elif elite:
                aptitude = 1 if quality_roll < 35 else 2 if quality_roll < 75 else 3 if quality_roll < 95 else 4
            else:
                aptitude = (
                    1
                    if quality_roll < 60
                    else 2
                    if quality_roll < 85
                    else 3
                    if quality_roll < 95
                    else 4
                    if quality_roll < 99
                    else 5
                )
        return item_id, aptitude, 1

    @staticmethod
    def _is_elite_reward_source(
        monster: MonsterState | None,
        definition: MonsterDefinition | None,
    ) -> bool:
        """Classify both random-affix and authored ``【精英】`` reward sources."""
        if monster is None or definition is None:
            return False
        return bool(monster.elite_affixes) or definition.name.startswith("【精英】")

    def _semantic_monster_drop_probability_ppm(
        self,
        monster_level: int,
        boss: bool,
        item_id: int,
    ) -> int:
        """Return the per-roll probability of one semantic drop, independent of value."""
        if not boss:
            return 1_000_000
        pools = GAME_DATA_CATALOG.drop_candidates_by_kind(monster_level, boss)
        category_rates = {
            "consumable": 35,
            "equipment": 55,
            "skill": 10,
        }
        probability_ppm = 0
        for kind, category_percent in category_rates.items():
            candidates = tuple(pools.get(kind, ()))
            if not candidates:
                continue
            occurrences = candidates.count(item_id)
            if occurrences <= 0:
                continue
            probability_ppm += round(
                category_percent * 10_000 * occurrences / len(candidates)
            )
        return min(1_000_000, probability_ppm)

    def _special_monster_drop_rows(self, monster_template_id: int) -> tuple[dict[str, Any], ...]:
        """Read one hot-reloaded fixed-item or dynamic-pool special drop table."""
        config = EDITOR_RUNTIME.entity(
            "balance_rules",
            "monster_drops",
            BALANCE_DEFAULTS["monster_drops"],
        )
        tables = config.get("specialDrops")
        rows = tables.get(str(monster_template_id), ()) if isinstance(tables, dict) else ()
        return tuple(row for row in rows if isinstance(row, dict)) if isinstance(rows, list) else ()

    def _monster_drop_override_rows(
        self,
        monster_template_id: int,
    ) -> tuple[dict[str, Any], ...] | None:
        """Return an enabled full replacement, distinguishing it from no override."""
        config = EDITOR_RUNTIME.entity(
            "balance_rules",
            "monster_drops",
            BALANCE_DEFAULTS["monster_drops"],
        )
        tables = config.get("dropOverrides")
        if not isinstance(tables, dict) or str(monster_template_id) not in tables:
            return None
        rows = tables.get(str(monster_template_id))
        if not isinstance(rows, list):
            return ()
        return tuple(row for row in rows if isinstance(row, dict))

    def _spawn_monster_drop_overrides(
        self,
        monster: MonsterState,
        rows: tuple[dict[str, Any], ...],
        drop_batch_positions: list[tuple[int, int]],
    ) -> None:
        """Spawn exact editor-authored replacement rows without global multipliers."""
        for row in rows:
            probability = max(
                0,
                min(10_000, self._safe_int(row.get("prob10000"), 0)),
            )
            if probability <= 0:
                continue
            roll = 0 if probability >= 10_000 else self.random.randrange(10_000)
            if roll >= probability:
                continue

            kind = str(row.get("kind") or "item").strip().lower()
            drop_x, drop_y, drop_foothold = self._next_drop_position(
                monster.x,
                monster.y,
                monster.foothold,
                batch_positions=drop_batch_positions,
            )
            object_id = (
                self.hub.allocate_drop_id(self)
                if self.hub is not None
                else self.next_drop_object_id
            )
            if self.hub is None:
                self.next_drop_object_id += 1

            if kind == "money":
                amount = max(1, self._safe_int(row.get("count"), 1))
                drop = DropState(
                    object_id=object_id,
                    item_id=amount,
                    x=drop_x,
                    y=drop_y,
                    is_money=True,
                    foothold=drop_foothold,
                    owner_release_at=time.monotonic()
                    + self.DERIVED_DROP_OWNER_PROTECTION_SECONDS,
                    lifetime_seconds=self.DERIVED_DROP_LIFETIME_SECONDS,
                )
            else:
                pool = str(row.get("pool") or "").strip()
                if pool:
                    candidates = GAME_DATA_CATALOG.special_drop_candidates(
                        pool,
                        monster.template_id,
                    )
                    if not candidates:
                        continue
                    item_id = candidates[self.random.randrange(len(candidates))]
                else:
                    item_id = self._safe_int(row.get("itemId"), 0)
                    if GAME_DATA_CATALOG.get_item_definition(item_id) is None:
                        continue
                drop = DropState(
                    object_id=object_id,
                    item_id=item_id,
                    x=drop_x,
                    y=drop_y,
                    quantity=max(1, self._safe_int(row.get("count"), 1)),
                    aptitude=max(1, self._safe_int(row.get("aptitude"), 2)),
                    can_trade=not bool(row.get("bind", False)),
                    foothold=drop_foothold,
                    owner_release_at=time.monotonic()
                    + self.DATABASE_DROP_OWNER_PROTECTION_SECONDS,
                    lifetime_seconds=self.DATABASE_DROP_LIFETIME_SECONDS,
                )
            self.drops[drop.object_id] = drop
            self._send_drop(drop)
            print(
                "[monster-drop-override] "
                + json.dumps(
                    {
                        "monsterId": monster.template_id,
                        "kind": kind,
                        "itemId": 0 if drop.is_money else drop.item_id,
                        "amount": drop.item_id if drop.is_money else drop.quantity,
                        "prob10000": probability,
                        "roll": roll,
                    },
                    ensure_ascii=False,
                    separators=(",", ":"),
                ),
                flush=True,
            )

    def _fixed_monster_item_drops(
        self,
        monster_template_id: int,
    ) -> tuple[tuple[int, int, int], ...]:
        """Return only explicitly guaranteed special drops for compatibility callers."""
        return tuple(
            (
                self._safe_int(row.get("itemId"), 0),
                max(1, self._safe_int(row.get("aptitude"), 2)),
                max(1, self._safe_int(row.get("count"), 1)),
            )
            for row in self._special_monster_drop_rows(monster_template_id)
            if self._safe_int(row.get("prob10000"), -1) >= 10_000
            and GAME_DATA_CATALOG.get_item_definition(
                self._safe_int(row.get("itemId"), 0)
            ) is not None
        )

    def _roll_restoration_monster_drops(
        self,
        monster_template_id: int,
        *,
        monster: MonsterState | None = None,
    ) -> tuple[tuple[int, int, int, bool], ...]:
        """Roll configured special sources, including weighted group guarantees."""
        drops: list[tuple[int, int, int, bool]] = []
        selection_groups: dict[str, list[dict[str, Any]]] = {}
        drop_multiplier: float | None = None
        monster_definition = GAME_DATA_CATALOG.get_monster_definition(
            monster_template_id
        )
        elite_reward_source = self._is_elite_reward_source(monster, monster_definition)
        for row in self._special_monster_drop_rows(monster_template_id):
            if (
                str(row.get("scope") or "").strip() == "primary_world_boss"
                and (monster is None or not self._is_primary_world_boss_instance(monster))
            ):
                continue
            raw_probability = row.get("prob10000")
            if raw_probability is None:
                continue
            base_probability = max(
                0,
                min(10_000, self._safe_int(raw_probability, 0)),
            )
            if base_probability <= 0:
                continue
            pool = str(row.get("pool") or "").strip()
            candidates = (
                GAME_DATA_CATALOG.special_drop_candidates(pool, monster_template_id)
                if pool
                else ()
            )
            if elite_reward_source and pool:
                candidates = tuple(
                    item_id
                    for item_id in candidates
                    if GAME_DATA_CATALOG.is_elite_drop_eligible(item_id)
                )
            configured_item_id = self._safe_int(row.get("itemId"), 0)
            if not pool and GAME_DATA_CATALOG.get_item_definition(configured_item_id) is None:
                continue
            if (
                elite_reward_source
                and not pool
                and not GAME_DATA_CATALOG.is_elite_drop_eligible(configured_item_id)
            ):
                continue
            if pool and not candidates:
                continue
            if base_probability >= 10_000:
                probability = 10_000
            else:
                if drop_multiplier is None:
                    drop_multiplier = self._monster_drop_rate_multiplier()
                probability = min(10_000, round(base_probability * drop_multiplier))
            roll = 0 if probability >= 10_000 else self.random.randrange(10_000)
            triggered = roll < probability
            item_id = configured_item_id
            if triggered and pool:
                item_id = candidates[self.random.randrange(len(candidates))]
            selection_group = str(
                row.get("selection_group") or row.get("selectionGroup") or ""
            ).strip()
            group_entry = {
                "row": row,
                "pool": pool,
                "candidates": candidates,
                "configured_item_id": configured_item_id,
                "triggered": triggered,
            }
            if selection_group:
                selection_groups.setdefault(selection_group, []).append(group_entry)
            print(
                "[restoration-drop] "
                + json.dumps(
                    {
                        "monsterId": monster_template_id,
                        "itemId": item_id,
                        "pool": pool,
                        "baseProb10000": base_probability,
                        "prob10000": probability,
                        "roll": roll,
                        "triggered": triggered,
                        "source": str(row.get("source") or "editor"),
                    },
                    ensure_ascii=False,
                    separators=(",", ":"),
                ),
                flush=True,
            )
            if triggered:
                drops.append(
                    (
                        item_id,
                        max(1, self._safe_int(row.get("aptitude"), 2)),
                        max(1, self._safe_int(row.get("count"), 1)),
                        not bool(row.get("bind", False)),
                    )
                )
        for selection_group, entries in selection_groups.items():
            minimum_drops = max(
                (
                    max(
                        0,
                        self._safe_int(
                            entry["row"].get(
                                "group_min_drops",
                                entry["row"].get("groupMinDrops", 0),
                            ),
                            0,
                        ),
                    )
                    for entry in entries
                ),
                default=0,
            )
            minimum_drops = min(len(entries), minimum_drops)
            triggered_count = sum(bool(entry["triggered"]) for entry in entries)
            while triggered_count < minimum_drops:
                fallback_entries = [
                    entry
                    for entry in entries
                    if not entry["triggered"]
                    and self._safe_int(
                        entry["row"].get(
                            "fallback_weight",
                            entry["row"].get("fallbackWeight", 0),
                        ),
                        0,
                    )
                    > 0
                ]
                if not fallback_entries:
                    break
                total_weight = sum(
                    self._safe_int(
                        entry["row"].get(
                            "fallback_weight",
                            entry["row"].get("fallbackWeight", 0),
                        ),
                        0,
                    )
                    for entry in fallback_entries
                )
                ticket = self.random.randrange(total_weight)
                chosen = fallback_entries[-1]
                for entry in fallback_entries:
                    ticket -= self._safe_int(
                        entry["row"].get(
                            "fallback_weight",
                            entry["row"].get("fallbackWeight", 0),
                        ),
                        0,
                    )
                    if ticket < 0:
                        chosen = entry
                        break
                chosen["triggered"] = True
                row = chosen["row"]
                candidates = chosen["candidates"]
                item_id = chosen["configured_item_id"]
                if chosen["pool"]:
                    item_id = candidates[self.random.randrange(len(candidates))]
                quantity = max(1, self._safe_int(row.get("count"), 1))
                drops.append(
                    (
                        item_id,
                        max(1, self._safe_int(row.get("aptitude"), 2)),
                        quantity,
                        not bool(row.get("bind", False)),
                    )
                )
                triggered_count += 1
                print(
                    "[restoration-drop-fallback] "
                    + json.dumps(
                        {
                            "monsterId": monster_template_id,
                            "itemId": item_id,
                            "selectionGroup": selection_group,
                            "groupMinDrops": minimum_drops,
                            "fallbackWeight": self._safe_int(
                                row.get(
                                    "fallback_weight",
                                    row.get("fallbackWeight", 0),
                                ),
                                0,
                            ),
                            "source": str(row.get("source") or "editor"),
                        },
                        ensure_ascii=False,
                        separators=(",", ":"),
                    ),
                    flush=True,
                )
        insect_drop = self._roll_hero_copy_insect_drop(monster_template_id)
        if insect_drop is not None:
            drops.append(insect_drop)
        return tuple(drops)

    def _restoration_monster_drop_probability_ppm(
        self,
        monster_template_id: int,
        item_id: int,
        *,
        monster: MonsterState | None = None,
    ) -> int:
        """Return the combined configured chance of one special Boss reward."""
        probability_ppm = 0
        drop_multiplier: float | None = None
        for row in self._special_monster_drop_rows(monster_template_id):
            if (
                str(row.get("scope") or "").strip() == "primary_world_boss"
                and (monster is None or not self._is_primary_world_boss_instance(monster))
            ):
                continue
            base_probability = max(
                0,
                min(10_000, self._safe_int(row.get("prob10000"), 0)),
            )
            if base_probability <= 0:
                continue
            if base_probability >= 10_000:
                effective_probability = 10_000
            else:
                if drop_multiplier is None:
                    drop_multiplier = self._monster_drop_rate_multiplier()
                effective_probability = min(
                    10_000,
                    round(base_probability * drop_multiplier),
                )
            pool = str(row.get("pool") or "").strip()
            if pool:
                candidates = GAME_DATA_CATALOG.special_drop_candidates(
                    pool,
                    monster_template_id,
                )
                if not candidates:
                    continue
                occurrences = candidates.count(item_id)
                if occurrences > 0:
                    probability_ppm += round(
                        effective_probability * 100 * occurrences / len(candidates)
                    )
                continue
            if self._safe_int(row.get("itemId"), 0) == item_id:
                probability_ppm += effective_probability * 100

        if (
            self.active_hero_copy_id is not None
            and monster_template_id == self.active_hero_boss_id
            and item_id in KUN_CHONG_ITEM_IDS
        ):
            definition = GAME_DATA_CATALOG.get_monster_definition(monster_template_id)
            if definition is not None and definition.boss and definition.level >= 40:
                config = EDITOR_RUNTIME.entity(
                    "balance_rules",
                    "monster_drops",
                    BALANCE_DEFAULTS["monster_drops"],
                )
                insect_probability = max(
                    0,
                    min(
                        10_000,
                        self._safe_int(config.get("heroCopyInsectRatePer10000"), 0),
                    ),
                )
                insect_probability = min(
                    10_000,
                    round(
                        insect_probability
                        * self._monster_drop_rate_multiplier(config)
                    ),
                )
                probability_ppm += round(
                    insect_probability * 100 / max(1, len(KUN_CHONG_ITEM_IDS))
                )
        return min(1_000_000, probability_ppm)

    def _roll_hero_copy_insect_drop(
        self, monster_template_id: int
    ) -> tuple[int, int, int, bool] | None:
        """Roll insects only for the final Boss of a level-40+ elite copy."""
        if (
            self.active_hero_copy_id is None
            or monster_template_id != self.active_hero_boss_id
        ):
            return None
        definition = GAME_DATA_CATALOG.get_monster_definition(monster_template_id)
        if not definition.boss or definition.level < 40:
            return None
        config = EDITOR_RUNTIME.entity(
            "balance_rules",
            "monster_drops",
            BALANCE_DEFAULTS["monster_drops"],
        )
        base_probability = max(
            0,
            min(
                10_000,
                self._safe_int(config.get("heroCopyInsectRatePer10000"), 0),
            ),
        )
        if base_probability <= 0:
            return None
        probability = min(
            10_000,
            round(base_probability * self._monster_drop_rate_multiplier(config)),
        )
        roll = 0 if probability >= 10_000 else self.random.randrange(10_000)
        triggered = roll < probability
        print(
            "[hero-copy-insect-drop] "
            + json.dumps(
                {
                    "copyId": self.active_hero_copy_id,
                    "monsterId": monster_template_id,
                    "monsterLevel": definition.level,
                    "baseProb10000": base_probability,
                    "prob10000": probability,
                    "roll": roll,
                    "triggered": triggered,
                    "source": "40407-elite-copy-boss-designed-rate-v1",
                },
                ensure_ascii=False,
                separators=(",", ":"),
            ),
            flush=True,
        )
        if not triggered:
            return None
        quality_roll = self.random.randrange(100)
        if definition.level >= 80:
            aptitude = (
                1
                if quality_roll < 25
                else 2
                if quality_roll < 60
                else 3
                if quality_roll < 90
                else 4
            )
        elif definition.level >= 60:
            aptitude = (
                1
                if quality_roll < 45
                else 2
                if quality_roll < 80
                else 3
                if quality_roll < 97
                else 4
            )
        else:
            aptitude = 1 if quality_roll < 70 else 2 if quality_roll < 95 else 3
        return self.random.choice(KUN_CHONG_ITEM_IDS), aptitude, 1, True

    def _monster_drop_rate_multiplier(self, config: dict[str, Any] | None = None) -> float:
        """Apply timed double-drop events once; fixed Boss rewards bypass this path."""
        monster_event, _ = self._active_double_gain()
        if not monster_event:
            return 1.0
        resolved = config or EDITOR_RUNTIME.entity(
            "balance_rules",
            "monster_drops",
            BALANCE_DEFAULTS["monster_drops"],
        )
        try:
            multiplier = float(resolved.get("doubleDropRateMultiplier", 2.0))
        except (TypeError, ValueError, OverflowError):
            multiplier = 2.0
        return max(1.0, min(10.0, multiplier))

    @staticmethod
    def _experience_required_for_level(level: int) -> int:
        """Return the original Flash current-level experience threshold."""
        if 0 < level < len(EXP_BY_LEVEL):
            return EXP_BY_LEVEL[level]
        return 0

    def _monster_experience_reward(self, amount: int) -> int:
        """Apply GameData's transform-card monster-experience percentage."""
        rate = max(0, self._equipped_attribute_bonus(EquipmentAttribute.MOB_EXP))
        rate += self._lianzhan_exp_rate()
        rate += self._bond_party_experience_rate()
        monster_event, _ = self._active_double_gain()
        if monster_event:
            config = EDITOR_RUNTIME.entity(
                "balance_rules",
                "monster_drops",
                BALANCE_DEFAULTS["monster_drops"],
            )
            try:
                multiplier = float(config.get("doubleExperienceMultiplier", 2.0))
            except (TypeError, ValueError, OverflowError):
                multiplier = 2.0
            event_bonus = max(0, round((min(10.0, multiplier) - 1.0) * 100))
            rate += event_bonus
            if self._has_active_vip():
                rate += event_bonus
        rate += self._active_gain_item_rate("exp")
        return max(1, round(amount * (100 + rate) / 100))

    def _bond_party_experience_rate(self) -> int:
        """Apply 同生共死 only for the real spouse in the same party and world."""
        if self.character.level < 30 or self.hub is None:
            return 0
        spouse = self._bond_partner_session()
        party = self.hub.party_for(self.character.character_id)
        if (
            spouse is None
            or party is None
            or spouse.character.character_id not in party.member_ids
            or spouse.character.map_id != self.character.map_id
            or spouse.line_id != self.line_id
            or spouse.copy_instance_id != self.copy_instance_id
        ):
            return 0
        return 30

    def _active_gain_item_rate(self, gain_name: str) -> int:
        now = int(time.time())
        return sum(
            self._safe_int(definition.parameters.get("rate"), 0)
            for item_id, expires_at in self.store.state.active_item_effects.items()
            if expires_at > now
            and (definition := GAME_DATA_CATALOG.get_item_definition(item_id)) is not None
            and definition.use_type == "shuangbei"
            and str(definition.parameters.get("name") or "") == gain_name
        )

    @staticmethod
    def _active_double_gain(now_epoch: float | None = None) -> tuple[bool, bool]:
        """Return monster/meditation double states from the formal recurring timetable."""
        monster_period, meditation_period = (
            FakeFlashSession._double_gain_activity_periods(now_epoch)
        )
        return monster_period[0], meditation_period[0]

    def _grant_experience(self, amount: int, *, apply_item_effect: bool = True) -> None:
        """Add experience, perform every crossed level-up, grow stats, and persist the result."""
        if amount <= 0:
            return
        experience_rate = 100 + (
            self._active_gain_item_rate("exp") if apply_item_effect else 0
        )
        amount = max(1, round(amount * experience_rate / 100))
        with self.store.lock:
            character = self.character
            starting_level = character.level
            character.exp += amount
            leveled_up = False
            while character.level < len(EXP_BY_LEVEL) - 1:
                required = self._experience_required_for_level(character.level)
                if required <= 0 or character.exp < required:
                    break
                character.exp -= required
                character.level += 1
                character.max_hp += 25
                character.max_mp += 10
                character.ap_atk += 1
                character.ap_def += 1
                character.ap_dex += 1
                character.ap_phy += 1
                character.remaining_ap += 4
                leveled_up = True
            if leveled_up:
                # Level-up restores the derived limits, including cultivation and attached pet.
                character.hp = self._current_max_hp()
                character.mp = self._current_max_mp()
            self.store.save()
        updates: dict[StatType, int] = {}
        if leveled_up:
            account = self.accounts.account_by_id(self.account_id) if self.account_id else None
            half_ring = int(account.get("bondHalfRingItem", 0)) if account else 0
            if half_ring:
                self._ensure_bond_skills(max(1, (half_ring // 10_000) % 10))
            updates.update(
                {
                    StatType.LEVEL: character.level,
                    StatType.HP: character.hp,
                    StatType.MP: character.mp,
                    StatType.AP_ATK: character.ap_atk,
                    StatType.AP_DEF: character.ap_def,
                    StatType.AP_DEX: character.ap_dex,
                    StatType.AP_PHY: character.ap_phy,
                    StatType.AVAILABLE_AP: character.remaining_ap,
                    **self._client_base_combat_stats(),
                }
            )
        updates[StatType.EXP] = character.exp
        self._send_stats(updates)
        if leveled_up:
            if self.account_id:
                self.accounts.update_character_summary(
                    self.character.character_id,
                    level=character.level,
                    mapId=character.map_id,
                    line=self.line_id,
                )
                account = self.accounts.account_by_id(self.account_id)
                for reached_level in range(starting_level + 1, character.level + 1):
                    if reached_level < TUTOR_STUDENT_MIN_LEVEL:
                        continue
                    if reached_level < TUTOR_LEVEL:
                        if account is not None and not int(account.get("tutorAccountId", 0)):
                            self._send_tutor_recommendations(want_tutors=True)
                    elif account is not None and len(
                        {int(value) for value in account.get("studentAccountIds", [])}
                    ) < TUTOR_MAX_STUDENTS:
                        self._send_tutor_recommendations(want_tutors=False)
            self._refresh_all_original_quests()
            self._trigger_editor_events(
                "升级",
                {"old_level": starting_level, "level": character.level},
            )

    def _refresh_monster_if_due(self) -> None:
        """Respawn due monsters at their authored location with a fresh elite roll."""
        if self.hub is not None and not self.hub.claim_monster_control(self):
            return
        now = time.monotonic()
        wave_memorial_changed = False
        for monster in self.monsters.values():
            if monster.hp > 0 or not monster.respawn_at or now < monster.respawn_at:
                continue
            definition = GAME_DATA_CATALOG.get_monster_definition(monster.template_id)
            monster.x = monster.spawn_x
            monster.y = monster.spawn_y
            monster.foothold = monster.spawn_foothold
            self._configure_monster_variant(monster, definition)
            monster.respawn_at = 0.0
            if self.hub is not None:
                self.hub.clear_boss_respawn(self, monster)
            monster.target_character_id = 0
            monster.engaged_character_ids.clear()
            monster.next_move_at = 0.0
            monster.next_attack_at = 0.0
            monster.client_velocity_x = 0
            monster.client_velocity_y = 0
            monster.client_movement_action = 1
            monster.client_foothold = monster.foothold
            monster.last_movement_broadcast_at = 0.0
            monster.movement_distance_remainder = 0.0
            monster.patrol_moving = False
            monster.patrol_phase_until = 0.0
            monster.attack_animation_until = 0.0
            monster.motion_started_at = 0.0
            monster.motion_ends_at = 0.0
            monster.knockback_until = 0.0
            monster.knockback_reported = False
            monster.skill_statuses.clear()
            if any(
                monster.template_id == template_id
                for _, template_id in self.WAVE_MEMORIAL_BOSS_SPECS
            ):
                wave_memorial_changed = True
            if self.entered_game:
                self._send_visible(self._monster_spawn_payload(monster))
        if wave_memorial_changed:
            self._refresh_wave_memorial_music_config()

    def _expire_map_drops(self, now: float | None = None) -> None:
        """Remove abandoned shared-map drops once their five-minute window expires."""
        if self.hub is not None and not self.hub.claim_monster_control(self):
            return
        current = time.monotonic() if now is None else now
        expired_ids: list[int] = []
        released_owner_ids: list[int] = []
        lock = self.hub.lock if self.hub is not None else nullcontext()
        with lock:
            for object_id, drop in tuple(self.drops.items()):
                if drop.persistent or drop.scheduled_event_key:
                    continue
                lifetime = (
                    drop.lifetime_seconds
                    if drop.lifetime_seconds > 0
                    else self.MAP_DROP_LIFETIME_SECONDS
                )
                if current - drop.spawned_at >= lifetime:
                    self.drops.pop(object_id, None)
                    expired_ids.append(object_id)
                    continue
                if (
                    drop.owner_character_id not in (None, 0)
                    and drop.owner_release_at > 0
                    and current >= drop.owner_release_at
                ):
                    drop.owner_character_id = 0
                    drop.owner_release_at = 0.0
                    released_owner_ids.append(object_id)
        for object_id in released_owner_ids:
            self._send_visible(
                f"{op(ServerOpcode.REMOVE_DROP_ITEM_OWNER)}:{object_id}"
            )
        for object_id in expired_ids:
            self._send_visible(
                f"{op(ServerOpcode.REMOVE_ITEM_FROM_MAP)}:"
                f"{op(DropRemoveAnimation.EXPIRE)}:{object_id}:false:0"
            )
        if not expired_ids or any(not drop.persistent for drop in self.drops.values()):
            return
        hidden = (
            GAME_DATA_CATALOG.hidden_copy_config(self.active_copy_id)
            if self.active_copy_id is not None
            else None
        )
        if hidden is not None and self._safe_int(hidden.get("type"), 0) == 101:
            for member in self._active_copy_members():
                member._complete_active_copy()

    def _remove_one_battle_item(self, item_id: int, *, notify: bool = True) -> bool:
        """Remove one globally unique battlefield item from the character bag."""
        with self.store.lock:
            row = next(
                (
                    item
                    for item in self.store.state.inventory.values()
                    if item.item_id == int(item_id) and item.quantity > 0
                ),
                None,
            )
            if row is None:
                return False
            if row.quantity <= 1:
                self.store.state.inventory.pop(row.slot, None)
                removed = True
            else:
                row.quantity -= 1
                removed = False
            self.store.save()
        if notify:
            if removed:
                self._send_inventory_clear(row.slot, InventoryType.BAG)
            else:
                self._send_inventory_update(row, from_drop=0)
        return True

    def _spawn_battle_item_drop(
        self,
        item_id: int,
        *,
        x: int | None = None,
        y: int | None = None,
        foothold: int | None = None,
        include_self: bool = True,
    ) -> DropState:
        """Create one public shared-map drop for an artifact or battlefield key."""
        origin_x = self.x if x is None else int(x)
        origin_y = self.y if y is None else int(y)
        origin_foothold = self.character.foothold if foothold is None else int(foothold)
        drop_x, drop_y, drop_foothold = self._next_drop_position(
            origin_x, origin_y, origin_foothold
        )
        drop = DropState(
            object_id=(
                self.hub.allocate_drop_id(self)
                if self.hub is not None
                else self.next_drop_object_id
            ),
            item_id=int(item_id),
            x=drop_x,
            y=drop_y,
            quantity=1,
            can_trade=False,
            owner_character_id=0,
            foothold=drop_foothold,
        )
        if self.hub is None:
            self.next_drop_object_id += 1
        self.drops[drop.object_id] = drop
        self._send_visible(self._drop_payload(drop), include_self=include_self)
        return drop

    def _release_global_battle_items(self, reason: str) -> None:
        """Drop active key/relic ownership on death, disconnect, or battlefield exit."""
        if self.hub is None:
            return
        character_id = self.character.character_id
        changed_artifact = False
        changed_war = False
        with self.hub.lock:
            artifact = self.hub.artifact_war
            if (
                artifact.holder_id == character_id
                and artifact.held_item_id > 0
                and not artifact.settled
            ):
                item_id = artifact.held_item_id
                if self._remove_one_battle_item(item_id, notify=reason != "disconnect"):
                    drop = self._spawn_battle_item_drop(
                        item_id, include_self=reason != "disconnect"
                    )
                    artifact.ground_drop_id = drop.object_id
                artifact.holder_id = 0
                artifact.holder_name = ""
                artifact.held_item_id = 0
                changed_artifact = True
            for relic in self.hub.war_relics.values():
                if relic.holder_id != character_id:
                    continue
                if self._remove_one_battle_item(relic.item_id, notify=reason != "disconnect"):
                    drop = self._spawn_battle_item_drop(
                        relic.item_id, include_self=reason != "disconnect"
                    )
                    relic.ground_drop_id = drop.object_id
                relic.holder_id = 0
                relic.holder_name = ""
                relic.channel_id = 0
                changed_war = True
        if changed_artifact:
            self.hub.persist_artifact_war()
        if changed_war:
            self.hub.persist_war_relics()

    def _claim_global_battle_drop(self, drop: DropState) -> None:
        """Bind a picked-up shared drop to exactly one authoritative carrier."""
        if self.hub is None:
            return
        changed_artifact = False
        changed_war = False
        with self.hub.lock:
            artifact = self.hub.artifact_war
            if artifact.ground_drop_id == drop.object_id:
                artifact.holder_id = self.character.character_id
                artifact.holder_name = self.character.name
                artifact.held_item_id = drop.item_id
                artifact.ground_drop_id = 0
                changed_artifact = True
            for relic in self.hub.war_relics.values():
                if relic.ground_drop_id != drop.object_id:
                    continue
                relic.holder_id = self.character.character_id
                relic.holder_name = self.character.name
                relic.channel_id = self.war_battle_channel
                relic.ground_drop_id = 0
                changed_war = True
                break
        if changed_artifact:
            self.hub.persist_artifact_war()
            self._broadcast_rare_event(
                f"{self.character.name}\u83b7\u5f97\u4e86\u795e\u5668\u6218\u573a\u552f\u4e00\u4fe1\u7269\uff01",
                highlights=(self.character.name,),
            )
        if changed_war:
            self.hub.persist_war_relics()
            self._broadcast_rare_event(
                f"{self.character.name}\u593a\u5f97\u4e86\u5fcd\u754c\u5927\u6218\u795e\u5668\uff01",
                highlights=(self.character.name,),
            )

    def _send_drop(self, drop: DropState) -> None:
        """Create a map drop in ItemDropInfo.decode2's exact field order."""
        now = time.monotonic()
        if not drop.persistent:
            if drop.owner_character_id is None:
                drop.owner_character_id = self.character.character_id
            if drop.owner_release_at <= 0:
                drop.owner_release_at = (
                    now + self.DERIVED_DROP_OWNER_PROTECTION_SECONDS
                )
            if drop.lifetime_seconds <= 0:
                drop.lifetime_seconds = self.DERIVED_DROP_LIFETIME_SECONDS
        # The first drop in a normal kill remains immediate.  Subsequent drops
        # in the same short burst (including an AOE kill's drops) are retained
        # in ``self.drops`` but published by the runtime ticker in bounded
        # batches.  This preserves pickup authority and rewards while avoiding
        # a single Flash frame containing dozens of object-create packets.
        if self.pending_drop_publications or now < self.drop_publication_burst_until:
            if drop.object_id not in self.pending_drop_publications:
                self.pending_drop_publications.append(drop.object_id)
        else:
            self._send_visible(self._drop_payload(drop))
        self.drop_publication_burst_until = now + 0.12

    def _flush_pending_drop_publications(self) -> None:
        """Publish a bounded number of queued drops and skip picked/expired ones."""
        published = 0
        while (
            self.pending_drop_publications
            and published < DROP_PUBLICATION_BATCH_SIZE
        ):
            object_id = self.pending_drop_publications.popleft()
            drop = self.drops.get(object_id)
            if drop is None:
                continue
            self._send_visible(self._drop_payload(drop))
            published += 1
        if not self.pending_drop_publications:
            self.drop_publication_burst_until = 0.0

    def _next_drop_position(
        self,
        origin_x: int,
        origin_y: int,
        foothold_id: int = 0,
        *,
        batch_positions: list[tuple[int, int]] | None = None,
    ) -> tuple[int, int, int]:
        """Reserve a visible slot on the nearest walkable floor.

        A supplied batch contains only drops from the same defeated unit, so
        that unit's rewards form one alternating row. Existing drops from other
        units are intentionally ignored and may occupy the same coordinates.
        Callers without a unit batch keep the global non-overlap behavior used
        by persistent event and battlefield objects.
        """
        used_positions = (
            tuple(batch_positions)
            if batch_positions is not None
            else tuple((drop.x, drop.y) for drop in self.drops.values())
        )
        floors: list[FootholdState] = []
        if self.current_map is not None:
            requested = self.current_map.footholds.get(foothold_id)
            below = self.current_map.foothold_below(origin_x, origin_y)
            for floor in (requested, below):
                if floor is not None and floor not in floors:
                    floors.append(floor)
            nearby = sorted(
                self.current_map.footholds.values(),
                key=lambda floor: abs(floor.y_at(max(floor.left, min(floor.right, origin_x))) - origin_y),
            )
            for floor in nearby:
                if floor.x1 != floor.x2 and floor not in floors:
                    floors.append(floor)

        def free(candidate_x: int, candidate_y: int) -> bool:
            return all(
                abs(candidate_x - drop_x) >= 30 or abs(candidate_y - drop_y) >= 24
                for drop_x, drop_y in used_positions
            )

        def reserve(candidate_x: int, candidate_y: int, candidate_foothold: int) -> tuple[int, int, int]:
            if batch_positions is not None:
                batch_positions.append((candidate_x, candidate_y))
            return candidate_x, candidate_y, candidate_foothold

        for floor in floors:
            center_x = max(floor.left, min(floor.right, int(origin_x)))
            width = max(1, floor.right - floor.left)
            slots = min(96, max(1, width // 30 + 1))
            for index in range(slots):
                if index == 0:
                    offset = 0
                else:
                    distance = ((index + 1) // 2) * 30
                    offset = -distance if index % 2 else distance
                candidate_x = max(floor.left, min(floor.right, center_x + offset))
                candidate_y = round(floor.y_at(candidate_x))
                if free(candidate_x, candidate_y):
                    return reserve(candidate_x, candidate_y, floor.foothold_id)

        # There is no walkable floor (or every nearby floor is saturated). Keep
        # the position deterministic but never reuse an occupied coordinate.
        step = 30 * (len(used_positions) + 1)
        for direction in (1, -1, 2, -2, 3, -3):
            candidate_x = int(origin_x + direction * step)
            if free(candidate_x, int(origin_y)):
                return reserve(candidate_x, int(origin_y), int(foothold_id))
        return reserve(int(origin_x + step), int(origin_y), int(foothold_id))

    def _drop_payload(self, drop: DropState) -> str:
        """Encode one retained world drop without broadcasting it twice."""
        owner_character_id = (
            self.character.character_id
            if drop.owner_character_id is None
            else drop.owner_character_id
        )
        return (
            f"{op(ServerOpcode.DROP_ITEM_FROM_MAPOBJECT)}:{drop.object_id}:"
            f"{'true' if drop.is_money else 'false'}:{drop.item_id}:"
            f"{'true' if drop.touch_up else 'false'}:"
            f"{drop.aptitude if not drop.is_money else 0}:"
            f"{owner_character_id}:{drop.x}:{drop.y}:{drop.x}:{drop.y}:"
            f"{drop.drop_mode}:{drop.foothold}"
        )

    def handle_item_pickup(self, read_str: str) -> None:
        """Move a known map drop into an existing stack or the first free bag slot."""
        fields = self._request_fields(read_str, ClientOpcode.ITEM_PICKUP)
        if not fields:
            return
        object_id = self._safe_int(fields[0], -1)
        drop = self.drops.get(object_id)
        if drop is None:
            return
        if drop.persistent:
            return
        now = time.monotonic()
        if (
            drop.owner_character_id not in (None, 0, self.character.character_id)
            and drop.owner_release_at > now
        ):
            self._send_system_chat("该掉落仍在归属保护时间内。")
            return
        self.drops.pop(object_id, None)
        if drop.is_money:
            with self.store.lock:
                self.store.state.money += drop.item_id
                self.store.save()
            self._send_stats({StatType.MONEY: self.store.state.money})
        else:
            definition = GAME_DATA_CATALOG.get_item_definition(drop.item_id)
            if drop.touch_up and definition is not None and definition.use_type == "zhenqi":
                amount = max(1, self._safe_int(definition.parameters.get("capacity"), 1))
                with self.store.lock:
                    self._add_zq(amount)
                    self.store.save()
                self._send_stats({StatType.ZQ: self.character.zq})
                self._send_visible(
                    f"{op(ServerOpcode.REMOVE_ITEM_FROM_MAP)}:"
                    f"{op(DropRemoveAnimation.PICKUP)}:{drop.object_id}:false:"
                    f"{self.character.character_id}"
                )
                return
            if definition is not None and definition.use_type == "zidong":
                with self.store.lock:
                    previous_hp = self.character.hp
                    previous_mp = self.character.mp
                    self.character.hp = min(
                        self._current_max_hp(),
                        self.character.hp + definition.hp_restore * drop.quantity,
                    )
                    self.character.mp = min(
                        self._current_max_mp(),
                        self.character.mp + definition.mp_restore * drop.quantity,
                    )
                    self.store.save()
                updates: dict[StatType, int] = {}
                if self.character.hp != previous_hp:
                    updates[StatType.HP] = self.character.hp
                if self.character.mp != previous_mp:
                    updates[StatType.MP] = self.character.mp
                if updates:
                    self._send_stats(updates)
                self._send_visible(
                    f"{op(ServerOpcode.REMOVE_ITEM_FROM_MAP)}:"
                    f"{op(DropRemoveAnimation.PICKUP)}:{drop.object_id}:false:"
                    f"{self.character.character_id}"
                )
                return
            with self.store.lock:
                if not self._has_inventory_capacity([(drop.item_id, drop.quantity)]):
                    self.drops[object_id] = drop
                    self._send_system_chat("背包已满，无法拾取。")
                    return
                if drop.inventory_item is not None:
                    slot = next(
                        (
                            value
                            for value in range(1, self.store.state.bag_capacity + 1)
                            if value not in self.store.state.inventory
                        ),
                        0,
                    )
                    if slot == 0:
                        self.drops[object_id] = drop
                        return
                    item = replace(drop.inventory_item, slot=slot)
                    self.store.state.inventory[slot] = item
                    created = True
                else:
                    item, created = self._add_inventory_item(
                        drop.item_id,
                        drop.quantity,
                        can_trade=drop.can_trade,
                    )
                if (
                    drop.inventory_item is None
                    and created
                    and GAME_DATA_CATALOG.is_equipment_item(drop.item_id)
                ):
                    item.aptitude = min(5, max(1, drop.aptitude))
                    equipment = GAME_DATA_CATALOG.get_equipment_definition(drop.item_id)
                    if equipment is not None and equipment.position != EquipmentPosition.TRANSFORM:
                        item.plus_attributes = self._generate_plus_attributes(
                            item,
                            equipment,
                            item.aptitude,
                        )
                self.store.save()
            if created:
                if GAME_DATA_CATALOG.is_equipment_item(item.item_id):
                    self.pending_equipment_pickups.add(item.unique_id)
                self._send_inventory_add(item, from_drop=1)
            else:
                self._send_inventory_update(item, from_drop=1)
            self._refresh_all_original_quests()
            self._claim_global_battle_drop(drop)
        self._send_visible(
            f"{op(ServerOpcode.REMOVE_ITEM_FROM_MAP)}:{op(DropRemoveAnimation.PICKUP)}:"
            f"{drop.object_id}:false:{self.character.character_id}"
        )
        hidden = (
            GAME_DATA_CATALOG.hidden_copy_config(self.active_copy_id)
            if self.active_copy_id is not None
            else None
        )
        if (
            hidden is not None
            and self._safe_int(hidden.get("type"), 0) == 101
            and not any(not value.persistent for value in self.drops.values())
        ):
            for member in self._active_copy_members():
                member._complete_active_copy()

    @staticmethod
    def _items_can_stack(first: InventoryItem, second: InventoryItem) -> bool:
        """Keep bound and unbound instances in separate stacks in every container."""
        return (
            first.item_id == second.item_id
            and first.can_trade == second.can_trade
            and not GAME_DATA_CATALOG.is_equipment_item(first.item_id)
        )

    @staticmethod
    def _item_can_leave_owner(item: InventoryItem | None) -> bool:
        """Return whether an item may cross character ownership boundaries."""
        if item is None or item.slot <= 0 or item.quantity <= 0 or not item.can_trade:
            return False
        definition = GAME_DATA_CATALOG.get_item_definition(item.item_id)
        return definition is None or definition.section != "RenWuWuPin"

    @staticmethod
    def _binds_when_equipped(
        item: InventoryItem,
        *,
        character_equipment: bool,
    ) -> bool:
        """Mirror ItemWindow2's green/purple bind-on-equip confirmation rule."""
        if (
            not item.can_trade
            or item.aptitude not in {3, 4}
            or item.item_id in GAME_DATA_CATALOG.never_bind_item_ids()
        ):
            return False
        if not character_equipment:
            return True
        definition = GAME_DATA_CATALOG.get_equipment_definition(item.item_id)
        return definition is not None and definition.position != EquipmentPosition.KUN_CHONG_BAG

    def _bind_item_instance(self, item: InventoryItem) -> bool:
        """Persist one irreversible instance bind and report whether it changed."""
        if not item.can_trade or item.item_id in GAME_DATA_CATALOG.never_bind_item_ids():
            return False
        item.can_trade = False
        return True

    def _add_inventory_item(
        self,
        item_id: int,
        quantity: int,
        *,
        can_trade: bool | None = None,
    ) -> tuple[InventoryItem, bool]:
        """Add an item without stacking equipment and report whether a slot was created."""
        inventory = self.store.state.inventory
        definition = GAME_DATA_CATALOG.get_item_definition(item_id)
        stack_limit = _item_stack_limit(item_id)
        # Native ItemCodec serializes quantity as an unsigned short. Clamp
        # malformed/replayed requests before they can poison the save or socket.
        quantity = max(1, _safe_item_quantity(item_id, quantity))
        if can_trade is None:
            can_trade = item_id not in GAME_DATA_CATALOG.bind_item_ids()
        if item_id in GAME_DATA_CATALOG.never_bind_item_ids():
            can_trade = True
        equipment = (
            GAME_DATA_CATALOG.get_equipment_definition(item_id)
            or GAME_DATA_CATALOG.get_pet_equipment_definition(item_id)
        )
        if equipment is None:
            for item in inventory.values():
                if (
                    item.slot > 0
                    and self._items_can_stack(
                        item,
                        InventoryItem(item_id=item_id, slot=0, can_trade=can_trade),
                    )
                    and _safe_item_quantity(item.item_id, item.quantity) + quantity
                    <= stack_limit
                ):
                    item.quantity = _safe_item_quantity(item.item_id, item.quantity) + quantity
                    return item, False
        slot = next(
            (slot for slot in range(1, self.store.state.bag_capacity + 1) if slot not in inventory),
            0,
        )
        if slot == 0:
            raise InventoryCapacityError("character bag is full")
        item = InventoryItem(
            item_id=item_id,
            slot=slot,
            quantity=quantity,
            unique_id=int(time.time_ns() % 9_000_000_000),
            can_trade=can_trade,
        )
        if equipment is not None:
            # New equipment starts with the original stage base value and durability.
            item.base_attr_type = equipment.base_attr_type
            item.base_attr_value = equipment.base_attr_value
            item.max_endure = equipment.max_endure
            item.endure = equipment.max_endure
            if equipment.type_name == "RenJu":
                item.plus_attributes = [
                    [int(attribute_type), int(value)]
                    for attribute_type, value in equipment.additional_attributes
                ]
            elif equipment.position == EquipmentPosition.BADGE:
                item.plus_attributes = [
                    [int(attribute_type), int(value)]
                    for attribute_type, value in equipment.additional_attributes
                ]
            if equipment.position == EquipmentPosition.TRANSFORM:
                apply_nya208_transform_card_profile(item)
                if item_id not in self.store.state.transform_card_collection:
                    self.store.state.transform_card_collection.append(item_id)
                    self.store.state.transform_card_collection.sort()
        inventory[slot] = item
        if GAME_DATA_CATALOG.is_equipment_item(item_id):
            self.pending_equipment_pickups.add(item.unique_id)
        return item, True

    def _normalize_transform_card_collection(self) -> None:
        """Backfill lifetime transform-card collection progress from existing saves."""
        collected = set(self.store.state.transform_card_collection)
        for item in (
            *self.store.state.inventory.values(),
            *self.store.state.transform_card_storage.values(),
        ):
            definition = GAME_DATA_CATALOG.get_equipment_definition(item.item_id)
            if (
                definition is not None
                and definition.position == EquipmentPosition.TRANSFORM
            ):
                collected.add(item.item_id)
        normalized = sorted(collected)
        if normalized != self.store.state.transform_card_collection:
            with self.store.lock:
                self.store.state.transform_card_collection = normalized
                self.store.save()

    def _normalize_item_binding(self) -> None:
        """Apply GameData's acquisition binding policy to existing item instances."""
        bind_ids = GAME_DATA_CATALOG.bind_item_ids()
        never_bind_ids = GAME_DATA_CATALOG.never_bind_item_ids()
        changed = False
        with self.store.lock:
            for item in (
                *self.store.state.inventory.values(),
                *self.store.state.storage.values(),
                *self.store.state.transform_card_storage.values(),
            ):
                if item.item_id in bind_ids:
                    expected = False
                elif item.item_id in never_bind_ids:
                    expected = True
                else:
                    # Ordinary items may be bound later by the player. Preserve
                    # that persisted instance state across login normalization.
                    continue
                if item.can_trade != expected:
                    item.can_trade = expected
                    changed = True
            if changed:
                self.store.save()

    def _normalize_transform_card_attributes(self) -> None:
        """Replace legacy fabricated rolls with captured Nya 2.0.8 card instances."""
        changed = False
        with self.store.lock:
            for item in (
                *self.store.state.inventory.values(),
                *self.store.state.transform_card_storage.values(),
            ):
                definition = GAME_DATA_CATALOG.get_equipment_definition(item.item_id)
                if definition is None or definition.position != EquipmentPosition.TRANSFORM:
                    continue
                changed = apply_nya208_transform_card_profile(item) or changed
            if changed:
                self.store.save()

    def _normalize_ling_qi_attributes(self) -> None:
        """Remove the legacy template addAttr that incorrectly marked fresh swords as refined."""
        changed = False
        with self.store.lock:
            for item in self.store.state.inventory.values():
                definition = GAME_DATA_CATALOG.get_equipment_definition(item.item_id)
                if (
                    definition is not None
                    and definition.type_name == "LingQi"
                    and item.plus_attributes == [[op(EquipmentAttribute.ATTACK), 600]]
                ):
                    item.plus_attributes = []
                    changed = True
            if changed:
                self.store.save()

    def _normalize_equipment_inlays(self) -> None:
        """Backfill skill-gem levels saved before skill gems carried their level as value."""
        changed = False
        with self.store.lock:
            for container in (self.store.state.inventory, self.store.state.storage):
                for item in container.values():
                    if not isinstance(item, InventoryItem):
                        continue
                    for inlay in item.inlays:
                        if len(inlay) < 5 or inlay[3] <= 0 or inlay[4] > 0:
                            continue
                        stone_config = GAME_DATA_CATALOG.get_stone_inlay(inlay[0])
                        if (
                            stone_config is not None
                            and stone_config[1] == inlay[2]
                            and stone_config[2] == inlay[3]
                            and stone_config[3] != inlay[4]
                        ):
                            inlay[4] = stone_config[3]
                            changed = True
            if changed:
                self.store.save()

    def _normalize_badge_attributes(self) -> None:
        """Restore every badge's authored fixed attributes in existing saves."""
        changed = False
        with self.store.lock:
            for item in (*self.store.state.inventory.values(), *self.store.state.storage.values()):
                definition = GAME_DATA_CATALOG.get_equipment_definition(item.item_id)
                if definition is None or definition.position != EquipmentPosition.BADGE:
                    continue
                expected_attributes = [
                    [int(attribute_type), int(value)]
                    for attribute_type, value in definition.additional_attributes
                ]
                if item.base_attr_type != definition.base_attr_type:
                    item.base_attr_type = definition.base_attr_type
                    changed = True
                if item.base_attr_value != definition.base_attr_value:
                    item.base_attr_value = definition.base_attr_value
                    changed = True
                if item.plus_attributes != expected_attributes:
                    item.plus_attributes = expected_attributes
                    changed = True
            if changed:
                self.store.save()

    def _normalize_special_equipment_strength(self) -> None:
        """Remove normal forge stars that crash Nya's badge tooltip."""
        changed = False
        unsupported_positions = {
            op(EquipmentPosition.BADGE),
        }
        with self.store.lock:
            for item in self.store.state.inventory.values():
                definition = GAME_DATA_CATALOG.get_equipment_definition(item.item_id)
                if definition is None or op(definition.position) not in unsupported_positions:
                    continue
                if item.strength_level or item.strength_info or item.strength_value:
                    item.strength_level = 0
                    item.strength_info = []
                    item.strength_value = 0
                    changed = True
            if changed:
                self.store.save()

    def _normalize_kun_chong_attributes(self) -> None:
        """Fill missing authored six-stat insect profiles on legacy saves."""
        changed = False
        with self.store.lock:
            for item in (
                *self.store.state.inventory.values(),
                *self.store.state.storage.values(),
            ):
                profile = KUN_CHONG_SIX_BASE_ATTRIBUTES.get(item.item_id)
                if not profile or item.plus_attributes:
                    continue
                item.plus_attributes = [
                    [int(attribute_type), int(value)]
                    for attribute_type, value in profile
                ]
                changed = True
            if changed:
                self.store.save()

    @staticmethod
    def _supports_standard_equipment_forge(
        definition: EquipmentDefinition,
    ) -> bool:
        """Match the equipment types accepted by the client's normal forge panels."""
        if isinstance(definition.position, PetEquipmentPosition):
            return (definition.item_id // 10_000) % 100 != 5
        return definition.position in {
            EquipmentPosition.WEAPON,
            EquipmentPosition.GLOVES,
            EquipmentPosition.CLOTHES,
            EquipmentPosition.HEADBAND,
            EquipmentPosition.BELT,
            EquipmentPosition.SHOES,
            EquipmentPosition.HAT,
            EquipmentPosition.RING,
            EquipmentPosition.BRACELET,
            EquipmentPosition.BAG,
            EquipmentPosition.CLOAK,
            EquipmentPosition.NECKLACE,
        } and (definition.item_id // 10_000) % 100 != 21

    def _normalize_equipment_forge_eligibility(self) -> None:
        """Remove legacy normal-forge fields from gear with dedicated upgrade systems."""
        changed = False
        fields = (
            ("born_attr_value", 0),
            ("strength_value", 0),
            ("tale_attr_type", -1),
            ("tale_attr_value", 0),
            ("special_attributes", []),
            ("special_level", 0),
            ("special_effect_type", 0),
            ("afterimage_flag", 0),
            ("forge_additive_ratio", 0),
            ("strength_level", 0),
            ("strength_info", []),
            ("carve_id", 0),
            ("carve_type", 0),
            ("carve_value", 0),
            ("stageup120_percent", 0),
            ("reforge_time", 0),
            ("zb_ling_hua", 0),
            ("myth_forge_type", 0),
            ("myth_forge_count", 0),
            ("myth_wuxing", 0),
            ("myth_skill_id", 0),
            ("myth_skill_level", 0),
            ("myth_wuxing_level", 0),
            ("myth_attributes", []),
        )
        with self.store.lock:
            for item in self.store.state.inventory.values():
                definition = (
                    GAME_DATA_CATALOG.get_equipment_definition(item.item_id)
                    or GAME_DATA_CATALOG.get_pet_equipment_definition(item.item_id)
                )
                if (
                    definition is None
                    or self._supports_standard_equipment_forge(definition)
                    or definition.type_name == "KunChong"
                ):
                    continue
                for name, default in fields:
                    if getattr(item, name) != default:
                        setattr(item, name, list(default) if isinstance(default, list) else default)
                        changed = True
            if changed:
                self.store.save()

    def _has_inventory_capacity(self, rewards: list[tuple[int, int]]) -> bool:
        """Check free slots before transactions that must not partially mutate state."""
        occupied = {slot for slot in self.store.state.inventory if slot > 0}
        required_slots = 0
        for item_id, quantity in rewards:
            if quantity <= 0:
                continue
            if GAME_DATA_CATALOG.is_equipment_item(item_id):
                required_slots += quantity
                continue
            stack_limit = _item_stack_limit(item_id)
            can_trade = item_id not in GAME_DATA_CATALOG.bind_item_ids()
            room = sum(
                max(
                    0,
                    stack_limit
                    - _safe_item_quantity(current.item_id, current.quantity),
                )
                for current in self.store.state.inventory.values()
                if current.slot > 0
                and self._items_can_stack(
                    current,
                    InventoryItem(item_id=item_id, slot=0, can_trade=can_trade),
                )
            )
            remaining = max(0, int(quantity) - room)
            required_slots += (remaining + stack_limit - 1) // stack_limit
        return required_slots <= self.store.state.bag_capacity - len(occupied)

    def handle_item_move(self, read_str: str) -> None:
        """Drop a requested quantity or swap validated bag/equipment positions."""
        fields = self._request_fields(read_str, ClientOpcode.ITEM_MOVE)
        if len(fields) < 3:
            return
        source = self._safe_int(fields[1], 0)
        destination = self._safe_int(fields[2], 0)
        if source == 0:
            return
        if destination == 0:
            if source < 0:
                with self.store.lock:
                    if source not in self.store.state.inventory:
                        return
                    destination = next(
                        (
                            slot
                            for slot in range(1, self.store.state.bag_capacity + 1)
                            if slot not in self.store.state.inventory
                        ),
                        0,
                    )
                if destination == 0:
                    self._send_system_chat(
                        "\u80cc\u5305\u5df2\u6ee1\uff0c\u65e0\u6cd5\u5378\u4e0b\u88c5\u5907\u3002"
                    )
                    return
            else:
                quantity = self._safe_int(fields[3], 0) if len(fields) > 3 else 0
                self._discard_inventory_item(source, quantity)
                return
        if source == destination:
            return
        newly_bound: list[InventoryItem] = []
        with self.store.lock:
            inventory = self.store.state.inventory
            source_item = inventory.get(source)
            if source_item is None:
                return
            destination_item = inventory.get(destination)
            if destination < 0 and not self._can_equip(source_item, destination):
                return
            if source < 0 and destination_item is not None and not self._can_equip(
                destination_item, source
            ):
                return
            equip_candidates = (
                (source_item, destination),
                (destination_item, source),
            )
            for candidate, target_slot in equip_candidates:
                if (
                    candidate is not None
                    and target_slot < 0
                    and self._binds_when_equipped(
                        candidate,
                        character_equipment=True,
                    )
                ):
                    self._bind_item_instance(candidate)
                    newly_bound.append(candidate)
            source_item = inventory.pop(source, None)
            destination_item = inventory.pop(destination, None)
            # source_item was checked above while the inventory was still intact.
            assert source_item is not None
            source_item.slot = destination
            inventory[destination] = source_item
            if destination_item is not None:
                destination_item.slot = source
                inventory[source] = destination_item
            self.store.save()
        moved_section = self._inventory_item_section(source_item)
        displaced_section = self._inventory_item_section(destination_item)
        special_sections = {"ShenQi", "HunJie", "LingQi", "RenJu"}
        if moved_section in special_sections or displaced_section in special_sections:
            self._send_special_equipment_move(
                source,
                destination,
                source_item,
                destination_item,
                moved_section,
                displaced_section,
            )
        else:
            equip_indicator = 3 if source < 0 or destination < 0 else 0
            self.send_text(
                f"{op(ServerOpcode.MODIFY_INVENTORY_ITEM)}:{op(InventoryUpdateFlag.MOVE)}:"
                f"{source}:{destination}:{equip_indicator}"
            )
        self._clamp_resources_after_equipment_change()
        if source < 0 or destination < 0:
            # MOVE rebuilds Flash's equipment attributes. Follow it with the
            # authoritative base values so dependent panels refresh in the same tick.
            self._send_all_stats()
            affected_skill_ids = self._skill_gem_ids(
                source_item
            ) | self._skill_gem_ids(destination_item)
            if affected_skill_ids:
                self._refresh_skill_gem_levels(affected_skill_ids)
        if source < 0 or destination < 0:
            self._send_character_look()
        if (
            source
            in {
                op(EquipmentPosition.NINJA_TOOL_SWORD),
                op(EquipmentPosition.NINJA_TOOL_MIRROR),
            }
            or destination
            in {
                op(EquipmentPosition.NINJA_TOOL_SWORD),
                op(EquipmentPosition.NINJA_TOOL_MIRROR),
            }
            or moved_section == "ShenQi"
            or displaced_section == "ShenQi"
        ):
            self._send_shenqi_status()
        for item in newly_bound:
            section = self._inventory_item_section(item)
            self._send_inventory_clear(
                item.slot,
                self._inventory_type_for_position(section, item.slot),
            )
            self._send_inventory_add(item, from_drop=0)
        if newly_bound:
            self._send_character_notice("装备成功，物品已绑定。")
        equipped_positions = {op(position) for position in KUN_CHONG_EQUIPPED_POSITIONS}
        if source in equipped_positions or destination in equipped_positions:
            self._send_equipped_kun_chong()

    @staticmethod
    def _inventory_item_section(item: InventoryItem | None) -> str:
        """Return the GameData family used to route one inventory update."""
        if item is None:
            return ""
        definition = GAME_DATA_CATALOG.get_item_definition(item.item_id)
        return definition.section if definition is not None else ""

    @staticmethod
    def _inventory_type_for_position(section: str, position: int) -> InventoryType:
        """Map one item family and slot to the matching client-side item list."""
        if position > 0:
            return InventoryType.BAG
        if section == "ShenQi":
            return InventoryType.SHEN_QI
        if section == "LingQi":
            return InventoryType.LING_QI
        if section == "RenJu":
            return InventoryType.REN_JU
        return InventoryType.EQUIPPED

    def _send_special_equipment_move(
        self,
        source: int,
        destination: int,
        moved_item: InventoryItem,
        displaced_item: InventoryItem | None,
        moved_section: str,
        displaced_section: str,
    ) -> None:
        """Refresh special client lists without routing them through CocoEquip MOVE."""
        special_move = None
        if moved_section == "LingQi" or displaced_section == "LingQi":
            special_move = (
                InventoryUpdateFlag.MOVE_LING_QI,
                InventoryType.LING_QI,
            )
        elif moved_section == "RenJu" or displaced_section == "RenJu":
            special_move = (
                InventoryUpdateFlag.MOVE_REN_JU,
                InventoryType.REN_JU,
            )
        if special_move is not None:
            update_flag, inventory_type = special_move
            self.send_text(
                f"{op(ServerOpcode.MODIFY_INVENTORY_ITEM)}:"
                f"{op(update_flag)}:{self._encode_item_payload(moved_item)}:"
                f"{source}:{op(inventory_type)}:{destination}"
            )
            return
        self._send_inventory_clear(
            source,
            self._inventory_type_for_position(moved_section, source),
        )
        if displaced_item is not None:
            self._send_inventory_clear(
                destination,
                self._inventory_type_for_position(displaced_section, destination),
            )
        self._send_inventory_add(moved_item, from_drop=2)
        if displaced_item is not None:
            self._send_inventory_add(displaced_item, from_drop=2)

    def _discard_inventory_item(self, slot: int, requested_quantity: int) -> None:
        """Remove a positive quantity from one bag stack and update the client."""
        hp_before = self.character.hp
        mp_before = self.character.mp
        with self.store.lock:
            item = self.store.state.inventory.get(slot)
            if item is None or slot <= 0 or requested_quantity <= 0:
                return
            quantity = min(requested_quantity, item.quantity)
            item.quantity -= quantity
            removed = item.quantity == 0
            if removed:
                del self.store.state.inventory[slot]
            self.store.save()
        if removed:
            self._send_inventory_clear(slot, InventoryType.BAG)
        else:
            self._send_inventory_update(item, from_drop=0)
        self._refresh_all_original_quests()

    def handle_item_split(self, read_str: str) -> None:
        """Split part of a stack into the first free original bag slot."""
        fields = self._request_fields(read_str, ClientOpcode.ITEM_SPLIT)
        if len(fields) < 2:
            return
        source_slot = self._safe_int(fields[0], 0)
        split_count = self._safe_int(fields[1], 0)
        with self.store.lock:
            inventory = self.store.state.inventory
            source = inventory.get(source_slot)
            if source is None or source_slot <= 0 or split_count <= 0 or split_count >= source.quantity:
                return
            destination = next(
                (slot for slot in range(1, self.store.state.bag_capacity + 1) if slot not in inventory),
                0,
            )
            if destination == 0:
                self._send_system_chat("背包已满，无法拆分。")
                return
            source.quantity -= split_count
            split_item = replace(
                source,
                slot=destination,
                quantity=split_count,
                unique_id=int(time.time_ns() % 9_000_000_000),
            )
            inventory[destination] = split_item
            self.store.save()
        self._send_inventory_update(source, from_drop=0)
        self._send_inventory_add(split_item, from_drop=0)

    def handle_item_sort(self, read_str: str) -> None:
        """Merge stackable duplicates and compact the character bag in stable item order."""
        fields = self._request_fields(read_str, ClientOpcode.ITEM_SORT)
        container = self._safe_int(fields[0], op(InventorySortContainer.BAG)) if fields else 0
        if container != op(InventorySortContainer.BAG):
            return
        with self.store.lock:
            inventory = self.store.state.inventory
            original_slots = {
                id(item): slot for slot, item in inventory.items() if slot > 0
            }
            ordered = sorted(
                (item for item in inventory.values() if item.slot > 0),
                key=lambda item: (item.item_id, not item.can_trade, item.unique_id),
            )
            compacted: list[InventoryItem] = []
            merged_items: list[InventoryItem] = []
            changed_quantities: set[int] = set()
            for item in ordered:
                is_stackable = not GAME_DATA_CATALOG.is_equipment_item(item.item_id)
                original_quantity = item.quantity
                remaining = _safe_item_quantity(item.item_id, original_quantity)
                if is_stackable and remaining > 0:
                    stack_limit = _item_stack_limit(item.item_id)
                    for target in compacted:
                        if (
                            target.item_id != item.item_id
                            or target.can_trade != item.can_trade
                            or _safe_item_quantity(target.item_id, target.quantity)
                            >= stack_limit
                        ):
                            continue
                        room = stack_limit - _safe_item_quantity(
                            target.item_id, target.quantity
                        )
                        added = min(remaining, room)
                        if added <= 0:
                            continue
                        target.quantity = _safe_item_quantity(
                            target.item_id, target.quantity
                        ) + added
                        remaining -= added
                        changed_quantities.add(id(target))
                        if remaining == 0:
                            break
                if remaining > 0:
                    item.quantity = remaining
                    if item.quantity != original_quantity:
                        changed_quantities.add(id(item))
                    compacted.append(item)
                else:
                    merged_items.append(item)

            # Build the same swap sequence the Flash inventory manager will execute. Clear
            # merged-away stacks first, then move surviving instances into compacted slots.
            simulated_slots = {
                slot: item
                for slot, item in inventory.items()
                if slot > 0 and item not in merged_items
            }
            move_packets: list[tuple[int, int]] = []
            for target_slot, desired_item in enumerate(compacted, start=1):
                source_slot = next(
                    slot for slot, item in simulated_slots.items() if item is desired_item
                )
                if source_slot == target_slot:
                    continue
                displaced = simulated_slots.pop(target_slot, None)
                simulated_slots[target_slot] = simulated_slots.pop(source_slot)
                if displaced is not None:
                    simulated_slots[source_slot] = displaced
                move_packets.append((source_slot, target_slot))

            equipped = {slot: item for slot, item in inventory.items() if slot < 0}
            inventory.clear()
            inventory.update(equipped)
            for slot, item in enumerate(compacted, start=1):
                item.slot = slot
                inventory[slot] = item
            self.store.save()
        for item in merged_items:
            self._send_inventory_clear(original_slots[id(item)], InventoryType.BAG)
        for source_slot, target_slot in move_packets:
            self.send_text(
                f"{op(ServerOpcode.MODIFY_INVENTORY_ITEM)}:{op(InventoryUpdateFlag.MOVE)}:"
                f"{source_slot}:{target_slot}:0"
            )
        for item in compacted:
            if id(item) in changed_quantities:
                self._send_inventory_update(item, from_drop=0)

    def _can_equip(self, item: InventoryItem, destination: int) -> bool:
        """Check the original equipment slot, level, and job before accepting a wear request."""
        definition = GAME_DATA_CATALOG.get_equipment_definition(item.item_id)
        is_kun_chong_slot = destination in {
            op(position) for position in KUN_CHONG_EQUIPPED_POSITIONS
        }
        if definition is None or (
            definition.position == EquipmentPosition.KUN_CHONG_BAG
            and not is_kun_chong_slot
        ) or (
            definition.position != EquipmentPosition.KUN_CHONG_BAG
            and destination != op(definition.position)
        ):
            return False
        if self.character.level < definition.required_level:
            self._send_system_chat(f"需要达到 {definition.required_level} 级才能装备。")
            return False
        if definition.required_job not in (0, self.character.job):
            self._send_system_chat("当前职业不能装备这个物品。")
            return False
        if item.crash_time > 0:
            self._send_character_notice("装备已经粉碎，请先进行破碎修复")
            return False
        if item.max_endure >= 0 and item.endure <= 0:
            self._send_character_notice("装备耐久为零，请先修理")
            return False
        return True

    def _equipped_attribute_bonus(self, attribute_type: EquipmentAttribute) -> int:
        """Sum one forged attribute from every persisted character equipment slot."""
        equipped_positions = {op(position) for position in CHARACTER_EQUIPPED_POSITIONS}
        return sum(
            self._equipment_attribute_total(item, op(attribute_type))
            for item in self.store.state.inventory.values()
            if item.slot in equipped_positions
            and item.crash_time <= 0
            and (item.max_endure < 0 or item.endure > 0)
        )

    @staticmethod
    def _equipment_attribute_total(item: InventoryItem, attribute_type: int) -> int:
        """Mirror each client equipment family's authored and instance attributes."""
        definition = GAME_DATA_CATALOG.get_equipment_definition(item.item_id)
        if definition is not None and definition.type_name in {
            "ShenQi", "LingQi", "HunJie", "RenJu"
        }:
            total = sum(
                value
                for candidate_type, value in definition.template_attributes
                if candidate_type == attribute_type
            )
            if definition.type_name in {"LingQi", "RenJu"}:
                total += sum(
                    values[1]
                    for values in item.plus_attributes
                    if len(values) >= 2 and values[0] == attribute_type
                )
                total += sum(
                    value
                    for candidate_type, value in definition.special_attributes
                    if candidate_type == attribute_type
                )
            total += sum(
                values[1]
                for values in item.special_attributes
                if len(values) >= 2 and values[0] == attribute_type
            )
            return total
        total = 0
        if item.base_attr_type == attribute_type:
            total += item.base_attr_value + item.born_attr_value + item.strength_value
        for values in item.plus_attributes:
            if len(values) < 2 or values[0] != attribute_type:
                continue
            plus_value = values[1]
            additive_ratio = max(0, item.forge_additive_ratio)
            # Flash MToolTipZhuangBei uses Math.ceil for the hundred-refine suffix.
            total += plus_value + (plus_value * additive_ratio + 99) // 100
        total += sum(
            values[4]
            for values in item.inlays
            if len(values) >= 5 and values[2] == attribute_type
        )
        if item.tale_attr_type == attribute_type:
            total += item.tale_attr_value
        if item.carve_id > 0 and item.carve_type == attribute_type:
            total += item.carve_value
        total += sum(
            values[1]
            for values in item.special_attributes
            if len(values) >= 2 and values[0] == attribute_type
        )
        return total

    def _equipped_myth_attribute_rate(self, attribute_type: EquipmentAttribute) -> int:
        """Sum equipped myth attributes, which the client displays as percentages."""
        equipped_positions = {op(position) for position in CHARACTER_EQUIPPED_POSITIONS}
        return sum(
            values[1]
            for item in self.store.state.inventory.values()
            if item.slot in equipped_positions
            and item.crash_time <= 0
            and (item.max_endure < 0 or item.endure > 0)
            for values in item.myth_attributes
            if len(values) >= 2 and values[0] == op(attribute_type)
        )

    def _apply_equipped_myth_rate(
        self,
        value: int,
        attribute_type: EquipmentAttribute,
    ) -> int:
        rate = self._equipped_myth_attribute_rate(attribute_type)
        return max(1, round(value * max(0, 100 + rate) / 100))

    def _active_item_parameter(self, name: str, *, effect_type: str = "shuxing") -> int:
        """Sum one parameter from currently active, persisted item effects."""
        now = int(time.time())
        total = 0
        for item_id, expires_at in self.store.state.active_item_effects.items():
            if expires_at <= now:
                continue
            definition = GAME_DATA_CATALOG.get_item_definition(item_id)
            if definition is None or definition.use_type not in {effect_type, "bianshen"}:
                continue
            total += self._safe_int(definition.parameters.get(name), 0)
        return total

    def _active_skill_buff_value(self, *buff_types: CombatBuffType) -> float:
        """Sum live server-owned skill Buff percentages for the requested types."""
        now = int(time.time() * 1_000)
        requested = {op(buff_type) for buff_type in buff_types}
        return sum(
            float(payload.get("value_percent") or 0)
            for buff_type, payload in self.store.state.active_skill_buffs.items()
            if buff_type in requested
            and self._safe_int(payload.get("expires_at"), 0) > now
        )

    def _has_active_skill_buff(self, *buff_types: CombatBuffType) -> bool:
        """Return whether any requested Buff or Debuff is still authoritative."""
        now = int(time.time() * 1_000)
        requested = {op(buff_type) for buff_type in buff_types}
        return any(
            buff_type in requested
            and self._safe_int(payload.get("expires_at"), 0) > now
            for buff_type, payload in self.store.state.active_skill_buffs.items()
        )

    def _is_mp_sealed(self) -> bool:
        """Return whether Five Elements Seal currently suppresses usable chakra."""
        return self._has_active_skill_buff(
            CombatBuffType.LOSE_MP,
            CombatBuffType.TIAN_ZHAO,
        )

    def _client_visible_mp(self) -> int:
        """Expose sealed chakra as zero without mutating the authoritative value."""
        return 0 if self._is_mp_sealed() else self.character.mp

    def _apply_skill_buff_rate(
        self,
        value: int,
        increases: tuple[CombatBuffType, ...],
        decreases: tuple[CombatBuffType, ...] = (),
    ) -> int:
        """Apply percentage Buff modifiers without mutating the persisted base value."""
        rate = self._active_skill_buff_value(*increases)
        rate -= self._active_skill_buff_value(*decreases)
        return max(1, round(value * max(0.0, 100.0 + rate) / 100.0))

    def _apply_active_item_rate(
        self,
        value: int,
        rate_name: str,
        flat_name: str | None = None,
    ) -> int:
        """Apply original percentage and optional flat timed-item modifiers."""
        rate = self._active_item_parameter(rate_name)
        flat = self._active_item_parameter(flat_name) if flat_name else 0
        return max(1, round(value * (100 + rate) / 100) + flat)

    @staticmethod
    def _apply_independent_percentage_bonuses(
        base_value: int,
        *rates: float,
        flat_bonus: int = 0,
    ) -> int:
        """Apply every percentage to one flat subtotal so bonuses never compound."""
        base = max(0, base_value)
        total_rate = sum(rates)
        return max(1, base + round(base * total_rate / 100.0) + flat_bonus)

    def _crime_attribute_bonus(self, attribute_name: str) -> int:
        """Read one flat attack/defence modifier from the active crime tier."""
        tier = GAME_DATA_CATALOG.crime_tier_config(self.character.crime)
        attributes = tier.get("atrr") if isinstance(tier, dict) else None
        if not isinstance(attributes, dict):
            return 0
        return sum(
            self._safe_int(row.get("value"), 0)
            for row in attributes.values()
            if isinstance(row, dict) and str(row.get("type", "")) == attribute_name
        )

    def _scale_edo_stat(self, value: int) -> int:
        """Apply Edo Tensei's temporary one-tenth attribute rule."""
        return max(1, round(value / 10.0)) if self._is_edo_controlled() else value

    def _family_flag_attr_rates(self) -> dict[str, int]:
        """Return authored percentage bonuses from the joined family flag level."""
        if not self.store.state.progression.family_joined:
            return {}
        level = max(1, int(self.store.state.progression.family_flag_level))
        config = GAME_DATA_CATALOG.get_family_flag_config(level)
        attr = config.get("attr") if isinstance(config, dict) else None
        if not isinstance(attr, dict):
            return {}
        return {
            str(key): max(0, self._safe_int(value, 0))
            for key, value in attr.items()
        }

    def _unscaled_current_attack(self) -> int:
        """Return actual attack from base stats, equipment, cultivation, and attached pet."""
        base_value = (
            self._base_attribute_bonuses()[CultivationAttribute.ATTACK]
            + self._equipped_attribute_bonus(EquipmentAttribute.ATTACK)
            + self._growth_attribute_bonuses()[CultivationAttribute.ATTACK]
            + self._crime_attribute_bonus("atk")
        )
        skill_rate = self._active_skill_buff_value(
            CombatBuffType.ADD_ATK,
            CombatBuffType.REDUCE_DEF_ADD_ATK,
            CombatBuffType.PET_ADD_ATK,
        ) - self._active_skill_buff_value(
            CombatBuffType.LOSE_EQ_ATK,
            CombatBuffType.REDUCE_ATK,
        )
        return self._apply_independent_percentage_bonuses(
            base_value,
            self._equipped_myth_attribute_rate(EquipmentAttribute.ATTACK),
            self._equipped_attribute_bonus(EquipmentAttribute.ATTACK_RATE),
            self._active_item_parameter("atk_rate"),
            self._family_flag_attr_rates().get("atk_rate", 0),
            skill_rate,
        ) + self._editor_buff_bonus("攻击")

    def _current_attack(self) -> int:
        return self._scale_edo_stat(self._unscaled_current_attack())

    def _unscaled_current_defence(self) -> int:
        """Return actual defence from every implemented growth system."""
        base_value = (
            self._base_attribute_bonuses()[CultivationAttribute.DEFENCE]
            + self._equipped_attribute_bonus(EquipmentAttribute.DEFENCE)
            + self._growth_attribute_bonuses()[CultivationAttribute.DEFENCE]
            + self._crime_attribute_bonus("def")
        )
        skill_rate = self._active_skill_buff_value(
            CombatBuffType.ADD_DEF,
            CombatBuffType.PET_ADD_DEF,
        ) - self._active_skill_buff_value(
                CombatBuffType.REDUCE_DEF_ADD_ATK,
                CombatBuffType.LOSE_EQ_DEF,
                CombatBuffType.REDUCE_DEF,
        )
        return self._apply_independent_percentage_bonuses(
            base_value,
            self._equipped_myth_attribute_rate(EquipmentAttribute.DEFENCE),
            self._active_item_parameter("def_rate"),
            self._family_flag_attr_rates().get("def_rate", 0),
            skill_rate,
        ) + self._editor_buff_bonus("防御")

    def _current_defence(self) -> int:
        return self._scale_edo_stat(self._unscaled_current_defence())

    def _unscaled_current_critical(self) -> int:
        """Return actual critical value from equipment, cultivation, and attached pet."""
        base_value = (
            self._base_attribute_bonuses()[CultivationAttribute.CRITICAL]
            + self._equipped_attribute_bonus(EquipmentAttribute.CRITICAL)
            + self._growth_attribute_bonuses()[CultivationAttribute.CRITICAL]
        )
        skill_rate = self._active_skill_buff_value(
            CombatBuffType.ADD_BSK,
            CombatBuffType.PET_ADD_BSK,
        ) - self._active_skill_buff_value(CombatBuffType.REDUCE_BSK)
        return self._apply_independent_percentage_bonuses(
            base_value,
            self._equipped_myth_attribute_rate(EquipmentAttribute.CRITICAL),
            self._active_item_parameter("bsk_rate"),
            skill_rate,
        ) + self._editor_buff_bonus("暴击")

    def _current_critical(self) -> int:
        return self._scale_edo_stat(self._unscaled_current_critical())

    def _unscaled_current_evasion(self) -> int:
        """Return actual evasion value from equipment, cultivation, and attached pet."""
        base_value = (
            self._base_attribute_bonuses()[CultivationAttribute.EVASION]
            + self._equipped_attribute_bonus(EquipmentAttribute.EVASION)
            + self._growth_attribute_bonuses()[CultivationAttribute.EVASION]
        )
        skill_rate = self._active_skill_buff_value(
            CombatBuffType.ADD_AVD,
            CombatBuffType.PET_ADD_AVD,
        ) - self._active_skill_buff_value(
            CombatBuffType.REDUCE_AVD_ADD_MAXHP,
            CombatBuffType.REDUCE_AVD,
        )
        return self._apply_independent_percentage_bonuses(
            base_value,
            self._equipped_myth_attribute_rate(EquipmentAttribute.EVASION),
            self._active_item_parameter("avd_rate"),
            skill_rate,
        ) + self._editor_buff_bonus("闪避")

    def _current_evasion(self) -> int:
        return self._scale_edo_stat(self._unscaled_current_evasion())

    def _unscaled_current_attack_speed(self) -> int:
        """Return attack speed from the player and the currently attached pet."""
        base_value = (
            160
            + self._equipped_attribute_bonus(EquipmentAttribute.ATTACK_SPEED)
            + self._growth_attribute_bonuses()[CultivationAttribute.ATTACK_SPEED]
            + self._attached_pet_speed_bonus(
                PetSpeedField.ATTACK,
                EquipmentAttribute.ATTACK_SPEED,
            )
        )
        skill_rate = self._active_skill_buff_value(
            CombatBuffType.ADD_ATK_SPEED,
            CombatBuffType.PET_ADD_ATK_SPEED,
        ) - self._active_skill_buff_value(CombatBuffType.REDUCE_ATK_SPEED)
        return self._apply_independent_percentage_bonuses(
            base_value,
            self._active_item_parameter("atkspeed_rate"),
            skill_rate,
        )

    def _current_attack_speed(self) -> int:
        return self._scale_edo_stat(self._unscaled_current_attack_speed())

    def _unscaled_current_walk_speed(self) -> int:
        """Return movement speed from the player and the currently attached pet."""
        if self.character.map_id in self.LOST_FOREST_MAP_IDS:
            return 100
        escort = self.store.state.original_quests.get(8100)
        if escort is not None and QuestState(escort.state) in (
            QuestState.ACTIVE,
            QuestState.READY_TO_COMPLETE,
        ):
            return 100
        base_value = (
            100
            + self._equipped_attribute_bonus(EquipmentAttribute.WALK_SPEED)
            + self._growth_attribute_bonuses()[CultivationAttribute.WALK_SPEED]
            + self._attached_pet_speed_bonus(
                PetSpeedField.WALK,
                EquipmentAttribute.WALK_SPEED,
            )
        )
        if self._has_active_skill_buff(CombatBuffType.DARKSIGHT):
            dark_sight = self._active_skill_buff_value(CombatBuffType.DARKSIGHT)
            base_value = max(
                1,
                round(base_value * max(0.0, 100.0 + dark_sight) / 100.0),
            )
        slow = max(
            self._active_skill_buff_value(CombatBuffType.SLOW),
            self._active_skill_buff_value(CombatBuffType.FIX_SLOW),
        )
        base_value = max(
            1,
            round(base_value * max(0.0, 100.0 - slow) / 100.0),
        )
        return self._apply_independent_percentage_bonuses(
            base_value,
            self._active_item_parameter("wlkspeed_rate"),
            flat_bonus=self._active_item_parameter("wlkspeed"),
        ) + self._editor_buff_bonus("移动速度")

    def _current_walk_speed(self) -> int:
        return self._scale_edo_stat(self._unscaled_current_walk_speed())

    def _unscaled_current_max_hp(self) -> int:
        """Return actual maximum HP from every implemented growth system."""
        base_value = (
            self.character.max_hp
            + self._base_attribute_bonuses()[CultivationAttribute.MAX_HP]
            + self._equipped_attribute_bonus(EquipmentAttribute.MAX_HP)
            + self._growth_attribute_bonuses()[CultivationAttribute.MAX_HP]
        )
        return self._apply_independent_percentage_bonuses(
            base_value,
            self._equipped_myth_attribute_rate(EquipmentAttribute.MAX_HP),
            self._active_item_parameter("maxhp_rate"),
            self._family_flag_attr_rates().get("maxhp_rate", 0),
            self._active_skill_buff_value(CombatBuffType.REDUCE_AVD_ADD_MAXHP),
        ) + self._editor_buff_bonus("生命上限")

    def _current_max_hp(self) -> int:
        return self._scale_edo_stat(self._unscaled_current_max_hp())

    def _unscaled_current_max_mp(self) -> int:
        """Return actual maximum MP from every implemented growth system."""
        base_value = (
            self.character.max_mp
            + self._base_attribute_bonuses()[CultivationAttribute.MAX_MP]
            + self._equipped_attribute_bonus(EquipmentAttribute.MAX_MP)
            + self._growth_attribute_bonuses()[CultivationAttribute.MAX_MP]
        )
        return self._apply_independent_percentage_bonuses(
            base_value,
            self._equipped_myth_attribute_rate(EquipmentAttribute.MAX_MP),
            self._active_item_parameter("maxmp_rate"),
        ) + self._editor_buff_bonus("查克拉上限")

    def _current_max_mp(self) -> int:
        return self._scale_edo_stat(self._unscaled_current_max_mp())

    def _current_attack_rate(self) -> int:
        """Return the equipped percentage attack bonus from original secret seals."""
        return round(
            self._equipped_attribute_bonus(EquipmentAttribute.ATTACK_RATE)
            + self._active_skill_buff_value(
                CombatBuffType.ADD_ATK,
                CombatBuffType.REDUCE_DEF_ADD_ATK,
                CombatBuffType.PET_ADD_ATK,
            )
            - self._active_skill_buff_value(
                CombatBuffType.LOSE_EQ_ATK,
                CombatBuffType.REDUCE_ATK,
            )
        )

    def _current_ignore_defence(self) -> int:
        """Return the equipped percentage of monster defence ignored by attacks."""
        return round(
            self._equipped_attribute_bonus(EquipmentAttribute.IGNORE_DEFENCE)
            + self._active_skill_buff_value(CombatBuffType.IGNORE_DEF)
        )

    def _current_damage_reflect(self) -> int:
        """Return combined secret-seal and cultivation reflected-damage percentage."""
        return (
            self._equipped_attribute_bonus(EquipmentAttribute.DAMAGE_REFLECT)
            + self._growth_attribute_bonuses()[CultivationAttribute.DAMAGE_REFLECT]
            + round(self._active_skill_buff_value(CombatBuffType.DAMAGE_REFLECT))
        )

    def _current_damage_reduce(self) -> int:
        """Return combined secret-seal and cultivation damage-reduction percentage."""
        return (
            self._equipped_attribute_bonus(EquipmentAttribute.DAMAGE_REDUCE)
            + self._growth_attribute_bonuses()[CultivationAttribute.DAMAGE_REDUCE]
            + round(self._active_skill_buff_value(CombatBuffType.DAMAGE_REDUCE))
        )

    def _current_anti_seal_pet(self) -> int:
        """Return the equipped chance to resist Totsuka Blade pet sealing."""
        return max(
            0,
            self._equipped_attribute_bonus(EquipmentAttribute.ANTI_SEAL_PET),
        )

    def _equipped_yata_mirror(self) -> InventoryItem | None:
        item = self.store.state.inventory.get(op(EquipmentPosition.REN_JU))
        if (
            item is None
            or item.item_id not in YATA_MIRROR_ITEM_IDS
            or item.crash_time > 0
            or (item.max_endure >= 0 and item.endure <= 0)
        ):
            return None
        return item

    def _yata_mirror_resistance_percent(
        self,
        attack: SkillDefinition | None,
    ) -> int:
        """Apply the authored 10%/20% reduction to matching profession ninjutsu."""
        mirror = self._equipped_yata_mirror()
        if mirror is None or attack is None:
            return 0
        skill_element = attack.skill_id // 1_000_000
        if (
            skill_element not in YATA_RESISTANCE_NAMES
            or skill_element != self.store.state.yata_resistance_element
        ):
            return 0
        return 20 if mirror.item_id == 65_000_002 else 10

    def _send_yata_resistance_status(self) -> None:
        mirror = self._equipped_yata_mirror()
        if mirror is None:
            return
        element = self.store.state.yata_resistance_element
        reduction = 20 if mirror.item_id == 65_000_002 else 10
        self._send_character_notice(
            f"八咫镜当前为{YATA_RESISTANCE_NAMES[element]}属性抗性，"
            f"对应职业忍术伤害降低{reduction}%。"
        )

    def _base_attribute_bonuses(self) -> dict[CultivationAttribute, int]:
        """Convert each complete five-point AP group with the documented Nya ratios."""
        attack_groups = max(0, self.character.ap_atk) // 5
        defence_groups = max(0, self.character.ap_def) // 5
        agility_groups = max(0, self.character.ap_dex) // 5
        constitution_groups = max(0, self.character.ap_phy) // 5
        return {
            CultivationAttribute.ATTACK: attack_groups * 8,
            CultivationAttribute.DEFENCE: defence_groups * 10,
            CultivationAttribute.CRITICAL: agility_groups * 4,
            CultivationAttribute.EVASION: agility_groups * 10,
            CultivationAttribute.MAX_HP: constitution_groups * 40,
            CultivationAttribute.MAX_MP: constitution_groups * 20,
        }

    def _growth_attribute_bonuses(self) -> dict[CultivationAttribute, int]:
        """Aggregate original stage, Eight Gates, and attached-pet bonuses once per stat read."""
        bonuses = {attribute: 0 for attribute in CultivationAttribute}
        self._merge_growth_attributes(bonuses, self._passive_skill_attribute_bonuses())
        for state_key, config_name, maximum_stage in (
            ("结印", "JieYin", 12),
            ("柔拳", "RouQuan", 8),
            (
                "写轮眼",
                "XieLunYan",
                GAME_DATA_CATALOG.cultivation_max_stage("XieLunYan"),
            ),
            ("轮眼", "LunHuiYan", 8),
        ):
            if state_key not in self.store.state.progression.stages:
                continue
            stage = self._cultivation_stage(state_key, maximum_stage)
            if config_name == "XieLunYan":
                attributes = self._xielunyan_current_attributes(stage)
            elif config_name == "RouQuan":
                attributes = self._rouquan_current_attributes(stage, state_key)
            else:
                attributes = self._cultivation_attributes(config_name, stage)
            self._merge_growth_attributes(
                bonuses,
                attributes,
            )
        self._merge_growth_attributes(bonuses, self._mai_attribute_bonuses())
        self._merge_growth_attributes(bonuses, self._attached_pet_attribute_bonuses())
        self._merge_growth_attributes(bonuses, self._spirit_attribute_bonuses())
        return bonuses

    def _spirit_attribute_bonuses(self) -> dict[str, int]:
        """Apply every negative-slot spirit's exact authored level attribute."""
        result: dict[str, int] = {}
        for item in self.store.state.progression.spirit_items:
            if item.slot >= 0:
                continue
            for attribute_name, value in GAME_DATA_CATALOG.spirit_attribute_values(
                item.item_id, item.level
            ).items():
                result[attribute_name] = result.get(attribute_name, 0) + value
        return result

    def _passive_skill_attribute_bonuses(self) -> dict[str, int]:
        """Apply common passive skill type_attr values to the live character stats."""
        section = GAME_DATA_CATALOG._get_skill_section("000").get("skill")
        if not isinstance(section, dict):
            return {}
        result: dict[str, int] = {}
        for skill in self.store.state.skills.values():
            raw_skill = section.get(f"{skill.skill_id:07d}")
            info = raw_skill.get("info") if isinstance(raw_skill, dict) else None
            type_attribute = info.get("type_attr") if isinstance(info, dict) else None
            if not isinstance(type_attribute, dict):
                continue
            attribute_name = str(type_attribute.get("type") or "").lower()
            if attribute_name not in {attribute.value for attribute in CultivationAttribute}:
                continue
            try:
                value_level = float(type_attribute.get("valueLevel") or 0)
            except (TypeError, ValueError):
                continue
            result[attribute_name] = result.get(attribute_name, 0) + int(
                value_level * self._effective_skill_level(skill)
            )
        return result

    def _passive_skill_effect_value(self, effect_type: str) -> int:
        """Sum one authored type_attr effect across the character's learned passives."""
        section = GAME_DATA_CATALOG._get_skill_section("000").get("skill")
        if not isinstance(section, dict):
            return 0
        result = 0.0
        for skill in self.store.state.skills.values():
            raw_skill = section.get(f"{skill.skill_id:07d}")
            info = raw_skill.get("info") if isinstance(raw_skill, dict) else None
            type_attribute = info.get("type_attr") if isinstance(info, dict) else None
            if (
                not isinstance(type_attribute, dict)
                or str(type_attribute.get("type") or "").lower() != effect_type
            ):
                continue
            try:
                value_level = float(type_attribute.get("valueLevel") or 0)
            except (TypeError, ValueError):
                continue
            result += value_level * self._effective_skill_level(skill)
        return max(0, round(result))

    @staticmethod
    def _merge_growth_attributes(
        destination: dict[CultivationAttribute, int],
        source: dict[str, int],
    ) -> None:
        """Merge named GameData values into the enum-keyed derived-stat accumulator."""
        by_name = {attribute.value: attribute for attribute in CultivationAttribute}
        for raw_name, value in source.items():
            attribute = by_name.get(raw_name)
            if attribute is not None:
                destination[attribute] += max(0, value)

    def _mai_attribute_bonuses(self) -> dict[str, int]:
        """Keep every opened Eight Gates attribute at its highest reached milestone."""
        result: dict[str, int] = {}
        for key, opened_count in self.store.state.progression.stage_progress.items():
            if not key.startswith("八门:") or opened_count <= 0:
                continue
            _, raw_list_id, raw_mai_id = key.split(":", 2)
            mai_root = GAME_DATA_CATALOG.get_mai_list(self._safe_int(raw_list_id, 0)).get("mai")
            mai = mai_root.get(raw_mai_id) if isinstance(mai_root, dict) else None
            points = mai.get("pts") if isinstance(mai, dict) else None
            if not isinstance(points, dict):
                continue
            ordered_points = self._mai_client_ordered_points(points)
            opened = ordered_points[:min(opened_count, len(ordered_points))]
            if not opened:
                continue
            gate_attributes: dict[str, int] = {}
            for _, point in opened:
                attribute_name = str(point.get("attr") or "")
                if not attribute_name:
                    continue
                gate_attributes[attribute_name] = max(
                    gate_attributes.get(attribute_name, 0),
                    self._safe_int(point.get("value"), 0),
                )
            for attribute_name, value in gate_attributes.items():
                result[attribute_name] = result.get(attribute_name, 0) + value
            if len(opened) == len(ordered_points):
                gate_attribute = str(mai.get("attr") or "")
                result[gate_attribute] = result.get(gate_attribute, 0) + self._safe_int(
                    mai.get("value"), 0
                )
        skill_bonus = self._mai_skill_level_bonus()
        if skill_bonus:
            result[CultivationAttribute.JOB_SKILL_LEVEL.value] = skill_bonus
            result[CultivationAttribute.WORLD_SKILL_LEVEL.value] = skill_bonus
        return result

    def _mai_skill_level_bonus(self) -> int:
        """Return the highest authored full-stage bonus: inner +1, soul +3, seal +5."""
        bonus = 0
        for list_id, stage_bonus in self.MAI_FULL_STAGE_SKILL_BONUSES.items():
            total = self._mai_total_point_count(list_id)
            if total and self._mai_exploded_point_count(list_id) >= total:
                bonus = max(bonus, stage_bonus)
        return bonus

    def _effective_skill_level(self, skill: SkillState) -> int:
        """Apply the same Eight Gates level bonus that Flash receives through stat 39/40."""
        ling_qi_bonus = max(
            self._ling_qi_skill_level_bonus(StatType.ADD_JOB_SKILL_LEVEL),
            self._ling_qi_skill_level_bonus(StatType.ADD_WORLD_SKILL_LEVEL),
        )
        return max(
            1,
            skill.level
            + self._mai_skill_level_bonus()
            + ling_qi_bonus
            + self._equipped_skill_gem_bonus(skill.skill_id),
        )

    def _equipped_skill_gem_bonus(self, skill_id: int) -> int:
        """Sum equipped jade-chain magatama levels for one skill."""
        total = 0
        for item in self.store.state.inventory.values():
            if (
                item.slot >= 0
                or item.item_id // 10_000 != 120
                or item.crash_time > 0
                or (item.max_endure >= 0 and item.endure <= 0)
            ):
                continue
            for inlay in item.inlays:
                if len(inlay) >= 5 and inlay[3] == skill_id:
                    total += max(0, inlay[4])
        return total

    def _skill_gem_bonus_rows(self) -> list[tuple[int, int]]:
        """Return per-skill jade-chain magatama bonuses for SKILL_CHANGE_TMP."""
        bonuses: dict[int, int] = {}
        for item in self.store.state.inventory.values():
            if (
                item.slot >= 0
                or item.item_id // 10_000 != 120
                or item.crash_time > 0
                or (item.max_endure >= 0 and item.endure <= 0)
            ):
                continue
            for inlay in item.inlays:
                if len(inlay) >= 5 and inlay[3] > 0:
                    bonuses[inlay[3]] = bonuses.get(inlay[3], 0) + max(0, inlay[4])
        return sorted(bonuses.items())

    def _send_skill_gem_bonuses(self) -> None:
        """Push temporary skill-level bonuses through the original SKILL_CHANGE_TMP packet."""
        if self.wire_mode != "original":
            return
        rows = self._skill_gem_bonus_rows()
        body = bytearray(struct.pack("<i", len(rows)))
        for skill_id, bonus in rows:
            # The client's SKILL_CHANGE_TMP handler reads only id and level per
            # row; a third int would shift every following skill id.
            body.extend(struct.pack("<ii", skill_id, bonus))
        self.send_original_packet(ServerOpcode.SKILL_CHANGE_TMP, bytes(body))

    def _refresh_skill_gem_levels(self, skill_ids: set[int] | None = None) -> None:
        """Refresh temporary gem bonuses, then replay base skill levels."""
        self._send_skill_gem_bonuses()
        if skill_ids is None:
            skills = list(self.store.state.skills.values())
        else:
            skills = [
                skill
                for skill_id in skill_ids
                if (skill := self.store.state.skills.get(skill_id)) is not None
            ]
        for skill in sorted(skills, key=lambda item: item.skill_id):
            self._send_skill_update(skill)

    @staticmethod
    def _skill_gem_ids(item: InventoryItem | None) -> set[int]:
        return (
            {
                inlay[3]
                for inlay in item.inlays
                if len(inlay) >= 5 and inlay[3] > 0
            }
            if item is not None
            else set()
        )

    def _ling_qi_skill_level_bonus(self, stat_type: StatType) -> int:
        """Return the opened sword's authored job/world skill bonus while equipped."""
        item = self.store.state.inventory.get(op(EquipmentPosition.LING_QI))
        if item is None:
            return 0
        return self._equipment_attribute_total(item, op(stat_type))

    @staticmethod
    def _pet_total_dream_score(pet: PetState) -> int:
        """Mirror PetAddValue.mengHuanDu (displayed dream score, not clamped)."""
        savvy_part = max(0, pet.savvy) / 10
        real_sum = (
            max(0, pet.potential_real_atk)
            + max(0, pet.potential_real_def)
            + max(0, pet.potential_real_dex)
            + max(0, pet.potential_real_str)
        )
        denominator = (
            max(0, pet.potential_total_atk)
            + max(0, pet.potential_real_def)
            + max(0, pet.potential_total_dex)
            + max(0, pet.potential_real_str)
        )
        potential_part = real_sum / denominator * 100 / 3 if denominator > 0 else 0.0
        skill_part = max(0, len(pet.skills)) * 1.25
        dream_part = max(0, pet.dream)
        return int(savvy_part + potential_part + skill_part + dream_part)

    @staticmethod
    def _pet_dream_multiplier(pet: PetState) -> float:
        """Mirror PetAddValue.caculateMengHuandu; returns a [0,1] multiplier."""
        savvy_part = max(0, pet.savvy) / 100 / 10
        real_sum = (
            max(0, pet.potential_real_atk)
            + max(0, pet.potential_real_def)
            + max(0, pet.potential_real_dex)
            + max(0, pet.potential_real_str)
        )
        # Keep the original client's exact denominator (it uses realDef/realStr
        # instead of totalDef/totalStr) so the server matches the client UI.
        denominator = (
            max(0, pet.potential_total_atk)
            + max(0, pet.potential_real_def)
            + max(0, pet.potential_total_dex)
            + max(0, pet.potential_real_str)
        )
        potential_part = real_sum / denominator / 3 if denominator > 0 else 0.0
        skill_part = max(0, len(pet.skills)) / 8 / 10
        dream_part = max(0, pet.dream) / 100
        multiplier = savvy_part + potential_part + skill_part + dream_part
        return min(1.0, max(0.0, round(multiplier, 6)))

    def _attached_pet_attribute_bonuses(self) -> dict[str, int]:
        """Mirror PetAddValue formulas and pet gear only while a pet is attached."""
        result = {attribute.value: 0 for attribute in CultivationAttribute}
        for pet in self.store.state.pets.values():
            if pet.position != op(PetPosition.ATTACHED):
                continue
            base_bonuses = {
                CultivationAttribute.ATTACK: self._pet_attack_bonus(
                    pet.potential_real_atk, pet.level
                ),
                CultivationAttribute.DEFENCE: self._pet_defence_bonus(
                    pet.potential_real_def, pet.level
                ),
                CultivationAttribute.EVASION: self._pet_attack_bonus(
                    pet.potential_real_dex, pet.level
                ),
                CultivationAttribute.CRITICAL: self._pet_critical_bonus(
                    pet.potential_real_str, pet.level
                ),
                CultivationAttribute.MAX_HP: self._pet_hp_bonus(
                    pet.potential_real_str, pet.level
                ),
                CultivationAttribute.MAX_MP: self._pet_mp_bonus(
                    pet.potential_real_dex, pet.level
                ),
            }
            dream_multiplier = self._pet_dream_multiplier(pet)
            for attribute, base_bonus in base_bonuses.items():
                passive_rate = self._pet_passive_attribute_rate(pet, attribute.value)
                passive_bonus = base_bonus * passive_rate // 100
                result[attribute.value] += base_bonus + passive_bonus
                if dream_multiplier > 0:
                    result[attribute.value] += math.floor(
                        (base_bonus + passive_bonus) * dream_multiplier
                    )
            for item in pet.equipment.values():
                for attribute, equipment_attribute in (
                    (CultivationAttribute.MAX_HP, EquipmentAttribute.MAX_HP),
                    (CultivationAttribute.MAX_MP, EquipmentAttribute.MAX_MP),
                    (CultivationAttribute.ATTACK, EquipmentAttribute.ATTACK),
                    (CultivationAttribute.DEFENCE, EquipmentAttribute.DEFENCE),
                    (CultivationAttribute.CRITICAL, EquipmentAttribute.CRITICAL),
                    (CultivationAttribute.EVASION, EquipmentAttribute.EVASION),
                ):
                    result[attribute.value] += self._equipment_attribute_total(
                        item, op(equipment_attribute)
                    )
        return result

    def _attached_pet_speed_bonus(
        self,
        speed_field: PetSpeedField,
        equipment_attribute: EquipmentAttribute,
    ) -> int:
        """Mirror PetAddValue speed, passive-skill rate, and pet-equipment bonuses."""
        total = 0
        for pet in self.store.state.pets.values():
            if pet.position != op(PetPosition.ATTACHED):
                continue
            pet_config = GAME_DATA_CATALOG.get_pet_config(pet.item_id)
            info = pet_config.get("info") if isinstance(pet_config.get("info"), dict) else {}
            speeds = info.get("speed") if isinstance(info.get("speed"), dict) else {}
            aptitude_speed = speeds.get(f"apt{pet.aptitude}")
            if not isinstance(aptitude_speed, dict):
                aptitude_speed = {}
            base_speed = max(0, self._safe_int(aptitude_speed.get(speed_field.value), 0))

            passive_rate = self._pet_passive_attribute_rate(pet, speed_field.value)
            equipment_bonus = sum(
                self._equipment_attribute_total(item, op(equipment_attribute))
                for item in pet.equipment.values()
            )
            passive_bonus = base_speed * passive_rate // 100
            total += (
                base_speed
                + passive_bonus
                + equipment_bonus
            )
            dream_multiplier = self._pet_dream_multiplier(pet)
            if dream_multiplier > 0:
                total += math.floor(
                    (base_speed + passive_bonus) * dream_multiplier
                )
        return total

    def _pet_passive_attribute_rate(self, pet: PetState, attribute_name: str) -> int:
        """Return the original per-level percentage from passive pet skills 201-208."""
        total = 0
        pet_skills = GAME_DATA_CATALOG._get_skill_section("PetSkill")
        for skill in pet.skills.values():
            raw_skill = pet_skills.get(str(skill.skill_id))
            skill_info = raw_skill.get("info") if isinstance(raw_skill, dict) else None
            type_attribute = (
                skill_info.get("type_attr") if isinstance(skill_info, dict) else None
            )
            if not isinstance(type_attribute, dict):
                continue
            if str(type_attribute.get("type") or "").lower() != attribute_name.lower():
                continue
            total += self._safe_int(type_attribute.get("valueLevel"), 0) * max(
                0, skill.level
            )
        return total

    @staticmethod
    def _pet_attack_bonus(potential: int, level: int) -> int:
        """Calculate the original PetAddValue attack/evasion curve."""
        if potential > 1400:
            potential = potential * 0.82 + 213
        return max(0, int((2 * potential / 300 + 0.003) * level + 0.0000388 * potential**2 + 0.018 * potential - 0.231))

    @staticmethod
    def _pet_defence_bonus(potential: int, level: int) -> int:
        """Calculate the original PetAddValue defence curve."""
        if potential > 1400:
            potential = potential * 0.772 + 346
        return max(0, int((0.006 * potential - 0.005) * level + 0.000032 * potential**2 + 0.008 * potential + 0.905))

    @staticmethod
    def _pet_critical_bonus(potential: int, level: int) -> int:
        """Calculate the original PetAddValue critical curve."""
        if potential > 1000:
            potential = potential * 0.5 + 500
        return max(0, int((0.0005 * potential - 0.004) * level + 0.0000121 * potential**2 - 0.007 * potential + 5.634))

    @staticmethod
    def _pet_hp_bonus(potential: int, level: int) -> int:
        """Calculate the original PetAddValue maximum-HP curve."""
        if potential > 1400:
            potential = potential * 0.715 + 417
        return max(0, int((0.02 * potential - 0.002) * level + 0.00012 * potential**2 + 0.057 * potential - 2.803))

    @staticmethod
    def _pet_mp_bonus(potential: int, level: int) -> int:
        """Calculate the original PetAddValue maximum-MP curve."""
        if potential > 1400:
            potential = potential * 0.649 + 508
        return max(0, int((0.004 * potential - 0.003) * level + 0.0000384 * potential**2 + 0.0191 * potential - 1.232))

    def _derived_combat_stats(self) -> dict[StatType, int]:
        """Build every secondary stat consumed by character and skill calculations."""
        growth = self._growth_attribute_bonuses()
        return {
            StatType.MAX_HP: self._current_max_hp(),
            StatType.MAX_MP: self._current_max_mp(),
            StatType.ATTACK: self._current_attack(),
            StatType.DEFENCE: self._current_defence(),
            StatType.CRITICAL: self._current_critical(),
            StatType.EVASION: self._current_evasion(),
            StatType.ATTACK_SPEED: self._current_attack_speed(),
            StatType.WALK_SPEED: self._current_walk_speed(),
            StatType.ANQI_TRIGGER: growth[CultivationAttribute.ANQI_TRIGGER],
            StatType.ADD_JOB_SKILL_LEVEL: growth[CultivationAttribute.JOB_SKILL_LEVEL],
            StatType.ADD_WORLD_SKILL_LEVEL: growth[CultivationAttribute.WORLD_SKILL_LEVEL],
        }

    def _clamp_resources_after_equipment_change(self) -> None:
        """Clamp current HP and MP after locally calculated maximums decrease."""
        updates: dict[StatType, int] = {}
        with self.store.lock:
            maximum_hp = self._current_max_hp()
            maximum_mp = self._current_max_mp()
            if self.character.hp > maximum_hp:
                self.character.hp = maximum_hp
                updates[StatType.HP] = self.character.hp
            if self.character.mp > maximum_mp:
                self.character.mp = maximum_mp
                updates[StatType.MP] = self.character.mp
            if updates:
                self.store.save()
        if updates:
            self._send_stats(updates)

    def _client_base_combat_stats(self) -> dict[StatType, int]:
        """Send authoritative totals; Nya displays these values without adding gear locally."""
        growth = self._growth_attribute_bonuses()
        stats = {
            StatType.MAX_HP: self._current_max_hp(),
            StatType.MAX_MP: self._current_max_mp(),
            StatType.ATTACK: self._current_attack(),
            StatType.DEFENCE: self._current_defence(),
            StatType.CRITICAL: self._current_critical(),
            StatType.EVASION: self._current_evasion(),
            StatType.ATTACK_SPEED: self._current_attack_speed(),
            StatType.WALK_SPEED: self._current_walk_speed(),
            StatType.DAMAGE_REFLECT: self._current_damage_reflect(),
            StatType.DAMAGE_REDUCE: self._current_damage_reduce(),
            StatType.IGNORE_DEF: self._current_ignore_defence(),
        }
        stats.update({
            # These effects have dedicated CocoStatType fields; include both
            # cultivation and the opened Totsuka sword bonus.
            StatType.ANQI_TRIGGER: growth[CultivationAttribute.ANQI_TRIGGER],
            StatType.ADD_JOB_SKILL_LEVEL: (
                growth[CultivationAttribute.JOB_SKILL_LEVEL]
                + self._ling_qi_skill_level_bonus(StatType.ADD_JOB_SKILL_LEVEL)
            ),
            StatType.ADD_WORLD_SKILL_LEVEL: (
                growth[CultivationAttribute.WORLD_SKILL_LEVEL]
                + self._ling_qi_skill_level_bonus(StatType.ADD_WORLD_SKILL_LEVEL)
            ),
        })
        return stats

    @staticmethod
    def _timed_item_effect_seconds(definition: ItemDefinition) -> int:
        """Read an item's authored duration, using one minute only for malformed data."""
        return max(1, FakeFlashSession._safe_int(definition.parameters.get("interval"), 60))

    def _send_active_item_effects(self) -> None:
        """Restore valid timed icons and discard expired or misclassified material effects."""
        now = int(time.time())
        expired = [
            item_id
            for item_id, expires_at in self.store.state.active_item_effects.items()
            if expires_at <= now
            or (
                (definition := GAME_DATA_CATALOG.get_item_definition(item_id)) is None
                or definition.use_type.lower()
                not in {"shuxing", "shuangbei", "bianshen"}
            )
        ]
        if expired:
            with self.store.lock:
                for item_id in expired:
                    self.store.state.active_item_effects.pop(item_id, None)
                self.store.save()
        for item_id, expires_at in sorted(self.store.state.active_item_effects.items()):
            definition = GAME_DATA_CATALOG.get_item_definition(item_id)
            if definition is None:
                continue
            self._send_timed_item_effect_state(
                definition,
                max(1, expires_at - now),
                self._timed_item_effect_seconds(definition),
            )

    @staticmethod
    def _double_reward_effect_type(definition: ItemDefinition) -> int:
        """Map GameData reward names to the original SHUANGBEI type byte."""
        return {"exp": 0, "zq": 1, "petexp": 2}.get(
            str(definition.parameters.get("name") or "").lower(),
            0,
        )

    def _send_timed_item_effect_state(
        self,
        definition: ItemDefinition,
        remaining: int,
        total: int,
    ) -> None:
        """Send attribute and double-reward effects with their distinct packet contracts."""
        if definition.use_type == "shuangbei":
            effect_type = self._double_reward_effect_type(definition)
            rate = max(-128, min(127, self._safe_int(definition.parameters.get("rate"), 0)))
            self.send_text(
                f"{op(ServerOpcode.DOUBLE_REWARD)}:{effect_type}:{rate}:"
                f"{definition.item_id}:{remaining}:{total}"
            )
            return
        self.send_text(
            f"{op(ServerOpcode.ATTRIBUTE_ITEM_EFFECT)}:{definition.item_id}:"
            f"{remaining}:{total}"
        )

    def _refresh_active_item_effects(self) -> None:
        """Remove expired item effects and immediately restore unmodified live stats."""
        now = int(time.time())
        expired = [
            item_id
            for item_id, expires_at in self.store.state.active_item_effects.items()
            if expires_at <= now
            or (
                (definition := GAME_DATA_CATALOG.get_item_definition(item_id)) is None
                or definition.use_type.lower()
                not in {"shuxing", "shuangbei", "bianshen"}
            )
        ]
        if not expired:
            return
        with self.store.lock:
            for item_id in expired:
                self.store.state.active_item_effects.pop(item_id, None)
            self.store.save()
        for item_id in expired:
            definition = GAME_DATA_CATALOG.get_item_definition(item_id)
            if definition is not None:
                self._send_timed_item_effect_state(
                    definition,
                    0,
                    self._timed_item_effect_seconds(definition),
                )
        if self.entered_game:
            self._send_all_stats()

    def _use_timed_item_effect(
        self,
        slot: int,
        definition: ItemDefinition,
        consume_count: int = 1,
    ) -> None:
        """Consume the requested stack amount and accumulate its authored duration."""
        duration = self._timed_item_effect_seconds(definition)
        now = int(time.time())
        with self.store.lock:
            item = self.store.state.inventory.get(slot)
            if (
                item is None
                or item.item_id != definition.item_id
                or item.quantity <= 0
            ):
                return
            used = min(max(1, consume_count), item.quantity)
            item.quantity -= used
            removed = item.quantity == 0
            if removed:
                del self.store.state.inventory[slot]
            current_expiry = self.store.state.active_item_effects.get(definition.item_id, now)
            expires_at = max(now, current_expiry) + duration * used
            self.store.state.active_item_effects[definition.item_id] = expires_at
            self.store.save()
        if removed:
            self._send_inventory_clear(slot, InventoryType.BAG)
        else:
            self._send_inventory_update(item, from_drop=0)
        self._send_timed_item_effect_state(
            definition,
            expires_at - now,
            duration * used,
        )
        if definition.use_type in {"shuxing", "bianshen"}:
            self._send_all_stats()
        if definition.use_type == "bianshen":
            self._send_character_look()

    def _send_auto_consume_effect_state(
        self,
        item_id: int,
        remaining: int,
        total: int,
    ) -> None:
        """Update one original automatic-elixir capacity Buff."""
        self.send_text(
            f"{op(ServerOpcode.AUTO_CONSUME)}:{item_id}:"
            f"{max(0, remaining)}:{max(0, total)}"
        )

    def _send_auto_consume_effects(self) -> None:
        """Restore persisted life/chakra elixir capacities after reconnect."""
        for item_id, effect in sorted(self.store.state.auto_consume_effects.items()):
            remaining = max(0, self._safe_int(effect.get("remaining"), 0))
            if remaining <= 0:
                continue
            total = max(remaining, self._safe_int(effect.get("total"), remaining))
            self._send_auto_consume_effect_state(item_id, remaining, total)

    def _use_auto_consume_item(
        self,
        slot: int,
        definition: ItemDefinition,
        consume_count: int,
    ) -> None:
        """Load life/chakra elixirs into the original persistent capacity Buff."""
        unit_capacity = max(definition.hp_restore, definition.mp_restore)
        if unit_capacity <= 0:
            return
        with self.store.lock:
            item = self.store.state.inventory.get(slot)
            if (
                item is None
                or item.item_id != definition.item_id
                or item.quantity <= 0
            ):
                return
            used = min(max(1, consume_count), item.quantity)
            item.quantity -= used
            removed = item.quantity == 0
            if removed:
                del self.store.state.inventory[slot]
            effect = self.store.state.auto_consume_effects.setdefault(
                definition.item_id,
                {"remaining": 0, "total": 0},
            )
            previous_remaining = max(0, self._safe_int(effect.get("remaining"), 0))
            added = unit_capacity * used
            remaining = min(2_147_483_647, previous_remaining + added)
            effect["remaining"] = remaining
            effect["total"] = remaining
            self.store.save()
        if removed:
            self._send_inventory_clear(slot, InventoryType.BAG)
        else:
            self._send_inventory_update(item, from_drop=0)
        self._send_auto_consume_effect_state(definition.item_id, remaining, remaining)

    def _tick_auto_consume_effects(self, now: float) -> None:
        """Drain elixir capacity into missing HP/MP using the original one-second cadence."""
        if (
            not self.entered_game
            or self._is_dead()
            or now - self.last_auto_potion_at < 1.0
            or now - self.last_pvp_damage_at < self.OUT_OF_COMBAT_SECONDS
            or self.war_battle_active
            or self.war_3v3_match_id > 0
            or self.muye_battle_team in (1, 2)
            or self.local_pk_opponent_id > 0
            or self.arena_opponent is not None
        ):
            return
        maximum_hp = self._current_max_hp()
        maximum_mp = self._current_max_mp()
        mp_sealed = self._is_mp_sealed()
        updates: dict[StatType, int] = {}
        changed: list[tuple[int, int, int]] = []
        restored_hp = 0
        restored_mp = 0
        with self.store.lock:
            for item_id, effect in list(self.store.state.auto_consume_effects.items()):
                definition = GAME_DATA_CATALOG.get_item_definition(item_id)
                remaining = max(0, self._safe_int(effect.get("remaining"), 0))
                total = max(remaining, self._safe_int(effect.get("total"), remaining))
                if definition is None or definition.use_type.lower() != "zidong":
                    del self.store.state.auto_consume_effects[item_id]
                    changed.append((item_id, 0, total))
                    continue
                used = 0
                if definition.hp_restore > 0 and self.character.hp < maximum_hp:
                    used = min(remaining, maximum_hp - self.character.hp)
                    self.character.hp += used
                    restored_hp += used
                    updates[StatType.HP] = self.character.hp
                elif (
                    not mp_sealed
                    and definition.mp_restore > 0
                    and self.character.mp < maximum_mp
                ):
                    used = min(remaining, maximum_mp - self.character.mp)
                    self.character.mp += used
                    restored_mp += used
                    updates[StatType.MP] = self.character.mp
                if used <= 0:
                    continue
                remaining -= used
                if remaining <= 0:
                    del self.store.state.auto_consume_effects[item_id]
                else:
                    effect["remaining"] = remaining
                changed.append((item_id, remaining, total))
            if changed:
                self.last_auto_potion_at = now
                self.store.save()
        if updates:
            self._send_stats(updates)
        for item_id, remaining, total in changed:
            self._send_auto_consume_effect_state(item_id, remaining, total)
        if restored_hp or restored_mp:
            restored = []
            if restored_hp:
                restored.append(f"生命 {restored_hp}")
            if restored_mp:
                restored.append(f"查克拉 {restored_mp}")
            self._send_character_notice(f"灵药自动恢复{'、'.join(restored)}。")

    def _lianzhan_config(self) -> dict[str, Any]:
        raw = GAME_DATA_CATALOG.raw_etc.get("Lianzhan")
        decoded = GAME_DATA_CATALOG._decode_section(raw) if raw is not None else {}
        return decoded if isinstance(decoded, dict) else {}

    def _lianzhan_exp_rate(self) -> int:
        if self.lianzhan_stage <= 0 or self.lianzhan_buff_expires_at <= time.monotonic():
            return 0
        rates = self._lianzhan_config().get("exp")
        return (
            max(0, self._safe_int(rates.get(str(self.lianzhan_stage)), 0))
            if isinstance(rates, dict)
            else 0
        )

    def _send_lianzhan_count(self) -> None:
        count = max(0, min(32767, self.lianzhan_count))
        if self.wire_mode == "original":
            self.send_original_packet(ServerOpcode.LIANZHAN, struct.pack("<Bh", 1, count))
        else:
            self.send_text(f"{op(ServerOpcode.LIANZHAN)}:1:{count}")

    def _send_lianzhan_stage(self) -> None:
        remaining = max(0, round(self.lianzhan_buff_expires_at - time.monotonic()))
        experience_rate = self._lianzhan_exp_rate()
        total_seconds = (
            max(1, self._safe_int(self._lianzhan_config().get("cooldown"), 900))
            if self.lianzhan_stage > 0
            else 0
        )
        self._send_visible(
            f"{op(ServerOpcode.LIANZHAN)}:2:{self.lianzhan_stage}:"
            f"{experience_rate}:{remaining}:{total_seconds}:"
            f"{self.character.character_id}"
        )

    def _refresh_lianzhan(self, now: float | None = None) -> None:
        current = time.monotonic() if now is None else now
        if self.lianzhan_count > 0 and self.lianzhan_last_kill_at > 0:
            intervals = self._lianzhan_config().get("interval")
            interval_ms = (
                self._safe_int(
                    intervals.get(str(min(8, self.lianzhan_count // 100))),
                    15_000,
                )
                if isinstance(intervals, dict)
                else 15_000
            )
            if current - self.lianzhan_last_kill_at >= max(0.5, interval_ms / 1000):
                self.lianzhan_count = 0
                self.store.state.progression.lianzhan_count = 0
                self.store.save()
                self._send_lianzhan_count()
        if self.lianzhan_stage > 0 and self.lianzhan_buff_expires_at <= current:
            self.lianzhan_stage = 0
            self.lianzhan_buff_expires_at = 0.0
            self.store.state.progression.lianzhan_stage = 0
            self.store.state.progression.lianzhan_buff_expires_at = 0
            self.store.save()
            self._send_lianzhan_stage()

    def _advance_lianzhan_kill(self) -> None:
        now = time.monotonic()
        self._refresh_lianzhan(now)
        self.lianzhan_count = min(899, self.lianzhan_count + 1)
        self.lianzhan_last_kill_at = now
        self.store.state.progression.lianzhan_count = self.lianzhan_count
        new_stage = min(8, self.lianzhan_count // 100)
        if new_stage > self.lianzhan_stage:
            self.lianzhan_stage = new_stage
            cooldown = max(
                1,
                self._safe_int(self._lianzhan_config().get("cooldown"), 900),
            )
            self.lianzhan_buff_expires_at = now + cooldown
            self.store.state.progression.lianzhan_stage = self.lianzhan_stage
            self.store.state.progression.lianzhan_buff_expires_at = int(time.time()) + cooldown
            self._send_lianzhan_stage()
            self._send_character_notice(f"达成{self.lianzhan_count}连斩！")
        self.store.save()
        self.store.state.progression.lianzhan_best = max(
            self.store.state.progression.lianzhan_best,
            self.lianzhan_count,
        )
        self._send_lianzhan_count()

    def _consume_parameter_item(
        self, slot: int, definition: ItemDefinition
    ) -> tuple[InventoryItem | None, bool]:
        consumed, removed = self._consume_bag_slot(slot, definition.item_id)
        if consumed is None:
            return None, False
        self.store.save()
        if removed:
            self._send_inventory_clear(slot, InventoryType.BAG)
        else:
            self._send_inventory_update(consumed, from_drop=0)
        return consumed, removed

    def _active_pet_for_item(self) -> PetState | None:
        return next(
            (
                pet
                for pet in self.store.state.pets.values()
                if pet.position == op(PetPosition.ATTACHED)
            ),
            next(
                (
                    pet
                    for pet in self.store.state.pets.values()
                    if pet.position == op(PetPosition.ATTACKING)
                ),
                next(iter(self.store.state.pets.values()), None),
            ),
        )

    def _use_pet_card(self, slot: int, definition: ItemDefinition) -> bool:
        """Create the exact GameData pet template carried by a pet card."""
        source_item = self.store.state.inventory.get(slot)
        if source_item is None or source_item.item_id != definition.item_id:
            return True
        pet_id = max(0, self._safe_int(definition.parameters.get("petid"), 0))
        aptitude = min(
            4,
            max(1, self._safe_int(definition.parameters.get("aptitude"), 1)),
        )
        pet_config = GAME_DATA_CATALOG.get_pet_config(pet_id)
        if pet_id <= 0 or not pet_config:
            self._send_system_chat("宠物卡数据无效，无法使用。")
            return True
        if len(self.store.state.pets) >= self.store.state.pet_capacity:
            self._send_system_chat("宠物栏已满，请先扩充或整理宠物栏。")
            return True
        unique_id = max(self.store.state.pets, default=90_000) + 1
        name = GAME_DATA_CATALOG.get_pet_name(pet_id).translate(SIMPLIFIED_TRANSLATION)
        minimum, _ = GAME_DATA_CATALOG.get_pet_potential_bounds(pet_id, aptitude)
        pet = PetState(
            unique_id=unique_id,
            item_id=pet_id,
            name=name or "神秘通灵兽",
            position=op(PetPosition.BAG),
            aptitude=aptitude,
            can_trade=source_item.can_trade,
            potential_real_atk=minimum,
            potential_real_def=minimum,
            potential_real_dex=minimum,
            potential_real_str=minimum,
            potential_total_atk=minimum,
            potential_total_def=minimum,
            potential_total_dex=minimum,
            potential_total_str=minimum,
            skills={
                skill_id: SkillState(skill_id)
                for skill_id in GAME_DATA_CATALOG.get_pet_default_skills(pet_id)
            },
        )
        with self.store.lock:
            consumed, _ = self._consume_parameter_item(slot, definition)
            if consumed is None:
                return True
            self.store.state.pets[pet.unique_id] = pet
            self.store.save()
        self.send_text(
            f"{op(ServerOpcode.PET_ACTION)}:{op(PetResponseAction.CREATE)}:"
            f"{self._encode_pet_update(pet)}"
        )
        return True

    def _use_pet_blessing(self, slot: int, definition: ItemDefinition) -> bool:
        pet = self._active_pet_for_item()
        if pet is None:
            self._send_system_chat("请先选择一只宠物。")
            return True
        pet_config = GAME_DATA_CATALOG.get_pet_config(pet.item_id)
        info = pet_config.get("info") if isinstance(pet_config.get("info"), dict) else {}
        maximum = max(1, self._safe_int(info.get("maxZhuFu"), 1_000))
        if pet.blessing >= maximum:
            self._send_system_chat("当前宠物的通灵祝福值已经达到上限。")
            return True
        gain = max(0, self._safe_int(definition.parameters.get("zhufu"), 0))
        with self.store.lock:
            consumed, _ = self._consume_parameter_item(slot, definition)
            if consumed is None:
                return True
            pet.blessing = min(maximum, pet.blessing + gain)
            self.store.save()
        self.send_text(
            f"{op(ServerOpcode.PET_ACTION)}:{op(PetResponseAction.UPDATE)}:"
            f"{self._encode_pet_update(pet)}"
        )
        return True

    def _use_cultivation_blessing(
        self,
        slot: int,
        definition: ItemDefinition,
        state_key: str,
        config_name: str,
        server_opcode: ServerOpcode,
    ) -> bool:
        stage = self._cultivation_stage(state_key, 8)
        if stage >= 8:
            self._send_system_chat(f"{state_key}已达到最高阶。")
            return True
        next_config = GAME_DATA_CATALOG.get_cultivation_stage(config_name, stage + 1)
        stage_up = (
            next_config.get("stageUp")
            if isinstance(next_config.get("stageUp"), dict)
            else {}
        )
        maximum = max(1, self._safe_int(stage_up.get("zhufu_show"), 1_000))
        blessing_key = f"{state_key}:祝福"
        current = max(
            0,
            self.store.state.progression.stage_progress.get(blessing_key, 0),
        )
        if current >= maximum:
            self._send_system_chat(f"{state_key}祝福值已经达到上限。")
            return True
        gain = max(0, self._safe_int(definition.parameters.get("zhufu"), 0))
        with self.store.lock:
            consumed, _ = self._consume_parameter_item(slot, definition)
            if consumed is None:
                return True
            self.store.state.progression.stage_progress[blessing_key] = min(
                maximum,
                current + gain,
            )
            self.store.save()
        self._send_cultivation_blessing(server_opcode, state_key)
        return True

    def _use_boss_reel(self, slot: int, definition: ItemDefinition) -> bool:
        """Summon one server-owned boss from the scroll's authored weighted pool."""
        required_map = self._safe_int(definition.parameters.get("map"), 0)
        if required_map <= 0 or self.character.map_id != required_map:
            self._send_system_chat("该封印卷轴不能在当前地图使用。")
            return True
        weighted: list[tuple[int, int]] = []
        for raw_entry in str(definition.parameters.get("boss") or "").split(","):
            raw_id, separator, raw_weight = raw_entry.partition(":")
            template_id = self._safe_int(raw_id, 0)
            weight = max(0, self._safe_int(raw_weight, 0))
            if separator and template_id > 0 and weight > 0:
                weighted.append((template_id, weight))
        if not weighted:
            self._send_system_chat("封印卷轴没有可召唤的首领数据。")
            return True
        roll = self.random.randrange(sum(weight for _, weight in weighted))
        template_id = weighted[-1][0]
        for candidate_id, weight in weighted:
            if roll < weight:
                template_id = candidate_id
                break
            roll -= weight
        monster_definition = GAME_DATA_CATALOG.get_monster_definition(template_id)
        object_id = max(self.monsters, default=20_000) + 1
        x = self.character.x + self.random.randint(-80, 80)
        y = self.character.y
        monster = MonsterState(
            object_id=object_id,
            template_id=template_id,
            x=x,
            y=y,
            foothold=self.character.foothold,
            first_attack=1,
            max_hp=monster_definition.max_hp,
            hp=monster_definition.max_hp,
            experience=monster_definition.experience,
            spawn_x=x,
            spawn_y=y,
            spawn_foothold=self.character.foothold,
            base_max_hp=monster_definition.max_hp,
            base_experience=monster_definition.experience,
            respawn_seconds=24 * 60 * 60,
        )
        self._configure_monster_variant(monster, monster_definition)
        with self.store.lock:
            consumed, _ = self._consume_parameter_item(slot, definition)
            if consumed is None:
                return True
            self.monsters[object_id] = monster
            self.store.save()
        self._send_visible(self._monster_spawn_payload(monster))
        self._send_system_chat("八卦封印卷轴已召唤出首领。")
        return True

    def _choose_hidden_treasure_copy(self, raw_weights: Any) -> int:
        """Choose a FuBen_Hide row from GameData's ``copy:weight`` list."""
        weighted: list[tuple[int, int]] = []
        for raw_row in str(raw_weights or "").split(","):
            raw_copy_id, separator, raw_weight = raw_row.partition(":")
            if not separator:
                continue
            copy_id = self._safe_int(raw_copy_id, 0)
            weight = max(0, self._safe_int(raw_weight, 0))
            if GAME_DATA_CATALOG.hidden_copy_config(copy_id) is not None and weight > 0:
                weighted.append((copy_id, weight))
        if not weighted:
            return 0
        roll = self.random.randrange(sum(weight for _, weight in weighted))
        for copy_id, weight in weighted:
            if roll < weight:
                return copy_id
            roll -= weight
        return weighted[-1][0]

    def _use_hidden_treasure_scroll(
        self,
        slot: int,
        definition: ItemDefinition,
    ) -> bool:
        """Validate the authored party/map rules and enter the hidden treasure copy."""
        params = definition.parameters
        required_map = self._safe_int(params.get("map"), 0)
        required_members = max(1, self._safe_int(params.get("level"), 1))
        if self.active_copy_id is not None or self.active_pve_level:
            self._send_native_server_message("当前已经在副本中，无法使用藏宝卷轴。", 16)
            return True
        if required_map and self.character.map_id != required_map:
            self._send_native_server_message("请先到达藏宝卷轴指定的地图再使用。", 16)
            return True
        if self.hub is None:
            self._send_native_server_message(
                f"该藏宝卷轴需要至少 {required_members} 人组队后由队长使用。",
                16,
            )
            return True
        party = self.hub.party_for(self.character.character_id)
        if party is None or party.leader_id != self.character.character_id:
            self._send_native_server_message("藏宝卷轴只能由队长使用。", 16)
            return True
        members = [
            member
            for member in self.hub.party_sessions(party)
            if member.entered_game
            and member.line_id == self.line_id
            and member.character.map_id == self.character.map_id
            and member.active_copy_id is None
        ]
        if len(members) < required_members:
            self._send_native_server_message(
                f"队伍中需要至少 {required_members} 人同时到达卷轴指定地图。",
                16,
            )
            return True
        copy_id = self._choose_hidden_treasure_copy(params.get("fuben"))
        definition_row = self._copy_definition(copy_id)
        if copy_id <= 0 or definition_row is None:
            self._send_native_server_message("藏宝卷轴的隐藏副本配置缺失。", 16)
            return True
        _, required_level = definition_row
        if any(member.character.level < required_level for member in members):
            self._send_native_server_message(
                f"队伍成员需要全部达到 {required_level} 级。",
                16,
            )
            return True
        with self.store.lock:
            consumed, _ = self._consume_parameter_item(slot, definition)
        if consumed is None:
            return True
        instance_id = self.hub.allocate_copy_instance()
        leader: FakeFlashSession | None = None
        for index, member in enumerate(members):
            member.pending_copy_id = None
            member.pending_copy_enter_at = 0.0
            member._enter_copy_instance(
                copy_id,
                instance_id,
                len(members),
                initialize_instance=index == 0,
            )
            leader = leader or member
        if leader is not None:
            for member in members[1:]:
                member.active_copy_target_kills = leader.active_copy_target_kills
                member.active_copy_kills = leader.active_copy_kills
        return True

    def _authored_gift_reward_rows(
        self, definition: ItemDefinition
    ) -> list[dict[str, int]]:
        """Return common and current-job gift rows without discarding bind metadata."""
        raw_items = definition.parameters.get("items")
        if not isinstance(raw_items, dict):
            return []
        job_group = str((max(0, int(self.character.job)) // 100) * 100)
        groups = [("0", raw_items.get("0"))]
        if job_group != "0":
            groups.append((job_group, raw_items.get(job_group)))
        rewards: list[dict[str, int]] = []
        for group_name, group in groups:
            if not isinstance(group, dict):
                continue
            # AVM2 enumerates integer-like object keys numerically. Captured JSON
            # preserves wire insertion order instead, so following dict order can
            # map a displayed choice (for example Hinata) to a different reward.
            ordered_keys = sorted(
                group,
                key=lambda key: (
                    0,
                    self._safe_int(key, 0),
                )
                if str(key).lstrip("-").isdigit()
                else (1, str(key)),
            )
            for reward_key in ordered_keys:
                raw_reward = group[reward_key]
                if not isinstance(raw_reward, dict):
                    continue
                item_id = self._safe_int(raw_reward.get("id"), 0)
                quantity = self._safe_int(raw_reward.get("count"), 1)
                if item_id <= 0 or quantity <= 0:
                    continue
                rewards.append(
                    {
                        "item_id": item_id,
                        "quantity": quantity,
                        "weight": max(0, self._safe_int(raw_reward.get("weight"), 0)),
                        "bind": 1 if self._safe_int(raw_reward.get("bind"), 0) else 0,
                        "publish": 1 if self._safe_int(raw_reward.get("pub"), 0) else 0,
                        "aptitude": min(
                            4, max(0, self._safe_int(raw_reward.get("aptitude"), 0))
                        ),
                        "star": min(19, max(0, self._safe_int(raw_reward.get("star"), 0))),
                        "job": self._safe_int(group_name, 0),
                    }
                )
        return rewards

    def _choose_weighted_gift_reward(
        self, rewards: list[dict[str, int]]
    ) -> dict[str, int] | None:
        if not rewards:
            return None
        total_weight = sum(reward["weight"] for reward in rewards)
        if total_weight <= 0:
            return rewards[self.random.randrange(len(rewards))]
        roll = self.random.randrange(total_weight)
        for reward in rewards:
            roll -= reward["weight"]
            if roll < 0:
                return reward
        return rewards[-1]

    @staticmethod
    def _gift_reward_probability_ppm(
        reward: dict[str, int],
        rewards: list[dict[str, int]],
    ) -> int:
        """Return one random-package row's actual weight share on a ppm scale."""
        if not rewards:
            return 0
        total_weight = sum(max(0, int(row.get("weight", 0))) for row in rewards)
        if total_weight <= 0:
            return round(1_000_000 / len(rewards))
        weight = max(0, int(reward.get("weight", 0)))
        return min(1_000_000, round(weight * 1_000_000 / total_weight))

    def _use_authored_gift_item(
        self,
        slot: int,
        definition: ItemDefinition,
        consume_count: int = 1,
        selection: dict[str, Any] | None = None,
    ) -> int | None:
        """Open deterministic or weighted GameData packages atomically."""
        kind = definition.use_type.lower()
        if kind not in {"libao", "libao_fufei", "libao_rand", "libao_select"}:
            return None
        consume_count = max(1, int(consume_count))
        rewards = self._authored_gift_reward_rows(definition)
        for reward in rewards:
            reward["announcement_probability_ppm"] = (
                self._gift_reward_probability_ppm(reward, rewards)
                if kind == "libao_rand"
                else 1_000_000
            )
        if kind == "libao_select" or (
            kind == "libao_rand" and isinstance(selection, dict)
        ):
            current_job = (max(0, int(self.character.job)) // 100) * 100
            selected_job = self._safe_int(
                selection.get("job") if isinstance(selection, dict) else None,
                -1,
            )
            selected_index = self._safe_int(
                selection.get("index") if isinstance(selection, dict) else None,
                -1,
            )
            if (
                selected_job not in {0, current_job}
                or selected_index < 0
                or selected_index >= len(rewards)
                or rewards[selected_index]["job"] != selected_job
            ):
                self._send_character_notice(
                    "\u8bf7\u5148\u5728\u81ea\u9009\u793c\u5305\u4e2d\u9009\u62e9\u4e00\u4ef6\u5956\u52b1\u3002"
                )
                return 0
            rewards = [rewards[selected_index]]
            # A manually selected reward has no random rarity, even when the
            # client reuses libao_rand for a choice-shaped package window.
            rewards[0]["announcement_probability_ppm"] = 1_000_000
        elif kind == "libao_rand":
            grouped: dict[tuple[int, int, int, int, int, int], dict[str, int]] = {}
            for _ in range(consume_count):
                selected = self._choose_weighted_gift_reward(rewards)
                if selected is None:
                    continue
                key = (
                    selected["item_id"],
                    selected["bind"],
                    selected["publish"],
                    selected["aptitude"],
                    selected["star"],
                    selected["announcement_probability_ppm"],
                )
                row = grouped.setdefault(key, dict(selected, quantity=0))
                row["quantity"] += selected["quantity"]
            rewards = list(grouped.values())
        elif consume_count > 1:
            rewards = [
                dict(reward, quantity=reward["quantity"] * consume_count)
                for reward in rewards
            ]
        capacity_rows = [
            (reward["item_id"], reward["quantity"])
            for reward in rewards
        ]
        if not self._has_inventory_capacity(capacity_rows):
            self._send_character_notice("背包空间不足，无法打开礼包。")
            return 0
        granted: list[tuple[InventoryItem, bool, dict[str, int]]] = []
        with self.store.lock:
            consumed = self.store.state.inventory.get(slot)
            if (
                consumed is None
                or consumed.item_id != definition.item_id
                or consumed.quantity < consume_count
            ):
                return 0
            consumed.quantity -= consume_count
            removed = consumed.quantity == 0
            if removed:
                del self.store.state.inventory[slot]
            for reward in rewards:
                is_equipment = GAME_DATA_CATALOG.is_equipment_item(reward["item_id"])
                grant_counts = [1] * reward["quantity"] if is_equipment else [reward["quantity"]]
                for grant_count in grant_counts:
                    item, created = self._add_inventory_item(
                        reward["item_id"],
                        grant_count,
                        can_trade=not bool(reward["bind"]),
                    )
                    if item.item_id in KUN_CHONG_ITEM_IDS and reward["aptitude"] > 0:
                        self._apply_kun_chong_profile(
                            item, reward["aptitude"], reward["star"]
                        )
                    granted.append(
                        (
                            item,
                            created,
                            dict(reward, quantity=grant_count),
                        )
                    )
            self.store.state.money += definition.money_reward * consume_count
            self.store.state.coupon_money += definition.coupon_reward * consume_count
            self.store.save()
        if removed:
            self._send_inventory_clear(slot, InventoryType.BAG)
        else:
            self._send_inventory_update(consumed, from_drop=0)
        for item, created, reward in granted:
            if created:
                self._send_inventory_add(item, from_drop=0)
            else:
                self._send_inventory_update(item, from_drop=0)
            if self._should_announce_reward_probability(
                reward.get("announcement_probability_ppm", 0)
            ):
                reward_definition = GAME_DATA_CATALOG.get_item_definition(
                    reward["item_id"]
                )
                reward_name = (
                    reward_definition.name
                    if reward_definition is not None
                    else "稀有物品"
                )
                self._broadcast_rare_reward(
                    definition.name,
                    reward_name,
                    reward["quantity"],
                    source_kind="gift",
                )
        updates: dict[StatType, int] = {}
        if definition.money_reward:
            updates[StatType.MONEY] = self.store.state.money
        if definition.coupon_reward:
            updates[StatType.CASH_BIND] = self.store.state.coupon_money
        if updates:
            self._send_stats(updates)
        return consume_count

    def _use_item_request_fields(self, read_str: str) -> list[str]:
        """Split USE_ITEM while preserving the optional AMF3 object as one JSON field."""
        payload = self._strip_timestamp(read_str)
        prefix = f"{op(ClientOpcode.USE_ITEM)}:"
        if payload.startswith(prefix):
            payload = payload[len(prefix) :]
        head = payload.split(":", 2)
        if len(head) < 2:
            return head
        if len(head) == 2:
            return head
        slot, item_id, tail = head
        stripped = tail.lstrip()
        if not stripped.startswith(("{", "[")):
            return [slot, item_id, *tail.split(":")]
        try:
            _, end = json.JSONDecoder().raw_decode(stripped)
        except json.JSONDecodeError:
            return [slot, item_id, *tail.split(":")]
        json_text = stripped[:end]
        remainder = stripped[end:]
        if remainder.startswith(":"):
            remainder = remainder[1:]
        return [slot, item_id, json_text, *(remainder.split(":") if remainder else [])]

    def _use_parameterized_item(self, slot: int, definition: ItemDefinition, selection: dict[str, Any] | None = None) -> bool:
        """Execute direct GameData item types whose complete effect is in params."""
        kind = definition.use_type.lower()
        params = definition.parameters
        pet = self._active_pet_for_item()
        # GameData stores cultivation talismans and experience/yueli pills as
        # ordinary `xiaohao` rows. They are immediate consumables, not buffs.
        exp_gain = self._safe_int(params.get("exp"), 0)
        if kind == "xiaohao" and exp_gain > 0:
            with self.store.lock:
                consumed, _ = self._consume_parameter_item(slot, definition)
                if consumed is None:
                    return True
            self._grant_experience(exp_gain, apply_item_effect=False)
            self._send_character_notice(f"\u83b7\u5f97\u7ecf\u9a8c {exp_gain}")
            return True
        yueli_gain = self._safe_int(params.get("yueli"), 0)
        if kind == "xiaohao" and yueli_gain > 0:
            with self.store.lock:
                consumed, _ = self._consume_parameter_item(slot, definition)
                if consumed is None:
                    return True
                self.store.state.progression.pve_points += yueli_gain
                self.store.save()
            self._send_pve_status()
            self._send_character_notice(f"获得阅历 {yueli_gain}")
            return True
        if kind == "petcard":
            return self._use_pet_card(slot, definition)
        if kind == "zhufu":
            return self._use_pet_blessing(slot, definition)
        cultivation_blessings = {
            "rouquan_zhufu": ("柔拳", "RouQuan", ServerOpcode.ROU_QUAN),
            "xielunyan_zhufu": (
                "写轮眼",
                "XieLunYan",
                ServerOpcode.XIELUNYAN_ACTION,
            ),
            "lunhuiyan_zhufu": (
                "轮眼",
                "LunHuiYan",
                ServerOpcode.LUN_HUI_YAN,
            ),
        }
        blessing_target = cultivation_blessings.get(kind)
        if blessing_target is not None:
            state_key, config_name, server_opcode = blessing_target
            return self._use_cultivation_blessing(
                slot,
                definition,
                state_key,
                config_name,
                server_opcode,
            )
        if kind == "boss_reel":
            return self._use_boss_reel(slot, definition)
        if kind == "tan_xian":
            return self._use_hidden_treasure_scroll(slot, definition)
        if kind == "zhenqi" and self._safe_int(params.get("full"), 0):
            amount = max(0, self._safe_int(params.get("capacity"), 0))
            with self.store.lock:
                consumed, _ = self._consume_parameter_item(slot, definition)
                if consumed is None:
                    return True
                self._add_zq(amount)
                self.store.save()
            self._send_stats({StatType.ZQ: self.character.zq})
            return True
        if kind == "qiandai" and self._safe_int(params.get("full"), 0):
            amount = max(0, self._safe_int(params.get("capacity"), 0))
            with self.store.lock:
                consumed, _ = self._consume_parameter_item(slot, definition)
                if consumed is None:
                    return True
                self.store.state.money += amount
                self.store.save()
            self._send_stats({StatType.MONEY: self.store.state.money})
            return True
        if kind == "huicheng":
            if self._is_in_combat(time.monotonic()):
                self._send_system_chat("战斗中不能使用回城卷轴。")
                return True
            with self.store.lock:
                consumed, _ = self._consume_parameter_item(slot, definition)
            if consumed is not None:
                self._warp_to_map(100_000_000)
            return True
        if kind == "xidian":
            baseline = self._level_attribute_baseline()
            current = self._base_attributes()
            refunded = sum(
                max(0, value - minimum)
                for value, minimum in zip(current, baseline)
            )
            if refunded <= 0:
                self._send_native_server_message("当前没有已分配的潜能点需要重洗。", 16)
                return True
            with self.store.lock:
                consumed, _ = self._consume_parameter_item(slot, definition)
                if consumed is None:
                    return True
                (
                    self.character.ap_atk,
                    self.character.ap_def,
                    self.character.ap_dex,
                    self.character.ap_phy,
                ) = baseline
                self.character.remaining_ap += refunded
                self.store.save()
            self._send_attribute_stats()
            self._send_system_chat(f"洗点成功，返还 {refunded} 点潜能。")
            return True
        if kind == "lianzhan_extend":
            if self.lianzhan_stage <= 0 or self.lianzhan_buff_expires_at <= time.monotonic():
                self._send_system_chat("当前没有可延长的连斩增益。")
                return True
            extension = max(1, self._safe_int(params.get("interval"), 1800))
            with self.store.lock:
                consumed, _ = self._consume_parameter_item(slot, definition)
                if consumed is None:
                    return True
            self.lianzhan_buff_expires_at += extension
            self.store.state.progression.lianzhan_buff_expires_at = int(time.time()) + max(
                0, round(self.lianzhan_buff_expires_at - time.monotonic())
            )
            self.store.save()
            self._send_lianzhan_stage()
            return True
        if kind == "shoulijian":
            self._train_an_qi(use_all=False)
            return True
        if kind == "lunhuiyan_jingpo":
            gain = max(0, self._safe_int(params.get("jingpo"), 0))
            stage = self._cultivation_stage("轮眼", 8)
            maximum = GAME_DATA_CATALOG.cultivation_progress_requirement("LunHuiYan", stage)
            with self.store.lock:
                consumed, _ = self._consume_parameter_item(slot, definition)
                if consumed is None:
                    return True
                current = self.store.state.progression.stage_progress.get("轮眼", 0)
                self.store.state.progression.stage_progress["轮眼"] = min(
                    maximum, current + gain
                )
                self.store.save()
            self._send_progress_cultivation_state(
                ServerOpcode.LUN_HUI_YAN, "轮眼", "LunHuiYan"
            )
            return True
        if kind in {"pet_potent", "wuxing", "zizhi", "huolishendan", "pet_dream"}:
            if pet is None:
                self._send_system_chat("请先选择一只宠物。")
                return True
            pet_stage = GAME_DATA_CATALOG.pet_stage(pet.item_id)
            if kind == "wuxing" and pet_stage < 8:
                self._send_system_chat("超级悟性符仅限八阶及以上宠物使用。")
                return True
            if kind == "zizhi" and pet_stage < 7:
                self._send_system_chat("超级资质符仅限七阶及以上宠物使用。")
                return True
            if kind == "wuxing" and pet.savvy >= 100:
                self._send_system_chat("当前宠物悟性已经达到满值。")
                return True
            if kind == "pet_dream" and pet.dream >= 100:
                self._send_system_chat("当前宠物梦幻灵珠进度已经达到满值。")
                return True
            selected_attr: str | None = None
            if kind == "pet_potent":
                raw_attr = selection.get("potent") if isinstance(selection, dict) else None
                if raw_attr in {"atk", "def", "dex", "str"}:
                    selected_attr = raw_attr
                else:
                    self._send_system_chat("请选择需要提升的通灵兽属性。")
                    return True
            with self.store.lock:
                consumed, _ = self._consume_parameter_item(slot, definition)
                if consumed is None:
                    return True
                if kind == "pet_potent":
                    attr = selected_attr
                    # Potential charms use GameData gain verbatim. Do not restore
                    # the legacy gain *= 10 multiplier.
                    gain = max(0, self._safe_int(params.get(attr), 0))
                    total_name = f"potential_total_{attr}"
                    real_name = f"potential_real_{attr}"
                    old_real = max(0, getattr(pet, real_name))
                    old_total = max(old_real, getattr(pet, total_name), 0)
                    new_total = old_total + gain
                    setattr(pet, total_name, new_total)
                    setattr(pet, real_name, min(new_total, old_real + gain))
                elif kind == "wuxing":
                    pet.savvy = 100
                elif kind == "zizhi":
                    maximum = GAME_DATA_CATALOG.get_pet_maximum_potential(
                        pet.item_id, pet.aptitude
                    )
                    for attr in ("atk", "def", "dex", "str"):
                        real_name = f"potential_real_{attr}"
                        total_name = f"potential_total_{attr}"
                        target = max(
                            0,
                            maximum,
                            getattr(pet, real_name),
                            getattr(pet, total_name),
                        )
                        setattr(pet, real_name, target)
                        setattr(pet, total_name, target)
                elif kind == "huolishendan":
                    for candidate in self.store.state.pets.values():
                        candidate.fullness = 100
                elif kind == "pet_dream":
                    pet.dream = min(100, pet.dream + 1)
                self.store.save()
            self.send_text(
                f"{op(ServerOpcode.PET_ACTION)}:{op(PetResponseAction.UPDATE)}:"
                f"{self._encode_pet_update(pet)}"
            )
            self._send_all_stats()
            if kind == "pet_dream":
                self._send_character_notice(f"梦幻灵珠进度提升至 {pet.dream}/100。")
            elif kind == "wuxing":
                self._send_character_notice("通灵兽悟性已提升至满值 100。")
            elif kind == "zizhi":
                self._send_character_notice("通灵兽四项潜力已提升至当前满值。")
            elif kind == "pet_potent":
                attr_name = {"atk": "攻击", "def": "防御", "dex": "灵巧", "str": "健体"}.get(selected_attr, "")
                self._send_character_notice(f"通灵兽{attr_name}潜力与潜力上限均已提升。")
            return True
        if kind == "vip_card":
            now = int(time.time())
            with self.store.lock:
                consumed, _ = self._consume_parameter_item(slot, definition)
                if consumed is None:
                    return True
                was_active = self._has_active_vip(now)
                if not was_active or self.store.state.vip_item_id <= 0:
                    self.store.state.vip_item_id = definition.item_id
                current_expiry = self.store.state.vip_expires_at if was_active else now
                duration_days = max(1, self._safe_int(params.get("expiredays"), 1))
                self.store.state.vip_expires_at = max(now, current_expiry) + duration_days * 86_400
                self.character.vip = True
                self.store.save()
            self._send_vip_status()
            return True
        if kind == "level_up":
            with self.store.lock:
                consumed, _ = self._consume_parameter_item(slot, definition)
            if consumed is not None:
                self._grant_experience(self._experience_required_for_level(self.character.level))
            return True
        if kind == "shemian":
            with self.store.lock:
                consumed, _ = self._consume_parameter_item(slot, definition)
                if consumed is None:
                    return True
                previous_crime = self.character.crime
                self.character.crime = max(
                    0, previous_crime - self._safe_int(params.get("value"), 0)
                )
                self.store.save()
            if self.character.crime != previous_crime:
                self._send_crime_update()
            return True
        if kind == "damoshi":
            with self.store.lock:
                consumed, _ = self._consume_parameter_item(slot, definition)
                if consumed is None:
                    return True
                equipment = [item for pos, item in self.store.state.inventory.items() if pos < 0]
                for item in equipment:
                    item.endure = item.max_endure
                self.store.save()
            for item in equipment:
                self._send_inventory_update(item, from_drop=0)
            return True
        if kind == "addattr":
            gain = max(0, self._safe_int(params.get("randomAddAttrValue"), 0))
            with self.store.lock:
                consumed, _ = self._consume_parameter_item(slot, definition)
                if consumed is None:
                    return True
                attr = self.random.choice(("ap_atk", "ap_def", "ap_dex", "ap_phy"))
                setattr(self.character, attr, getattr(self.character, attr) + gain)
                self.store.save()
            self._send_all_stats()
            return True
        return False

    def _editor_runtime_context(self, extra: dict[str, Any] | None = None) -> dict[str, Any]:
        """Expose a small, read-only value set to the no-code condition interpreter."""
        context = {
            "level": self.character.level,
            "vip_level": self._effective_vip_level(),
            "map_id": self.character.map_id,
            "job": self.character.job,
            "money": self.store.state.money,
            "cash": self.store.state.cash_money,
            "coupon": self.store.state.coupon_money,
            "has_family": self._current_family() is not None,
            "has_party": self.hub is not None and self.hub.party_for(self.character.character_id) is not None,
        }
        context.update(extra or {})
        return context

    def _editor_buff_bonus(self, stat_name: str) -> int:
        now = time.monotonic()
        expired = [buff_id for buff_id, (due_at, _) in self.editor_buffs.items() if due_at and due_at <= now]
        for buff_id in expired:
            self.editor_buffs.pop(buff_id, None)
        total = 0.0
        for _, config in self.editor_buffs.values():
            for modifier in config.get("modifiers", []):
                if isinstance(modifier, dict) and modifier.get("stat") == stat_name:
                    total += float(modifier.get("value") or 0)
        return round(total)

    def _apply_editor_buff(self, buff_id: str) -> None:
        config = EDITOR_RUNTIME.entity("buffs", buff_id)
        if not config or config.get("enabled") is not True:
            return
        duration = max(0, self._safe_int(config.get("durationSeconds"), 0))
        self.editor_buffs[buff_id] = (time.monotonic() + duration if duration else 0.0, config)
        text = str(config.get("startText") or "")
        if text:
            self._send_character_notice(text)
        self._send_all_stats()

    def _execute_editor_actions(self, actions: Any, context: dict[str, Any], depth: int = 0) -> bool:
        """Execute validated no-code actions; arbitrary source code is never evaluated."""
        if not isinstance(actions, list) or depth > 4:
            return False
        changed = False
        for action in actions[:64]:
            if not isinstance(action, dict):
                continue
            action_type = str(action.get("type") or "")
            amount = max(0, self._safe_int(action.get("amount", action.get("value", 0)), 0))
            if action_type == "发送提示":
                self._send_character_notice(str(action.get("text") or ""))
            elif action_type == "发送公告":
                self._send_scrolled_announcement(str(action.get("text") or ""))
            elif action_type in {"增加金币", "扣除金币", "增加元宝", "增加点券"}:
                with self.store.lock:
                    if action_type == "增加金币":
                        self.store.state.money += amount
                    elif action_type == "扣除金币":
                        self.store.state.money = max(0, self.store.state.money - amount)
                    elif action_type == "增加元宝":
                        self.store.state.cash_money += amount
                    else:
                        self.store.state.coupon_money += amount
                    self.store.save()
                changed = True
            elif action_type in {"恢复生命", "恢复查克拉"}:
                with self.store.lock:
                    if action_type == "恢复生命":
                        self.character.hp = min(self._current_max_hp(), self.character.hp + amount)
                    else:
                        self.character.mp = min(self._current_max_mp(), self.character.mp + amount)
                    self.store.save()
                changed = True
            elif action_type == "增加经验" and amount:
                self._grant_experience(amount)
                changed = True
            elif action_type == "发放物品":
                item_id = self._safe_int(action.get("itemId"), 0)
                quantity = max(1, self._safe_int(action.get("count"), 1))
                if GAME_DATA_CATALOG.get_item_definition(item_id) is not None:
                    with self.store.lock:
                        item, created = self._add_inventory_item(item_id, quantity)
                        item.bound = bool(action.get("bound", True))
                        self.store.save()
                    self._send_inventory_add(item, from_drop=0) if created else self._send_inventory_update(item, from_drop=0)
                    changed = True
            elif action_type == "移除物品":
                item_id = self._safe_int(action.get("itemId"), 0)
                remaining = max(1, self._safe_int(action.get("count"), 1))
                for slot, item in list(self.store.state.inventory.items()):
                    if item.item_id != item_id or remaining <= 0:
                        continue
                    removed = min(item.quantity, remaining)
                    item.quantity -= removed
                    remaining -= removed
                    if item.quantity <= 0:
                        del self.store.state.inventory[slot]
                        self._send_inventory_clear(slot, InventoryType.BAG)
                    else:
                        self._send_inventory_update(item, from_drop=0)
                    changed = True
                if changed:
                    self.store.save()
            elif action_type == "应用Buff":
                self._apply_editor_buff(str(action.get("buffId") or ""))
                changed = True
            elif action_type == "移除Buff":
                self.editor_buffs.pop(str(action.get("buffId") or ""), None)
                self._send_all_stats()
                changed = True
            elif action_type == "传送":
                map_id = self._safe_int(action.get("mapId"), 0)
                if map_id in GAME_DATA_CATALOG.map_names:
                    raw_x = action.get("x")
                    raw_y = action.get("y")
                    exact = (
                        (self._safe_int(raw_x, 0), self._safe_int(raw_y, 0))
                        if raw_x is not None and raw_y is not None
                        else None
                    )
                    self._warp_to_map(map_id, exact_position=exact)
                    changed = True
            elif action_type in {"开始任务", "完成任务"}:
                quest_id = self._safe_int(action.get("questId"), 0)
                definition = GAME_DATA_CATALOG.get_quest_definition(quest_id)
                if definition is not None and action_type == "开始任务" and self._can_start_original_quest(definition):
                    self._start_original_quest(definition)
                    changed = True
                elif definition is not None and action_type == "完成任务":
                    progress = self.store.state.original_quests.get(quest_id)
                    if progress is not None:
                        progress.state = int(QuestState.READY_TO_COMPLETE)
                        self._complete_original_quest(definition, definition.end_npc_id, show_dialog=False)
                        changed = True
            elif action_type == "触发事件":
                self._run_editor_event(str(action.get("eventId") or ""), context, depth + 1)
                changed = True
        if changed:
            self._send_all_stats()
        return changed

    def _run_editor_event(self, event_id: str, context: dict[str, Any], depth: int = 0) -> bool:
        config = EDITOR_RUNTIME.entity("automation_events", event_id)
        if not config or config.get("enabled") is not True:
            return False
        now = time.monotonic()
        if now < self.editor_event_cooldowns.get(event_id, 0.0):
            return False
        if not conditions_match(config.get("conditions", []), context):
            return False
        cooldown = max(0.0, float(config.get("cooldownSeconds") or 0))
        self.editor_event_cooldowns[event_id] = now + cooldown
        return self._execute_editor_actions(config.get("actions", []), context, depth)

    def _trigger_editor_events(self, trigger: str, extra: dict[str, Any] | None = None) -> None:
        context = self._editor_runtime_context(extra)
        rows = EDITOR_RUNTIME.entities("automation_events")
        ordered = sorted(rows.items(), key=lambda row: self._safe_int(row[1].get("priority"), 100))
        for event_id, config in ordered:
            if config.get("trigger") == trigger:
                self._run_editor_event(event_id, context)

    def _use_editor_item_effect(self, slot: int, item_id: int) -> bool:
        config = EDITOR_RUNTIME.entity("item_effects", item_id)
        if not config or config.get("enabled") is not True:
            return False
        context = self._editor_runtime_context({
            "item_id": item_id,
            "item_count": sum(item.quantity for item in self.store.state.inventory.values() if item.item_id == item_id),
        })
        if not conditions_match(config.get("conditions", []), context):
            self._send_character_notice(str(config.get("failureText") or "当前条件不满足，无法使用。"))
            return True
        if config.get("consume", True):
            with self.store.lock:
                consumed, removed = self._consume_bag_slot(slot, item_id)
                if consumed is None:
                    return True
                self.store.save()
            self._send_inventory_clear(slot, InventoryType.BAG) if removed else self._send_inventory_update(consumed, from_drop=0)
        self._execute_editor_actions(config.get("actions", []), context)
        self._trigger_editor_events("使用物品", {**context, "item_id": item_id})
        return True

    def _use_legacy_ration_pill(
        self,
        slot: int,
        item_id: int,
        consume_count: int,
    ) -> None:
        stat_names = ("攻击", "防御", "灵巧", "健体")
        stat_keys = ("ap_atk", "ap_def", "ap_dex", "ap_phy")
        with self.store.lock:
            item = self.store.state.inventory.get(slot)
            if item is None or item.item_id != item_id or item.quantity <= 0:
                return
            consume_count = max(1, min(consume_count, item.quantity))
            index = self.random.randrange(len(stat_keys))
            key = stat_keys[index]
            gain = RATION_PILL_RANDOM_ATTRIBUTE_GAIN * consume_count
            setattr(self.character, key, max(0, int(getattr(self.character, key, 0))) + gain)
            item.quantity -= consume_count
            removed = item.quantity == 0
            if removed:
                del self.store.state.inventory[slot]
            self.store.save()
        if removed:
            self._send_inventory_clear(slot, InventoryType.BAG)
        else:
            self._send_inventory_update(item, from_drop=0)
        self._send_all_stats()
        self._send_character_notice(f"使用兵粮丸，{stat_names[index]}永久增加 {gain} 点。")
        self._advance_original_quests(
            QuestObjectiveKind.USE_ITEM,
            item_id,
            amount=consume_count,
            map_id=self.character.map_id,
        )
        self._refresh_all_original_quests()

    def handle_use_item(self, read_str: str) -> None:
        """Apply original consumables, player/pet books, and pet skill-reset items."""
        if self._is_dead():
            return
        fields = self._use_item_request_fields(read_str)
        if len(fields) < 2:
            return
        slot = self._safe_int(fields[0], 0)
        requested_item_id = self._safe_int(fields[1], 0)
        definition = GAME_DATA_CATALOG.get_item_definition(requested_item_id)
        if definition is None or self.character.level < definition.required_level:
            return
        if definition.mp_restore > 0 and self._is_mp_sealed():
            self._send_item_cooldown(requested_item_id, 0, 0)
            self._send_system_chat("五行封印期间无法使用回复查克拉的药品。")
            return
        if self.arena_opponent is not None and (
            definition.hp_restore
            or definition.mp_restore
            or definition.use_type.lower() == "zidong"
        ):
            self._send_dynamic_info("竞技场内不能使用回复类药品。")
            return
        use_all_requested = len(fields) > 3 and fields[3].strip().lower() == "true"
        inventory_item = self.store.state.inventory.get(slot)
        is_auto_consume_elixir = definition.use_type.lower() == "zidong"
        consume_count = (
            inventory_item.quantity
            if (
                use_all_requested
                and definition.use_all
                and inventory_item is not None
                and inventory_item.item_id == requested_item_id
            )
            else 1
        )
        if self._use_editor_item_effect(slot, requested_item_id):
            return
        if requested_item_id == LEGACY_RATION_PILL_ITEM_ID:
            self._use_legacy_ration_pill(slot, requested_item_id, consume_count)
            return
        if definition.section == "ShenQi" and slot > 0:
            equipment = GAME_DATA_CATALOG.get_equipment_definition(requested_item_id)
            if equipment is not None:
                self.handle_item_move(
                    f"{op(ClientOpcode.ITEM_MOVE)}:0:{slot}:{op(equipment.position)}"
                )
            return
        if definition.use_type.lower() == "rouquan" or self._is_rouquan_progress_item(
            requested_item_id
        ):
            self._use_rouquan_progress_item(slot, requested_item_id, consume_count)
            return
        if definition.use_type.lower() == "jinghun" or self._is_xielunyan_progress_item(
            requested_item_id
        ):
            self._use_xielunyan_progress_item(slot, requested_item_id, consume_count)
            return
        # Life/chakra elixirs load a persistent recovery capacity. They must be
        # usable while resources are full and are not ordinary auto-potions,
        # so neither the auto-use threshold nor the shared potion CD applies.
        if is_auto_consume_elixir:
            self._use_auto_consume_item(slot, definition, consume_count)
            return
        restorative = bool(definition.hp_restore or definition.mp_restore)
        use_started_at = int(time.time() * 1_000)
        persisted_item_cooldowns = self.store.state.item_cooldowns
        if restorative and (
            use_started_at < persisted_item_cooldowns.get(-1, 0)
            or use_started_at < persisted_item_cooldowns.get(requested_item_id, 0)
        ):
            self._send_item_cooldown(requested_item_id, 0, 0)
            return
        if definition.use_type in {"shuxing", "shuangbei", "bianshen"}:
            self._use_timed_item_effect(slot, definition, consume_count)
            return
        gift_selection: dict[str, Any] | None = None
        if len(fields) > 2 and fields[2] not in {"", "-", "null"}:
            try:
                decoded_selection = json.loads(fields[2])
                if isinstance(decoded_selection, dict):
                    gift_selection = decoded_selection
            except json.JSONDecodeError:
                pass
        if definition.use_type == "jineng" and requested_item_id == 15018001:
            self._use_pet_skill_symbol(
                slot,
                definition,
                gift_selection if isinstance(gift_selection, dict) else {},
            )
            return
        gift_consumed = self._use_authored_gift_item(
            slot,
            definition,
            consume_count,
            gift_selection,
        )
        if gift_consumed is not None:
            if gift_consumed > 0:
                self._advance_original_quests(
                    QuestObjectiveKind.USE_ITEM,
                    requested_item_id,
                    amount=gift_consumed,
                    map_id=self.character.map_id,
                )
                self._refresh_all_original_quests()
            return
        initial_quantity = (
            inventory_item.quantity
            if inventory_item is not None and inventory_item.item_id == requested_item_id
            else 0
        )
        if self._use_parameterized_item(slot, definition, gift_selection):
            consumed_count = max(
                0,
                initial_quantity
                - (
                    current.quantity
                    if (
                        (current := self.store.state.inventory.get(slot)) is not None
                        and current.item_id == requested_item_id
                    )
                    else 0
                ),
            )
            while consumed_count < consume_count:
                current = self.store.state.inventory.get(slot)
                if current is None or current.item_id != requested_item_id:
                    break
                before = current.quantity
                if not self._use_parameterized_item(slot, definition, gift_selection):
                    break
                current = self.store.state.inventory.get(slot)
                after = (
                    current.quantity
                    if current is not None and current.item_id == requested_item_id
                    else 0
                )
                if after >= before:
                    break
                consumed_count += before - after
            if consumed_count:
                self._advance_original_quests(
                    QuestObjectiveKind.USE_ITEM,
                    requested_item_id,
                    amount=consumed_count,
                    map_id=self.character.map_id,
                )
                self._refresh_all_original_quests()
            return
        pet_unique_id = self._safe_int(fields[4], 0) if len(fields) > 4 else 0
        old_pet_skill = self._safe_int(fields[5], 0) if len(fields) > 5 else 0
        new_pet_skill = self._safe_int(fields[6], 0) if len(fields) > 6 else 0
        if pet_unique_id and old_pet_skill and new_pet_skill:
            self._reset_pet_skill(
                slot, requested_item_id, pet_unique_id, old_pet_skill, new_pet_skill
            )
            return
        if definition.skill_id > 0:
            if requested_item_id // 1_000_000 == 7:
                pet = next(
                    (
                        value
                        for value in self.store.state.pets.values()
                        if value.position != op(PetPosition.BAG)
                    ),
                    next(iter(self.store.state.pets.values()), None),
                )
                if pet is not None:
                    self._learn_pet_skill(pet, requested_item_id, slot)
                    self._send_all_stats()
                return
            skill_definition = GAME_DATA_CATALOG.get_skill_definition(definition.skill_id)
            if skill_definition is not None:
                self._learn_skill(skill_definition, selected_slot=slot)
            return
        if not (
            definition.hp_restore
            or definition.mp_restore
            or definition.contents
            or definition.money_reward
            or definition.coupon_reward
        ):
            self._send_system_chat(f"{definition.name}是材料或任务物品，不能直接使用。")
            return
        restores_hp = definition.hp_restore > 0 and self.character.hp < self._current_max_hp()
        restores_mp = definition.mp_restore > 0 and self.character.mp < self._current_max_mp()
        config = self.store.state.character_config
        maximum_hp = self._current_max_hp()
        maximum_mp = self._current_max_mp()
        hp_threshold = max(1, min(99, self._config_int(config, "auotReplyHpValue", 70)))
        mp_threshold = max(1, min(99, self._config_int(config, "auotReplyMpValue", 50)))
        auto_use_requested = bool(
            restorative
            and len(fields) > 3
            and fields[3].strip().lower() == "true"
        )
        auto_use = auto_use_requested and bool(
            (
                restores_hp
                and self._config_bool(config, "autoReplyHp", True)
                and self.character.hp * 100 <= maximum_hp * hp_threshold
            )
            or (
                restores_mp
                and self._config_bool(config, "autoReplyMp", True)
                and self.character.mp * 100 <= maximum_mp * mp_threshold
            )
        )
        if auto_use_requested and not auto_use:
            # The client can make this decision from a stale/clipped WarpToMap HP
            # value.  Return authoritative resource pairs together with the
            # cancelled use so its bar and automatic-item poll converge at once.
            self._send_authoritative_resources(
                include_hp=definition.hp_restore > 0,
                include_mp=definition.mp_restore > 0,
            )
            self._send_item_cooldown(requested_item_id, 0, 0)
            return
        if (
            (definition.hp_restore or definition.mp_restore)
            and not restores_hp
            and not restores_mp
            and not definition.contents
            and not definition.money_reward
            and not definition.coupon_reward
        ):
            # Cancel the client's pending-use overlay without consuming the stack.
            self._send_item_cooldown(requested_item_id, 0, 0)
            return
        with self.store.lock:
            item = self.store.state.inventory.get(slot)
            if item is None or item.item_id != requested_item_id or item.quantity <= 0:
                return
            if definition.contents and not self._has_inventory_capacity(
                [
                    (item_id, quantity * consume_count)
                    for item_id, quantity in definition.contents
                ]
            ):
                self._send_system_chat("背包空间不足，无法打开礼包。")
                return
            consume_count = min(consume_count, item.quantity)
            hp_before = self.character.hp
            mp_before = self.character.mp
            item.quantity -= consume_count
            self.character.hp = min(
                self._current_max_hp(),
                self.character.hp + definition.hp_restore,
            )
            self.character.mp = min(
                self._current_max_mp(),
                self.character.mp + definition.mp_restore,
            )
            removed = item.quantity == 0
            if removed:
                del self.store.state.inventory[slot]
            self.store.state.money += definition.money_reward * consume_count
            self.store.state.coupon_money += definition.coupon_reward * consume_count
            rewards = [
                self._add_inventory_item(item_id, quantity * consume_count)
                for item_id, quantity in definition.contents
            ]
            if restorative:
                self.store.state.item_cooldowns[-1] = use_started_at + round(
                    self.ITEM_PUBLIC_COOLDOWN_SECONDS * 1_000
                )
                self.store.state.item_cooldowns[requested_item_id] = (
                    use_started_at + round(self.ITEM_SERVER_COOLDOWN_SECONDS * 1_000)
                )
            self.store.save()
        if removed:
            self._send_inventory_clear(slot, InventoryType.BAG)
        else:
            self._send_inventory_update(item, from_drop=0)
        for reward, created in rewards:
            if created:
                self._send_inventory_add(reward, from_drop=0)
            else:
                self._send_inventory_update(reward, from_drop=0)
        updates: dict[StatType, int] = {}
        if definition.hp_restore:
            updates[StatType.HP] = self.character.hp
        if definition.mp_restore:
            updates[StatType.MP] = self.character.mp
        if definition.money_reward:
            updates[StatType.MONEY] = self.store.state.money
        if definition.coupon_reward:
            updates[StatType.CASH_BIND] = self.store.state.coupon_money
        if updates:
            self._send_stats(updates)
        if restorative:
            self._share_bond_potion(
                definition.hp_restore,
                definition.mp_restore,
            )
        if restorative:
            self._send_item_cooldown(
                requested_item_id,
                0,
                int(self.ITEM_SERVER_COOLDOWN_SECONDS),
            )
            if auto_use:
                restored: list[str] = []
                if self.character.hp > hp_before:
                    restored.append(f"生命 {self.character.hp - hp_before}")
                if self.character.mp > mp_before:
                    restored.append(f"查克拉 {self.character.mp - mp_before}")
                if restored:
                    self._send_character_notice(
                        f"自动使用{definition.name}，恢复{'、'.join(restored)}。"
                    )
        if definition.coupon_reward:
            self.handle_cash_money("")
        self._advance_original_quests(
            QuestObjectiveKind.USE_ITEM,
            requested_item_id,
            amount=consume_count,
            map_id=self.character.map_id,
        )
        self._refresh_all_original_quests()

    def _reset_pet_skill(
        self,
        slot: int,
        item_id: int,
        pet_unique_id: int,
        old_skill_id: int,
        new_skill_id: int,
    ) -> None:
        """Consume the selected reset item and replace one learned pet skill."""
        pet = self.store.state.pets.get(pet_unique_id)
        if pet is None or old_skill_id not in pet.skills or new_skill_id <= 0:
            return
        with self.store.lock:
            consumed, removed = self._consume_bag_slot(slot, item_id)
            if consumed is None:
                return
            previous = pet.skills.pop(old_skill_id)
            pet.skills[new_skill_id] = SkillState(
                skill_id=new_skill_id,
                level=previous.level,
                master_level=previous.master_level,
            )
            self.store.save()
        if removed:
            self._send_inventory_clear(consumed.slot, InventoryType.BAG)
        else:
            self._send_inventory_update(consumed, from_drop=0)
        self._send_pet_skill_list(pet)
        self._send_all_stats()

    def handle_skill_change(self, read_str: str) -> None:
        """Learn a common passive or job skill and refresh derived attributes."""
        fields = self._request_fields(read_str, ClientOpcode.SKILL_CHANGE)
        if len(fields) < 2:
            return
        try:
            action = SkillChangeAction(self._safe_int(fields[0], -1))
        except ValueError:
            return
        skill_id = self._safe_int(fields[1], 0)
        definition = GAME_DATA_CATALOG.get_skill_definition(skill_id)
        if definition is None or not (
            skill_id < 10_000
            or skill_id in COMMON_PROBABILITY_SKILL_IDS
            or skill_id // 10_000 == self.character.job
        ):
            return
        if action == SkillChangeAction.LEARN:
            self._learn_skill(definition)
        elif action == SkillChangeAction.UPGRADE:
            self._upgrade_skill(definition)

    def _send_item_cooldown(self, item_id: int, cool_type: int, seconds: int) -> None:
        """Replay the original item-specific cooldown contract."""
        if self.wire_mode == "original":
            self.send_original_packet(
                ServerOpcode.ITEM_COOLDOWN,
                struct.pack("<iii", item_id, cool_type, seconds),
            )
            return
        self.send_text(
            f"{op(ServerOpcode.ITEM_COOLDOWN)}:{item_id}:{cool_type}:{seconds}"
        )

    def _learn_skill(
        self,
        definition: SkillDefinition,
        selected_slot: int | None = None,
    ) -> None:
        """Consume the configured book and create a level-one persisted skill."""
        with self.store.lock:
            if definition.skill_id in self.store.state.skills:
                self._send_character_notice("该忍术已经学会，无需重复使用技能书。")
                return
            if self.character.level < definition.required_level:
                self._send_system_chat(f"需要达到 {definition.required_level} 级才能学习。")
                return
            requirement_error = self._skill_requirement_error(definition)
            if requirement_error:
                self._send_character_notice(requirement_error)
                return
            consumed_item: InventoryItem | None = None
            removed = False
            if definition.book_item_id > 0:
                if selected_slot is None:
                    consumed_item, removed = self._consume_bag_item(definition.book_item_id)
                else:
                    consumed_item, removed = self._consume_bag_slot(
                        selected_slot,
                        definition.book_item_id,
                    )
                if consumed_item is None:
                    self._send_system_chat("背包里没有学习这个技能所需的技能书。")
                    return
            skill = SkillState(skill_id=definition.skill_id)
            self.store.state.skills[skill.skill_id] = skill
            self.store.save()
        if consumed_item is not None:
            if removed:
                self._send_inventory_clear(consumed_item.slot, InventoryType.BAG)
            else:
                self._send_inventory_update(consumed_item, from_drop=0)
        self._send_skill_update(skill)
        self._send_all_stats()
        book = (
            GAME_DATA_CATALOG.get_item_definition(definition.book_item_id)
            if definition.book_item_id > 0
            else None
        )
        skill_name = book.name if book is not None else "未知忍术"
        for suffix in ("技能书", "忍术书", "秘籍"):
            if skill_name.endswith(suffix):
                skill_name = skill_name[: -len(suffix)]
                break
        if self._is_high_level_skill(definition):
            self._broadcast_system_chat(
                f"[系统]{self.character.name}学习到了高级忍术【{skill_name}】！"
            )
        else:
            self._send_character_notice(f"成功学会忍术【{skill_name}】。")

    @staticmethod
    def _is_high_level_skill(definition: SkillDefinition) -> bool:
        """Match advanced skills whose acquisition is worthy of a world notice."""
        return (
            definition.required_level >= 50
            or definition.required_mai > 0
            or definition.required_xielunyan > 0
            or definition.required_family_contribution > 0
        )

    def _skill_requirement_error(self, definition: SkillDefinition) -> str:
        """Return the first unmet original skill-open requirement."""
        # This client never evaluates info.open.reqSkill. Its authored values
        # (1001010/1001011) do not identify any skill template, so treating them
        # as IDs makes otherwise valid job skills impossible to learn.
        # The four project-authored special skills use real template IDs and
        # therefore enforce their two explicit prerequisite chains here.
        project_prerequisite = self._project_skill_prerequisite(
            definition.skill_id
        )
        if (
            project_prerequisite > 0
            and project_prerequisite not in self.store.state.skills
        ):
            return "请先学习前置特别忍术。"
        current_mai_list = self._current_mai_list_id()
        opened_mai = (
            current_mai_list * 8
            + self._mai_completed_gate_count(current_mai_list)
        )
        if opened_mai < definition.required_mai:
            return f"需要开通 {definition.required_mai} 个八门穴位。"
        xielunyan_stage = max(
            0,
            self.store.state.progression.stages.get("写轮眼", 0),
        )
        if xielunyan_stage < definition.required_xielunyan:
            return f"需要写轮眼达到 {definition.required_xielunyan} 阶。"
        lunhuiyan_stage = self._cultivation_stage("轮眼", 8)
        for required_stage in range(1, 9):
            stage_data = GAME_DATA_CATALOG.get_cultivation_stage(
                "LunHuiYan",
                required_stage,
            )
            raw_skills = str(stage_data.get("skills") or "")
            stage_skills = {
                self._safe_int(value, 0)
                for value in re.findall(r"\d+", raw_skills)
            }
            if definition.skill_id not in stage_skills:
                continue
            if lunhuiyan_stage < required_stage:
                stage_name = str(stage_data.get("name") or f"第 {required_stage} 道")
                return f"需要先解锁轮回六道的{stage_name}。"
            break
        family_contribution = self.store.state.progression.family_contribution
        if family_contribution < definition.required_family_contribution:
            return f"需要家族贡献 {definition.required_family_contribution}。"
        return ""

    def _upgrade_skill(self, definition: SkillDefinition) -> None:
        """Raise a skill after paying coins and the mastery-adjusted essence cost."""
        if definition.skill_id in NON_UPGRADABLE_BOND_SKILL_IDS:
            self._send_character_notice("羁绊忍术随羁绊阶段解锁，不能手动升级。")
            return
        with self.store.lock:
            skill = self.store.state.skills.get(definition.skill_id)
            if skill is None:
                self._send_system_chat("请先学习这个技能。")
                return
            max_level = len(EXP_BY_LEVEL) - 1
            if skill.level >= max_level:
                self._send_system_chat("角色等级不足，暂时不能继续升级这个技能。")
                return
            next_level = skill.level + 1
            if self.character.level < next_level:
                self._send_system_chat(f"角色需要达到 {next_level} 级才能升级这个技能。")
                return
            money_cost, mastery_required = definition.upgrade_requirements(next_level)
            if money_cost <= 0 or mastery_required <= 0:
                return
            current_mastery = max(0, min(skill.master_level, mastery_required))
            essence_cost = mastery_required - current_mastery
            if self.character.zq < essence_cost:
                self._send_system_chat(
                    f"查克拉精华不足，还需要 {essence_cost}点。"
                )
                return
            if self.store.state.money < money_cost:
                self._send_system_chat("金币不足，无法升级技能。")
                return
            self.store.state.money -= money_cost
            self.character.zq -= essence_cost
            skill.level += 1
            skill.master_level = 0
            self.store.save()
        self._send_skill_update(skill)
        self._send_stats(
            {
                StatType.MONEY: self.store.state.money,
                StatType.ZQ: self.character.zq,
            }
        )
        self._send_all_stats()

    def _consume_bag_item(self, item_id: int) -> tuple[InventoryItem | None, bool]:
        """Consume one matching positive-slot item and report whether its stack vanished."""
        for slot, item in list(self.store.state.inventory.items()):
            if slot <= 0 or item.item_id != item_id or item.quantity <= 0:
                continue
            item.quantity -= 1
            removed = item.quantity == 0
            if removed:
                del self.store.state.inventory[slot]
            return item, removed
        return None, False

    def _consume_bag_slot(
        self,
        slot: int,
        expected_item_id: int,
    ) -> tuple[InventoryItem | None, bool]:
        """Consume one item from an exact client-selected bag slot."""
        item = self.store.state.inventory.get(slot)
        if item is None or slot <= 0 or item.item_id != expected_item_id or item.quantity <= 0:
            return None, False
        item.quantity -= 1
        removed = item.quantity == 0
        if removed:
            del self.store.state.inventory[slot]
        return item, removed

    def _send_skill_update(self, skill: SkillState) -> None:
        """Update one skill using SkillInfo.decode2's three ampersand fields."""
        self.send_text(
            f"{op(ServerOpcode.UPDATE_SKILLS)}:"
            f"{skill.skill_id}&{skill.level}&{skill.master_level}"
        )

    def _send_inventory_add(self, item: InventoryItem, from_drop: int) -> None:
        """Add one item using AddInventorySlotInfo.decode2 and CocoItem.decode3."""
        section = self._inventory_item_section(item)
        inventory_type = self._inventory_type_for_position(section, item.slot)
        item_payload = self._encode_item_payload(item)
        self.send_text(
            f"{op(ServerOpcode.MODIFY_INVENTORY_ITEM)}:{op(InventoryUpdateFlag.ADD)}:"
            f"{item_payload}:{from_drop}:{op(inventory_type)}:{item.slot}"
        )
        if item.unique_id in self.pending_equipment_pickups:
            self.pending_equipment_pickups.discard(item.unique_id)
            self._send_equipment_pickup(item)

    def _send_equipment_pickup(self, item: InventoryItem) -> None:
        """Ask the original client to compare a newly acquired player equipment item."""
        if item.slot <= 0 or not GAME_DATA_CATALOG.is_equipment_item(item.item_id):
            return
        self.send_text(
            f"{op(ServerOpcode.EQUIP_PICKUP)}:{item.item_id}:{item.unique_id}"
        )

    def _encode_item_payload(self, item: InventoryItem) -> str:
        """Serialize every ItemCodec family using the original client's field contract."""
        owner = self.character.name.replace("&", "")
        quantity = _safe_item_quantity(item.item_id, item.quantity)
        common_fields: list[int | str] = [
            op(ItemCodecType.ITEM),
            item.item_id,
            item.slot,
            quantity,
            0,
            0,
            int(item.can_trade),
            owner,
            0,
            item.unique_id,
        ]
        item_definition = GAME_DATA_CATALOG.get_item_definition(item.item_id)
        equipment_definition = GAME_DATA_CATALOG.get_equipment_definition(item.item_id)
        section = item_definition.section if item_definition is not None else ""
        if section == "ShenQi" and equipment_definition is not None:
            common_fields[0] = op(ItemCodecType.SHEN_QI)
            base_attributes = "!".join(
                f"{attribute_type}*{value}"
                for attribute_type, value in equipment_definition.template_attributes
            ) or "-"
            holy_attributes = "!".join(
                f"{attribute_type}*{value}*{skill_id}"
                for attribute_type, value, skill_id in equipment_definition.holy_attributes
            ) or "-"
            return "&".join(
                str(value) for value in [*common_fields, base_attributes, holy_attributes]
            )
        if section == "HunJie":
            common_fields[0] = op(ItemCodecType.COUPLE_RING)
            return "&".join(str(value) for value in [*common_fields, 0, "-"])
        if section == "LingQi" and equipment_definition is not None:
            common_fields[0] = op(ItemCodecType.LING_QI)
            plus_attributes = "!".join(
                "*".join(str(value) for value in entry[:2]) for entry in item.plus_attributes
            ) or "-"
            return "&".join(str(value) for value in [*common_fields, plus_attributes])
        if not GAME_DATA_CATALOG.is_equipment_item(item.item_id):
            return "&".join(str(value) for value in common_fields)
        common_fields[0] = op(ItemCodecType.EQUIPMENT)
        plus_attributes = "!".join("*".join(str(value) for value in entry[:2]) for entry in item.plus_attributes) or "-"
        inlays = "!".join("*".join(str(value) for value in entry[:5]) for entry in item.inlays) or "-"
        strength_info = "!".join("true" if value else "false" for value in item.strength_info) or "-"
        equipment_fields: list[int | str] = [
            item.aptitude,
            item.max_endure,
            item.endure,
            item.base_attr_type,
            item.base_attr_value,
            item.born_attr_value,
            item.strength_value,
            plus_attributes,
            item.tale_attr_type,
            item.tale_attr_value,
            item.forge_additive_ratio,
            inlays,
            item.strength_level,
            strength_info,
            item.crash_time,
            item.carve_id,
            item.carve_type,
            item.carve_value,
            item.stageup120_percent,
        ]
        return "&".join(str(value) for value in [*common_fields, *equipment_fields])

    def _send_inventory_update(self, item: InventoryItem, from_drop: int) -> None:
        """Update one stack quantity using UpdateInventorySlotInfo.decode2."""
        quantity = _safe_item_quantity(item.item_id, item.quantity)
        self.send_text(
            f"{op(ServerOpcode.MODIFY_INVENTORY_ITEM)}:{op(InventoryUpdateFlag.UPDATE)}:"
            f"{from_drop}:{item.item_id}:{item.slot}:{quantity}:1:"
            f"{int(item.can_trade)}"
        )

    def _send_inventory_clear(self, slot: int, inventory_type: InventoryType) -> None:
        """Clear one slot using ClearInventoryItemInfo.decode2."""
        self.send_text(
            f"{op(ServerOpcode.MODIFY_INVENTORY_ITEM)}:{op(InventoryUpdateFlag.CLEAR)}:"
            f"false:{op(inventory_type)}:{slot}"
        )

    def _send_equipment_slot_update(self, item: InventoryItem) -> None:
        """Send MODIFY_INVENTORY_ITEM flag 11 so Nya refreshes quick stage-up."""
        if self.wire_mode != "original":
            return
        section = self._inventory_item_section(item)
        inventory_type = self._inventory_type_for_position(section, item.slot)
        body = (
            struct.pack("<B", op(InventoryUpdateFlag.UPDATE_EQUIP_SLOT))
            + struct.pack("<iB", item.slot, inventory_type)
            + self._original_item_payload(item)
        )
        self.send_original_packet(ServerOpcode.MODIFY_INVENTORY_ITEM, body)

    def _refresh_inventory_item(self, item: InventoryItem) -> None:
        """Recreate one item so Flash decodes changed durability and broken state."""
        section = self._inventory_item_section(item)
        inventory_type = self._inventory_type_for_position(section, item.slot)
        self._send_inventory_clear(item.slot, inventory_type)
        self._send_inventory_add(item, from_drop=0)

    def _npc_quest_selections(
        self,
        npc: NpcState,
        include_automatic: bool = False,
    ) -> str:
        """Encode native QuestDialog selection rows for quests related to one NPC."""
        self._refresh_family_quest_period()
        definitions = list(GAME_DATA_CATALOG.quests_for_npc(npc.template_id))
        if include_automatic:
            definitions.extend(
                definition
                for quest_id in GAME_DATA_CATALOG.quest_ids
                if (definition := GAME_DATA_CATALOG.get_quest_definition(quest_id)) is not None
                and definition.supported
                and definition.start_npc_id == 0
            )
        rows: list[str] = []
        if npc.template_id == 27 and self.character.level >= 20:
            self._refresh_ring_quest_periods()
            daily_quest_id = self._active_ring_template_id("daily")
            daily_progress = self.store.state.original_quests.get(daily_quest_id)
            daily_status = (
                2
                if daily_progress is not None
                and QuestState(daily_progress.state) == QuestState.READY_TO_COMPLETE
                else 1 if daily_progress is not None else 0
            )
            weekly_quest_id = self._active_ring_template_id("weekly")
            weekly_progress = self.store.state.original_quests.get(weekly_quest_id)
            weekly_status = (
                2
                if weekly_progress is not None
                and QuestState(weekly_progress.state) == QuestState.READY_TO_COMPLETE
                else 1 if weekly_progress is not None else 0
            )
            daily_count = self.store.state.ring_daily_count
            if daily_count < 20 or daily_quest_id:
                rows.append(
                    f"每日环任务&8001&"
                    f"{daily_status}&"
                    f"{min(daily_count + 1, 20)}&20&8001"
                )
            weekly_count = self.store.state.ring_weekly_count
            if self.character.level >= 35 and (
                weekly_count < 100 or weekly_quest_id
            ):
                rows.append(
                    f"周试炼任务&8002&"
                    f"{weekly_status}&"
                    f"{min(weekly_count + 1, 100)}&100&8002"
                )
        escort_definition = GAME_DATA_CATALOG.get_quest_definition(8100)
        escort_start_npc_id = (
            escort_definition.start_npc_id if escort_definition is not None else 23
        )
        if npc.template_id == escort_start_npc_id and self.character.level >= 30:
            escort = self.store.state.original_quests.get(8100)
            finish_count = escort.finish_count if escort is not None else 0
            if finish_count < 3 or (
                escort is not None
                and QuestState(escort.state)
                in (QuestState.ACTIVE, QuestState.READY_TO_COMPLETE)
            ):
                status = 0
                if escort is not None:
                    if QuestState(escort.state) == QuestState.ACTIVE:
                        status = 1
                    elif QuestState(escort.state) == QuestState.READY_TO_COMPLETE:
                        status = 2
                rows.append(
                    f"护送任务&8100&{status}&{min(finish_count + 1, 3)}&3&8100"
                )
            if self.character.level >= 35 and self._current_family() is not None:
                family_progress = self.store.state.original_quests.get(8101)
                family_count = self.store.state.progression.family_quest_count
                family_status = 0
                if family_progress is not None:
                    if QuestState(family_progress.state) == QuestState.ACTIVE:
                        family_status = 1
                    elif QuestState(family_progress.state) == QuestState.READY_TO_COMPLETE:
                        family_status = 2
                if family_count < 5 or family_status:
                    rows.append(
                        f"家族任务&8101&{family_status}&{min(family_count + 1, 5)}&5&8101"
                    )
        escort_end_npc_id = (
            escort_definition.end_npc_id if escort_definition is not None else 75
        )
        escort = self.store.state.original_quests.get(8100)
        if (
            npc.template_id == escort_end_npc_id
            and escort is not None
            and QuestState(escort.state)
            in (QuestState.ACTIVE, QuestState.READY_TO_COMPLETE)
        ):
            rows.append(
                f"护送任务&8100&2&{min(escort.finish_count + 1, 3)}&3&8100"
            )
        for definition in {
            definition.quest_id: definition for definition in definitions
        }.values():
            # Fugaku renders 8001/8002 as wrappers.  Keep private templates
            # hidden everywhere except their receiver once they are complete.
            if 8003 <= definition.quest_id <= 8022:
                progress = self.store.state.original_quests.get(definition.quest_id)
                ring_mode = self._ring_mode_for_quest_id(definition.quest_id)
                if (
                    not ring_mode
                    or progress is None
                    or QuestState(progress.state) != QuestState.READY_TO_COMPLETE
                    or definition.end_npc_id != npc.template_id
                ):
                    continue
                safe_name = definition.name.replace(":", " ").replace("&", " ")
                rows.append(
                    f"{safe_name}&{definition.quest_id}&2&0&0&{definition.quest_id}"
                )
                continue
            if definition.quest_id in {8001, 8002, 8101}:
                continue
            progress = self.store.state.original_quests.get(definition.quest_id)
            status: int | None = None
            if self._can_start_original_quest(definition) and definition.start_npc_id in (
                npc.template_id,
                0 if include_automatic else -1,
            ):
                status = 0
            elif progress is not None:
                state = QuestState(progress.state)
                if state == QuestState.READY_TO_COMPLETE and definition.end_npc_id == npc.template_id:
                    status = 2
                elif state == QuestState.ACTIVE:
                    has_dialogue_objective = any(
                        objective.kind == QuestObjectiveKind.NPC
                        and objective.target_id == npc.template_id
                        and progress.progress.get(objective.progress_key, 0) < objective.count
                        for objective in definition.objectives
                    )
                    if has_dialogue_objective or definition.end_npc_id == npc.template_id:
                        status = 1
            if status is None:
                continue
            safe_name = definition.name.replace(":", "：").replace("&", "和")
            rows.append(
                f"{safe_name}&{definition.quest_id}&{status}&0&0&{definition.quest_id}"
            )
        return "@".join(rows) or "-"

    def _refresh_family_quest_period(self) -> None:
        """Reset Oil Girl Shino's five family tasks once per local calendar day."""
        progression = self.store.state.progression
        day_key = date.today().isoformat()
        if progression.family_quest_day_key == day_key:
            return
        with self.store.lock:
            progression.family_quest_day_key = day_key
            progression.family_quest_count = 0
            progress = self.store.state.original_quests.get(8101)
            if progress is not None:
                progress.state = int(QuestState.NOT_STARTED)
                progress.finish_count = 0
                progress.progress.clear()
            self.store.save()

    def _is_merchant_npc(self, npc_template_id: int) -> bool:
        if npc_template_id in NYA208_MERCHANT_CATALOG:
            return True
        script_name, _ = GAME_DATA_CATALOG.npc_functions.get(npc_template_id, ("", ""))
        return (
            npc_template_id in self.MERCHANT_NPC_TEMPLATE_IDS
            or script_name == "\u7269\u54c1\u4ea4\u6613"
        )

    def _merchant_shop_layout(
        self,
        npc_template_id: int,
    ) -> tuple[tuple[str, str, tuple[int, ...], int], ...] | None:
        layout = self.MERCHANT_SHOP_LAYOUT.get(npc_template_id)
        if layout is not None:
            return layout
        _, role = GAME_DATA_CATALOG.npc_functions.get(npc_template_id, ("", ""))
        layout_template_id = self.MERCHANT_ROLE_LAYOUT_TEMPLATE_IDS.get(role)
        return self.MERCHANT_SHOP_LAYOUT.get(layout_template_id)

    def _merchant_shop_id(self, npc_template_id: int) -> int:
        if npc_template_id in self.MERCHANT_SHOP_LAYOUT or npc_template_id in NYA208_MERCHANT_CATALOG:
            return npc_template_id
        _, role = GAME_DATA_CATALOG.npc_functions.get(npc_template_id, ("", ""))
        return self.MERCHANT_ROLE_LAYOUT_TEMPLATE_IDS.get(role, npc_template_id)

    def _merchant_shop_config(self, npc_template_id: int) -> dict[str, Any]:
        """Return the live editor inventory and pricing for the NPC's merchant role."""
        shop_id = self._merchant_shop_id(npc_template_id)
        captured_shop = NYA208_MERCHANT_CATALOG.get(npc_template_id)
        captured_prices: dict[str, int] = {}
        if captured_shop is not None:
            tabs = []
            for captured_tab in captured_shop.get("tabs", ()):
                items = [
                    dict(item)
                    for item in captured_tab.get("items", ())
                    if isinstance(item, dict)
                ]
                tabs.append(
                    {
                        "name": str(captured_tab.get("name") or "商品"),
                        "enabled": True,
                        "itemIds": [int(item["item_id"]) for item in items],
                        "items": items,
                    }
                )
                captured_prices.update(
                    {str(item["item_id"]): int(item["price"]) for item in items}
                )
        else:
            layout = self._merchant_shop_layout(npc_template_id)
            if layout is None:
                layout = (("消耗品", "XiaoHao", (), 24), ("技能书", "JiNengShu", (), 24))
            tabs: list[dict[str, Any]] = []
            for tab_name, section_name, category_prefixes, maximum_rows in layout:
                item_ids = GAME_DATA_CATALOG.merchant_item_ids(
                    section_name,
                    category_prefixes,
                    maximum_rows,
                )
                if npc_template_id == 14 and section_name == "XiaoHao":
                    # The medicine NPC is not the general-goods NPC. Pet food is
                    # an authored consumable, but it must stay on the grocery shelf.
                    item_ids = tuple(
                        item_id
                        for item_id in item_ids
                        if (
                            definition := GAME_DATA_CATALOG.get_item_definition(item_id)
                        ) is not None
                        and (definition.hp_restore > 0 or definition.mp_restore > 0)
                    )
                tabs.append({"name": tab_name, "enabled": True, "itemIds": list(item_ids[:maximum_rows])})

        override = editor_shop_override("npc_shops", shop_id)
        if isinstance(override.get("tabs"), list):
            tabs = [tab for tab in override["tabs"] if isinstance(tab, dict)]
        if override.get("enabled") is False:
            tabs = []
        prices = captured_prices
        if isinstance(override.get("itemPrices"), dict):
            prices.update(override["itemPrices"])
        try:
            buy_multiplier = max(0.0, float(override.get("buyPriceMultiplier", 1.0)))
            sell_multiplier = max(0.0, float(override.get("sellPriceMultiplier", 0.5)))
        except (TypeError, ValueError):
            buy_multiplier, sell_multiplier = 1.0, 0.5
        return {
            "shop_id": shop_id,
            "tabs": tabs,
            "prices": prices,
            "buy_multiplier": buy_multiplier,
            "sell_multiplier": sell_multiplier,
        }

    @staticmethod
    def _captured_merchant_item(config: dict[str, Any], item_id: int) -> dict[str, Any] | None:
        """Return the captured row metadata for one item in the active merchant."""
        for tab in config.get("tabs", ()):
            for row in tab.get("items", ()) if isinstance(tab, dict) else ():
                if isinstance(row, dict) and int(row.get("item_id", 0)) == item_id:
                    return row
        return None

    def _merchant_price(self, item_id: int, config: dict[str, Any]) -> int:
        definition = GAME_DATA_CATALOG.get_item_definition(item_id)
        if definition is None:
            return 1
        configured = config["prices"].get(str(item_id), definition.price)
        return max(1, round(max(0, self._safe_int(configured, definition.price)) * config["buy_multiplier"]))

    def handle_npc_talk(self, read_str: str) -> None:
        """Show authored dialogue with native quest rows and optional service actions."""
        npc = self._resolve_talk_npc(read_str)
        if npc is None:
            return
        if (
            self.active_copy_id == 8
            and self.character.map_id == 406_010_001
            and npc.template_id == 64
        ):
            self._complete_active_copy()
            return
        self.active_npc_object_id = npc.object_id
        self._clear_active_quest_dialog()
        self._send_current_npc_dialog(
            npc,
            include_automatic=npc.object_id == self.QUEST_NPC_OBJECT_ID,
        )

    def _send_current_npc_dialog(
        self,
        npc: NpcState,
        include_automatic: bool = False,
    ) -> None:
        """Refresh one NPC's authored services and currently actionable quest rows."""
        if npc.object_id != self.QUEST_NPC_OBJECT_ID:
            menu_entries = [
                f"{label}&{op(action)}"
                for label, action in self.NPC_SERVICE_MENUS.get(npc.template_id, ())
            ]
            if (
                npc.template_id in self.STORAGE_NPC_TEMPLATE_IDS
                and not self._npc_supports_menu_action(npc, NpcMenuAction.STORAGE)
            ):
                menu_entries.append(f"打开仓库&{op(NpcMenuAction.STORAGE)}")
            if self._is_merchant_npc(npc.template_id):
                menu_entries.append(f"物品交易&{op(NpcMenuAction.SHOP)}")
            if npc.template_id in self.CARD_COLLECTION_NPC_TEMPLATE_IDS:
                menu_entries.append(
                    f"卡片套册收集&{op(NpcMenuAction.CARD_COLLECTION)}"
                )
            menu_entries.append(f"离开&{op(NpcMenuAction.LEAVE)}")
            self._send_npc_dialog(
                npc.dialogue,
                npc.template_id,
                "@".join(menu_entries),
                self._npc_quest_selections(npc),
            )
            return
        selections = self._npc_quest_selections(npc, include_automatic=True)
        menu = "-"
        if selections == "-":
            menu = (
                "训练任务&0@木叶商店&1@公共仓库&2@传送木叶村&3@"
                "人物养成&5@单人试炼&6@成就奖励&7@离开&-1"
            )
        self._send_npc_dialog(npc.dialogue, npc.template_id, menu, selections)

    def _npc_supports_menu_action(
        self,
        npc: NpcState,
        action: NpcMenuAction,
    ) -> bool:
        """Keep every authored service action scoped to the NPC that exposes it."""
        return any(
            candidate == action
            for _, candidate in self.NPC_SERVICE_MENUS.get(npc.template_id, ())
        )

    def handle_npc_talk_more_ex(self, read_str: str) -> None:
        """Execute one selected guide menu action from NPC_TALK_MORE_EX."""
        fields = self._request_fields(read_str, ClientOpcode.NPC_TALK_MORE_EX)
        if len(fields) < 2 or self.active_npc_object_id is None:
            return
        command_type = self._safe_int(fields[0], -1)
        active_npc = self.npcs.get(self.active_npc_object_id)
        is_guide = self.active_npc_object_id == self.QUEST_NPC_OBJECT_ID
        if active_npc is None:
            return
        if command_type == op(NpcTalkCommandType.CLOSE):
            self._clear_active_quest_dialog()
            return
        if command_type == op(NpcTalkCommandType.NEXT):
            self._continue_original_quest_dialog(active_npc)
            return
        if command_type == op(NpcTalkCommandType.SELECTION):
            quest_id = self._safe_int(fields[1], -1)
            if not self._handle_original_quest_npc(
                active_npc,
                include_automatic=is_guide,
                selected_quest_id=quest_id,
            ):
                self._send_current_npc_dialog(active_npc, include_automatic=is_guide)
            return
        if command_type != op(NpcTalkCommandType.MENU):
            return
        raw_action = self._safe_int(fields[1], -1)
        if active_npc.template_id == 76 and raw_action in (100, 200, 300, 400):
            label = next(
                label
                for job, label in self.JOB_TRANSFER_CHOICES.values()
                if job == raw_action
            )
            self._change_character_job(raw_action, label)
            return
        try:
            action = NpcMenuAction(raw_action)
        except ValueError:
            return
        if action == NpcMenuAction.LEAVE:
            self._clear_active_quest_dialog()
            self.active_npc_object_id = None
        elif action == NpcMenuAction.QUEST and is_guide:
            self._handle_quest_npc_talk()
        elif action == NpcMenuAction.SHOP and (
            is_guide or self._is_merchant_npc(active_npc.template_id)
        ):
            self._send_npc_shop(active_npc.template_id)
        elif action == NpcMenuAction.STORAGE and (
            is_guide or active_npc.template_id in self.STORAGE_NPC_TEMPLATE_IDS
        ):
            self._send_storage_open()
        elif action == NpcMenuAction.TELEPORT and is_guide:
            self._warp_to_map(100_000_000)
        elif action == NpcMenuAction.ORIGINAL_QUEST:
            if not self._handle_original_quest_npc(
                active_npc,
                include_automatic=True,
            ):
                self._send_npc_dialog("当前没有可推进的原版任务。", active_npc.template_id)
        elif action == NpcMenuAction.PROGRESSION and is_guide:
            self._upgrade_offline_progression()
        elif action == NpcMenuAction.SOLO_TRIAL and is_guide:
            self._start_solo_trial()
        elif action == NpcMenuAction.ACHIEVEMENTS and is_guide:
            self._claim_available_achievements()
        elif action == NpcMenuAction.CARD_COLLECTION and (
            active_npc.template_id in self.CARD_COLLECTION_NPC_TEMPLATE_IDS
        ):
            # Client.onShowNpcTriggerPanel maps original panel id 5 to GuwanshoujiWindow.
            self.send_text(
                f"{op(ServerOpcode.SHOW_NPC_PANEL)}:{active_npc.object_id}:5"
            )
        elif action == NpcMenuAction.JOB_TRANSFER and self._npc_supports_menu_action(
            active_npc, action
        ):
            self.send_text(
                f"{op(ServerOpcode.SHOW_NPC_PANEL)}:{active_npc.object_id}:100"
            )
        elif action in self.JOB_TRANSFER_CHOICES and active_npc.template_id == 76:
            job, label = self.JOB_TRANSFER_CHOICES[action]
            self._change_character_job(job, label)
        elif not self._npc_supports_menu_action(active_npc, action):
            return
        elif action == NpcMenuAction.ITEM_EXCHANGE:
            self.send_text(
                f"{op(ServerOpcode.SHOW_NPC_PANEL)}:{active_npc.object_id}:10"
            )
        elif action == NpcMenuAction.TRANSFORM_CARD_SWAP:
            self.send_text(
                f"{op(ServerOpcode.SHOW_NPC_PANEL)}:{active_npc.object_id}:60"
            )
        elif action == NpcMenuAction.TRANSFORM_CARD_SPECIAL_SWAP:
            self.send_text(
                f"{op(ServerOpcode.SHOW_NPC_PANEL)}:{active_npc.object_id}:102"
            )
        elif action == NpcMenuAction.TOTSUKA_EXCHANGE:
            self.send_text(
                f"{op(ServerOpcode.SHOW_NPC_PANEL)}:{active_npc.object_id}:51"
            )
        elif action == NpcMenuAction.ARTIFACT_INFO:
            self.send_text(
                f"{op(ServerOpcode.SHOW_NPC_PANEL)}:{active_npc.object_id}:50"
            )
        elif action == NpcMenuAction.RENJU_EXCHANGE:
            self.send_text(
                f"{op(ServerOpcode.SHOW_NPC_PANEL)}:{active_npc.object_id}:61"
            )
        elif action == NpcMenuAction.JOB_EQUIPMENT_CONVERT:
            self.send_text(
                f"{op(ServerOpcode.SHOW_NPC_PANEL)}:{active_npc.object_id}:101"
            )
        elif action == NpcMenuAction.PVE:
            self.send_text(
                f"{op(ServerOpcode.SHOW_NPC_PANEL)}:{active_npc.object_id}:6"
            )
            self._send_pve_status()
        elif action == NpcMenuAction.COPY:
            self._send_copy_history()
        elif action == NpcMenuAction.ELITE_COPY:
            self._send_hero_enter_info()
        elif action == NpcMenuAction.BADGE:
            self.send_text(
                f"{op(ServerOpcode.SHOW_NPC_PANEL)}:{active_npc.object_id}:11"
            )
        elif action == NpcMenuAction.TREASURE:
            self.send_text(
                f"{op(ServerOpcode.SHOW_NPC_PANEL)}:{active_npc.object_id}:8"
            )
            self._send_treasure_state(self.store.state.fudai_transaction)
        elif action == NpcMenuAction.COOKING:
            self.send_text(f"{op(ServerOpcode.BUFF_HECHENG)}:1:0")
        elif action == NpcMenuAction.WASH_POINT:
            self.send_text(
                f"{op(ServerOpcode.SHOW_NPC_PANEL)}:{active_npc.object_id}:4"
            )
        elif action == NpcMenuAction.JADE:
            self.send_text(
                f"{op(ServerOpcode.SHOW_NPC_PANEL)}:{active_npc.object_id}:7"
            )
        elif action == NpcMenuAction.WAR:
            self.handle_war_panel_action(f"{op(ClientOpcode.WAR_PANEL_ACTION)}:0")
        elif action == NpcMenuAction.ARTIFACT_WAR:
            self._enter_artifact_warfield()
        elif action == NpcMenuAction.CHUNIN_EXAM:
            self._send_chunin_results()
            self.send_text(f"{op(ServerOpcode.WAR_WORLDCUP)}:2")

    def _change_character_job(self, new_job: int, label: str) -> None:
        """Atomically consume the transfer token, change job, and unequip old gear."""
        if new_job not in (100, 200, 300, 400):
            return
        if self.character.job == new_job:
            self._send_native_server_message(f"你已经是{label}。", 16)
            return
        replaced_skills: list[tuple[SkillState, SkillState]] = []
        moved_items: list[tuple[InventoryItem, int]] = []
        consumed_item: InventoryItem | None = None
        consumed_removed = False
        with self.store.lock:
            incompatible = [
                item
                for item in self.store.state.inventory.values()
                if item.slot < 0
                and (definition := GAME_DATA_CATALOG.get_equipment_definition(item.item_id))
                is not None
                and definition.required_job not in (0, new_job)
            ]
            consumed_item = next(
                (
                    item
                    for item in self.store.state.inventory.values()
                    if item.slot > 0
                    and item.item_id == self.JOB_TRANSFER_ITEM_ID
                    and item.quantity > 0
                ),
                None,
            )
            if consumed_item is None:
                self._send_native_server_message("缺少转职凭证，无法转职。", 16)
                return
            free_slots = [
                slot
                for slot in range(1, self.store.state.bag_capacity + 1)
                if slot not in self.store.state.inventory
            ]
            if consumed_item.quantity == 1:
                free_slots.append(consumed_item.slot)
                free_slots.sort()
            if len(free_slots) < len(incompatible):
                self._send_native_server_message(
                    "背包空间不足，无法卸下原职业装备。", 16
                )
                return
            consumed_item.quantity -= 1
            consumed_removed = consumed_item.quantity == 0
            if consumed_removed:
                self.store.state.inventory.pop(consumed_item.slot, None)
            for item, destination in zip(incompatible, free_slots):
                old_slot = item.slot
                self.store.state.inventory.pop(old_slot, None)
                item.slot = destination
                self.store.state.inventory[destination] = item
                moved_items.append((item, old_slot))
            profession_skill_ids = {
                job * 10_000 + 1_000 + index
                for job in (100, 200, 300, 400)
                for index in (1, 2, 3)
            }
            for skill_id, skill in list(self.store.state.skills.items()):
                if skill_id not in profession_skill_ids:
                    continue
                target_skill_id = new_job * 10_000 + skill_id % 10_000
                if target_skill_id == skill_id:
                    continue
                if GAME_DATA_CATALOG.get_skill_definition(target_skill_id) is None:
                    continue
                replacement = SkillState(
                    skill_id=target_skill_id,
                    level=skill.level,
                    master_level=skill.master_level,
                )
                existing = self.store.state.skills.get(target_skill_id)
                if existing is not None:
                    replacement.level = max(replacement.level, existing.level)
                    replacement.master_level = max(
                        replacement.master_level,
                        existing.master_level,
                    )
                self.store.state.skills.pop(skill_id, None)
                self.store.state.skills[target_skill_id] = replacement
                for binding in self.store.state.keymap.values():
                    if binding.action == skill_id:
                        binding.action = target_skill_id
                replaced_skills.append((skill, replacement))
            self.character.job = new_job
            self.character.gender = 1 if new_job in (200, 400) else 0
            self.character.face = 2 if self.character.gender else 1
            self.store.save()
        if self.account_id:
            self.accounts.update_character_summary(
                self.character.character_id,
                job=new_job,
                gender=self.character.gender,
                face=self.character.face,
            )
        if consumed_removed:
            self._send_inventory_clear(consumed_item.slot, InventoryType.BAG)
        else:
            self._send_inventory_update(consumed_item, from_drop=0)
        self._send_stats({StatType.JOB: new_job})
        for item, old_slot in moved_items:
            self._send_inventory_clear(old_slot, InventoryType.EQUIPPED)
            self._send_inventory_add(item, from_drop=0)
        for old_skill, new_skill in replaced_skills:
            self._send_skill_update(
                SkillState(skill_id=old_skill.skill_id, level=0, master_level=0)
            )
            self._send_skill_update(new_skill)
        self._send_char_config()
        self._send_character_info()
        self._send_equipped_info()
        self._send_character_look()
        self._send_all_stats()
        if self.wire_mode == "original":
            inventory = sorted(
                self.store.state.inventory.values(), key=lambda item: item.slot
            )
            equipped = [
                item
                for item in inventory
                if item.slot < 0
                and self._inventory_item_section(item)
                not in {"ShenQi", "HunJie", "LingQi", "RenJu"}
            ]
            bag = [item for item in inventory if item.slot > 0]
            self.send_original_packet(
                ServerOpcode.EQUIPPED_INFO,
                self._original_item_list_payload(equipped),
            )
            self.send_original_packet(
                ServerOpcode.BAG_INFO,
                self._original_item_list_payload(bag),
            )
            self.send_original_packet(
                ServerOpcode.UPDATE_STATS,
                self._original_update_stats_payload(),
            )
            self._send_character_look()
        self._send_native_server_message(f"转职成功：{label}。")

    @staticmethod
    def _scheduled_warfield_for_map(map_id: int) -> tuple[str, str] | None:
        """Resolve direct activity-map requests to their authored schedule section."""
        for section_name, label in (
            ("warfield", "神器战场"),
            ("pvp_warfield", "铃铛争夺战"),
        ):
            raw = GAME_DATA_CATALOG.huodong_config(section_name)
            config = raw.get("0") if isinstance(raw.get("0"), dict) else {}
            try:
                configured_map_id = int(float(config.get("mapid") or 0))
            except (TypeError, ValueError):
                configured_map_id = 0
            if configured_map_id == int(map_id):
                return section_name, label
        return None

    def _clear_scheduled_warfield_state(self) -> None:
        self.scheduled_warfield_section = ""
        self.scheduled_warfield_return_map_id = None
        self.scheduled_warfield_return_position = None
        self.pvp_mode = 1

    def _enter_scheduled_warfield(self, section_name: str, label: str) -> bool:
        """Validate and enter one GameData-authored recurring battlefield."""
        raw = GAME_DATA_CATALOG.huodong_config(section_name)
        config = raw.get("0") if isinstance(raw.get("0"), dict) else {}
        map_id = self._safe_int(config.get("mapid"), 0)
        required_level = max(1, self._safe_int(config.get("reqLevel"), 45))
        required_channel = max(0, self._safe_int(config.get("channel"), 3))
        if self.character.level < required_level:
            self._send_native_server_message(
                f"进入{label}需要达到{required_level}级。", 16
            )
            return False
        if required_channel and self.line_id != required_channel:
            self._send_native_server_message(
                f"{label}只在{required_channel}线开放。", 16
            )
            return False
        active, remaining = self._activity_window_state(config)
        if not active:
            self._send_native_server_message(
                f"{label}尚未开放，距离下次开启还有{remaining}秒。", 16
            )
            return False
        if GAME_DATA_CATALOG.get_map(map_id) is None:
            self._send_native_server_message(f"{label}地图资源尚未恢复。", 16)
            return False
        if (
            self.active_copy_id is not None
            or self.active_hero_copy_id is not None
            or self.active_pve_level
            or self.muye_battle_team in (1, 2)
            or self.war_battle_active
            or self.war_3v3_match_id
        ):
            self._send_native_server_message("请先离开当前副本或战场。", 16)
            return False
        if self.character.map_id != map_id:
            self.scheduled_warfield_return_map_id = self.character.map_id
            self.scheduled_warfield_return_position = (self.x, self.y)
        elif self.scheduled_warfield_return_map_id is None:
            self.scheduled_warfield_return_map_id = DEFAULT_MAP_ID
            self.scheduled_warfield_return_position = None
        self.scheduled_warfield_section = section_name
        self.pvp_mode = 5
        self._warp_to_map(map_id)
        self.send_text(f"{op(ServerOpcode.OPEN_PVP_ACTION)}:8:{remaining}")
        self.send_text(f"{op(ServerOpcode.OPEN_PVP_ACTION)}:9:0:-:{remaining}")
        self._send_native_server_message(
            f"已进入{label}，活动结束后将自动返回。", 16
        )
        return True

    def _leave_scheduled_warfield(self, label: str) -> None:
        return_map_id = self.scheduled_warfield_return_map_id or DEFAULT_MAP_ID
        return_position = self.scheduled_warfield_return_position
        self._clear_scheduled_warfield_state()
        self.send_text(f"{op(ServerOpcode.OPEN_PVP_ACTION)}:8:0")
        self._warp_to_map(return_map_id, exact_position=return_position)
        self._send_native_server_message(f"{label}已结束，已返回原地图。", 16)

    def _tick_scheduled_warfield(self) -> None:
        """End recurring battlefields by wall-clock time, including after reconnect."""
        resolved = self._scheduled_warfield_for_map(self.character.map_id)
        if resolved is None:
            return
        section_name, label = resolved
        if section_name == "warfield":
            self._tick_artifact_war()
            return
        raw = GAME_DATA_CATALOG.huodong_config(section_name)
        config = raw.get("0") if isinstance(raw.get("0"), dict) else {}
        active, remaining = self._activity_window_state(config)
        if not active:
            if not self.scheduled_warfield_section:
                self.scheduled_warfield_section = section_name
                self.scheduled_warfield_return_map_id = DEFAULT_MAP_ID
            self._leave_scheduled_warfield(label)
            return
        if not self.scheduled_warfield_section:
            self.scheduled_warfield_section = section_name
            self.scheduled_warfield_return_map_id = DEFAULT_MAP_ID
            self.scheduled_warfield_return_position = None
            self.pvp_mode = 5
            self.send_text(f"{op(ServerOpcode.OPEN_PVP_ACTION)}:8:{remaining}")
            self.send_text(f"{op(ServerOpcode.OPEN_PVP_ACTION)}:9:0:-:{remaining}")

    def _enter_artifact_warfield(self) -> None:
        """Enter either the key contest or the key-holder-only artifact contest."""
        phase, remaining, season_key = self._artifact_war_phase()
        if phase == "closed":
            self._send_native_server_message("神器战场尚未开放。", 16)
            return
        if phase == "intermission":
            self._send_native_server_message(
                f"密匙之争已结束，神器之争将在{remaining}秒后开启。", 16
            )
            return
        if self.hub is None:
            return
        with self.hub.lock:
            self._prepare_artifact_war_season_locked(season_key, phase)
            state = self.hub.artifact_war
            if phase == "artifact" and state.holder_id != self.character.character_id:
                self._send_native_server_message(
                    "只有密匙持有者可进入神器之争。", 16
                )
                return
        if phase == "key":
            if not self._enter_scheduled_warfield("warfield", "神器战场"):
                return
        else:
            raw = GAME_DATA_CATALOG.huodong_config("warfield")
            config = raw.get("0") if isinstance(raw.get("0"), dict) else {}
            required_level = max(1, self._safe_int(config.get("reqLevel"), 45))
            required_channel = max(1, self._safe_int(config.get("channel"), 3))
            map_id = self._safe_int(config.get("mapid"), 501_000_000)
            if self.character.level < required_level or self.line_id != required_channel:
                self._send_native_server_message("神器之争只对3线合格玩家开放。", 16)
                return
            self.scheduled_warfield_return_map_id = self.character.map_id
            self.scheduled_warfield_return_position = (self.x, self.y)
            self.scheduled_warfield_section = "warfield"
            self.pvp_mode = 5
            self._warp_to_map(map_id)
            self.send_text(f"{op(ServerOpcode.OPEN_PVP_ACTION)}:8:{remaining}")
        self._sync_artifact_war_drop()
        self._sync_artifact_phase_monsters(phase)

    @staticmethod
    def _artifact_war_phase(now: datetime | None = None) -> tuple[str, int, str]:
        current = now or datetime.now()
        season_key = current.strftime("%Y-%m-%d")
        if current.isoweekday() not in {3, 6}:
            return "closed", 0, season_key
        seconds = current.hour * 3600 + current.minute * 60 + current.second
        if 20 * 3600 <= seconds < 20 * 3600 + 30 * 60:
            return "key", 20 * 3600 + 30 * 60 - seconds, season_key
        if 20 * 3600 + 30 * 60 <= seconds < 20 * 3600 + 40 * 60:
            return "intermission", 20 * 3600 + 40 * 60 - seconds, season_key
        if 20 * 3600 + 40 * 60 <= seconds < 21 * 3600:
            return "artifact", 21 * 3600 - seconds, season_key
        return "closed", 0, season_key

    def _prepare_artifact_war_season_locked(self, season_key: str, phase: str) -> None:
        if self.hub is None:
            return
        state = self.hub.artifact_war
        if state.season_key != season_key:
            self.hub.artifact_war = ArtifactWarState(season_key=season_key, phase=phase)
            self.hub.persist_artifact_war()
        elif state.phase != phase:
            state.phase = phase
            self.hub.persist_artifact_war()

    @staticmethod
    def _next_artifact_expiry(now: datetime | None = None) -> int:
        current = now or datetime.now()
        for offset in range(1, 8):
            candidate = current + timedelta(days=offset)
            if candidate.isoweekday() in {3, 6}:
                return int(candidate.replace(hour=19, minute=0, second=0, microsecond=0).timestamp())
        return int((current + timedelta(days=7)).timestamp())

    def _sync_artifact_war_drop(self) -> None:
        if self.hub is None or self.character.map_id != 501_000_000:
            return
        phase, _, season_key = self._artifact_war_phase()
        with self.hub.lock:
            self._prepare_artifact_war_season_locked(season_key, phase)
            state = self.hub.artifact_war
            if state.ground_drop_id and state.ground_drop_id not in self.drops:
                item_id = 17_200_001 if phase == "artifact" else 16_000_030
                drop = self._spawn_battle_item_drop(item_id)
                state.ground_drop_id = drop.object_id
                self.hub.persist_artifact_war()

    def _sync_artifact_phase_monsters(self, phase: str) -> None:
        if self.character.map_id != 501_000_000:
            return
        hidden_ids = (
            self.world_state.scheduled_object_ids.setdefault(
                "artifact-phase-hidden", set()
            )
            if self.world_state is not None
            else set()
        )
        for monster in self.monsters.values():
            if monster.template_id != 2_200_012:
                continue
            if phase == "key" and monster.hp > 0:
                monster.hp = 0
                monster.respawn_at = float("inf")
                hidden_ids.add(monster.object_id)
                self._send_visible(
                    f"{op(ServerOpcode.KILL_MONSTER)}:{monster.object_id}:"
                    f"{op(MonsterRemovalAnimation.IMMEDIATE)}"
                )
            elif (
                phase == "artifact"
                and monster.object_id in hidden_ids
                and monster.hp <= 0
            ):
                monster.hp = monster.max_hp
                monster.respawn_at = 0.0
                hidden_ids.discard(monster.object_id)
                self._send_monster_spawn(monster)

    def _settle_artifact_war(self) -> None:
        if self.hub is None:
            return
        winner: FakeFlashSession | None = None
        with self.hub.lock:
            state = self.hub.artifact_war
            if state.settled:
                return
            if state.held_item_id == 17_200_001 and state.holder_id:
                state.winner_id = state.holder_id
                state.winner_name = state.holder_name
                state.ownership_expires_at = self._next_artifact_expiry()
                winner = self.hub.sessions_by_character.get(state.holder_id)
            state.settled = True
            state.phase = "closed"
            self.hub.persist_artifact_war()
        if winner is not None:
            with winner.store.lock:
                winner.store.state.progression.artifact_war_wins += 1
                winner.store.save()
            winner._broadcast_rare_event(
                f"{winner.character.name}成为神器战场最终胜者，获得草薙剑使用权！",
                highlights=(winner.character.name, "草薙剑"),
            )

    def _tick_artifact_war(self) -> None:
        phase, remaining, season_key = self._artifact_war_phase()
        if self.hub is not None:
            with self.hub.lock:
                self._prepare_artifact_war_season_locked(season_key, phase)
        if phase in {"key", "artifact"}:
            self._sync_artifact_war_drop()
            self._sync_artifact_phase_monsters(phase)
            if time.monotonic() - self.artifact_war_last_exp_at >= 30:
                self.artifact_war_last_exp_at = time.monotonic()
                self._grant_experience(
                    max(100, self.character.level * 50), apply_item_effect=False
                )
            self.send_text(f"{op(ServerOpcode.OPEN_PVP_ACTION)}:8:{remaining}")
            return
        if phase == "intermission":
            if self.scheduled_warfield_section:
                self._leave_scheduled_warfield("密匙之争")
            return
        self._settle_artifact_war()
        if self.scheduled_warfield_section:
            self._leave_scheduled_warfield("神器战场")

    def _expire_artifact_ownership(self) -> None:
        if self.hub is None:
            return
        with self.hub.lock:
            state = self.hub.artifact_war
            should_expire = (
                state.settled
                and state.winner_id == self.character.character_id
                and state.ownership_expires_at > 0
                and int(time.time()) >= state.ownership_expires_at
            )
            if not should_expire:
                return
            self._remove_one_battle_item(17_200_001)
            state.winner_id = 0
            state.winner_name = ""
            state.ownership_expires_at = 0
            self.hub.persist_artifact_war()
        self._send_native_server_message("草薙剑使用权已到期。", 16)

    def _upgrade_offline_progression(self) -> None:
        """Refresh the real character-tab systems instead of advancing a made-up guide track."""
        self._send_cultivation_states()
        self._send_all_stats()
        self._send_npc_dialog(
            "人物属性的手里剑、结印、八门、柔拳、昆虫、写轮眼和轮回六道已同步，请在对应页签操作。",
            self.QUEST_NPC_TEMPLATE_ID,
        )

    def _send_cultivation_states(self) -> None:
        """Initialize every original character cultivation tab after entering the map."""
        # The client needs a stage-one panel to begin training, but merely opening
        # that panel must not persist or grant stage-one combat attributes.
        self._send_an_qi_state()
        self._send_cultivation_blessing(ServerOpcode.AN_QI, "手里剑")
        self._send_jie_yin_state()
        self._send_progress_cultivation_state(ServerOpcode.ROU_QUAN, "柔拳", "RouQuan")
        self._send_cultivation_blessing(ServerOpcode.ROU_QUAN, "柔拳")
        self._send_progress_cultivation_state(
            ServerOpcode.XIELUNYAN_ACTION,
            "写轮眼",
            "XieLunYan",
        )
        self._send_xielunyan_blessing()
        self._send_progress_cultivation_state(
            ServerOpcode.LUN_HUI_YAN,
            "轮眼",
            "LunHuiYan",
        )
        self._send_cultivation_blessing(ServerOpcode.LUN_HUI_YAN, "轮眼")
        self._send_mai_statistics()
        self._send_equipped_kun_chong()

    def _send_equipped_kun_chong(self) -> None:
        """Refresh the original insect panel with all four equipped KunChong slots."""
        equipped_positions = {op(position) for position in KUN_CHONG_EQUIPPED_POSITIONS}
        encoded = "@".join(
            self._encode_item_payload(item)
            for item in sorted(self.store.state.inventory.values(), key=lambda value: value.slot)
            if item.slot in equipped_positions
        ) or "-"
        self.send_text(f"{op(ServerOpcode.EQUIPPED_KUNCHONG)}:{encoded}")

    def _cultivation_stage(self, state_key: str, maximum: int) -> int:
        """Return a client-visible stage; missing keys remain unowned in stat aggregation."""
        stage = self.store.state.progression.stages.get(state_key, 1)
        return min(max(1, stage), maximum)

    def _an_qi_level(self) -> int:
        """Return the persisted level within the current shuriken stage."""
        level = self.store.state.progression.stages.get("手里剑:等级", 1)
        return min(max(1, level), 4)

    def _an_qi_mastery(self, stage: int, level: int) -> tuple[int, int]:
        """Return current and maximum mastery for one authored shuriken level."""
        level_config = GAME_DATA_CATALOG.get_cultivation_stage("AnQi", stage).get("levels")
        level_data = level_config.get(str(level), {}) if isinstance(level_config, dict) else {}
        maximum = max(1, self._safe_int(level_data.get("master_max"), 5_000))
        current = min(
            maximum,
            max(0, self.store.state.progression.stage_progress.get("手里剑", 0)),
        )
        return current, maximum

    def _send_an_qi_state(self) -> None:
        """Send the persisted shuriken stage, level, mastery, and open state."""
        stage = self._cultivation_stage("手里剑", 7)
        level = self._an_qi_level()
        mastery, _ = self._an_qi_mastery(stage, level)
        enabled = bool(self.store.state.progression.stage_progress.get("手里剑:开启", 1))
        self.send_text(
            f"{op(ServerOpcode.AN_QI)}:{op(CultivationResponseAction.STATUS)}:"
            f"{stage}:{level}:{mastery}:{str(enabled).lower()}"
        )

    def _train_an_qi(self, *, use_all: bool) -> int:
        """Consume authored training seals and advance all four levels safely."""
        config = GAME_DATA_CATALOG.get_cultivation_config("AnQi")
        common = config.get("common") if isinstance(config.get("common"), dict) else {}
        speed_up = (
            common.get("speedUp")
            if isinstance(common.get("speedUp"), dict)
            else {}
        )
        item_id = max(0, self._safe_int(speed_up.get("needItemId"), 15_020_001))
        mastery_gain = max(1, self._safe_int(speed_up.get("addMaster"), 50))
        available = self._inventory_item_quantity(item_id)
        if available <= 0:
            self._send_system_chat("手里剑修炼符不足。")
            self._send_an_qi_state()
            return 0

        stage = self._cultivation_stage("手里剑", 7)
        level = self._an_qi_level()
        current, maximum = self._an_qi_mastery(stage, level)
        if level >= 4 and current >= maximum:
            self._send_system_chat("当前手里剑熟练度已经满了，请先突破。")
            self._send_an_qi_state()
            return 0

        limit = available if use_all else 1
        used = 0
        while used < limit:
            current += mastery_gain
            used += 1
            if current < maximum:
                continue
            if level >= 4:
                current = maximum
                break
            level += 1
            current = 0
            _, maximum = self._an_qi_mastery(stage, level)

        with self.store.lock:
            changes = self._consume_inventory_quantity(item_id, used)
            self.store.state.progression.stages["手里剑:等级"] = level
            self.store.state.progression.stage_progress["手里剑"] = current
            self.store.save()
        for item, removed in changes:
            if removed:
                self._send_inventory_clear(item.slot, InventoryType.BAG)
            else:
                self._send_inventory_update(item, from_drop=0)
        self._send_an_qi_state()
        self._send_system_chat(f"手里剑修炼成功，消耗修炼符 {used} 个。")
        return used

    def _send_jie_yin_state(self) -> None:
        """Send JieYinProcessor action 0 with the persisted seal-training progress."""
        stage = self._cultivation_stage("结印", 12)
        count = max(0, self.store.state.progression.stage_progress.get("结印", 0))
        self.send_text(
            f"{op(ServerOpcode.JIE_YIN)}:{op(CultivationResponseAction.STATUS)}:"
            f"{stage}:{count}"
        )

    def _send_progress_cultivation_state(
        self,
        opcode: ServerOpcode,
        state_key: str,
        config_name: str,
    ) -> None:
        """Send the shared action-0 stage/count packet used by eye and fist panels."""
        stage = self._cultivation_stage(
            state_key,
            GAME_DATA_CATALOG.cultivation_max_stage(config_name),
        )
        requirement = GAME_DATA_CATALOG.cultivation_progress_requirement(config_name, stage)
        count = min(
            requirement,
            max(
                0,
                self.store.state.progression.stage_progress.get(
                    state_key,
                    0,
                ),
            ),
        )
        self.send_text(
            f"{op(opcode)}:{op(CultivationResponseAction.STATUS)}:{stage}:{count}"
        )

    def handle_an_qi(self, read_str: str) -> None:
        """Toggle, speed up, or advance the original shuriken cultivation panel."""
        fields = self._request_fields(read_str, ClientOpcode.AN_QI)
        action = self._safe_int(fields[0], op(CultivationRequestAction.STATUS_OR_TRAIN)) if fields else 0
        if action == op(CultivationRequestAction.STAGE_UP_OR_AUTO):
            stage = self._cultivation_stage("手里剑", 7)
            level = self._an_qi_level()
            mastery, maximum = self._an_qi_mastery(stage, level)
            if level < 4 or mastery < maximum:
                self._send_system_chat("手里剑熟练度还没有满。")
                self._send_an_qi_state()
                return
            self._advance_stage_cultivation("手里剑", "AnQi", 7, ServerOpcode.AN_QI)
            return
        if action == 2:
            use_all = len(fields) > 1 and fields[1].strip().lower() in {
                "1",
                "true",
            }
            self._train_an_qi(use_all=use_all)
            return
        if action == op(CultivationRequestAction.STATUS_OR_TRAIN) and len(fields) > 1:
            with self.store.lock:
                self.store.state.progression.stage_progress["手里剑:开启"] = int(
                    fields[1].lower() in {"1", "true"}
                )
                self.store.save()
        self._send_an_qi_state()

    def handle_jie_yin(self, read_str: str) -> None:
        """Consume one authored essence cost and add one small seal-training roll."""
        fields = self._request_fields(read_str, ClientOpcode.JIE_YIN)
        action = self._safe_int(fields[0], -1) if fields else -1
        if action not in (
            op(CultivationRequestAction.STATUS_OR_TRAIN),
            op(CultivationRequestAction.STAGE_UP_OR_AUTO),
        ):
            return
        stage = self._cultivation_stage("结印", 12)
        if stage >= 12:
            self._send_jie_yin_state()
            return
        stage_data = GAME_DATA_CATALOG.get_cultivation_stage("JieYin", stage)
        stage_up = stage_data.get("stageUp") if isinstance(stage_data.get("stageUp"), dict) else {}
        zq_cost = max(0, self._safe_int(stage_up.get("needZq"), 1_000))
        required = max(1, self._safe_int(stage_up.get("needPointCnt"), 1))
        if self.character.zq < zq_cost:
            self._send_system_chat("查克拉精华不足。")
            return
        current = max(0, self.store.state.progression.stage_progress.get("结印", 0))
        gain = min(required - current, self.random.randint(1, 10))
        next_stage = stage
        with self.store.lock:
            self.character.zq -= zq_cost
            current += gain
            self.store.state.progression.stage_progress["结印"] = current
            if current >= required and stage < 12:
                next_stage = stage + 1
                self._apply_cultivation_attribute_delta("JieYin", stage, next_stage)
                self.store.state.progression.stages["结印"] = next_stage
                self.store.state.progression.stage_progress["结印"] = 0
            self.store.save()
        self.send_text(
            f"{op(ServerOpcode.JIE_YIN)}:{op(CultivationResponseAction.RESULT)}:1:{gain}"
        )
        self._send_stats({StatType.ZQ: self.character.zq})
        self._send_jie_yin_state()
        self._send_all_stats()

    def handle_rou_quan(self, read_str: str) -> None:
        """Handle the original RouQuan stage-up request and response."""
        self._handle_progress_cultivation_request(
            read_str,
            ClientOpcode.ROU_QUAN,
            ServerOpcode.ROU_QUAN,
            "柔拳",
            "RouQuan",
        )

    def handle_ling_qi(self, read_str: str) -> None:
        """Run the original four Totsuka Blade material transactions."""
        fields = self._request_fields(read_str, ClientOpcode.LING)
        if not fields:
            return
        action = self._safe_int(fields[0], -1)
        if action == op(LingQiAction.COMBINE):
            self._combine_ling_qi()
            return
        if len(fields) < 3:
            return
        item_id = self._safe_int(fields[1], 0)
        slot = self._safe_int(fields[2], 0)
        item = self.store.state.inventory.get(slot)
        if (
            item is None
            or slot <= 0
            or item.item_id != item_id
            or item_id not in (op(ItemId.TOTSUKA_BLADE), op(ItemId.OPENED_TOTSUKA_BLADE))
        ):
            self.send_text(f"{op(ServerOpcode.LING)}:{action}:0:-")
            return
        if action == op(LingQiAction.KAI_GUANG):
            self._open_ling_qi(item)
        elif action == op(LingQiAction.LING_HUA):
            self._spiritualize_ling_qi(item)
        elif action == op(LingQiAction.WASH):
            self._wash_ling_qi(item)

    def handle_renju(self, read_str: str) -> None:
        """Handle the native RenJu awakening and six-fragment exchange actions."""
        fields = self._request_fields(read_str, ClientOpcode.RENJU)
        action = self._safe_int(fields[0], -1) if fields else -1
        if action == op(RenJuAction.KAI_GUANG):
            self._open_renju(fields)
            return
        if action == op(RenJuAction.SWITCH_RESISTANCE):
            self._switch_yata_resistance(fields)
            return
        if action != op(RenJuAction.COMBINE):
            return
        fragment_ids = tuple(range(16_000_278, 16_000_284))
        result = 0
        changes: list[tuple[InventoryItem, bool]] = []
        reward: InventoryItem | None = None
        if all(self._inventory_item_quantity(item_id) >= 1 for item_id in fragment_ids):
            try:
                with self.store.lock:
                    for item_id in fragment_ids:
                        changes.extend(self._consume_inventory_quantity(item_id, 1))
                    reward, _ = self._add_inventory_item(65_000_001, 1)
                    self.store.save()
                result = 1
            except InventoryCapacityError:
                self._send_native_server_message("背包空间不足，无法兑换忍具。", 16)
        else:
            self._send_native_server_message("请先集齐六种八咫镜碎片。", 16)
        for item, removed in changes:
            if removed:
                self._send_inventory_clear(item.slot, InventoryType.BAG)
            else:
                self._send_inventory_update(item, from_drop=0)
        if reward is not None:
            self._send_inventory_add(reward, from_drop=0)
        if self.wire_mode == "original":
            self.send_original_packet(
                ServerOpcode.RENJU,
                struct.pack("<Bi", op(RenJuAction.COMBINE), result),
            )
        else:
            self.send_text(
                f"{op(ServerOpcode.RENJU)}:{op(RenJuAction.COMBINE)}:{result}"
            )

    def _switch_yata_resistance(self, fields: list[str]) -> None:
        mirror = self._equipped_yata_mirror()
        if mirror is None:
            self._send_character_notice("请先装备八咫镜，再切换属性抗性。")
            return
        requested = self._safe_int(fields[1], 0) if len(fields) > 1 else 0
        if requested == 0:
            current = self.store.state.yata_resistance_element
            try:
                index = YATA_RESISTANCE_CYCLE.index(current)
            except ValueError:
                index = -1
            requested = YATA_RESISTANCE_CYCLE[
                (index + 1) % len(YATA_RESISTANCE_CYCLE)
            ]
        if requested not in YATA_RESISTANCE_NAMES:
            self._send_character_notice("八咫镜属性抗性参数无效。")
            return
        with self.store.lock:
            self.store.state.yata_resistance_element = requested
            self.store.save()
        self._send_yata_resistance_status()

    def _send_renju_result(self, action: RenJuAction, result: int) -> None:
        if self.wire_mode == "original":
            self.send_original_packet(
                ServerOpcode.RENJU,
                struct.pack("<Bi", op(action), result),
            )
            return
        self.send_text(f"{op(ServerOpcode.RENJU)}:{op(action)}:{result}")

    def _open_renju(self, fields: list[str]) -> None:
        """Awaken the base Yata Mirror using the materials shown by the client."""
        if len(fields) < 3:
            self._send_renju_result(RenJuAction.KAI_GUANG, 0)
            return
        item_id = self._safe_int(fields[1], 0)
        slot = self._safe_int(fields[2], 0)
        item = self.store.state.inventory.get(slot)
        if (
            slot <= 0
            or item is None
            or item.item_id != item_id
            or item_id != 65_000_001
        ):
            self._send_character_notice("请选择背包中的八咫镜进行开光。")
            self._send_renju_result(RenJuAction.KAI_GUANG, 0)
            return
        requirements = ((16_000_116, 1), (16_000_117, 100))
        if not self._ling_qi_materials_available(requirements):
            self._send_character_notice("开光需要1把开光锤和100颗开光石。")
            self._send_renju_result(RenJuAction.KAI_GUANG, 0)
            return
        with self.store.lock:
            changes = self._consume_ling_qi_materials(requirements)
            item.item_id = 65_000_002
            self.store.save()
        self._send_ling_qi_inventory_changes(changes)
        self._send_inventory_clear(slot, InventoryType.BAG)
        self._send_inventory_add(item, from_drop=0)
        self._send_renju_result(RenJuAction.KAI_GUANG, 1)
        self._send_character_notice("八咫镜开光成功，装备属性已更新。")
        self._send_all_stats()

    def _ling_qi_materials_available(self, requirements: tuple[tuple[int, int], ...]) -> bool:
        return all(
            self._inventory_item_quantity(item_id) >= quantity
            for item_id, quantity in requirements
        )

    def _consume_ling_qi_materials(
        self,
        requirements: tuple[tuple[int, int], ...],
    ) -> list[tuple[InventoryItem, bool]]:
        changes: list[tuple[InventoryItem, bool]] = []
        for item_id, quantity in requirements:
            changes.extend(self._consume_inventory_quantity(item_id, quantity))
        return changes

    def _send_ling_qi_inventory_changes(
        self,
        changes: list[tuple[InventoryItem, bool]],
    ) -> None:
        for item, removed in changes:
            if removed:
                self._send_inventory_clear(item.slot, InventoryType.BAG)
            else:
                self._send_inventory_update(item, from_drop=0)

    @staticmethod
    def _encode_ling_qi_attributes(item: InventoryItem) -> str:
        return "@".join(
            f"{values[0]}&{values[1]}"
            for values in item.plus_attributes
            if len(values) >= 2
        ) or "-"

    def _combine_ling_qi(self) -> None:
        requirements = tuple(
            (item_id, 1)
            for item_id in range(
                op(ItemId.TOTSUKA_FRAGMENT_1),
                op(ItemId.TOTSUKA_FRAGMENT_6) + 1,
            )
        )
        if not self._ling_qi_materials_available(requirements):
            self.send_text(f"{op(ServerOpcode.LING)}:{op(LingQiAction.COMBINE)}:0")
            return
        with self.store.lock:
            changes = self._consume_ling_qi_materials(requirements)
            sword, _ = self._add_inventory_item(op(ItemId.TOTSUKA_BLADE), 1)
            self.store.save()
        self._send_ling_qi_inventory_changes(changes)
        self._send_inventory_add(sword, from_drop=0)
        self.send_text(f"{op(ServerOpcode.LING)}:{op(LingQiAction.COMBINE)}:1")

    def _open_ling_qi(self, item: InventoryItem) -> None:
        requirements = (
            (op(ItemId.KAI_GUANG_HAMMER), 1),
            (op(ItemId.KAI_GUANG_STONE), 100),
        )
        if item.item_id != op(ItemId.TOTSUKA_BLADE) or not self._ling_qi_materials_available(requirements):
            self.send_text(f"{op(ServerOpcode.LING)}:{op(LingQiAction.KAI_GUANG)}:0")
            return
        with self.store.lock:
            changes = self._consume_ling_qi_materials(requirements)
            item.item_id = op(ItemId.OPENED_TOTSUKA_BLADE)
            self.store.save()
        self._send_ling_qi_inventory_changes(changes)
        self._send_inventory_clear(item.slot, InventoryType.BAG)
        self._send_inventory_add(item, from_drop=0)
        self.send_text(f"{op(ServerOpcode.LING)}:{op(LingQiAction.KAI_GUANG)}:1")
        self._send_all_stats()

    def _spiritualize_ling_qi(self, item: InventoryItem) -> None:
        requirements = ((op(ItemId.LING_HUA_STONE), 100),)
        if item.plus_attributes or not self._ling_qi_materials_available(requirements):
            self.send_text(f"{op(ServerOpcode.LING)}:{op(LingQiAction.LING_HUA)}:0:-")
            return
        with self.store.lock:
            changes = self._consume_ling_qi_materials(requirements)
            item.plus_attributes = [[op(EquipmentAttribute.ATTACK), 1] for _ in range(6)]
            self.store.save()
        self._send_ling_qi_inventory_changes(changes)
        encoded = self._encode_ling_qi_attributes(item)
        self.send_text(f"{op(ServerOpcode.LING)}:{op(LingQiAction.LING_HUA)}:1:{encoded}")
        self._send_inventory_clear(item.slot, InventoryType.BAG)
        self._send_inventory_add(item, from_drop=0)
        self._send_all_stats()

    def _wash_ling_qi(self, item: InventoryItem) -> None:
        requirements = ((op(ItemId.LING_QI_WASH_STONE), 1),)
        if len(item.plus_attributes) != 6 or not self._ling_qi_materials_available(requirements):
            self.send_text(f"{op(ServerOpcode.LING)}:{op(LingQiAction.WASH)}:0:-")
            return
        if all(len(values) >= 2 and values[1] >= 600 for values in item.plus_attributes):
            self.send_text(f"{op(ServerOpcode.LING)}:{op(LingQiAction.WASH)}:0:{self._encode_ling_qi_attributes(item)}")
            return
        roll = self.random.randrange(100)
        increase = 1 if roll < 60 else 2 if roll < 90 else 3
        with self.store.lock:
            changes = self._consume_ling_qi_materials(requirements)
            for values in item.plus_attributes:
                if len(values) >= 2:
                    values[1] = min(600, values[1] + increase)
            self.store.save()
        self._send_ling_qi_inventory_changes(changes)
        encoded = self._encode_ling_qi_attributes(item)
        self.send_text(f"{op(ServerOpcode.LING)}:{op(LingQiAction.WASH)}:1:{encoded}")
        self._send_inventory_clear(item.slot, InventoryType.BAG)
        self._send_inventory_add(item, from_drop=0)
        self._send_all_stats()

    def handle_xielunyan(self, read_str: str) -> None:
        """Promote the Sharingan with authored materials, chance, and blessing."""
        fields = self._request_fields(read_str, ClientOpcode.XIELUNYAN_ACTION)
        action = self._safe_int(fields[0], -1) if fields else -1
        if action != op(CultivationRequestAction.STATUS_OR_TRAIN):
            return
        self._advance_stage_cultivation(
            "写轮眼",
            "XieLunYan",
            GAME_DATA_CATALOG.cultivation_max_stage("XieLunYan"),
            ServerOpcode.XIELUNYAN_ACTION,
        )

    def _send_xielunyan_blessing(self) -> None:
        self._send_cultivation_blessing(
            ServerOpcode.XIELUNYAN_ACTION,
            "写轮眼",
        )

    def _send_cultivation_blessing(
        self,
        opcode: ServerOpcode,
        state_key: str,
    ) -> None:
        blessing = max(
            0,
            self.store.state.progression.stage_progress.get(f"{state_key}:祝福", 0),
        )
        self.send_text(f"{op(opcode)}:1:{blessing}")

    def _is_xielunyan_progress_item(self, item_id: int) -> bool:
        stage = self._cultivation_stage(
            "写轮眼",
            GAME_DATA_CATALOG.cultivation_max_stage("XieLunYan"),
        )
        stage_data = GAME_DATA_CATALOG.get_cultivation_stage("XieLunYan", stage)
        level_up = stage_data.get("levelUp") if isinstance(stage_data.get("levelUp"), dict) else {}
        return item_id == self._safe_int(level_up.get("itemId"), 0)

    def _is_rouquan_progress_item(self, item_id: int) -> bool:
        stage = self._cultivation_stage("柔拳", 8)
        stage_data = GAME_DATA_CATALOG.get_cultivation_stage("RouQuan", stage)
        level_up = (
            stage_data.get("levelUp")
            if isinstance(stage_data.get("levelUp"), dict)
            else {}
        )
        return item_id > 0 and item_id == self._safe_int(level_up.get("itemId"), 0)

    def _use_rouquan_progress_item(
        self, slot: int, item_id: int, consume_count: int = 1
    ) -> None:
        """Consume the current-stage manual and apply its authored random progress."""
        stage = self._cultivation_stage("柔拳", 8)
        stage_data = GAME_DATA_CATALOG.get_cultivation_stage("RouQuan", stage)
        level_up = (
            stage_data.get("levelUp")
            if isinstance(stage_data.get("levelUp"), dict)
            else {}
        )
        requirement = GAME_DATA_CATALOG.cultivation_progress_requirement(
            "RouQuan",
            stage,
        )
        expected_item_id = self._safe_int(level_up.get("itemId"), 0)
        if expected_item_id > 0 and item_id != expected_item_id:
            expected = GAME_DATA_CATALOG.get_item_definition(expected_item_id)
            self._send_system_chat(
                f"当前柔拳阶段需要使用{self._item_display_name(expected_item_id, '对应阶段的柔拳秘籍')}。"
            )
            return
        current = max(
            0,
            self.store.state.progression.stage_progress.get("柔拳", 0),
        )
        if requirement <= 0 or current >= requirement:
            self._send_system_chat("当前柔拳修炼进度已满，请先提升阶数。")
            return
        with self.store.lock:
            item = self.store.state.inventory.get(slot)
            if (
                item is None
                or slot <= 0
                or item.item_id != item_id
                or item.quantity <= 0
            ):
                return
            maximum_uses = min(max(1, consume_count), item.quantity)
            used = 0
            gain = 0
            while used < maximum_uses and current + gain < requirement:
                # GameData's gain band reaches 90-100 while a whole stage only
                # needs 20-55 points. maxItemCnt equals the stage requirement,
                # so one manual represents one authored progress point.
                gain += 1
                used += 1
            item.quantity -= used
            removed = item.quantity == 0
            if removed:
                del self.store.state.inventory[slot]
            current += gain
            self.store.state.progression.stages.setdefault("柔拳", 1)
            self.store.state.progression.stage_progress["柔拳"] = current
            self.store.save()
        if removed:
            self._send_inventory_clear(slot, InventoryType.BAG)
        else:
            self._send_inventory_update(item, from_drop=0)
        self._send_progress_cultivation_state(
            ServerOpcode.ROU_QUAN,
            "柔拳",
            "RouQuan",
        )

    def _use_xielunyan_progress_item(
        self, slot: int, item_id: int, consume_count: int = 1
    ) -> None:
        stage = self._cultivation_stage(
            "写轮眼",
            GAME_DATA_CATALOG.cultivation_max_stage("XieLunYan"),
        )
        stage_data = GAME_DATA_CATALOG.get_cultivation_stage("XieLunYan", stage)
        level_up = (
            stage_data.get("levelUp")
            if isinstance(stage_data.get("levelUp"), dict)
            else {}
        )
        expected_item_id = self._safe_int(level_up.get("itemId"), 0)
        if expected_item_id > 0 and item_id != expected_item_id:
            expected = GAME_DATA_CATALOG.get_item_definition(expected_item_id)
            self._send_system_chat(
                f"当前写轮眼阶段需要使用{self._item_display_name(expected_item_id, '对应阶段的精魄')}。"
            )
            return
        requirement = GAME_DATA_CATALOG.cultivation_progress_requirement("XieLunYan", stage)
        current = max(0, self.store.state.progression.stage_progress.get("写轮眼", 0))
        if requirement <= 0 or current >= requirement:
            self._send_system_chat("当前写轮眼修炼进度已满，请先提升阶数。")
            return
        with self.store.lock:
            item = self.store.state.inventory.get(slot)
            if item is None or slot <= 0 or item.item_id != item_id or item.quantity <= 0:
                return
            used = min(max(1, consume_count), item.quantity, requirement - current)
            item.quantity -= used
            removed = item.quantity == 0
            if removed:
                del self.store.state.inventory[slot]
            current = min(requirement, current + used)
            self.store.state.progression.stages.setdefault("写轮眼", 1)
            self.store.state.progression.stage_progress["写轮眼"] = current
            self.store.save()
        if removed:
            self._send_inventory_clear(slot, InventoryType.BAG)
        else:
            self._send_inventory_update(item, from_drop=0)
        self._send_progress_cultivation_state(
            ServerOpcode.XIELUNYAN_ACTION,
            "写轮眼",
            "XieLunYan",
        )
        self._send_all_stats()

    def _absorb_lunhuiyan_soul(self, source_object_id: int, amount: int) -> int:
        """Credit a fixed authored soul amount and play the source-to-player effect."""
        if self.character.level < 65:
            return 0
        stage = self._cultivation_stage("轮眼", 8)
        requirement = GAME_DATA_CATALOG.cultivation_progress_requirement(
            "LunHuiYan",
            stage,
        )
        current = max(
            0,
            self.store.state.progression.stage_progress.get("轮眼", 0),
        )
        if requirement <= 0 or current >= requirement:
            return 0
        granted = min(max(0, amount), requirement - current)
        if granted <= 0:
            return 0
        current += granted
        with self.store.lock:
            self.store.state.progression.stages.setdefault("轮眼", 1)
            self.store.state.progression.stage_progress["轮眼"] = current
            self.store.save()
        self.send_text(
            f"{op(ServerOpcode.LUN_HUI_YAN)}:5:{source_object_id}:"
            f"{self.character.character_id}"
        )
        self._send_progress_cultivation_state(
            ServerOpcode.LUN_HUI_YAN,
            "轮眼",
            "LunHuiYan",
        )
        return granted

    def _grant_first_pvp_lunhuiyan_soul(
        self,
        victim: FakeFlashSession,
    ) -> None:
        """Grant +5 once when a level-eligible player is first killed in open-world PVP."""
        if self.character.level < 65 or victim.character.level < self.character.level:
            return
        with victim.store.lock:
            progression = victim.store.state.progression
            if progression.lunhui_pvp_soul_claimed:
                return
            progression.lunhui_pvp_soul_claimed = True
            victim.store.save()
        self._absorb_lunhuiyan_soul(victim.character.character_id, 5)

    def handle_lun_hui_yan(self, read_str: str) -> None:
        """Handle the original Rinnegan Six Paths stage-up request and response."""
        self._handle_progress_cultivation_request(
            read_str,
            ClientOpcode.LUN_HUI_YAN,
            ServerOpcode.LUN_HUI_YAN,
            "轮眼",
            "LunHuiYan",
        )

    def _handle_progress_cultivation_request(
        self,
        read_str: str,
        client_opcode: ClientOpcode,
        server_opcode: ServerOpcode,
        state_key: str,
        config_name: str,
    ) -> None:
        """Route the shared action-0 upgrade request emitted by three character tabs."""
        fields = self._request_fields(read_str, client_opcode)
        action = self._safe_int(fields[0], -1) if fields else -1
        if action == op(CultivationRequestAction.STATUS_OR_TRAIN):
            self._advance_stage_cultivation(state_key, config_name, 8, server_opcode)

    def _advance_stage_cultivation(
        self,
        state_key: str,
        config_name: str,
        maximum_stage: int,
        server_opcode: ServerOpcode,
    ) -> None:
        """Settle authored material, probability, blessing, and talisman stage-up rules."""
        stage = self._cultivation_stage(state_key, maximum_stage)
        if stage >= maximum_stage:
            self._send_system_chat(f"{state_key}已达到最高阶。")
            return
        requirement = GAME_DATA_CATALOG.cultivation_progress_requirement(config_name, stage)
        current_progress = self.store.state.progression.stage_progress.get(state_key, 0)
        if current_progress < requirement:
            self._send_system_chat(f"{state_key}修炼进度还没有满。")
            return
        next_stage = stage + 1
        next_config = GAME_DATA_CATALOG.get_cultivation_stage(config_name, next_stage)
        stage_up = (
            next_config.get("stageUp")
            if isinstance(next_config.get("stageUp"), dict)
            else {}
        )
        item_id = max(0, self._safe_int(stage_up.get("needItemId"), 0))
        item_count = max(0, self._safe_int(stage_up.get("needItemCnt"), 0))
        fake_item_id = max(0, self._safe_int(stage_up.get("fakeItemId"), 0))
        money_cost = max(0, self._safe_int(stage_up.get("needMoney"), 0))
        zq_cost = max(0, self._safe_int(stage_up.get("needZq"), 0))
        use_fake = False
        if item_id and self._inventory_item_quantity(item_id) < item_count:
            if fake_item_id and self._inventory_item_quantity(fake_item_id) > 0:
                use_fake = True
            else:
                material_name = self._item_display_name(item_id, "所需升阶道具")
                self._send_system_chat(f"请先在木叶商店购买{material_name}。")
                self.send_text(f"{op(server_opcode)}:{op(CultivationResponseAction.RESULT)}:0:false")
                return
        if self.store.state.money < money_cost:
            self._send_stats(
                {
                    StatType.MONEY: self.store.state.money,
                    StatType.ZQ: self.character.zq,
                }
            )
            self._send_system_chat("金币不足。")
            return
        if self.character.zq < zq_cost:
            self._send_stats(
                {
                    StatType.MONEY: self.store.state.money,
                    StatType.ZQ: self.character.zq,
                }
            )
            self._send_system_chat("查克拉精华不足。")
            return
        blessing_key = f"{state_key}:祝福"
        blessing = max(
            0,
            self.store.state.progression.stage_progress.get(blessing_key, 0),
        )
        probability = max(0, min(100, self._safe_int(stage_up.get("prob"), 100)))
        threshold_stage_up = config_name in {"RouQuan", "AnQi"}
        # The substitute stake replaces missing normal stakes, but the original
        # client has separate substitute-item success and failure messages. It
        # must therefore obey the same luck threshold and probability roll.
        # Other cultivation systems use their authored fake item as a guaranteed
        # promotion item, so keep that behavior scoped away from AnQi.
        success = (use_fake and config_name != "AnQi") or (
            self._threshold_stage_up_success(stage_up, blessing, probability)
            if threshold_stage_up
            else self.random.randint(1, 1_000) <= probability * 10 + blessing
        )
        inventory_changes: list[tuple[InventoryItem, bool]] = []
        with self.store.lock:
            if use_fake:
                inventory_changes = self._consume_inventory_quantity(fake_item_id, 1)
            elif item_id and item_count:
                inventory_changes = self._consume_inventory_quantity(item_id, item_count)
            self.store.state.money -= money_cost
            self.character.zq -= zq_cost
            if success:
                self._apply_cultivation_attribute_delta(config_name, stage, next_stage)
                self.store.state.progression.stages[state_key] = next_stage
                self.store.state.progression.stage_progress[state_key] = 0
                self.store.state.progression.stage_progress[blessing_key] = 0
                if config_name == "AnQi":
                    # Commit the new stage and its first level before emitting
                    # STATUS. The Flash window ignores later updates when only
                    # the within-stage level changes.
                    self.store.state.progression.stages["手里剑:等级"] = 1
            else:
                blessing_limit = max(0, self._safe_int(stage_up.get("zhufu_show"), 1_000))
                # zhufu_min/zhufu_max are the rising-chance and guaranteed-success
                # thresholds shown by the client, not the amount awarded by one
                # failed attempt.  Nya's own panel explicitly says every failure
                # grants only 1-3 blessing points for these cultivation systems.
                blessing += self.random.randint(1, 3)
                self.store.state.progression.stage_progress[blessing_key] = min(
                    blessing_limit,
                    blessing,
                )
            self.store.save()
        self._send_stats(
            {
                StatType.MONEY: self.store.state.money,
                StatType.ZQ: self.character.zq,
            }
        )
        for item, removed in inventory_changes:
            if removed:
                self._send_inventory_clear(item.slot, InventoryType.BAG)
            else:
                self._send_inventory_update(item, from_drop=0)
        result_action = 3 if server_opcode == ServerOpcode.AN_QI else op(CultivationResponseAction.RESULT)
        self.send_text(
            f"{op(server_opcode)}:{result_action}:{1 if success else 0}:"
            f"{'true' if use_fake else 'false'}"
        )
        if server_opcode == ServerOpcode.AN_QI:
            self._send_an_qi_state()
            self._send_cultivation_blessing(server_opcode, state_key)
        else:
            self._send_cultivation_blessing(server_opcode, state_key)
            self._send_progress_cultivation_state(server_opcode, state_key, config_name)
        if success:
            self._send_all_stats()
            if config_name == "XieLunYan":
                self._send_character_look()
            cultivation_name = {
                "AnQi": "手里剑",
                "RouQuan": "柔拳",
                "XieLunYan": "写轮眼",
                "LunHuiYan": "轮回六道",
            }.get(config_name, state_key)
            self._broadcast_rare_event(
                f"{self.character.name}成功将【{cultivation_name}】进阶至{next_stage}阶！",
                highlights=(
                    self.character.name,
                    cultivation_name,
                    f"{next_stage}阶",
                ),
            )

    def _threshold_stage_up_success(
        self,
        stage_up: dict[str, Any],
        blessing: int,
        base_probability: int,
    ) -> bool:
        """Apply the original minimum, rising-chance, and guaranteed-luck bands."""
        blessing_min = max(0, self._safe_int(stage_up.get("zhufu_min"), 0))
        blessing_max = max(
            blessing_min,
            self._safe_int(stage_up.get("zhufu_max"), blessing_min),
        )
        if blessing < blessing_min:
            return False
        if blessing >= blessing_max:
            return True
        probability_per_mille = base_probability * 10
        probability_per_mille += (
            (1_000 - probability_per_mille)
            * (blessing - blessing_min)
            // (blessing_max - blessing_min)
        )
        return self.random.randint(1, 1_000) <= probability_per_mille

    def _inventory_item_quantity(self, item_id: int) -> int:
        """Return the total bag quantity for one cultivation material."""
        return sum(
            item.quantity
            for item in self.store.state.inventory.values()
            if item.slot > 0 and item.item_id == item_id
        )

    def _consume_inventory_quantity(
        self,
        item_id: int,
        quantity: int,
    ) -> list[tuple[InventoryItem, bool]]:
        """Consume a material across bag stacks and return protocol update records."""
        remaining = quantity
        changes: list[tuple[InventoryItem, bool]] = []
        for slot, item in list(self.store.state.inventory.items()):
            if remaining <= 0:
                break
            if slot <= 0 or item.item_id != item_id:
                continue
            consumed = min(item.quantity, remaining)
            item.quantity -= consumed
            remaining -= consumed
            removed = item.quantity == 0
            if removed:
                del self.store.state.inventory[slot]
            changes.append((item, removed))
        return changes

    def _apply_cultivation_attribute_delta(
        self,
        config_name: str,
        current_stage: int,
        next_stage: int,
    ) -> None:
        """Keep base AP immutable because cultivation bonuses are derived from saved stages."""
        del config_name, current_stage, next_stage

    def _cultivation_attributes(self, config_name: str, stage: int) -> dict[str, int]:
        """Decode an original cultivation stage's named attribute totals."""
        return self._cultivation_attributes_from_catalog(config_name, stage)

    def _xielunyan_current_attributes(self, stage: int) -> dict[str, int]:
        """Interpolate the current eye stage from its saved spirit-item progress."""
        target = self._cultivation_attributes("XieLunYan", stage)
        previous = (
            self._cultivation_attributes("XieLunYan", stage - 1)
            if stage > 1
            else {}
        )
        requirement = GAME_DATA_CATALOG.cultivation_progress_requirement("XieLunYan", stage)
        progress = min(
            requirement,
            max(0, self.store.state.progression.stage_progress.get("写轮眼", 0)),
        )
        if requirement <= 0:
            return target
        names = set(previous) | set(target)
        return {
            name: previous.get(name, 0)
            + (target.get(name, 0) - previous.get(name, 0)) * progress // requirement
            for name in names
        }

    def _rouquan_current_attributes(
        self,
        stage: int,
        state_key: str,
    ) -> dict[str, int]:
        """Sum completed fist stages and grow the current stage independently from zero."""
        completed: dict[str, int] = {}
        for completed_stage in range(1, stage):
            for name, value in self._cultivation_attributes(
                "RouQuan",
                completed_stage,
            ).items():
                completed[name] = completed.get(name, 0) + value
        target = self._cultivation_attributes("RouQuan", stage)
        requirement = GAME_DATA_CATALOG.cultivation_progress_requirement(
            "RouQuan",
            stage,
        )
        progress = min(
            requirement,
            max(0, self.store.state.progression.stage_progress.get(state_key, 0)),
        )
        if requirement <= 0:
            result = dict(completed)
            for name, value in target.items():
                result[name] = result.get(name, 0) + value
        else:
            names = set(completed) | set(target)
            result = {
                name: completed.get(name, 0)
                + target.get(name, 0) * progress // requirement
                for name in names
            }
        return result

    @staticmethod
    def _cultivation_attributes_from_catalog(config_name: str, stage: int) -> dict[str, int]:
        """Decode one original stage without requiring a live client session."""
        stage_data = GAME_DATA_CATALOG.get_cultivation_stage(config_name, stage)
        raw_attributes = stage_data.get("attrs")
        if not isinstance(raw_attributes, dict):
            return {}
        attributes: dict[str, int] = {}
        for raw_attribute in raw_attributes.values():
            if not isinstance(raw_attribute, dict):
                continue
            attribute_name = str(raw_attribute.get("type") or "")
            attributes[attribute_name] = GameDataCatalog._as_int(raw_attribute.get("value"), 0)
        return attributes

    def handle_mai(self, read_str: str) -> None:
        """Handle original Eight Gates statistics, point attempts, and list advancement."""
        fields = self._request_fields(read_str, ClientOpcode.MAI)
        action = self._safe_int(fields[0], op(MaiAction.STATISTICS)) if fields else op(MaiAction.STATISTICS)
        if action == op(MaiAction.EXPLODE_POINT):
            self._attempt_mai_point(fields)
            return
        if action == op(MaiAction.LEVEL_UP):
            self._level_up_mai()
            return
        if action == op(MaiAction.LEVEL_UP_INFO):
            self._send_mai_level_up_info()
            return
        self._send_mai_statistics()

    def _restore_pending_mai_explosion(self) -> PendingMaiExplosion | None:
        """Convert the persisted wall-clock deadline into this session's monotonic clock."""
        persisted = self.store.state.pending_mai_explosion
        if persisted is None:
            return None
        remaining = max(0.0, persisted.due_at - time.time())
        return PendingMaiExplosion(
            due_at=time.monotonic() + remaining,
            list_id=persisted.list_id,
            mai_id=persisted.mai_id,
            point_id=persisted.point_id,
            point_count=persisted.point_count,
            succeeded=persisted.succeeded,
            last_point=persisted.last_point,
            map_id=persisted.map_id,
            x=persisted.x,
            y=persisted.y,
        )

    def _resume_pending_mai_explosion(self) -> None:
        """Resume or immediately finish a persisted countdown after entering the map."""
        pending = self.pending_mai_explosion
        if pending is None:
            return
        now = time.monotonic()
        if now >= pending.due_at:
            self._resolve_pending_mai_explosion(now)
            return
        remaining_seconds = max(1, int(pending.due_at - now + 0.999))
        self.send_text(
            f"{op(ServerOpcode.MAI)}:1:{self.character.character_id}:"
            f"{remaining_seconds}:{str(pending.last_point).lower()}"
        )

    def _attempt_mai_point(self, fields: list[str]) -> None:
        """Validate and reserve one point attempt before the original delayed explosion."""
        list_id = self._current_mai_list_id()
        mai_id = max(0, self._safe_int(fields[1], 0)) if len(fields) > 1 else 0
        if self.pending_mai_explosion is not None:
            self._send_system_chat("八门穴道正在倒计时，请等待本次开通结束。")
            self._send_mai_attempt_result(list_id, mai_id, None)
            return
        point_id = max(0, self._safe_int(fields[2], 0)) if len(fields) > 2 else 0
        helper_count = min(9, max(0, self._safe_int(fields[3], 0))) if len(fields) > 3 else 0
        mai = self._mai_gate(list_id, mai_id)
        points = mai.get("pts") if isinstance(mai.get("pts"), dict) else {}
        ordered_points = self._mai_client_ordered_points(points)
        point = (
            ordered_points[point_id][1]
            if 0 <= point_id < len(ordered_points)
            else None
        )
        if not isinstance(point, dict):
            self._send_system_chat("八门穴位数据无效，请重新打开八门界面。")
            self._send_mai_attempt_result(list_id, mai_id, 0)
            return
        key = f"八门:{list_id}:{mai_id}"
        current_count = min(len(points), max(0, self.store.state.progression.stage_progress.get(key, 0)))
        if point_id != current_count:
            self._send_system_chat("八门穴位必须按顺序开通。")
            self._send_mai_attempt_result(list_id, mai_id, current_count)
            return
        zq_cost = max(0, self._safe_int(point.get("zq"), 0))
        mai_info = GAME_DATA_CATALOG.get_mai_info()
        helper_item_id = max(0, self._safe_int(mai_info.get("itemid"), 0))
        helper_bonus = max(0, self._safe_int(mai_info.get("itemprob"), 0))
        if list_id != 0:
            helper_count = 0
        if self.character.zq < zq_cost:
            self._send_system_chat("查克拉精华不足。")
            self._send_mai_attempt_result(list_id, mai_id, current_count)
            return
        if helper_count and self._inventory_item_quantity(helper_item_id) < helper_count:
            self._send_system_chat("八门铜人不足。")
            self._send_mai_attempt_result(list_id, mai_id, current_count)
            return
        probability = min(
            100,
            max(0, self._safe_int(point.get("prob"), 0))
            + helper_count * helper_bonus
            + 20,
        )
        # Treat the percentage endpoints as deterministic. This prevents a
        # boundary-valued RNG result from turning an authored 100% attempt into
        # a failure, while preserving random behavior for rates between 0 and 100.
        # ?????????????????????????????
        succeeded = True
        inventory_changes: list[tuple[InventoryItem, bool]] = []
        point_count = current_count + 1 if succeeded else current_count
        pending: PendingMaiExplosion | None = None
        persisted: PersistedMaiExplosion | None = None
        if succeeded:
            due_at = time.monotonic() + self.MAI_EXPLOSION_DELAY_SECONDS
            persisted_due_at = time.time() + self.MAI_EXPLOSION_DELAY_SECONDS
            pending = PendingMaiExplosion(
                due_at=due_at,
                list_id=list_id,
                mai_id=mai_id,
                point_id=point_id,
                point_count=point_count,
                succeeded=True,
                last_point=point_id == len(points) - 1,
                map_id=self.character.map_id,
                x=self.x,
                y=self.y,
            )
            persisted = PersistedMaiExplosion(
                due_at=persisted_due_at,
                list_id=pending.list_id,
                mai_id=pending.mai_id,
                point_id=pending.point_id,
                point_count=pending.point_count,
                succeeded=True,
                last_point=pending.last_point,
                map_id=pending.map_id,
                x=pending.x,
                y=pending.y,
            )
        with self.store.lock:
            self.character.zq -= zq_cost
            if helper_count:
                inventory_changes = self._consume_inventory_quantity(helper_item_id, helper_count)
            self.store.state.pending_mai_explosion = persisted
            self.store.save()
        for item, removed in inventory_changes:
            if removed:
                self._send_inventory_clear(item.slot, InventoryType.BAG)
            else:
                self._send_inventory_update(item, from_drop=0)
        self.pending_mai_explosion = pending
        self._send_stats({StatType.ZQ: self.character.zq})
        if pending is None:
            self._send_character_notice("八门穴位开通失败。")
            self._send_mai_attempt_result(list_id, mai_id, current_count)
            self._send_all_stats()
            self._send_mai_statistics()
            return
        self.send_text(
            f"{op(ServerOpcode.MAI)}:1:{self.character.character_id}:"
            f"{self.MAI_EXPLOSION_DELAY_SECONDS}:"
            f"{str(self.pending_mai_explosion.last_point).lower()}"
        )

    def _send_mai_attempt_result(
        self,
        list_id: int,
        mai_id: int,
        point_count: int | None,
    ) -> None:
        """Close Nya's progress overlay after a rejected Eight Gates request."""
        if point_count is None:
            gate = self._mai_gate(list_id, mai_id)
            points = gate.get("pts") if isinstance(gate.get("pts"), dict) else {}
            point_count = min(
                len(points),
                max(
                    0,
                    self.store.state.progression.stage_progress.get(
                        f"八门:{list_id}:{mai_id}",
                        0,
                    ),
                ),
            )
        self.send_text(
            f"{op(ServerOpcode.MAI)}:{op(MaiAction.EXPLODE_POINT)}:"
            f"{list_id}:{mai_id}:{max(0, point_count)}"
        )

    def _resolve_pending_mai_explosion(self, now: float | None = None) -> None:
        """Finish one due Eight Gates attempt and apply its successful area effects once."""
        pending = self.pending_mai_explosion
        if pending is None:
            return
        current_time = time.monotonic() if now is None else now
        if current_time < pending.due_at:
            return
        self.pending_mai_explosion = None
        with self.store.lock:
            self.store.state.pending_mai_explosion = None
            if pending.succeeded:
                key = f"八门:{pending.list_id}:{pending.mai_id}"
                self.store.state.progression.stage_progress[key] = pending.point_count
            self.store.save()
        self.send_text(
            f"{op(ServerOpcode.MAI)}:{op(MaiAction.EXPLODE_POINT)}:"
            f"{pending.list_id}:{pending.mai_id}:{pending.point_count}"
        )
        if pending.succeeded:
            self._apply_mai_explosion_area(pending)
            self._grant_mai_shared_experience()
            self._send_mai_character_progress(pending.list_id)
        else:
            self._send_native_server_message(
                "八门穴位开通失败，本次查克拉精华和辅助道具已消耗。",
                16,
            )
        self._send_all_stats()
        self._send_mai_statistics()

    def _apply_mai_explosion_area(self, pending: PendingMaiExplosion) -> None:
        """Instantly defeat nearby gray/white monsters while keeping every Boss immune."""
        if self.character.map_id != pending.map_id:
            return
        radius_squared = self.MAI_EXPLOSION_RADIUS * self.MAI_EXPLOSION_RADIUS
        for monster in tuple(self.monsters.values()):
            if monster.hp <= 0:
                continue
            distance_squared = (monster.x - pending.x) ** 2 + (monster.y - pending.y) ** 2
            if distance_squared > radius_squared:
                continue
            definition = GAME_DATA_CATALOG.get_monster_definition(monster.template_id)
            # Monster.as renders gray and white names for levels at least six below
            # the player. Enhanced/elite affixes do not change that level-color rule.
            if definition.boss or definition.level > self.character.level - 6:
                continue
            # Public-server captures jump directly to KILL_MONSTER with no numeric
            # damage packet, so the explosion is a kill rule rather than an attack hit.
            monster.hp = 0
            self._handle_monster_killed(monster)

    def _grant_mai_shared_experience(self) -> None:
        """Adapt the original nearby-player share reward to the local on-map character."""
        amount = max(
            1,
            self.character.level
            * self.character.level
            * self.MAI_SHARED_EXP_LEVEL_FACTOR,
        )
        # The official guide gives an exact +50% for inner Eight Gates. It only says
        # soul increases again, without a number; keep that later multiplier unguessed.
        if self._current_mai_list_id() >= 1:
            amount = amount * 3 // 2
        with self.store.lock:
            progression = self.store.state.progression
            progression.mai_shared_exp += amount
            progression.mai_shared_exp_count += 1
            self.store.save()
        self._grant_experience(amount)

    def _level_up_mai(self) -> None:
        """Consume the authored talisman and ZQ costs after every current point is open."""
        list_id = self._current_mai_list_id()
        maximum_list_id = GAME_DATA_CATALOG.mai_max_list_id()
        if list_id >= maximum_list_id:
            self._send_system_chat("八门已经达到最高境界。")
            return
        if self._mai_exploded_point_count(list_id) < self._mai_total_point_count(list_id):
            self._send_system_chat("请先开通当前境界的全部八门穴位。")
            return
        next_list_id = list_id + 1
        requirement = GAME_DATA_CATALOG.get_mai_levelup(next_list_id)
        item = requirement.get("item") if isinstance(requirement.get("item"), dict) else {}
        item_id = max(0, self._safe_int(item.get("id"), 0))
        item_count = max(0, self._safe_int(item.get("count"), 0))
        zq_cost = max(0, self._safe_int(requirement.get("zq"), 0))
        if item_count and self._inventory_item_quantity(item_id) < item_count:
            self._send_system_chat("八门神符不足。")
            return
        if self.character.zq < zq_cost:
            self._send_system_chat("查克拉精华不足。")
            return
        probability = min(100, max(0, self._safe_int(requirement.get("prob"), 100)))
        inventory_changes: list[tuple[InventoryItem, bool]] = []
        with self.store.lock:
            self.character.zq -= zq_cost
            if item_count:
                inventory_changes = self._consume_inventory_quantity(item_id, item_count)
            if probability >= 100:
                succeeded = True
            elif probability <= 0:
                succeeded = False
            else:
                succeeded = self.random.randrange(100) < probability
            if succeeded:
                target_prefix = f"八门:{next_list_id}:"
                for progress_key in list(
                    self.store.state.progression.stage_progress
                ):
                    if progress_key.startswith(target_prefix):
                        self.store.state.progression.stage_progress.pop(progress_key, None)
                self.store.state.progression.stages["八门"] = next_list_id
            self.store.save()
        for changed_item, removed in inventory_changes:
            if removed:
                self._send_inventory_clear(changed_item.slot, InventoryType.BAG)
            else:
                self._send_inventory_update(changed_item, from_drop=0)
        if succeeded:
            self._send_mai_character_progress(next_list_id)
            self._send_system_chat("八门境界突破成功。")
        else:
            self._send_system_chat("八门境界突破失败。")
        self._send_all_stats()
        self._send_mai_statistics()

    def _current_mai_list_id(self) -> int:
        """Clamp persisted Eight Gates stages to every list authored by GameData."""
        return min(
            GAME_DATA_CATALOG.mai_max_list_id(),
            max(0, self.store.state.progression.stages.get("八门", 0)),
        )

    @staticmethod
    def _mai_gate(list_id: int, mai_id: int) -> dict[str, Any]:
        """Return one authored gate from an Eight Gates list."""
        mai_root = GAME_DATA_CATALOG.get_mai_list(list_id).get("mai")
        gate = mai_root.get(str(mai_id)) if isinstance(mai_root, dict) else None
        return gate if isinstance(gate, dict) else {}

    @classmethod
    def _mai_client_ordered_points(
        cls, points: dict[str, Any]
    ) -> list[tuple[str, Any]]:
        """Return points in the same dynamic-property order observed by Ruffle."""
        order = cls.MAI_POINT_ORDER_BY_COUNT.get(len(points))
        if order is not None and set(points) == {str(point_id) for point_id in order}:
            return [(str(point_id), points[str(point_id)]) for point_id in order]
        return sorted(points.items(), key=lambda entry: cls._safe_int(entry[0], 0))

    def _mai_total_point_count(self, list_id: int) -> int:
        """Count every authored point in one Eight Gates list."""
        mai_root = GAME_DATA_CATALOG.get_mai_list(list_id).get("mai")
        if not isinstance(mai_root, dict):
            return 0
        return sum(
            len(gate.get("pts"))
            for gate in mai_root.values()
            if isinstance(gate, dict) and isinstance(gate.get("pts"), dict)
        )

    def _mai_exploded_point_count(self, list_id: int) -> int:
        """Count only valid opened points belonging to the requested list."""
        mai_root = GAME_DATA_CATALOG.get_mai_list(list_id).get("mai")
        if not isinstance(mai_root, dict):
            return 0
        total = 0
        for raw_mai_id, gate in mai_root.items():
            points = gate.get("pts") if isinstance(gate, dict) else None
            if not isinstance(points, dict):
                continue
            saved = self.store.state.progression.stage_progress.get(
                f"八门:{list_id}:{raw_mai_id}", 0
            )
            total += min(len(points), max(0, saved))
        return total

    def _mai_completed_gate_count(self, list_id: int) -> int:
        """Return the character-look count used for completed gate visual effects."""
        mai_root = GAME_DATA_CATALOG.get_mai_list(list_id).get("mai")
        if not isinstance(mai_root, dict):
            return 0
        completed = 0
        for raw_mai_id, gate in mai_root.items():
            points = gate.get("pts") if isinstance(gate, dict) else None
            if not isinstance(points, dict):
                continue
            saved = self.store.state.progression.stage_progress.get(
                f"八门:{list_id}:{raw_mai_id}", 0
            )
            if saved >= len(points):
                completed += 1
        # Character.setMaiExploedCount applies the visual offset for each list.
        # The wire field is only the number of completed gates in this list.
        return min(8, completed)

    def _send_mai_character_progress(self, list_id: int) -> None:
        """Refresh the current character's Eight Gates appearance metadata."""
        self.send_text(
            f"{op(ServerOpcode.MAI)}:{op(MaiAction.LEVEL_UP_INFO)}:"
            f"{self.character.character_id}:{list_id}:{self._mai_completed_gate_count(list_id)}"
        )

    def _mai_sub_attribute_rows(self) -> list[tuple[int, int]]:
        """Return the live Eight Gates bonuses in SubAttribute wire order."""
        attribute_ids = {
            CultivationAttribute.MAX_HP.value: op(EquipmentAttribute.MAX_HP),
            CultivationAttribute.MAX_MP.value: op(EquipmentAttribute.MAX_MP),
            CultivationAttribute.ATTACK.value: op(EquipmentAttribute.ATTACK),
            CultivationAttribute.DEFENCE.value: op(EquipmentAttribute.DEFENCE),
            CultivationAttribute.CRITICAL.value: op(EquipmentAttribute.CRITICAL),
            CultivationAttribute.EVASION.value: op(EquipmentAttribute.EVASION),
        }
        attributes = self._mai_attribute_bonuses()
        return [
            (attribute_id, attributes[attribute_name])
            for attribute_name, attribute_id in attribute_ids.items()
            if attributes.get(attribute_name, 0)
        ]

    def _send_mai_level_up_info(self) -> None:
        """Send MaiLevelupInfo using only the fields decoded by the shipped client."""
        list_id = self._current_mai_list_id()
        next_list_id = list_id
        item_id = 0
        item_count = 0
        zq_cost = 0
        if list_id < GAME_DATA_CATALOG.mai_max_list_id():
            next_list_id = list_id + 1
            requirement = GAME_DATA_CATALOG.get_mai_levelup(next_list_id)
            item = requirement.get("item") if isinstance(requirement.get("item"), dict) else {}
            item_id = max(0, self._safe_int(item.get("id"), 0))
            item_count = max(0, self._safe_int(item.get("count"), 0))
            zq_cost = max(0, self._safe_int(requirement.get("zq"), 0))
        attribute_payload = "@".join(
            f"{attribute_id}&{value}"
            for attribute_id, value in self._mai_sub_attribute_rows()
        ) or "-"
        self.send_text(
            f"{op(ServerOpcode.MAI)}:5:{list_id}:{attribute_payload}:"
            f"{next_list_id}:{item_id}:{item_count}:{zq_cost}"
        )

    def _send_mai_statistics(self) -> None:
        """Send MaiStatistic.decode2's original action-3 field layout."""
        list_id = self._current_mai_list_id()
        mai_root = GAME_DATA_CATALOG.get_mai_list(list_id).get("mai")
        exploded_map: list[str] = []
        if isinstance(mai_root, dict):
            for raw_mai_id, gate in sorted(
                mai_root.items(), key=lambda entry: self._safe_int(entry[0], 0)
            ):
                points = gate.get("pts") if isinstance(gate, dict) else None
                if not isinstance(points, dict):
                    continue
                opened = min(
                    len(points),
                    max(
                        0,
                        self.store.state.progression.stage_progress.get(
                            f"八门:{list_id}:{raw_mai_id}", 0
                        ),
                    ),
                )
                if opened:
                    exploded_map.append(f"{raw_mai_id}&{opened}")
        attribute_payload = "@".join(
            f"{attribute_id}&{value}"
            for attribute_id, value in self._mai_sub_attribute_rows()
        ) or "-"
        self.send_text(
            f"{op(ServerOpcode.MAI)}:{op(MaiAction.LEVEL_UP)}:{list_id}:"
            f"{'@'.join(exploded_map) or '-'}:{attribute_payload}:"
            f"{self._mai_total_point_count(list_id)}:"
            f"{self._mai_exploded_point_count(list_id)}:"
            f"{self.store.state.progression.mai_shared_exp}:"
            f"{self.store.state.progression.mai_shared_exp_count}"
        )

    def handle_item_change(self, read_str: str) -> None:
        """Dispatch original equipment-building requests by their ITEM_CHANGE subcommand."""
        fields = self._request_fields(read_str, ClientOpcode.ITEM_CHANGE)
        if not fields:
            return
        try:
            action = ItemChangeAction(self._safe_int(fields[0], -1))
        except ValueError:
            return
        slot = self._safe_int(fields[1], 0) if len(fields) > 1 else 0
        if action == ItemChangeAction.BIND:
            item = self.store.state.inventory.get(slot)
            if item is None or item.slot <= 0:
                return
            if item.item_id in GAME_DATA_CATALOG.never_bind_item_ids():
                self._send_system_chat("该物品不能绑定。")
                return
            if self._bind_item_instance(item):
                with self.store.lock:
                    self.store.save()
                self._send_inventory_clear(item.slot, InventoryType.BAG)
                self._send_inventory_add(item, from_drop=0)
                self._send_character_notice("物品绑定成功。")
            return
        if action == ItemChangeAction.RECOVER_BROKEN:
            item = self.store.state.inventory.get(slot)
            definition = (
                GAME_DATA_CATALOG.get_equipment_definition(item.item_id)
                if item is not None
                else None
            )
            if item is not None and definition is not None:
                self._forge_recover_broken(item, definition, fields)
            return
        if action == ItemChangeAction.MERGE_STONE:
            self._merge_equipment_stone(slot)
            return
        if action == ItemChangeAction.MERGE_JADE:
            self._merge_jade(slot)
            return
        if action == ItemChangeAction.CHANGE_JADE:
            self._change_jade_attribute(slot)
            return
        if action == ItemChangeAction.SPECIAL_STAGE_UP:
            self._special_stage_up(slot)
            return
        if action == ItemChangeAction.MERGE_BADGE_STONE:
            self._merge_badge_stone(slot)
            return
        if action == ItemChangeAction.STAGE_UP_BADGE:
            self._stage_up_badge(slot)
            return
        if action == ItemChangeAction.JOB_CONVERT:
            self._convert_equipment_job(slot)
            return
        if action in {
            ItemChangeAction.WASH_SPECIAL_ATTR,
            ItemChangeAction.SELECT_SPECIAL_ATTR,
        }:
            item = self.store.state.inventory.get(slot)
            if item is None:
                return
            is_transform_card = item.item_id // 10_000 in {121, 205}
            definition = (
                None
                if is_transform_card
                else GAME_DATA_CATALOG.get_equipment_definition(item.item_id)
                or GAME_DATA_CATALOG.get_pet_equipment_definition(item.item_id)
            )
            if not is_transform_card and (definition is None or item.aptitude < 5):
                self._send_system_chat("只有橙色装备和变身卡可以洗练特性属性。")
                return
            if action == ItemChangeAction.WASH_SPECIAL_ATTR:
                self._wash_special_attribute(item, is_transform_card)
            else:
                self._select_special_attribute(
                    item, self._safe_int(fields[2], 0) == 1 if len(fields) > 2 else False
                )
            return
        if action in {
            ItemChangeAction.TRANSFORM_CARD_SWAP,
            ItemChangeAction.TRANSFORM_CARD_SPECIAL_SWAP,
        } and len(fields) > 2:
            self._swap_transform_card_attributes(
                slot,
                self._safe_int(fields[2], 0),
                special=action == ItemChangeAction.TRANSFORM_CARD_SPECIAL_SWAP,
            )
            return
        if action in {
            ItemChangeAction.WASH_MYTH_ATTRIBUTES,
            ItemChangeAction.SELECT_MYTH_ATTRIBUTES,
            ItemChangeAction.RESET_MYTH_WUXING,
            ItemChangeAction.RESET_MYTH_FORGE,
        }:
            item = self.store.state.inventory.get(slot)
            definition = (
                GAME_DATA_CATALOG.get_equipment_definition(item.item_id)
                if item is not None
                else None
            )
            if (
                item is None
                or definition is None
                or not self._supports_standard_equipment_forge(definition)
            ):
                self._send_system_chat("请先放入可进行神话锻造的普通角色装备。")
                return
            if action == ItemChangeAction.WASH_MYTH_ATTRIBUTES:
                quality = self._safe_int(fields[2], 0) if len(fields) > 2 else 0
                self._forge_myth_attribute(item, quality)
            elif action == ItemChangeAction.SELECT_MYTH_ATTRIBUTES:
                self._send_myth_attribute_result(item, ForgeResult.SUCCESS)
            elif action == ItemChangeAction.RESET_MYTH_WUXING:
                self._reset_myth_wuxing(item)
            else:
                self._reset_myth_forge(item)
            return
        if action in (ItemChangeAction.INLAY, ItemChangeAction.INLAY_JADE) and len(fields) > 2:
            self._inlay_equipment_stone(slot, self._safe_int(fields[2], 0))
            return
        if action in (
            ItemChangeAction.REMOVE_INLAY,
            ItemChangeAction.REMOVE_JADE,
        ) and len(fields) > 2:
            self._remove_equipment_stone(slot, self._safe_int(fields[2], -1))
            return
        if action == ItemChangeAction.STRENGTH_KUNCHONG:
            self._strengthen_kun_chong(slot)
            return
        handlers: dict[ItemChangeAction, Callable[[InventoryItem, EquipmentDefinition, list[str]], None]] = {
            ItemChangeAction.STRENGTH: self._forge_strength_level,
            ItemChangeAction.STAGE_UP: self._forge_stage_up,
            ItemChangeAction.STAGE_UP_120: self._forge_stage_up_120,
            ItemChangeAction.CHANGE_APTITUDE: self._forge_change_aptitude,
            ItemChangeAction.RESET_STRENGTH: self._forge_reset_strength,
            ItemChangeAction.REPAIR: self._forge_repair,
            ItemChangeAction.WASH_BORN_ATTRIBUTE: self._forge_born_attribute,
            ItemChangeAction.CARVE: self._forge_carve,
            ItemChangeAction.WASH_PLUS_ATTRIBUTES: self._forge_wash_plus_attributes,
            ItemChangeAction.SELECT_PLUS_ATTRIBUTES: self._forge_select_plus_attributes,
            ItemChangeAction.FULL_PLUS_ATTRIBUTE: self._forge_full_plus_attribute,
            ItemChangeAction.FORGE_STRENGTH: self._forge_level_eleven,
            ItemChangeAction.FORGE_ADDITIVE: self._forge_additive,
            ItemChangeAction.CHANGE_TO_ORANGE: self._forge_change_to_orange,
            ItemChangeAction.CHANGE_TALE_ATTRIBUTE: self._forge_change_tale_attribute,
        }
        handler = handlers.get(action)
        if handler is None:
            return
        item = self.store.state.inventory.get(slot)
        definition = (
            GAME_DATA_CATALOG.get_equipment_definition(item.item_id)
            or GAME_DATA_CATALOG.get_pet_equipment_definition(item.item_id)
            if item is not None
            else None
        )
        if item is None or definition is None:
            self._send_system_chat("请先放入可打造的装备。")
            return
        if not self._supports_standard_equipment_forge(definition):
            self._send_system_chat("该装备只支持自身专属玩法，不能使用普通装备打造。")
            return
        handler(item, definition, fields)

    def _send_myth_attribute_result(
        self,
        item: InventoryItem,
        result: ForgeResult,
    ) -> None:
        attributes = "@".join(
            f"{values[0]}&{values[1]}"
            for values in item.myth_attributes
            if len(values) >= 2
        ) or "-"
        self.send_text(
            f"{op(ServerOpcode.WASH_MYTH_ATTRIBUTE_RESULT)}:{item.slot}:"
            f"{op(result)}:{attributes}:{item.myth_forge_count}:"
            f"{item.myth_forge_type}:{item.myth_skill_id}:"
            f"{item.myth_skill_level}:{item.myth_wuxing}:"
            f"{item.myth_wuxing_level}"
        )

    def _forge_myth_attribute(self, item: InventoryItem, quality: int) -> None:
        """Settle the five-step myth forge contract exposed by the Nya client."""
        material_ids = {1: 16_000_185, 2: 16_000_186, 3: 16_000_187}
        value_ranges = {1: (2, 5), 2: (5, 10), 3: (10, 18)}
        material_id = material_ids.get(quality, 0)
        if material_id <= 0:
            self._send_system_chat("请先选择普通、精良或完美锻造品质。")
            return
        if item.myth_forge_count >= 5:
            self._send_system_chat("该装备的五条神话属性已经锻造完成。")
            self._send_myth_attribute_result(item, ForgeResult.FAILURE)
            return
        if self._inventory_item_quantity(material_id) < 1:
            self._send_system_chat("神话属性锻造石不足。")
            return
        gold_cost = 5_000_000
        if self.store.state.money < gold_cost:
            self._send_system_chat("金币不足，需要5000000金币。")
            return
        success_rates = (100, 80, 60, 40, 20)
        success_rate = success_rates[item.myth_forge_count]
        with self.store.lock:
            changes = self._consume_inventory_quantity(material_id, 1)
            self.store.state.money -= gold_cost
            succeeded = self.random.randrange(100) < success_rate
            if succeeded:
                used_types = {
                    values[0]
                    for values in item.myth_attributes
                    if len(values) >= 2
                }
                candidates = [
                    int(attribute_type)
                    for attribute_type in (
                        EquipmentAttribute.MAX_HP,
                        EquipmentAttribute.MAX_MP,
                        EquipmentAttribute.ATTACK,
                        EquipmentAttribute.DEFENCE,
                        EquipmentAttribute.CRITICAL,
                        EquipmentAttribute.EVASION,
                    )
                    if int(attribute_type) not in used_types
                ]
                attribute_type = self.random.choice(candidates or [int(EquipmentAttribute.ATTACK)])
                value_min, value_max = value_ranges[quality]
                item.myth_attributes.append(
                    [attribute_type, self.random.randint(value_min, value_max)]
                )
                item.myth_forge_count += 1
                item.myth_forge_type = (item.myth_forge_type * 10 + quality) % 100_000
                if item.myth_wuxing <= 0:
                    item.myth_wuxing = self.random.randint(1, 5)
                item.myth_wuxing_level = max(item.myth_wuxing_level, quality)
                if item.myth_forge_count >= 3 and item.myth_skill_id <= 0:
                    item.myth_skill_id = self.random.choice(
                        (101, 102, 103, 104, 105, 201, 202, 203, 301, 302)
                    )
                if item.myth_skill_id > 0:
                    item.myth_skill_level = max(item.myth_skill_level, quality)
            self._finish_forge(item, changes, succeeded)
        result = ForgeResult.SUCCESS if succeeded else ForgeResult.FAILURE
        self._send_myth_attribute_result(item, result)
        if succeeded:
            self._send_all_stats()
        else:
            self._send_system_chat("神话属性锻造失败，本次锻造次数不增加。")

    def _reset_myth_wuxing(self, item: InventoryItem) -> None:
        material_id = 16_000_189
        if item.myth_forge_count <= 0 or item.myth_wuxing <= 0:
            self._send_system_chat("该装备还没有可重置的神话五行。")
            return
        if self._inventory_item_quantity(material_id) < 1 or self.store.state.money < 5_000_000:
            self._send_system_chat("神话五行重置石或金币不足。")
            return
        candidates = [value for value in range(1, 6) if value != item.myth_wuxing]
        with self.store.lock:
            changes = self._consume_inventory_quantity(material_id, 1)
            self.store.state.money -= 5_000_000
            item.myth_wuxing = self.random.choice(candidates)
            self._finish_forge(item, changes, True)
        self._send_myth_attribute_result(item, ForgeResult.SUCCESS)
        self._send_all_stats()

    def _reset_myth_forge(self, item: InventoryItem) -> None:
        material_id = 16_000_188
        if item.myth_forge_count <= 0:
            self._send_system_chat("该装备还没有可重置的神话锻造成果。")
            return
        if self._inventory_item_quantity(material_id) < 1 or self.store.state.money < 5_000_000:
            self._send_system_chat("神话锻造重置石或金币不足。")
            return
        with self.store.lock:
            changes = self._consume_inventory_quantity(material_id, 1)
            self.store.state.money -= 5_000_000
            item.myth_attributes = []
            item.myth_forge_count = 0
            item.myth_forge_type = 0
            item.myth_skill_id = 0
            item.myth_skill_level = 0
            item.myth_wuxing = 0
            item.myth_wuxing_level = 0
            self._finish_forge(item, changes, True)
        self._send_myth_attribute_result(item, ForgeResult.SUCCESS)
        self._send_all_stats()

    def _swap_transform_card_attributes(
        self,
        first_slot: int,
        second_slot: int,
        *,
        special: bool,
    ) -> None:
        """Atomically exchange the two permanent bag cards' instance attributes."""
        first = self.store.state.inventory.get(first_slot)
        second = self.store.state.inventory.get(second_slot)
        permanent_ids = set(GAME_DATA_CATALOG.permanent_transform_card_ids)
        material_id = 16_000_555
        valid = (
            first is not None
            and second is not None
            and first_slot > 0
            and second_slot > 0
            and first_slot != second_slot
            and first.item_id in permanent_ids
            and second.item_id in permanent_ids
            and (special or (first.reforge_time <= 0 and second.reforge_time <= 0))
        )
        if not valid:
            self._send_system_chat("请放入两张符合条件的永久变身卡。")
            return
        if self._inventory_item_quantity(material_id) < 1:
            self._send_system_chat("需要一个研究所凭证才能交换属性。")
            return
        with self.store.lock:
            changes = self._consume_inventory_quantity(material_id, 1)
            if special:
                first.special_attributes, second.special_attributes = (
                    second.special_attributes,
                    first.special_attributes,
                )
                first.special_level, second.special_level = (
                    second.special_level,
                    first.special_level,
                )
                first.special_effect_type, second.special_effect_type = (
                    second.special_effect_type,
                    first.special_effect_type,
                )
            else:
                first.plus_attributes, second.plus_attributes = (
                    second.plus_attributes,
                    first.plus_attributes,
                )
                first.born_attr_value, second.born_attr_value = (
                    second.born_attr_value,
                    first.born_attr_value,
                )
                first.tale_attr_type, second.tale_attr_type = (
                    second.tale_attr_type,
                    first.tale_attr_type,
                )
                first.tale_attr_value, second.tale_attr_value = (
                    second.tale_attr_value,
                    first.tale_attr_value,
                )
                swap_time = int(time.time())
                first.reforge_time = swap_time
                second.reforge_time = swap_time
            self.store.save()
        for changed, removed in changes:
            if removed:
                self._send_inventory_clear(changed.slot, InventoryType.BAG)
            else:
                self._send_inventory_update(changed, from_drop=0)
        self._send_inventory_update(first, from_drop=0)
        self._send_inventory_update(second, from_drop=0)
        self._send_all_stats()
        self._send_system_chat("变身卡属性交换成功。")

    def _convert_equipment_job(self, slot: int) -> None:
        """Convert one bag equipment template while preserving every instance property."""
        material_id = 16_000_183
        item = self.store.state.inventory.get(slot)
        source_definition = (
            GAME_DATA_CATALOG.get_equipment_definition(item.item_id)
            if item is not None and item.slot > 0
            else None
        )
        job_group = self.character.job // 100
        source_job_group = item.item_id % 10 if item is not None else 0
        target_item_id = (
            item.item_id // 10 * 10 + job_group
            if item is not None and 1 <= job_group <= 4
            else 0
        )
        target_definition = GAME_DATA_CATALOG.get_equipment_definition(target_item_id)

        if (
            item is None
            or source_definition is None
            or item.slot <= 0
            or source_job_group == 0
            or source_job_group == job_group
            or target_definition is None
            or target_definition.required_job not in (0, self.character.job)
        ):
            self._send_system_chat("该装备无法转换为当前职业对应装备。")
            return

        normalized_aptitude = 6 if item.aptitude > 5 else item.aptitude
        is_myth = (
            normalized_aptitude >= 6
            or item.myth_forge_count > 0
            or item.myth_skill_id > 0
            or item.myth_wuxing > 0
        )
        material_count = 10 if is_myth else max(1, normalized_aptitude)
        if self._inventory_item_quantity(material_id) < material_count:
            self._send_system_chat("职业装备转换材料不足。")
            return

        with self.store.lock:
            inventory_changes = self._consume_inventory_quantity(
                material_id, material_count
            )
            item.item_id = target_item_id
            self.store.save()
        for changed_item, removed in inventory_changes:
            if removed:
                self._send_inventory_clear(changed_item.slot, InventoryType.BAG)
            else:
                self._send_inventory_update(changed_item, from_drop=0)
        # A template-id change cannot use the quantity-only UPDATE packet. Flash
        # otherwise retains the old ItemData object until the bag is reopened.
        self._refresh_inventory_item(item)
        self._send_system_chat("职业装备转换成功。")

    def _merge_badge_stone(self, slot: int) -> None:
        """Batch three authored badge stones into each next-level stone atomically."""
        item = self.store.state.inventory.get(slot)
        progression = (
            GAME_DATA_CATALOG.get_stone_progression(item.item_id)
            if item is not None and item.slot > 0 and item.item_id // 100_000 == 132
            else None
        )
        if item is None or progression is None:
            self._send_system_chat("请放入徽章石。")
            return
        level, next_item_id, _ = progression
        attempts = item.quantity // 3
        if attempts <= 0:
            self._send_system_chat("每次合成至少需要三个同级徽章石。")
            return
        if next_item_id <= 0 or GAME_DATA_CATALOG.get_item_definition(next_item_id) is None:
            self._send_system_chat("该徽章石已达到最高等级。")
            return
        consumed_count = attempts * 3
        source_will_remain = item.quantity > consumed_count
        if source_will_remain and not self._has_inventory_capacity([(next_item_id, attempts)]):
            self._send_system_chat("背包已满，无法合成徽章石。")
            return
        with self.store.lock:
            item.quantity -= consumed_count
            removed = item.quantity <= 0
            if removed:
                self.store.state.inventory.pop(slot, None)
            result, created = self._add_inventory_item(
                next_item_id,
                attempts,
                can_trade=item.can_trade,
            )
            self.store.save()
        if removed:
            self._send_inventory_clear(slot, InventoryType.BAG)
        else:
            self._send_inventory_update(item, from_drop=0)
        if created:
            self._send_inventory_add(result, from_drop=0)
        else:
            self._send_inventory_update(result, from_drop=0)
        self.send_text(
            f"{op(ServerOpcode.HUI_ZHANG_STONE_MERGE_RES)}:{attempts}:"
            f"{next_item_id}:{max(0, item.quantity)}:{item.item_id}"
        )

    def _stage_up_badge(self, slot: int) -> None:
        """Consume the exact EquipSystem material and replace one badge in place."""
        item = self.store.state.inventory.get(slot)
        definition = GAME_DATA_CATALOG.get_equipment_definition(item.item_id) if item else None
        if item is None or definition is None or definition.position != EquipmentPosition.BADGE:
            self._send_system_chat("请放入可进阶的徽章。")
            return
        next_definition = GAME_DATA_CATALOG.get_equipment_definition(definition.next_item_id)
        stage_config = GAME_DATA_CATALOG.get_equipment_system_config(
            "huiZhangStageUp"
        ).get(str(item.item_id))
        if next_definition is None or not isinstance(stage_config, dict):
            self._send_system_chat("该徽章已达到最高阶。")
            return
        material_id = self._safe_int(stage_config.get("needItemId"), 0)
        material_count = max(1, self._safe_int(stage_config.get("needItemCnt"), 1))
        if self._inventory_item_quantity(material_id) < material_count:
            self._send_system_chat("徽章进阶石不足。")
            return
        old_item_id = item.item_id
        with self.store.lock:
            changes = self._consume_inventory_quantity(material_id, material_count)
            item.item_id = next_definition.item_id
            item.base_attr_type = next_definition.base_attr_type
            item.base_attr_value = next_definition.base_attr_value
            item.max_endure = next_definition.max_endure
            item.endure = next_definition.max_endure
            item.plus_attributes = [
                [int(attribute_type), int(value)]
                for attribute_type, value in next_definition.additional_attributes
            ]
            self.store.save()
        for changed, removed in changes:
            if removed:
                self._send_inventory_clear(changed.slot, InventoryType.BAG)
            else:
                self._send_inventory_update(changed, from_drop=0)
        inventory_type = InventoryType.EQUIPPED if slot < 0 else InventoryType.BAG
        self._send_inventory_clear(slot, inventory_type)
        self._send_inventory_add(item, from_drop=0)
        self._send_all_stats()
        old_name = self._item_display_name(old_item_id, "原徽章")
        new_name = self._item_display_name(item.item_id, "新徽章")
        self._send_system_chat(f"徽章进阶成功：{old_name}提升为{new_name}。")

    def _merge_jade(self, slot: int) -> None:
        """Batch merge Gouyu: two same-level stones become one next-level stone."""
        item = self.store.state.inventory.get(slot)
        progression = (
            GAME_DATA_CATALOG.get_stone_progression(item.item_id)
            if item is not None and item.slot > 0 and item.item_id // 100_000 == 131
            else None
        )
        if item is None or progression is None or not progression[2]:
            self._send_system_chat("请放入可合成的勾玉。")
            return
        level, next_item_id, _ = progression
        next_progression = GAME_DATA_CATALOG.get_stone_progression(next_item_id)
        if next_item_id <= 0 or next_progression is None:
            self._send_system_chat("勾玉已到最高等级，无法继续合成。")
            return
        source_count = 2
        if item.quantity < source_count:
            self._send_system_chat("合成需要两个同等级勾玉。")
            return
        config = GAME_DATA_CATALOG.get_equipment_system_config("jade").get("merge")
        row = config.get(f"level{next_progression[0]}") if isinstance(config, dict) else None
        if not isinstance(row, dict):
            self._send_system_chat("未找到该等级的勾玉合成配置。")
            return
        material_id = self._safe_int(row.get("needItemId"), 0)
        material_count = max(1, self._safe_int(row.get("needItemCnt"), 1))
        attempts = item.quantity // source_count
        required_material = material_count * attempts
        if (
            material_id > 0
            and self._inventory_item_quantity(material_id) < required_material
        ):
            self._send_system_chat("勾玉合成符不足。")
            return
        success_count = 0
        for _ in range(attempts):
            if self._roll_forge(self._safe_int(row.get("prob"), 0)):
                success_count += 1
        remaining_source = item.quantity - attempts * source_count
        if (
            success_count > 0
            and remaining_source > 0
            and not self._has_inventory_capacity([(next_item_id, success_count)])
        ):
            self._send_system_chat("背包已满，无法合成勾玉。")
            return
        with self.store.lock:
            item.quantity -= attempts * source_count
            removed = item.quantity <= 0
            if removed:
                self.store.state.inventory.pop(slot, None)
            changes = (
                self._consume_inventory_quantity(material_id, required_material)
                if material_id > 0
                else []
            )
            result_item = None
            result_created = False
            if success_count > 0:
                result_item, result_created = self._add_inventory_item(
                    next_item_id,
                    success_count,
                    can_trade=item.can_trade,
                )
            self.store.save()
        if removed:
            self._send_inventory_clear(slot, InventoryType.BAG)
        else:
            self._send_inventory_update(item, from_drop=0)
        for changed, changed_removed in changes:
            if changed_removed:
                self._send_inventory_clear(changed.slot, InventoryType.BAG)
            else:
                self._send_inventory_update(changed, from_drop=0)
        if result_item is not None:
            if result_created:
                self._send_inventory_add(result_item, from_drop=0)
            else:
                self._send_inventory_update(result_item, from_drop=0)
        self.send_text(
            f"{op(ServerOpcode.STONE_MERGE_RESPONSE)}:{success_count}:"
            f"{next_item_id if success_count else 0}:{next_progression[0] if success_count else 0}:"
            f"{attempts - success_count}:{item.item_id}:{level}:"
            f"{max(0, item.quantity)}:{item.item_id}:{level}"
        )

    def _change_jade_attribute(self, slot: int) -> None:
        """Convert one Gouyu to a different authored attribute family at the same level."""
        item = self.store.state.inventory.get(slot)
        progression = (
            GAME_DATA_CATALOG.get_stone_progression(item.item_id)
            if item is not None and item.slot > 0 and item.item_id // 100_000 == 131
            else None
        )
        if item is None or progression is None or not progression[2]:
            self._send_system_chat("请放入勾玉。")
            return
        level, _, attribute_name = progression
        config = GAME_DATA_CATALOG.get_equipment_system_config("jade").get("change")
        row = config.get(f"level{level}") if isinstance(config, dict) else None
        candidates = [
            item_id
            for item_id in GAME_DATA_CATALOG.jade_items_at_level(level)
            if (candidate := GAME_DATA_CATALOG.get_stone_progression(item_id)) is not None
            and candidate[2] != attribute_name
        ]
        if not isinstance(row, dict) or not candidates:
            self._send_system_chat("该勾玉暂时无法转换属性。")
            return
        money_cost = max(0, self._safe_int(row.get("needMoney"), 0))
        if self.store.state.money < money_cost:
            self._send_system_chat("金币不足。")
            return
        target_item_id = self.random.choice(candidates)
        if item.quantity > 1 and not self._has_inventory_capacity([(target_item_id, 1)]):
            self._send_system_chat("背包已满，无法转换勾玉。")
            return
        old_item_id = item.item_id
        with self.store.lock:
            self.store.state.money -= money_cost
            succeeded = self._roll_forge(self._safe_int(row.get("prob"), 0))
            created_result = None
            if succeeded and item.quantity == 1:
                item.item_id = target_item_id
            elif succeeded:
                item.quantity -= 1
                created_result = self._add_inventory_item(
                    target_item_id,
                    1,
                    can_trade=item.can_trade,
                )
            self.store.save()
        self._send_stats({StatType.MONEY: self.store.state.money})
        if succeeded and item.quantity == 1 and item.item_id == target_item_id:
            self._send_inventory_clear(slot, InventoryType.BAG)
            self._send_inventory_add(item, from_drop=0)
        elif succeeded:
            self._send_inventory_update(item, from_drop=0)
            if created_result is not None:
                changed, created = created_result
                if created:
                    self._send_inventory_add(changed, from_drop=0)
                else:
                    self._send_inventory_update(changed, from_drop=0)
        self.send_text(
            f"{op(ServerOpcode.STONE_MERGE_RESPONSE)}:{1 if succeeded else 0}:"
            f"{target_item_id if succeeded else 0}:{level}:{0 if succeeded else 1}:"
            f"{old_item_id}:{level}:0:{old_item_id}:{level}"
        )

    def _special_stage_up(self, slot: int) -> None:
        """Advance one jade chain through EquipSystem.special.stageup."""
        item = self.store.state.inventory.get(slot)
        definition = (
            GAME_DATA_CATALOG.get_equipment_definition(item.item_id)
            if item is not None
            else None
        )
        if (
            item is None
            or definition is None
            or definition.type_name != "EquipS1"
            or item.item_id // 10_000 != 120
        ):
            self._send_system_chat("请放入玉链。")
            return
        next_stage = definition.stage + 1
        equip_system = GAME_DATA_CATALOG.get_cultivation_config("EquipSystem")
        special = equip_system.get("special") if isinstance(equip_system, dict) else {}
        stageup = special.get("stageup") if isinstance(special, dict) else {}
        config = stageup.get(f"stage{next_stage}") if isinstance(stageup, dict) else None
        next_definition = GAME_DATA_CATALOG.get_equipment_definition(
            definition.next_item_id
        )
        if not isinstance(config, dict) or next_definition is None:
            self._send_system_chat("该玉链已达到最高阶。")
            return
        money_cost = max(0, self._safe_int(config.get("needMoney"), 0))
        if self.store.state.money < money_cost:
            self._send_system_chat("金币不足。")
            return
        with self.store.lock:
            self.store.state.money -= money_cost
            succeeded = self._roll_forge(self._safe_int(config.get("prob"), 0))
            if succeeded:
                item.item_id = next_definition.item_id
                item.base_attr_type = next_definition.base_attr_type
                item.base_attr_value = next_definition.base_attr_value
                item.max_endure = next_definition.max_endure
                item.endure = next_definition.max_endure
                item.plus_attributes = [
                    [int(attribute_type), int(value)]
                    for attribute_type, value in next_definition.additional_attributes
                ]
            self.store.save()
        self._send_stats({StatType.MONEY: self.store.state.money})
        inventory_type = InventoryType.EQUIPPED if slot < 0 else InventoryType.BAG
        self._send_inventory_clear(slot, inventory_type)
        self._send_inventory_add(item, from_drop=0)
        self._send_all_stats()
        self._send_system_chat(
            "玉链进阶成功。" if succeeded else "玉链进阶失败，原玉链保留。"
        )

    def _merge_equipment_stone(self, slot: int) -> None:
        """Consume three same-level gems and create GameData's exact `next` gem."""
        item = self.store.state.inventory.get(slot)
        if item is None or item.slot <= 0:
            return
        raw_stone = GAME_DATA_CATALOG.raw_item_sections.get("BaoShi", {}).get(
            f"{item.item_id:08d}"
        )
        decoded = (
            GAME_DATA_CATALOG._decode_section(raw_stone)
            if raw_stone is not None
            else {}
        )
        inlay = decoded.get("inlay") if isinstance(decoded, dict) else None
        current_level = (
            max(1, self._safe_int(inlay.get("stoneLevel"), 1))
            if isinstance(inlay, dict)
            else 0
        )
        next_item_id = (
            self._safe_int(inlay.get("next"), 0)
            if isinstance(inlay, dict)
            else 0
        )
        next_stone = GAME_DATA_CATALOG.get_stone_inlay(next_item_id)
        if current_level <= 0 or next_item_id <= 0 or next_stone is None:
            self._send_system_chat("该宝石已达到最高等级。")
            return
        if item.quantity < 3:
            self._send_system_chat("合成需要三个同等级宝石。")
            return
        if item.quantity > 3 and not self._has_inventory_capacity(
            [(next_item_id, 1)]
        ):
            self._send_system_chat("背包已满，无法合成宝石。")
            return
        with self.store.lock:
            item.quantity -= 3
            removed = item.quantity <= 0
            if removed:
                self.store.state.inventory.pop(slot, None)
            result, created = self._add_inventory_item(
                next_item_id,
                1,
                can_trade=item.can_trade,
            )
            self.store.save()
        if removed:
            self._send_inventory_clear(slot, InventoryType.BAG)
        else:
            self._send_inventory_update(item, from_drop=0)
        if created:
            self._send_inventory_add(result, from_drop=0)
        else:
            self._send_inventory_update(result, from_drop=0)
        self.send_text(
            f"{op(ServerOpcode.STONE_MERGE_RESPONSE)}:1:{next_item_id}:"
            f"{next_stone[0]}:0:{item.item_id}:{current_level}:"
            f"{max(0, item.quantity)}:{item.item_id}:{current_level}"
        )

    def _strengthen_kun_chong(self, slot: int) -> None:
        """Consume original insect-strength gold and apply its live attribute ratio."""
        item = self.store.state.inventory.get(slot)
        if item is None or item.item_id // 10_000 != 131:
            self._send_system_chat("''' + os.environ['M6'] + '''")
            return
        next_level = item.strength_level + 1
        strength_root = GAME_DATA_CATALOG.get_equipment_system_config("KunChong").get(
            "strength"
        )
        config = strength_root.get(str(next_level)) if isinstance(strength_root, dict) else None
        if not isinstance(config, dict):
            self._send_system_chat("昆虫已达到强化上限。")
            return
        money_cost = max(0, self._safe_int(config.get("needMoney"), 0))
        if self.store.state.money < money_cost:
            self._send_system_chat("金币不足。")
            return
        destroyed = False
        item_changed = False
        with self.store.lock:
            self.store.state.money -= money_cost
            succeeded = self._roll_forge(self._safe_int(config.get("ratio"), 0))
            if succeeded:
                self._apply_kun_chong_profile(item, item.aptitude, next_level)
                item_changed = True
            else:
                fail_result = self._safe_int(config.get("failResult"), 0)
                if fail_result == 1:
                    self._apply_kun_chong_profile(
                        item, item.aptitude, max(0, item.strength_level - 1)
                    )
                    item_changed = True
                elif fail_result == 2:
                    self._apply_kun_chong_profile(item, item.aptitude, 0)
                    item_changed = True
                elif fail_result == 3:
                    del self.store.state.inventory[slot]
                    destroyed = True
            self.store.save()
        insect_inventory_type = InventoryType.EQUIPPED if slot < 0 else InventoryType.BAG
        if destroyed:
            self._send_inventory_clear(slot, insect_inventory_type)
        elif item_changed:
            self._send_inventory_update(item, from_drop=0)
        result = ForgeResult.SUCCESS if succeeded else ForgeResult.FAILURE
        self.send_text(
            f"{op(ServerOpcode.KUNCHONG_STRENGTH_RESULT)}:{slot}:{op(result)}"
        )
        self._send_stats(
            {StatType.MONEY: self.store.state.money, **self._client_base_combat_stats()}
        )
        self._send_equipped_kun_chong()

    def _inlay_equipment_stone(self, equipment_slot: int, stone_slot: int) -> None:
        """Consume one compatible original BaoShi and append its five-field inlay row."""
        equipment = self.store.state.inventory.get(equipment_slot)
        definition = (
            GAME_DATA_CATALOG.get_equipment_definition(equipment.item_id)
            or GAME_DATA_CATALOG.get_pet_equipment_definition(equipment.item_id)
            if equipment
            else None
        )
        stone = self.store.state.inventory.get(stone_slot)
        stone_config = GAME_DATA_CATALOG.get_stone_inlay(stone.item_id) if stone else None
        if equipment is None or definition is None or stone is None or stone_config is None:
            return
        if (
            equipment.item_id // 10_000 == 120
            and definition.type_name == "EquipS1"
        ):
            maximum_slots = max(1, definition.stage)
        else:
            maximum_slots = 6 if equipment.aptitude >= 5 else 5
        if len(equipment.inlays) >= maximum_slots:
            self._send_system_chat("宝石孔已满。")
            return
        stone_level, attribute_type, skill_id, attribute_value = stone_config
        inlay_config = GAME_DATA_CATALOG.get_equipment_system_config("inlay")
        allowed_names = str(inlay_config.get(definition.type_name) or "").split(";")
        attribute_names = {
            int(value): name for name, value in EQUIPMENT_ATTRIBUTE_BY_NAME.items()
        }
        if skill_id <= 0 and attribute_names.get(attribute_type, "") not in allowed_names:
            self._send_system_chat("这类宝石不能镶嵌在该装备上。")
            return
        with self.store.lock:
            consumed, removed = self._consume_bag_slot(stone_slot, stone.item_id)
            if consumed is None:
                return
            if not consumed.can_trade:
                self._bind_item_instance(equipment)
            equipment.inlays.append(
                [stone.item_id, stone_level, attribute_type, skill_id, attribute_value]
            )
            self.store.save()
        if removed:
            self._send_inventory_clear(stone_slot, InventoryType.BAG)
        else:
            self._send_inventory_update(consumed, from_drop=0)
        self._send_equipment_inlays(equipment)
        equipment_section = self._inventory_item_section(equipment)
        self._send_inventory_clear(
            equipment.slot,
            self._inventory_type_for_position(equipment_section, equipment.slot),
        )
        self._send_inventory_add(equipment, from_drop=0)
        if equipment.slot < 0:
            self._send_all_stats()
            self._refresh_skill_gem_levels({skill_id})

    def _remove_equipment_stone(self, equipment_slot: int, inlay_index: int) -> None:
        """Remove one indexed gem, return its template to the bag, and refresh the panel."""
        equipment = self.store.state.inventory.get(equipment_slot)
        if equipment is None or not (0 <= inlay_index < len(equipment.inlays)):
            return
        removed_skill_id = equipment.inlays[inlay_index][3] if len(
            equipment.inlays[inlay_index]
        ) >= 4 else 0
        stone_id = equipment.inlays[inlay_index][0]
        if not self._has_inventory_capacity([(stone_id, 1)]):
            self._send_system_chat("背包已满，无法拆下宝石。")
            return
        with self.store.lock:
            del equipment.inlays[inlay_index]
            returned, created = self._add_inventory_item(
                stone_id,
                1,
                can_trade=equipment.can_trade,
            )
            self.store.save()
        if created:
            self._send_inventory_add(returned, from_drop=0)
        else:
            self._send_inventory_update(returned, from_drop=0)
        self._send_equipment_inlays(equipment)
        equipment_section = self._inventory_item_section(equipment)
        self._send_inventory_clear(
            equipment.slot,
            self._inventory_type_for_position(equipment_section, equipment.slot),
        )
        self._send_inventory_add(equipment, from_drop=0)
        self._clamp_resources_after_equipment_change()
        if equipment.slot < 0:
            self._send_all_stats()
            if removed_skill_id > 0:
                self._refresh_skill_gem_levels({removed_skill_id})

    def _send_equipment_inlays(self, equipment: InventoryItem) -> None:
        """Send EQUIP_INLAY_INFO in the exact five ampersand-field row format."""
        encoded = "@".join(
            "&".join(str(value) for value in entry[:5]) for entry in equipment.inlays
        ) or "-"
        self.send_text(
            f"{op(ServerOpcode.EQUIPMENT_INLAY_INFO)}:{equipment.slot}:{encoded}"
        )

    def _consume_forge_cost(
        self,
        config: dict[str, Any],
        requested_help_count: int = 0,
    ) -> tuple[list[tuple[InventoryItem, bool]], int] | None:
        """Validate and consume one original forge row's material, lucky-item, and gold costs."""
        material_id = self._safe_int(config.get("needItemId"), 0)
        material_count = max(0, self._safe_int(config.get("needItemCnt"), 0))
        money_cost = max(0, self._safe_int(config.get("needMoney"), 0))
        help_item_id = self._safe_int(config.get("helpItemId"), 0)
        max_help_count = max(0, self._safe_int(config.get("maxHelpCnt"), requested_help_count))
        help_count = min(max(0, requested_help_count), max_help_count)
        if material_count > 0 and self._inventory_item_quantity(material_id) < material_count:
            material_name = self._item_display_name(material_id, "所需打造材料")
            self._send_system_chat(f"请先在木叶商店购买{material_name}。")
            return None
        if help_count > 0 and self._inventory_item_quantity(help_item_id) < help_count:
            help_item_name = self._item_display_name(help_item_id, "幸运精华")
            self._send_system_chat(f"{help_item_name}数量不足。")
            return None
        if self.store.state.money < money_cost:
            self._send_system_chat("金币不足。")
            return None
        changes = self._consume_inventory_quantity(material_id, material_count)
        if help_count > 0:
            changes.extend(self._consume_inventory_quantity(help_item_id, help_count))
        self.store.state.money -= money_cost
        return changes, help_count

    def _roll_forge(self, probability: int, help_count: int = 0) -> bool:
        """Roll the original percent chance with each lucky essence adding three percent."""
        chance = min(100, max(0, probability + help_count * 3))
        return self.random.randrange(100) < chance

    def _finish_forge(
        self,
        item: InventoryItem,
        inventory_changes: list[tuple[InventoryItem, bool]],
        item_changed: bool,
    ) -> None:
        """Persist one forge transaction and refresh materials, equipment, gold, and live stats."""
        self.store.save()
        for changed_item, removed in inventory_changes:
            if removed:
                self._send_inventory_clear(changed_item.slot, InventoryType.BAG)
            else:
                self._send_inventory_update(changed_item, from_drop=0)
        if item_changed:
            inventory_type = InventoryType.BAG if item.slot > 0 else InventoryType.EQUIPPED
            self._send_inventory_clear(item.slot, inventory_type)
            self._send_inventory_add(item, from_drop=0)
        self._send_stats({StatType.MONEY: self.store.state.money})
        if item_changed and item.slot < 0:
            self._clamp_resources_after_equipment_change()

    def _forge_strength_level(
        self,
        item: InventoryItem,
        definition: EquipmentDefinition,
        fields: list[str],
    ) -> None:
        """Raise equipment strength from level 0 through 10 using EquipSystem.strength."""
        next_level = item.strength_level + 1
        config = GAME_DATA_CATALOG.get_equipment_system_config("strength").get(f"level{next_level}")
        if not isinstance(config, dict) or next_level > 10:
            self._send_system_chat("已达普通强化上限，请使用百炼升到 11 级。")
            return
        help_count = max(0, self._safe_int(fields[2], 0)) if len(fields) > 2 else 0
        with self.store.lock:
            paid = self._consume_forge_cost(config, help_count)
            if paid is None:
                return
            changes, effective_help = paid
            succeeded = self._roll_forge(self._safe_int(config.get("prob"), 0), effective_help)
            if succeeded:
                item.strength_level = next_level
                item.strength_value = round(item.base_attr_value * self._safe_int(config.get("addRatio"), 0) / 100)
                item.strength_info = [True] * next_level
            self._finish_forge(item, changes, succeeded)
        if not succeeded:
            self._send_system_chat("装备强化失败，强化等级保留。")

    def _forge_stage_up(
        self,
        item: InventoryItem,
        definition: EquipmentDefinition,
        fields: list[str],
    ) -> None:
        """Advance an equipment template to its original next item and stage configuration."""
        next_stage = definition.stage + 1
        config = GAME_DATA_CATALOG.get_equipment_system_config("stageup").get(f"stage{next_stage}")
        next_definition = (
            GAME_DATA_CATALOG.get_equipment_definition(definition.next_item_id)
            or GAME_DATA_CATALOG.get_pet_equipment_definition(definition.next_item_id)
        )
        if not isinstance(config, dict) or next_definition is None:
            self._send_system_chat("这件装备已无法继续进阶。")
            return
        help_count = max(0, self._safe_int(fields[2], 0)) if len(fields) > 2 else 0
        with self.store.lock:
            paid = self._consume_forge_cost(config, help_count)
            if paid is None:
                return
            changes, effective_help = paid
            succeeded = self._roll_forge(self._safe_int(config.get("prob"), 0), effective_help)
            if succeeded:
                item.item_id = next_definition.item_id
                item.base_attr_type = next_definition.base_attr_type
                item.base_attr_value = next_definition.base_attr_value
                item.max_endure = next_definition.max_endure
                item.endure = next_definition.max_endure
                strength_config = GAME_DATA_CATALOG.get_equipment_system_config("strength").get(
                    f"level{item.strength_level}"
                )
                ratio = self._safe_int(strength_config.get("addRatio"), 0) if isinstance(strength_config, dict) else 0
                item.strength_value = round(item.base_attr_value * ratio / 100)
            self._finish_forge(item, changes, succeeded)
        if not succeeded:
            self._send_system_chat("装备进阶失败，原装备保留。")

    def _forge_stage_up_120(
        self,
        item: InventoryItem,
        definition: EquipmentDefinition,
        fields: list[str],
    ) -> None:
        """Use 升阶灵石/升阶神石 to advance a 6-stage equip to stage 7."""
        if definition.stage != 6 or definition.next_item_id <= 0:
            self._send_system_chat("该装备不能使用快速升阶。")
            return
        next_definition = GAME_DATA_CATALOG.get_equipment_definition(
            definition.next_item_id
        )
        if next_definition is None:
            self._send_system_chat("该装备无法继续升阶。")
            return
        config = GAME_DATA_CATALOG.get_equipment_system_config("stageup120").get("stage")
        if not isinstance(config, dict):
            self._send_system_chat("快速升阶配置缺失。")
            return
        normal = config.get("needItem")
        alternative = config.get("needItemAlternative")
        normal_id = self._safe_int(normal.get("itemId"), 0) if isinstance(normal, dict) else 0
        alternative_id = (
            self._safe_int(alternative.get("itemId"), 0)
            if isinstance(alternative, dict)
            else 0
        )
        normal_percent = (
            self._safe_int(normal.get("upPercent"), 25)
            if isinstance(normal, dict)
            else 25
        )
        alternative_percent = (
            self._safe_int(alternative.get("upPercent"), 25)
            if isinstance(alternative, dict)
            else 25
        )
        threshold = self._safe_int(config.get("thresholdForUseAlternative"), 75)
        material_slot = self._safe_int(fields[2], 0) if len(fields) > 2 else 0
        material = self.store.state.inventory.get(material_slot)
        if (
            material is None
            or material.slot <= 0
            or material.item_id not in {normal_id, alternative_id}
            or material.quantity <= 0
        ):
            self._send_system_chat("升阶材料不足。")
            return
        if item.stageup120_percent >= 100:
            self._send_system_chat("该装备升阶进度已满。")
            return
        if material.item_id == alternative_id and item.stageup120_percent < threshold:
            self._send_system_chat(
                f"升阶进度需达到 {threshold}% 后才能使用升阶神石。"
            )
            return
        percent = (
            alternative_percent
            if material.item_id == alternative_id
            else normal_percent
        )
        changes: list[tuple[InventoryItem, bool]] = []
        promoted = False
        with self.store.lock:
            consumed = self.store.state.inventory.get(material_slot)
            if (
                consumed is None
                or consumed.item_id != material.item_id
                or consumed.quantity <= 0
            ):
                return
            consumed.quantity -= 1
            removed = consumed.quantity == 0
            if removed:
                del self.store.state.inventory[material_slot]
            changes.append((consumed, removed))
            item.stageup120_percent = min(
                100,
                item.stageup120_percent + percent,
            )
            if item.stageup120_percent >= 100:
                item.item_id = next_definition.item_id
                item.base_attr_type = next_definition.base_attr_type
                item.base_attr_value = next_definition.base_attr_value
                item.max_endure = next_definition.max_endure
                item.endure = next_definition.max_endure
                item.stageup120_percent = 0
                strength_config = GAME_DATA_CATALOG.get_equipment_system_config(
                    "strength"
                ).get(f"level{item.strength_level}")
                ratio = (
                    self._safe_int(strength_config.get("addRatio"), 0)
                    if isinstance(strength_config, dict)
                    else 0
                )
                item.strength_value = round(item.base_attr_value * ratio / 100)
                promoted = True
            self.store.save()
        self._finish_forge(item, changes, True)
        self._send_equipment_slot_update(item)
        if promoted:
            old_name = self._item_display_name(definition.item_id, "装备")
            new_name = self._item_display_name(next_definition.item_id, "装备")
            self._send_system_chat(f"快速升阶成功：{old_name}提升为{new_name}。")
        else:
            self._send_system_chat(
                f"使用升阶材料成功，当前升阶进度 {item.stageup120_percent}%。"
            )

    def _forge_change_aptitude(
        self,
        item: InventoryItem,
        definition: EquipmentDefinition,
        fields: list[str],
    ) -> None:
        """Raise white through purple equipment aptitude using original reset-stone costs."""
        root = GAME_DATA_CATALOG.get_equipment_system_config("changeAptitude")
        tier = root.get(f"apt{min(4, max(1, item.aptitude))}")
        if not isinstance(tier, dict) or item.aptitude >= 5:
            self._send_system_chat("装备资质已达橙色上限。")
            return
        config = {**tier, "needItemId": root.get("needItemId"), "helpItemId": root.get("helpItemId"), "maxHelpCnt": root.get("maxHelpCnt")}
        help_count = max(0, self._safe_int(fields[2], 0)) if len(fields) > 2 else 0
        with self.store.lock:
            paid = self._consume_forge_cost(config, help_count)
            if paid is None:
                return
            changes, effective_help = paid
            succeeded = self._roll_forge(self._safe_int(config.get("prob"), 0), effective_help)
            if succeeded:
                item.aptitude = min(5, item.aptitude + 1)
                if not item.plus_attributes:
                    item.plus_attributes = self._generate_plus_attributes(item, definition, item.aptitude)
            self._finish_forge(item, changes, succeeded)
        if not succeeded:
            self._send_system_chat("资质提升失败，原资质保留。")

    def _forge_reset_strength(
        self,
        item: InventoryItem,
        definition: EquipmentDefinition,
        fields: list[str],
    ) -> None:
        """Reset strengthening to zero with the original stage-based reset cost."""
        config = GAME_DATA_CATALOG.get_equipment_system_config("resetStrength").get(
            f"stage{definition.stage}"
        )
        if not isinstance(config, dict):
            return
        help_count = max(0, self._safe_int(fields[2], 0)) if len(fields) > 2 else 0
        with self.store.lock:
            paid = self._consume_forge_cost(config, help_count)
            if paid is None:
                return
            changes, effective_help = paid
            succeeded = self._roll_forge(self._safe_int(config.get("prob"), 0), effective_help)
            if succeeded:
                item.strength_level = 0
                item.strength_value = 0
                item.strength_info = []
            self._finish_forge(item, changes, succeeded)

    def _forge_repair(
        self,
        item: InventoryItem,
        definition: EquipmentDefinition,
        fields: list[str],
    ) -> None:
        """Restore equipment durability using the original per-stage normal repair price."""
        repair_root = GAME_DATA_CATALOG.get_equipment_system_config("naijiu").get("repair")
        config = repair_root.get(f"stage{definition.stage}") if isinstance(repair_root, dict) else None
        if not isinstance(config, dict) or item.max_endure < 0 or item.endure >= item.max_endure:
            return
        missing = item.max_endure - item.endure
        cost = missing * max(1, self._safe_int(config.get("normalPrice"), 1))
        with self.store.lock:
            paid = self._consume_forge_cost({"needMoney": cost})
            if paid is None:
                return
            changes, _ = paid
            item.endure = item.max_endure
            self._finish_forge(item, changes, True)

    def _forge_recover_broken(
        self,
        item: InventoryItem,
        definition: EquipmentDefinition,
        fields: list[str],
    ) -> None:
        """Recover a fragmented equipment instance with EquipSystem.crash material."""
        if item.crash_time <= 0 or item.slot == op(EquipmentPosition.BADGE):
            return
        config = dict(GAME_DATA_CATALOG.get_equipment_system_config("crash"))
        if not config:
            return
        config["needItemCnt"] = 1
        with self.store.lock:
            paid = self._consume_forge_cost(config)
            if paid is None:
                return
            changes, _ = paid
            succeeded = self._roll_forge(self._safe_int(config.get("prob"), 0))
            if succeeded:
                item.crash_time = 0
            self._finish_forge(item, changes, succeeded)
        if succeeded:
            self._send_character_notice("装备破碎修复成功")
            self._send_all_stats()
        else:
            self._send_character_notice("装备破碎修复失败")

    def _forge_born_attribute(
        self,
        item: InventoryItem,
        definition: EquipmentDefinition,
        fields: list[str],
    ) -> None:
        """Roll the innate attribute value using EquipSystem.born type and stage costs."""
        root = GAME_DATA_CATALOG.get_equipment_system_config("born")
        type_config = root.get(definition.type_name)
        money = root.get("needMoney")
        if not isinstance(type_config, dict) or not isinstance(money, dict):
            return
        config = {
            **type_config,
            "needItemId": root.get("needItemId"),
            "needMoney": money.get(f"stage{definition.stage}"),
        }
        with self.store.lock:
            paid = self._consume_forge_cost(config)
            if paid is None:
                return
            changes, _ = paid
            succeeded = self._roll_forge(self._safe_int(config.get("prob"), 0))
            if succeeded:
                item.born_attr_value = max(item.born_attr_value, round(item.base_attr_value * self.random.randint(10, 100) / 100))
            self._finish_forge(item, changes, succeeded)
        if not succeeded:
            self._send_system_chat("天生属性打造失败，原属性保留。")

    def _forge_carve(
        self,
        item: InventoryItem,
        definition: EquipmentDefinition,
        fields: list[str],
    ) -> None:
        """Carve one of the four original secret seals and persist its percentage value."""
        root = GAME_DATA_CATALOG.get_equipment_system_config("carve")
        requirements = root.get("req") if isinstance(root.get("req"), dict) else {}
        config = requirements.get(f"stage{definition.stage}")
        values = root.get("value") if isinstance(root.get("value"), dict) else {}
        if not isinstance(config, dict) or not values:
            return
        with self.store.lock:
            paid = self._consume_forge_cost(config)
            if paid is None:
                return
            changes, _ = paid
            succeeded = self._roll_forge(self._safe_int(config.get("prob"), 0))
            if succeeded:
                carve_id = self.random.choice(sorted(self._safe_int(key, 0) for key in values if self._safe_int(key, 0) > 0))
                carve = values.get(str(carve_id)) if isinstance(values.get(str(carve_id)), dict) else {}
                carve_types = {
                    "ATK_RATE": EquipmentAttribute.ATTACK_RATE,
                    "DAMAGE_REFLECT": EquipmentAttribute.DAMAGE_REFLECT,
                    "DAMAGE_REDUCE": EquipmentAttribute.DAMAGE_REDUCE,
                    "IGNORE_DEF": EquipmentAttribute.IGNORE_DEFENCE,
                }
                item.carve_id = carve_id
                item.carve_type = int(carve_types.get(str(carve.get("type")), EquipmentAttribute.ATTACK_RATE))
                item.carve_value = self.random.randint(
                    self._safe_int(carve.get("value_min"), 1),
                    max(1, self._safe_int(carve.get("value_max"), 1)),
                )
                self._bind_item_instance(item)
            self._finish_forge(item, changes, succeeded)
        if not succeeded:
            self._send_system_chat("秘印刻印失败，原秘印保留。")

    def _generate_plus_attributes(
        self,
        item: InventoryItem,
        definition: EquipmentDefinition,
        requested_count: int,
    ) -> list[list[int]]:
        """Generate unique original secondary attributes for one equipment stage and type."""
        plus_root = GAME_DATA_CATALOG.get_equipment_system_config("plus")
        stage_root = plus_root.get(f"stage{definition.stage}")
        type_root = stage_root.get(definition.type_name) if isinstance(stage_root, dict) else None
        if not isinstance(type_root, dict):
            return []
        candidates = [value for _, value in sorted(type_root.items()) if isinstance(value, dict)]
        attributes: list[list[int]] = []
        for config in candidates[: max(1, min(requested_count, len(candidates)))]:
            attribute = EQUIPMENT_ATTRIBUTE_BY_NAME.get(str(config.get("type") or "").lower())
            if attribute is None:
                continue
            value_from = self._safe_int(config.get("valueFrom"), 1)
            value_to = max(value_from, self._safe_int(config.get("valueTo"), value_from))
            attributes.append([int(attribute), self.random.randint(value_from, value_to)])
        return attributes

    def _forge_wash_plus_attributes(
        self,
        item: InventoryItem,
        definition: EquipmentDefinition,
        fields: list[str],
    ) -> None:
        """Roll a preview secondary-attribute list for the original save-or-cancel dialog."""
        plus_root = GAME_DATA_CATALOG.get_equipment_system_config("plus")
        wash = plus_root.get("washvalue") if isinstance(plus_root.get("washvalue"), dict) else {}
        needs = wash.get("need") if isinstance(wash.get("need"), dict) else {}
        stage = needs.get(f"stage{definition.stage}") if isinstance(needs.get(f"stage{definition.stage}"), dict) else {}
        current_count = len(item.plus_attributes) or max(1, min(5, item.aptitude))
        count_config = stage.get(f"plus{current_count}") if isinstance(stage.get(f"plus{current_count}"), dict) else {}
        config = {**count_config, "needItemId": wash.get("needItemId"), "needMoney": stage.get("needMoney")}
        with self.store.lock:
            paid = self._consume_forge_cost(config)
            if paid is None:
                return
            changes, _ = paid
            preview = self._generate_plus_attributes(item, definition, current_count)
            self.pending_plus_attributes[item.slot] = preview
            self._finish_forge(item, changes, False)
        encoded = "@".join(f"{values[0]}&{values[1]}" for values in preview) or "-"
        self.send_text(
            f"{op(ServerOpcode.WASH_PLUS_VALUE_RESULT)}:{item.slot}:"
            f"{op(ForgeResult.SUCCESS)}:{encoded}"
        )

    def _forge_select_plus_attributes(
        self,
        item: InventoryItem,
        definition: EquipmentDefinition,
        fields: list[str],
    ) -> None:
        """Accept or discard the pending secondary attributes selected in the Flash dialog."""
        accepted = bool(self._safe_int(fields[2], 0)) if len(fields) > 2 else False
        preview = self.pending_plus_attributes.pop(item.slot, None)
        if not accepted or preview is None:
            return
        with self.store.lock:
            item.plus_attributes = preview
            self._finish_forge(item, [], True)

    def _wash_special_attribute(self, item: InventoryItem, is_transform_card: bool) -> None:
        stone_id = 16_000_181
        gold_cost = 1_000_000
        with self.store.lock:
            if self._inventory_item_quantity(stone_id) < 1:
                self._send_system_chat("特性洗练石不足。")
                return
            if self.store.state.money < gold_cost:
                self._send_system_chat("金币不足，需要1000000金币。")
                return
            changes = self._consume_inventory_quantity(stone_id, 1)
            self.store.state.money -= gold_cost
            percent_candidates = [
                int(EquipmentAttribute.MAX_HP), int(EquipmentAttribute.MAX_MP),
                int(EquipmentAttribute.ATTACK), int(EquipmentAttribute.DEFENCE),
                int(EquipmentAttribute.CRITICAL), int(EquipmentAttribute.EVASION),
                int(EquipmentAttribute.ATTACK_SPEED), int(EquipmentAttribute.WALK_SPEED),
                int(EquipmentAttribute.ATTACK_RATE),
            ]
            fixed_candidates = [
                int(EquipmentAttribute.MAX_HP), int(EquipmentAttribute.MAX_MP),
                int(EquipmentAttribute.ATTACK), int(EquipmentAttribute.DEFENCE),
                int(EquipmentAttribute.CRITICAL), int(EquipmentAttribute.EVASION),
            ]
            used_types: set[int] = set()
            attributes: list[list[int]] = []
            for _ in range(4 if is_transform_card else 3):
                remaining = [value for value in percent_candidates if value not in used_types] or percent_candidates
                attribute_type = self.random.choice(remaining)
                used_types.add(attribute_type)
                attributes.append([attribute_type, self.random.randint(1, 5)])
            stage = max(1, int(getattr(item, "stage", 1) or 1))
            for _ in range(3):
                remaining = [value for value in fixed_candidates if value not in used_types] or fixed_candidates
                attribute_type = self.random.choice(remaining)
                used_types.add(attribute_type)
                base_value = 100 + stage * 50
                attributes.append([
                    attribute_type,
                    self.random.randint(base_value, base_value + stage * 100),
                ])
            extra = (
                len(attributes),
                self.random.randint(1, 3),
                1 if self.random.randrange(100) < 15 else 0,
            )
            self.pending_special_attributes[item.slot] = [list(row) for row in attributes]
            self.pending_special_extra[item.slot] = extra
            self._finish_forge(item, changes, False)
        encoded = "@".join(f"{row[0]}&{row[1]}" for row in attributes) or "-"
        self.send_text(
            f"{op(ServerOpcode.WASH_SPECIAL_ATTR_RESULT)}:{item.slot}:"
            f"{op(ForgeResult.SUCCESS)}:{encoded}:{extra[0]}:{extra[1]}:{extra[2]}"
        )

    def _select_special_attribute(self, item: InventoryItem, accepted: bool) -> None:
        preview = self.pending_special_attributes.pop(item.slot, None)
        extra = self.pending_special_extra.pop(item.slot, None)
        if not accepted or preview is None or extra is None:
            return
        with self.store.lock:
            item.special_attributes = [list(row) for row in preview]
            item.special_level, item.special_effect_type, item.afterimage_flag = extra
            self._finish_forge(item, [], True)

    def _forge_full_plus_attribute(
        self,
        item: InventoryItem,
        definition: EquipmentDefinition,
        fields: list[str],
    ) -> None:
        """Max one selected secondary attribute using the original perfect-refine item."""
        attribute_index = self._safe_int(fields[3], -1) if len(fields) > 3 else -1
        if attribute_index < 0 or attribute_index >= len(item.plus_attributes):
            return
        plus_root = GAME_DATA_CATALOG.get_equipment_system_config("plus")
        full_config = plus_root.get("fullone") if isinstance(plus_root.get("fullone"), dict) else {}
        config = {"needItemId": full_config.get("needItemId"), "needItemCnt": 1}
        stage_root = plus_root.get(f"stage{definition.stage}")
        type_root = stage_root.get(definition.type_name) if isinstance(stage_root, dict) else {}
        attribute_type = item.plus_attributes[attribute_index][0]
        maximum = item.plus_attributes[attribute_index][1]
        if isinstance(type_root, dict):
            for candidate in type_root.values():
                if not isinstance(candidate, dict):
                    continue
                candidate_type = EQUIPMENT_ATTRIBUTE_BY_NAME.get(str(candidate.get("type") or "").lower())
                if candidate_type is not None and int(candidate_type) == attribute_type:
                    maximum = max(maximum, self._safe_int(candidate.get("valueTo"), maximum))
                    break
        with self.store.lock:
            paid = self._consume_forge_cost(config)
            if paid is None:
                return
            changes, _ = paid
            item.plus_attributes[attribute_index][1] = maximum
            self._finish_forge(item, changes, True)

    def _forge_level_eleven(
        self,
        item: InventoryItem,
        definition: EquipmentDefinition,
        fields: list[str],
    ) -> None:
        """Use the original hundred-refine stone to raise a level-10 item to level 11."""
        config = GAME_DATA_CATALOG.get_equipment_system_config("strength").get("level11")
        succeeded = False
        if not isinstance(config, dict) or item.strength_level != 10:
            self.send_text(
                f"{op(ServerOpcode.EQUIPMENT_FORGE_STRENGTH_RESULT)}:"
                f"{item.slot}:{op(ForgeResult.FAILURE)}"
            )
            return
        with self.store.lock:
            paid = self._consume_forge_cost(config)
            if paid is None:
                return
            changes, _ = paid
            succeeded = self._roll_forge(self._safe_int(config.get("prob"), 0))
            if succeeded:
                item.strength_level = 11
                item.strength_value = round(item.base_attr_value * self._safe_int(config.get("addRatio"), 0) / 100)
                item.strength_info = [True] * 11
            self._finish_forge(item, changes, succeeded)
        self.send_text(
            f"{op(ServerOpcode.EQUIPMENT_FORGE_STRENGTH_RESULT)}:"
            f"{item.slot}:{op(ForgeResult.SUCCESS if succeeded else ForgeResult.FAILURE)}"
        )

    def _forge_additive(
        self,
        item: InventoryItem,
        definition: EquipmentDefinition,
        fields: list[str],
    ) -> None:
        """Increase the persisted hundred-refine additive ratio and return opcode 2065."""
        config = GAME_DATA_CATALOG.get_equipment_system_config("forgeAdditive")
        succeeded = False
        if item.strength_level < 11 or item.forge_additive_ratio >= self.MAX_FORGE_ADDITIVE_RATIO:
            self.send_text(
                f"{op(ServerOpcode.EQUIPMENT_FORGE_ADDITIVE_RESULT)}:"
                f"{item.slot}:{op(ForgeResult.FAILURE)}"
            )
            return
        with self.store.lock:
            paid = self._consume_forge_cost(config)
            if paid is None:
                return
            changes, _ = paid
            succeeded = self._roll_forge(self._safe_int(config.get("prob"), 0))
            if succeeded:
                roll = self.random.randrange(100)
                gain = 3 if roll >= 90 else 2 if roll >= 60 else 1
                item.forge_additive_ratio = min(
                    self.MAX_FORGE_ADDITIVE_RATIO,
                    item.forge_additive_ratio + gain,
                )
            self._finish_forge(item, changes, succeeded)
        self.send_text(
            f"{op(ServerOpcode.EQUIPMENT_FORGE_ADDITIVE_RESULT)}:"
            f"{item.slot}:{op(ForgeResult.SUCCESS if succeeded else ForgeResult.FAILURE)}"
        )

    def _forge_change_to_orange(
        self,
        item: InventoryItem,
        definition: EquipmentDefinition,
        fields: list[str],
    ) -> None:
        """Consume original orange stones and promote any lower aptitude to orange."""
        root = GAME_DATA_CATALOG.get_equipment_system_config("changeToOrange")
        type_config = root.get(definition.type_name)
        if (
            not isinstance(type_config, dict)
            or item.aptitude != 4
            or item.strength_level < 10
            or definition.required_level < 60
        ):
            self._send_system_chat("只有60级以上的紫色10星装备可以打造为橙装。")
            return
        config = {**type_config, "needItemId": root.get("needItemId")}
        with self.store.lock:
            paid = self._consume_forge_cost(config)
            if paid is None:
                return
            changes, _ = paid
            item.aptitude = 5
            if not item.plus_attributes:
                item.plus_attributes = self._generate_plus_attributes(item, definition, item.aptitude)
            self._roll_tale_attribute(item)
            self._finish_forge(item, changes, True)

    def _forge_change_tale_attribute(
        self,
        item: InventoryItem,
        definition: EquipmentDefinition,
        fields: list[str],
    ) -> None:
        """Reroll one original legendary core attribute and persist it in CocoEquip."""
        config = GAME_DATA_CATALOG.get_equipment_system_config("changeTaleAttribute")
        with self.store.lock:
            paid = self._consume_forge_cost(config)
            if paid is None:
                return
            changes, _ = paid
            self._roll_tale_attribute(item)
            self._finish_forge(item, changes, True)

    def _roll_tale_attribute(self, item: InventoryItem) -> None:
        """Roll one original orange legendary core attribute from EquipSystem.taleAttributes."""
        rows = GAME_DATA_CATALOG.get_equipment_system_config("taleAttributes")
        candidates = [row for row in rows.values() if isinstance(row, dict)]
        if not candidates:
            return
        selected = self.random.choice(candidates)
        attribute = EQUIPMENT_ATTRIBUTE_BY_NAME.get(
            str(selected.get("type") or "").lower()
        )
        if attribute is None:
            return
        value_from = self._safe_int(selected.get("valueFrom"), 1)
        value_to = max(value_from, self._safe_int(selected.get("valueTo"), value_from))
        item.tale_attr_type = op(attribute)
        item.tale_attr_value = self.random.randint(value_from, value_to)

    def _start_solo_trial(self) -> None:
        """Start a four-kill local trial that uses the original forest monsters and rewards."""
        progression = self.store.state.progression
        if progression.trial_active:
            self._send_npc_dialog(
                f"单人试炼进行中：{progression.trial_kills}/4。",
                self.QUEST_NPC_TEMPLATE_ID,
            )
            return
        progression.trial_active = True
        progression.trial_kills = 0
        progression.trial_return_map = self.character.map_id
        self.store.save()
        self._warp_to_map(int(MapId.KONOHA_FOREST))
        self._send_system_chat("单人试炼开始：击败三只怪物和最后一只首领，共四只。")

    def _claim_available_achievements(self) -> None:
        """Claim deterministic offline milestones for kills, maps, level, quests, skills, and gear."""
        progression = self.store.state.progression
        completed_quests = sum(
            progress.state == int(QuestState.COMPLETED)
            for progress in self.store.state.original_quests.values()
        )
        conditions = {
            "first_kill": progression.total_monster_kills >= 1,
            "five_maps": len(progression.visited_maps) >= 5,
            "level_five": self.character.level >= 5,
            "first_quest": completed_quests >= 1 or self.store.state.quest.state == int(QuestState.COMPLETED),
            "first_skill": bool(self.store.state.skills),
            "first_equipment": any(slot < 0 for slot in self.store.state.inventory),
            "trial_clear": progression.trial_best >= 4,
        }
        claimable = [key for key, ready in conditions.items() if ready and key not in progression.claimed_achievements]
        if not claimable:
            self._send_npc_dialog("当前没有可领取的成就奖励。", self.QUEST_NPC_TEMPLATE_ID)
            return
        if not self._has_inventory_capacity([(int(ItemId.HEALTH_POTION), len(claimable))]):
            self._send_npc_dialog("背包空间不足，暂时不能领取成就奖励。", self.QUEST_NPC_TEMPLATE_ID)
            return
        with self.store.lock:
            progression.claimed_achievements.extend(claimable)
            self.store.state.money += 200 * len(claimable)
            reward, created = self._add_inventory_item(int(ItemId.HEALTH_POTION), len(claimable))
            self.store.save()
        if created:
            self._send_inventory_add(reward, from_drop=0)
        else:
            self._send_inventory_update(reward, from_drop=0)
        self._send_stats({StatType.MONEY: self.store.state.money})
        self._send_npc_dialog(
            f"领取 {len(claimable)} 项成就：金币 {200 * len(claimable)}、药水 {len(claimable)}。",
            self.QUEST_NPC_TEMPLATE_ID,
        )

    def _send_legacy_npc_shop(self, npc_template_id: int | None = None) -> None:
        """Open the role-appropriate inventory, including live editor prices."""
        resolved_npc_id = npc_template_id or self.QUEST_NPC_TEMPLATE_ID
        encoded_tabs: list[str] = []
        config = self._merchant_shop_config(resolved_npc_id)
        for tab in config["tabs"]:
            if tab.get("enabled") is False:
                continue
            tab_name = str(tab.get("name") or "商品")
            item_ids = tab.get("itemIds") if isinstance(tab.get("itemIds"), list) else []
            encoded_items: list[str] = []
            for raw_item_id in item_ids:
                item_id = self._safe_int(raw_item_id, 0)
                definition = GAME_DATA_CATALOG.get_item_definition(item_id)
                if definition is None:
                    continue
                price = self._merchant_price(item_id, config)
                item_type = (
                    ItemCodecType.EQUIPMENT
                    if GAME_DATA_CATALOG.is_equipment_item(item_id)
                    else ItemCodecType.ITEM
                )
                encoded_items.append(
                    f"{item_id}#{price}#0#{price}#{definition.stack_max}#"
                    f"{op(item_type)}#false"
                )
            if encoded_items:
                encoded_tabs.append(f"{tab_name}&{'!'.join(encoded_items)}")
        self.send_text(
            f"{op(ServerOpcode.OPEN_NPC_SHOP)}:"
            f"{resolved_npc_id}:"
            f"{'@'.join(encoded_tabs)}"
        )
        if resolved_npc_id in self.NEW_PLAYER_MERCHANT_IDS:
            self._queue_tutorial_once(
                f"npc-shop:{resolved_npc_id}",
                BeginUiEffect.NPC_SHOP,
            )

    def _send_npc_shop(self, npc_template_id: int | None = None) -> None:
        """Open a merchant with exact captured row metadata when available."""
        resolved_npc_id = npc_template_id or self.QUEST_NPC_TEMPLATE_ID
        config = self._merchant_shop_config(resolved_npc_id)
        encoded_tabs: list[str] = []
        for tab in config["tabs"]:
            if tab.get("enabled") is False:
                continue
            tab_name = str(tab.get("name") or "商品").translate(SIMPLIFIED_TRANSLATION)
            item_ids = tab.get("itemIds") if isinstance(tab.get("itemIds"), list) else []
            encoded_items: list[str] = []
            for raw_item_id in item_ids:
                item_id = self._safe_int(raw_item_id, 0)
                definition = GAME_DATA_CATALOG.get_item_definition(item_id)
                if definition is None:
                    continue
                captured = self._captured_merchant_item(config, item_id)
                price = self._merchant_price(item_id, config)
                item_type = int(captured["item_type"]) if captured is not None else op(
                    ItemCodecType.EQUIPMENT
                    if GAME_DATA_CATALOG.is_equipment_item(item_id)
                    else ItemCodecType.ITEM
                )
                slot_max = (
                    max(1, int(captured["slot_max"]))
                    if captured is not None
                    else definition.stack_max
                )
                can_recharge = bool(captured.get("can_recharge", False)) if captured else False
                encoded_items.append(
                    f"{item_id}#{price}#0#{price}#{slot_max}#"
                    f"{item_type}#{str(can_recharge).lower()}"
                )
            if encoded_items:
                encoded_tabs.append(f"{tab_name}&{'!'.join(encoded_items)}")
        self.send_text(
            f"{op(ServerOpcode.OPEN_NPC_SHOP)}:{resolved_npc_id}:"
            f"{'@'.join(encoded_tabs)}"
        )
        if resolved_npc_id in self.NEW_PLAYER_MERCHANT_IDS:
            self._queue_tutorial_once(
                f"npc-shop:{resolved_npc_id}",
                BeginUiEffect.NPC_SHOP,
            )

    def _queue_tutorial_once(
        self,
        key: str,
        effect: BeginUiEffect,
        delay_seconds: float = 0.35,
    ) -> bool:
        """Persist a guide and wait until its target window exists before emitting it."""
        with self.store.lock:
            if key in self.store.state.shown_tutorials:
                return False
            self.store.state.shown_tutorials.append(key)
            self.store.state.shown_tutorials.sort()
            self.store.save()
        self.pending_tutorial_effects.append(
            (time.monotonic() + max(0.0, delay_seconds), effect)
        )
        return True

    def _flush_pending_tutorials(self, now: float | None = None) -> None:
        """Emit queued guide effects whose native UI targets have finished opening."""
        current_time = time.monotonic() if now is None else now
        ready = [
            (due_at, effect)
            for due_at, effect in self.pending_tutorial_effects
            if due_at <= current_time
        ]
        self.pending_tutorial_effects = [
            (due_at, effect)
            for due_at, effect in self.pending_tutorial_effects
            if due_at > current_time
        ]
        for _, effect in ready:
            self.send_text(f"{op(ServerOpcode.BEGIN_UI_EFFECT)}:{op(effect)}")

    def _send_tutorial_once(self, key: str, effect: BeginUiEffect) -> bool:
        """Persist and emit one original client guide effect exactly once."""
        with self.store.lock:
            if key in self.store.state.shown_tutorials:
                return False
            self.store.state.shown_tutorials.append(key)
            self.store.state.shown_tutorials.sort()
            self.store.save()
        self.send_text(f"{op(ServerOpcode.BEGIN_UI_EFFECT)}:{op(effect)}")
        return True

    def _mystery_shop_catalog(self) -> list[int]:
        """Return unique, currently enabled cash items that the client can render."""
        item_ids: list[int] = []
        for category in CashShopCategory:
            item_ids.extend(self._cash_shop_config(int(category))["item_ids"])
        return [
            item_id
            for item_id in dict.fromkeys(item_ids)
            if GAME_DATA_CATALOG.get_item_definition(item_id) is not None
        ]

    def _refresh_mystery_shop(self, *, manual: bool = False) -> bool:
        """Rotate five bound products and persist the six-hour refresh deadline."""
        progression = self.store.state.progression
        now = int(time.time())
        catalog = self._mystery_shop_catalog()
        if len(catalog) < 5:
            self._send_system_chat("神秘商店当前没有足够的有效商品。")
            return False
        if manual:
            with self.store.lock:
                if self.store.state.cash_money < 50:
                    self._send_system_chat("元宝不足，手动刷新神秘商店需要50元宝。")
                    return False
                self.store.state.cash_money -= 50
        seed = (
            self.character.character_id * 1_000_003
            + now
            + progression.mystery_shop_refresh_at * 31
        )
        selected = random.Random(seed).sample(catalog, 5)
        with self.store.lock:
            progression.mystery_shop_item_ids = selected
            progression.mystery_shop_bought_ids = []
            progression.mystery_shop_refresh_at = now + 6 * 60 * 60
            self.store.save()
        if manual:
            self.handle_cash_money("")
        return True

    def _ensure_mystery_shop(self) -> bool:
        progression = self.store.state.progression
        valid = (
            len(progression.mystery_shop_item_ids) == 5
            and all(
                GAME_DATA_CATALOG.get_item_definition(item_id) is not None
                for item_id in progression.mystery_shop_item_ids
            )
        )
        if not valid or progression.mystery_shop_refresh_at <= int(time.time()):
            return self._refresh_mystery_shop()
        return True

    def _mystery_shop_row(self, item_id: int) -> tuple[int, int]:
        category = self._cash_shop_category(item_id) or CashShopCategory.COMMON
        price = self._cash_shop_price(item_id, int(category))
        index = self.store.state.progression.mystery_shop_item_ids.index(item_id)
        # The original window explicitly supports both point-coupon and ingot rows.
        return price, 1 if index % 2 else 0

    def _send_mystery_shop(self) -> None:
        if not self._ensure_mystery_shop():
            return
        progression = self.store.state.progression
        remain_seconds = max(
            0, progression.mystery_shop_refresh_at - int(time.time())
        )
        bought = set(progression.mystery_shop_bought_ids)
        rows: list[tuple[int, int, int, int, int, int]] = []
        for item_id in progression.mystery_shop_item_ids:
            price, money_type = self._mystery_shop_row(item_id)
            rows.append(
                (
                    item_id,
                    1,
                    price,
                    money_type,
                    price,
                    int(item_id in bought),
                )
            )

        if self.wire_mode != "original":
            encoded_rows = "@".join(
                "&".join(str(value) for value in row) for row in rows
            ) or "-"
            self.send_text(
                f"{op(ServerOpcode.OPEN_SECRET_SHOP)}:{remain_seconds}:"
                f"{encoded_rows}:100"
            )
            return

        body = bytearray(struct.pack("<ii", remain_seconds, len(rows)))
        for row in rows:
            body.extend(
                struct.pack(
                    "<6i",
                    *row,
                )
            )
        body.extend(struct.pack("<i", 100))
        self.send_original_packet(ServerOpcode.OPEN_SECRET_SHOP, bytes(body))

    def _buy_mystery_shop_item(self, item_id: int) -> None:
        progression = self.store.state.progression
        if not self._ensure_mystery_shop():
            return
        if (
            item_id not in progression.mystery_shop_item_ids
            or item_id in progression.mystery_shop_bought_ids
        ):
            self._send_mystery_shop()
            return
        price, money_type = self._mystery_shop_row(item_id)
        if self._complete_cash_shop_purchase(
            item_id,
            1,
            price,
            use_bound_cash=money_type == 1,
            force_bound=True,
        ):
            with self.store.lock:
                progression.mystery_shop_bought_ids.append(item_id)
                self.store.save()
            if money_type == 1:
                self._send_stats({StatType.CASH_BIND: self.store.state.coupon_money})
            else:
                self.handle_cash_money("")
        self._send_mystery_shop()

    def handle_npc_shop(self, read_str: str) -> None:
        """Buy or sell local items with persisted character gold."""
        fields = self._request_fields(read_str, ClientOpcode.NPC_SHOP)
        if not fields:
            return
        special_action = self._safe_int(fields[0], -1)
        if special_action == 6:
            if self.character.level < 25:
                self._send_system_chat("达到25级后才能开启神秘商店。")
                return
            self._send_mystery_shop()
            return
        if special_action == 7 and len(fields) >= 2:
            self._buy_mystery_shop_item(self._safe_int(fields[1], 0))
            return
        if special_action == 8:
            if self.character.level < 25:
                self._send_system_chat("达到25级后才能开启神秘商店。")
                return
            if self._refresh_mystery_shop(manual=True):
                self._send_mystery_shop()
            return
        try:
            action = ShopAction(self._safe_int(fields[0], -1))
        except ValueError:
            self._send_shop_confirmation(ShopConfirmCode.SHOP_ERROR)
            return
        if action == ShopAction.BUY and len(fields) >= 3:
            self._buy_shop_item(self._safe_int(fields[1], 0), self._safe_int(fields[2], 0))
        elif action == ShopAction.SELL and len(fields) >= 4:
            self._sell_shop_item(
                self._safe_int(fields[1], 0),
                self._safe_int(fields[2], 0),
                self._safe_int(fields[3], 0),
            )
        elif action == ShopAction.SELL_ALL_NORMAL_EQUIPMENT and len(fields) >= 3:
            self._sell_matching_equipment(
                maximum_aptitude=self._safe_int(fields[1], 0),
                maximum_strength=self._safe_int(fields[2], 0),
            )
        elif action == ShopAction.ONE_KEY_SELL_EQUIPMENT and len(fields) >= 4:
            self._sell_matching_equipment(
                maximum_required_level=self._safe_int(fields[1], 0),
                maximum_strength=self._safe_int(fields[2], 0),
                maximum_aptitude=self._safe_int(fields[3], 0),
            )
        else:
            self._send_shop_confirmation(ShopConfirmCode.SHOP_ERROR)

    def _send_shop_confirmation(self, code: ShopConfirmCode) -> None:
        """Finish one original shop transaction in both Flash transports."""
        self.send_text(f"{op(ServerOpcode.CONFIRM_SHOP_TRANSACTION)}:{op(code)}")

    def _buy_shop_item(self, item_id: int, quantity: int) -> None:
        """Validate the active merchant row, deduct gold, and add purchased instances."""
        if quantity <= 0:
            self._send_shop_confirmation(ShopConfirmCode.SHOP_ERROR)
            return
        definition = GAME_DATA_CATALOG.get_item_definition(item_id)
        if definition is None:
            self._send_shop_confirmation(ShopConfirmCode.SHOP_ERROR)
            return
        requested_quantity = quantity
        quantity = min(quantity, _item_stack_limit(item_id))
        active_npc = self.npcs.get(self.active_npc_object_id or -1)
        config = self._merchant_shop_config(active_npc.template_id if active_npc is not None else 0)
        sold_item_ids = {
            self._safe_int(raw_id, 0)
            for tab in config["tabs"]
            if tab.get("enabled") is not False
            for raw_id in (tab.get("itemIds") or [])
        }
        if item_id not in sold_item_ids:
            self._send_shop_confirmation(ShopConfirmCode.SHOP_ERROR)
            return
        total_price = self._merchant_price(item_id, config) * quantity
        with self.store.lock:
            if self.store.state.money < total_price:
                self._send_shop_confirmation(ShopConfirmCode.NO_ENOUGH_MONEY)
                self._send_system_chat("金币不足。")
                return
            if not self._has_inventory_capacity([(item_id, quantity)]):
                self._send_system_chat("背包已满。")
                return
            item, created = self._add_inventory_item(item_id, quantity)
            self.store.state.money -= total_price
            self.store.save()
        if created:
            self._send_inventory_add(item, from_drop=0)
        else:
            self._send_inventory_update(item, from_drop=0)
        self._send_stats({StatType.MONEY: self.store.state.money})
        self._send_shop_confirmation(ShopConfirmCode.BUY_SUCCESS)
        if quantity != requested_quantity:
            self._send_system_chat(
                f"输入数量超过{definition.name}的堆叠上限，已按{quantity}件购买。"
            )
        self._refresh_all_original_quests()

    def _complete_cash_shop_purchase(
        self,
        item_id: int,
        quantity: int,
        unit_price: int,
        use_bound_cash: bool = False,
        force_bound: bool = False,
    ) -> bool:
        """Apply the shared persisted inventory and premium-currency transaction."""
        if quantity <= 0:
            return False
        definition = GAME_DATA_CATALOG.get_item_definition(item_id)
        if definition is None:
            return False
        requested_quantity = quantity
        quantity = min(quantity, _item_stack_limit(item_id))
        total_price = max(1, unit_price) * quantity
        with self.store.lock:
            balance = (
                self.store.state.coupon_money
                if use_bound_cash
                else self.store.state.cash_money
            )
            if balance < total_price:
                self._send_system_chat("元宝不足。")
                return False
            if not self._has_inventory_capacity([(item_id, quantity)]):
                self._send_system_chat("背包已满。")
                return False
            item, created = self._add_inventory_item(
                item_id,
                quantity,
                can_trade=False if force_bound else None,
            )
            if use_bound_cash:
                self.store.state.coupon_money -= total_price
            else:
                self.store.state.cash_money -= total_price
            self.store.save()
        if created:
            self._send_inventory_add(item, from_drop=0)
        else:
            self._send_inventory_update(item, from_drop=0)
        self._send_system_chat(f"购买成功，获得{definition.name}×{quantity}。")
        if quantity != requested_quantity:
            self._send_system_chat(
                f"输入数量超过堆叠上限，本次仅结算{quantity}件，未多扣货币。"
            )
        self._refresh_all_original_quests()
        return True

    def _buy_cash_shop_item(self, item_id: int, quantity: int) -> None:
        """Purchase one generated cash-shop item with premium currency."""
        if item_id not in self._cash_shop_item_ids(self.active_cash_category_id):
            return
        self._complete_cash_shop_purchase(
            item_id,
            quantity,
            self._cash_shop_price(item_id),
        )

    def _sell_shop_item(self, slot: int, item_id: int, quantity: int) -> None:
        """Remove a bag quantity and pay the active merchant's configured sell rate."""
        definition = GAME_DATA_CATALOG.get_item_definition(item_id)
        if definition is None or quantity <= 0:
            self._send_shop_confirmation(ShopConfirmCode.SHOP_ERROR)
            return
        active_npc = self.npcs.get(self.active_npc_object_id or -1)
        config = self._merchant_shop_config(active_npc.template_id if active_npc is not None else 0)
        with self.store.lock:
            item = self.store.state.inventory.get(slot)
            if item is None or slot <= 0 or item.item_id != item_id:
                self._send_shop_confirmation(ShopConfirmCode.SHOP_ERROR)
                return
            sold = min(quantity, item.quantity)
            item.quantity -= sold
            base_price = max(1, self._safe_int(config["prices"].get(str(item_id), definition.price), definition.price))
            self.store.state.money += max(1, round(base_price * config["sell_multiplier"])) * sold
            removed = item.quantity == 0
            if removed:
                del self.store.state.inventory[slot]
            self.store.save()
        if removed:
            self._send_inventory_clear(slot, InventoryType.BAG)
        else:
            self._send_inventory_update(item, from_drop=0)
        self._send_stats({StatType.MONEY: self.store.state.money})
        self._send_shop_confirmation(ShopConfirmCode.SELL_SUCCESS)
        self._refresh_all_original_quests()

    @staticmethod
    def _is_normal_quick_sale_equipment(
        item: InventoryItem,
        definition: EquipmentDefinition | None,
    ) -> bool:
        """Match ItemType.isItemAZhuangBei while excluding protected equipment families."""
        if item.slot <= 0 or definition is None:
            return False
        item_family = item.item_id // 1_000_000
        equipment_type = item.item_id // 10_000
        if item_family == 1:
            return 101 <= equipment_type <= 112
        if item_family == 2:
            return 201 <= equipment_type <= 204
        return False

    def _sell_matching_equipment(
        self,
        *,
        maximum_aptitude: int,
        maximum_strength: int,
        maximum_required_level: int | None = None,
    ) -> None:
        """Atomically sell every bag equipment instance accepted by Nya's quick-sale filters."""
        if maximum_aptitude < 1 or maximum_strength < 0:
            self._send_shop_confirmation(ShopConfirmCode.SHOP_ERROR)
            return
        active_npc = self.npcs.get(self.active_npc_object_id or -1)
        config = self._merchant_shop_config(
            active_npc.template_id if active_npc is not None else 0
        )
        sold_slots: list[int] = []
        total_price = 0
        with self.store.lock:
            for slot, item in list(self.store.state.inventory.items()):
                definition = (
                    GAME_DATA_CATALOG.get_equipment_definition(item.item_id)
                    or GAME_DATA_CATALOG.get_pet_equipment_definition(item.item_id)
                )
                if not self._is_normal_quick_sale_equipment(item, definition):
                    continue
                if item.aptitude > maximum_aptitude:
                    continue
                if item.strength_level > maximum_strength or item.strength_level >= 7:
                    continue
                if item.inlays:
                    continue
                if (
                    maximum_required_level is not None
                    and definition is not None
                    and definition.required_level > maximum_required_level
                ):
                    continue
                item_definition = GAME_DATA_CATALOG.get_item_definition(item.item_id)
                if item_definition is None:
                    continue
                base_price = max(
                    1,
                    self._safe_int(
                        config["prices"].get(str(item.item_id), item_definition.price),
                        item_definition.price,
                    ),
                )
                unit_price = max(1, round(base_price * config["sell_multiplier"]))
                total_price += unit_price * max(1, item.quantity)
                sold_slots.append(slot)
                del self.store.state.inventory[slot]
            if sold_slots:
                self.store.state.money += total_price
                self.store.save()
        for slot in sold_slots:
            self._send_inventory_clear(slot, InventoryType.BAG)
        if sold_slots:
            self._send_stats({StatType.MONEY: self.store.state.money})
            self._refresh_all_original_quests()
        self._send_shop_confirmation(ShopConfirmCode.SELL_SUCCESS)

    def _send_storage_open(self) -> None:
        """Open the persisted single-player warehouse with full item instances."""
        items = "@".join(
            self._encode_item_payload(item)
            for item in sorted(self.store.state.storage.values(), key=lambda value: value.slot)
        ) or "-"
        self.send_text(
            f"{op(ServerOpcode.OPEN_STORAGE)}:{op(StorageAction.MOVE)}:"
            f"{self.QUEST_NPC_TEMPLATE_ID}:{self.store.state.storage_capacity}:"
            f"{self.store.state.storage_money}:{len(self.store.state.storage)}:{items}"
        )

    def handle_storage(self, read_str: str) -> None:
        """Move items and gold between the bag and persisted local warehouse."""
        fields = self._request_fields(read_str, ClientOpcode.STORAGE)
        if not fields:
            return
        try:
            action = StorageAction(self._safe_int(fields[0], -1))
        except ValueError:
            return
        if action == StorageAction.STORE_ITEM and len(fields) >= 3:
            self._store_inventory_item(self._safe_int(fields[1], 0), self._safe_int(fields[2], 0))
        elif action == StorageAction.TAKE_ITEM and len(fields) >= 3:
            self._take_storage_item(self._safe_int(fields[1], 0), self._safe_int(fields[2], 0))
        elif action == StorageAction.MOVE and len(fields) >= 3:
            self._move_storage_item(self._safe_int(fields[1], 0), self._safe_int(fields[2], 0))
        elif action == StorageAction.STORE_MONEY and len(fields) >= 2:
            self._move_storage_money(self._safe_int(fields[1], 0))
        elif action == StorageAction.TAKE_MONEY and len(fields) >= 2:
            self._move_storage_money(-self._safe_int(fields[1], 0))
        elif action == StorageAction.REMOVE_ITEM and len(fields) >= 2:
            self._remove_storage_item(self._safe_int(fields[1], 0))

    def _store_inventory_item(self, bag_slot: int, requested_quantity: int) -> None:
        """Move a bag quantity into the first free or matching storage stack."""
        with self.store.lock:
            source = self.store.state.inventory.get(bag_slot)
            if source is None or bag_slot <= 0:
                return
            source_quantity = _safe_item_quantity(source.item_id, source.quantity)
            requested = requested_quantity if requested_quantity > 0 else source_quantity
            quantity = min(source_quantity, requested)
            if quantity <= 0:
                return
            stack_limit = _item_stack_limit(source.item_id)
            target = next(
                (
                    item for item in self.store.state.storage.values()
                    if self._items_can_stack(item, source)
                    and _safe_item_quantity(item.item_id, item.quantity) < stack_limit
                ),
                None,
            )
            if target is None:
                slot = next(
                    (value for value in range(1, self.store.state.storage_capacity + 1) if value not in self.store.state.storage),
                    0,
                )
                if slot == 0:
                    self._send_system_chat("仓库已满。")
                    return
                target = self._copy_inventory_item(source, slot, quantity)
                self.store.state.storage[slot] = target
            else:
                room = stack_limit - _safe_item_quantity(target.item_id, target.quantity)
                quantity = min(quantity, room)
                if quantity <= 0:
                    return
                target.quantity = _safe_item_quantity(target.item_id, target.quantity) + quantity
            source.quantity -= quantity
            removed = source.quantity == 0
            if removed:
                del self.store.state.inventory[bag_slot]
            self.store.save()
        if removed:
            self._send_inventory_clear(bag_slot, InventoryType.BAG)
        else:
            self._send_inventory_update(source, from_drop=0)
        self.send_text(f"{op(ServerOpcode.OPEN_STORAGE)}:4:{self._encode_item_payload(target)}")
        self._refresh_all_original_quests()

    def _take_storage_item(self, storage_slot: int, requested_quantity: int) -> None:
        """Move a warehouse quantity back into the character bag."""
        with self.store.lock:
            source = self.store.state.storage.get(storage_slot)
            if source is None:
                return
            source_quantity = _safe_item_quantity(source.item_id, source.quantity)
            requested = requested_quantity if requested_quantity > 0 else source_quantity
            quantity = min(source_quantity, requested)
            if quantity <= 0:
                return
            stack_limit = _item_stack_limit(source.item_id)
            can_merge = any(
                item.slot > 0
                and self._items_can_stack(item, source)
                and _safe_item_quantity(item.item_id, item.quantity) < stack_limit
                for item in self.store.state.inventory.values()
            )
            matching_room = max(
                (
                    max(
                        0,
                        stack_limit
                        - _safe_item_quantity(item.item_id, item.quantity),
                    )
                    for item in self.store.state.inventory.values()
                    if item.slot > 0 and self._items_can_stack(item, source)
                ),
                default=0,
            )
            has_free_slot = any(
                slot not in self.store.state.inventory
                for slot in range(1, self.store.state.bag_capacity + 1)
            )
            if not has_free_slot and not GAME_DATA_CATALOG.is_equipment_item(source.item_id):
                # A matching stack is only useful for the amount of room it has.
                # Move that room instead of raising InventoryCapacityError.
                quantity = min(quantity, matching_room)
                if quantity <= 0:
                    self._send_system_chat("背包已满。")
                    return
            if not can_merge and not has_free_slot:
                self._send_system_chat("背包已满。")
                return
            if GAME_DATA_CATALOG.is_equipment_item(source.item_id):
                bag_slot = next(
                    slot
                    for slot in range(1, self.store.state.bag_capacity + 1)
                    if slot not in self.store.state.inventory
                )
                item = self._copy_inventory_item(source, bag_slot, quantity)
                self.store.state.inventory[bag_slot] = item
                created = True
            else:
                item, created = self._add_inventory_item(
                    source.item_id,
                    quantity,
                    can_trade=source.can_trade,
                )
            source.quantity = source_quantity - quantity
            removed = source.quantity == 0
            if removed:
                del self.store.state.storage[storage_slot]
            self.store.save()
        if created:
            self._send_inventory_add(item, from_drop=0)
        else:
            self._send_inventory_update(item, from_drop=0)
        if removed:
            self.send_text(f"{op(ServerOpcode.OPEN_STORAGE)}:5:{storage_slot}")
        else:
            self.send_text(f"{op(ServerOpcode.OPEN_STORAGE)}:4:{self._encode_item_payload(source)}")
        self._refresh_all_original_quests()

    def _move_storage_item(self, source_slot: int, destination_slot: int) -> None:
        """Swap two warehouse slots and send the compact storage position refresh."""
        if source_slot <= 0 or destination_slot <= 0 or source_slot == destination_slot:
            return
        with self.store.lock:
            source = self.store.state.storage.pop(source_slot, None)
            if source is None:
                return
            destination = self.store.state.storage.pop(destination_slot, None)
            source.slot = destination_slot
            self.store.state.storage[destination_slot] = source
            if destination is not None:
                destination.slot = source_slot
                self.store.state.storage[source_slot] = destination
            self.store.save()
        self._send_storage_positions()

    def _move_storage_money(self, amount: int) -> None:
        """Deposit positive gold or withdraw negative gold with balance validation."""
        with self.store.lock:
            if amount > 0:
                moved = min(amount, self.store.state.money)
                self.store.state.money -= moved
                self.store.state.storage_money += moved
            else:
                moved = min(-amount, self.store.state.storage_money)
                self.store.state.storage_money -= moved
                self.store.state.money += moved
            self.store.save()
        self.send_text(
            f"{op(ServerOpcode.OPEN_STORAGE)}:3:{self.store.state.storage_capacity}:"
            f"{self.store.state.storage_money}"
        )
        self._send_stats({StatType.MONEY: self.store.state.money})

    def _remove_storage_item(self, slot: int) -> None:
        """Discard one item stack directly from the local warehouse."""
        with self.store.lock:
            if self.store.state.storage.pop(slot, None) is None:
                return
            self.store.save()
        self.send_text(f"{op(ServerOpcode.OPEN_STORAGE)}:5:{slot}")

    def _send_storage_positions(self) -> None:
        """Refresh warehouse positions using ItemSortInfo.decode2 field order."""
        encoded = "@".join(
            f"{item.item_id}&{item.slot}&{_safe_item_quantity(item.item_id, item.quantity)}&{item.unique_id}"
            for item in sorted(self.store.state.storage.values(), key=lambda value: value.slot)
        ) or "-"
        self.send_text(
            f"{op(ServerOpcode.OPEN_STORAGE)}:6:{self.store.state.storage_capacity}:"
            f"{self.store.state.storage_money}:{encoded}"
        )

    @staticmethod
    def _copy_inventory_item(source: InventoryItem, slot: int, quantity: int) -> InventoryItem:
        """Copy one item instance while assigning a container-local slot and quantity."""
        values = asdict(source)
        values.update({
            "slot": slot,
            "quantity": _safe_item_quantity(source.item_id, quantity),
        })
        return InventoryItem(**values)

    def _resolve_talk_npc(self, read_str: str) -> NpcState | None:
        """Resolve object/template IDs while retaining the active NPC for continue packets."""
        fields = read_str.split(":") if read_str else []
        if fields and fields[0].isdigit():
            fields = fields[1:]
        if fields and fields[-1].isdigit() and len(fields[-1]) >= 10:
            fields = fields[:-1]
        for field in fields:
            candidate = self._safe_int(field, -1)
            if candidate in self.npcs:
                return self.npcs[candidate]
        for field in fields:
            candidate = self._safe_int(field, -1)
            match = next((npc for npc in self.npcs.values() if npc.template_id == candidate), None)
            if match is not None:
                return match
        if self.active_npc_object_id in self.npcs:
            return self.npcs[self.active_npc_object_id]
        return min(
            self.npcs.values(),
            key=lambda npc: (npc.x - self.x) ** 2 + (npc.y - self.y) ** 2,
            default=None,
        )

    def _handle_original_quest_npc(
        self,
        npc: NpcState,
        include_automatic: bool = False,
        selected_quest_id: int | None = None,
    ) -> bool:
        """Advance, turn in, accept, or report an original quest related to one NPC."""
        if npc.template_id == 27 and selected_quest_id == 8001:
            return self._start_ring_quest("daily")
        if npc.template_id == 27 and selected_quest_id == 8002:
            return self._start_ring_quest("weekly")
        escort_definition = GAME_DATA_CATALOG.get_quest_definition(8100)
        escort_start_npc_id = (
            escort_definition.start_npc_id if escort_definition is not None else 23
        )
        escort_end_npc_id = (
            escort_definition.end_npc_id if escort_definition is not None else 75
        )
        if npc.template_id == escort_start_npc_id and selected_quest_id == 8100:
            self._send_mixin_state()
            return True
        if npc.template_id == escort_end_npc_id and selected_quest_id == 8100:
            escort = self.store.state.original_quests.get(8100)
            if escort is not None and QuestState(escort.state) == QuestState.READY_TO_COMPLETE:
                if self.wire_mode == "original":
                    self._send_mixin_state()
                self._send_original_quest_full_progress(
                    escort_definition,
                    escort,
                    flash_status=2,
                )
            else:
                self._mark_mixin_escort_ready()
            return True
        definitions = list(GAME_DATA_CATALOG.quests_for_npc(npc.template_id))
        if include_automatic:
            definitions.extend(
                definition
                for quest_id in GAME_DATA_CATALOG.quest_ids
                if (definition := GAME_DATA_CATALOG.get_quest_definition(quest_id)) is not None
                and definition.supported
                and definition.start_npc_id == 0
            )
        definitions = list({definition.quest_id: definition for definition in definitions}.values())
        if selected_quest_id is not None:
            definitions = [
                definition
                for definition in definitions
                if definition.quest_id == selected_quest_id
            ]

        # Completion has priority, but rewards are not granted until the player confirms
        # every authored receiver line.
        for definition in definitions:
            progress = self.store.state.original_quests.get(definition.quest_id)
            if (
                progress is not None
                and QuestState(progress.state) == QuestState.READY_TO_COMPLETE
                and definition.end_npc_id == npc.template_id
            ):
                self._begin_original_quest_dialog(
                    definition,
                    npc,
                    "complete",
                    definition.complete_dialogues,
                )
                return True

        for definition in definitions:
            progress = self.store.state.original_quests.get(definition.quest_id)
            if progress is None or QuestState(progress.state) != QuestState.ACTIVE:
                continue
            matching = [
                objective
                for objective in definition.objectives
                if objective.kind == QuestObjectiveKind.NPC
                and objective.target_id == npc.template_id
            ]
            if matching:
                self._begin_original_quest_dialog(
                    definition,
                    npc,
                    "npc_complete",
                    definition.complete_dialogues,
                )
                return True

        for definition in definitions:
            if not self._can_start_original_quest(definition):
                continue
            if definition.start_npc_id not in (npc.template_id, 0 if include_automatic else -1):
                continue
            self._begin_original_quest_dialog(
                definition,
                npc,
                "start",
                definition.start_dialogues,
            )
            return True

        for definition in definitions:
            progress = self.store.state.original_quests.get(definition.quest_id)
            if progress is None or QuestState(progress.state) != QuestState.ACTIVE:
                continue
            if definition.end_npc_id != npc.template_id:
                continue
            self._send_npc_dialog(
                self._original_quest_incomplete_npc_text(definition, progress) or npc.dialogue,
                npc.template_id,
                player_text=self._original_quest_incomplete_reply(definition, progress),
            )
            return True
        return False

    def _refresh_ring_quest_periods(self) -> None:
        """Reset daily and ISO-week counters only when their authored period changes."""
        today = date.today()
        iso_year, iso_week, _ = today.isocalendar()
        day_key = today.isoformat()
        week_key = f"{iso_year}-W{iso_week:02d}"
        changed = False
        with self.store.lock:
            state = self.store.state
            if state.ring_daily_day_key != day_key:
                state.ring_daily_day_key = day_key
                state.ring_daily_count = 0
                changed = True
            if state.ring_week_key != week_key:
                state.ring_week_key = week_key
                state.ring_weekly_count = 0
                changed = True
            active_ring_ids = [
                quest_id
                for quest_id, progress in state.original_quests.items()
                if 8003 <= quest_id <= 8022
                and QuestState(progress.state)
                in (QuestState.ACTIVE, QuestState.READY_TO_COMPLETE)
            ]
            normalized_modes = {
                quest_id: mode
                for quest_id, mode in state.ring_quest_modes.items()
                if quest_id in active_ring_ids and mode in {"daily", "weekly"}
            }
            if normalized_modes != state.ring_quest_modes:
                state.ring_quest_modes = normalized_modes
                changed = True
            # Upgrade the former one-slot save without discarding its unfinished
            # ring quest.
            unowned_ring_ids = [
                quest_id
                for quest_id in active_ring_ids
                if quest_id not in state.ring_quest_modes
            ]
            used_modes = set(state.ring_quest_modes.values())
            for quest_id in unowned_ring_ids:
                preferred_mode = (
                    state.ring_active_mode
                    if state.ring_active_mode in {"daily", "weekly"}
                    and state.ring_active_mode not in used_modes
                    else "daily" if "daily" not in used_modes else "weekly"
                )
                if preferred_mode in used_modes:
                    break
                state.ring_quest_modes[quest_id] = preferred_mode
                used_modes.add(preferred_mode)
                changed = True
            if changed:
                self.store.save()

    def _ring_mode_for_quest_id(self, quest_id: int) -> str:
        """Return the independent daily/weekly owner of one active template."""
        mode = self.store.state.ring_quest_modes.get(int(quest_id), "")
        return mode if mode in {"daily", "weekly"} else ""

    def _ring_definition_candidates(self) -> tuple[OriginalQuestDefinition, ...]:
        """Return the nearest five authored level bands suitable for rotation."""
        candidates = [
            definition
            for quest_id in range(8003, 8023)
            if (definition := GAME_DATA_CATALOG.get_quest_definition(quest_id))
            is not None
            and self.character.level >= definition.min_level
        ]
        candidates.sort(key=lambda definition: (definition.min_level, definition.quest_id))
        return tuple(candidates[-5:])

    def _choose_ring_definition(
        self,
        *,
        previous_quest_id: int = 0,
    ) -> OriginalQuestDefinition | None:
        """Choose a non-repeating target without colliding with the other ring."""
        candidates = self._ring_definition_candidates()
        if not candidates:
            return None
        occupied = {
            quest_id
            for quest_id, mode in self.store.state.ring_quest_modes.items()
            if mode in {"daily", "weekly"}
        }
        available = [
            definition
            for definition in candidates
            if definition.quest_id not in occupied
            and definition.quest_id != previous_quest_id
        ]
        if not available:
            available = [
                definition
                for definition in candidates
                if definition.quest_id not in occupied
            ]
        return self.random.choice(available) if available else None

    def _start_daily_ring_quest(self) -> bool:
        """Compatibility wrapper for tests and older internal callers."""
        return self._start_ring_quest("daily")

    def _start_ring_quest(self, mode: str) -> bool:
        """Start one authored level-band daily or weekly Fugaku ring quest."""
        if mode not in {"daily", "weekly"}:
            return False
        if mode == "weekly" and self.character.level < 35:
            self._send_native_server_message("达到35级后才能领取周试炼任务。", 16)
            return True
        self._refresh_ring_quest_periods()
        if self._active_ring_template_id(mode):
            self._send_native_server_message("当前环任务尚未完成。", 16)
            return True
        definition = self._choose_ring_definition()
        if definition is None:
            self._send_native_server_message("当前等级没有可用的环任务。", 16)
            return True
        maximum = 20 if mode == "daily" else 100
        finish_count = (
            self.store.state.ring_daily_count
            if mode == "daily"
            else self.store.state.ring_weekly_count
        )
        if finish_count >= maximum:
            period_name = "今日二十环" if mode == "daily" else "本周一百环"
            self._send_native_server_message(f"{period_name}任务已经全部完成。", 16)
            return True
        with self.store.lock:
            progress = OriginalQuestProgress(
                state=int(QuestState.ACTIVE),
                finish_count=finish_count,
            )
            self.store.state.original_quests[definition.quest_id] = progress
            self.store.state.ring_quest_modes[definition.quest_id] = mode
            self.store.state.ring_active_mode = mode
            self._refresh_original_quest_progress(definition, progress)
            self.store.save()
        self._send_original_quest_started_notification(definition.quest_id)
        # SHOW_STATUS_INFO creates the static 8001/8002 wrapper and opens its
        # native ring window.  Mutate that exact QuestInfoData instance with
        # the selected level-band objective instead of replacing the started
        # list: replacing it leaves the already-open window bound to stale or
        # empty data while the tracker points at the new objective.
        self._send_original_quest_full_progress(definition, progress)
        self._send_original_can_start_quest_list()
        self._send_npc_quest_status()
        return True

    def _active_ring_template_id(self, mode: str | None = None) -> int:
        """Return one active objective template, optionally scoped by ring type."""
        return next(
            (
                quest_id
                for quest_id, progress in self.store.state.original_quests.items()
                if 8003 <= quest_id <= 8022
                and (mode is None or self._ring_mode_for_quest_id(quest_id) == mode)
                and QuestState(progress.state)
                in (QuestState.ACTIVE, QuestState.READY_TO_COMPLETE)
            ),
            0,
        )

    def _client_original_quest_id(self, quest_id: int) -> int:
        """Expose ring objective templates through their original UI wrapper IDs."""
        if 8003 <= quest_id <= 8022:
            mode = self._ring_mode_for_quest_id(quest_id)
            if mode == "daily":
                return 8001
            if mode == "weekly":
                return 8002
        return quest_id

    def _original_quest_incomplete_npc_text(
        self,
        definition: OriginalQuestDefinition,
        progress: OriginalQuestProgress,
    ) -> str:
        """Select the original stop line for the first unfinished objective, if authored."""
        for objective in definition.objectives:
            if progress.progress.get(objective.progress_key, 0) >= objective.count:
                continue
            for kind, index, dialogue in definition.incomplete_dialogues:
                if kind == objective.kind.value and index == objective.index:
                    return dialogue
        return ""

    def _original_quest_incomplete_reply(
        self,
        definition: OriginalQuestDefinition,
        progress: OriginalQuestProgress,
    ) -> str:
        """Create a natural player reply when GameData has no authored stop response."""
        objective = next(
            (
                candidate
                for candidate in definition.objectives
                if progress.progress.get(candidate.progress_key, 0) < candidate.count
            ),
            None,
        )
        if objective is None:
            return f"《{definition.name}》已经完成了。"
        if objective.kind == QuestObjectiveKind.PET:
            return f"我还没有捕捉到{GAME_DATA_CATALOG.get_pet_name(objective.target_id)}。"
        if objective.kind == QuestObjectiveKind.MONSTER:
            monster = GAME_DATA_CATALOG.get_monster_definition(objective.target_id)
            return f"我还没有击败{monster.name}。"
        if objective.kind in {
            QuestObjectiveKind.ITEM,
            QuestObjectiveKind.EQUIPMENT,
            QuestObjectiveKind.USE_ITEM,
        }:
            item = GAME_DATA_CATALOG.get_item_definition(objective.target_id)
            item_name = item.name if item is not None else "需要的物品"
            return f"我还没有准备好{item_name}。"
        if objective.kind == QuestObjectiveKind.NPC:
            npc_name = GAME_DATA_CATALOG.npc_strings.get(objective.target_id, ("那个人", ""))[0]
            return f"我还没有见到{npc_name}。"
        if objective.kind == QuestObjectiveKind.LEVEL:
            return "我的修行还不够。"
        return f"《{definition.name}》还没有完成。"

    def _begin_original_quest_dialog(
        self,
        definition: OriginalQuestDefinition,
        npc: NpcState,
        action: str,
        lines: tuple[str, ...],
    ) -> None:
        """Start an authored quest conversation and defer its state change to the last reply."""
        self.active_quest_dialog_id = definition.quest_id
        self.active_quest_dialog_action = action
        self.active_quest_dialog_lines = lines
        self.active_quest_dialog_index = 0
        if lines:
            self._send_authored_quest_dialog(lines[0], npc.template_id)
            return
        self._finish_original_quest_dialog(npc)

    def _continue_original_quest_dialog(self, npc: NpcState) -> None:
        """Advance one authored line or apply the deferred quest transition."""
        if self.active_quest_dialog_id is None:
            return
        self.active_quest_dialog_index += 1
        if self.active_quest_dialog_index < len(self.active_quest_dialog_lines):
            self._send_authored_quest_dialog(
                self.active_quest_dialog_lines[self.active_quest_dialog_index],
                npc.template_id,
            )
            return
        self._finish_original_quest_dialog(npc)

    def _finish_original_quest_dialog(self, npc: NpcState) -> None:
        """Apply the accept, dialogue objective, or turn-in associated with a conversation."""
        quest_id = self.active_quest_dialog_id
        action = self.active_quest_dialog_action
        self._clear_active_quest_dialog()
        if quest_id is None or action is None:
            return
        definition = GAME_DATA_CATALOG.get_quest_definition(quest_id)
        if definition is None:
            return
        progress = self.store.state.original_quests.get(quest_id)
        if action == "start":
            if self._can_start_original_quest(definition) and definition.start_npc_id in (
                npc.template_id,
                0 if npc.object_id == self.QUEST_NPC_OBJECT_ID else -1,
            ):
                self._start_original_quest(definition)
            return
        if action == "npc_complete":
            if progress is None or QuestState(progress.state) != QuestState.ACTIVE:
                return
            self._advance_original_quest(
                definition,
                QuestObjectiveKind.NPC,
                npc.template_id,
                amount=1,
            )
            progress = self.store.state.original_quests.get(quest_id)
        if (
            progress is not None
            and QuestState(progress.state) == QuestState.READY_TO_COMPLETE
            and definition.end_npc_id == npc.template_id
        ):
            self._complete_original_quest(
                definition,
                npc.template_id,
                show_dialog=False,
            )

    def _clear_active_quest_dialog(self) -> None:
        """Discard transient dialogue state without changing persisted quest progress."""
        self.active_quest_dialog_id = None
        self.active_quest_dialog_action = None
        self.active_quest_dialog_lines = ()
        self.active_quest_dialog_index = 0

    def _can_start_original_quest(self, definition: OriginalQuestDefinition) -> bool:
        """Check supported type, level range, save state, and completed prerequisites."""
        if definition.quest_id == 8101:
            self._refresh_family_quest_period()
            if (
                self._current_family() is None
                or self.store.state.progression.family_quest_count >= 5
            ):
                return False
        if not definition.supported or self.character.level < definition.min_level:
            return False
        if definition.max_level and self.character.level > definition.max_level:
            return False
        progress = self.store.state.original_quests.get(definition.quest_id)
        if progress is not None and QuestState(progress.state) != QuestState.NOT_STARTED:
            return False
        return all(
            QuestState(required.state) == QuestState.COMPLETED
            for quest_id in definition.prerequisite_ids
            if (required := self.store.state.original_quests.get(quest_id)) is not None
        ) and all(
            quest_id in self.store.state.original_quests
            for quest_id in definition.prerequisite_ids
        )

    def _start_original_quest(self, definition: OriginalQuestDefinition) -> None:
        """Create active progress, then publish the native accepted-quest notification."""
        with self.store.lock:
            progress = OriginalQuestProgress(state=int(QuestState.ACTIVE))
            self.store.state.original_quests[definition.quest_id] = progress
            self._refresh_original_quest_progress(definition, progress)
            self.store.save()
        self._send_original_quest_lists()
        self._send_original_quest_started_notification(definition.quest_id)
        self._send_npc_quest_status()

    def _start_automatic_original_quests(self) -> list[int]:
        """Persist every currently eligible quest that has no authored starting NPC."""
        started: list[tuple[OriginalQuestDefinition, OriginalQuestProgress]] = []
        with self.store.lock:
            for quest_id in GAME_DATA_CATALOG.quest_ids:
                definition = GAME_DATA_CATALOG.get_quest_definition(quest_id)
                if (
                    definition is None
                    or definition.start_npc_id != 0
                    or not self._can_start_original_quest(definition)
                ):
                    continue
                progress = OriginalQuestProgress(state=int(QuestState.ACTIVE))
                self.store.state.original_quests[definition.quest_id] = progress
                self._refresh_original_quest_progress(definition, progress)
                started.append((definition, progress))
            if started:
                self.store.save()
        return [definition.quest_id for definition, _ in started]

    def _send_original_quest_started_notification(self, quest_id: int) -> None:
        """Trigger the client's native accept tip after its quest list contains the quest."""
        client_quest_id = self._client_original_quest_id(quest_id)
        self.send_text(
            f"{op(ServerOpcode.SHOW_STATUS_INFO)}:1:{client_quest_id}:1:0"
        )

    def _send_original_quest_completion_notification(self, quest_id: int) -> None:
        """Trigger the native completion tip, which starts navigation to the turn-in NPC."""
        self.send_text(
            f"{op(ServerOpcode.SHOW_QUEST_COMPLETION)}:"
            f"{self._client_original_quest_id(quest_id)}"
        )

    def _refresh_original_quest_progress(
        self,
        definition: OriginalQuestDefinition,
        progress: OriginalQuestProgress,
    ) -> None:
        """Refresh level and inventory-derived conditions and promote completed objectives."""
        if definition.quest_id == 8100:
            return
        for objective in definition.objectives:
            if objective.kind == QuestObjectiveKind.LEVEL:
                progress.progress[objective.progress_key] = self.character.level
            elif objective.kind in (QuestObjectiveKind.ITEM, QuestObjectiveKind.EQUIPMENT):
                progress.progress[objective.progress_key] = sum(
                    item.quantity
                    for item in self.store.state.inventory.values()
                    if item.item_id == objective.target_id
                )
            else:
                progress.progress.setdefault(objective.progress_key, 0)
        if QuestState(progress.state) == QuestState.ACTIVE and all(
            progress.progress.get(objective.progress_key, 0)
            >= self._quest_objective_count(definition, progress, objective)
            for objective in definition.objectives
        ):
            progress.state = int(QuestState.READY_TO_COMPLETE)

    @staticmethod
    def _quest_objective_count(
        definition: OriginalQuestDefinition,
        progress: OriginalQuestProgress,
        objective: QuestObjective,
    ) -> int:
        """Apply the native 1-5 difficulty level to loop-task requirements."""
        if definition.quest_type != "loop":
            return objective.count
        difficulty = max(1, min(5, progress.difficulty_level))
        return max(1, (objective.count * (5 + difficulty) + 9) // 10)

    def _advance_original_quest(
        self,
        definition: OriginalQuestDefinition,
        kind: QuestObjectiveKind,
        target_id: int,
        amount: int,
        map_id: int = 0,
    ) -> bool:
        """Increment matching active objectives and send Flash-compatible progress updates."""
        progress = self.store.state.original_quests.get(definition.quest_id)
        if progress is None or QuestState(progress.state) != QuestState.ACTIVE:
            return False
        changed: list[QuestObjective] = []
        with self.store.lock:
            for objective in definition.objectives:
                if objective.kind != kind or objective.target_id != target_id:
                    continue
                if objective.map_id and map_id and objective.map_id != map_id:
                    continue
                current = progress.progress.get(objective.progress_key, 0)
                next_value = min(
                    self._quest_objective_count(definition, progress, objective),
                    current + max(0, amount),
                )
                if next_value != current:
                    progress.progress[objective.progress_key] = next_value
                    changed.append(objective)
            if not changed:
                return False
            self._refresh_original_quest_progress(definition, progress)
            self.store.save()
        changed_kinds = tuple(dict.fromkeys(objective.kind for objective in changed))
        # Captured Nya traffic publishes the updated objective while the quest is
        # still active, then publishes status 2 when that update completes it.
        self._send_original_quest_full_progress(
            definition,
            progress,
            flash_status=1,
            kinds=changed_kinds,
        )
        if QuestState(progress.state) == QuestState.READY_TO_COMPLETE:
            self._send_original_quest_full_progress(
                definition,
                progress,
                flash_status=2,
            )
            self._send_original_quest_completion_notification(definition.quest_id)
        self._send_npc_quest_status()
        return True

    def _advance_original_quests(
        self,
        kind: QuestObjectiveKind,
        target_id: int,
        amount: int = 1,
        map_id: int = 0,
    ) -> None:
        """Advance every active original quest matching one gameplay event."""
        for quest_id in tuple(self.store.state.original_quests):
            definition = GAME_DATA_CATALOG.get_quest_definition(quest_id)
            if definition is not None:
                self._advance_original_quest(definition, kind, target_id, amount, map_id)

    def _refresh_all_original_quests(self) -> None:
        """Refresh inventory/level-derived conditions after item, equipment, or level changes."""
        changed: list[
            tuple[OriginalQuestDefinition, OriginalQuestProgress, QuestState]
        ] = []
        with self.store.lock:
            for quest_id, progress in self.store.state.original_quests.items():
                if QuestState(progress.state) != QuestState.ACTIVE:
                    continue
                definition = GAME_DATA_CATALOG.get_quest_definition(quest_id)
                if definition is None:
                    continue
                before = (progress.state, dict(progress.progress))
                self._refresh_original_quest_progress(definition, progress)
                if before != (progress.state, progress.progress):
                    changed.append((definition, progress, QuestState(before[0])))
            if changed:
                self.store.save()
        for definition, progress, previous_state in changed:
            self._send_original_quest_full_progress(
                definition,
                progress,
                flash_status=1 if previous_state == QuestState.ACTIVE else None,
            )
            if QuestState(progress.state) == QuestState.READY_TO_COMPLETE:
                self._send_original_quest_full_progress(
                    definition,
                    progress,
                    flash_status=2,
                )
                self._send_original_quest_completion_notification(definition.quest_id)
        if changed:
            self._send_npc_quest_status()

    def _complete_original_quest(
        self,
        definition: OriginalQuestDefinition,
        npc_template_id: int,
        show_dialog: bool = True,
    ) -> None:
        """Consume delivery items, grant original rewards once, and unlock successor quests."""
        if npc_template_id != definition.end_npc_id:
            return
        progress = self.store.state.original_quests.get(definition.quest_id)
        if progress is None or QuestState(progress.state) != QuestState.READY_TO_COMPLETE:
            return
        ring_mode = self._ring_mode_for_quest_id(definition.quest_id)
        is_ring_quest = bool(ring_mode)
        is_family_quest = definition.quest_id == 8101
        if is_family_quest:
            self._refresh_family_quest_period()
        reward_multiplier = (
            max(1, min(5, progress.rich_degree)) if is_ring_quest else 1
        )
        reward_specs = [
            (reward.item_id, reward.count * reward_multiplier)
            for reward in definition.item_rewards
            if reward.job in (0, self.character.job)
        ]
        if not self._has_inventory_capacity(reward_specs):
            self._send_system_chat("背包空间不足，无法领取任务奖励。")
            return
        if is_ring_quest:
            self._refresh_ring_quest_periods()
        inventory_updates: list[tuple[InventoryItem, bool]] = []
        reward_updates: list[tuple[InventoryItem, bool]] = []
        next_ring_quest_id = 0
        family_run = min(self.store.state.progression.family_quest_count + 1, 5)
        family_gold = (
            max(1_000, self.character.level * 500) * family_run
            if is_family_quest
            else 0
        )
        family_experience = (
            max(1_000, self.character.level * 1_000) * family_run
            if is_family_quest
            else 0
        )
        family_contribution = (
            max(10, self.character.level // 2) * family_run
            if is_family_quest
            else 0
        )
        with self.store.lock:
            for objective in definition.objectives:
                if objective.kind not in (QuestObjectiveKind.ITEM, QuestObjectiveKind.EQUIPMENT):
                    continue
                remaining = objective.count
                for slot, item in list(self.store.state.inventory.items()):
                    if item.item_id != objective.target_id or remaining <= 0:
                        continue
                    removed_count = min(item.quantity, remaining)
                    item.quantity -= removed_count
                    remaining -= removed_count
                    removed = item.quantity == 0
                    if removed:
                        del self.store.state.inventory[slot]
                    inventory_updates.append((item, removed))
            progress.state = int(QuestState.COMPLETED)
            if is_family_quest:
                progression = self.store.state.progression
                progression.family_quest_count = family_run
                progression.family_contribution += family_contribution
                progression.family_weekly_contribution += family_contribution
                progress.finish_count = family_run
                if family_run < 5:
                    progress.state = int(QuestState.NOT_STARTED)
                    progress.progress.clear()
            elif is_ring_quest and ring_mode == "daily":
                self.store.state.ring_daily_count = min(
                    20, self.store.state.ring_daily_count + 1
                )
                progress.finish_count = self.store.state.ring_daily_count
            elif is_ring_quest and ring_mode == "weekly":
                self.store.state.ring_weekly_count = min(
                    100, self.store.state.ring_weekly_count + 1
                )
                progress.finish_count = self.store.state.ring_weekly_count
            else:
                progress.finish_count += 1
            if is_ring_quest and ring_mode:
                finish_count = (
                    self.store.state.ring_daily_count
                    if ring_mode == "daily"
                    else self.store.state.ring_weekly_count
                )
                maximum = 20 if ring_mode == "daily" else 100
                self.store.state.ring_quest_modes.pop(definition.quest_id, None)
                if finish_count < maximum:
                    next_definition = self._choose_ring_definition(
                        previous_quest_id=definition.quest_id,
                    )
                    if next_definition is None:
                        next_definition = definition
                    next_progress = OriginalQuestProgress(
                        state=int(QuestState.ACTIVE),
                        finish_count=finish_count,
                    )
                    self.store.state.original_quests[next_definition.quest_id] = next_progress
                    self.store.state.ring_quest_modes[next_definition.quest_id] = ring_mode
                    self.store.state.ring_active_mode = ring_mode
                    self._refresh_original_quest_progress(next_definition, next_progress)
                    next_ring_quest_id = next_definition.quest_id
                elif not self.store.state.ring_quest_modes:
                    self.store.state.ring_active_mode = ""
            self.store.state.money += (
                definition.reward_money * reward_multiplier + family_gold
            )
            self._add_zq(definition.reward_zq * reward_multiplier)
            for item_id, count in reward_specs:
                reward_updates.append(self._add_inventory_item(item_id, count))
            self.store.save()
        for item, removed in inventory_updates:
            inventory_type = InventoryType.BAG if item.slot > 0 else InventoryType.EQUIPPED
            if removed:
                self._send_inventory_clear(item.slot, inventory_type)
            else:
                self._send_inventory_update(item, from_drop=0)
        for item, created in reward_updates:
            if created:
                self._send_inventory_add(item, from_drop=0)
            else:
                self._send_inventory_update(item, from_drop=0)
        self._grant_experience(
            definition.reward_exp * reward_multiplier + family_experience
        )
        updates = {StatType.MONEY: self.store.state.money, StatType.ZQ: self.character.zq}
        self._send_stats(updates)
        if is_family_quest:
            self.send_text(
                f"{op(ServerOpcode.BANGHUI)}:20:"
                f"{self.store.state.progression.family_contribution}"
            )
            self._send_system_chat(
                f"家族任务完成，本次获得金币{family_gold}、经验{family_experience}、"
                f"家族贡献{family_contribution}。"
            )
        newly_started_quests = self._start_automatic_original_quests()
        if next_ring_quest_id:
            # SHOW_STATUS_INFO creates the native 8001/8002 wrapper and binds the
            # already-open ring window to that QuestInfoData instance.  Updating
            # it in place keeps the window and tracker on the same rotated target.
            # Sending STARTED_LIST here would rebuild the tracker with a different
            # instance and leave the open window displaying the previous target.
            self._send_original_quest_started_notification(next_ring_quest_id)
            next_definition = GAME_DATA_CATALOG.get_quest_definition(
                next_ring_quest_id
            )
            next_progress = self.store.state.original_quests.get(next_ring_quest_id)
            if next_definition is not None and next_progress is not None:
                self._send_original_quest_full_progress(
                    next_definition,
                    next_progress,
                )
            self._send_original_can_start_quest_list()
        else:
            self._send_original_quest_lists()
        for quest_id in newly_started_quests:
            self._send_original_quest_started_notification(quest_id)
        self._send_npc_quest_status()
        self._trigger_editor_events("完成任务", {"quest_id": definition.quest_id})
        if definition.quest_id == 1003:
            self._send_tutorial_once("quest-search-npc:1003", BeginUiEffect.SEARCH_NPC)

    def _original_quest_progress_summary(
        self,
        definition: OriginalQuestDefinition,
        progress: OriginalQuestProgress,
    ) -> str:
        """Build a concise readable fallback when authored stop dialogue is absent."""
        return "，".join(
            f"{objective.kind.value}:{progress.progress.get(objective.progress_key, 0)}/"
            f"{self._quest_objective_count(definition, progress, objective)}"
            for objective in definition.objectives
        )

    def _original_quest_progress_data(
        self,
        definition: OriginalQuestDefinition,
        progress: OriginalQuestProgress,
        kinds: tuple[QuestObjectiveKind, ...] | None = None,
    ) -> dict[str, Any]:
        """Build the nested AMF object used by the captured Nya quest packets."""
        selected_kinds = kinds or tuple(
            dict.fromkeys(objective.kind for objective in definition.objectives)
        )
        data: dict[str, Any] = {}
        for kind in selected_kinds:
            related = [
                objective
                for objective in definition.objectives
                if objective.kind == kind
            ]
            if kind == QuestObjectiveKind.LEVEL:
                maximum_index = max((objective.index for objective in related), default=0)
                values = [0] * (maximum_index + 1)
                for objective in related:
                    values[objective.index] = progress.progress.get(
                        objective.progress_key, 0
                    )
                data[kind.value] = values
                continue
            data[kind.value] = {
                objective.progress_key: {
                    "curr": progress.progress.get(objective.progress_key, 0),
                    "count": self._quest_objective_count(
                        definition, progress, objective
                    ),
                }
                for objective in related
            }
        return data

    def _original_quest_loop_fields(
        self,
        definition: OriginalQuestDefinition,
        progress: OriginalQuestProgress,
    ) -> tuple[int, dict[str, Any] | None]:
        """Return the loop counter and dynamic payload required by QuestStatusInfo."""
        if definition.quest_id == 8101 or definition.quest_type == "banghui":
            run = min(self.store.state.progression.family_quest_count + 1, 5)
            family_money = max(10, self.character.level // 2) * run
            gold = max(1_000, self.character.level * 500) * run
            experience = max(1_000, self.character.level * 1_000) * run
            objective = definition.objectives[0]
            return run, {
                "check": {
                    objective.kind.value: objective.count,
                    "info": {"level": run},
                },
                "act": {
                    "info": {"level": run},
                    "exp": experience,
                    "money": gold,
                    "bang_money": family_money,
                },
                "actEx": {},
                "npc": definition.end_npc_id,
            }
        if definition.quest_type == "loop":
            maximum = (
                100
                if self._ring_mode_for_quest_id(definition.quest_id) == "weekly"
                else 20
            )
            check: dict[str, Any] = {
                "info": {"level": max(1, min(5, progress.difficulty_level))}
            }
            for objective in definition.objectives:
                if objective.kind == QuestObjectiveKind.LEVEL:
                    check[objective.kind.value] = objective.count
                    continue
                group = check.setdefault(objective.kind.value, {})
                row = {
                    "id": objective.target_id,
                    "count": self._quest_objective_count(
                        definition, progress, objective
                    ),
                }
                if objective.map_id:
                    row["map"] = objective.map_id
                if objective.source_monster_id:
                    row["mob"] = objective.source_monster_id
                if objective.turn_in_npc_id:
                    row["npc"] = objective.turn_in_npc_id
                group[str(objective.index)] = row
            multiplier = max(1, min(5, progress.rich_degree))
            act: dict[str, Any] = {
                "info": {"level": multiplier},
                "exp": definition.reward_exp * multiplier,
                "money": definition.reward_money * multiplier,
                "zq": definition.reward_zq * multiplier,
            }
            rewards = [
                reward
                for reward in definition.item_rewards
                if reward.job in (0, self.character.job)
            ]
            if rewards:
                act["item"] = {
                    str(index): {
                        "id": reward.item_id,
                        "count": reward.count * multiplier,
                        "job": reward.job,
                    }
                    for index, reward in enumerate(rewards)
                }
            return min(progress.finish_count + 1, maximum), {
                "check": check,
                "act": act,
                "actEx": {},
                "npc": definition.end_npc_id,
                "daily_cooldown": {
                    "remain_seconds": max(
                        0, progress.refresh_available_at - int(time.time())
                    )
                },
            }
        if definition.quest_id == 8100 or definition.quest_type == "mixin":
            return min(progress.finish_count + 1, 3), self._mixin_dynamic_data(progress)
        return 0, None

    def _send_original_quest_single_progress(
        self,
        definition: OriginalQuestDefinition,
        progress: OriginalQuestProgress,
        objective: QuestObjective,
    ) -> None:
        """Send action 1 using QuestProcessor.actionSingleProgressUpdate field order."""
        current = progress.progress.get(objective.progress_key, 0)
        data = (
            f"{objective.progress_key}&{current}&"
            f"{self._quest_objective_count(definition, progress, objective)}"
        )
        self.send_text(
            f"{op(ServerOpcode.QUEST_INFO_UPDATE)}:"
            f"{op(QuestListUpdateAction.SINGLE_PROGRESS)}:"
            f"{self._client_original_quest_id(definition.quest_id)}:"
            f"{objective.index}:{objective.kind.value}:{data}"
        )

    def _send_original_quest_full_progress(
        self,
        definition: OriginalQuestDefinition,
        progress: OriginalQuestProgress,
        flash_status: int | None = None,
        kinds: tuple[QuestObjectiveKind, ...] | None = None,
    ) -> None:
        """Send action 2 with the exact nested object observed in Nya captures."""
        if flash_status is None:
            flash_status = (
                2
                if QuestState(progress.state) == QuestState.READY_TO_COMPLETE
                else 1
            )
        selected_kinds = kinds or tuple(
            dict.fromkeys(objective.kind for objective in definition.objectives)
        )
        if self.wire_mode == "original":
            client_quest_id = self._client_original_quest_id(definition.quest_id)
            body = bytearray(
                struct.pack(
                    "<BiB",
                    op(QuestListUpdateAction.ALL_PROGRESS),
                    client_quest_id,
                    flash_status,
                )
            )
            body.extend(
                build_original_object_buffer(
                    self._original_quest_progress_data(
                        definition,
                        progress,
                        selected_kinds,
                    )
                )
            )
            loop_id, dynamic_data = self._original_quest_loop_fields(
                definition, progress
            )
            body.extend(struct.pack("<h", loop_id))
            if loop_id > 0:
                body.extend(build_original_object_buffer(dynamic_data or {}))
                body.extend(struct.pack("<h", progress.finish_count))
            self.send_original_packet(ServerOpcode.QUEST_INFO_UPDATE, bytes(body))
            return
        for kind in selected_kinds:
            related = [objective for objective in definition.objectives if objective.kind == kind]
            data = "@".join(
                f"{objective.progress_key}&{progress.progress.get(objective.progress_key, 0)}&"
                f"{self._quest_objective_count(definition, progress, objective)}"
                for objective in related
            ) or "-"
            self.send_text(
                f"{op(ServerOpcode.QUEST_INFO_UPDATE)}:"
                f"{op(QuestListUpdateAction.ALL_PROGRESS)}:"
                f"{self._client_original_quest_id(definition.quest_id)}:"
                f"{flash_status}:{kind.value}:{data}:0"
            )

    def _encode_original_quest_status(
        self,
        definition: OriginalQuestDefinition,
        progress: OriginalQuestProgress,
    ) -> str:
        """Encode one QuestStatusInfo.decode1 entry for the started quest list."""
        kind = definition.objectives[0].kind
        related = [objective for objective in definition.objectives if objective.kind == kind]
        data = "!".join(
            f"{objective.progress_key}+{progress.progress.get(objective.progress_key, 0)}+"
            f"{self._quest_objective_count(definition, progress, objective)}"
            for objective in related
        ) or "-"
        flash_status = 2 if QuestState(progress.state) == QuestState.READY_TO_COMPLETE else 1
        loop_id, _ = self._original_quest_loop_fields(definition, progress)
        return (
            f"{self._client_original_quest_id(definition.quest_id)}&"
            f"{flash_status}&{kind.value}&{data}&{loop_id}&-&{progress.finish_count}"
        )

    def _send_original_started_quest_list(self) -> None:
        """Publish active quests using the captured action-3 AMF layout."""
        entries: list[tuple[OriginalQuestDefinition, OriginalQuestProgress]] = []
        for quest_id, progress in sorted(self.store.state.original_quests.items()):
            if QuestState(progress.state) not in (
                QuestState.ACTIVE,
                QuestState.READY_TO_COMPLETE,
            ):
                continue
            definition = GAME_DATA_CATALOG.get_quest_definition(quest_id)
            if definition is not None:
                entries.append((definition, progress))
        if self.wire_mode == "original":
            body = bytearray(
                struct.pack(
                    "<BH",
                    op(QuestListUpdateAction.STARTED_LIST),
                    len(entries),
                )
            )
            for definition, progress in entries:
                flash_status = (
                    2
                    if QuestState(progress.state) == QuestState.READY_TO_COMPLETE
                    else 1
                )
                body.extend(
                    struct.pack(
                        "<iB",
                        self._client_original_quest_id(definition.quest_id),
                        flash_status,
                    )
                )
                body.extend(
                    build_original_object_buffer(
                        self._original_quest_progress_data(definition, progress)
                    )
                )
                loop_id, dynamic_data = self._original_quest_loop_fields(
                    definition, progress
                )
                body.extend(struct.pack("<h", loop_id))
                if loop_id > 0:
                    body.extend(build_original_object_buffer(dynamic_data or {}))
                    body.extend(struct.pack("<h", progress.finish_count))
            self.send_original_packet(ServerOpcode.QUEST_INFO_UPDATE, bytes(body))
            return
        encoded = [
            self._encode_original_quest_status(definition, progress)
            for definition, progress in entries
        ]
        self.send_text(
            f"{op(ServerOpcode.QUEST_INFO_UPDATE)}:"
            f"{op(QuestListUpdateAction.STARTED_LIST)}:{'@'.join(encoded) or '-'}"
        )

    def _send_original_can_start_quest_list(self) -> None:
        """Publish every currently eligible authored quest."""
        self._refresh_ring_quest_periods()
        active_daily_ring = bool(self._active_ring_template_id("daily"))
        active_weekly_ring = bool(self._active_ring_template_id("weekly"))
        quest_ids = [
            quest_id
            for quest_id in GAME_DATA_CATALOG.quest_ids
            if (definition := GAME_DATA_CATALOG.get_quest_definition(quest_id))
            is not None
            and not (8003 <= quest_id <= 8022)
            and not (
                quest_id in {8001, 8002}
                and (
                    (
                        quest_id == 8001
                        and (
                            active_daily_ring
                            or self.store.state.ring_daily_count >= 20
                        )
                    )
                    or (
                        quest_id == 8002
                        and (
                            active_weekly_ring
                            or self.store.state.ring_weekly_count >= 100
                        )
                    )
                )
            )
            and self._can_start_original_quest(definition)
        ]
        if self.wire_mode == "original":
            body = bytearray(
                struct.pack(
                    "<BH",
                    op(QuestListUpdateAction.CAN_START_LIST),
                    len(quest_ids),
                )
            )
            for quest_id in quest_ids:
                body.extend(struct.pack("<i", quest_id))
            self.send_original_packet(ServerOpcode.QUEST_INFO_UPDATE, bytes(body))
            return
        self.send_text(
            f"{op(ServerOpcode.QUEST_INFO_UPDATE)}:"
            f"{op(QuestListUpdateAction.CAN_START_LIST)}:"
            f"{'@'.join(str(quest_id) for quest_id in quest_ids) or '-'}"
        )

    def _send_original_quest_lists(self) -> None:
        """Refresh both original started and can-start lists after each state transition."""
        self._send_original_started_quest_list()
        self._send_original_can_start_quest_list()
        if self.wire_mode != "original":
            for quest_id, progress in sorted(self.store.state.original_quests.items()):
                if QuestState(progress.state) not in (
                    QuestState.ACTIVE,
                    QuestState.READY_TO_COMPLETE,
                ):
                    continue
                definition = GAME_DATA_CATALOG.get_quest_definition(quest_id)
                if definition is not None:
                    self._send_original_quest_full_progress(definition, progress)

    def _handle_quest_npc_talk(self) -> None:
        """Drive the accept-progress-turn-in loop from repeated guide conversations."""
        with self.store.lock:
            quest = self.store.state.quest
            state = QuestState(quest.state)
            if state == QuestState.NOT_STARTED:
                quest.state = int(QuestState.ACTIVE)
                quest.kills = 0
                message = "任务已接受：击败木叶森林里任意一只怪物，然后回来找我。"
                self.store.save()
            elif state == QuestState.ACTIVE:
                message = f"训练进度：{quest.kills}/{self.QUEST_TARGET_KILLS}。"
            elif state == QuestState.READY_TO_COMPLETE:
                self._complete_quest()
                message = (
                    f"任务完成！获得经验{self.QUEST_REWARD_EXP}、金币{self.QUEST_REWARD_MONEY}"
                    f"和药水{self.QUEST_REWARD_ITEM_COUNT}个。"
                )
            else:
                message = "训练任务已经完成，继续在本地图自由战斗吧。"
        self._send_npc_dialog(message, self.QUEST_NPC_TEMPLATE_ID)
        self._send_npc_quest_status()

    def _complete_quest(self) -> None:
        """Grant the fixed quest rewards and persist them exactly once."""
        quest = self.store.state.quest
        if QuestState(quest.state) != QuestState.READY_TO_COMPLETE:
            return
        if not self._has_inventory_capacity(
            [(self.QUEST_REWARD_ITEM_ID, self.QUEST_REWARD_ITEM_COUNT)]
        ):
            self._send_system_chat("背包空间不足，无法领取任务奖励。")
            return
        quest.state = int(QuestState.COMPLETED)
        self.store.state.money += self.QUEST_REWARD_MONEY
        item, created = self._add_inventory_item(
            self.QUEST_REWARD_ITEM_ID,
            self.QUEST_REWARD_ITEM_COUNT,
        )
        self.store.save()
        if created:
            self._send_inventory_add(item, from_drop=0)
        else:
            self._send_inventory_update(item, from_drop=0)
        self._grant_experience(self.QUEST_REWARD_EXP)
        self._send_stats({StatType.MONEY: self.store.state.money})
        self.send_text(f"{op(ServerOpcode.SHOW_QUEST_COMPLETION)}:{self.QUEST_ID}")

    def _spend_ring_currency(self, amount: int) -> bool:
        """Spend one native ring-task fee from bound cash first, then cash."""
        if self.store.state.coupon_money >= amount:
            self.store.state.coupon_money -= amount
            self._send_stats({StatType.CASH_BIND: self.store.state.coupon_money})
            return True
        if self.store.state.cash_money >= amount:
            self.store.state.cash_money -= amount
            self.handle_cash_money("")
            return True
        self._send_native_server_message("点券或元宝不足。", 16)
        return False

    def _handle_ring_quest_action(
        self,
        definition: OriginalQuestDefinition,
        progress: OriginalQuestProgress,
        action: QuestAction,
    ) -> bool:
        """Handle the native loop-task difficulty, reward-star, and instant-complete buttons."""
        if definition.quest_type not in {"loop", "banghui"} or QuestState(progress.state) not in (
            QuestState.ACTIVE,
            QuestState.READY_TO_COMPLETE,
        ):
            return False
        if action == QuestAction.DECREASE_REQUIREMENT:
            with self.store.lock:
                if progress.difficulty_level <= 1:
                    self._send_native_server_message("任务难度已经是最低等级。", 16)
                    return True
                progress.difficulty_level -= 1
                if QuestState(progress.state) == QuestState.ACTIVE:
                    self._refresh_original_quest_progress(definition, progress)
                self.store.save()
            self._send_original_quest_full_progress(definition, progress)
            if QuestState(progress.state) == QuestState.READY_TO_COMPLETE:
                self._send_original_quest_completion_notification(definition.quest_id)
            return True
        if action == QuestAction.INCREASE_REWARD_LEVEL:
            with self.store.lock:
                if progress.rich_degree >= 5:
                    self._send_native_server_message("任务奖励已经提升到五星。", 16)
                    return True
                if not self._spend_ring_currency(10):
                    return True
                progress.rich_degree += 1
                progress.refresh_available_at = int(time.time()) + 600
                self.store.save()
            self._send_original_quest_full_progress(definition, progress)
            return True
        if action == QuestAction.COMPLETE_LOOP:
            with self.store.lock:
                if not self._spend_ring_currency(5):
                    return True
                for objective in definition.objectives:
                    progress.progress[objective.progress_key] = self._quest_objective_count(
                        definition, progress, objective
                    )
                progress.state = int(QuestState.READY_TO_COMPLETE)
                self.store.save()
            self._send_original_quest_full_progress(definition, progress, flash_status=2)
            self._complete_original_quest(
                definition,
                definition.end_npc_id,
                show_dialog=False,
            )
            return True
        return False

    def handle_quest_action(self, read_str: str) -> None:
        """Support explicit Flash quest buttons in addition to the quick NPC state machine."""
        fields = self._request_fields(read_str, ClientOpcode.QUEST_ACTION)
        if len(fields) < 2:
            return
        action_value = self._safe_int(fields[0], -1)
        quest_id = self._safe_int(fields[1], -1)
        if quest_id in {8001, 8002}:
            expected_mode = "daily" if quest_id == 8001 else "weekly"
            quest_id = self._active_ring_template_id(expected_mode) or quest_id
        try:
            action = QuestAction(action_value)
        except ValueError:
            return
        if quest_id != self.QUEST_ID:
            definition = GAME_DATA_CATALOG.get_quest_definition(quest_id)
            if definition is None:
                return
            progress = self.store.state.original_quests.get(quest_id)
            active_npc = (
                self.npcs.get(self.active_npc_object_id)
                if self.active_npc_object_id is not None
                else None
            )
            if progress is not None and self._handle_ring_quest_action(
                definition, progress, action
            ):
                return
            if (
                action == QuestAction.START
                and active_npc is not None
                and active_npc.template_id == definition.start_npc_id
            ):
                self._handle_original_quest_npc(
                    active_npc,
                    selected_quest_id=definition.quest_id,
                )
            elif (
                action == QuestAction.COMPLETE
                and progress is not None
                and QuestState(progress.state) == QuestState.READY_TO_COMPLETE
                and active_npc is not None
                and active_npc.template_id == definition.end_npc_id
            ):
                self._handle_original_quest_npc(
                    active_npc,
                    selected_quest_id=definition.quest_id,
                )
            elif (
                action == QuestAction.FORFEIT
                and progress is not None
                and QuestState(progress.state) in (QuestState.ACTIVE, QuestState.READY_TO_COMPLETE)
            ):
                with self.store.lock:
                    progress.state = int(QuestState.NOT_STARTED)
                    progress.progress.clear()
                    if 8003 <= definition.quest_id <= 8022:
                        self.store.state.ring_quest_modes.pop(
                            definition.quest_id,
                            None,
                        )
                        if not self.store.state.ring_quest_modes:
                            self.store.state.ring_active_mode = ""
                    self.store.save()
                self._send_original_quest_lists()
                self._send_npc_quest_status()
            return
        with self.store.lock:
            quest = self.store.state.quest
            state = QuestState(quest.state)
            if action == QuestAction.START and state == QuestState.NOT_STARTED:
                quest.state = int(QuestState.ACTIVE)
                quest.kills = 0
                self.store.save()
            elif action == QuestAction.COMPLETE and state == QuestState.READY_TO_COMPLETE:
                self._complete_quest()
            elif action == QuestAction.FORFEIT and state in (
                QuestState.ACTIVE,
                QuestState.READY_TO_COMPLETE,
            ):
                quest.state = int(QuestState.NOT_STARTED)
                quest.kills = 0
                self.store.save()
        self._send_npc_quest_status()

    def handle_quest_info(self, read_str: str) -> None:
        """Return original started/can-start quest lists in QuestProcessor's text format."""
        fields = self._request_fields(read_str, ClientOpcode.QUEST_INFO)
        request_type = self._safe_int(fields[0], 0) if fields else 0
        if request_type == 1:
            self._send_original_started_quest_list()
        elif request_type == 2:
            self._send_original_can_start_quest_list()

    def _send_npc_dialog(
        self,
        message: str,
        npc_template_id: int,
        menu: str = "-",
        selection: str = "-",
        player_text: str = "-",
    ) -> None:
        """Show plain text through NPCTalkProcessor.handleNPCTalkExPacket."""
        safe_message = message.replace(":", "：")
        safe_player_text = player_text.replace(":", "：")
        self.send_text(
            f"{op(ServerOpcode.NPC_TALK_EX)}:{npc_template_id}:"
            f"{safe_message}:{safe_player_text}:{menu}:{selection}:-:-"
        )

    def _send_authored_quest_dialog(
        self,
        dialogue: str,
        npc_template_id: int,
    ) -> None:
        """Split GameData's `NPC text @ player reply` into the native two-pane fields."""
        npc_text, separator, player_text = dialogue.partition("@")
        # A few authoritative Nya quest lines omit the player half entirely.
        # NPC_TALK_EX treats "-" as no selectable reply, so the client cannot
        # send the final continue packet and the deferred quest transition stalls.
        reply = player_text.strip() if separator and player_text.strip() else "\u7ee7\u7eed"
        self._send_npc_dialog(
            npc_text.strip(),
            npc_template_id,
            player_text=reply,
        )

    def _send_npc_quest_status(self) -> None:
        """Update local and original quest markers for every NPC on the current map."""
        priority = {
            NpcQuestStatus.NONE: 0,
            NpcQuestStatus.IN_PROGRESS: 1,
            NpcQuestStatus.CAN_START: 2,
            NpcQuestStatus.CAN_COMPLETE: 3,
        }
        local_status_by_state = {
            QuestState.NOT_STARTED: NpcQuestStatus.CAN_START,
            QuestState.ACTIVE: NpcQuestStatus.IN_PROGRESS,
            QuestState.READY_TO_COMPLETE: NpcQuestStatus.CAN_COMPLETE,
            QuestState.COMPLETED: NpcQuestStatus.NONE,
        }
        escort_definition = GAME_DATA_CATALOG.get_quest_definition(8100)
        escort_start_npc_id = (
            escort_definition.start_npc_id if escort_definition is not None else 23
        )
        escort_end_npc_id = (
            escort_definition.end_npc_id if escort_definition is not None else 75
        )
        escort = self.store.state.original_quests.get(8100)
        for npc in self.npcs.values():
            status = NpcQuestStatus.NONE
            if npc.object_id == self.QUEST_NPC_OBJECT_ID:
                status = local_status_by_state[QuestState(self.store.state.quest.state)]
            elif npc.template_id == 27 and self.character.level >= 20:
                active_ring = next(
                    (
                        progress
                        for quest_id, progress in self.store.state.original_quests.items()
                        if 8003 <= quest_id <= 8022
                        and QuestState(progress.state)
                        in (QuestState.ACTIVE, QuestState.READY_TO_COMPLETE)
                    ),
                    None,
                )
                status = (
                    NpcQuestStatus.IN_PROGRESS
                    if active_ring is not None
                    else NpcQuestStatus.CAN_START
                )
            elif npc.template_id == escort_start_npc_id and self.character.level >= 30:
                escort_state = (
                    QuestState(escort.state)
                    if escort is not None
                    else QuestState.NOT_STARTED
                )
                if escort_state in (
                    QuestState.NOT_STARTED,
                    QuestState.COMPLETED,
                ):
                    status = NpcQuestStatus.CAN_START
                elif escort_start_npc_id == escort_end_npc_id:
                    status = (
                        NpcQuestStatus.CAN_COMPLETE
                        if escort_state == QuestState.READY_TO_COMPLETE
                        else NpcQuestStatus.IN_PROGRESS
                    )
            elif (
                npc.template_id == escort_end_npc_id
                and escort is not None
                and QuestState(escort.state)
                in (QuestState.ACTIVE, QuestState.READY_TO_COMPLETE)
            ):
                status = (
                    NpcQuestStatus.CAN_COMPLETE
                    if QuestState(escort.state) == QuestState.READY_TO_COMPLETE
                    else NpcQuestStatus.IN_PROGRESS
                )
            for definition in GAME_DATA_CATALOG.quests_for_npc(npc.template_id):
                # Keep private ring templates from producing gray markers, but
                # expose a real completion marker at the authored receiver.
                if 8003 <= definition.quest_id <= 8022:
                    progress = self.store.state.original_quests.get(
                        definition.quest_id
                    )
                    if (
                        not self._ring_mode_for_quest_id(definition.quest_id)
                        or progress is None
                        or definition.end_npc_id != npc.template_id
                        or QuestState(progress.state)
                        != QuestState.READY_TO_COMPLETE
                    ):
                        continue
                    candidate = NpcQuestStatus.CAN_COMPLETE
                    if priority[candidate] > priority[status]:
                        status = candidate
                    continue
                progress = self.store.state.original_quests.get(definition.quest_id)
                candidate = NpcQuestStatus.NONE
                if (
                    progress is not None
                    and QuestState(progress.state) == QuestState.READY_TO_COMPLETE
                    and definition.end_npc_id == npc.template_id
                ):
                    candidate = NpcQuestStatus.CAN_COMPLETE
                elif self._can_start_original_quest(definition) and (
                    definition.start_npc_id == npc.template_id
                    or (
                        npc.object_id == self.QUEST_NPC_OBJECT_ID
                        and definition.start_npc_id == 0
                    )
                ):
                    candidate = NpcQuestStatus.CAN_START
                elif (
                    progress is not None
                    and QuestState(progress.state) == QuestState.ACTIVE
                    and definition.end_npc_id == npc.template_id
                ):
                    candidate = NpcQuestStatus.IN_PROGRESS
                if priority[candidate] > priority[status]:
                    status = candidate
            self.send_text(
                f"{op(ServerOpcode.UPDATE_NPC_QUEST_STATUS)}:{npc.object_id}:{op(status)}"
            )

    @staticmethod
    def _request_fields(read_str: str, opcode: ClientOpcode) -> list[str]:
        """Remove the leading opcode and trailing millisecond timestamp from readStr."""
        if not read_str:
            return []
        fields = read_str.split(":")
        if fields and fields[0] == str(op(opcode)):
            fields = fields[1:]
        if fields and fields[-1].isdigit() and len(fields[-1]) >= 10:
            fields = fields[:-1]
        return fields

    @staticmethod
    def _strip_timestamp(read_str: str) -> str:
        """Remove the timestamp suffix without splitting JSON payloads on inner colons."""
        payload, separator, timestamp = read_str.rpartition(":")
        if separator and timestamp.isdigit() and len(timestamp) >= 10:
            return payload
        return read_str

    @staticmethod
    def _safe_int(value: Any, default: int) -> int:
        """Convert integer-like protocol numbers without disconnecting on bad UI input."""
        try:
            return int(float(value))
        except (TypeError, ValueError):
            return default

    def send_json(self, payload: dict[str, Any]) -> None:
        """Send a JSON-shaped server packet through the Flash XOR and AMF3 wrapper."""
        normalized = {
            key: int(value) if isinstance(value, IntEnum) else value
            for key, value in payload.items()
        }
        if self.wire_mode == "original":
            if self._send_original_json(normalized):
                return
            _trace_packet("send-original-json-unhandled", repr(normalized)[:240])
            return
        self.send_raw(json.dumps(normalized, ensure_ascii=False, separators=(",", ":")))

    def _send_original_json(self, payload: dict[str, Any]) -> bool:
        """Serialize object-shaped responses used by the unpacked client."""
        opcode = self._safe_int(payload.get("jylx"), -1)
        if opcode == op(ServerOpcode.WORLD_BOSS):
            action = self._safe_int(payload.get("action"), 0)
            data = {
                key: value
                for key, value in payload.items()
                if key not in {"jylx", "action"}
            }
            self.send_original_packet(
                ServerOpcode.WORLD_BOSS,
                struct.pack("<B", action & 0xFF)
                + build_original_object_buffer(data),
            )
            return True
        if opcode == op(ServerOpcode.BIGUAN_INFO):
            self.send_original_packet(
                ServerOpcode.BIGUAN_INFO,
                struct.pack(
                    "<iiii",
                    self._safe_int(payload.get("seconds"), 0),
                    self._safe_int(payload.get("expGain"), 0),
                    self._safe_int(payload.get("zqGain"), 0),
                    self._safe_int(payload.get("problem"), 0),
                ),
            )
            return True
        if opcode == op(ServerOpcode.WANG_LIST):
            rows: list[dict[str, Any]] = []
            for raw_row in str(payload.get("wanglist", "")).split("||"):
                if not raw_row:
                    continue
                try:
                    row = json.loads(raw_row)
                except (TypeError, ValueError, json.JSONDecodeError):
                    continue
                if isinstance(row, dict):
                    rows.append(row)
            body = bytearray(struct.pack("<i", len(rows)))
            for index, row in enumerate(rows):
                body.extend(
                    struct.pack(
                        "<iiiBi",
                        self._safe_int(row.get("index"), index),
                        self._safe_int(row.get("mobId"), 0),
                        self._safe_int(row.get("mapId"), 0),
                        1 if bool(row.get("alive")) else 0,
                        self._safe_int(row.get("nextTime"), 0),
                    )
                )
            self.send_original_packet(ServerOpcode.WANG_LIST, bytes(body))
            return True
        if opcode >= 0:
            data = {key: value for key, value in payload.items() if key != "jylx"}
            try:
                body = build_original_object_buffer(data)
            except (TypeError, ValueError):
                return False
            self.send_original_packet(opcode, body)
            return True
        return False

    @staticmethod
    def _original_cash_item_payload(raw_fields: list[str]) -> bytes:
        """Encode CashItemInfo.decode field order from the shared text row."""
        values = [FakeFlashSession._safe_int(value, 0) for value in raw_fields[:16]]
        values.extend([0] * (16 - len(values)))
        body = bytearray()
        body.extend(struct.pack("<iii", values[0], values[1], values[2]))
        body.extend(struct.pack("<BB", values[3] & 0xFF, values[4] & 0xFF))
        body.extend(struct.pack("<ii", values[5], values[6]))
        body.extend(struct.pack("<Bii", values[7] & 0xFF, values[8], values[9]))
        body.extend(struct.pack("<BBB", values[10] & 0xFF, values[11] & 0xFF, values[12] & 0xFF))
        body.extend(struct.pack("<iiB", values[13], values[14], values[15] & 0xFF))
        return bytes(body)

    def _original_paihang_payload(self, raw_row: str) -> bytes:
        values = raw_row.split("&")
        values.extend(["0"] * (5 - len(values)))
        return b"".join(
            (
                struct.pack(
                    "<ii",
                    self._safe_int(values[0], 0),
                    self._safe_int(values[1], 0),
                ),
                self._original_utf(values[2]),
                struct.pack(
                    "<dd",
                    float(self._safe_int(values[3], 0)),
                    float(self._safe_int(values[4], 0)),
                ),
            )
        )

    def _original_map_flag_payload(self, raw_row: str) -> bytes:
        values = raw_row.split("&")
        values.extend(["0"] * (12 - len(values)))
        return b"".join(
            (
                struct.pack(
                    "<iiiii",
                    self._safe_int(values[0], 0),
                    self._safe_int(values[1], 0),
                    self._safe_int(values[2], 0),
                    self._safe_int(values[3], 0),
                    self._safe_int(values[4], 0),
                ),
                self._original_utf(values[5]),
                struct.pack(
                    "<iiiii",
                    self._safe_int(values[6], 0),
                    self._safe_int(values[7], 0),
                    self._safe_int(values[8], 0),
                    self._safe_int(values[9], 0),
                    self._safe_int(values[10], 0),
                ),
                self._original_utf(values[11]),
            )
        )

    def send_text(self, payload: str) -> None:
        """Send a colon-delimited server packet through the Flash XOR and AMF3 wrapper."""
        normalized = payload.translate(SIMPLIFIED_TRANSLATION)
        if self.wire_mode == "original":
            if self._send_original_text(normalized):
                return
            _trace_packet("send-original-unhandled", normalized[:200])
            return
        self.send_raw(normalized)

    def _send_original_core_text(self, opcode: int, fields: list[str]) -> bool:
        """Encode core combat, pet, quest, and channel responses for native clients."""
        if opcode == op(ServerOpcode.SERVERMESSAGE) and len(fields) >= 3:
            self.send_original_packet(
                ServerOpcode.SERVERMESSAGE,
                struct.pack("<B", self._safe_int(fields[1], 0) & 0xFF)
                + self._original_utf(":".join(fields[2:])),
            )
            return True
        if opcode == op(ServerOpcode.MONEY_SELL) and len(fields) >= 2:
            action = self._safe_int(fields[1], -1)
            if action == 0 and len(fields) >= 8:
                rows = [
                    row.split("&")
                    for row in fields[7].split("@")
                    if row and row != "-"
                ]
                body = bytearray(
                    struct.pack(
                        "<Bi?iiii",
                        action,
                        self._safe_int(fields[2], 0),
                        fields[3].lower() in {"1", "true"},
                        self._safe_int(fields[4], 0),
                        self._safe_int(fields[5], 0),
                        self._safe_int(fields[6], 0),
                        len(rows),
                    )
                )
                for values in rows:
                    values.extend(["0"] * (3 - len(values)))
                    body.extend(
                        struct.pack(
                            "<iii",
                            *(self._safe_int(value, 0) for value in values[:3]),
                        )
                    )
                self.send_original_packet(ServerOpcode.MONEY_SELL, bytes(body))
                return True
            if action == 1 and len(fields) >= 6:
                self.send_original_packet(
                    ServerOpcode.MONEY_SELL,
                    struct.pack(
                        "<B?ii?",
                        action,
                        fields[2].lower() in {"1", "true"},
                        self._safe_int(fields[3], 0),
                        self._safe_int(fields[4], 0),
                        fields[5].lower() in {"1", "true"},
                    ),
                )
                return True
            return False
        if opcode == op(ServerOpcode.LIANZHAN) and len(fields) >= 2:
            action = self._safe_int(fields[1], -1)
            if action == 1 and len(fields) >= 3:
                self.send_original_packet(
                    ServerOpcode.LIANZHAN,
                    struct.pack(
                        "<Bh",
                        action,
                        max(0, min(32767, self._safe_int(fields[2], 0))),
                    ),
                )
                return True
            if action == 2 and len(fields) >= 7:
                self.send_original_packet(
                    ServerOpcode.LIANZHAN,
                    struct.pack(
                        "<Bhhiii",
                        action,
                        max(0, min(8, self._safe_int(fields[2], 0))),
                        max(0, min(32767, self._safe_int(fields[3], 0))),
                        self._safe_int(fields[4], 0),
                        self._safe_int(fields[5], 0),
                        self._safe_int(fields[6], 0),
                    ),
                )
                return True
            return False
        if opcode == op(ServerOpcode.OPEN_PVP_ACTION) and len(fields) >= 2:
            action = self._safe_int(fields[1], -1)
            if action == 7 and len(fields) >= 4:
                item_ids = [
                    self._safe_int(value, 0)
                    for value in fields[3].split("@")
                    if value and value != "-"
                ]
                body = bytearray(
                    struct.pack(
                        "<Bii",
                        action,
                        self._safe_int(fields[2], 0),
                        len(item_ids),
                    )
                )
                for item_id in item_ids:
                    body.extend(struct.pack("<i", item_id))
                self.send_original_packet(ServerOpcode.OPEN_PVP_ACTION, bytes(body))
                return True
        if opcode == op(ServerOpcode.CONFIRM_SHOP_TRANSACTION) and len(fields) >= 2:
            self.send_original_packet(
                ServerOpcode.CONFIRM_SHOP_TRANSACTION,
                struct.pack(
                    "<b",
                    self._safe_int(fields[1], op(ShopConfirmCode.SHOP_ERROR)),
                ),
            )
            return True
        if opcode == op(ServerOpcode.CHANGE_CHANNEL) and len(fields) >= 6:
            try:
                address = socket.inet_aton(fields[1])
            except OSError:
                address = socket.inet_aton(self.lan_ip)
            body = address + struct.pack(
                "<Hiii",
                self._safe_int(fields[2], SERVER_PORT) & 0xFFFF,
                self._safe_int(fields[3], self.line_id),
                self._safe_int(fields[4], int(time.time())),
                self._safe_int(fields[5], 0),
            )
            self.send_original_packet(ServerOpcode.CHANGE_CHANNEL, body)
            return True
        if opcode == op(ServerOpcode.MOB_ATTACK) and len(fields) >= 13:
            rows = [row for row in fields[12].split("@") if row and row != "-"]
            damage_count = max(0, min(self._safe_int(fields[5], 1), 16))
            body = bytearray(
                struct.pack(
                    "<BidiBB?BiBb",
                    self._safe_int(fields[1], 1) & 0xFF,
                    self._safe_int(fields[2], self.character.character_id),
                    float(fields[3]),
                    self._safe_int(fields[4], self.character.level),
                    damage_count,
                    len(rows),
                    fields[7].lower() in {"1", "true"},
                    self._safe_int(fields[8], 1) & 0xFF,
                    self._safe_int(fields[9], 0),
                    self._safe_int(fields[10], 0) & 0xFF,
                    self._safe_int(fields[11], 0),
                )
            )
            for row in rows:
                target, _, remainder = row.partition("&")
                alive, _, raw_hits = remainder.partition("&")
                hits = [value for value in raw_hits.split("*") if value]
                body.extend(
                    struct.pack(
                        "<i?",
                        self._safe_int(target, 0),
                        alive.lower() in {"1", "true"},
                    )
                )
                for index in range(damage_count):
                    body.extend(
                        struct.pack(
                            "<iB",
                            self._safe_int(hits[index * 2], 0)
                            if index * 2 < len(hits)
                            else 0,
                            self._safe_int(hits[index * 2 + 1], 0) & 0xFF
                            if index * 2 + 1 < len(hits)
                            else 0,
                        )
                    )
            self.send_original_packet(ServerOpcode.MOB_ATTACK, bytes(body))
            return True
        if opcode == op(ServerOpcode.DAMAGE_PLAYER) and len(fields) >= 9:
            self.send_original_packet(
                ServerOpcode.DAMAGE_PLAYER,
                struct.pack(
                    "<ii?iiibi",
                    self._safe_int(fields[1], self.character.character_id),
                    self._safe_int(fields[2], 0),
                    fields[3].lower() in {"1", "true"},
                    self._safe_int(fields[4], 0),
                    self._safe_int(fields[5], 0),
                    self._safe_int(fields[6], 0),
                    self._safe_int(fields[7], 0),
                    self._safe_int(fields[8], 0),
                ),
            )
            return True
        if opcode == op(ServerOpcode.PLAYER_DAMAGE_PLAYER) and len(fields) >= 9:
            self.send_original_packet(
                ServerOpcode.PLAYER_DAMAGE_PLAYER,
                struct.pack(
                    "<6i?b",
                    self._safe_int(fields[8], 0),
                    self._safe_int(fields[1], 0),
                    self._safe_int(fields[2], 0),
                    self._safe_int(fields[3], 0),
                    self._safe_int(fields[4], 0),
                    self._safe_int(fields[5], 0),
                    fields[6].lower() in {"1", "true"},
                    self._safe_int(fields[7], 0),
                ),
            )
            return True
        if opcode == op(ServerOpcode.DAMAGE_MONSTER) and len(fields) >= 3:
            self.send_original_packet(
                ServerOpcode.DAMAGE_MONSTER,
                struct.pack("<ii", self._safe_int(fields[1], 0), self._safe_int(fields[2], 0)),
            )
            return True
        if opcode == op(ServerOpcode.APPLY_MONSTER_STATUS) and len(fields) >= 4:
            rows = [
                row.split("&")
                for row in fields[2].split("@")
                if row and row != "-"
            ]
            body = bytearray(
                struct.pack("<iH", self._safe_int(fields[1], 0), len(rows))
            )
            for values in rows:
                values.extend(["0"] * max(0, 5 - len(values)))
                try:
                    buff_value = float(values[1])
                except ValueError:
                    buff_value = 0.0
                body.extend(
                    struct.pack(
                        "<Bdiii",
                        self._safe_int(values[0], 0) & 0xFF,
                        buff_value,
                        self._safe_int(values[2], 0),
                        self._safe_int(values[3], 0),
                        self._safe_int(values[4], 0),
                    )
                )
            body.extend(
                struct.pack(
                    "<h",
                    max(-0x8000, min(0x7FFF, self._safe_int(fields[3], 0))),
                )
            )
            self.send_original_packet(ServerOpcode.APPLY_MONSTER_STATUS, bytes(body))
            return True
        if opcode == op(ServerOpcode.CANCEL_MONSTER_STATUS) and len(fields) >= 3:
            values = [
                self._safe_int(value, 0) & 0xFF
                for value in fields[2].split("@")
                if value and value != "-"
            ]
            self.send_original_packet(
                ServerOpcode.CANCEL_MONSTER_STATUS,
                struct.pack("<iH", self._safe_int(fields[1], 0), len(values))
                + bytes(values),
            )
            return True
        if opcode == op(ServerOpcode.SHOW_MONSTER_HP) and len(fields) >= 3:
            self.send_original_packet(
                ServerOpcode.SHOW_MONSTER_HP,
                struct.pack(
                    "<iB",
                    self._safe_int(fields[1], 0),
                    max(0, min(100, self._safe_int(fields[2], 0))),
                ),
            )
            return True
        if opcode == op(ServerOpcode.PET_ACTION) and len(fields) >= 2:
            return self._send_original_pet_text(fields)
        if opcode == op(ServerOpcode.QUEST_INFO_UPDATE) and len(fields) >= 2:
            return self._send_original_quest_text(fields)
        if opcode == op(ServerOpcode.SPIRIT_ACTION) and len(fields) >= 2:
            return self._send_original_spirit_text(fields)
        if opcode == op(ServerOpcode.LOCAL_PK_ACTION) and len(fields) >= 2:
            return self._send_original_local_pk_text(fields)
        if opcode == op(ServerOpcode.MUYE_BATTLE) and len(fields) >= 2:
            return self._send_original_muye_battle_text(fields)
        if self._send_original_war_3v3_text(opcode, fields):
            return True
        if opcode == op(ServerOpcode.WAR_PANEL_ACTION) and len(fields) >= 2:
            return self._send_original_war_panel_text(fields)
        if opcode == op(ServerOpcode.WAR_WORLDCUP) and len(fields) >= 2:
            return self._send_original_war_worldcup_text(fields)
        if self._send_original_common_text(opcode, fields):
            return True
        if self._send_original_equipment_text(opcode, fields):
            return True
        if self._send_original_feature_text(opcode, fields):
            return True
        return False

    def _send_original_common_text(self, opcode: int, fields: list[str]) -> bool:
        """Encode shared UI and combat feedback used across existing gameplay."""
        if opcode == op(ServerOpcode.CHANGE_NAMES) and len(fields) >= 3:
            result = self._safe_int(fields[1], 1) & 0xFF
            body = bytearray(struct.pack("<B", result))
            body.extend(self._original_utf(fields[2]))
            if result in {10, 12}:
                history = [
                    value
                    for value in (fields[3].split("@") if len(fields) > 3 else [])
                    if value and value != "-"
                ]
                body.extend(struct.pack("<H", len(history)))
                for value in history:
                    body.extend(self._original_utf(value))
            self.send_original_packet(ServerOpcode.CHANGE_NAMES, bytes(body))
            return True
        if opcode == op(ServerOpcode.SERVERLIST) and len(fields) >= 4:
            server_id = self._safe_int(fields[1], 1) & 0xFF
            rows = [] if fields[3] == "-" else fields[3].split("@")
            body = bytearray(struct.pack("<B", server_id))
            body.extend(self._original_utf(fields[2]))
            body.extend(struct.pack("<B", 0))
            body.extend(self._original_utf(""))
            body.extend(struct.pack("<B", len(rows) & 0xFF))
            for row in rows:
                values = row.split("&")
                values.extend(["0", "0", "0"])
                body.extend(self._original_utf(values[0]))
                body.extend(
                    struct.pack(
                        "<iBH",
                        self._safe_int(values[1], 0),
                        server_id,
                        self._safe_int(values[2], 0) & 0xFFFF,
                    )
                )
            self.send_original_packet(ServerOpcode.SERVERLIST, bytes(body))
            self.send_original_packet(ServerOpcode.SERVERLIST, b"\xff")
            return True
        if opcode == op(ServerOpcode.WARP_TO_MAP) and len(fields) >= 9:
            self.send_original_packet(
                ServerOpcode.WARP_TO_MAP,
                struct.pack(
                    "<iiB3HII",
                    self._safe_int(fields[1], 1),
                    self._safe_int(fields[2], 0),
                    self._safe_int(fields[3], 0) & 0xFF,
                    self._safe_int(fields[4], 0) & 0xFFFF,
                    self._safe_int(fields[5], 0) & 0xFFFF,
                    self._safe_int(fields[6], 0) & 0xFFFF,
                    self._safe_int(fields[8], 0) & 0xFFFFFFFF,
                    self._safe_int(fields[7], 0) & 0xFFFFFFFF,
                ),
            )
            return True
        if opcode == op(ServerOpcode.KILL_MONSTER) and len(fields) >= 3:
            self.send_original_packet(
                ServerOpcode.KILL_MONSTER,
                struct.pack("<iB", self._safe_int(fields[1], 0), self._safe_int(fields[2], 0) & 0xFF),
            )
            return True
        if opcode == op(ServerOpcode.DROP_ITEM_FROM_MAPOBJECT) and len(fields) >= 13:
            self.send_original_packet(
                ServerOpcode.DROP_ITEM_FROM_MAPOBJECT,
                struct.pack(
                    "<i?i?bi4hbi",
                    self._safe_int(fields[1], 0),
                    fields[2].lower() in {"1", "true"},
                    self._safe_int(fields[3], 0),
                    fields[4].lower() in {"1", "true"},
                    self._safe_int(fields[5], 0),
                    self._safe_int(fields[6], 0),
                    *(self._safe_int(value, 0) for value in fields[7:11]),
                    self._safe_int(fields[11], 0),
                    self._safe_int(fields[12], 0),
                ),
            )
            return True
        if opcode == op(ServerOpcode.REMOVE_DROP_ITEM_OWNER) and len(fields) >= 2:
            self.send_original_packet(
                ServerOpcode.REMOVE_DROP_ITEM_OWNER,
                struct.pack("<i", self._safe_int(fields[1], 0)),
            )
            return True
        if opcode == op(ServerOpcode.REMOVE_ITEM_FROM_MAP) and len(fields) >= 4:
            animation = self._safe_int(fields[1], 0)
            pet = len(fields) > 3 and fields[3].lower() in {"1", "true"}
            body = bytearray(
                struct.pack("<Bi?", animation & 0xFF, self._safe_int(fields[2], 0), pet)
            )
            if animation >= 2:
                body.extend(struct.pack("<d", float(self._safe_int(fields[4], 0)) if len(fields) > 4 else 0.0))
                if pet:
                    body.extend(struct.pack("<B", self._safe_int(fields[5], 0) & 0xFF if len(fields) > 5 else 0))
            self.send_original_packet(ServerOpcode.REMOVE_ITEM_FROM_MAP, bytes(body))
            return True
        if opcode == op(ServerOpcode.MOB_SKILL) and len(fields) >= 11:
            mobs = [] if fields[9] == "-" else fields[9].split("@")
            summons = [] if fields[10] == "-" else fields[10].split("@")
            body = bytearray(
                struct.pack(
                    "<i3b4i",
                    self._safe_int(fields[1], 0),
                    self._safe_int(fields[2], 0),
                    self._safe_int(fields[3], 0),
                    self._safe_int(fields[4], 0),
                    *(self._safe_int(value, 0) for value in fields[5:9]),
                )
            )
            for rows in (mobs, summons):
                body.extend(struct.pack("<i", len(rows)))
                for value in rows:
                    body.extend(struct.pack("<i", self._safe_int(value, 0)))
            self.send_original_packet(ServerOpcode.MOB_SKILL, bytes(body))
            return True
        if opcode == op(ServerOpcode.AUTO_CONSUME) and len(fields) >= 4:
            self.send_original_packet(
                ServerOpcode.AUTO_CONSUME,
                struct.pack("<3i", *(self._safe_int(value, 0) for value in fields[1:4])),
            )
            return True
        if opcode == op(ServerOpcode.ATTRIBUTE_ITEM_EFFECT) and len(fields) >= 4:
            self.send_original_packet(
                ServerOpcode.ATTRIBUTE_ITEM_EFFECT,
                struct.pack("<3i", *(self._safe_int(value, 0) for value in fields[1:4])),
            )
            return True
        if opcode == op(ServerOpcode.DOUBLE_REWARD) and len(fields) >= 6:
            self.send_original_packet(
                ServerOpcode.DOUBLE_REWARD,
                struct.pack(
                    "<bbi2i",
                    max(-128, min(127, self._safe_int(fields[1], 0))),
                    max(-128, min(127, self._safe_int(fields[2], 0))),
                    *(self._safe_int(value, 0) for value in fields[3:6]),
                ),
            )
            return True
        if opcode in {
            op(ServerOpcode.CHANGE_CHANNEL_FRAME),
            op(ServerOpcode.EXIT_BATTLE),
        }:
            # Nya 2.0.8 has no packet handlers for these legacy UI opcodes.
            # The native warp/character packets already drive the battle lifecycle.
            return True
        if opcode == op(ServerOpcode.COUPLE_ATTACK) and len(fields) >= 12:
            body = struct.pack(
                "<ii3b6i",
                self._safe_int(fields[1], 0),
                self._safe_int(fields[2], 0),
                self._safe_int(fields[3], 0),
                self._safe_int(fields[4], 0),
                self._safe_int(fields[5], 0),
                *(self._safe_int(value, 0) for value in fields[6:12]),
            )
            self.send_original_packet(ServerOpcode.COUPLE_ATTACK, body)
            return True
        if opcode == op(ServerOpcode.COOLDOWN) and len(fields) >= 3:
            cooldown = max(-32768, min(32767, self._safe_int(fields[2], 0)))
            self.send_original_packet(
                ServerOpcode.COOLDOWN,
                struct.pack("<ih", self._safe_int(fields[1], 0), cooldown),
            )
            return True
        if opcode == op(ServerOpcode.GIVE_BUFF) and len(fields) >= 2:
            rows = [
                row.split("&")
                for row in fields[1].split("@")
                if row and row != "-"
            ]
            body = bytearray(struct.pack("<H", len(rows)))
            for values in rows:
                values.extend(["0"] * max(0, 5 - len(values)))
                try:
                    buff_value = float(values[1])
                except ValueError:
                    buff_value = 0.0
                body.extend(
                    struct.pack(
                        "<Bdiii",
                        self._safe_int(values[0], 0) & 0xFF,
                        buff_value,
                        self._safe_int(values[2], 0),
                        self._safe_int(values[3], 0),
                        self._safe_int(values[4], 0),
                    )
                )
            self.send_original_packet(ServerOpcode.GIVE_BUFF, bytes(body))
            return True
        if opcode == op(ServerOpcode.SYSTEM_BUF_ACTION) and len(fields) >= 3:
            action = self._safe_int(fields[1], -1)
            buff_type = self._safe_int(fields[2], 0) & 0xFF
            if action == 0 and len(fields) >= 6:
                try:
                    buff_value = float(fields[3])
                except (TypeError, ValueError):
                    buff_value = 0.0
                self.send_original_packet(
                    ServerOpcode.SYSTEM_BUF_ACTION,
                    struct.pack(
                        "<BBdii",
                        action,
                        buff_type,
                        buff_value,
                        max(0, self._safe_int(fields[4], 0)),
                        max(0, self._safe_int(fields[5], 0)),
                    ),
                )
                return True
            if action == 1:
                self.send_original_packet(
                    ServerOpcode.SYSTEM_BUF_ACTION,
                    struct.pack("<BB", action, buff_type),
                )
                return True
        if opcode == op(ServerOpcode.CANCEL_BUFF) and len(fields) >= 2:
            values = [
                self._safe_int(value, 0) & 0xFF
                for value in fields[1].split("@")
                if value and value != "-"
            ]
            self.send_original_packet(
                ServerOpcode.CANCEL_BUFF,
                struct.pack("<H", len(values)) + bytes(values),
            )
            return True
        if opcode == op(ServerOpcode.GIVE_FOREIGN_BUFF) and len(fields) >= 3:
            rows = [
                row.split("&")
                for row in fields[2].split("@")
                if row and row != "-"
            ]
            body = bytearray(
                struct.pack(
                    "<iH",
                    self._safe_int(fields[1], 0),
                    len(rows),
                )
            )
            for values in rows:
                values.extend(["0"] * max(0, 5 - len(values)))
                try:
                    buff_value = float(values[1])
                except ValueError:
                    buff_value = 0.0
                body.extend(
                    struct.pack(
                        "<Bdiii",
                        self._safe_int(values[0], 0) & 0xFF,
                        buff_value,
                        self._safe_int(values[2], 0),
                        self._safe_int(values[3], 0),
                        self._safe_int(values[4], 0),
                    )
                )
            delay = self._safe_int(fields[3], 0) if len(fields) > 3 else 0
            body.extend(struct.pack("<h", max(-32_768, min(32_767, delay))))
            self.send_original_packet(ServerOpcode.GIVE_FOREIGN_BUFF, bytes(body))
            return True
        if opcode == op(ServerOpcode.CANCEL_FOREIGN_BUFF) and len(fields) >= 3:
            values = [
                self._safe_int(value, 0) & 0xFF
                for value in fields[2].split("@")
                if value and value != "-"
            ]
            self.send_original_packet(
                ServerOpcode.CANCEL_FOREIGN_BUFF,
                struct.pack(
                    "<iH",
                    self._safe_int(fields[1], 0),
                    len(values),
                )
                + bytes(values),
            )
            return True
        if opcode == op(ServerOpcode.PLAYER_DEAD_BOX) and len(fields) >= 3:
            action = self._safe_int(fields[1], 0)
            body = bytearray(struct.pack("<b", action))
            body.extend(struct.pack("<i", self._safe_int(fields[2], 0)))
            if action == 1:
                body.extend(
                    struct.pack(
                        "<i",
                        self._safe_int(fields[3], 0) if len(fields) > 3 else 0,
                    )
                )
            elif action != 2:
                return False
            self.send_original_packet(ServerOpcode.PLAYER_DEAD_BOX, bytes(body))
            return True
        if opcode == op(ServerOpcode.SHOW_NPC_PANEL) and len(fields) >= 3:
            self.send_original_packet(
                ServerOpcode.SHOW_NPC_PANEL,
                struct.pack(
                    "<ii",
                    self._safe_int(fields[1], 0),
                    self._safe_int(fields[2], 0),
                ),
            )
            return True
        if opcode == op(ServerOpcode.UPDATE_SKILLS) and len(fields) >= 2:
            values = fields[1].split("&")
            values.extend(["0", "0", "0"])
            self.send_original_packet(
                ServerOpcode.UPDATE_SKILLS,
                struct.pack(
                    "<iii",
                    *(self._safe_int(value, 0) for value in values[:3]),
                ),
            )
            return True
        if opcode == op(ServerOpcode.EQUIP_PICKUP) and len(fields) >= 3:
            try:
                unique_id = float(fields[2])
            except ValueError:
                unique_id = 0.0
            self.send_original_packet(
                ServerOpcode.EQUIP_PICKUP,
                struct.pack(
                    "<Bid",
                    0,
                    self._safe_int(fields[1], 0),
                    unique_id,
                ),
            )
            return True
        if opcode == op(ServerOpcode.CHANGE_WEATHER) and len(fields) >= 2:
            self.send_original_packet(
                ServerOpcode.CHANGE_WEATHER,
                struct.pack("<i", self._safe_int(fields[1], 0)),
            )
            return True
        if opcode == op(ServerOpcode.BEGIN_UI_EFFECT) and len(fields) >= 2:
            self.send_original_packet(
                ServerOpcode.BEGIN_UI_EFFECT,
                struct.pack("<b", self._safe_int(fields[1], 0)),
            )
            return True
        if (
            opcode == op(ServerOpcode.SHOW_STATUS_INFO)
            and len(fields) >= 5
            and self._safe_int(fields[1], -1) == 1
        ):
            self.send_original_packet(
                ServerOpcode.SHOW_STATUS_INFO,
                struct.pack(
                    "<BiBb",
                    1,
                    self._safe_int(fields[2], 0),
                    self._safe_int(fields[3], 0) & 0xFF,
                    self._safe_int(fields[4], 0),
                ),
            )
            return True
        return False

    def _send_original_war_panel_text(self, fields: list[str]) -> bool:
        """Encode the cross-server panel actions shared with the Nya client."""
        action = self._safe_int(fields[1], -1)
        body = bytearray(struct.pack("<B", action & 0xFF))
        if action == 0 and len(fields) >= 4:
            rows = [
                row.split("&")
                for row in fields[2].split("@")
                if row and row != "-"
            ]
            body.extend(struct.pack("<i", len(rows)))
            for values in rows:
                values.extend(["0", "", "0"])
                body.extend(struct.pack("<i", self._safe_int(values[0], 0)))
                body.extend(self._original_utf(values[1]))
                body.extend(struct.pack("<i", self._safe_int(values[2], 0)))
            body.extend(struct.pack("<i", self._safe_int(fields[3], 0)))
        elif action == 1 and len(fields) >= 6:
            body.extend(
                struct.pack(
                    "<4i",
                    *(self._safe_int(value, 0) for value in fields[2:6]),
                )
            )
        elif action in {2, 5, 7} and len(fields) >= 3:
            body.extend(struct.pack("<i", self._safe_int(fields[2], 0)))
        elif action == 3 and len(fields) >= 3:
            rows = [
                row.split("&")
                for row in fields[2].split("@")
                if row and row != "-"
            ]
            body.extend(struct.pack("<i", len(rows)))
            for values in rows:
                values.extend(["0"] * max(0, 9 - len(values)))
                body.extend(
                    struct.pack(
                        "<iii",
                        self._safe_int(values[0], 0),
                        self._safe_int(values[1], 0),
                        self._safe_int(values[2], 0),
                    )
                )
                body.extend(self._original_utf(values[3]))
                body.extend(struct.pack("<i", self._safe_int(values[4], 0)))
                body.extend(self._original_utf(values[5]))
                body.extend(
                    struct.pack(
                        "<3i",
                        self._safe_int(values[6], 0),
                        self._safe_int(values[7], 0),
                        self._safe_int(values[8], 0),
                    )
                )
        elif action == 4 and len(fields) >= 3:
            target = self._character_info_session(
                self._safe_int(fields[2], -1)
            )
            if target is None:
                return False
            body.extend(target._original_character_full_info_payload())
        elif action == 6 and len(fields) >= 4:
            body.extend(struct.pack("<i", self._safe_int(fields[2], 0)))
            body.extend(self._original_utf(fields[3]))
        else:
            return False
        self.send_original_packet(ServerOpcode.WAR_PANEL_ACTION, bytes(body))
        return True

    def _send_original_war_worldcup_text(self, fields: list[str]) -> bool:
        """Encode opcode 2312 exactly as WarWorldcupProcessor decodes it."""
        action = self._safe_int(fields[1], -1)
        body = bytearray(struct.pack("<B", action & 0xFF))
        if action == 0 and len(fields) >= 7:
            rows = [row.split("&") for row in fields[2].split("@")]
            rows.extend([["-1", "0", "", "0", "0"]] * max(0, 32 - len(rows)))
            for values in rows[:32]:
                values.extend(["0"] * max(0, 5 - len(values)))
                body.extend(
                    struct.pack(
                        "<ii",
                        self._safe_int(values[0], -1),
                        self._safe_int(values[1], 0),
                    )
                )
                body.extend(self._original_utf(values[2]))
                body.extend(
                    struct.pack(
                        "<ii",
                        self._safe_int(values[3], 0),
                        self._safe_int(values[4], 0),
                    )
                )
            body.extend(
                struct.pack(
                    "<4i",
                    *(self._safe_int(value, 0) for value in fields[3:7]),
                )
            )
        elif action in {1, 2}:
            pass
        elif action in {3, 4, 5} and len(fields) >= 3:
            body.extend(struct.pack("<i", self._safe_int(fields[2], 0)))
        else:
            return False
        self.send_original_packet(ServerOpcode.WAR_WORLDCUP, bytes(body))
        return True

    def _send_original_equipment_text(self, opcode: int, fields: list[str]) -> bool:
        """Encode equipment lists and forge results already implemented by the server."""
        if opcode == op(ServerOpcode.WASH_MYTH_ATTRIBUTE_RESULT) and len(fields) >= 10:
            rows = [
                row.split("&")
                for row in fields[3].split("@")
                if row and row != "-"
            ]
            body = bytearray(
                struct.pack(
                    "<3i",
                    self._safe_int(fields[1], 0),
                    self._safe_int(fields[2], 0),
                    len(rows),
                )
            )
            for values in rows:
                values.extend(["0", "0"])
                body.extend(
                    struct.pack(
                        "<2i",
                        self._safe_int(values[0], 0),
                        self._safe_int(values[1], 0),
                    )
                )
            body.extend(
                struct.pack(
                    "<6i",
                    *(self._safe_int(value, 0) for value in fields[4:10]),
                )
            )
            self.send_original_packet(
                ServerOpcode.WASH_MYTH_ATTRIBUTE_RESULT,
                bytes(body),
            )
            return True
        if opcode in {
            op(ServerOpcode.EQUIPPED_INFO),
            op(ServerOpcode.EQUIPPED_KUNCHONG),
        }:
            if opcode == op(ServerOpcode.EQUIPPED_INFO):
                items = [
                    item
                    for item in sorted(
                        self.store.state.inventory.values(),
                        key=lambda value: value.slot,
                    )
                    if -199 <= item.slot < 0
                    and GAME_DATA_CATALOG.is_equipment_item(item.item_id)
                    and self._inventory_item_section(item)
                    not in {"ShenQi", "HunJie", "LingQi", "RenJu"}
                ]
                response_opcode = ServerOpcode.EQUIPPED_INFO
            else:
                equipped_positions = {
                    op(position) for position in KUN_CHONG_EQUIPPED_POSITIONS
                }
                items = [
                    item
                    for item in sorted(
                        self.store.state.inventory.values(),
                        key=lambda value: value.slot,
                    )
                    if item.slot in equipped_positions
                ]
                response_opcode = ServerOpcode.EQUIPPED_KUNCHONG
            self.send_original_packet(
                response_opcode,
                self._original_item_list_payload(items),
            )
            return True
        fixed_widths = {
            op(ServerOpcode.HUI_ZHANG_STONE_MERGE_RES): 4,
            op(ServerOpcode.STONE_MERGE_RESPONSE): 9,
            op(ServerOpcode.KUNCHONG_STRENGTH_RESULT): 2,
            op(ServerOpcode.EQUIPMENT_FORGE_STRENGTH_RESULT): 2,
            op(ServerOpcode.EQUIPMENT_FORGE_ADDITIVE_RESULT): 2,
        }
        if opcode in fixed_widths:
            width = fixed_widths[opcode]
            if len(fields) < width + 1:
                return False
            self.send_original_packet(
                opcode,
                struct.pack(
                    f"<{width}i",
                    *(self._safe_int(value, 0) for value in fields[1 : width + 1]),
                ),
            )
            return True
        if opcode == op(ServerOpcode.EQUIPMENT_INLAY_INFO) and len(fields) >= 3:
            rows = [
                row.split("&")
                for row in fields[2].split("@")
                if row and row != "-"
            ]
            body = bytearray(
                struct.pack("<ii", self._safe_int(fields[1], 0), len(rows))
            )
            for values in rows:
                values.extend(["0"] * max(0, 5 - len(values)))
                body.extend(
                    struct.pack(
                        "<5i",
                        *(self._safe_int(value, 0) for value in values[:5]),
                    )
                )
            self.send_original_packet(ServerOpcode.EQUIPMENT_INLAY_INFO, bytes(body))
            return True
        if opcode == op(ServerOpcode.WASH_PLUS_VALUE_RESULT) and len(fields) >= 4:
            rows = [
                row.split("&")
                for row in fields[3].split("@")
                if row and row != "-"
            ]
            body = bytearray(
                struct.pack(
                    "<3i",
                    self._safe_int(fields[1], 0),
                    self._safe_int(fields[2], 0),
                    len(rows),
                )
            )
            for values in rows:
                values.extend(["0", "0"])
                body.extend(
                    struct.pack(
                        "<ii",
                        self._safe_int(values[0], 0),
                        self._safe_int(values[1], 0),
                    )
                )
            self.send_original_packet(ServerOpcode.WASH_PLUS_VALUE_RESULT, bytes(body))
            return True
        if opcode == op(ServerOpcode.WASH_SPECIAL_ATTR_RESULT) and len(fields) >= 7:
            rows = [
                row.split("&")
                for row in fields[3].split("@")
                if row and row != "-"
            ]
            body = bytearray(struct.pack(
                "<3i", self._safe_int(fields[1], 0), self._safe_int(fields[2], 0), len(rows)
            ))
            for values in rows:
                body.extend(struct.pack(
                    "<ii", self._safe_int(values[0], 0), self._safe_int(values[1], 0)
                ))
            body.extend(struct.pack(
                "<3i", self._safe_int(fields[4], 0), self._safe_int(fields[5], 0), self._safe_int(fields[6], 0)
            ))
            self.send_original_packet(ServerOpcode.WASH_SPECIAL_ATTR_RESULT, bytes(body))
            return True
        return False

    @staticmethod
    def _original_scalar_action_body(fields: list[str], action_width: int = 1) -> bytes:
        """Encode an action followed by the int/bool/UTF scalars used by simple processors."""
        action = int(fields[1]) if len(fields) > 1 else 0
        if action_width == 2:
            body = bytearray(struct.pack("<H", action & 0xFFFF))
        elif action_width == 4:
            body = bytearray(struct.pack("<i", action))
        else:
            body = bytearray(struct.pack("<B", action & 0xFF))
        for value in fields[2:]:
            lowered = value.lower()
            if lowered in {"true", "false"}:
                body.extend(struct.pack("<?", lowered == "true"))
                continue
            try:
                body.extend(struct.pack("<i", int(value)))
            except ValueError:
                encoded = value.encode("utf-8")
                body.extend(struct.pack("<H", len(encoded)))
                body.extend(encoded)
        return bytes(body)

    def _send_original_feature_text(self, opcode: int, fields: list[str]) -> bool:
        """Encode shared progression and activity handlers for the native client."""
        if (
            opcode == op(ServerOpcode.AN_QI)
            and len(fields) >= 10
            and self._safe_int(fields[1], -1) == op(CultivationResponseAction.RESULT)
        ):
            players = [
                row.split("&")
                for row in fields[8].split("@")
                if row and row != "-"
            ]
            mobs = [
                row.split("&")
                for row in fields[9].split("@")
                if row and row != "-"
            ]
            body = bytearray(
                struct.pack(
                    "<BiiiBBB",
                    op(CultivationResponseAction.RESULT),
                    self._safe_int(fields[2], 0),
                    self._safe_int(fields[3], 0),
                    self._safe_int(fields[4], 0),
                    self._safe_int(fields[5], 0) & 0xFF,
                    self._safe_int(fields[6], 0) & 0xFF,
                    self._safe_int(fields[7], 0) & 0xFF,
                )
            )
            body.extend(struct.pack("<i", len(players)))
            for values in players:
                values.extend(["0", "0"])
                body.extend(
                    struct.pack(
                        "<ii",
                        self._safe_int(values[0], 0),
                        self._safe_int(values[1], 0),
                    )
                )
            body.extend(struct.pack("<i", len(mobs)))
            for values in mobs:
                values.extend(["0", "0"])
                body.extend(
                    struct.pack(
                        "<ii",
                        self._safe_int(values[0], 0),
                        self._safe_int(values[1], 0),
                    )
                )
            self.send_original_packet(ServerOpcode.AN_QI, bytes(body))
            return True
        cultivation = {
            op(ServerOpcode.AN_QI),
            op(ServerOpcode.XIELUNYAN_ACTION),
            op(ServerOpcode.ROU_QUAN),
            op(ServerOpcode.LUN_HUI_YAN),
            op(ServerOpcode.JIE_YIN),
        }
        if opcode in cultivation and len(fields) >= 2:
            self.send_original_packet(opcode, self._original_scalar_action_body(fields))
            return True
        if opcode == op(ServerOpcode.CAN_JUAN_ACTION) and len(fields) >= 3:
            self.send_original_packet(
                ServerOpcode.CAN_JUAN_ACTION,
                struct.pack(
                    "<B?",
                    self._safe_int(fields[1], 0) & 0xFF,
                    fields[2].lower() in {"1", "true"},
                ),
            )
            return True
        if opcode == op(ServerOpcode.OPEN_PVP_ACTION) and len(fields) >= 2:
            self.send_original_packet(opcode, self._original_scalar_action_body(fields))
            return True
        if opcode == op(ServerOpcode.HUO_YUE) and len(fields) >= 2:
            action = self._safe_int(fields[1], -1)
            body = bytearray(struct.pack("<B", action & 0xFF))
            if action == 0 and len(fields) >= 5:
                expected = max(0, self._safe_int(fields[2], 0))
                if len(fields) < 5 + expected:
                    return False
                counts = [
                    self._safe_int(value, 0)
                    for value in fields[3 : 3 + expected]
                ]
                body.extend(struct.pack("<i", expected))
                for value in counts:
                    body.extend(struct.pack("<i", value))
                body.extend(
                    struct.pack(
                        "<ii",
                        self._safe_int(fields[3 + expected], 0),
                        self._safe_int(fields[4 + expected], 0),
                    )
                )
            elif action == 1 and len(fields) >= 3:
                body.extend(struct.pack("<i", self._safe_int(fields[2], 0)))
            elif action == 2 and len(fields) >= 5:
                body.extend(struct.pack("<iii", *(self._safe_int(value, 0) for value in fields[2:5])))
            else:
                return False
            self.send_original_packet(ServerOpcode.HUO_YUE, bytes(body))
            return True
        if opcode == op(ServerOpcode.HUO_DONG_PANEL) and len(fields) >= 2:
            action = self._safe_int(fields[1], -1)
            if action != 0:
                return False
            rows = [row.split("&") for row in (fields[2].split("@") if len(fields) > 2 else []) if row and row != "-"]
            body = bytearray(struct.pack("<Bi", action, len(rows)))
            for values in rows:
                values.extend(["0"] * (6 - len(values)))
                body.extend(
                    struct.pack(
                        "<iii??",
                        self._safe_int(values[0], 0),
                        self._safe_int(values[1], 0),
                        self._safe_int(values[2], 0),
                        values[3].lower() in {"1", "true"},
                        values[4].lower() in {"1", "true"},
                    )
                )
            self.send_original_packet(ServerOpcode.HUO_DONG_PANEL, bytes(body))
            return True
        if opcode == op(ServerOpcode.CARD_ACTION) and len(fields) >= 3:
            action = self._safe_int(fields[1], -1)
            body = bytearray(struct.pack("<B", action & 0xFF))
            if action == 0:
                rows = [row.split("&") for row in fields[3].split("@") if row and row != "-"] if len(fields) > 3 else []
                body.extend(struct.pack("<ii", self._safe_int(fields[2], 0), len(rows)))
                for values in rows:
                    values.extend(["0", "0"])
                    body.extend(struct.pack("<i?", self._safe_int(values[0], 0), self._safe_int(values[1], 0) != 0))
            elif action == 1 and len(fields) >= 7:
                rows = [row.split("&") for row in fields[6].split("@") if row and row != "-"]
                body.extend(
                    struct.pack(
                        "<ii??i",
                        self._safe_int(fields[2], 0),
                        self._safe_int(fields[3], 0),
                        self._safe_int(fields[4], 0) != 0,
                        self._safe_int(fields[5], 0) != 0,
                        len(rows),
                    )
                )
                for values in rows:
                    values.extend(["0", "0"])
                    body.extend(struct.pack("<ii", self._safe_int(values[0], 0), self._safe_int(values[1], 0)))
            else:
                return False
            self.send_original_packet(ServerOpcode.CARD_ACTION, bytes(body))
            return True
        if opcode == op(ServerOpcode.CHENG_JIU) and len(fields) >= 2:
            return self._send_original_achievement_text(fields)
        if opcode == op(ServerOpcode.FUDAI) and len(fields) >= 2:
            return self._send_original_fudai_text(fields)
        if opcode == op(ServerOpcode.MAI) and len(fields) >= 2:
            return self._send_original_mai_text(fields)
        if opcode == op(ServerOpcode.LING) and len(fields) >= 3:
            action = self._safe_int(fields[1], -1)
            success = self._safe_int(fields[2], 0)
            body = bytearray(struct.pack("<Bi", action & 0xFF, success))
            if action == op(LingQiAction.LING_HUA):
                rows = [
                    row.split("&")
                    for row in (fields[3].split("@") if len(fields) > 3 else [])
                    if row and row != "-"
                ]
                body.extend(struct.pack("<i", len(rows)))
                for values in rows:
                    values.extend(["0", "0"])
                    body.extend(
                        struct.pack(
                            "<ii",
                            self._safe_int(values[0], 0),
                            self._safe_int(values[1], 0),
                        )
                    )
            elif action == op(LingQiAction.WASH):
                rows = [
                    row.split("&")
                    for row in (fields[3].split("@") if len(fields) > 3 else [])
                    if row and row != "-"
                ]
                body.extend(struct.pack("<ii", 0, len(rows)))
                for values in rows:
                    values.extend(["0", "0"])
                    body.extend(
                        struct.pack(
                            "<ii",
                            self._safe_int(values[0], 0),
                            self._safe_int(values[1], 0),
                        )
                    )
            elif action not in {op(LingQiAction.KAI_GUANG), op(LingQiAction.COMBINE)}:
                return False
            self.send_original_packet(ServerOpcode.LING, bytes(body))
            return True
        if opcode == op(ServerOpcode.BUFF_HECHENG) and len(fields) >= 3:
            action = self._safe_int(fields[1], 0)
            result = self._safe_int(fields[2], 0)
            data = {"buffItemId": result} if action == 2 else {}
            self.send_original_packet(
                ServerOpcode.BUFF_HECHENG,
                struct.pack("<i", action)
                + build_original_object_buffer(data),
            )
            return True
        if opcode == op(ServerOpcode.BANGHUI) and len(fields) >= 2:
            action = self._safe_int(fields[1], 0)
            data: dict[str, Any]
            if len(fields) == 3 and fields[2].startswith("{"):
                try:
                    parsed = json.loads(fields[2])
                    data = parsed if isinstance(parsed, dict) else {"value": parsed}
                except (ValueError, json.JSONDecodeError):
                    data = {"value": fields[2]}
            else:
                data = {"fields": fields[2:]}
            self.send_original_packet(
                ServerOpcode.BANGHUI,
                struct.pack("<H", action & 0xFFFF) + build_original_object_buffer(data),
            )
            return True
        return False

    def _send_original_achievement_text(self, fields: list[str]) -> bool:
        action = self._safe_int(fields[1], -1)
        body = bytearray(struct.pack("<B", action & 0xFF))
        if action == 0 and len(fields) >= 6:
            rows = [row.split("&") for row in fields[5].split("@") if row and row != "-"]
            body.extend(
                struct.pack(
                    "<4i",
                    self._safe_int(fields[2], 0),
                    self._safe_int(fields[3], 0),
                    self._safe_int(fields[4], 0),
                    len(rows),
                )
            )
            for values in rows:
                values.extend(["0", "0"])
                body.extend(struct.pack("<ii", self._safe_int(values[0], 0), self._safe_int(values[1], 0)))
        elif action == 1:
            rows = [row.split("&") for row in (fields[2].split("@") if len(fields) > 2 else []) if row and row != "-"]
            body.extend(struct.pack("<i", len(rows)))
            for values in rows:
                values.extend(["0", "0"])
                body.extend(struct.pack("<ii", self._safe_int(values[0], 0), self._safe_int(values[1], 0)))
        elif action == 3 and len(fields) >= 4:
            body.extend(struct.pack("<i", self._safe_int(fields[2], 0)))
            body.extend(self._original_utf(fields[3]))
        elif action == 4 and len(fields) >= 3:
            body.extend(struct.pack("<i", self._safe_int(fields[2], 0)))
        elif action == 2 and len(fields) >= 6:
            body.extend(struct.pack("<ii?i", self._safe_int(fields[2], 0), self._safe_int(fields[3], 0), fields[4].lower() in {"1", "true"}, self._safe_int(fields[5], 0)))
        else:
            return False
        self.send_original_packet(ServerOpcode.CHENG_JIU, bytes(body))
        return True

    def _original_item_node(self, raw: str) -> bytes:
        """Encode ItemNode with the concrete IItem object used by reward cells."""
        if raw in {"", "-"}:
            return struct.pack("<ihhB", 0, 0, 0, 0)
        values = raw.split("&")
        item_id = self._safe_int(values[1], 0) if len(values) > 1 else 0
        slot = self._safe_int(values[2], 0) if len(values) > 2 else 0
        quantity = max(1, self._safe_int(values[3], 1)) if len(values) > 3 else 1
        unique_id = self._safe_int(values[9], 0) if len(values) > 9 else 0
        aptitude = self._safe_int(values[10], 0) if len(values) > 10 else 0
        star = self._safe_int(values[22], 0) if len(values) > 22 else 0
        item = InventoryItem(
            item_id=item_id,
            slot=slot,
            quantity=quantity,
            unique_id=unique_id,
            aptitude=max(1, aptitude) if aptitude else 2,
            max_endure=self._safe_int(values[11], 100) if len(values) > 11 else 100,
            endure=self._safe_int(values[12], 100) if len(values) > 12 else 100,
            base_attr_type=self._safe_int(values[13], op(EquipmentAttribute.ATTACK))
            if len(values) > 13
            else op(EquipmentAttribute.ATTACK),
            base_attr_value=self._safe_int(values[14], 40) if len(values) > 14 else 40,
            born_attr_value=self._safe_int(values[15], 0) if len(values) > 15 else 0,
            strength_value=self._safe_int(values[16], 0) if len(values) > 16 else 0,
            strength_level=max(0, star),
            strength_info=[True] * max(0, star),
        )
        return struct.pack("<ihh", item_id, aptitude, star) + self._original_item_payload(item)

    def _send_original_fudai_text(self, fields: list[str]) -> bool:
        action = self._safe_int(fields[1], -1)
        body = bytearray(struct.pack("<B", action & 0xFF))
        if action in {1, 17} and len(fields) >= 6:
            candidates = [row for row in fields[4].split("@") if row and row != "-"]
            body.extend(struct.pack("<B", self._safe_int(fields[2], 0) & 0xFF))
            body.extend(self._original_item_node(fields[3]))
            body.extend(struct.pack("<H", len(candidates)))
            for row in candidates:
                body.extend(self._original_item_node(row))
            body.extend(struct.pack("<B", self._safe_int(fields[5], 0) & 0xFF))
        elif action in {2, 18} and len(fields) >= 4:
            body.extend(struct.pack("<Bi", self._safe_int(fields[2], 0) & 0xFF, self._safe_int(fields[3], 0)))
        elif action in {33, 34}:
            pass
        else:
            return False
        self.send_original_packet(ServerOpcode.FUDAI, bytes(body))
        return True

    def _send_original_mai_text(self, fields: list[str]) -> bool:
        action = self._safe_int(fields[1], -1)
        body = bytearray(struct.pack("<B", action & 0xFF))
        if action == 1 and len(fields) >= 5:
            body.extend(struct.pack("<ii?", self._safe_int(fields[2], 0), self._safe_int(fields[3], 0), fields[4].lower() in {"1", "true"}))
        elif action == 2 and len(fields) >= 5:
            body.extend(struct.pack("<iii", *(self._safe_int(value, 0) for value in fields[2:5])))
        elif action == 4 and len(fields) >= 5:
            body.extend(struct.pack("<iBi", self._safe_int(fields[2], 0), self._safe_int(fields[3], 0) & 0xFF, self._safe_int(fields[4], 0)))
        elif action == 3 and len(fields) >= 9:
            exploded = [row.split("&") for row in fields[3].split("@") if row and row != "-"]
            attributes = [row.split("&") for row in fields[4].split("@") if row and row != "-"]
            body.extend(struct.pack("<hhh", self._safe_int(fields[2], 0), self._safe_int(fields[6], 0), self._safe_int(fields[5], 0)))
            body.extend(struct.pack("<d", float(self._safe_int(fields[7], 0))))
            body.extend(struct.pack("<h", len(attributes)))
            for values in attributes:
                values.extend(["0", "0"])
                body.extend(struct.pack("<Bh", self._safe_int(values[0], 0) & 0xFF, self._safe_int(values[1], 0)))
            body.extend(struct.pack("<h", len(exploded)))
            for values in exploded:
                values.extend(["0", "0"])
                body.extend(struct.pack("<hh", self._safe_int(values[0], 0), self._safe_int(values[1], 0)))
            body.extend(struct.pack("<h", self._safe_int(fields[8], 0)))
        elif action == 5 and len(fields) >= 8:
            attributes = [
                row.split("&", 1)
                for row in fields[3].split("@")
                if row and row != "-"
            ]
            body.extend(struct.pack("<iH", self._safe_int(fields[2], 0), len(attributes)))
            for values in attributes:
                values.extend(["0", "0"])
                value = max(-32768, min(32767, self._safe_int(values[1], 0)))
                body.extend(
                    struct.pack(
                        "<Bh",
                        self._safe_int(values[0], 0) & 0xFF,
                        value,
                    )
                )
            item_count = max(-32768, min(32767, self._safe_int(fields[6], 0)))
            body.extend(
                struct.pack(
                    "<iihi",
                    self._safe_int(fields[4], 0),
                    self._safe_int(fields[5], 0),
                    item_count,
                    self._safe_int(fields[7], 0),
                )
            )
        else:
            return False
        self.send_original_packet(ServerOpcode.MAI, bytes(body))
        return True

    @staticmethod
    def _original_spirit_item(values: list[str]) -> bytes:
        """Encode CocoSpirit.decode's slot/id/color/exp/level field order."""
        values = values + ["0"] * max(0, 5 - len(values))
        return struct.pack(
            "<5i",
            FakeFlashSession._safe_int(values[2], 0),
            FakeFlashSession._safe_int(values[0], 0),
            FakeFlashSession._safe_int(values[1], 0),
            FakeFlashSession._safe_int(values[3], 0),
            FakeFlashSession._safe_int(values[4], 0),
        )

    def _send_original_spirit_text(self, fields: list[str]) -> bool:
        """Encode every response emitted by the shared spirit gameplay loop."""
        command = self._safe_int(fields[1], -1)
        body = bytearray(struct.pack("<b", command))
        if command == 0 and len(fields) >= 6:
            statuses = [
                self._safe_int(value, 0)
                for value in fields[5].split("@")
                if value and value != "-"
            ]
            body.extend(struct.pack("<i", len(statuses)))
            for status in statuses:
                body.extend(struct.pack("<i", status))
            body.extend(
                struct.pack(
                    "<i?i",
                    self._safe_int(fields[2], 0),
                    fields[4].lower() in {"1", "true"},
                    self._safe_int(fields[3], 0),
                )
            )
        elif command == 1 and len(fields) >= 3:
            item_ids = [
                self._safe_int(value, 0)
                for value in fields[2].split("@")
                if value and value != "-"
            ]
            body.extend(struct.pack("<i", len(item_ids)))
            for item_id in item_ids:
                body.extend(struct.pack("<i", item_id))
        elif command in {2, 4} and len(fields) >= 7:
            body.extend(self._original_spirit_item(fields[2:7]))
        elif command == 3 and len(fields) >= 3:
            body.extend(struct.pack("<i", self._safe_int(fields[2], 0)))
        elif command == 5 and len(fields) >= 4:
            body.extend(
                struct.pack(
                    "<ii",
                    self._safe_int(fields[2], 0),
                    self._safe_int(fields[3], 0),
                )
            )
        elif command == 6 and len(fields) >= 4:
            body.extend(
                struct.pack(
                    "<ii",
                    self._safe_int(fields[2], 0),
                    self._safe_int(fields[3], 0),
                )
            )
        elif command == 7 and len(fields) >= 4:
            rows = [
                row.split("&")
                for row in fields[3].split("@")
                if row and row != "-"
            ]
            body.extend(
                struct.pack(
                    "<?i",
                    fields[2].lower() in {"1", "true"},
                    len(rows),
                )
            )
            for values in rows:
                body.extend(self._original_spirit_item(values))
        elif command == 8 and len(fields) >= 3:
            rows = [
                row.split("&")
                for row in fields[2].split("@")
                if row and row != "-"
            ]
            body.extend(struct.pack("<i", len(rows)))
            for values in rows:
                values.extend(["0", "0"])
                body.extend(
                    struct.pack(
                        "<ii",
                        self._safe_int(values[0], 0),
                        self._safe_int(values[1], 0),
                    )
                )
        else:
            return False
        self.send_original_packet(ServerOpcode.SPIRIT_ACTION, bytes(body))
        return True

    def _send_original_local_pk_text(self, fields: list[str]) -> bool:
        """Encode every LocalPkProcessor action emitted by the shared match loop."""
        action = self._safe_int(fields[1], -1)
        body = bytearray(struct.pack("<b", action))
        if action == 0 and len(fields) >= 12:
            body.extend(
                struct.pack(
                    "<5i",
                    *(self._safe_int(value, 0) for value in fields[2:7]),
                )
            )
            prizes = [
                self._safe_int(value, 0)
                for value in fields[7].split("@")
                if value and value != "-"
            ]
            body.extend(struct.pack("<i", len(prizes)))
            for prize in prizes:
                body.extend(struct.pack("<i", prize))
            body.extend(
                struct.pack(
                    "<4i",
                    *(self._safe_int(value, 0) for value in fields[8:12]),
                )
            )
        elif action == 1 and len(fields) >= 3:
            body.extend(
                struct.pack("<?", fields[2].lower() in {"1", "true"})
            )
        elif action == 2 and len(fields) >= 5:
            body.extend(
                struct.pack(
                    "<?ii",
                    fields[2].lower() in {"1", "true"},
                    self._safe_int(fields[3], 0),
                    self._safe_int(fields[4], 0),
                )
            )
        elif action == 3 and len(fields) >= 5:
            body.extend(
                struct.pack(
                    "<3i",
                    *(self._safe_int(value, 0) for value in fields[2:5]),
                )
            )
        elif action in {4, 5, 6} and len(fields) >= 3:
            body.extend(struct.pack("<i", self._safe_int(fields[2], 0)))
        else:
            return False
        self.send_original_packet(ServerOpcode.LOCAL_PK_ACTION, bytes(body))
        return True

    def _original_muye_player(self, values: list[str]) -> bytes:
        values = values + ["0"] * max(0, 5 - len(values))
        return b"".join(
            (
                struct.pack("<i", self._safe_int(values[0], 0)),
                self._original_utf(values[1]),
                struct.pack(
                    "<3i",
                    self._safe_int(values[2], 0),
                    self._safe_int(values[3], 0),
                    self._safe_int(values[4], 0),
                ),
            )
        )

    def _send_original_muye_battle_text(self, fields: list[str]) -> bool:
        """Encode every MuyeBattleProcessor response used by the shared battle."""
        action = self._safe_int(fields[1], -1)
        body = bytearray(struct.pack("<B", action & 0xFF))
        fixed_widths = {0: 2, 1: 5, 4: 3, 5: 1, 6: 3, 7: 9, 8: 1, 9: 1, 10: 1, 11: 1}
        if action in fixed_widths:
            width = fixed_widths[action]
            if len(fields) < width + 2:
                return False
            body.extend(
                struct.pack(
                    f"<{width}i",
                    *(self._safe_int(value, 0) for value in fields[2 : width + 2]),
                )
            )
        elif action == 2 and len(fields) >= 7:
            body.extend(self._original_muye_player(fields[2:7]))
        elif action == 3 and len(fields) >= 3:
            rows = [
                row.split("&")
                for row in fields[2].split("@")
                if row and row != "-"
            ]
            body.extend(struct.pack("<i", len(rows)))
            for values in rows:
                body.extend(self._original_muye_player(values))
        else:
            return False
        self.send_original_packet(ServerOpcode.MUYE_BATTLE, bytes(body))
        return True

    def _original_copy_player(self, values: list[str]) -> bytes:
        values = values + ["0"] * max(0, 7 - len(values))
        return b"".join(
            (
                struct.pack(
                    "<ii",
                    self._safe_int(values[0], 0),
                    self._safe_int(values[1], 0),
                ),
                self._original_utf(values[2]),
                struct.pack(
                    "<ii",
                    self._safe_int(values[3], 0),
                    self._safe_int(values[4], 0),
                ),
                self._original_utf(values[5]),
                struct.pack("<i", self._safe_int(values[6], 0)),
            )
        )

    def _original_war_stat_player(self, values: list[str], end: bool) -> bytes:
        width = 12 if end else 9
        values = values + ["0"] * max(0, width - len(values))
        numeric_tail = values[3:width]
        return b"".join(
            (
                struct.pack(
                    "<ii",
                    self._safe_int(values[0], 0),
                    self._safe_int(values[1], 0),
                ),
                self._original_utf(values[2]),
                struct.pack(
                    f"<{len(numeric_tail)}i",
                    *(self._safe_int(value, 0) for value in numeric_tail),
                ),
            )
        )

    def _send_original_war_3v3_text(self, opcode: int, fields: list[str]) -> bool:
        """Encode the shared 3v3 registration, countdown, and scoreboard packets."""
        if opcode == op(ServerOpcode.WAR_3V3_PANEL_ACTION) and len(fields) >= 2:
            action = self._safe_int(fields[1], -1)
            body = bytearray(struct.pack("<B", action & 0xFF))
            if action == 0 and len(fields) >= 11:
                body.extend(struct.pack("<i", self._safe_int(fields[2], 0)))
                body.extend(self._original_copy_player(fields[3:10]))
                rows = [
                    row.split("&")
                    for row in fields[10].split("@")
                    if row and row != "-"
                ]
                body.extend(struct.pack("<i", len(rows)))
                for values in rows:
                    body.extend(self._original_copy_player(values))
            elif action == 1 and len(fields) >= 4:
                body.extend(
                    struct.pack(
                        "<ii",
                        self._safe_int(fields[2], 0),
                        self._safe_int(fields[3], 0),
                    )
                )
            elif action == 2 and len(fields) >= 3:
                body.extend(struct.pack("<i", self._safe_int(fields[2], 0)))
            else:
                return False
            self.send_original_packet(ServerOpcode.WAR_3V3_PANEL_ACTION, bytes(body))
            return True
        if opcode == op(ServerOpcode.WAR_3V3_COUNT_DOWN) and len(fields) >= 3:
            self.send_original_packet(
                ServerOpcode.WAR_3V3_COUNT_DOWN,
                struct.pack(
                    "<ii",
                    self._safe_int(fields[1], 0),
                    self._safe_int(fields[2], 0),
                ),
            )
            return True
        if opcode == op(ServerOpcode.WAR_3V3_SOMEONE_LEAVE_MATCHING):
            self.send_original_packet(ServerOpcode.WAR_3V3_SOMEONE_LEAVE_MATCHING, b"")
            return True
        if opcode == op(ServerOpcode.WAR_3V3_START_INFO) and len(fields) >= 2:
            self.send_original_packet(
                ServerOpcode.WAR_3V3_START_INFO,
                struct.pack("<i", self._safe_int(fields[1], 0)),
            )
            return True
        if opcode in {
            op(ServerOpcode.WAR_3V3_STATICS_DURING),
            op(ServerOpcode.WAR_3V3_STATICS_END),
        }:
            end = opcode == op(ServerOpcode.WAR_3V3_STATICS_END)
            minimum = 5 if end else 4
            if len(fields) < minimum:
                return False
            rows = [
                row.split("&")
                for row in fields[4 if end else 3].split("@")
                if row and row != "-"
            ]
            width = 12 if end else 9
            while len(rows) < 6:
                rows.append(["0", "0", ""] + ["0"] * (width - 3))
            header_values = fields[1:4] if end else fields[1:3]
            body = bytearray(
                struct.pack(
                    f"<{len(header_values)}i",
                    *(self._safe_int(value, 0) for value in header_values),
                )
            )
            for values in rows[:6]:
                body.extend(self._original_war_stat_player(values, end))
            self.send_original_packet(opcode, bytes(body))
            return True
        return False

    def _send_original_pet_text(self, fields: list[str]) -> bool:
        """Encode every pet response currently emitted by the shared pet handler."""
        action = self._safe_int(fields[1], -1)
        body = bytearray(struct.pack("<B", action & 0xFF))
        if action == op(PetResponseAction.INITIAL_LIST):
            pets = sorted(self.store.state.pets.values(), key=lambda value: value.unique_id)
            body.extend(struct.pack("<ii", self._safe_int(fields[2], 10), len(pets)))
            for pet in pets:
                body.extend(self._original_pet_payload(pet))
        elif action in {
            op(PetResponseAction.CREATE),
            op(PetResponseAction.UPDATE),
            op(PetResponseAction.EVOLUTION_UP),
        }:
            unique_id = self._safe_int(fields[10], 0) if len(fields) > 10 else 0
            pet = self.store.state.pets.get(unique_id)
            if pet is None:
                return True
            body.extend(self._original_pet_payload(pet))
        elif action == op(PetResponseAction.DELETE) and len(fields) >= 3:
            body.extend(struct.pack("<d", float(self._safe_int(fields[2], 0))))
        elif action in {op(PetResponseAction.SHOW), op(PetResponseAction.ATTACH)} and len(fields) >= 12:
            body.extend(
                struct.pack(
                    "<idi",
                    self._safe_int(fields[2], self.character.character_id),
                    float(fields[3]),
                    self._safe_int(fields[4], 0),
                )
            )
            body.extend(self._original_utf(fields[5]))
            body.extend(
                struct.pack(
                    "<hhBiii",
                    self._safe_int(fields[6], 0),
                    self._safe_int(fields[7], 0),
                    self._safe_int(fields[8], 0) & 0xFF,
                    self._safe_int(fields[9], 0),
                    self._safe_int(fields[10], 0),
                    self._safe_int(fields[11], 0),
                )
            )
        elif action == op(PetResponseAction.UNSHOW) and len(fields) >= 5:
            body.extend(struct.pack("<idi", self._safe_int(fields[2], 0), float(fields[3]), self._safe_int(fields[4], 0)))
        elif action == op(PetResponseAction.LEVEL_UP) and len(fields) >= 4:
            body.extend(struct.pack("<id", self._safe_int(fields[2], 0), float(fields[3])))
        elif action == op(PetResponseAction.UPDATE_NAME) and len(fields) >= 5:
            body.extend(struct.pack("<id", self._safe_int(fields[2], 0), float(fields[3])))
            body.extend(self._original_utf(fields[4]))
        elif action == op(PetResponseAction.UPDATE_STATS) and len(fields) >= 5:
            rows = [
                row.split("&")
                for row in fields[4].split("@")
                if row and row != "-"
            ]
            body.extend(
                struct.pack(
                    "<idH",
                    self._safe_int(fields[2], 0),
                    float(fields[3]),
                    len(rows),
                )
            )
            for values in rows:
                values.extend(["0"] * (2 - len(values)))
                body.extend(
                    struct.pack(
                        "<Bi",
                        self._safe_int(values[0], 0) & 0xFF,
                        self._safe_int(values[1], 0),
                    )
                )
        elif action == op(PetResponseAction.UPDATE_SKILL) and len(fields) >= 7:
            body.extend(
                struct.pack(
                    "<idiii",
                    self._safe_int(fields[2], 0),
                    float(fields[3]),
                    self._safe_int(fields[4], 0),
                    self._safe_int(fields[5], 0),
                    self._safe_int(fields[6], 0),
                )
            )
        elif action == op(PetResponseAction.UPDATE_EQUIPMENT) and len(fields) >= 5:
            raw_item = fields[4].split("&")
            position = self._safe_int(raw_item[2], 0) if len(raw_item) > 2 else 0
            pet = self.store.state.pets.get(self._safe_int(fields[3], 0))
            item = pet.equipment.get(position) if pet is not None else None
            if item is None:
                return True
            body.extend(
                struct.pack(
                    "<idB",
                    self._safe_int(fields[2], 0),
                    float(fields[3]),
                    position & 0xFF,
                )
            )
            body.extend(self._original_item_payload(item)[1:])
        elif action == op(PetResponseAction.REMOVE_EQUIPMENT) and len(fields) >= 5:
            body.extend(struct.pack("<idB", self._safe_int(fields[2], 0), float(fields[3]), self._safe_int(fields[4], 0) & 0xFF))
        elif action == op(PetResponseAction.UPDATE_SKILL_LIST) and len(fields) >= 5:
            rows = [row for row in fields[4].split("@") if row and row != "-"]
            body.extend(struct.pack("<idi", self._safe_int(fields[2], 0), float(fields[3]), len(rows)))
            for row in rows:
                values = row.split("&")
                values.extend(["0"] * (3 - len(values)))
                body.extend(struct.pack("<iii", *(self._safe_int(value, 0) for value in values[:3])))
        elif action == op(PetResponseAction.EVOLUTION_RESULT) and len(fields) >= 5:
            body.extend(struct.pack("<idi", self._safe_int(fields[2], 0), float(fields[3]), self._safe_int(fields[4], 0)))
        else:
            return False
        self.send_original_packet(ServerOpcode.PET_ACTION, bytes(body))
        return True

    def _quest_progress_value_from_text(
        self,
        kind: str,
        encoded: str,
        row_separator: str,
        field_separator: str,
    ) -> Any:
        """Decode the legacy text bridge into Nya's captured AMF progress value."""
        rows: list[tuple[str, int, int]] = []
        for row in encoded.split(row_separator) if encoded != "-" else ():
            values = row.split(field_separator)
            if len(values) < 3:
                continue
            rows.append(
                (
                    values[0],
                    self._safe_int(values[1], 0),
                    self._safe_int(values[2], 0),
                )
            )
        if kind in {QuestObjectiveKind.LEVEL.value, "charge"}:
            maximum_index = max(
                (self._safe_int(key, 0) for key, _, _ in rows),
                default=0,
            )
            result = [0] * (maximum_index + 1)
            for key, current, _ in rows:
                result[self._safe_int(key, 0)] = current
            return result
        return {
            key: {"curr": current, "count": count}
            for key, current, count in rows
        }

    def _send_original_quest_text(self, fields: list[str]) -> bool:
        """Encode all QuestProcessor list and progress response actions."""
        action = self._safe_int(fields[1], -1)
        body = bytearray(struct.pack("<B", action & 0xFF))
        if action == op(QuestListUpdateAction.CAN_START_LIST):
            rows = [
                self._safe_int(value, 0)
                for value in (fields[2].split("@") if len(fields) > 2 else [])
                if value and value != "-"
            ]
            body.extend(struct.pack("<H", len(rows)))
            for quest_id in rows:
                body.extend(struct.pack("<i", quest_id))
        elif action == op(QuestListUpdateAction.STARTED_LIST):
            rows = [row for row in (fields[2].split("@") if len(fields) > 2 else []) if row and row != "-"]
            body.extend(struct.pack("<H", len(rows)))
            for row in rows:
                values = row.split("&")
                values.extend(["0", "-", "0"])
                kind = values[2]
                progress = {
                    kind: self._quest_progress_value_from_text(
                        kind,
                        values[3],
                        "!",
                        "+",
                    )
                }
                body.extend(struct.pack("<iB", self._safe_int(values[0], 0), self._safe_int(values[1], 0) & 0xFF))
                body.extend(build_original_object_buffer(progress))
                loop_id = self._safe_int(values[4], 0)
                body.extend(struct.pack("<h", loop_id))
                if loop_id > 0:
                    body.extend(build_original_object_buffer({}))
                    body.extend(struct.pack("<h", self._safe_int(values[6], 0)))
        elif action == op(QuestListUpdateAction.SINGLE_PROGRESS) and len(fields) >= 6:
            body.extend(struct.pack("<ii", self._safe_int(fields[2], 0), self._safe_int(fields[3], 0)))
            body.extend(self._original_utf(fields[4]))
            body.extend(
                build_original_object_buffer(
                    self._quest_progress_value_from_text(
                        fields[4],
                        fields[5],
                        "@",
                        "&",
                    )
                )
            )
        elif action == op(QuestListUpdateAction.ALL_PROGRESS) and len(fields) >= 6:
            body.extend(struct.pack("<iB", self._safe_int(fields[2], 0), self._safe_int(fields[3], 0) & 0xFF))
            body.extend(
                build_original_object_buffer(
                    {
                        fields[4]: self._quest_progress_value_from_text(
                            fields[4],
                            fields[5],
                            "@",
                            "&",
                        )
                    }
                )
            )
            body.extend(struct.pack("<h", 0))
        else:
            return False
        self.send_original_packet(ServerOpcode.QUEST_INFO_UPDATE, bytes(body))
        return True

    def _send_original_tutor_text(self, fields: list[str]) -> bool:
        """Encode the AMF3 objects consumed by Nya's TutorProcessor."""
        if len(fields) < 2:
            return False
        action = self._safe_int(fields[1], -1)
        if action == 20:
            target_id = self._safe_int(fields[2], -1) if len(fields) > 2 else -1
            target = self._character_info_session(target_id)
            if target is None:
                return False
            online = 1 if target.hub is not None and target.hub.session_for_character(target_id) else 0
            body = bytearray(struct.pack("<B", action))
            body.extend(target._original_character_full_info_payload())
            body.extend(struct.pack("<ii", 0, online))
            self.send_original_packet(ServerOpcode.TUTOR, bytes(body))
            return True

        data: dict[str, Any]
        if action in {1, 2}:
            rows = fields[2].split("@") if len(fields) > 2 and fields[2] != "-" else []
            people = []
            for row in rows:
                values = row.split("&")
                values.extend(["0"] * (4 - len(values)))
                people.append(
                    {
                        "charId": self._safe_int(values[0], 0),
                        "name": values[1],
                        "level": self._safe_int(values[2], 1),
                        "job": self._safe_int(values[3], 300),
                    }
                )
            data = {"tutors" if action == 1 else "students": people}
        elif action in {4, 5}:
            data = {
                "charId": self._safe_int(fields[2], 0) if len(fields) > 2 else 0,
                "name": fields[3] if len(fields) > 3 else "",
            }
        elif action == 14:
            relations = []
            rows = fields[2].split("@") if len(fields) > 2 and fields[2] != "-" else []
            for row in rows:
                values = row.split("&")
                values.extend(["0"] * (11 - len(values)))
                relations.append(
                    {
                        "charId": self._safe_int(values[0], 0),
                        "name": values[1],
                        "level": self._safe_int(values[2], 1),
                        "job": self._safe_int(values[3], 300),
                        "face": self._safe_int(values[4], 0),
                        "channelId": self._safe_int(values[5], -1),
                        "gender": self._safe_int(values[6], 0),
                        "type": self._safe_int(values[7], 0),
                        "degree": self._safe_int(values[8], 0),
                        "isCouple": bool(self._safe_int(values[9], 0)),
                        "contactTime": float(self._safe_int(values[10], 0)),
                    }
                )
            data = {"relations": relations}
        elif action == 15:
            values = fields[2:9]
            values.extend(["0"] * (7 - len(values)))
            data = {
                "autoAcceptStudent": self._safe_int(values[0], 0),
                "autoAcceptTutor": self._safe_int(values[1], 0),
                "autoRefuseStudent": self._safe_int(values[2], 2),
                "autoRefuseTutor": self._safe_int(values[3], 2),
                "myExp": self._safe_int(values[4], 0),
                "myFame": self._safe_int(values[5], 0),
                "fame": self._safe_int(values[6], 0),
            }
        elif action == 16:
            values = fields[2:7]
            values.extend(["0"] * (5 - len(values)))
            data = {
                "charId": self._safe_int(values[0], 0),
                "exp": self._safe_int(values[1], 0),
                "fame": self._safe_int(values[2], 0),
                "level": self._safe_int(values[3], 1),
                "name": values[4],
            }
        elif action in {17, 18}:
            rows = fields[2].split("@") if len(fields) > 2 and fields[2] != "-" else []
            people = []
            for row in rows:
                values = row.split("&")
                values.extend(["0"] * (4 - len(values)))
                people.append(
                    {
                        "name": values[0],
                        "charId": self._safe_int(values[1], 0),
                        "face": self._safe_int(values[2], 0),
                        "level": self._safe_int(values[3], 1),
                    }
                )
            data = {"tutors" if action == 17 else "students": people}
            data["count"] = self._safe_int(fields[3], len(people)) if len(fields) > 3 else len(people)
        elif action == 19:
            data = {"gains": []}
        elif 1 <= action <= 19:
            data = {}
        else:
            return False
        self.send_original_packet(
            ServerOpcode.TUTOR,
            struct.pack("<B", action) + build_original_object_buffer(data),
        )
        return True

    def _original_pk_candidate_payload(self, raw_row: str) -> bytes:
        values = raw_row.split("&")
        values.extend(["0"] * (12 - len(values)))
        return b"".join(
            (
                struct.pack(
                    "<4i",
                    self._safe_int(values[0], 0),
                    self._safe_int(values[1], 0),
                    self._safe_int(values[2], 0),
                    self._safe_int(values[3], 1),
                ),
                self._original_utf(values[4]),
                struct.pack(
                    "<B6i",
                    1 if self._safe_int(values[5], 0) else 0,
                    *(self._safe_int(value, 0) for value in values[6:12]),
                ),
            )
        )

    def _original_pk_report_payload(self, values: list[str]) -> bytes:
        values = list(values)
        values.extend(["0"] * (8 - len(values)))
        return b"".join(
            (
                struct.pack("<2i", self._safe_int(values[0], 0), self._safe_int(values[1], 0)),
                self._original_utf(values[2]),
                struct.pack("<i", self._safe_int(values[3], 0)),
                self._original_utf(values[4]),
                struct.pack("<3i", *(self._safe_int(value, 0) for value in values[5:8])),
            )
        )

    def _send_original_pk_text(self, fields: list[str]) -> bool:
        """Encode every response action registered by Nya's PkProcessor."""
        if len(fields) < 2:
            return False
        action = self._safe_int(fields[1], -1)
        body = bytearray(struct.pack("<B", action & 0xFF))
        if action == 0 and len(fields) >= 10:
            candidates = [] if fields[8] == "-" else fields[8].split("@")
            reports = [] if fields[9] == "-" else fields[9].split("@")
            body.extend(struct.pack("<i", self._safe_int(fields[7], 0)))
            body.extend(struct.pack("<i", len(candidates)))
            for row in candidates:
                body.extend(self._original_pk_candidate_payload(row))
            body.extend(struct.pack("<i", len(reports)))
            for row in reports:
                body.extend(self._original_pk_report_payload(row.split("&")))
            body.extend(struct.pack("<5i", *(self._safe_int(value, 0) for value in fields[2:7])))
        elif action == 1 and len(fields) >= 3:
            body.extend(struct.pack("<i", self._safe_int(fields[2], 0)))
        elif action == 2 and len(fields) >= 3:
            rows = [] if fields[2] == "-" else fields[2].split("@")
            body.extend(struct.pack("<i", len(rows)))
            for row in rows:
                body.extend(self._original_pk_candidate_payload(row))
        elif action == 3 and len(fields) >= 3:
            rows = [] if fields[2] == "-" else fields[2].split("@")
            body.extend(struct.pack("<i", len(rows)))
            for row in rows:
                body.extend(self._original_pk_report_payload(row.split("&")))
        elif action == 4 and len(fields) >= 7:
            body.extend(struct.pack("<5i", *(self._safe_int(value, 0) for value in fields[2:7])))
        elif action in {5, 6} and len(fields) >= 3:
            body.extend(struct.pack("<i", self._safe_int(fields[2], 0)))
        elif action == 7 and len(fields) >= 4:
            body.extend(struct.pack("<?i", bool(self._safe_int(fields[2], 0)), self._safe_int(fields[3], 0)))
        elif action == 8 and len(fields) >= 4:
            body.extend(struct.pack("<2i", self._safe_int(fields[2], 0), self._safe_int(fields[3], 0)))
        elif action == 9 and len(fields) >= 3:
            rows = [] if fields[2] == "-" else fields[2].split("@")
            body.extend(struct.pack("<i", len(rows)))
            for row in rows:
                values = row.split("&")
                values.extend(["0"] * (5 - len(values)))
                body.extend(struct.pack("<3i", *(self._safe_int(value, 0) for value in values[:3])))
                body.extend(self._original_utf(values[3]))
                body.extend(struct.pack("<B", self._safe_int(values[4], 0) & 0xFF))
        elif action == 10 and len(fields) >= 10:
            body.extend(self._original_pk_report_payload(fields[2:10]))
        elif action == 11 and len(fields) >= 4:
            body.extend(struct.pack("<iB", self._safe_int(fields[2], 0), self._safe_int(fields[3], 0) & 0xFF))
        else:
            return False
        self.send_original_packet(ServerOpcode.PK_ACTION, bytes(body))
        return True

    def _send_original_copy_text(self, fields: list[str]) -> bool:
        """Encode the shared copy lifecycle for Nya's CopyProcessor."""
        if len(fields) < 2:
            return False
        action = self._safe_int(fields[1], -1)
        body = bytearray(struct.pack("<B", action & 0xFF))
        if action == 0 and len(fields) >= 4:
            rows = [] if fields[2] == "-" else fields[2].split("@")
            body.extend(struct.pack("<i", len(rows)))
            for row in rows:
                values = row.split("&")
                values.extend(["0", "0"])
                body.extend(struct.pack("<2i", self._safe_int(values[0], 0), self._safe_int(values[1], 0)))
            body.extend(struct.pack("<i", self._safe_int(fields[3], 0)))
        elif action == 1 and len(fields) >= 4:
            body.extend(struct.pack("<2i", self._safe_int(fields[2], 0), self._safe_int(fields[3], 0)))
        elif action in {2, 6, 10} and len(fields) >= 3:
            body.extend(struct.pack("<i", self._safe_int(fields[2], 0)))
        elif action == 4 and len(fields) >= 5:
            body.extend(struct.pack("<3i", *(self._safe_int(value, 0) for value in fields[2:5])))
        elif action == 5 and len(fields) >= 7:
            body.extend(struct.pack("<5i", *(self._safe_int(value, 0) for value in fields[2:7])))
        elif action == 7 and len(fields) >= 4:
            body.extend(struct.pack("<2i", self._safe_int(fields[2], 0), self._safe_int(fields[3], 0)))
        elif action == 8 and len(fields) >= 4:
            rows = [] if fields[3] == "-" else fields[3].split("@")
            body.extend(struct.pack("<2i", self._safe_int(fields[2], 0), len(rows)))
            for row in rows:
                values = row.split("&")
                values.extend(["0", "0"])
                body.extend(struct.pack("<2i", self._safe_int(values[0], 0), self._safe_int(values[1], 0)))
        elif action == 9 and len(fields) >= 4:
            body.extend(struct.pack("<i?", self._safe_int(fields[2], 0), bool(self._safe_int(fields[3], 0))))
        elif action == 3:
            # The mature server currently uses single-player entry (action 5).
            # Keep the multiplayer confirmation shape available for shared callers.
            if len(fields) < 11:
                return False
            body.extend(struct.pack("<2i", self._safe_int(fields[2], 0), self._safe_int(fields[3], 0)))
            values = fields[4:11]
            body.extend(struct.pack("<2i", self._safe_int(values[0], 0), self._safe_int(values[1], 0)))
            body.extend(self._original_utf(values[2]))
            body.extend(struct.pack("<2i", self._safe_int(values[3], 1), self._safe_int(values[4], 300)))
            body.extend(self._original_utf(values[5]))
            body.extend(struct.pack("<i", self._safe_int(values[6], 0)))
            body.extend(struct.pack("<i", 0))
        else:
            return False
        self.send_original_packet(ServerOpcode.COPY_ACTION, bytes(body))
        return True

    def _send_original_banghui_boss_text(self, fields: list[str]) -> bool:
        if len(fields) < 2:
            return False
        action = self._safe_int(fields[1], -1)
        body = bytearray(struct.pack("<B", action & 0xFF))
        if action == 0 and len(fields) >= 6:
            rows = [] if fields[5] == "-" else fields[5].split("@")
            body.extend(struct.pack("<4i", self._safe_int(fields[2], 0), self._safe_int(fields[3], 0), self._safe_int(fields[4], 0), len(rows)))
            for row in rows:
                body.extend(struct.pack("<i", self._safe_int(row, 0)))
        elif action in {1, 3} and len(fields) >= 3:
            body.extend(struct.pack("<i", self._safe_int(fields[2], 0)))
        elif action == 2 and len(fields) >= 5:
            body.extend(struct.pack("<3i", *(self._safe_int(value, 0) for value in fields[2:5])))
        else:
            return False
        self.send_original_packet(ServerOpcode.BANGHUI_BOSS, bytes(body))
        return True

    def _send_original_banghui_text(self, fields: list[str]) -> bool:
        """Translate mature family responses into BanghuiProcessor AMF3 objects."""
        if len(fields) < 2:
            return False
        action = self._safe_int(fields[1], -1)
        if action == 3 and len(fields) >= 6:
            rows = [] if fields[5] == "-" else fields[5].split("@")
            families = []
            for row in rows:
                values = row.split("&")
                values.extend(["0"] * (12 - len(values)))
                families.append(
                    {
                        "id": self._safe_int(values[0], 0),
                        "channelId": self._safe_int(values[1], -1),
                        "name": values[2],
                        "leader": values[3],
                        "leaderName": values[3],
                        "leaderId": self._safe_int(values[4], 0),
                        "flagLevel": self._safe_int(values[5], 1),
                        "memberCount": self._safe_int(values[6], 0),
                        "memberLimit": self._safe_int(values[7], 50),
                        "maxMemberCount": self._safe_int(values[7], 50),
                        "levelSum": self._safe_int(values[8], 0),
                        "bossSum": self._safe_int(values[9], 0),
                        "flagStyle": self._safe_int(values[10], 1000),
                        "flagName": values[11],
                    }
                )
            body = struct.pack(
                "<H3i",
                action,
                self._safe_int(fields[2], len(families)),
                self._safe_int(fields[3], len(families)),
                self._safe_int(fields[4], 1),
            ) + build_original_object_buffer(families)
            self.send_original_packet(ServerOpcode.BANGHUI, body)
            return True

        data: Any
        if action == 1 and len(fields) >= 14:
            members = []
            for row in ([] if fields[13] == "-" else fields[13].split("@")):
                values = row.split("&")
                values.extend(["0"] * (6 - len(values)))
                members.append(
                    {
                        "name": values[0],
                        "level": self._safe_int(values[1], 1),
                        "rank": self._safe_int(values[2], 4),
                        "contriValue": self._safe_int(values[3], 0),
                        "weeklyContriValue": self._safe_int(values[4], 0),
                        "leftContriValue": self._safe_int(values[5], 0),
                    }
                )
            data = {
                "banghui": {
                    "id": self._safe_int(fields[2], 0),
                    "name": fields[3],
                    "notice": fields[4],
                    "memberCount": self._safe_int(fields[5], 0),
                    "memberLimit": 50,
                    "maxMemberCount": 50,
                    "leader": fields[6],
                    "levelSum": self._safe_int(fields[7], 0),
                    "bossSum": self._safe_int(fields[8], 0),
                    "createTime": float(self._safe_int(fields[9], 0) * 1000),
                },
                "flag": {
                    "level": self._safe_int(fields[10], 1),
                    "name": fields[11],
                    "style": self._safe_int(fields[12], 1000),
                },
                "members": members,
            }
        elif action == 2:
            data = {
                "result": bool(self._safe_int(fields[2], 0)) if len(fields) > 2 else False,
                "id": self._safe_int(fields[3], 0) if len(fields) > 3 else 0,
            }
        elif action == 4:
            data = {
                "name": fields[2] if len(fields) > 2 else "",
                "level": self._safe_int(fields[3], 1) if len(fields) > 3 else 1,
                "style": self._safe_int(fields[4], 1000) if len(fields) > 4 else 1000,
            }
        elif action == 5 and len(fields) >= 5:
            items = []
            for row in fields[3].split(","):
                item_values = row.split("&", 1)
                item_values.extend(["0", "0"])
                item_id = self._safe_int(item_values[0], 0)
                if item_id > 0:
                    items.append(
                        {
                            "id": item_id,
                            "count": self._safe_int(item_values[1], 0),
                        }
                    )
            members = []
            for row in ([] if fields[4] == "-" else fields[4].split("@")):
                values = row.split("&")
                values.extend(["0"] * (11 - len(values)))
                members.append(
                    {
                        "id": self._safe_int(values[0], 0),
                        "name": values[1],
                        "level": self._safe_int(values[2], 1),
                        "rank": self._safe_int(values[3], 4),
                        "shujiCount": self._safe_int(values[4], 0),
                        "contri": {"money": self._safe_int(values[5], 0)},
                        "weeklyShujiCount": self._safe_int(values[6], 0),
                        "weeklyContri": {"money": self._safe_int(values[7], 0)},
                        "channelId": self._safe_int(values[8], -1),
                        "contriValue": self._safe_int(values[9], 0),
                        "weeklyContriValue": self._safe_int(values[10], 0),
                    }
                )
            data = {
                "contri": {
                    "money": self._safe_int(fields[2], 0),
                    "items": items,
                },
                "members": members,
            }
        elif action == 6:
            members = []
            for row in ([] if len(fields) < 3 or fields[2] == "-" else fields[2].split("@")):
                values = row.split("&")
                values.extend(["0"] * (17 - len(values)))
                members.append(
                    {
                        "id": self._safe_int(values[0], 0),
                        "name": values[1],
                        "level": self._safe_int(values[2], 1),
                        "rank": self._safe_int(values[3], 4),
                        "job": self._safe_int(values[4], 300),
                        "face": self._safe_int(values[5], 0),
                        "gender": self._safe_int(values[6], 0),
                        "shujiCount": self._safe_int(values[7], 0),
                        "contriValue": self._safe_int(values[8], 0),
                        "weeklyContriValue": self._safe_int(values[9], 0),
                        "channelId": self._safe_int(values[10], -1),
                        "nick": values[11],
                        "skillValue": self._safe_int(values[12], 0),
                        "maiValue": self._safe_int(values[13], 0),
                        "chengjiuValue": self._safe_int(values[14], 0),
                        "shengwangValue": self._safe_int(values[15], 0),
                        "bossValue": self._safe_int(values[16], 0),
                    }
                )
            data = members
        elif action in {7, 12, 14}:
            data = {
                "id": self._safe_int(fields[2], 0) if len(fields) > 2 else 0,
                "name": fields[3] if len(fields) > 3 else "",
            }
        elif action == 8:
            data = {
                "name": fields[2] if len(fields) > 2 else "",
                "id": self._safe_int(fields[3], 0) if len(fields) > 3 else 0,
                "face": self._safe_int(fields[4], 0) if len(fields) > 4 else 0,
                "level": self._safe_int(fields[5], 1) if len(fields) > 5 else 1,
            }
            data["data"] = dict(data)
        elif action == 9:
            data = {"name": fields[2] if len(fields) > 2 else ""}
        elif action in {10, 11, 18, 22}:
            data = {"id": self._safe_int(fields[2], 0) if len(fields) > 2 else 0}
            if len(fields) > 3:
                data["channelId"] = self._safe_int(fields[3], -1)
            if len(fields) > 4:
                data["rank"] = self._safe_int(fields[4], 4)
        elif action == 13:
            data = {"id": self._safe_int(fields[2], 0) if len(fields) > 2 else 0}
        elif action == 15:
            data = {
                "id": self._safe_int(fields[2], 0) if len(fields) > 2 else 0,
                "name": fields[3] if len(fields) > 3 else "",
                "notice": fields[4] if len(fields) > 4 else "",
                "createTime": float(self._safe_int(fields[5], 0) * 1000) if len(fields) > 5 else 0.0,
                "leaderId": self._safe_int(fields[6], 0) if len(fields) > 6 else 0,
                "leaderName": fields[7] if len(fields) > 7 else "",
            }
        elif action == 16:
            data = {
                "leaderName": fields[2] if len(fields) > 2 else "",
                "leaderLevel": self._safe_int(fields[3], 1) if len(fields) > 3 else 1,
                "leaderJob": self._safe_int(fields[4], 300) if len(fields) > 4 else 300,
                "leaderFace": self._safe_int(fields[5], 0) if len(fields) > 5 else 0,
                "name": fields[6] if len(fields) > 6 else "",
                "leaderId": self._safe_int(fields[7], 0) if len(fields) > 7 else 0,
                "id": self._safe_int(fields[8], 0) if len(fields) > 8 else 0,
            }
            data["data"] = dict(data)
        elif action == 17:
            data = {
                "isMoney": bool(self._safe_int(fields[2], 0)) if len(fields) > 2 else False,
                "result": bool(self._safe_int(fields[3], 0)) if len(fields) > 3 else False,
            }
        elif action == 19:
            data = {"result": bool(self._safe_int(fields[2], 0)) if len(fields) > 2 else False}
        elif action == 20:
            data = {"contriValue": self._safe_int(fields[2], 0) if len(fields) > 2 else 0}
        elif action == 21 and len(fields) >= 5:
            # Action 21 is overloaded: client requests check a family name,
            # while server pushes this object to render a player's emblem.
            data = {
                "charId": self._safe_int(fields[2], 0),
                "flagStyle": self._safe_int(fields[3], 0),
                "banghuiName": fields[4],
            }
        elif action == 23:
            data = []
            for row in ([] if len(fields) < 3 or fields[2] == "-" else fields[2].split("@")):
                values = row.split("&")
                values.extend(["0"] * (3 - len(values)))
                data.append(
                    {
                        "itemId": self._safe_int(values[0], 0),
                        "count": self._safe_int(values[1], 0),
                        "price": self._safe_int(values[2], 0),
                    }
                )
        else:
            return False
        self.send_original_packet(
            ServerOpcode.BANGHUI,
            struct.pack("<H", action & 0xFFFF) + build_original_object_buffer(data),
        )
        return True

    def _send_original_pet_attack_text(self, fields: list[str]) -> bool:
        if len(fields) < 17:
            return False
        players = [] if fields[14] == "-" else fields[14].split("@")
        mobs = [] if fields[15] == "-" else fields[15].split("@")
        body = bytearray(
            struct.pack(
                "<id4i3B4i",
                self._safe_int(fields[1], 0),
                float(fields[2]),
                *(self._safe_int(value, 0) for value in fields[3:7]),
                *(self._safe_int(value, 0) & 0xFF for value in fields[7:10]),
                *(self._safe_int(value, 0) for value in fields[10:14]),
            )
        )
        body.extend(struct.pack("<i", len(players)))
        for value in players:
            body.extend(struct.pack("<i", self._safe_int(value, 0)))
        body.extend(struct.pack("<i", len(mobs)))
        for value in mobs:
            body.extend(struct.pack("<i", self._safe_int(value, 0)))
        tag: Any = None
        if fields[16] not in {"", "-", "0", "null"}:
            try:
                tag = json.loads(fields[16])
            except (ValueError, json.JSONDecodeError):
                tag = fields[16]
        body.extend(build_original_object_buffer(tag))
        self.send_original_packet(ServerOpcode.PET_ATTACK, bytes(body))
        return True

    def _send_original_player_attack_text(self, fields: list[str]) -> bool:
        """Encode relayed PlayerAttackInfo so native peers see every player skill."""
        if len(fields) < 17:
            return False
        players = () if fields[13] == "-" else fields[13].split("@")
        monsters = () if fields[14] == "-" else fields[14].split("@")
        tag_text = ":".join(fields[17:]) if len(fields) > 17 else "null"
        tag: Any = None
        if tag_text not in {"", "-", "0", "null"}:
            try:
                tag = json.loads(tag_text)
            except (ValueError, json.JSONDecodeError):
                tag = None
        self.send_original_packet(
            ServerOpcode.PLAYER_ATTACK,
            self._player_attack_packet_body(
                character_id=self._safe_int(fields[1], 0),
                attack=self._safe_int(fields[2], 0),
                defence=self._safe_int(fields[3], 0),
                critical=self._safe_int(fields[4], 0),
                evasion=self._safe_int(fields[5], 0),
                stance=self._safe_int(fields[6], 0),
                direction=self._safe_int(fields[7], 0),
                # Nya's captured PLAYER_ATTACK requests and broadcasts always
                # carry zero here.  Do not let one client's local playback
                # value alter another player's attack animation speed.
                speed=0,
                skill_id=self._safe_int(fields[9], 0),
                skill_level=max(1, self._safe_int(fields[10], 1)),
                x=self._safe_int(fields[11], 0),
                y=self._safe_int(fields[12], 0),
                players=(self._safe_int(value, 0) for value in players),
                monsters=(self._safe_int(value, 0) for value in monsters),
                tag=tag,
            ),
        )
        return True

    def _send_original_ninja_3v3_text(self, fields: list[str]) -> bool:
        """Encode the Nya 2343 responses with the native little-endian contract."""
        if len(fields) < 2:
            return False
        action = self._safe_int(fields[1], -1)
        body = bytearray(struct.pack("<B", action & 0xFF))

        def ints(start: int, count: int) -> list[int]:
            return [self._safe_int(value, 0) for value in fields[start : start + count]]

        def member_payload(row: list[str]) -> bytes:
            row = row + ["0"] * max(0, 10 - len(row))
            return b"".join(
                (
                    struct.pack("<ii", self._safe_int(row[0], 0), self._safe_int(row[1], 0)),
                    self._original_utf(row[2]),
                    struct.pack(
                        "<ii",
                        self._safe_int(row[3], 0),
                        self._safe_int(row[4], 0),
                    ),
                    self._original_utf(row[5]),
                    struct.pack(
                        "<iiBB",
                        self._safe_int(row[6], 0),
                        self._safe_int(row[7], 0),
                        self._safe_int(row[8], 0) & 0xFF,
                        self._safe_int(row[9], 0) & 0xFF,
                    ),
                )
            )

        if action == 0 and len(fields) >= 40:
            body.extend(struct.pack("<BBii", *ints(2, 4)))
            for index in (6, 7, 8, 9, 10):
                body.extend(self._original_utf(fields[index]))
            body.extend(struct.pack("<Bi", self._safe_int(fields[11], 0) & 0xFF, self._safe_int(fields[12], 0)))
            body.extend(self._original_utf(fields[13]))
            body.extend(struct.pack("<iBiBii", self._safe_int(fields[14], 0), self._safe_int(fields[15], 0) & 0xFF, self._safe_int(fields[16], 0), self._safe_int(fields[17], 0) & 0xFF, self._safe_int(fields[18], 0), self._safe_int(fields[19], 0)))
            body.extend(struct.pack("<8i", *ints(20, 8)))
            body.extend(struct.pack("<i", self._safe_int(fields[28], 0)))
            body.extend(self._original_utf(fields[29]))
            body.extend(struct.pack("<i", self._safe_int(fields[30], 0)))
            member_rows = [] if fields[32] in {"", "-"} else [row.split("&") for row in fields[32].split("@")]
            body.extend(struct.pack("<i", len(member_rows)))
            for row in member_rows:
                body.extend(member_payload(row))
            other_rows = [] if fields[34] in {"", "-"} else [row.split("&") for row in fields[34].split("@")]
            body.extend(struct.pack("<i", len(other_rows)))
            for row in other_rows:
                row = row + ["0"] * max(0, 9 - len(row))
                body.extend(struct.pack("<i", self._safe_int(row[0], 0)))
                body.extend(self._original_utf(row[1]))
                body.extend(struct.pack("<ii", self._safe_int(row[2], 0), self._safe_int(row[3], 0)))
                body.extend(self._original_utf(row[4]))
                body.extend(struct.pack("<ii", self._safe_int(row[5], 0), self._safe_int(row[6], 0)))
                body.extend(self._original_utf(row[7]))
                body.extend(struct.pack("<B", self._safe_int(row[8], 0) & 0xFF))
            reward_count = self._safe_int(fields[35], 0)
            body.extend(struct.pack("<i", max(0, reward_count)))
            reward_offset = 36
            for index in range(max(0, reward_count)):
                row = fields[reward_offset + index].split("&")
                row = row + ["0"] * max(0, 9 - len(row))
                body.extend(struct.pack("<i", self._safe_int(row[0], 0)))
                body.extend(self._original_utf(row[1]))
                body.extend(self._original_utf(row[2]))
                body.extend(struct.pack("<6i", *[self._safe_int(value, 0) for value in row[3:9]]))
            team_size_index = reward_offset + reward_count
            body.extend(struct.pack("<i", self._safe_int(fields[team_size_index], 3)))
            claim_count_index = team_size_index + 1
            claim_count = self._safe_int(fields[claim_count_index], 0) if len(fields) > claim_count_index else 0
            body.extend(struct.pack("<i", max(0, claim_count)))
            for index in range(max(0, claim_count)):
                row = fields[claim_count_index + 1 + index].split("&")
                row = row + ["0", "1"]
                body.extend(struct.pack("<3i", *[self._safe_int(value, 0) for value in row[:3]]))
            trailer_index = claim_count_index + 1 + claim_count
            body.extend(self._original_utf(fields[trailer_index] if len(fields) > trailer_index else "未配置"))
            body.extend(struct.pack("<B", self._safe_int(fields[trailer_index + 1], 0) & 0xFF if len(fields) > trailer_index + 1 else 0))
        elif action == 1 and len(fields) >= 4:
            body.extend(struct.pack("<ii", self._safe_int(fields[2], 0), self._safe_int(fields[3], 0)))
            body.extend(self._original_utf(fields[4] if len(fields) > 4 else ""))
        elif action == 2 and len(fields) >= 4:
            body.extend(struct.pack("<ii", self._safe_int(fields[2], 0), self._safe_int(fields[3], 0)))
        elif action == 3 and len(fields) >= 3:
            body.extend(struct.pack("<i", self._safe_int(fields[2], 0)))
        elif action in {4, 5}:
            # Battle packets are emitted by the legacy combat loop only after
            # both parties are accepted; preserve the exact client decoder
            # shape for the new panel as well.
            start = 2
            if action == 4:
                if len(fields) < 8:
                    return False
                body.extend(struct.pack("<5i", *ints(start, 5)))
                row_start = 7
            else:
                if len(fields) < 7:
                    return False
                body.extend(struct.pack("<3i", *ints(start, 3)))
                row_start = 5
            rows = [] if fields[row_start] in {"", "-"} else [row.split("&") for row in fields[row_start].split("@")]
            body.extend(struct.pack("<i", len(rows)))
            for row in rows:
                row = row + ["0"] * max(0, 6 - len(row))
                body.extend(struct.pack("<i", self._safe_int(row[0], 0)))
                body.extend(self._original_utf(row[1]))
                body.extend(struct.pack("<4i", *[self._safe_int(value, 0) for value in row[2:6]]))
            body.extend(self._original_utf(fields[row_start + 1] if len(fields) > row_start + 1 else "战队一"))
            body.extend(self._original_utf(fields[row_start + 2] if len(fields) > row_start + 2 else "战队二"))
        elif action == 10 and len(fields) >= 3:
            body.extend(struct.pack("<i", self._safe_int(fields[2], 0)))
            rows = [] if len(fields) < 4 or fields[3] in {"", "-"} else [row.split("&") for row in fields[3].split("@")]
            for row in rows:
                row = row + ["0"] * max(0, 10 - len(row))
                body.extend(struct.pack("<ii", self._safe_int(row[0], 0), self._safe_int(row[1], 0)))
                body.extend(self._original_utf(row[2]))
                body.extend(struct.pack("<ii", self._safe_int(row[3], 0), self._safe_int(row[4], 0)))
                body.extend(self._original_utf(row[5]))
                body.extend(struct.pack("<B i B B", self._safe_int(row[6], 0) & 0xFF, self._safe_int(row[7], 0), self._safe_int(row[8], 0) & 0xFF, self._safe_int(row[9], 0) & 0xFF))
        elif action == 11 and len(fields) >= 7:
            body.extend(struct.pack("<i", self._safe_int(fields[2], 0)))
            body.extend(self._original_utf(fields[3]))
            body.extend(struct.pack("<i", self._safe_int(fields[4], 0)))
            body.extend(self._original_utf(fields[5]))
            body.extend(struct.pack("<i", self._safe_int(fields[6], 30)))
        elif action == 12 and len(fields) >= 6:
            body.extend(struct.pack("<i", self._safe_int(fields[2], 0)))
            body.extend(self._original_utf(fields[3]))
            body.extend(struct.pack("<i", self._safe_int(fields[4], 0)))
            rows = [] if fields[5] in {"", "-"} else [row.split("&") for row in fields[5].split("@")]
            body.extend(struct.pack("<i", len(rows)))
            for row in rows:
                body.extend(member_payload(row))
        elif action == 14 and len(fields) >= 4:
            body.extend(struct.pack("<iB", self._safe_int(fields[2], 0), self._safe_int(fields[3], 0) & 0xFF))
        elif action == 15:
            body.extend(self._original_utf(fields[2] if len(fields) > 2 else "常驻赛季"))
            body.extend(self._original_utf(fields[3] if len(fields) > 3 else "刚刚"))
            body.extend(struct.pack("<4i", 0, 0, 0, 0))
            body.extend(struct.pack("<i", 0))
        elif action == 16:
            body.extend(struct.pack("<Bi", 0, 0))
            body.extend(self._original_utf("常驻赛季"))
            body.extend(self._original_utf("未配置"))
            body.extend(struct.pack("<3iBiBBi", 3, 0, 0, 0, 0, 0, 0, 0))
            body.extend(self._original_utf(""))
            body.extend(struct.pack("<2i", 0, 0))
        else:
            return False
        self.send_original_packet(ServerOpcode.NINJA_3V3_ACTION, bytes(body))
        return True

    def _send_original_text(self, payload: str) -> bool:
        """Serialize the first shared gameplay responses for the desktop client."""
        fields = payload.split(":")
        if not fields:
            return False
        opcode = self._safe_int(fields[0], -1)
        if (
            opcode == op(ServerOpcode.PLAYER_ATTACK)
            and self._send_original_player_attack_text(fields)
        ):
            return True
        if opcode == op(ServerOpcode.BANGHUI) and self._send_original_banghui_text(fields):
            return True
        if opcode == op(ServerOpcode.NINJA_3V3_ACTION) and self._send_original_ninja_3v3_text(fields):
            return True
        if self._send_original_core_text(opcode, fields):
            return True
        if opcode == op(ServerOpcode.TUTOR) and self._send_original_tutor_text(fields):
            return True
        if opcode == op(ServerOpcode.PK_ACTION) and self._send_original_pk_text(fields):
            return True
        if opcode == op(ServerOpcode.COPY_ACTION) and self._send_original_copy_text(fields):
            return True
        if opcode == op(ServerOpcode.BANGHUI_BOSS) and self._send_original_banghui_boss_text(fields):
            return True
        if opcode == op(ServerOpcode.PET_ATTACK) and self._send_original_pet_attack_text(fields):
            return True
        if opcode == op(ServerOpcode.CASH_MONEY) and len(fields) >= 2:
            self.send_original_packet(
                ServerOpcode.CASH_MONEY,
                struct.pack("<i", self._safe_int(fields[1], 0)),
            )
            return True
        if opcode in {
            op(ServerOpcode.CASH_CATEGORY),
            op(ServerOpcode.CASH_SEARCH),
        } and len(fields) >= 3:
            total = self._safe_int(fields[1], 0)
            good_count = self._safe_int(fields[2], 0)
            rows = fields[3].split("@") if len(fields) > 3 and fields[3] != "-" else []
            rows = rows[:good_count]
            body = bytearray(struct.pack("<ii", total, len(rows)))
            for row in rows:
                body.extend(self._original_cash_item_payload(row.split("&")))
            self.send_original_packet(opcode, bytes(body))
            return True
        if opcode == op(ServerOpcode.CASH_ITEM_INFO) and len(fields) >= 17:
            self.send_original_packet(
                ServerOpcode.CASH_ITEM_INFO,
                self._original_cash_item_payload(fields[1:17]),
            )
            return True
        if opcode in {
            op(ServerOpcode.CASH_CATEGORY_CAPACITY),
            op(ServerOpcode.CASH_STORAGE_CAPACITY),
        } and len(fields) >= 2:
            self.send_original_packet(
                opcode,
                struct.pack("<i", self._safe_int(fields[1], 0)),
            )
            return True
        if opcode == op(ServerOpcode.GIFT_INFO) and len(fields) >= 2:
            info_type = self._safe_int(fields[1], 0)
            body = bytearray(struct.pack("<B", info_type & 0xFF))
            if info_type == 1:
                values = [self._safe_int(value, 0) for value in fields[2:5]]
                values.extend([0] * (3 - len(values)))
                body.extend(struct.pack("<iii", *values[:3]))
            elif info_type == 2:
                count = self._safe_int(fields[2], 0) if len(fields) > 2 else 0
                body.extend(struct.pack("<B", count & 0xFF))
                raw_pairs = fields[3].split("@") if len(fields) > 3 else []
                for raw_pair in raw_pairs[:count]:
                    pair = raw_pair.split("&")
                    pair.extend(["0", "0"])
                    body.extend(
                        struct.pack(
                            "<BB",
                            self._safe_int(pair[0], 0) & 0xFF,
                            self._safe_int(pair[1], 0) & 0xFF,
                        )
                    )
                days = 0
                if count == 0 and len(fields) > 3:
                    days = self._safe_int(fields[3].split("&")[-1], 0)
                elif len(fields) > 4:
                    days = self._safe_int(fields[4], 0)
                body.extend(struct.pack("<B", days & 0xFF))
            elif info_type == 3:
                body.extend(struct.pack("<h", self._safe_int(fields[2], 0) if len(fields) > 2 else 0))
            elif info_type == 4:
                values = [self._safe_int(value, 0) for value in fields[2:5]]
                values.extend([0] * (3 - len(values)))
                body.extend(struct.pack("<iii", *values[:3]))
                body.extend(struct.pack("<B", 1 if len(fields) > 5 and fields[5].lower() in {"1", "true"} else 0))
            elif info_type == 5:
                body.extend(
                    struct.pack(
                        "<ii",
                        self._safe_int(fields[2], 0) if len(fields) > 2 else 0,
                        self._safe_int(fields[3], 0) if len(fields) > 3 else 0,
                    )
                )
            elif info_type == 6:
                raw_value: Any = {}
                if len(fields) > 2 and fields[2] not in {"", "-"}:
                    try:
                        raw_value = json.loads(fields[2])
                    except (TypeError, ValueError, json.JSONDecodeError):
                        raw_value = {}
                body.extend(build_original_object_buffer(raw_value))
            elif info_type == 62:
                body.extend(struct.pack("<i", self._safe_int(fields[2], 0) if len(fields) > 2 else 0))
            self.send_original_packet(ServerOpcode.GIFT_INFO, bytes(body))
            return True
        if opcode == op(ServerOpcode.PAI_HANG) and len(fields) >= 2:
            action = self._safe_int(fields[1], 0)
            if action == 0 and len(fields) >= 5:
                titles = fields[4].split("@") if fields[4] != "-" else []
                body = bytearray(
                    struct.pack(
                        "<Bii",
                        action,
                        self._safe_int(fields[2], 0),
                        len(titles),
                    )
                )
                for title in titles:
                    body.extend(struct.pack("<i", self._safe_int(title, 0)))
                self.send_original_packet(ServerOpcode.PAI_HANG, bytes(body))
                return True
            if action == 1 and len(fields) >= 6:
                rows = fields[5].split("@") if fields[5] != "-" else []
                body = bytearray(
                    struct.pack(
                        "<BiBi",
                        action & 0xFF,
                        self._safe_int(fields[2], 0),
                        1 if fields[3].lower() in {"1", "true"} else 0,
                        self._safe_int(fields[4], 0),
                    )
                )
                body.extend(struct.pack("<i", len(rows)))
                for row in rows:
                    body.extend(self._original_paihang_payload(row))
                self.send_original_packet(ServerOpcode.PAI_HANG, bytes(body))
                return True
            if action == 2 and len(fields) >= 5:
                rows = fields[4].split("@") if fields[4] != "-" else []
                body = bytearray(
                    struct.pack(
                        "<Biii",
                        action & 0xFF,
                        self._safe_int(fields[2], 0),
                        self._safe_int(fields[3], 0),
                        len(rows),
                    )
                )
                for row in rows:
                    body.extend(self._original_paihang_payload(row))
                self.send_original_packet(ServerOpcode.PAI_HANG, bytes(body))
                return True
        if opcode == op(ServerOpcode.PVE_ACTION) and len(fields) >= 2:
            action = self._safe_int(fields[1], -1)
            body = bytearray(struct.pack("<B", action & 0xFF))
            if action == 0:
                body.extend(
                    struct.pack(
                        "<id",
                        self._safe_int(fields[2], 0) if len(fields) > 2 else 0,
                        float(self._safe_int(fields[3], 0)) if len(fields) > 3 else 0.0,
                    )
                )
            elif action == 1:
                rows = fields[2].split("@") if len(fields) > 2 and fields[2] != "-" else []
                body.extend(struct.pack("<i", len(rows)))
                for row in rows:
                    body.extend(self._original_paihang_payload(row))
            elif action == 2:
                rows = fields[2].split("@") if len(fields) > 2 and fields[2] != "-" else []
                body.extend(struct.pack("<i", len(rows)))
                for row in rows:
                    values = row.split("&")
                    values.extend(["0", "1"])
                    body.extend(
                        struct.pack(
                            "<iB",
                            self._safe_int(values[0], 0),
                            1 if self._safe_int(values[1], 1) == 0 else 0,
                        )
                    )
            else:
                return False
            self.send_original_packet(ServerOpcode.PVE_ACTION, bytes(body))
            return True
        if opcode == op(ServerOpcode.MAP_FLAG_ACTION) and len(fields) >= 2:
            action = self._safe_int(fields[1], -1)
            body = bytearray(struct.pack("<B", action & 0xFF))
            if action == 0:
                rows = fields[2].split("@") if len(fields) > 2 and fields[2] != "-" else []
                body.extend(struct.pack("<i", len(rows)))
                for row in rows:
                    body.extend(self._original_map_flag_payload(row))
            elif action == 1 and len(fields) >= 4:
                body.extend(struct.pack("<i", self._safe_int(fields[2], 0)))
                body.extend(self._original_map_flag_payload(fields[3]))
            else:
                return False
            self.send_original_packet(ServerOpcode.MAP_FLAG_ACTION, bytes(body))
            return True
        if opcode == op(ServerOpcode.OPEN_NPC_SHOP) and len(fields) >= 3:
            raw_tabs = fields[2].split("@") if fields[2] else []
            tabs: list[tuple[str, list[list[str]]]] = []
            for raw_tab in raw_tabs:
                tab_name, separator, raw_items = raw_tab.partition("&")
                if not separator:
                    continue
                items = [raw_item.split("#") for raw_item in raw_items.split("!") if raw_item]
                tabs.append((tab_name, items))
            body = bytearray(
                struct.pack(
                    "<IH",
                    self._safe_int(fields[1], 0) & 0xFFFFFFFF,
                    len(tabs),
                )
            )
            for tab_name, items in tabs:
                body.extend(self._original_utf(tab_name))
                body.extend(struct.pack("<H", len(items)))
                for values in items:
                    values.extend(["0"] * (7 - len(values)))
                    body.extend(
                        struct.pack(
                            "<IIhfHBB",
                            self._safe_int(values[0], 0) & 0xFFFFFFFF,
                            self._safe_int(values[1], 0) & 0xFFFFFFFF,
                            self._safe_int(values[2], 0),
                            float(self._safe_int(values[3], 0)),
                            self._safe_int(values[4], 0) & 0xFFFF,
                            self._safe_int(values[5], 0) & 0xFF,
                            1 if values[6].lower() in {"1", "true"} else 0,
                        )
                    )
            self.send_original_packet(ServerOpcode.OPEN_NPC_SHOP, bytes(body))
            return True
        if opcode == op(ServerOpcode.OPEN_STORAGE) and len(fields) >= 2:
            action = self._safe_int(fields[1], -1)
            body = bytearray(struct.pack("<B", action & 0xFF))
            if action == 1 and len(fields) >= 6:
                body.extend(
                    struct.pack(
                        "<iid",
                        self._safe_int(fields[2], 0),
                        self._safe_int(fields[3], self.store.state.storage_capacity),
                        float(self._safe_int(fields[4], 0)),
                    )
                )
                for item in sorted(self.store.state.storage.values(), key=lambda value: value.slot):
                    body.extend(self._original_item_payload(item))
                body.extend(b"\x00")
            elif action == 3 and len(fields) >= 4:
                body.extend(
                    struct.pack(
                        "<id",
                        self._safe_int(fields[2], self.store.state.storage_capacity),
                        float(self._safe_int(fields[3], 0)),
                    )
                )
            elif action == 4 and len(fields) >= 3:
                raw_item = fields[2].split("&")
                slot = self._safe_int(raw_item[2], 0) if len(raw_item) > 2 else 0
                item = self.store.state.storage.get(slot) or self.store.state.inventory.get(slot)
                if item is None:
                    return True
                body.extend(self._original_item_payload(item))
            elif action == 5 and len(fields) >= 3:
                body.extend(struct.pack("<i", self._safe_int(fields[2], 0)))
            elif action == 6 and len(fields) >= 5:
                body.extend(
                    struct.pack(
                        "<id",
                        self._safe_int(fields[2], self.store.state.storage_capacity),
                        float(self._safe_int(fields[3], 0)),
                    )
                )
                rows = fields[4].split("@") if fields[4] != "-" else []
                for row in rows:
                    values = row.split("&")
                    values.extend(["0"] * (4 - len(values)))
                    body.extend(
                        struct.pack(
                            "<BiiHd",
                            op(ItemCodecType.ITEM),
                            self._safe_int(values[0], 0),
                            self._safe_int(values[1], 0),
                            self._safe_int(values[2], 0) & 0xFFFF,
                            float(self._safe_int(values[3], 0)),
                        )
                    )
                body.extend(b"\x00")
            else:
                return False
            self.send_original_packet(ServerOpcode.OPEN_STORAGE, bytes(body))
            return True
        if opcode == op(ServerOpcode.CHATTEXT):
            message = fields[3] if len(fields) > 3 else fields[1] if len(fields) > 1 else ""
            self.send_original_packet(
                ServerOpcode.CHATTEXT,
                self._original_utf(message) + struct.pack("<hh", 0, 0),
            )
            return True
        if opcode == op(ServerOpcode.CHAT_MESSAGE) and len(fields) >= 4:
            message_type = self._safe_int(fields[1], 1)
            positions = self._safe_int(fields[2], 0)
            message = fields[3].replace("[[CHARM~", "[[CHARM:")
            name = fields[4] if len(fields) > 4 and fields[4] else "系统"
            character_id = self._safe_int(
                fields[5] if len(fields) > 5 else self.character.character_id,
                self.character.character_id,
            )
            character_level = self._safe_int(
                fields[6] if len(fields) > 6 else self.character.level,
                self.character.level,
            )
            tag: Any = None
            if len(fields) > 7 and fields[7] not in {"", "-", "null"}:
                try:
                    tag = json.loads(fields[7])
                except (TypeError, ValueError, json.JSONDecodeError):
                    tag = None
            target_name = fields[8] if len(fields) > 8 else ""
            target_id = self._safe_int(fields[9], 0) if len(fields) > 9 else 0
            char_type = self._safe_int(fields[10], 0) if len(fields) > 10 else 0
            target_char_type = self._safe_int(fields[11], 0) if len(fields) > 11 else 0
            body = b"".join(
                (
                    struct.pack("<BI", message_type & 0xFF, positions & 0xFFFFFFFF),
                    self._original_utf(message),
                    self._original_utf(name),
                    struct.pack("<ii", character_id, character_level),
                    build_original_object_buffer(tag),
                    self._original_utf(target_name),
                    struct.pack("<iii", target_id, char_type, target_char_type),
                )
            )
            self.send_original_packet(ServerOpcode.CHAT_MESSAGE, body)
            return True
        if opcode == op(ServerOpcode.HEAL_STATE) and len(fields) >= 2:
            action = self._safe_int(fields[1], -1)
            body = bytearray(struct.pack("<B", action & 0xFF))
            if action == 1:
                body.extend(
                    struct.pack(
                        "<Bii",
                        self._safe_int(fields[2], 0) & 0xFF if len(fields) > 2 else 0,
                        self._safe_int(fields[3], 0) if len(fields) > 3 else 0,
                        self._safe_int(fields[4], 0) if len(fields) > 4 else 0,
                    )
                )
            elif action in {2, 3, 4}:
                body.extend(
                    struct.pack(
                        "<i",
                        self._safe_int(fields[2], 0) if len(fields) > 2 else 0,
                    )
                )
            else:
                return False
            self.send_original_packet(ServerOpcode.HEAL_STATE, bytes(body))
            return True
        if opcode == op(ServerOpcode.CHAR_INFO) and len(fields) >= 3:
            action = self._safe_int(fields[1], -1)
            target_id = self._safe_int(fields[2], -1)
            body = bytearray(struct.pack("<B", action & 0xFF))
            target = self._character_info_session(target_id) if target_id >= 0 else None
            if target is None:
                body.extend(struct.pack("<i", -1))
            elif action == 0:
                body.extend(target._original_character_full_info_payload())
            elif action == 1:
                body.extend(target._original_character_simple_info_payload())
            elif action == 2:
                body.extend(
                    target._original_flower_character_info_payload(
                        self.account_id,
                        reward_level=self.character.level,
                    )
                )
            else:
                return False
            self.send_original_packet(ServerOpcode.CHAR_INFO, bytes(body))
            return True
        if opcode == op(ServerOpcode.CHAR_SEARCH) and len(fields) >= 2:
            search_id = self._safe_int(fields[1], 0)
            rows = [
                row
                for row in (fields[2].split("@") if len(fields) > 2 else [])
                if row and row != "-"
            ]
            body = bytearray(struct.pack("<iH", search_id, len(rows)))
            for raw_row in rows:
                values = raw_row.split("&")
                values.extend(["-"] * (8 - len(values)))
                body.extend(
                    struct.pack(
                        "<4i",
                        self._safe_int(values[0], -1),
                        self._safe_int(values[1], 0),
                        self._safe_int(values[2], 1),
                        self._safe_int(values[3], 0),
                    )
                )
                body.extend(self._original_utf(values[4]))
                body.extend(struct.pack("<i", self._safe_int(values[5], 0)))
                body.extend(self._original_utf(values[6]))
                body.extend(self._original_utf(values[7]))
                body.extend(build_original_object_buffer(None))
            self.send_original_packet(ServerOpcode.CHAR_SEARCH, bytes(body))
            return True
        if opcode == op(ServerOpcode.TARGET_INFO) and len(fields) >= 8:
            self.send_original_packet(
                ServerOpcode.TARGET_INFO,
                struct.pack(
                    "<B6i",
                    self._safe_int(fields[2], 0) & 0xFF,
                    self._safe_int(fields[1], 0),
                    self._safe_int(fields[3], 0),
                    self._safe_int(fields[4], 0),
                    self._safe_int(fields[5], 0),
                    self._safe_int(fields[6], 0),
                    self._safe_int(fields[7], 0),
                ),
            )
            return True
        if opcode == op(ServerOpcode.FRIENDLIST) and len(fields) >= 2:
            action = self._safe_int(fields[1], -1)
            if action == 16:
                target_id = self._safe_int(fields[2], -1) if len(fields) > 2 else -1
                target = self._character_info_session(target_id)
                body = bytearray(struct.pack("<B", action))
                if target is None:
                    body.extend(struct.pack("<i", -1))
                else:
                    body.extend(target._original_character_full_info_payload())
                    body.extend(
                        struct.pack(
                            "<5i",
                            target.character.ap_atk,
                            target.character.ap_def,
                            target.character.ap_dex,
                            target.character.ap_phy,
                            target.character.remaining_ap,
                        )
                    )
                self.send_original_packet(ServerOpcode.FRIENDLIST, bytes(body))
                return True
            if action == 36:
                valid = self._safe_int(fields[9], 0) != 0 if len(fields) > 9 else False
                body = bytearray(struct.pack("<BB", action, int(valid)))
                if valid:
                    list_id = self._safe_int(fields[2], 0)
                    exploded_rows = [
                        row.split("&", 1)
                        for row in (fields[3].split("@") if len(fields) > 3 else [])
                        if row and row != "-" and "&" in row
                    ]
                    body.extend(
                        struct.pack(
                            "<3hd",
                            list_id,
                            self._safe_int(fields[6], 0),
                            self._safe_int(fields[5], 0),
                            float(self._safe_int(fields[7], 0)),
                        )
                    )
                    body.extend(struct.pack("<H", 0))  # empty SubAttribute
                    body.extend(struct.pack("<H", len(exploded_rows)))
                    for mai_id, opened in exploded_rows:
                        body.extend(
                            struct.pack(
                                "<2h",
                                self._safe_int(mai_id, 0),
                                self._safe_int(opened, 0),
                            )
                        )
                    body.extend(
                        struct.pack(
                            "<h",
                            self._safe_int(fields[8], 0),
                        )
                    )
                self.send_original_packet(ServerOpcode.FRIENDLIST, bytes(body))
                return True
            if action == 37:
                valid = self._safe_int(fields[2], 0) != 0 if len(fields) > 2 else False
                body = bytearray(struct.pack("<BB", action, int(valid)))
                if valid:
                    skills = [
                        row.split("&")
                        for row in (fields[4].split("@") if len(fields) > 4 else [])
                        if row and row != "-"
                    ]
                    body.extend(struct.pack("<iH", self._safe_int(fields[3], 0), len(skills)))
                    for values in skills:
                        values.extend(["0"] * (3 - len(values)))
                        body.extend(
                            struct.pack(
                                "<3i",
                                self._safe_int(values[0], 0),
                                self._safe_int(values[1], 0),
                                self._safe_int(values[2], 0),
                            )
                        )
                self.send_original_packet(ServerOpcode.FRIENDLIST, bytes(body))
                return True
            data: dict[str, Any]
            if action == 2:
                entrylist: dict[str, list[dict[str, Any]]] = {
                    "FRIEND": [],
                    "RECENT": [],
                    "ENEMY": [],
                    "BANNED": [],
                }
                infolist: dict[str, dict[str, Any]] = {}
                groups = {
                    "FRIEND": fields[2] if len(fields) > 2 else "-",
                    "BANNED": fields[5] if len(fields) > 5 else "-",
                }
                for friend_type, raw_group in groups.items():
                    for raw_row in raw_group.split("@") if raw_group != "-" else ():
                        entry, info = self._original_friend_row_objects(
                            raw_row,
                            friend_type,
                        )
                        entrylist[friend_type].append(entry)
                        infolist[str(info["charId"])] = info
                data = {"entrylist": entrylist, "infolist": infolist}
            elif action == 3 and len(fields) >= 13:
                raw_row = "&".join(
                    (
                        fields[3], fields[2], fields[4], fields[5], fields[6],
                        fields[7], fields[8], fields[9], fields[10],
                        fields[13] if len(fields) > 13 else "0", fields[11],
                    )
                )
                friend_type = fields[12] or "FRIEND"
                data, info = self._original_friend_row_objects(raw_row, friend_type)
                self.send_original_packet(
                    ServerOpcode.FRIENDLIST,
                    struct.pack("<B", 1) + build_original_object_buffer(info),
                )
            elif action == 4:
                data = {
                    "charId": self._safe_int(fields[2], 0) if len(fields) > 2 else 0,
                    "friendType": fields[3] if len(fields) > 3 else "FRIEND",
                }
            elif action == 5:
                data = {
                    "charId": self._safe_int(fields[2], 0) if len(fields) > 2 else 0,
                    "name": fields[3] if len(fields) > 3 else "-",
                }
            elif action == 7:
                friend_id = self._safe_int(fields[2], 0) if len(fields) > 2 else 0
                friend_name = fields[4] if len(fields) > 4 else "-"
