                    self._safe_int(fields[5], 0),
                    self._safe_int(fields[6], 0),
                    self._safe_int(fields[7], 0) if len(fields) > 7 else 0,
                    self._safe_int(fields[8], 0) if len(fields) > 8 else 0,
                    self._safe_int(fields[9], 0) & 0xFFFF if len(fields) > 9 else 0,
                    movement_status & 0xFF,
